// The Land Before Stone: Meghavan, the Rain Country — what its people say, what its things are, its signs, quests and updates. One row per English text, its translations in TABLE_LANGUAGES' order (see table.ts).
import type { Row } from "./table.ts";

export const MEGHAVAN_TALK: Readonly<Record<string, Row>> = {
  "THE GATE OF RAINS. Here begins Meghavan. Ilavarta keeps the road to Tirthali; the League keeps its own roads, and says so; Shailagarh keeps the passes. Travellers are asked to carry water in the dry months and a cloak in the wet.": ["雨の門。ここよりメガヴァン。ティルタリへの道はイラヴァルタが守る。同盟は自らの道を守り、そう公言している。峠はシャイラガルが守る。旅人は乾季には水を、雨季には外套を携えられたし。", "비의 문. 여기서부터 메가반. 티르탈리로 가는 길은 일라바르타가 지킨다. 동맹은 자기 길을 지키며, 그렇다고 분명히 말한다. 고개는 샤일라가르가 지킨다. 여행자는 건기에는 물을, 우기에는 외투를 지니기 바란다.", "雨之门。梅加万由此开始。伊拉瓦塔掌管通往提尔塔利的道路;同盟掌管自己的道路,并且明说如此;沙伊拉加尔掌管山口。敬请旅人旱季带水,雨季带斗篷。", "雨之門。梅加萬由此開始。伊拉瓦塔掌管通往提爾塔利的道路;同盟掌管自己的道路,並且明說如此;沙伊拉加爾掌管山口。敬請旅人旱季帶水,雨季帶斗篷。", "CỔNG MƯA. Meghavan bắt đầu từ đây. Ilavarta giữ con đường đến Tirthali; Liên minh giữ những con đường của riêng mình, và nói rõ như vậy; Shailagarh giữ các đèo. Lữ khách được yêu cầu mang theo nước vào những tháng khô và áo choàng vào những tháng mưa.", "GERBANG HUJAN. Di sinilah Meghavan bermula. Ilavarta menjaga jalan ke Tirthali; Liga menjaga jalannya sendiri, dan menegaskannya; Shailagarh menjaga celah-celah gunung. Para pelancong diminta membawa air di bulan-bulan kering dan jubah di bulan-bulan basah.", "ประตูแห่งสายฝน เมฆาวันเริ่มต้นที่นี่ อิลาวรรตะดูแลถนนสู่ตีรถลี สันนิบาตดูแลถนนของตนเอง และประกาศไว้ชัดเจน ไศลครห์ดูแลช่องเขา ขอให้นักเดินทางพกน้ำในเดือนแล้ง และพกเสื้อคลุมในเดือนฝน", "YAĞMUR KAPISI. Meghavan burada başlar. Tirthali yolunu Ilavarta korur; Birlik kendi yollarını korur ve bunu açıkça söyler; geçitleri Shailagarh korur. Yolculardan kurak aylarda su, yağışlı aylarda pelerin taşımaları rica olunur.", "LA PUERTA DE LAS LLUVIAS. Aquí empieza Meghavan. Ilavarta guarda el camino a Tirthali; la Liga guarda sus propios caminos, y lo deja claro; Shailagarh guarda los pasos. Se ruega a los viajeros llevar agua en los meses secos y una capa en los húmedos.", "O PORTÃO DAS CHUVAS. Aqui começa Meghavan. Ilavarta guarda a estrada para Tirthali; a Liga guarda as próprias estradas, e faz questão de dizer; Shailagarh guarda os desfiladeiros. Pede-se aos viajantes que levem água nos meses secos e uma capa nos chuvosos.", "ВРАТА ДОЖДЕЙ. Здесь начинается Мегхаван. Дорогу на Тиртхали держит Илаварта; Лига держит собственные дороги и не устаёт об этом напоминать; перевалы держит Шайлагарх. Путников просят брать с собой воду в сухие месяцы и плащ — в дождливые.", "БРАМА ДОЩІВ. Тут починається Мегхаван. Дорогу на Тіртхалі тримає Ілаварта; Ліга тримає власні дороги й не забуває про це нагадувати; перевали тримає Шайлагарх. Подорожніх просять брати воду в сухі місяці й плащ — у дощові."],
  "A boulder with green on its north side: the rain reaches this far": ["北側が緑に覆われた大岩。雨はここまで届く", "북쪽 면이 초록빛인 바위. 비가 여기까지 닿는다", "一块北面泛绿的巨石:雨水最远到此", "一塊北面泛綠的巨石:雨水最遠到此", "Một tảng đá lớn xanh rêu ở mặt bắc: mưa đến được tận đây", "Batu besar yang hijau di sisi utaranya: hujan sampai sejauh ini", "ก้อนหินใหญ่ที่ด้านเหนือเขียวครึ้ม ฝนมาถึงแค่ตรงนี้", "Kuzey yüzü yeşillenmiş bir kaya: yağmur buraya kadar ulaşıyor", "Una roca con verde en su cara norte: la lluvia llega hasta aquí", "Uma rocha com verde no lado norte: a chuva chega até aqui", "Валун, позеленевший с северной стороны: дождь доходит досюда", "Валун, що позеленів з північного боку: дощ сягає аж сюди"],
  "Rope, lamp oil, salt from the Ouresh and pepper from the Golden Shore, priced in two currencies": ["縄、灯油、ウレシュの塩、黄金の浜の胡椒。値札は二つの通貨で書かれている", "밧줄, 등잔 기름, 우레시의 소금과 황금 해안의 후추. 가격은 두 가지 화폐로 매겨져 있다", "绳子、灯油、乌雷什人的盐和黄金海岸的胡椒,用两种货币标价", "繩子、燈油、烏雷什人的鹽和黃金海岸的胡椒,用兩種貨幣標價", "Dây thừng, dầu đèn, muối của người Ouresh và tiêu từ Bờ Vàng, niêm yết giá bằng hai loại tiền", "Tali, minyak lampu, garam dari orang Ouresh dan lada dari Pantai Emas, dihargai dalam dua mata uang", "เชือก น้ำมันตะเกียง เกลือจากชาวอูเรช และพริกไทยจากชายฝั่งทองคำ ติดราคาไว้สองสกุลเงิน", "İp, kandil yağı, Ouresh'lerden tuz ve Altın Kıyı'dan karabiber; fiyatlar iki para biriminde", "Cuerda, aceite de lámpara, sal de los ouresh y pimienta de la Costa Dorada, con precios en dos monedas", "Corda, óleo de lamparina, sal dos ouresh e pimenta da Costa Dourada, com preços em duas moedas", "Верёвка, масло для ламп, соль от уреш и перец с Золотого берега, цены в двух валютах", "Мотузка, олія для ламп, сіль від уреш і перець із Золотого берега, ціни у двох валютах"],
  "Cloth dyed with madder, indigo and turmeric, hung to dry in all three colours": ["茜、藍、ウコンで染めた布が、三色そろって干してある", "꼭두서니, 쪽, 강황으로 물들인 천이 세 가지 색 모두 널려 말라 가고 있다", "用茜草、靛蓝和姜黄染的布,三种颜色全都挂着晾干", "用茜草、靛藍和薑黃染的布,三種顏色全都掛著晾乾", "Vải nhuộm bằng thiên thảo, chàm và nghệ, phơi khô đủ cả ba màu", "Kain yang dicelup akar mengkudu, nila, dan kunyit, dijemur dalam ketiga warnanya", "ผ้าย้อมด้วยรากมัดเดอร์ คราม และขมิ้น แขวนตากไว้ครบทั้งสามสี", "Kökboya, çivit ve zerdeçalla boyanmış kumaşlar, üç renkte de kurumaya asılmış", "Tela teñida con rubia, añil y cúrcuma, tendida a secar en los tres colores", "Pano tingido com garança, anil e cúrcuma, pendurado para secar nas três cores", "Ткань, окрашенная мареной, индиго и куркумой, сушится во всех трёх цветах", "Тканина, пофарбована мареною, індиго й куркумою, сохне в усіх трьох кольорах"],
  "A ledger of crossings: who, how many, how wet, and a column headed 'did not ask'": ["渡河の台帳。誰が、何人、どれだけ濡れたか。そして「訊かず」と見出しのついた欄", "도하 장부. 누가, 몇 명이, 얼마나 젖었는지, 그리고 '묻지 않음'이라는 제목의 칸", "渡河登记簿:谁、几人、湿到什么程度,还有一栏标着“未问”", "渡河登記簿:誰、幾人、濕到什麼程度,還有一欄標著「未問」", "Sổ ghi chép các chuyến qua sông: ai, bao nhiêu người, ướt đến đâu, và một cột đề \"không hỏi\"", "Buku catatan penyeberangan: siapa, berapa orang, seberapa basah, dan satu kolom berjudul \"tidak ditanya\"", "สมุดบันทึกการข้ามน้ำ ใคร กี่คน เปียกแค่ไหน และมีช่องหนึ่งหัวข้อว่า \"ไม่ได้ถาม\"", "Bir geçiş defteri: kim, kaç kişi, ne kadar ıslak ve \"sorulmadı\" başlıklı bir sütun", "Un registro de cruces: quién, cuántos, cuán mojados, y una columna titulada «no se preguntó»", "Um livro de travessias: quem, quantos, quão molhados, e uma coluna intitulada \"não se perguntou\"", "Книга переправ: кто, сколько, насколько промок, и графа под заголовком «не спрашивали»", "Книга переправ: хто, скільки, наскільки змок, і графа із заголовком «не питали»"],
  "TIRTHALI, the ford town. Ferrywarden Amul keeps the crossing. Caravans rest at the caravanserai. Sarovan is north-east; the ford and Mandapur are south-east; the Deepgreen and Kanthar are south. What is bought in Tirthali is the buyer's own business, says the ferrywarden; what is dug up is the Queen's, says the Queen.": ["渡しの町ティルタリ。渡し場は渡し守アムルが預かる。隊商は隊商宿で休む。サロヴァンは北東、浅瀬とマンダプルは南東、深緑の森とカンタルは南。ティルタリで買ったものは買い手の勝手、と渡し守は言う。掘り出したものは女王のもの、と女王は言う。", "나루 마을 티르탈리. 나루는 나루지기 아물이 지킨다. 대상들은 대상 숙소에서 쉰다. 사로반은 북동쪽, 여울과 만다푸르는 남동쪽, 깊은초록 숲과 칸타르는 남쪽. 티르탈리에서 산 물건은 산 사람 소관이라고 나루지기는 말한다. 파낸 물건은 여왕의 것이라고 여왕은 말한다.", "提尔塔利,渡口之镇。渡口守阿穆尔掌管渡口。商队在商队客栈歇脚。萨罗万在东北;浅滩与曼达普尔在东南;深绿林与坎塔尔在南。渡口守说,在提尔塔利买了什么是买家自己的事;女王说,挖出来的东西归女王。", "提爾塔利,渡口之鎮。渡口守阿穆爾掌管渡口。商隊在商隊客棧歇腳。薩羅萬在東北;淺灘與曼達普爾在東南;深綠林與坎塔爾在南。渡口守說,在提爾塔利買了什麼是買家自己的事;女王說,挖出來的東西歸女王。", "TIRTHALI, thị trấn bến lội. Người giữ bến Amul trông coi chỗ qua sông. Đoàn buôn nghỉ chân tại lữ quán. Sarovan ở phía đông bắc; bến lội và Mandapur ở phía đông nam; Rừng Thẳm Xanh và Kanthar ở phía nam. Mua gì ở Tirthali là việc riêng của người mua, người giữ bến nói vậy; đào được gì là của Nữ hoàng, Nữ hoàng nói vậy.", "TIRTHALI, kota penyeberangan. Penjaga Penyeberangan Amul menjaga penyeberangan. Karavan beristirahat di karavanserai. Sarovan di timur laut; tempat penyeberangan dan Mandapur di tenggara; Rimba Hijau Pekat dan Kanthar di selatan. Apa yang dibeli di Tirthali adalah urusan pembelinya sendiri, kata penjaga penyeberangan; apa yang digali adalah milik Ratu, kata Ratu.", "ตีรถลี เมืองท่าข้าม ผู้คุมท่าข้ามอมุลดูแลท่าข้าม กองคาราวานพักที่คาราวานเซราย สโรวันอยู่ทางตะวันออกเฉียงเหนือ ท่าข้ามและมัณฑปุระอยู่ทางตะวันออกเฉียงใต้ ป่าเขียวลึกและกันถาร์อยู่ทางใต้ ผู้คุมท่าข้ามว่า ของที่ซื้อในตีรถลีเป็นเรื่องของผู้ซื้อเอง ราชินีว่า ของที่ขุดขึ้นมาเป็นของราชินี", "TIRTHALI, geçit kasabası. Geçidi Geçit Bekçisi Amul tutar. Kervanlar kervansarayda dinlenir. Sarovan kuzeydoğuda; geçit ve Mandapur güneydoğuda; Derin Yeşillik ve Kanthar güneyde. Tirthali'de satın alınan şey alıcının kendi işidir, der geçit bekçisi; topraktan çıkarılan şey Kraliçe'nindir, der Kraliçe.", "TIRTHALI, el pueblo del vado. El guardavado Amul custodia el paso. Las caravanas descansan en el caravasar. Sarovan queda al noreste; el vado y Mandapur, al sureste; el Verdor Profundo y Kanthar, al sur. Lo que se compra en Tirthali es asunto del comprador, dice el guardavado; lo que se desentierra es de la Reina, dice la Reina.", "TIRTHALI, a vila do vau. O guarda do vau Amul cuida da travessia. As caravanas descansam no caravançará. Sarovan fica a nordeste; o vau e Mandapur, a sudeste; o Verde Profundo e Kanthar, ao sul. O que se compra em Tirthali é assunto do comprador, diz o guarda do vau; o que se desenterra é da Rainha, diz a Rainha.", "ТИРТХАЛИ, городок у брода. Переправу держит паромщик Амул. Караваны отдыхают в караван-сарае. Сарован к северо-востоку; брод и Мандапур к юго-востоку; Глубокая Зелень и Кантхар к югу. Что куплено в Тиртхали — дело самого покупателя, говорит паромщик; что выкопано из земли — принадлежит королеве, говорит королева.", "ТІРТХАЛІ, містечко біля броду. Переправу тримає поромник Амул. Каравани відпочивають у караван-сараї. Сарован на північний схід; брід і Мандапур на південний схід; Глибока Зелень і Кантхар на південь. Що куплено в Тіртхалі — справа самого покупця, каже поромник; що викопано із землі — належить королеві, каже королева."],
  "The Keeper's seat: a plain stone bench, a brass water-measure set in its arm": ["守り手の座。飾り気のない石の長椅子で、肘掛けに真鍮の水量計がはめ込まれている", "수호자의 자리. 수수한 돌 벤치로, 팔걸이에 놋쇠 수위계가 박혀 있다", "守护者的座位:一条朴素的石凳,扶手上嵌着一只黄铜量水器", "守護者的座位:一條樸素的石凳,扶手上嵌著一只黃銅量水器", "Ghế của Người Giữ Hồ: một băng ghế đá giản dị, tay vịn gắn một thước đo nước bằng đồng thau", "Kursi Sang Penjaga: bangku batu polos, dengan takaran air kuningan terpasang di sandaran lengannya", "ที่นั่งของผู้รักษา ม้านั่งหินเรียบๆ มีเครื่องวัดน้ำทองเหลืองฝังอยู่ที่ที่วางแขน", "Bekçi'nin makamı: sade bir taş sıra, kolçağına pirinç bir su ölçeği gömülü", "El asiento de la Guardiana: un sencillo banco de piedra, con una medida de agua de latón engastada en el brazo", "O assento da Guardiã: um banco de pedra simples, com uma medida de água de latão encravada no braço", "Место Хранительницы: простая каменная скамья, в подлокотник вделана латунная мера воды", "Місце Хранительки: проста кам'яна лава, у підлокітник вправлено латунну міру води"],
  "Ilavarta's banner: a white lotus on a blue square, a tank seen from above": ["イラヴァルタの旗。青い正方形に白い蓮。上から見た貯水池だ", "일라바르타의 깃발. 파란 사각형 위의 흰 연꽃, 위에서 내려다본 저수지다", "伊拉瓦塔的旗帜:蓝色方块上一朵白莲,正是俯瞰的水池", "伊拉瓦塔的旗幟:藍色方塊上一朵白蓮,正是俯瞰的水池", "Cờ của Ilavarta: một đóa sen trắng trên ô vuông xanh lam, một hồ chứa nhìn từ trên cao", "Panji Ilavarta: teratai putih di atas bujur sangkar biru, sebuah telaga dilihat dari atas", "ธงของอิลาวรรตะ ดอกบัวขาวบนสี่เหลี่ยมสีน้ำเงิน คือสระที่มองจากเบื้องบน", "Ilavarta'nın sancağı: mavi bir kare üstünde beyaz bir nilüfer, yukarıdan görülen bir havuz", "El estandarte de Ilavarta: un loto blanco sobre un cuadrado azul, un estanque visto desde arriba", "O estandarte de Ilavarta: um lótus branco sobre um quadrado azul, um tanque visto de cima", "Знамя Илаварты: белый лотос на синем квадрате — пруд, увиденный сверху", "Стяг Ілаварти: білий лотос на синьому квадраті — став, побачений згори"],
  "A model of the Ilavati in clay, every tank and canal on it, little flags where the silt is worst": ["粘土で作ったイラヴァティ川の模型。貯水池も水路もすべて載っていて、泥の堆積がひどい所には小旗が立っている", "점토로 만든 일라바티 강 모형. 저수지와 운하가 빠짐없이 있고, 토사가 가장 심한 곳마다 작은 깃발이 꽂혀 있다", "一座黏土做的伊拉瓦蒂河模型,每个水池和每条水渠都在上面,淤泥最严重的地方插着小旗", "一座黏土做的伊拉瓦蒂河模型,每個水池和每條水渠都在上面,淤泥最嚴重的地方插著小旗", "Một mô hình sông Ilavati bằng đất sét, đủ mọi hồ chứa và kênh đào, cắm cờ nhỏ ở những chỗ phù sa bồi nặng nhất", "Maket Ilavati dari tanah liat, lengkap dengan setiap telaga dan kanal, dengan bendera kecil di tempat endapan lumpurnya paling parah", "แบบจำลองแม่น้ำอิลาวดีปั้นจากดินเหนียว มีสระและคลองครบทุกแห่ง ปักธงเล็กๆ ตรงที่ตะกอนหนักที่สุด", "Kilden bir Ilavati maketi; her havuz ve kanal üzerinde, alüvyonun en kötü olduğu yerlerde küçük bayraklar", "Una maqueta de arcilla del Ilavati, con cada estanque y canal, y banderitas donde el limo es peor", "Uma maquete de argila do Ilavati, com cada tanque e canal, e bandeirinhas onde o lodo é pior", "Глиняная модель Илавати со всеми прудами и каналами, флажки там, где ила больше всего", "Глиняна модель Ілаваті з усіма ставами й каналами, прапорці там, де мулу найбільше"],
  "The engineers' rolls: depths, flows, and costs, in red ink, rising": ["技師たちの記録簿。水深、流量、費用。赤インクで、右肩上がり", "기술자들의 기록부. 수심, 유량, 비용이 붉은 잉크로, 계속 올라가고 있다", "工程师们的记录:水深、流量和开支,用红墨水写着,节节攀升", "工程師們的記錄:水深、流量和開支,用紅墨水寫著,節節攀升", "Sổ sách của các kỹ sư: độ sâu, lưu lượng và chi phí, bằng mực đỏ, ngày một tăng", "Catatan para insinyur: kedalaman, aliran, dan biaya, bertinta merah, terus naik", "บัญชีของพวกวิศวกร ความลึก อัตราไหล และค่าใช้จ่าย เขียนด้วยหมึกแดง และพุ่งขึ้นเรื่อยๆ", "Mühendislerin kayıtları: derinlikler, akışlar ve maliyetler; kırmızı mürekkeple ve hep artıyor", "Los registros de los ingenieros: profundidades, caudales y costes, en tinta roja, al alza", "Os registros dos engenheiros: profundidades, vazões e custos, em tinta vermelha, subindo", "Записи инженеров: глубины, расходы воды и затраты, красными чернилами, и всё растут", "Записи інженерів: глибини, витрати води й кошти, червоним чорнилом, і все зростають"],
  "The temple's offering chest, locked twice: once by the treasurers, once by the Queen": ["寺院の賽銭箱。鍵は二つ。一つは会計役たちの、一つは女王の", "사원의 헌금함. 자물쇠가 두 개다. 하나는 재무관들이, 하나는 여왕이 채웠다", "神庙的供奉箱,上了两道锁:一道是司库们的,一道是女王的", "神廟的供奉箱,上了兩道鎖:一道是司庫們的,一道是女王的", "Hòm công đức của đền, khóa hai lần: một lần bởi các thủ quỹ, một lần bởi Nữ hoàng", "Peti persembahan kuil, dikunci dua kali: sekali oleh para bendahara, sekali oleh Ratu", "หีบรับเครื่องบูชาของวิหาร ล็อกสองชั้น ชั้นหนึ่งโดยเหรัญญิก อีกชั้นโดยราชินี", "Tapınağın adak sandığı, iki kez kilitli: bir kez haznedarlarca, bir kez Kraliçe'ce", "El cofre de ofrendas del templo, cerrado dos veces: una por los tesoreros, otra por la Reina", "O cofre de oferendas do templo, trancado duas vezes: uma pelos tesoureiros, outra pela Rainha", "Ящик для подношений храма, запертый дважды: раз казначеями, раз королевой", "Скринька для пожертв храму, замкнена двічі: раз скарбниками, раз королевою"],
  "Rice in sacks, lentils in jars, lamp wicks, rope, and a basket of mangoes nobody is guarding": ["袋入りの米、壺入りのレンズ豆、灯芯、縄、そして誰も見張っていないマンゴーの籠", "자루에 든 쌀, 단지에 든 렌즈콩, 등잔 심지, 밧줄, 그리고 아무도 지키지 않는 망고 한 바구니", "成袋的米、成罐的扁豆、灯芯、绳子,还有一篮没人看管的芒果", "成袋的米、成罐的扁豆、燈芯、繩子,還有一籃沒人看管的芒果", "Gạo đóng bao, đậu lăng đựng vò, bấc đèn, dây thừng, và một giỏ xoài chẳng ai canh", "Beras dalam karung, kacang lentil dalam toples, sumbu lampu, tali, dan sekeranjang mangga yang tak dijaga siapa pun", "ข้าวสารเป็นกระสอบ ถั่วเลนทิลใส่โถ ไส้ตะเกียง เชือก และมะม่วงตะกร้าหนึ่งที่ไม่มีใครเฝ้า", "Çuval çuval pirinç, kavanoz kavanoz mercimek, kandil fitilleri, ip ve kimsenin beklemediği bir sepet mango", "Arroz en sacos, lentejas en tarros, mechas de lámpara, cuerda y un cesto de mangos que nadie vigila", "Arroz em sacos, lentilhas em potes, pavios de lamparina, corda e um cesto de mangas que ninguém vigia", "Рис в мешках, чечевица в банках, фитили для ламп, верёвка и корзина манго, которую никто не стережёт", "Рис у мішках, сочевиця в глечиках, ґноти для ламп, мотузка й кошик манго, який ніхто не стереже"],
  "A brass lamp, a water jar, a palm-leaf book of the tank songs": ["真鍮のランプ、水甕、貯水池の歌を記した貝葉の本", "놋쇠 등잔, 물항아리, 저수지 노래를 적은 패엽 책", "一盏黄铜灯、一只水罐、一本记着水池歌谣的贝叶书", "一盞黃銅燈、一只水罐、一本記著水池歌謠的貝葉書", "Một cây đèn đồng thau, một vò nước, một cuốn sách lá cọ chép những bài ca về hồ", "Lampu kuningan, tempayan air, kitab lontar berisi lagu-lagu telaga", "ตะเกียงทองเหลือง โอ่งน้ำ คัมภีร์ใบลานบันทึกเพลงแห่งสระ", "Pirinç bir kandil, bir su küpü, havuz şarkılarının yazılı olduğu palmiye yaprağından bir kitap", "Una lámpara de latón, una tinaja de agua, un libro de hojas de palma con los cantos de los estanques", "Uma lamparina de latão, um jarro de água, um livro de folhas de palmeira com as canções dos tanques", "Латунная лампа, кувшин для воды, книга на пальмовых листьях с песнями о прудах", "Латунна лампа, глек для води, книга на пальмовому листі з піснями про стави"],
  "SAROVAN, the city of the tanks. Seat of Queen Saumitra, Keeper of the Tanks, and of the kingdom of Ilavarta. The Great Tank is open to all at dawn and dusk. The Queen's bridge is south of the city: toll by the head, by the cart, by the beast.": ["貯水池の都サロヴァン。貯水池の守り手サウミトラ女王と、イラヴァルタ王国の本拠。大貯水池は夜明けと日暮れに誰にでも開かれる。女王の橋は都の南。通行料は一人ごと、荷車ごと、家畜ごと。", "저수지의 도시 사로반. 저수지의 수호자 사우미트라 여왕과 일라바르타 왕국의 자리. 대저수지는 새벽과 해 질 녘에 누구에게나 열린다. 여왕의 다리는 도시 남쪽에 있다. 통행료는 머릿수대로, 수레대로, 짐승대로.", "萨罗万,水池之城。水池守护者萨乌米特拉女王与伊拉瓦塔王国的所在。大水池在黎明与黄昏向所有人开放。女王桥在城南:按人头、按车、按牲口收过路费。", "薩羅萬,水池之城。水池守護者薩烏米特拉女王與伊拉瓦塔王國的所在。大水池在黎明與黃昏向所有人開放。女王橋在城南:按人頭、按車、按牲口收過路費。", "SAROVAN, thành phố của những hồ chứa. Nơi ngự của Nữ hoàng Saumitra, Người Giữ Hồ, và của vương quốc Ilavarta. Hồ Lớn mở cửa cho mọi người lúc bình minh và hoàng hôn. Cầu của Nữ hoàng ở phía nam thành phố: thu phí theo đầu người, theo xe, theo súc vật.", "SAROVAN, kota telaga. Kedudukan Ratu Saumitra, Penjaga Telaga, dan kerajaan Ilavarta. Telaga Agung terbuka bagi semua orang saat fajar dan senja. Jembatan Ratu ada di selatan kota: tol per kepala, per gerobak, per hewan.", "สโรวัน นครแห่งสระ ที่ประทับของราชินีเสามิตรา ผู้รักษาสระ และที่ตั้งของราชอาณาจักรอิลาวรรตะ สระใหญ่เปิดให้ทุกคนในยามรุ่งอรุณและยามสนธยา สะพานของราชินีอยู่ทางใต้ของเมือง เก็บค่าผ่านทางรายหัว รายเกวียน รายสัตว์", "SAROVAN, havuzlar şehri. Havuzların Bekçisi Kraliçe Saumitra'nın ve Ilavarta krallığının merkezi. Büyük Havuz şafakta ve alacakaranlıkta herkese açıktır. Kraliçe'nin köprüsü şehrin güneyindedir: geçiş ücreti kişi başı, araba başı, hayvan başı.", "SAROVAN, la ciudad de los estanques. Sede de la reina Saumitra, Guardiana de los Estanques, y del reino de Ilavarta. El Gran Estanque está abierto a todos al alba y al anochecer. El puente de la Reina está al sur de la ciudad: peaje por cabeza, por carro, por bestia.", "SAROVAN, a cidade dos tanques. Sede da rainha Saumitra, Guardiã dos Tanques, e do reino de Ilavarta. O Grande Tanque é aberto a todos ao amanhecer e ao entardecer. A ponte da Rainha fica ao sul da cidade: pedágio por cabeça, por carroça, por animal.", "САРОВАН, город прудов. Резиденция королевы Саумитры, Хранительницы прудов, и королевства Илаварта. Великий пруд открыт для всех на рассвете и в сумерках. Королевский мост к югу от города: пошлина с головы, с телеги, со скотины.", "САРОВАН, місто ставів. Резиденція королеви Саумітри, Хранительки ставів, і королівства Ілаварта. Великий став відкритий для всіх на світанку й у сутінках. Королівський міст на південь від міста: мито з голови, з воза, з худобини."],
  "Shailagarh's banner: a white peak on red, three stars over it for the three passes": ["シャイラガルの旗。赤地に白い峰、その上に三つの峠を表す三つの星", "샤일라가르의 깃발. 붉은 바탕에 흰 봉우리, 그 위에 세 고개를 뜻하는 별 셋", "沙伊拉加尔的旗帜:红底白峰,峰上三颗星,代表三处山口", "沙伊拉加爾的旗幟:紅底白峰,峰上三顆星,代表三處山口", "Cờ của Shailagarh: một ngọn núi trắng trên nền đỏ, phía trên là ba ngôi sao tượng trưng cho ba con đèo", "Panji Shailagarh: puncak putih di atas merah, tiga bintang di atasnya untuk tiga celah gunung", "ธงของไศลครห์ ยอดเขาสีขาวบนพื้นแดง มีดาวสามดวงอยู่เหนือยอด แทนช่องเขาทั้งสาม", "Shailagarh'ın sancağı: kırmızı üstüne beyaz bir doruk, üzerinde üç geçit için üç yıldız", "El estandarte de Shailagarh: un pico blanco sobre rojo, con tres estrellas encima por los tres pasos", "O estandarte de Shailagarh: um pico branco sobre vermelho, com três estrelas acima pelos três desfiladeiros", "Знамя Шайлагарха: белая вершина на красном, над ней три звезды — по числу перевалов", "Стяг Шайлагарха: біла вершина на червоному, над нею три зорі — за числом перевалів"],
  "A map of the passes, the mines, and the Copper Banner's companies marked in pins that cost a great deal each": ["峠と鉱山の地図。銅の旗の部隊が、一本一本がたいそう高価なピンで示されている", "고개와 광산의 지도. 구리 깃발의 부대들이 하나하나 값비싼 핀으로 표시되어 있다", "一张山口与矿山的地图,铜旗的各个连队用图钉标出,每枚图钉都价值不菲", "一張山口與礦山的地圖,銅旗的各個連隊用圖釘標出,每枚圖釘都價值不菲", "Một tấm bản đồ các con đèo, các mỏ, và các đại đội của Cờ Đồng được đánh dấu bằng những chiếc ghim chiếc nào cũng đắt đỏ", "Peta celah-celah gunung, tambang-tambang, dan kompi-kompi Panji Tembaga yang ditandai dengan jarum yang masing-masing mahal sekali", "แผนที่ช่องเขา เหมือง และกองร้อยของธงทองแดงที่ปักหมุดไว้ หมุดแต่ละอันแพงหูฉี่", "Geçitlerin ve madenlerin haritası; Bakır Sancak'ın bölükleri her biri epey pahalı iğnelerle işaretlenmiş", "Un mapa de los pasos, las minas y las compañías del Estandarte de Cobre, marcadas con alfileres que cuestan un dineral cada uno", "Um mapa dos desfiladeiros, das minas e das companhias do Estandarte de Cobre, marcadas com alfinetes que custam uma fortuna cada um", "Карта перевалов, рудников и рот Медного знамени, отмеченных булавками, каждая из которых стоит немалых денег", "Мапа перевалів, копалень і рот Мідного стягу, позначених шпильками, кожна з яких коштує чималих грошей"],
  "Scales, crucibles, a touchstone, and a blackiron ingot stamped with the Obsidian Legacy's obelisk": ["天秤、るつぼ、試金石、そして黒曜の遺統のオベリスクが刻印された黒鉄の延べ棒", "저울, 도가니, 시금석, 그리고 흑요 유산의 오벨리스크가 찍힌 흑철 주괴", "天平、坩埚、试金石,还有一块盖着黑曜遗脉方尖碑印记的黑铁锭", "天平、坩堝、試金石,還有一塊蓋著黑曜遺脈方尖碑印記的黑鐵錠", "Cân, nồi nấu kim loại, đá thử vàng, và một thỏi sắt đen đóng dấu hình tháp đá của Di Sản Hắc Diện", "Timbangan, kowi, batu uji, dan sebatang ingot besi hitam bercap obelisk Warisan Obsidian", "ตาชั่ง เบ้าหลอม หินทดสอบทอง และแท่งเหล็กดำที่ประทับตราเสาโอเบลิสก์ของมรดกออบซิเดียน", "Teraziler, potalar, bir mihenk taşı ve Obsidyen Mirası'nın dikilitaşıyla damgalanmış bir karademir külçesi", "Balanzas, crisoles, una piedra de toque y un lingote de hierro negro estampado con el obelisco del Legado de Obsidiana", "Balanças, cadinhos, uma pedra de toque e um lingote de ferro-negro estampado com o obelisco do Legado de Obsidiana", "Весы, тигли, пробирный камень и слиток чёрного железа с клеймом-обелиском Обсидианового наследия", "Терези, тиглі, пробірний камінь і злиток чорного заліза з тавром-обеліском Обсидіанової спадщини"],
  "Rope, pitons, lamp oil, dried apricots and blankets, all of it priced for people who have climbed a long way": ["縄、ハーケン、灯油、干し杏、毛布。どれも長い道のりを登ってきた人向けの値段だ", "밧줄, 하켄, 등잔 기름, 말린 살구, 담요. 모두 먼 길을 올라온 사람에게 맞춘 값이다", "绳子、岩钉、灯油、杏干和毯子,全都按爬了很远山路的人定价", "繩子、岩釘、燈油、杏乾和毯子,全都按爬了很遠山路的人定價", "Dây thừng, đinh leo núi, dầu đèn, mơ khô và chăn, tất cả đều được định giá cho những người đã leo một chặng đường dài", "Tali, piton, minyak lampu, aprikot kering, dan selimut, semuanya dihargai untuk orang yang sudah mendaki jauh", "เชือก หมุดปีนเขา น้ำมันตะเกียง แอปริคอตแห้ง และผ้าห่ม ทั้งหมดตั้งราคาไว้สำหรับคนที่ปีนขึ้นมาไกล", "İp, kaya çivisi, kandil yağı, kuru kayısı ve battaniye; hepsi uzun yoldan tırmanıp gelmiş insanlara göre fiyatlandırılmış", "Cuerda, clavijas, aceite de lámpara, orejones y mantas, todo con precios para gente que ha subido mucho", "Corda, pitons, óleo de lamparina, damascos secos e cobertores, tudo com preço para quem subiu um longo caminho", "Верёвка, скальные крючья, масло для ламп, курага и одеяла — всё по ценам для тех, кто долго карабкался в гору", "Мотузка, скельні гаки, олія для ламп, курага й ковдри — усе за цінами для тих, хто довго дерся вгору"],
  "Highland wool in red and undyed grey, thick enough to stand up on its own": ["赤と生成りの灰色の高地の羊毛。ひとりでに立つほど分厚い", "빨간색과 염색하지 않은 회색의 고원 양모. 혼자 서 있을 만큼 두껍다", "红色与未染灰色的高地羊毛,厚得能自己立起来", "紅色與未染灰色的高地羊毛,厚得能自己立起來", "Len cao nguyên màu đỏ và xám mộc, dày đến mức tự đứng được", "Wol dataran tinggi merah dan abu-abu tanpa celup, cukup tebal untuk berdiri sendiri", "ขนแกะที่ราบสูงสีแดงและสีเทาไม่ย้อม หนาจนตั้งอยู่ได้เอง", "Kırmızı ve boyanmamış gri yayla yünü, kendi başına ayakta duracak kadar kalın", "Lana de las tierras altas en rojo y gris sin teñir, tan gruesa que se tiene en pie sola", "Lã das terras altas em vermelho e cinza cru, grossa o bastante para ficar de pé sozinha", "Горная шерсть, красная и некрашеная серая, такая плотная, что стоит сама", "Гірська вовна, червона й нефарбована сіра, така щільна, що стоїть сама"],
  "SHAILAGARH, the fortress of the passes. Held by Lord Varanjit. The mines are open to those who pay the mine-tithe; the passes are open to those who pay the pass-toll; the fortress is open to those who are asked in.": ["峠の砦、シャイラガル。ヴァランジット卿が治める。鉱山は鉱山十分の一税を払う者に開かれ、峠は通行税を払う者に開かれ、砦は招かれた者に開かれる。", "고개의 요새 샤일라가르. 바란지트 경이 다스린다. 광산은 광산 십일조를 내는 자에게 열려 있고, 고개는 통행세를 내는 자에게 열려 있으며, 요새는 초대받은 자에게 열려 있다.", "沙伊拉加尔,群山隘口的要塞。由瓦兰吉特大人镇守。矿山向缴纳矿山什一税者开放;山口向缴纳过路费者开放;要塞向受邀入内者开放。", "沙伊拉加爾,群山隘口的要塞。由瓦蘭吉特大人鎮守。礦山向繳納礦山什一稅者開放;山口向繳納過路費者開放;要塞向受邀入內者開放。", "SHAILAGARH, pháo đài của các con đèo. Do Lãnh chúa Varanjit trấn giữ. Mỏ mở cửa cho ai nộp thuế mỏ; đèo mở cửa cho ai nộp phí qua đèo; pháo đài mở cửa cho ai được mời vào.", "SHAILAGARH, benteng celah-celah gunung. Dikuasai Tuan Varanjit. Tambang terbuka bagi yang membayar upeti tambang; celah terbuka bagi yang membayar bea celah; benteng terbuka bagi yang diundang masuk.", "ไศลครห์ ป้อมแห่งช่องเขา ปกครองโดยท่านวรัญชิต เหมืองเปิดให้ผู้ที่จ่ายส่วยเหมือง ช่องเขาเปิดให้ผู้ที่จ่ายค่าผ่านทาง ป้อมเปิดให้ผู้ที่ได้รับเชิญเข้าไป", "SHAILAGARH, geçitlerin kalesi. Lord Varanjit'in elinde. Madenler maden öşrünü ödeyenlere açıktır; geçitler geçit bacını ödeyenlere açıktır; kale ise içeri davet edilenlere açıktır.", "SHAILAGARH, la fortaleza de los pasos. En manos del señor Varanjit. Las minas están abiertas a quien paga el diezmo minero; los pasos, a quien paga el peaje del paso; la fortaleza, a quien es invitado a entrar.", "SHAILAGARH, a fortaleza dos passos. Nas mãos do senhor Varanjit. As minas estão abertas a quem paga o dízimo da mina; os passos, a quem paga o pedágio do passo; a fortaleza, a quem é convidado a entrar.", "ШАЙЛАГАРХ, крепость перевалов. В руках лорда Варанджита. Рудники открыты тем, кто платит рудничную десятину; перевалы — тем, кто платит перевальную пошлину; крепость — тем, кого пригласили войти.", "ШАЙЛАГАРХ, фортеця перевалів. У руках лорда Варанджита. Копальні відкриті для тих, хто платить копальняну десятину; перевали — для тих, хто платить перевальне мито; фортеця — для тих, кого запросили всередину."],
  "MANDAPUR. Here the League of Seven Parasols meets under the open sky, and the Speaker speaks for all seven until the next turn. No ruler's parasol stands higher than another's. Tolls on League roads are paid at the office by the south step.": ["マンダプル。ここで七つの日傘同盟は青空の下に集い、議長は次の交代まで七者すべてを代弁する。どの支配者の日傘も他の者より高くは立たない。同盟の街道の通行税は、南の石段そばの役所で支払うこと。", "만다푸르. 이곳에서 일곱 일산 동맹이 탁 트인 하늘 아래 모이고, 의장은 다음 차례가 올 때까지 일곱 모두를 대변한다. 어떤 통치자의 일산도 다른 이의 것보다 높이 서지 않는다. 동맹 도로의 통행세는 남쪽 계단 옆 사무소에서 낸다.", "曼达普尔。七华盖同盟在此露天集会,议长代表七方发言,直到下一次轮替。任何统治者的华盖都不得高于他人。同盟道路的通行费,请到南阶旁的收费处缴纳。", "曼達普爾。七華蓋同盟在此露天集會,議長代表七方發言,直到下一次輪替。任何統治者的華蓋都不得高於他人。同盟道路的通行費,請到南階旁的收費處繳納。", "MANDAPUR. Nơi đây Liên minh Bảy Lọng họp dưới bầu trời rộng mở, và Phát ngôn nhân nói thay cả bảy cho đến lượt kế tiếp. Không chiếc lọng của người cai trị nào đứng cao hơn chiếc khác. Phí đường của Liên minh nộp tại trạm cạnh bậc thềm phía nam.", "MANDAPUR. Di sini Liga Tujuh Payung bersidang di bawah langit terbuka, dan Juru Bicara berbicara untuk ketujuhnya sampai giliran berikutnya. Tak ada payung penguasa yang berdiri lebih tinggi dari yang lain. Bea jalan Liga dibayar di kantor dekat tangga selatan.", "มัณฑปุระ ที่นี่สันนิบาตเจ็ดฉัตรประชุมกันกลางแจ้ง และประธานพูดแทนทั้งเจ็ดจนกว่าจะถึงวาระถัดไป ไม่มีฉัตรของผู้ปกครองใดตั้งสูงกว่าของผู้อื่น ค่าผ่านทางบนถนนของสันนิบาตชำระได้ที่สำนักงานข้างบันไดทิศใต้", "MANDAPUR. Yedi Şemsiye Birliği burada açık gökyüzü altında toplanır ve Sözcü bir sonraki nöbete dek yedisi adına konuşur. Hiçbir hükümdarın şemsiyesi bir başkasınınkinden yüksekte durmaz. Birlik yollarının geçiş ücreti güney basamağının yanındaki büroda ödenir.", "MANDAPUR. Aquí la Liga de los Siete Parasoles se reúne a cielo abierto, y el Portavoz habla por los siete hasta el siguiente turno. Ningún parasol de gobernante se alza más alto que el de otro. Los peajes de los caminos de la Liga se pagan en la oficina junto a la escalinata sur.", "MANDAPUR. Aqui a Liga dos Sete Para-sóis se reúne a céu aberto, e o Porta-voz fala pelos sete até o próximo turno. Nenhum para-sol de governante fica mais alto que o de outro. Os pedágios das estradas da Liga são pagos no posto junto à escadaria sul.", "МАНДАПУР. Здесь Лига Семи Зонтов собирается под открытым небом, и Глашатай говорит за всех семерых до следующей очереди. Ничей зонт правителя не стоит выше чужого. Пошлины на дорогах Лиги платят в конторе у южных ступеней.", "МАНДАПУР. Тут Ліга Семи Парасолів збирається під відкритим небом, і Речник говорить за всіх сімох до наступної черги. Жодна парасоль правителя не стоїть вище за чужу. Мито на дорогах Ліги сплачують у конторі біля південних сходів."],
  "Shelves of palm-leaf books, bound in boards, each with a label in three scripts": ["板で綴じた貝葉の書物が並ぶ棚。どれにも三種の文字で書かれた札が付いている", "나무판으로 묶은 패엽서가 꽂힌 서가. 하나하나에 세 가지 문자로 쓴 표찰이 붙어 있다", "一排排贝叶书,以木板装订,每本都贴着三种文字的标签", "一排排貝葉書,以木板裝訂,每本都貼著三種文字的標籤", "Những kệ sách lá cọ, đóng bìa gỗ, cuốn nào cũng có nhãn ghi bằng ba thứ chữ", "Rak-rak kitab daun lontar, dijilid papan, masing-masing berlabel dalam tiga aksara", "ชั้นวางคัมภีร์ใบลาน เข้าปกด้วยแผ่นไม้ แต่ละเล่มมีป้ายเขียนด้วยอักษรสามแบบ", "Tahta kapaklarla ciltlenmiş palmiye yaprağı kitaplarıyla dolu raflar, her birinde üç ayrı yazıyla bir etiket", "Estantes de libros de hoja de palma, encuadernados entre tablas, cada uno con una etiqueta en tres escrituras", "Estantes de livros de folha de palmeira, encadernados entre tábuas, cada um com uma etiqueta em três escritas", "Полки с книгами на пальмовых листьях в дощатых переплётах, у каждой ярлык на трёх письменностях", "Полиці з книгами на пальмовому листі в дощаних оправах, на кожній ярлик трьома письменами"],
  "A reading desk under the dome, a star chart weighted flat with four inkpots": ["ドームの下の書見台。星図が四つのインク壺で押さえて広げてある", "돔 아래의 독서대. 잉크병 네 개로 눌러 편 성도가 놓여 있다", "穹顶下的一张阅读桌,一幅星图被四个墨水瓶压平", "穹頂下的一張閱讀桌,一幅星圖被四個墨水瓶壓平", "Bàn đọc dưới mái vòm, một tấm bản đồ sao được chặn phẳng bằng bốn lọ mực", "Meja baca di bawah kubah, peta bintang ditindih rata dengan empat botol tinta", "โต๊ะอ่านหนังสือใต้โดม แผนที่ดาวถูกกดให้แบนด้วยขวดหมึกสี่ขวด", "Kubbenin altında bir okuma masası, dört mürekkep hokkasıyla düz tutulan bir yıldız haritası", "Un pupitre de lectura bajo la cúpula, con una carta estelar sujeta con cuatro tinteros", "Uma mesa de leitura sob a cúpula, com uma carta estelar mantida aberta por quatro tinteiros", "Читальный стол под куполом, звёздная карта прижата четырьмя чернильницами", "Читальний стіл під банею, зоряна мапа притиснута чотирма чорнильницями"],
  "The Assembly's banner: a pen crossed with a coin, on sea green": ["議会の旗:海緑色の地に、ペンと貨幣を交差させた図", "의회의 깃발: 바닷빛 초록 바탕에 펜과 주화가 교차한 문양", "议会的旗帜:海绿底色上,一支笔与一枚钱币交叉", "議會的旗幟:海綠底色上,一支筆與一枚錢幣交叉", "Cờ của Hội đồng: một cây bút bắt chéo với một đồng xu, trên nền xanh nước biển", "Panji Majelis: pena bersilang dengan koin, di atas warna hijau laut", "ธงของสภา: ปากกาไขว้กับเหรียญ บนพื้นสีเขียวน้ำทะเล", "Meclis'in sancağı: deniz yeşili zemin üzerinde bir sikkeyle çaprazlanmış bir kalem", "El estandarte de la Asamblea: una pluma cruzada con una moneda, sobre verde mar", "O estandarte da Assembleia: uma pena cruzada com uma moeda, sobre verde-mar", "Знамя Собрания: перо, скрещённое с монетой, на поле цвета морской волны", "Прапор Зборів: перо, схрещене з монетою, на полі кольору морської хвилі"],
  "Silk from the far east, cotton from the valley, and ink-dyed stoles for the Assembly": ["遥か東方の絹、谷の木綿、そして議会向けの墨染めの肩掛け", "머나먼 동쪽의 비단, 계곡의 무명, 그리고 의회용 먹물 들인 숄", "远东的丝绸、河谷的棉布,还有给议会做的墨染披巾", "遠東的絲綢、河谷的棉布,還有給議會做的墨染披巾", "Lụa từ viễn đông, vải bông từ thung lũng, và khăn choàng nhuộm mực cho Hội đồng", "Sutra dari timur jauh, katun dari lembah, dan selendang celup tinta untuk Majelis", "ผ้าไหมจากตะวันออกไกล ผ้าฝ้ายจากหุบเขา และผ้าคลุมไหล่ย้อมหมึกสำหรับสภา", "Uzak doğudan ipek, vadiden pamuk ve Meclis için mürekkeple boyanmış şallar", "Seda del lejano oriente, algodón del valle y estolas teñidas de tinta para la Asamblea", "Seda do extremo oriente, algodão do vale e estolas tingidas de tinta para a Assembleia", "Шёлк с дальнего востока, хлопок из долины и окрашенные чернилами палантины для Собрания", "Шовк із далекого сходу, бавовна з долини й пофарбовані чорнилом палантини для Зборів"],
  "Ship's biscuit, rope, tar, lamp oil, and charts of coasts nobody you know has seen": ["乾パン、ロープ、タール、灯油、そしてあなたの知り合いの誰ひとり見たことのない海岸の海図", "건빵, 밧줄, 타르, 등잔 기름, 그리고 당신이 아는 누구도 본 적 없는 해안의 해도", "船用硬饼干、绳索、焦油、灯油,还有你认识的人谁都没见过的海岸的海图", "船用硬餅乾、繩索、焦油、燈油,還有你認識的人誰都沒見過的海岸的海圖", "Bánh quy đi biển, dây thừng, hắc ín, dầu đèn, và hải đồ của những bờ biển chẳng ai bạn quen từng thấy", "Biskuit kapal, tali, ter, minyak lampu, dan peta pesisir yang belum pernah dilihat siapa pun yang kau kenal", "ขนมปังกรอบเดินเรือ เชือก น้ำมันดิน น้ำมันตะเกียง และแผนที่ชายฝั่งที่ไม่มีใครที่คุณรู้จักเคยเห็น", "Peksimet, halat, katran, lamba yağı ve tanıdığın hiç kimsenin görmediği kıyıların haritaları", "Galleta de barco, cuerda, brea, aceite de lámpara y cartas de costas que nadie que conozcas ha visto", "Biscoito de bordo, corda, piche, óleo de lamparina e cartas de costas que ninguém que você conhece já viu", "Корабельные сухари, верёвка, дёготь, ламповое масло и карты берегов, которых не видел никто из ваших знакомых", "Корабельні сухарі, мотузка, дьоготь, лампова олія й мапи узбереж, яких не бачив ніхто з ваших знайомих"],
  "SUVARNATIRA, the free port. Governed by the Assembly of Ink and Coin under Provost Lalitha. No crown is owed here and no toll on books. The Archive admits any reader with clean hands and a reason; the harbour admits any ship that pays its berth.": ["自由港スヴァルナティーラ。ラリタ学頭のもと、墨と貨幣の議会が治める。ここではいかなる王冠にも借りはなく、書物に通行税はかからない。文書館は手が清く理由のある読者なら誰でも迎え入れ、港は停泊料を払う船ならどれでも迎え入れる。", "자유항 수바르나티라. 랄리타 학장 아래 먹과 주화의 의회가 다스린다. 이곳에서는 어떤 왕관에도 빚진 것이 없고, 책에는 통행세가 붙지 않는다. 서고는 손이 깨끗하고 이유가 있는 독자라면 누구든 받아들이고, 항구는 정박료를 내는 배라면 어떤 배든 받아들인다.", "苏瓦尔纳蒂拉,自由港。由墨与币议会在拉丽塔院长领导下治理。此地不欠任何王冠,书籍也不收通行费。档案馆接纳任何双手干净、理由正当的读者;港口接纳任何付清泊位费的船只。", "蘇瓦爾納蒂拉,自由港。由墨與幣議會在拉麗塔院長領導下治理。此地不欠任何王冠,書籍也不收通行費。檔案館接納任何雙手乾淨、理由正當的讀者;港口接納任何付清泊位費的船隻。", "SUVARNATIRA, cảng tự do. Do Hội đồng Mực và Xu cai quản dưới quyền Viện trưởng Lalitha. Ở đây chẳng nợ vương miện nào, và sách không phải đóng phí. Văn khố đón mọi người đọc có đôi tay sạch và một lý do; bến cảng đón mọi con tàu trả phí neo đậu.", "SUVARNATIRA, pelabuhan bebas. Diperintah Majelis Tinta dan Koin di bawah Provos Lalitha. Di sini tak ada mahkota yang harus disembah dan tak ada bea atas buku. Arsip menerima pembaca mana pun yang bertangan bersih dan punya alasan; pelabuhan menerima kapal mana pun yang membayar tambatannya.", "สุวรรณตีระ เมืองท่าเสรี ปกครองโดยสภาหมึกและเหรียญภายใต้อธิการลลิตา ที่นี่ไม่ติดค้างมงกุฎใด และไม่เก็บค่าผ่านทางจากหนังสือ หอจดหมายเหตุรับผู้อ่านทุกคนที่มือสะอาดและมีเหตุผล ท่าเรือรับเรือทุกลำที่จ่ายค่าจอด", "SUVARNATIRA, serbest liman. Rektör Lalitha'nın başında olduğu Mürekkep ve Sikke Meclisi tarafından yönetilir. Burada hiçbir taca borç yoktur, kitaplardan da geçiş ücreti alınmaz. Arşiv, elleri temiz ve bir gerekçesi olan her okuru kabul eder; liman, rıhtım ücretini ödeyen her gemiyi kabul eder.", "SUVARNATIRA, el puerto libre. Gobernado por la Asamblea de Tinta y Moneda bajo la prebostesa Lalitha. Aquí no se le debe nada a ninguna corona ni se paga peaje por los libros. El Archivo admite a cualquier lector con las manos limpias y un motivo; el puerto admite a cualquier barco que pague su amarre.", "SUVARNATIRA, o porto livre. Governado pela Assembleia da Tinta e da Moeda sob a reitora Lalitha. Aqui não se deve nada a coroa alguma, e não há pedágio sobre livros. O Arquivo admite qualquer leitor de mãos limpas e com um motivo; o porto admite qualquer navio que pague sua ancoragem.", "СУВАРНАТИРА, вольный порт. Управляется Собранием Чернил и Монет под началом провоста Лалиты. Здесь никто не в долгу у короны, и с книг не берут пошлин. Архив принимает любого читателя с чистыми руками и вескою причиной; гавань принимает любое судно, оплатившее стоянку.", "СУВАРНАТІРА, вільний порт. Керується Зборами Чорнила й Монет під проводом провоста Лаліти. Тут ніхто не в боргу перед короною, і з книжок не беруть мита. Архів приймає будь-якого читача з чистими руками й поважною причиною; гавань приймає будь-яке судно, що сплатило стоянку."],
  "KANTHAR, of the Kanthari. The forest is not a road. Ask before you cut, ask before you hunt, ask before you take anything that grows. Grandmother Sukesh answers for the village.": ["カンタリのカンタル。森は道ではない。切る前に尋ね、狩る前に尋ね、育つものを取る前に尋ねよ。村のことはスケシュ婆さまが答える。", "칸타리족의 칸타르. 숲은 길이 아니다. 베기 전에 묻고, 사냥하기 전에 묻고, 자라는 것을 가져가기 전에 물어라. 마을을 대신해서는 수케시 할머니가 답한다.", "坎塔尔,坎塔里人之地。森林不是道路。砍伐之前先问,狩猎之前先问,拿走任何生长之物之前先问。苏凯什奶奶代表村子答复。", "坎塔爾,坎塔里人之地。森林不是道路。砍伐之前先問,狩獵之前先問,拿走任何生長之物之前先問。蘇凱什奶奶代表村子答覆。", "KANTHAR, của người Kanthari. Rừng không phải là đường. Hãy hỏi trước khi chặt, hỏi trước khi săn, hỏi trước khi lấy bất cứ thứ gì đang mọc. Bà Sukesh trả lời thay cho làng.", "KANTHAR, milik orang Kanthari. Hutan bukan jalan. Bertanyalah sebelum menebang, bertanyalah sebelum berburu, bertanyalah sebelum mengambil apa pun yang tumbuh. Nenek Sukesh menjawab atas nama desa.", "กันถาร์ ของชาวกันถารี ป่าไม่ใช่ถนน จงถามก่อนตัด ถามก่อนล่า ถามก่อนเอาสิ่งใดที่งอกงามไป ยายสุเกศเป็นผู้ตอบแทนหมู่บ้าน", "KANTHAR, Kantharilerin yurdu. Orman yol değildir. Kesmeden önce sor, avlanmadan önce sor, büyüyen herhangi bir şeyi almadan önce sor. Köy adına Sukesh Nine cevap verir.", "KANTHAR, de los kanthari. El bosque no es un camino. Pregunta antes de talar, pregunta antes de cazar, pregunta antes de llevarte cualquier cosa que crezca. La abuela Sukesh responde por la aldea.", "KANTHAR, dos kanthari. A floresta não é uma estrada. Pergunte antes de cortar, pergunte antes de caçar, pergunte antes de levar qualquer coisa que cresça. A avó Sukesh responde pela aldeia.", "КАНТХАР, селение кантхари. Лес — не дорога. Спроси, прежде чем рубить; спроси, прежде чем охотиться; спроси, прежде чем взять что-либо растущее. За деревню отвечает бабушка Сукеш.", "КАНТХАР, оселя кантхарі. Ліс — не дорога. Спитай, перш ніж рубати; спитай, перш ніж полювати; спитай, перш ніж узяти будь-що, що росте. За село відповідає бабуся Сукеш."],
  "A ripe mango from the Ilavati's orchards, so soft it has to be eaten leaning forward. Heals 6.": ["イラヴァティ川の果樹園で採れた熟したマンゴー。柔らかすぎて、前かがみにならないと食べられない。6回復。", "일라바티 강 과수원에서 딴 잘 익은 망고. 너무 물러서 몸을 앞으로 숙이고 먹어야 한다. 6 회복.", "一个伊拉瓦蒂河边果园里的熟芒果,软得只能弯着腰吃。恢复 6。", "一顆伊拉瓦蒂河邊果園裡的熟芒果,軟得只能彎著腰吃。恢復 6。", "Một quả xoài chín từ vườn cây bên sông Ilavati, mềm đến mức phải chồm người tới trước mà ăn. Hồi 6.", "Mangga matang dari kebun-kebun di tepi Ilavati, begitu lembek sampai harus dimakan sambil membungkuk ke depan. Memulihkan 6.", "มะม่วงสุกจากสวนริมแม่น้ำอิลาวดี นิ่มจนต้องโน้มตัวไปข้างหน้าเวลากิน ฟื้นฟู 6", "Ilavati'nin bahçelerinden olgun bir mango; öyle yumuşak ki öne eğilerek yemek gerekir. 6 iyileştirir.", "Un mango maduro de los huertos del Ilavati, tan blando que hay que comerlo inclinado hacia delante. Cura 6.", "Uma manga madura dos pomares do Ilavati, tão mole que precisa ser comida inclinado para a frente. Cura 6.", "Спелый манго из садов Илавати, такой мягкий, что есть его приходится, наклонившись вперёд. Лечит 6.", "Стигле манго із садів Ілаваті, таке м'яке, що їсти його доводиться, нахилившись уперед. Лікує 6."],
  "Black tea boiled with milk, ginger, cardamom and too much sugar, in a little clay cup you're meant to break after. Heals 5.": ["牛乳、生姜、カルダモン、それに多すぎる砂糖と一緒に煮出した紅茶。飲んだ後に割るための小さな素焼きの器に入っている。5回復。", "우유, 생강, 카다멈, 그리고 너무 많은 설탕을 넣고 끓인 홍차. 다 마시면 깨뜨리라고 만든 작은 토기 잔에 담겨 있다. 5 회복.", "红茶加牛奶、姜、小豆蔻和太多的糖一起煮,盛在一个小陶杯里——喝完就该把杯子摔碎。恢复 5。", "紅茶加牛奶、薑、小豆蔻和太多的糖一起煮,盛在一個小陶杯裡——喝完就該把杯子摔碎。恢復 5。", "Trà đen nấu với sữa, gừng, bạch đậu khấu và quá nhiều đường, đựng trong chiếc chén đất nhỏ mà uống xong thì phải đập vỡ. Hồi 5.", "Teh hitam direbus dengan susu, jahe, kapulaga, dan terlalu banyak gula, dalam cangkir tanah liat kecil yang memang untuk dipecahkan sesudahnya. Memulihkan 5.", "ชาดำต้มกับนม ขิง กระวาน และน้ำตาลมากเกินไป ใส่ถ้วยดินเผาใบเล็กที่ดื่มเสร็จแล้วต้องทุบทิ้ง ฟื้นฟู 5", "Süt, zencefil, kakule ve fazlasıyla şekerle kaynatılmış siyah çay; sonradan kırılması gereken küçük bir kil fincanda. 5 iyileştirir.", "Té negro hervido con leche, jengibre, cardamomo y demasiado azúcar, en una tacita de barro que se supone que rompes después. Cura 5.", "Chá preto fervido com leite, gengibre, cardamomo e açúcar demais, numa tacinha de barro que você deve quebrar depois. Cura 5.", "Чёрный чай, сваренный с молоком, имбирём, кардамоном и слишком большим количеством сахара, в глиняной чашечке, которую потом положено разбить. Лечит 5.", "Чорний чай, зварений із молоком, імбиром, кардамоном і забагато цукру, у глиняній чашечці, яку потім годиться розбити. Лікує 5."],
  "A bowl of rice with yellow lentils, cumin and a spoon of ghee: what Meghavan eats when it isn't celebrating, and most of what it eats when it is. Heals 16.": ["黄色いレンズ豆とクミン、ギーをひと匙のせたご飯。メガヴァンが祝い事のない日に食べるもので、祝い事の日に食べるものもほとんどこれだ。16回復。", "노란 렌틸콩과 쿠민, 기 한 숟가락을 곁들인 밥 한 그릇. 메가반이 잔치를 하지 않을 때 먹는 음식이자, 잔치를 할 때 먹는 음식의 대부분이다. 16 회복.", "一碗米饭,配黄扁豆、孜然和一勺酥油:梅加万不过节时吃的就是这个,过节时吃的也大多是这个。恢复 16。", "一碗米飯,配黃扁豆、孜然和一勺酥油:梅加萬不過節時吃的就是這個,過節時吃的也大多是這個。恢復 16。", "Một bát cơm với đậu lăng vàng, thì là Ai Cập và một thìa bơ ghee: thứ Meghavan ăn khi không có lễ hội, và cũng là phần lớn những gì nó ăn khi có. Hồi 16.", "Semangkuk nasi dengan lentil kuning, jintan, dan sesendok ghee: makanan Meghavan saat tidak sedang berpesta, dan sebagian besar makanannya saat sedang berpesta. Memulihkan 16.", "ข้าวหนึ่งชามกับถั่วเลนทิลเหลือง ยี่หร่า และเนยกีหนึ่งช้อน คือสิ่งที่เมฆาวันกินยามไม่มีงานฉลอง และเป็นส่วนใหญ่ของสิ่งที่กินยามมีงานฉลอง ฟื้นฟู 16", "Sarı mercimek, kimyon ve bir kaşık sadeyağla bir kâse pirinç: Meghavan'ın kutlama yapmadığı günlerde yediği, kutlama yaptığı günlerde de yediklerinin çoğu. 16 iyileştirir.", "Un cuenco de arroz con lentejas amarillas, comino y una cucharada de ghee: lo que come Meghavan cuando no está de fiesta, y casi todo lo que come cuando lo está. Cura 16.", "Uma tigela de arroz com lentilha amarela, cominho e uma colher de ghee: o que Meghavan come quando não está em festa, e quase tudo o que come quando está. Cura 16.", "Миска риса с жёлтой чечевицей, зирой и ложкой гхи: то, что Мегхаван ест, когда не празднует, и большая часть того, что он ест, когда празднует. Лечит 16.", "Миска рису з жовтою сочевицею, кмином і ложкою топленого масла гхі: те, що Мегхаван їсть, коли не святкує, і більшість того, що він їсть, коли святкує. Лікує 16."],
  "A peafowl's train feather, an eye of blue and bronze at its tip. Suvarnatira's scribes keep one on the desk for luck, and to point at things.": ["クジャクの飾り羽。先端に青と青銅色の目玉模様がある。スヴァルナティーラの書記たちは幸運のため、そして物を指し示すために、一本を机に置いている。", "공작의 꽁지깃. 끝에 푸른색과 청동색의 눈 무늬가 있다. 수바르나티라의 서기들은 행운을 빌려고, 그리고 무언가를 가리키려고 책상에 하나씩 둔다.", "一根孔雀尾羽,末端有一只蓝铜相间的眼斑。苏瓦尔纳蒂拉的书吏们在桌上放一根,图个吉利,也用来指东西。", "一根孔雀尾羽,末端有一隻藍銅相間的眼斑。蘇瓦爾納蒂拉的書吏們在桌上放一根,圖個吉利,也用來指東西。", "Một chiếc lông đuôi công, đầu lông có con mắt màu xanh lam và đồng thau. Các thư lại ở Suvarnatira để một chiếc trên bàn cho may mắn, và để chỉ trỏ.", "Bulu ekor merak, dengan mata biru dan perunggu di ujungnya. Para juru tulis Suvarnatira menyimpan satu di meja untuk keberuntungan, dan untuk menunjuk-nunjuk.", "ขนหางนกยูง ปลายขนมีลายตาสีน้ำเงินและสีสำริด เหล่าอาลักษณ์แห่งสุวรรณตีระวางไว้บนโต๊ะคนละเส้นเพื่อความโชคดี และไว้ชี้สิ่งต่าง ๆ", "Bir tavus kuşunun kuyruk tüyü, ucunda mavi ve bronz bir göz. Suvarnatira'nın kâtipleri masalarında uğur için bir tane tutar, bir de bir şeyleri göstermek için.", "Una pluma de la cola de un pavo real, con un ojo azul y bronce en la punta. Los escribas de Suvarnatira tienen una en el escritorio para la suerte, y para señalar cosas.", "Uma pena da cauda de um pavão, com um olho azul e bronze na ponta. Os escribas de Suvarnatira deixam uma na mesa para dar sorte, e para apontar coisas.", "Перо из павлиньего хвоста с сине-бронзовым глазком на кончике. Писцы Суварнатиры держат такое на столе на удачу — и чтобы указывать им на что-нибудь.", "Перо з павичевого хвоста із синьо-бронзовим вічком на кінчику. Писарі Суварнатіри тримають таке на столі на удачу — і щоб показувати ним на щось."],
  "A striped pelt, heavy and still warm-smelling. The Kanthari say a tiger skin belongs to the forest; the Archive's buyers say it belongs to whoever pays.": ["縞模様の毛皮。重く、まだ温かい匂いがする。カンタリは虎の皮は森のものだと言い、文書館の買い手は金を払った者のものだと言う。", "줄무늬 가죽. 묵직하고 아직 따뜻한 냄새가 난다. 칸타리족은 호랑이 가죽이 숲의 것이라 하고, 서고의 구매인들은 값을 치르는 자의 것이라 한다.", "一张带条纹的毛皮,沉甸甸的,闻起来还带着体温。坎塔里人说虎皮属于森林;档案馆的买家说它属于付钱的人。", "一張帶條紋的毛皮,沉甸甸的,聞起來還帶著體溫。坎塔里人說虎皮屬於森林;檔案館的買家說它屬於付錢的人。", "Một tấm da sọc, nặng và vẫn còn mùi ấm. Người Kanthari nói da hổ thuộc về rừng; những người mua của Văn khố nói nó thuộc về ai trả tiền.", "Kulit bergaris, berat dan masih berbau hangat. Orang Kanthari bilang kulit harimau milik hutan; para pembeli Arsip bilang kulit itu milik siapa pun yang membayar.", "หนังลายทาง หนักและยังมีกลิ่นอุ่น ๆ ชาวกันถารีว่าหนังเสือเป็นของป่า ส่วนพวกผู้ซื้อของหอจดหมายเหตุว่ามันเป็นของใครก็ตามที่จ่ายเงิน", "Çizgili bir post; ağır ve hâlâ sıcak kokulu. Kanthariler kaplan postunun ormana ait olduğunu söyler; Arşiv'in alıcıları ise parayı kim öderse ona ait olduğunu.", "Una piel rayada, pesada y que aún huele a cálido. Los kanthari dicen que una piel de tigre pertenece al bosque; los compradores del Archivo dicen que pertenece a quien pague.", "Uma pele listrada, pesada e com um cheiro ainda morno. Os kanthari dizem que a pele de tigre pertence à floresta; os compradores do Arquivo dizem que pertence a quem pagar.", "Полосатая шкура, тяжёлая и всё ещё пахнущая теплом. Кантхари говорят, что тигриная шкура принадлежит лесу; скупщики Архива говорят — тому, кто платит.", "Смугаста шкура, важка й досі пахне теплом. Кантхарі кажуть, що тигряча шкура належить лісові; скупники Архіву кажуть — тому, хто платить."],
  "A wild gaur's horn, curved and grey-green at the tip. Carvers in Mandapur make parasol handles of it.": ["野生のガウルの角。湾曲し、先端は灰緑色。マンダプルの彫り師たちはこれで日傘の柄を作る。", "야생 가우르의 뿔. 휘어 있고 끝은 회녹색이다. 만다푸르의 조각가들은 이것으로 일산 손잡이를 만든다.", "一只野生印度野牛的角,弯曲,尖端灰绿。曼达普尔的雕匠用它做华盖的柄。", "一隻野生印度野牛的角,彎曲,尖端灰綠。曼達普爾的雕匠用它做華蓋的柄。", "Sừng của một con bò tót hoang, cong và xám xanh ở đầu. Thợ chạm ở Mandapur dùng nó làm cán lọng.", "Tanduk banteng gaur liar, melengkung dan hijau keabuan di ujungnya. Para pemahat di Mandapur membuat gagang payung darinya.", "เขากระทิงป่า โค้งงอ ปลายเป็นสีเขียวอมเทา ช่างแกะสลักในมัณฑปุระนำมาทำด้ามฉัตร", "Yabani bir gaurun boynuzu; kıvrık, ucu gri-yeşil. Mandapur'daki oymacılar bundan şemsiye sapları yapar.", "El cuerno de un gaur salvaje, curvo y gris verdoso en la punta. Los tallistas de Mandapur hacen con él mangos de parasol.", "O chifre de um gauro selvagem, curvo e cinza-esverdeado na ponta. Os entalhadores de Mandapur fazem dele cabos de para-sol.", "Рог дикого гаура, изогнутый, серо-зелёный на конце. Резчики Мандапура делают из него рукояти зонтов.", "Ріг дикого гаура, вигнутий, сіро-зелений на кінці. Різьбярі Мандапура роблять із нього руків'я парасолів."],
  "A curved sabre of blackiron with a disc pommel and a knuckle guard, as Ilavarta's tank guards carry. It cuts from the saddle or the ghat steps alike.": ["円盤形の柄頭と護拳がついた、ブラックアイアンの湾刀。イラヴァルタの貯水池の衛兵が帯びるものだ。鞍の上からでもガートの石段からでも、同じように斬れる。", "원반형 칼자루 끝과 손등 보호대가 달린 흑철 곡도. 일라바르타의 저수지 경비병들이 차는 것이다. 말안장 위에서든 가트 계단에서든 똑같이 잘 벤다.", "一把黑铁弯刀,圆盘形柄头,带护手,伊拉瓦塔的水池卫兵就佩这种刀。不论在马鞍上还是河阶上,一样好砍。", "一把黑鐵彎刀,圓盤形柄頭,帶護手,伊拉瓦塔的水池衛兵就佩這種刀。不論在馬鞍上還是河階上,一樣好砍。", "Một thanh kiếm cong bằng sắt đen, chuôi đốc hình đĩa và có chắn tay, như lính canh hồ chứa của Ilavarta vẫn mang. Chém từ trên yên ngựa hay từ bậc ghat đều ngọt như nhau.", "Sabel melengkung dari besi hitam dengan pangkal gagang berbentuk cakram dan pelindung buku jari, seperti yang dibawa para penjaga telaga Ilavarta. Sama tajamnya ditebaskan dari atas pelana maupun dari tangga ghat.", "ดาบโค้งเหล็กดำ ปลายด้ามเป็นรูปจานกลม มีกระบังมือ แบบที่ทหารรักษาสระแห่งอิลาวรรตะพกกัน ฟันได้ดีพอกันทั้งจากบนหลังม้าและจากท่าน้ำ", "Disk kabzalı ve parmak siperli, kara demirden kıvrık bir pala; Ilavarta'nın havuz muhafızlarının taşıdığı türden. Eyerden de gat basamaklarından da aynı keskinlikte keser.", "Un sable curvo de hierro negro con pomo de disco y guardamano, como los que llevan los guardias de los estanques de Ilavarta. Corta igual desde la silla de montar que desde los escalones de los ghats.", "Um sabre curvo de ferro negro com pomo de disco e guarda-mão, como os que os guardas dos tanques de Ilavarta carregam. Corta igual da sela ou dos degraus dos ghats.", "Изогнутая сабля из чёрного железа с дисковым навершием и защитной дужкой, какие носят стражи прудов Илаварты. Рубит одинаково хорошо что с седла, что со ступеней гатов.", "Вигнута шабля з чорного заліза з дисковим навершям і захисною дужкою, як у вартових ставів Ілаварти. Рубає однаково добре що з сідла, що зі сходів гатів."],
  "A short, broad blade set crossways in an H-shaped grip, made to be punched rather than swung. Mandapur's duellists say it ends arguments before they're finished.": ["短く幅広の刃を、H字形の握りに横向きに据えたもの。振るのではなく、拳で突き出すために作られている。マンダプルの決闘者たちに言わせれば、これは口論が終わる前に口論を終わらせる。", "H자 모양 손잡이에 가로로 박힌 짧고 넓은 칼날. 휘두르는 게 아니라 주먹으로 내지르도록 만들어졌다. 만다푸르의 결투가들은 이것이 말다툼을 끝나기도 전에 끝내 준다고 한다.", "一片短而宽的刀刃,横嵌在H形握柄上,是像出拳一样捅出去的,而不是挥的。曼达普尔的决斗者说,它能在争论吵完之前就结束争论。", "一片短而寬的刀刃,橫嵌在H形握柄上,是像出拳一樣捅出去的,而不是揮的。曼達普爾的決鬥者說,它能在爭論吵完之前就結束爭論。", "Một lưỡi dao ngắn và rộng gắn ngang trong chuôi cầm hình chữ H, làm ra để đấm chứ không phải để vung. Các tay đấu tay đôi ở Mandapur bảo nó kết thúc cuộc cãi vã trước khi cãi xong.", "Bilah pendek dan lebar yang dipasang melintang pada gagang berbentuk H, dibuat untuk ditinjukan, bukan diayunkan. Para petarung duel Mandapur bilang belati ini mengakhiri perdebatan sebelum perdebatannya selesai.", "ใบมีดสั้นและกว้างติดตั้งตามขวางบนด้ามจับรูปตัว H ทำมาเพื่อชกต่อย ไม่ใช่เพื่อเหวี่ยงฟัน นักดวลแห่งมัณฑปุระว่ามันยุติการโต้เถียงได้ก่อนที่จะเถียงกันจบ", "H biçimli bir kabzaya enine takılmış kısa, geniş bir bıçak; savrulmak için değil, yumruk gibi vurulmak için yapılmış. Mandapur'un düellocuları onun tartışmaları daha bitmeden bitirdiğini söyler.", "Una hoja corta y ancha montada de través en una empuñadura en forma de H, hecha para lanzarse como un puñetazo y no para blandirse. Los duelistas de Mandapur dicen que zanja las discusiones antes de que terminen.", "Uma lâmina curta e larga montada de través num punho em forma de H, feita para socar, não para brandir. Os duelistas de Mandapur dizem que ela encerra as discussões antes de terminarem.", "Короткий широкий клинок, поперечно закреплённый в H-образной рукояти: им бьют, как кулаком, а не машут. Дуэлянты Мандапура говорят, что он заканчивает споры раньше, чем те закончатся.", "Короткий широкий клинок, поперечно закріплений в H-подібному руків'ї: ним б'ють, як кулаком, а не махають. Дуелянти Мандапура кажуть, що він закінчує суперечки раніше, ніж ті скінчаться."],
  "A coat of fine blackiron rings riveted shut, lined with quilted highland wool so it doesn't freeze to you in the passes. Shailagarh's forge-masters sign each one inside the collar.": ["リベットで留めた細かいブラックアイアンの輪で編んだ鎖帷子。峠で体に凍りつかないよう、高地の羊毛を刺し子にした裏地がついている。シャイラガルの鍛冶頭は一着ごとに襟の内側に署名する。", "리벳으로 고정한 고운 흑철 고리로 엮은 갑옷. 고개에서 몸에 얼어붙지 않도록 누빈 고원 양모로 안감을 댔다. 샤일라가르의 대장장이 장인들은 한 벌 한 벌 옷깃 안쪽에 서명을 남긴다.", "一件用细密黑铁环铆合而成的甲衣,内衬绗缝的高地羊毛,免得在山口冻在你身上。沙伊拉加尔的锻造大师会在每一件的领口内侧签名。", "一件用細密黑鐵環鉚合而成的甲衣,內襯絎縫的高地羊毛,免得在山口凍在你身上。沙伊拉加爾的鍛造大師會在每一件的領口內側簽名。", "Một chiếc áo giáp kết từ những vòng sắt đen nhỏ tán đinh khít lại, lót len cao nguyên chần bông để nó không đông cứng dính vào người khi qua đèo. Các thợ cả lò rèn Shailagarh ký tên vào mặt trong cổ áo của từng chiếc.", "Baju zirah dari cincin-cincin besi hitam halus yang dikeling rapat, berlapis wol dataran tinggi berjahit sehingga tidak membeku menempel di badanmu saat melintasi celah gunung. Para empu tempa Shailagarh menandatangani setiap zirah di bagian dalam kerahnya.", "เสื้อเกราะจากห่วงเหล็กดำละเอียดตอกหมุดปิดสนิท บุด้วยขนแกะที่ราบสูงเย็บนวม จะได้ไม่แข็งติดตัวคุณยามข้ามช่องเขา ช่างตีเหล็กใหญ่แห่งไศลครห์ลงชื่อไว้ด้านในปกคอทุกตัว", "Perçinle kapatılmış ince kara demir halkalardan bir zırh; geçitlerde üstüne donup yapışmasın diye kapitone yayla yünüyle astarlanmış. Shailagarh'ın demirci ustaları her birini yakasının içinden imzalar.", "Una cota de finos anillos de hierro negro remachados, forrada de lana acolchada de las tierras altas para que no se te congele encima en los pasos. Los maestros forjadores de Shailagarh firman cada una por dentro del cuello.", "Uma cota de finos anéis de ferro negro rebitados, forrada com lã acolchoada das terras altas para não congelar grudada em você nos desfiladeiros. Os mestres forjadores de Shailagarh assinam cada uma por dentro da gola.", "Кольчуга из мелких клёпаных колец чёрного железа, подбитая стёганой горской шерстью, чтобы не примерзала к телу на перевалах. Мастера-кузнецы Шайлагарха подписывают каждую изнутри ворота.", "Кольчуга з дрібних клепаних кілець чорного заліза, підбита стьобаною гірською вовною, щоб не примерзала до тіла на перевалах. Майстри-ковалі Шайлагарха підписують кожну зсередини коміра."],
  "A saffron turban tied the Tirthali way, half Kharaveth and half Meghavan, which is to say tied twice.": ["ティルタリ流に巻いたサフラン色のターバン。半分カラヴェス風、半分メガヴァン風、つまり二度巻いてある。", "티르탈리 식으로 맨 사프란색 터번. 반은 카라베스 식, 반은 메가반 식이니, 말하자면 두 번 맨 것이다.", "一条番红花色的头巾,按提尔塔利的缠法缠成:一半卡拉维斯式,一半梅加万式——也就是说,缠了两遍。", "一條番紅花色的頭巾,按提爾塔利的纏法纏成:一半卡拉維斯式,一半梅加萬式——也就是說,纏了兩遍。", "Một chiếc khăn xếp màu nghệ quấn theo kiểu Tirthali, nửa Kharaveth nửa Meghavan, nghĩa là quấn hai lần.", "Sorban kunyit yang diikat dengan cara Tirthali, setengah Kharaveth dan setengah Meghavan, alias diikat dua kali.", "ผ้าโพกหัวสีหญ้าฝรั่นที่พันแบบตีรถลี ครึ่งหนึ่งแบบคาราเวธ อีกครึ่งแบบเมฆาวัน หรือพูดง่าย ๆ คือพันสองรอบ", "Tirthali usulü bağlanmış safran rengi bir sarık; yarı Kharaveth, yarı Meghavan, yani iki kez bağlanmış.", "Un turbante azafrán atado a la manera de Tirthali, mitad Kharaveth y mitad Meghavan, es decir, atado dos veces.", "Um turbante cor de açafrão amarrado à moda de Tirthali, metade Kharaveth e metade Meghavan, ou seja, amarrado duas vezes.", "Шафрановый тюрбан, повязанный, как принято в Тиртхали: наполовину на манер Харавета, наполовину на манер Мегхавана, то есть повязанный дважды.", "Шафрановий тюрбан, пов'язаний, як заведено в Тіртхалі: наполовину на манер Харавета, наполовину на манер Мегхавана, тобто пов'язаний двічі."],
  "A long cotton shirt to the knee, red-stitched at the collar, cool in the dry months and quick to dry in the wet.": ["膝丈の長い木綿のシャツ。襟に赤い縫い取りがあり、乾季には涼しく、雨季にはすぐ乾く。", "무릎까지 오는 긴 무명 셔츠. 옷깃에 붉은 바느질이 있고, 건기에는 시원하고 우기에는 빨리 마른다.", "一件长及膝盖的棉布长衫,领口缝着红线,旱季穿着凉快,雨季干得也快。", "一件長及膝蓋的棉布長衫,領口縫著紅線,旱季穿著涼快,雨季乾得也快。", "Một chiếc áo bông dài tới gối, cổ áo khâu chỉ đỏ, mát vào những tháng khô và mau khô vào mùa mưa.", "Kemeja katun panjang sampai lutut, berjahit merah di kerah, sejuk di bulan-bulan kering dan cepat kering di musim hujan.", "เสื้อผ้าฝ้ายยาวถึงเข่า ปกเย็บด้ายแดง ใส่เย็นสบายในเดือนแล้ง และแห้งไวในหน้าฝน", "Dize kadar uzanan, yakası kırmızı dikişli uzun pamuklu bir gömlek; kurak aylarda serin tutar, yağışlı aylarda çabuk kurur.", "Una camisa larga de algodón hasta la rodilla, con pespunte rojo en el cuello, fresca en los meses secos y rápida en secarse en los húmedos.", "Uma camisa longa de algodão até o joelho, com costura vermelha na gola, fresca nos meses secos e rápida para secar nos chuvosos.", "Длинная хлопковая рубаха до колен с красной строчкой по вороту: прохладная в сухие месяцы и быстро сохнущая в дождливые.", "Довга бавовняна сорочка до колін із червоною строчкою на комірі: прохолодна в сухі місяці й швидко висихає в дощові."],
  "Loose trousers rolled to the knee, for the ford, and rolled to the ankle, for everywhere else.": ["ゆったりしたズボン。浅瀬を渡るときは膝まで、それ以外はどこでも足首まで裾をまくる。", "헐렁한 바지. 여울을 건널 때는 무릎까지, 그 밖의 모든 곳에서는 발목까지 걷어 올린다.", "宽松的长裤,过浅滩时卷到膝盖,去别的地方就卷到脚踝。", "寬鬆的長褲,過淺灘時捲到膝蓋,去別的地方就捲到腳踝。", "Quần rộng xắn tới gối khi lội qua bến, và xắn tới mắt cá ở mọi nơi khác.", "Celana longgar yang digulung sampai lutut untuk menyeberang, dan sampai mata kaki untuk ke mana pun selain itu.", "กางเกงหลวม ๆ พับขาถึงเข่าเวลาลุยข้ามท่า และพับถึงข้อเท้าเวลาไปที่อื่นทุกแห่ง", "Geçit için dize, geri kalan her yer için bileğe kadar kıvrılan bol bir şalvar.", "Pantalones holgados remangados hasta la rodilla, para el vado, y hasta el tobillo, para todo lo demás.", "Calças folgadas arregaçadas até o joelho, para o vau, e até o tornozelo, para todo o resto.", "Свободные штаны, подвёрнутые до колен — для брода, и до щиколоток — для всего остального.", "Вільні штани, підкочені до колін — для броду, і до кісточок — для всього іншого."],
  "A wide shawl of undyed wool, worn over the head against Kharaveth's dust or Meghavan's rain, depending on which way you're going.": ["染めていない羊毛の幅広のショール。行く方向次第で、カラヴェスの砂塵よけにも、メガヴァンの雨よけにも頭からかぶる。", "염색하지 않은 양모로 짠 넓은 숄. 어느 쪽으로 가느냐에 따라 카라베스의 먼지나 메가반의 비를 막으려고 머리에 쓴다.", "一条本色羊毛的宽披肩,披在头上,挡卡拉维斯的沙尘或梅加万的雨,看你往哪边走。", "一條本色羊毛的寬披肩,披在頭上,擋卡拉維斯的沙塵或梅加萬的雨,看你往哪邊走。", "Một chiếc khăn choàng rộng bằng len mộc, trùm lên đầu để chắn bụi của Kharaveth hay mưa của Meghavan, tùy bạn đang đi hướng nào.", "Selendang lebar dari wol tanpa celup, dipakai menutupi kepala untuk menahan debu Kharaveth atau hujan Meghavan, tergantung ke arah mana kau pergi.", "ผ้าคลุมผืนกว้างทำจากขนแกะไม่ย้อมสี คลุมหัวไว้กันฝุ่นของคาราเวธหรือฝนของเมฆาวัน แล้วแต่ว่าคุณกำลังไปทางไหน", "Boyanmamış yünden geniş bir şal; hangi yöne gittiğine bağlı olarak Kharaveth'in tozuna ya da Meghavan'ın yağmuruna karşı başa örtülür.", "Un chal ancho de lana sin teñir, que se lleva sobre la cabeza contra el polvo de Kharaveth o la lluvia de Meghavan, según hacia dónde vayas.", "Um xale largo de lã crua, usado sobre a cabeça contra a poeira de Kharaveth ou a chuva de Meghavan, dependendo de para onde você vai.", "Широкая шаль из некрашеной шерсти; её накидывают на голову от пыли Харавета или от дождей Мегхавана — смотря в какую сторону идёшь.", "Широка шаль із нефарбованої вовни; її накидають на голову від пилу Харавета чи від дощів Мегхавана — залежно від того, в який бік ідеш."],
  "Leather sandals with a toe ring, soaked and dried so many times they've taken the shape of the ford.": ["足指を通す輪のついた革のサンダル。何度も濡れては乾いたせいで、浅瀬の形になってしまった。", "발가락 고리가 달린 가죽 샌들. 하도 젖었다 말랐다를 반복해서 여울의 모양을 닮아 버렸다.", "一双带趾环的皮凉鞋,泡湿又晾干了太多回,已经长成了浅滩的形状。", "一雙帶趾環的皮涼鞋,泡濕又晾乾了太多回,已經長成了淺灘的形狀。", "Đôi dép da có vòng xỏ ngón, ướt rồi khô nhiều lần đến nỗi đã mang hình dạng của bến lội.", "Sandal kulit dengan cincin jempol, sudah basah dan kering berkali-kali sampai bentuknya mengikuti bentuk penyeberangan.", "รองเท้าแตะหนังมีห่วงคล้องนิ้วเท้า เปียกแล้วแห้งมานับครั้งไม่ถ้วนจนกลายเป็นรูปทรงของท่าข้ามไปแล้ว", "Parmak halkalı deri sandaletler; o kadar çok ıslanıp kurumuşlar ki geçidin şeklini almışlar.", "Sandalias de cuero con anilla para el dedo, empapadas y secadas tantas veces que han tomado la forma del vado.", "Sandálias de couro com anel para o dedo, encharcadas e secas tantas vezes que tomaram a forma do vau.", "Кожаные сандалии с кольцом для пальца, столько раз промокавшие и высыхавшие, что приняли форму брода.", "Шкіряні сандалі з кільцем для пальця, що стільки разів намокали й висихали, що набули форми броду."],
  "A white turban with a blue fold, Ilavarta's colours: the white of the lotus, the blue of a kept tank.": ["青いひだの入った白いターバン。イラヴァルタの色だ。白は蓮の白、青は手入れの行き届いた貯水池の青。", "푸른 주름이 한 겹 들어간 흰 터번. 일라바르타의 색이다. 흰색은 연꽃의 흰색, 푸른색은 잘 관리된 저수지의 푸른색.", "一条白头巾,带一道蓝色褶,是伊拉瓦塔的颜色:莲花的白,照料得当的水池的蓝。", "一條白頭巾,帶一道藍色褶,是伊拉瓦塔的顏色:蓮花的白,照料得當的水池的藍。", "Một chiếc khăn xếp trắng có một nếp gấp xanh lam, màu của Ilavarta: trắng của hoa sen, xanh của hồ chứa được chăm nom.", "Sorban putih dengan satu lipatan biru, warna Ilavarta: putihnya teratai, birunya telaga yang terawat.", "ผ้าโพกหัวสีขาวมีจีบสีน้ำเงิน สีประจำอิลาวรรตะ ขาวดั่งดอกบัว น้ำเงินดั่งสระที่ได้รับการดูแล", "Mavi kıvrımlı beyaz bir sarık, Ilavarta'nın renkleri: nilüferin beyazı, bakımlı bir havuzun mavisi.", "Un turbante blanco con un pliegue azul, los colores de Ilavarta: el blanco del loto, el azul de un estanque bien cuidado.", "Um turbante branco com uma dobra azul, as cores de Ilavarta: o branco do lótus, o azul de um tanque bem cuidado.", "Белый тюрбан с синей складкой — цвета Илаварты: белизна лотоса, синева ухоженного пруда.", "Білий тюрбан із синьою складкою — кольори Ілаварти: білизна лотоса, синява доглянутого ставу."],
  "A long coat flaring from the waist, tank blue, tied at the side. Sarovan's officials wear it to court and to the ghats at dawn.": ["腰から裾広がりになった長い上着。貯水池の青で、脇で紐を結ぶ。サロヴァンの役人たちはこれを着て宮廷にも、夜明けのガートにも行く。", "허리에서부터 퍼지는 긴 겉옷으로, 저수지빛 푸른색에 옆에서 끈으로 묶는다. 사로반의 관리들은 이것을 입고 궁정에도, 새벽의 가트에도 간다.", "一件从腰部散开的长袍,水池蓝,在侧边系带。萨罗万的官员穿着它上朝,也穿着它在黎明时去河阶。", "一件從腰部散開的長袍,水池藍,在側邊繫帶。薩羅萬的官員穿著它上朝,也穿著它在黎明時去河階。", "Một chiếc áo dài xòe từ eo, màu xanh hồ chứa, buộc dây bên hông. Quan chức ở Sarovan mặc nó lên triều và xuống bậc ghat lúc bình minh.", "Mantel panjang yang mengembang dari pinggang, berwarna biru telaga, diikat di samping. Para pejabat Sarovan memakainya ke istana dan ke tangga ghat saat fajar.", "เสื้อคลุมยาวบานออกจากเอว สีน้ำสระ ผูกเชือกด้านข้าง ขุนนางแห่งสโรวันสวมไปเข้าเฝ้าในราชสำนัก และไปท่าน้ำยามรุ่งอรุณ", "Belden itibaren genişleyen, havuz mavisi, yandan bağlanan uzun bir kaftan. Sarovan'ın memurları onu hem saraya hem de şafakta gat basamaklarına giyer.", "Una casaca larga que se abre desde la cintura, azul estanque, atada al costado. Los funcionarios de Sarovan la llevan a la corte y a los ghats al amanecer.", "Um casaco longo que se abre a partir da cintura, azul-tanque, amarrado do lado. Os funcionários de Sarovan o usam na corte e nos ghats ao amanhecer.", "Длинный кафтан, расширяющийся от талии, цвета пруда, с завязками сбоку. Чиновники Сарована носят его и ко двору, и на гаты на рассвете.", "Довгий каптан, що розширюється від талії, кольору ставу, із зав'язками збоку. Урядовці Сарована носять його і до двору, і на гати на світанку."],
  "A length of white cotton wrapped and pleated at the waist, a gold thread along its border.": ["腰に巻いてひだを寄せた白い木綿の長布。縁に金糸が一本通っている。", "허리에 감고 주름을 잡은 흰 무명천 한 필. 가장자리를 따라 금실이 한 줄 들어가 있다.", "一段白棉布,裹在腰间打出褶子,边缘织着一道金线。", "一段白棉布,裹在腰間打出褶子,邊緣織著一道金線。", "Một tấm vải bông trắng quấn quanh eo và xếp ly, dọc mép có một đường chỉ vàng.", "Sehelai kain katun putih yang dililit dan dilipit di pinggang, dengan benang emas di sepanjang pinggirannya.", "ผ้าฝ้ายสีขาวผืนยาว พันรอบเอวและจับจีบ มีด้ายทองเดินตามริมผ้า", "Bele sarılıp pililenmiş bir boy beyaz pamuklu kumaş; kenarı boyunca bir altın iplik.", "Un largo de algodón blanco envuelto y plisado en la cintura, con un hilo de oro a lo largo del borde.", "Um corte de algodão branco enrolado e pregueado na cintura, com um fio de ouro ao longo da barra.", "Отрез белого хлопка, обёрнутый вокруг пояса и уложенный складками, с золотой нитью по краю.", "Відріз білої бавовни, обгорнутий довкола пояса й укладений складками, із золотою ниткою по краю."],
  "A fine white shawl worked with pink lotuses along the hem, as the Queen's household wears on festival days.": ["裾に沿って桃色の蓮を刺繍した上質な白いショール。祭りの日に女王の側仕えたちがまとうものだ。", "단을 따라 분홍 연꽃을 수놓은 고운 흰 숄. 축제날 여왕의 궁인들이 두르는 것이다.", "一条精致的白披肩,下摆绣着粉色莲花,女王的内廷在节庆日就披这种。", "一條精緻的白披肩,下襬繡著粉色蓮花,女王的內廷在節慶日就披這種。", "Một chiếc khăn choàng trắng mịn thêu hoa sen hồng dọc gấu, như người trong cung của Nữ hoàng vẫn khoác vào ngày lễ hội.", "Selendang putih halus bersulam teratai merah muda di sepanjang kelimannya, seperti yang dikenakan rombongan istana Ratu pada hari-hari perayaan.", "ผ้าคลุมไหล่สีขาวเนื้อดี ปักลายบัวสีชมพูตามชายผ้า แบบที่ข้าราชบริพารของราชินีห่มในวันเทศกาล", "Eteği boyunca pembe nilüferler işlenmiş ince beyaz bir şal; Kraliçe'nin saray halkı bayram günlerinde böyle giyer.", "Un chal blanco y fino bordado con lotos rosas a lo largo del borde, como los que lleva la casa de la Reina en los días de fiesta.", "Um xale branco e fino bordado com lótus cor-de-rosa ao longo da barra, como a casa da Rainha usa nos dias de festa.", "Тонкая белая шаль с розовыми лотосами, вышитыми по краю, — такие носят приближённые королевы в праздничные дни.", "Тонка біла шаль із рожевими лотосами, вишитими по краю, — такі носять наближені королеви у святкові дні."],
  "Soft leather slippers with turned-up toes, left at the top of the ghat steps by everyone who bathes.": ["つま先が反り返った柔らかな革のスリッパ。沐浴する者は皆、これをガートの石段のいちばん上に脱いでいく。", "앞코가 위로 말린 부드러운 가죽 슬리퍼. 목욕하러 가는 사람은 모두 가트 계단 맨 위에 벗어 둔다.", "一双软皮便鞋,鞋尖上翘。每个下水沐浴的人都会把它留在河阶顶上。", "一雙軟皮便鞋,鞋尖上翹。每個下水沐浴的人都會把它留在河階頂上。", "Đôi dép da mềm mũi cong vểnh, ai xuống tắm cũng để lại trên đầu bậc ghat.", "Selop kulit lembut berujung melengkung ke atas, yang ditinggalkan di puncak tangga ghat oleh siapa saja yang mandi.", "รองเท้าหนังนุ่มปลายงอน ทุกคนที่ลงอาบน้ำจะถอดทิ้งไว้ที่บันไดขั้นบนสุดของท่าน้ำ", "Burnu kalkık yumuşak deri terlikler; yıkanan herkes onları gat basamaklarının en üstünde bırakır.", "Babuchas de cuero blando con la punta vuelta hacia arriba, que todo el que se baña deja en lo alto de los escalones del ghat.", "Chinelos de couro macio com a ponta virada para cima, deixados no alto dos degraus do ghat por todos que se banham.", "Мягкие кожаные туфли с загнутыми носами; каждый, кто идёт купаться, оставляет их наверху ступеней гата.", "М'які шкіряні капці із загнутими носами; кожен, хто йде купатися, лишає їх нагорі сходів гату."],
  "A round wool cap, red with an undyed band, folded down over the ears when the wind comes over the passes.": ["染めていない帯が入った赤い丸い毛糸帽。峠を越えて風が吹きつけると、折り下げて耳を覆う。", "염색하지 않은 띠를 두른 붉고 둥근 양모 모자. 고개 너머로 바람이 불어오면 귀까지 접어 내린다.", "一顶圆形的红色羊毛帽,带一圈本色的帽边,风从山口吹来时就翻下来盖住耳朵。", "一頂圓形的紅色羊毛帽,帶一圈本色的帽邊,風從山口吹來時就翻下來蓋住耳朵。", "Một chiếc mũ len tròn màu đỏ có viền len mộc, kéo xuống trùm tai khi gió thổi qua đèo.", "Topi wol bundar berwarna merah dengan pita tanpa celup, dilipat turun menutupi telinga saat angin datang melewati celah gunung.", "หมวกขนสัตว์ทรงกลมสีแดงคาดแถบไม่ย้อมสี พับลงมาปิดหูเมื่อลมพัดข้ามช่องเขามา", "Boyanmamış bir şeridi olan kırmızı, yuvarlak bir yün başlık; rüzgâr geçitlerin üstünden esince kulakların üstüne indirilir.", "Un gorro redondo de lana, rojo con una franja sin teñir, que se baja sobre las orejas cuando el viento llega por los pasos.", "Um gorro redondo de lã, vermelho com uma faixa crua, dobrado sobre as orelhas quando o vento vem pelos desfiladeiros.", "Круглая шерстяная шапка, красная, с некрашеной полосой; её отворачивают на уши, когда с перевалов приходит ветер.", "Кругла вовняна шапка, червона, з нефарбованою смугою; її відгортають на вуха, коли з перевалів налітає вітер."],
  "A thick coat of highland wool, belted, the right side crossing over the left. It smells of sheep in the rain, which is honest of it.": ["高地の羊毛で作った厚手の上着。帯で締め、右の身頃を左の上に重ねる。雨に濡れた羊の匂いがするが、それは正直というものだ。", "고원 양모로 만든 두툼한 외투로, 허리띠를 매고 오른쪽 섶이 왼쪽 위로 여며진다. 비 맞은 양 냄새가 나는데, 솔직해서 좋다.", "一件厚实的高地羊毛大衣,系腰带,右襟压在左襟上。闻起来像淋了雨的羊,倒也诚实。", "一件厚實的高地羊毛大衣,繫腰帶,右襟壓在左襟上。聞起來像淋了雨的羊,倒也誠實。", "Một chiếc áo khoác dày bằng len cao nguyên, thắt đai, vạt phải đè lên vạt trái. Nó có mùi cừu dầm mưa, kể ra cũng thật thà.", "Mantel tebal dari wol dataran tinggi, bersabuk, sisi kanan menyilang di atas sisi kiri. Baunya seperti domba kehujanan, dan itu jujur sekali.", "เสื้อโค้ตหนาทำจากขนแกะที่ราบสูง คาดเข็มขัด ป้ายด้านขวาทับด้านซ้าย มีกลิ่นแกะตากฝน ซึ่งก็นับว่าซื่อตรงดี", "Yayla yününden kalın, kemerli bir palto; sağ yakası solun üstüne kapanır. Yağmur yemiş koyun gibi kokar, ki bu onun dürüstlüğüdür.", "Un abrigo grueso de lana de las tierras altas, con cinturón, el lado derecho cruzado sobre el izquierdo. Huele a oveja bajo la lluvia, lo cual dice mucho de su honradez.", "Um casaco grosso de lã das terras altas, com cinto, o lado direito cruzando sobre o esquerdo. Cheira a ovelha na chuva, o que é honesto da parte dele.", "Толстый кафтан из горской шерсти, подпоясанный, правая пола запахнута на левую. Пахнет овцой под дождём, и в этом есть своя честность.", "Товстий каптан із гірської вовни, підперезаний, права пола запнута на ліву. Пахне вівцею під дощем, і в цьому є своя чесність."],
  "Heavy woollen trousers tucked into the boot, patched at the knees by somebody who climbs.": ["ブーツに裾を入れて履く厚手のウールのズボン。膝には、山を登る誰かが当てた継ぎがある。", "장화 속에 밀어 넣어 입는 두꺼운 모직 바지. 무릎에는 산을 오르는 누군가가 덧댄 천이 붙어 있다.", "一条厚重的羊毛长裤,裤脚塞进靴子里,膝盖上打着补丁——补它的人是爬山的。", "一條厚重的羊毛長褲,褲腳塞進靴子裡,膝蓋上打著補丁——補它的人是爬山的。", "Quần len dày nhét vào ống ủng, đầu gối có miếng vá của ai đó hay leo núi.", "Celana wol tebal yang diselipkan ke dalam sepatu bot, ditambal di bagian lutut oleh seseorang yang suka mendaki.", "กางเกงขนสัตว์หนา ๆ สอดปลายขาไว้ในรองเท้าบูต มีรอยปะที่เข่าโดยใครสักคนที่ปีนเขา", "Çizmenin içine sokulan kalın yün bir pantolon; dizlerini tırmanan biri yamamış.", "Pantalones gruesos de lana metidos en la bota, remendados en las rodillas por alguien que escala.", "Calças grossas de lã enfiadas na bota, remendadas nos joelhos por alguém que escala.", "Тяжёлые шерстяные штаны, заправленные в сапоги, с заплатами на коленях — их ставил кто-то, кто лазит по горам.", "Важкі вовняні штани, заправлені в чоботи, із латками на колінах — їх ставив хтось, хто лазить горами."],
  "A red blanket striped in black, worn as a cloak by day and slept under by night. Shailagarh's sentries are never without one.": ["黒い縞の入った赤い毛布。昼はマントとして羽織り、夜はかけて眠る。シャイラガルの歩哨は決してこれを手放さない。", "검은 줄무늬가 들어간 붉은 담요. 낮에는 망토로 두르고 밤에는 덮고 잔다. 샤일라가르의 보초들은 이것 없이 다니는 법이 없다.", "一条带黑条纹的红毯子,白天当斗篷披,晚上盖着睡。沙伊拉加尔的哨兵从不离身。", "一條帶黑條紋的紅毯子,白天當斗篷披,晚上蓋著睡。沙伊拉加爾的哨兵從不離身。", "Một tấm chăn đỏ kẻ sọc đen, ban ngày khoác làm áo choàng, ban đêm đắp mà ngủ. Lính gác Shailagarh không bao giờ thiếu nó.", "Selimut merah bergaris hitam, dipakai sebagai jubah di siang hari dan untuk berselimut di malam hari. Para penjaga Shailagarh tak pernah tanpa selimut ini.", "ผ้าห่มสีแดงลายทางดำ กลางวันใช้คลุมแทนเสื้อคลุม กลางคืนใช้ห่มนอน ยามรักษาการณ์แห่งไศลครห์ไม่เคยขาดมันสักผืน", "Siyah çizgili kırmızı bir battaniye; gündüz pelerin gibi giyilir, gece altında uyunur. Shailagarh'ın nöbetçileri onsuz asla dolaşmaz.", "Una manta roja con rayas negras, que se lleva como capa de día y bajo la que se duerme de noche. Los centinelas de Shailagarh nunca van sin una.", "Um cobertor vermelho listrado de preto, usado como capa de dia e para dormir debaixo à noite. As sentinelas de Shailagarh nunca andam sem um.", "Красное одеяло в чёрную полоску: днём его носят как плащ, ночью под ним спят. Часовые Шайлагарха без него не ходят.", "Червона ковдра в чорну смужку: удень її носять як плащ, уночі під нею сплять. Вартові Шайлагарха без неї не ходять."],
  "Felt boots with leather soles, laced to the shin. Good on snow, better on scree.": ["革底のフェルトのブーツで、すねまで紐で締める。雪の上でもいいが、ガレ場ならもっといい。", "가죽 밑창을 댄 펠트 장화로, 정강이까지 끈을 맨다. 눈 위에서도 좋고, 너덜길에서는 더 좋다.", "皮底毡靴,鞋带系到小腿。走雪地不错,走碎石坡更好。", "皮底氈靴,鞋帶繫到小腿。走雪地不錯,走碎石坡更好。", "Ủng nỉ đế da, buộc dây tới ống chân. Đi tuyết thì tốt, đi đá vụn còn tốt hơn.", "Sepatu bot laken bersol kulit, bertali sampai tulang kering. Bagus di salju, lebih bagus lagi di lereng berbatu lepas.", "รองเท้าบูตสักหลาดพื้นหนัง ผูกเชือกถึงหน้าแข้ง เดินบนหิมะก็ดี บนลานหินร่วนยิ่งดีกว่า", "Deri tabanlı, incik hizasına kadar bağcıklı keçe çizmeler. Karda iyi, taşlı yamaçta daha iyi.", "Botas de fieltro con suela de cuero, atadas hasta la espinilla. Buenas en la nieve, mejores en el pedregal.", "Botas de feltro com sola de couro, amarradas até a canela. Boas na neve, melhores no cascalho.", "Войлочные сапоги на кожаной подошве со шнуровкой до голени. Хороши на снегу, ещё лучше на осыпи.", "Повстяні чоботи на шкіряній підошві зі шнурівкою до гомілки. Добрі на снігу, ще кращі на осипі."],
  "A wide hat of woven palm, painted inside in the seven colours of the League, so the wearer is shaded by all of them at once.": ["椰子の葉で編んだつばの広い帽子。内側は同盟の七色に塗られていて、かぶる者は七つすべての陰に同時に入れる。", "야자잎을 엮어 만든 챙 넓은 모자. 안쪽이 동맹의 일곱 색으로 칠해져 있어, 쓴 사람은 일곱 모두의 그늘을 한꺼번에 받는다.", "一顶棕榈叶编的宽檐帽,帽里涂着同盟的七种颜色,戴的人就同时受到七家的荫庇。", "一頂棕櫚葉編的寬簷帽,帽裡塗著同盟的七種顏色,戴的人就同時受到七家的蔭庇。", "Một chiếc nón rộng vành đan bằng lá cọ, mặt trong sơn bảy màu của Liên minh, để người đội được tất cả che bóng cùng một lúc.", "Topi lebar dari anyaman daun palem, bagian dalamnya dicat tujuh warna Liga, sehingga pemakainya dinaungi oleh ketujuhnya sekaligus.", "หมวกปีกกว้างสานจากใบปาล์ม ด้านในทาเจ็ดสีของสันนิบาต ผู้สวมจึงได้ร่มเงาจากทั้งเจ็ดพร้อมกัน", "Örülmüş palmiye yaprağından geniş bir şapka; içi Birlik'in yedi rengine boyanmış, böylece takan kişi hepsinin gölgesinde birden kalır.", "Un sombrero ancho de palma trenzada, pintado por dentro con los siete colores de la Liga, para que quien lo lleve quede a la sombra de todos a la vez.", "Um chapéu largo de palha de palmeira trançada, pintado por dentro nas sete cores da Liga, para que quem o usa fique à sombra de todas de uma vez.", "Широкая шляпа из плетёной пальмы, изнутри раскрашенная в семь цветов Лиги, чтобы её владельца осеняли все семь сразу.", "Широкий капелюх із плетеної пальми, зсередини розфарбований у сім кольорів Ліги, щоб того, хто його носить, затіняли всі сім одразу."],
  "A wrap coat tied at the chest with cords, worn by the League's delegates. The cords are tied differently for each of the seven, and arguments start there.": ["胸元を紐で結ぶ打ち合わせの上着で、同盟の代表たちが着る。紐の結び方は七者ごとに違い、議論はまずそこから始まる。", "가슴께를 끈으로 여미는 여밈 외투로, 동맹의 대표들이 입는다. 끈 매는 법이 일곱 곳마다 달라서, 언쟁은 거기서부터 시작된다.", "一件在胸前用系绳系合的裹襟外袍,同盟的代表们都穿。七家的系绳各有各的系法,争吵就从这儿开始。", "一件在胸前用繫繩繫合的裹襟外袍,同盟的代表們都穿。七家的繫繩各有各的繫法,爭吵就從這兒開始。", "Một chiếc áo quấn vạt buộc dây ở ngực, do các đại biểu của Liên minh mặc. Mỗi bên trong bảy bên buộc dây một kiểu, và cãi vã bắt đầu từ đó.", "Mantel lilit yang diikat di dada dengan tali, dipakai para utusan Liga. Talinya diikat dengan cara berbeda untuk masing-masing dari ketujuhnya, dan perdebatan dimulai dari situ.", "เสื้อคลุมแบบป้ายผูกเชือกที่หน้าอก ผู้แทนของสันนิบาตสวมใส่ เชือกผูกต่างกันไปตามแต่ละฝ่ายในเจ็ดฝ่าย และการโต้เถียงก็เริ่มตรงนั้น", "Göğüste kordonlarla bağlanan, Birlik delegelerinin giydiği kruvaze bir kaftan. Kordonlar yedisinin her biri için farklı bağlanır ve tartışmalar oradan başlar.", "Una casaca cruzada atada al pecho con cordones, que llevan los delegados de la Liga. Los cordones se atan de forma distinta para cada uno de los siete, y ahí empiezan las discusiones.", "Um casaco transpassado amarrado no peito com cordões, usado pelos delegados da Liga. Os cordões são amarrados de um jeito diferente para cada um dos sete, e as discussões começam aí.", "Запашной кафтан, завязанный на груди шнурами, — его носят делегаты Лиги. У каждого из семи шнуры завязываются по-своему, и споры начинаются уже с этого.", "Запашний каптан, зав'язаний на грудях шнурами, — його носять делегати Ліги. У кожного із семи шнури зав'язуються по-своєму, і суперечки починаються вже з цього."],
  "Fitted cotton trousers gathered at the ankle, for long walks between towns that disagree with each other.": ["足首ですぼめた、体に合う木綿のズボン。互いに意見の合わない町から町への長い道のりのためのもの。", "발목에서 모아지는 몸에 맞는 무명 바지. 서로 의견이 맞지 않는 마을들 사이를 오래 걸을 때 입는다.", "合身的棉布长裤,裤脚在脚踝处收拢,适合在彼此意见不合的城镇之间长途跋涉。", "合身的棉布長褲,褲腳在腳踝處收攏,適合在彼此意見不合的城鎮之間長途跋涉。", "Quần bông vừa người, túm ở mắt cá, để đi bộ đường dài giữa những thị trấn chẳng đồng ý với nhau.", "Celana katun pas badan yang mengerut di pergelangan kaki, untuk perjalanan jauh antara kota-kota yang tak pernah sepakat satu sama lain.", "กางเกงผ้าฝ้ายเข้ารูป รวบปลายขาที่ข้อเท้า สำหรับเดินทางไกลระหว่างเมืองที่ไม่เคยเห็นพ้องกัน", "Bilekte büzgülü, vücuda oturan pamuklu bir pantolon; birbiriyle anlaşamayan kasabalar arasındaki uzun yürüyüşler için.", "Pantalones ceñidos de algodón fruncidos en el tobillo, para largas caminatas entre pueblos que no se ponen de acuerdo entre sí.", "Calças justas de algodão franzidas no tornozelo, para longas caminhadas entre cidades que discordam umas das outras.", "Облегающие хлопковые штаны, собранные у щиколотки, — для долгих переходов между городами, которые друг с другом не согласны.", "Облягаючі бавовняні штани, зібрані біля кісточок, — для довгих переходів між містами, що одне з одним не згодні."],
  "A purple mantle with seven gold bars at the hem, one for each parasol. A Speaker wears it for a year, then gives it back.": ["裾に七本の金の帯が入った紫のマント。一本が日傘ひとつ分だ。議長は一年間これをまとい、それから返す。", "단에 금색 줄 일곱 개가 들어간 보라색 망토. 일산 하나에 한 줄씩이다. 의장은 이것을 일 년 동안 두르고, 그다음 돌려준다.", "一件紫色披风,下摆有七道金条纹,每道代表一顶华盖。议长披它一年,然后交还。", "一件紫色披風,下襬有七道金條紋,每道代表一頂華蓋。議長披它一年,然後交還。", "Một chiếc áo choàng tím có bảy vạch vàng ở gấu, mỗi vạch cho một chiếc lọng. Phát ngôn nhân mặc nó một năm, rồi trả lại.", "Mantel ungu dengan tujuh garis emas di keliman, satu untuk setiap payung. Seorang Juru Bicara memakainya selama setahun, lalu mengembalikannya.", "เสื้อคลุมสีม่วงมีแถบทองเจ็ดแถบที่ชาย แถบละหนึ่งฉัตร ประธานสวมมันหนึ่งปี แล้วจึงคืนไป", "Eteğinde yedi altın şerit bulunan mor bir cüppe; her şemsiye için bir tane. Bir Sözcü onu bir yıl giyer, sonra geri verir.", "Un manto púrpura con siete franjas doradas en el borde, una por cada parasol. Un Portavoz lo lleva durante un año y luego lo devuelve.", "Um manto roxo com sete faixas douradas na barra, uma para cada para-sol. Um Porta-voz o usa por um ano e depois o devolve.", "Пурпурная мантия с семью золотыми полосами по подолу, по одной на каждый зонт. Глашатай носит её год, а потом возвращает.", "Пурпурова мантія із сімома золотими смугами по подолу, по одній на кожну парасоль. Речник носить її рік, а потім повертає."],
  "A soft cap of sea-green cotton with a long tail down the back, as the Archive's readers wear so the librarians can tell them from the merchants.": ["海緑色の木綿で作った柔らかい帽子で、背中に長い垂れがある。文書館の閲覧者がかぶるもので、司書たちが商人と見分けられるようにするためだ。", "등 뒤로 긴 꼬리가 늘어진 바다빛 초록 무명 모자. 서고의 열람자들이 쓰는데, 사서들이 상인과 구별할 수 있게 하기 위해서다.", "一顶海绿色的软棉帽,后面垂着一条长尾,档案馆的读者都戴,好让管理员把他们和商人区分开来。", "一頂海綠色的軟棉帽,後面垂著一條長尾,檔案館的讀者都戴,好讓管理員把他們和商人區分開來。", "Một chiếc mũ mềm bằng vải bông xanh ngọc biển, có đuôi dài thả xuống sau lưng; người đọc ở Văn khố đội nó để thủ thư phân biệt họ với dân buôn.", "Topi lembut dari katun hijau laut dengan ekor panjang menjuntai di punggung, dipakai para pembaca Arsip agar pustakawan bisa membedakan mereka dari pedagang.", "หมวกผ้าฝ้ายนุ่มสีเขียวน้ำทะเล มีหางยาวห้อยลงด้านหลัง ผู้อ่านของหอจดหมายเหตุสวมกัน บรรณารักษ์จะได้แยกพวกเขาออกจากพ่อค้า", "Arkadan uzun bir kuyruğu sarkan, deniz yeşili pamuktan yumuşak bir başlık; Arşiv'in okurları kütüphaneciler onları tüccarlardan ayırt edebilsin diye takar.", "Un gorro blando de algodón verde mar con una larga cola por la espalda, como el que llevan los lectores del Archivo para que los bibliotecarios los distingan de los mercaderes.", "Um gorro macio de algodão verde-mar com uma longa cauda nas costas, como os leitores do Arquivo usam para que os bibliotecários os distingam dos mercadores.", "Мягкая шапочка из хлопка цвета морской волны с длинным хвостом на спину; её носят читатели Архива, чтобы библиотекари отличали их от купцов.", "М'яка шапочка з бавовни кольору морської хвилі з довгим хвостом на спину; її носять читачі Архіву, щоб бібліотекарі відрізняли їх від купців."],
  "A robe of silk dyed the colour of good ink, a gold coin stitched at the collar: the Assembly of Ink and Coin, in one garment.": ["上等な墨の色に染めた絹の長衣。襟には金貨が一枚縫い付けてある。墨と貨幣の議会を、一着に仕立てたもの。", "좋은 먹 빛깔로 물들인 비단 장포. 깃에는 금화 한 닢이 꿰매어져 있다. 먹과 주화의 의회를 옷 한 벌에 담았다.", "一袭染成上好墨色的丝袍，领口缝着一枚金币：墨与币议会，尽在一件衣裳里。", "一襲染成上好墨色的絲袍，領口縫著一枚金幣：墨與幣議會，盡在一件衣裳裡。", "Một chiếc áo choàng lụa nhuộm màu mực tốt, cổ áo đính một đồng xu vàng: cả Hội đồng Mực và Xu gói gọn trong một bộ y phục.", "Jubah sutra yang dicelup warna tinta bagus, dengan sekeping koin emas terjahit di kerahnya: Majelis Tinta dan Koin dalam satu pakaian.", "เสื้อคลุมไหมย้อมสีหมึกชั้นดี มีเหรียญทองเย็บติดที่คอเสื้อ สภาหมึกและเหรียญทั้งสภาในอาภรณ์ชิ้นเดียว", "İyi mürekkep renginde boyanmış ipek bir cüppe, yakasına bir altın sikke dikilmiş: Mürekkep ve Sikke Meclisi, tek bir giyside.", "Una túnica de seda teñida del color de la buena tinta, con una moneda de oro cosida al cuello: la Asamblea de Tinta y Moneda en una sola prenda.", "Uma túnica de seda tingida da cor de uma boa tinta, com uma moeda de ouro costurada na gola: a Assembleia da Tinta e da Moeda numa só peça.", "Шёлковое одеяние цвета хороших чернил с золотой монетой, пришитой у ворота: Собрание Чернил и Монет в одном наряде.", "Шовкове вбрання кольору доброго чорнила із золотою монетою, пришитою біля коміра: Збори Чорнила й Монет в одному одязі."],
  "Wide white trousers, salt-stained to the knee, the free port's everyday wear.": ["膝まで塩の染みがついた、ゆったりした白いズボン。自由港の普段着だ。", "무릎까지 소금기 얼룩이 진 통 넓은 흰 바지. 자유항의 평상복이다.", "宽大的白色长裤，膝盖以下满是盐渍，是自由港的日常穿着。", "寬大的白色長褲，膝蓋以下滿是鹽漬，是自由港的日常穿著。", "Chiếc quần trắng ống rộng, loang vết muối tới đầu gối, đồ mặc thường ngày của thương cảng tự do.", "Celana putih lebar, bernoda garam sampai lutut, pakaian sehari-hari di pelabuhan bebas.", "กางเกงขายาวสีขาวทรงหลวม คราบเกลือเปื้อนถึงเข่า เป็นชุดลำลองประจำวันของเมืองท่าเสรี", "Dizlerine kadar tuz lekeli, bol beyaz pantolon; serbest limanın gündelik kıyafeti.", "Pantalones blancos y anchos, manchados de sal hasta la rodilla: la ropa de diario del puerto franco.", "Calças brancas e largas, manchadas de sal até o joelho: o traje do dia a dia do porto livre.", "Широкие белые штаны, в соляных разводах до колен, — повседневная одежда вольного порта.", "Широкі білі штани, у сольових плямах до колін, — повсякденний одяг вільного порту."],
  "A long stole of sea green, a pen worked in gold at one end and a coin at the other. You wear it with the pen in front if you're a scholar, the coin if you're a merchant, and both if you're the Provost.": ["海緑色の長い肩掛けで、片端に金糸で筆、もう片端に貨幣が刺繍されている。学者なら筆を前に、商人なら貨幣を前に、学頭なら両方を前にして掛ける。", "바다빛 초록의 긴 숄로, 한쪽 끝에는 금실로 붓이, 다른 쪽 끝에는 주화가 수놓여 있다. 학자라면 붓을 앞으로, 상인이라면 주화를 앞으로, 학장이라면 둘 다 앞으로 해서 두른다.", "一条海绿色的长披带，一端用金线绣着一支笔，另一端绣着一枚钱币。学者把笔那头搭在前面，商人把钱币那头搭在前面，院长则两头都搭在前面。", "一條海綠色的長披帶，一端用金線繡著一支筆，另一端繡著一枚錢幣。學者把筆那頭搭在前面，商人把錢幣那頭搭在前面，院長則兩頭都搭在前面。", "Một dải khăn choàng dài màu xanh nước biển, một đầu thêu ngòi bút bằng chỉ vàng, đầu kia thêu đồng xu. Học giả quàng để ngòi bút ra trước, thương nhân để đồng xu ra trước, còn Viện trưởng thì để cả hai.", "Selendang panjang hijau laut, bersulam pena emas di satu ujung dan koin di ujung lainnya. Cendekiawan memakainya dengan pena di depan, saudagar dengan koin di depan, dan Provos dengan keduanya di depan.", "ผ้าคล้องไหล่ยาวสีเขียวน้ำทะเล ปลายข้างหนึ่งปักรูปปากกาด้วยดิ้นทอง อีกข้างปักรูปเหรียญ ถ้าเป็นนักปราชญ์ก็คล้องให้ปากกาอยู่ด้านหน้า ถ้าเป็นพ่อค้าก็ให้เหรียญอยู่ด้านหน้า และถ้าเป็นอธิการก็ให้อยู่ด้านหน้าทั้งคู่", "Deniz yeşili uzun bir şal; bir ucuna altın iple kalem, öbür ucuna sikke işlenmiş. Âlimsen kalemi öne getirerek takarsın, tüccarsan sikkeyi, Rektörsen ikisini birden.", "Una larga estola verde mar, con una pluma bordada en oro en un extremo y una moneda en el otro. Se lleva con la pluma delante si eres erudito, con la moneda si eres mercader, y con las dos si eres la prebostesa.", "Uma longa estola verde-mar, com uma pena bordada a ouro numa ponta e uma moeda na outra. Usa-se com a pena na frente se você é estudioso, com a moeda se é mercador, e com as duas se é a reitora.", "Длинный палантин цвета морской волны: на одном конце золотом вышито перо, на другом — монета. Учёные носят его пером вперёд, купцы — монетой, а провост — и тем и другим.", "Довгий палантин кольору морської хвилі: на одному кінці золотом вишито перо, на другому — монету. Учені носять його пером наперед, купці — монетою, а провост — і тим, і тим."],
  "Cork-soled sandals that float, which is the point, in a port.": ["水に浮くコルク底のサンダル。港ではそこが肝心だ。", "물에 뜨는 코르크 밑창 샌들. 항구에서는 바로 그게 핵심이다.", "软木底的凉鞋，能浮在水上——在港口，要的就是这个。", "軟木底的涼鞋，能浮在水上——在港口，要的就是這個。", "Dép đế bần nổi được trên nước, mà ở bến cảng thì đó chính là mục đích.", "Sandal bersol gabus yang bisa mengapung, dan di pelabuhan, justru itulah gunanya.", "รองเท้าแตะพื้นไม้ก๊อกที่ลอยน้ำได้ ซึ่งในเมืองท่าก็คือจุดประสงค์ทั้งหมดของมัน", "Suda yüzen mantar tabanlı sandaletler; bir limanda bütün mesele de bu zaten.", "Sandalias con suela de corcho que flotan, que es de lo que se trata en un puerto.", "Sandálias de sola de cortiça que boiam, que é justamente a ideia num porto.", "Сандалии на пробковой подошве, которые не тонут, — в порту в этом весь смысл.", "Сандалі на корковій підошві, що не тонуть, — у порту в цьому весь сенс."],
  "A band of red seeds and green beads worn across the brow. Each pattern belongs to a family, and borrowing one is a conversation.": ["赤い木の実と緑のビーズを連ねて額に巻く帯。模様はそれぞれ一族のもので、借りるとなればひと話し合いになる。", "붉은 씨앗과 초록 구슬을 엮어 이마에 두르는 띠. 무늬마다 주인 가문이 있어서, 하나 빌리려면 이야기를 꽤 나눠야 한다.", "用红籽和绿珠串成的带子，横系在额前。每种花纹都属于一个家族，想借一条，得先好好谈一谈。", "用紅籽和綠珠串成的帶子，橫繫在額前。每種花紋都屬於一個家族，想借一條，得先好好談一談。", "Một dải hạt đỏ và cườm xanh đeo ngang trán. Mỗi hoa văn thuộc về một dòng họ, và muốn mượn một cái thì phải nói chuyện một hồi.", "Ikat dari biji merah dan manik hijau yang dikenakan melintang di dahi. Setiap pola milik satu keluarga, dan meminjamnya berarti harus bicara panjang.", "สายคาดร้อยเมล็ดสีแดงกับลูกปัดสีเขียว คาดพาดหน้าผาก ลวดลายแต่ละแบบเป็นของตระกูลหนึ่ง และการขอยืมสักเส้นก็ต้องคุยกันยาว", "Alna takılan, kırmızı tohumlar ve yeşil boncuklardan bir bant. Her desen bir aileye aittir ve birini ödünç almak uzun bir sohbet demektir.", "Una banda de semillas rojas y cuentas verdes que se lleva sobre la frente. Cada dibujo pertenece a una familia, y pedir uno prestado da para una conversación.", "Uma faixa de sementes vermelhas e contas verdes usada na testa. Cada padrão pertence a uma família, e pegar um emprestado rende uma conversa.", "Повязка из красных семян и зелёных бусин, которую носят на лбу. Каждый узор принадлежит какому-то роду, и одолжить его — это целый разговор.", "Пов'язка з червоного насіння й зелених намистин, яку носять на лобі. Кожен візерунок належить якомусь родові, і позичити його — це ціла розмова."],
  "A wrap of bark-cloth and cotton, dyed in leaf greens. You don't hear a Kanthari coming, and you don't see one either.": ["樹皮布と木綿の巻き布で、木の葉の緑に染めてある。カンタリの者が近づいても足音は聞こえないし、姿も見えない。", "나무껍질 천과 무명으로 지은 두름옷으로, 잎사귀 초록빛으로 물들였다. 칸타리족이 다가와도 발소리는 들리지 않고, 모습도 보이지 않는다.", "树皮布和棉布做的裹布，染成树叶般的绿色。坎塔里人走近时你听不见，也看不见。", "樹皮布和棉布做的裹布，染成樹葉般的綠色。坎塔里人走近時你聽不見，也看不見。", "Tấm khăn quấn bằng vải vỏ cây và vải bông, nhuộm màu xanh lá. Người Kanthari đến gần thì bạn chẳng nghe thấy, mà cũng chẳng nhìn thấy.", "Kain lilit dari kain kulit kayu dan katun, dicelup hijau daun. Kau tak mendengar orang Kanthari datang, dan tak melihatnya juga.", "ผ้าพันทำจากผ้าเปลือกไม้กับฝ้าย ย้อมสีเขียวใบไม้ ชาวกันถารีเดินมาใกล้ก็ไม่ได้ยิน และก็มองไม่เห็นด้วย", "Yaprak yeşiline boyanmış, ağaç kabuğu bezi ve pamuktan bir sargı. Bir Kanthari'nin geldiğini duymazsın, görmezsin de.", "Una envoltura de tela de corteza y algodón, teñida de verde hoja. A un kanthari no lo oyes llegar, y tampoco lo ves.", "Um manto de pano de casca de árvore e algodão, tingido de verde-folha. Você não ouve um kanthari chegando, e também não o vê.", "Накидка из лубяной ткани и хлопка, окрашенная в цвета листвы. Кантхари не слышно, когда он подходит, и не видно тоже.", "Накидка з лубової тканини й бавовни, пофарбована в кольори листя. Кантхарі не чути, коли він підходить, і не видно теж."],
  "A wrap-skirt to the knee, striped brown and green, worn by everyone in Kanthar whatever else they wear.": ["茶と緑の縞の、膝丈の巻きスカート。カンタルでは誰もが、ほかに何を着ていようとこれだけは身につけている。", "갈색과 초록 줄무늬의 무릎길이 두름치마. 칸타르에서는 누구나 다른 옷을 뭘 입든 이것만은 입는다.", "一条及膝的裹裙，棕绿相间的条纹。在坎塔尔，不管身上还穿着什么，人人都系着它。", "一條及膝的裹裙，棕綠相間的條紋。在坎塔爾，不管身上還穿著什麼，人人都繫著它。", "Chiếc váy quấn dài tới gối, sọc nâu xen xanh lá, ai ở Kanthar cũng mặc, bất kể ngoài ra họ mặc gì.", "Sarung selutut bergaris cokelat dan hijau, dipakai semua orang di Kanthar, apa pun pakaian mereka yang lain.", "ผ้านุ่งยาวถึงเข่า ลายทางสีน้ำตาลสลับเขียว ทุกคนในกันถาร์นุ่งกัน ไม่ว่าจะสวมอะไรอย่างอื่นอยู่ก็ตาม", "Kahverengi ve yeşil çizgili, diz boyu bir sarma etek; Kanthar'da başka ne giyerse giysin herkes bunu giyer.", "Una falda envolvente hasta la rodilla, a rayas marrones y verdes, que en Kanthar lleva todo el mundo, se ponga lo que se ponga encima.", "Uma saia envelope até o joelho, listrada de marrom e verde, usada por todo mundo em Kanthar, seja lá o que mais vistam.", "Юбка-запашка до колен в коричневую и зелёную полоску; в Кантхаре её носят все, что бы ещё на них ни было надето.", "Спідниця-запашка до колін у коричневу й зелену смужку; у Кантхарі її носять усі, хоч би що ще було на них вдягнено."],
  "A cape of overlapping teak leaves sewn on a palm-fibre net. The monsoon runs off it like off a roof.": ["ヤシ繊維の網にチークの葉を重ねて縫い付けた合羽。モンスーンの雨も、屋根を伝うように流れ落ちる。", "야자 섬유 그물에 티크 잎을 겹겹이 꿰매 붙인 우장. 몬순 빗물이 지붕에서처럼 흘러내린다.", "在棕榈纤维编的网上层层缝上柚木叶做成的雨披。季风雨落在上面，就像从屋顶上流下去一样。", "在棕櫚纖維編的網上層層縫上柚木葉做成的雨披。季風雨落在上面，就像從屋頂上流下去一樣。", "Chiếc áo tơi làm từ lá tếch xếp chồng, khâu trên lưới sợi cọ. Mưa gió mùa trôi tuột khỏi nó như trôi khỏi mái nhà.", "Jubah dari daun jati yang bertumpuk, dijahit pada jala serat palem. Hujan monsun mengalir darinya seperti dari atap.", "เสื้อคลุมทำจากใบสักเรียงซ้อนกัน เย็บติดบนตาข่ายใยปาล์ม ฝนมรสุมไหลลื่นออกไปเหมือนไหลจากหลังคา", "Palmiye lifinden bir ağa üst üste dikilmiş tik yapraklarından bir pelerin. Muson yağmuru üstünden çatıdan akar gibi akıp gider.", "Una capa de hojas de teca superpuestas, cosidas sobre una red de fibra de palma. El monzón resbala por ella como por un tejado.", "Uma capa de folhas de teca sobrepostas, costuradas numa rede de fibra de palmeira. A monção escorre por ela como por um telhado.", "Накидка из внахлёст уложенных тиковых листьев, нашитых на сетку из пальмового волокна. Муссон стекает с неё, как с крыши.", "Накидка з тикового листя, накладеного внапуск і нашитого на сітку з пальмового волокна. Мусон стікає з неї, як із даху."],
  "A frog the size of a dog, green and gold, its throat swelling like a bell. When the rain starts, every one of them in the valley starts too.": ["犬ほどもある緑と金のカエルで、喉が鐘のように膨らむ。雨が降り出すと、谷じゅうのこいつらが一斉に鳴き出す。", "개만 한 크기의 초록과 금빛 개구리로, 목이 종처럼 부풀어 오른다. 비가 시작되면 골짜기의 녀석들도 하나같이 시작한다.", "一只狗那么大的青蛙，绿中带金，喉囊鼓得像口钟。雨一下起来，山谷里所有的这种蛙也一齐叫起来。", "一隻狗那麼大的青蛙，綠中帶金，喉囊鼓得像口鐘。雨一下起來，山谷裡所有的這種蛙也一齊叫起來。", "Một con ếch to bằng con chó, xanh lục ánh vàng, cổ họng phồng lên như quả chuông. Mưa vừa bắt đầu là cả thung lũng ếch cũng bắt đầu theo.", "Katak sebesar anjing, hijau dan keemasan, tenggorokannya menggembung seperti lonceng. Begitu hujan mulai, semua katak sejenisnya di lembah ikut mulai.", "กบตัวขนาดเท่าสุนัข สีเขียวแซมทอง คอพองออกเหมือนระฆัง พอฝนเริ่มตก กบพวกนี้ทุกตัวในหุบเขาก็เริ่มร้องตาม", "Köpek büyüklüğünde, yeşil ve altın rengi bir kurbağa; gırtlağı çan gibi şişer. Yağmur başladığında vadideki bütün hemcinsleri de başlar.", "Una rana del tamaño de un perro, verde y dorada, con el buche hinchado como una campana. Cuando empieza la lluvia, empiezan también todas las del valle.", "Uma rã do tamanho de um cachorro, verde e dourada, com a garganta inchando como um sino. Quando a chuva começa, todas as do vale começam também.", "Лягушка размером с собаку, зелёная с золотом, горло раздувается колоколом. Когда начинается дождь, начинают и все её сородичи в долине.", "Жаба завбільшки із собаку, зелена із золотом, горло роздувається дзвоном. Коли починається дощ, починають і всі її родички в долині."],
  "A peacock in blue and green and bronze, its train a hundred eyes. It screams like somebody in trouble, which is how it gets its way.": ["青と緑と青銅色の雄クジャクで、飾り羽には百の目がある。困っている人のような声で叫ぶ。そうやって我を通すのだ。", "파랑과 초록과 청동빛을 두른 공작으로, 꼬리깃에는 눈이 백 개다. 곤경에 빠진 사람처럼 비명을 지르는데, 그게 제 뜻을 관철하는 방법이다.", "一只蓝、绿、古铜三色的孔雀，尾屏上有上百只眼。它叫起来像有人遇险，它就是靠这个为所欲为的。", "一隻藍、綠、古銅三色的孔雀，尾屏上有上百隻眼。牠叫起來像有人遇險，牠就是靠這個為所欲為的。", "Một con công xanh lam, xanh lục và màu đồng, đuôi xòe trăm con mắt. Nó kêu thét như ai đang gặp nạn, và đó là cách nó được việc.", "Merak berwarna biru, hijau, dan perunggu, ekornya bermata seratus. Ia menjerit seperti orang dalam kesulitan, dan begitulah ia mendapatkan maunya.", "นกยูงสีน้ำเงิน เขียว และสำริด หางมีตานับร้อย มันกรีดร้องเหมือนคนกำลังเดือดร้อน ซึ่งก็เป็นวิธีที่มันได้ดั่งใจ", "Mavi, yeşil ve bronz renkli bir tavus kuşu; kuyruğunda yüz göz. Başı dertte biri gibi çığlık atar; istediğini de böyle elde eder.", "Un pavo real azul, verde y bronce, con una cola de cien ojos. Chilla como alguien en apuros, y así se sale con la suya.", "Um pavão azul, verde e bronze, com uma cauda de cem olhos. Grita como alguém em apuros, e é assim que consegue o que quer.", "Павлин в синем, зелёном и бронзовом, со шлейфом в сотню глаз. Кричит, как человек в беде, — так он и добивается своего.", "Павич у синьому, зеленому й бронзовому, зі шлейфом на сотню очей. Кричить, як людина в біді, — так він і домагається свого."],
  "A leech as long as your arm, rising out of the wet grass on its tail when it feels your step. The rain brings them; the dry months bury them.": ["腕ほどの長さのヒルで、足音を感じると濡れた草むらから尾で立ち上がる。雨が連れてきて、乾季が埋めてしまう。", "팔뚝만 한 거머리로, 발소리를 느끼면 젖은 풀숲에서 꼬리로 일어선다. 비가 데려오고, 건기가 묻어 버린다.", "一条有手臂那么长的水蛭，一察觉到你的脚步，就从湿草里用尾巴立起来。雨季把它们带来，旱季把它们埋掉。", "一條有手臂那麼長的水蛭，一察覺到你的腳步，就從濕草裡用尾巴立起來。雨季把牠們帶來，旱季把牠們埋掉。", "Một con đỉa dài bằng cánh tay, dựng đứng trên đuôi giữa đám cỏ ướt khi cảm thấy bước chân bạn. Mưa mang chúng tới; mùa khô vùi chúng đi.", "Lintah sepanjang lenganmu, menegakkan diri di atas ekornya dari rumput basah saat merasakan langkahmu. Hujan membawa mereka; bulan-bulan kering menguburnya.", "ปลิงยาวเท่าแขน พอรู้สึกถึงฝีเท้าก็ยืดตัวขึ้นจากพงหญ้าเปียกด้วยหาง ฝนพาพวกมันมา หน้าแล้งฝังพวกมันไป", "Kolun kadar uzun bir sülük; adımını hissedince ıslak otların arasından kuyruğunun üstünde dikilir. Yağmur getirir onları; kurak aylar gömer.", "Una sanguijuela tan larga como tu brazo, que se alza sobre la cola entre la hierba mojada cuando siente tus pasos. La lluvia las trae; los meses secos las entierran.", "Uma sanguessuga do comprimento do seu braço, que se ergue na cauda no capim molhado quando sente seus passos. A chuva as traz; os meses secos as enterram.", "Пиявка длиной с руку; почуяв шаги, она поднимается на хвосте из мокрой травы. Дожди их приносят, сухие месяцы хоронят.", "П'явка завдовжки з руку; відчувши кроки, вона здіймається на хвості з мокрої трави. Дощі їх приносять, сухі місяці ховають."],
  "A grey monkey with a black face and a tail longer than it is, sitting on a rock as if it owned the road. Travellers' purses go missing near them, and the langurs don't apologise.": ["黒い顔に体より長い尾を持つ灰色の猿で、道の持ち主のような顔で岩に座っている。こいつらの近くでは旅人の財布が消え、ラングールは謝らない。", "얼굴이 검고 꼬리가 제 몸보다 긴 잿빛 원숭이로, 길 주인이라도 되는 양 바위에 앉아 있다. 이 녀석들 근처에서는 나그네의 지갑이 사라지는데, 랑구르는 사과하지 않는다.", "一只灰毛黑脸的猴子，尾巴比身子还长，坐在石头上，仿佛这条路是它家的。在它们附近，旅人的钱袋总会不翼而飞，而叶猴从不道歉。", "一隻灰毛黑臉的猴子，尾巴比身子還長，坐在石頭上，彷彿這條路是牠家的。在牠們附近，旅人的錢袋總會不翼而飛，而葉猴從不道歉。", "Một con khỉ xám mặt đen, đuôi dài hơn cả thân, ngồi trên tảng đá như thể con đường là của nó. Gần chúng thì túi tiền của lữ khách hay biến mất, và lũ voọc chẳng bao giờ xin lỗi.", "Monyet abu-abu bermuka hitam dengan ekor lebih panjang dari tubuhnya, duduk di atas batu seolah jalan itu miliknya. Kantong uang para pelancong suka hilang di dekat mereka, dan para lutung tak pernah minta maaf.", "ลิงสีเทาหน้าดำ หางยาวกว่าตัว นั่งอยู่บนก้อนหินราวกับเป็นเจ้าของถนน ถุงเงินของนักเดินทางมักหายไปแถวพวกมัน และพวกค่างก็ไม่เคยขอโทษ", "Kara suratlı, kuyruğu kendinden uzun gri bir maymun; yolun sahibiymiş gibi bir kayanın üstünde oturur. Yanlarında yolcuların keseleri kaybolur ve langurlar özür dilemez.", "Un mono gris de cara negra y cola más larga que él, sentado en una roca como si fuera el dueño del camino. Cerca de ellos desaparecen las bolsas de los viajeros, y los langures no piden perdón.", "Um macaco cinzento de cara preta e cauda mais comprida que ele, sentado numa pedra como se fosse dono da estrada. Perto deles, as bolsas dos viajantes somem, e os langures não pedem desculpas.", "Серая обезьяна с чёрной мордой и хвостом длиннее себя, сидит на камне, будто дорога принадлежит ей. Рядом с ними у путников пропадают кошельки, а лангуры не извиняются.", "Сіра мавпа з чорною мордою і хвостом, довшим за себе, сидить на камені, ніби дорога належить їй. Поруч із ними в подорожніх зникають гаманці, а лангури не перепрошують."],
  "A long brown snake that rises and spreads its hood when it sees you, two pale marks on the back of it like eyes. The farmers leave it bowls of milk, and a wide path.": ["人を見ると鎌首をもたげてフードを広げる、長い茶色の蛇。フードの裏には目のような淡い模様が二つある。農民たちはこいつに牛乳の鉢を供え、道は大きく空けてやる。", "사람을 보면 몸을 일으켜 목덜미를 펼치는 길고 갈색인 뱀으로, 그 뒷면에는 눈 같은 옅은 무늬 두 개가 있다. 농부들은 이 뱀에게 우유 한 사발과 넉넉한 길을 내어 준다.", "一条长长的褐色蛇，一见到你就立起身子，张开颈兜，背面有两块像眼睛的浅色斑纹。农民们给它留几碗牛奶，还给它让出一条宽宽的路。", "一條長長的褐色蛇，一見到你就立起身子，張開頸兜，背面有兩塊像眼睛的淺色斑紋。農民們給牠留幾碗牛奶，還給牠讓出一條寬寬的路。", "Một con rắn dài màu nâu, thấy bạn là ngóc đầu dậy bành mang ra, sau mang có hai đốm nhạt trông như mắt. Nông dân để cho nó những bát sữa, và một lối đi thật rộng.", "Ular cokelat panjang yang menegakkan diri dan mengembangkan tudungnya saat melihatmu, dengan dua tanda pucat di baliknya seperti mata. Para petani meninggalkan semangkuk susu untuknya, dan jalan yang lebar.", "งูยาวสีน้ำตาล พอเห็นคนก็ชูคอแผ่แม่เบี้ย ด้านหลังแม่เบี้ยมีลายจางสองจุดคล้ายดวงตา ชาวนาวางชามนมไว้ให้มัน และหลีกทางให้กว้าง ๆ", "Seni görünce dikilip kukuletasını açan uzun, kahverengi bir yılan; kukuletanın arkasında göze benzeyen iki soluk leke var. Çiftçiler ona kâse kâse süt bırakır, bir de geniş bir yol.", "Una serpiente larga y parda que se alza y despliega la capucha al verte, con dos marcas pálidas por detrás como ojos. Los campesinos le dejan cuencos de leche, y un camino bien ancho.", "Uma cobra longa e parda que se ergue e abre o capuz quando te vê, com duas marcas pálidas atrás, como olhos. Os lavradores lhe deixam tigelas de leite, e um caminho bem largo.", "Длинная бурая змея, которая, завидев вас, поднимается и раздувает капюшон; на его обороте два бледных пятна, похожих на глаза. Крестьяне оставляют ей плошки с молоком — и широкую дорогу.", "Довга бура змія, яка, побачивши вас, здіймається й роздуває каптур; на його звороті дві бліді плями, схожі на очі. Селяни залишають їй мисочки з молоком — і широку дорогу."],
  "A wild ox taller than a man at the shoulder, black, white-stockinged, its horns curved up and in. It isn't looking for a fight, and it will finish one.": ["肩の高さが人の背丈を超える野牛。黒い体に白い靴下を履いたような脚、角は上へ内へと曲がっている。喧嘩を求めてはいないが、始まれば決着はつける。", "어깨 높이가 사람 키보다 큰 들소. 몸은 검고 다리는 흰 양말을 신은 듯하며, 뿔은 위로 안으로 굽었다. 싸움을 찾아다니지는 않지만, 붙으면 끝을 낸다.", "一头肩高超过人的野牛，通体乌黑，四蹄像穿了白袜子，牛角向上向内弯。它不找架打，但真打起来，收场的一定是它。", "一頭肩高超過人的野牛，通體烏黑，四蹄像穿了白襪子，牛角向上向內彎。牠不找架打，但真打起來，收場的一定是牠。", "Một con bò rừng vai cao hơn đầu người, lông đen, chân trắng như đi tất, sừng cong lên và quặp vào trong. Nó không đi tìm chuyện đánh nhau, nhưng đã đánh thì nó sẽ kết thúc.", "Sapi liar yang tinggi bahunya melebihi manusia, hitam, kakinya putih seperti berkaus kaki, tanduknya melengkung ke atas dan ke dalam. Ia tidak mencari perkelahian, tapi ia akan menuntaskannya.", "วัวป่าที่ไหล่สูงกว่าคน ตัวดำ ขาขาวเหมือนสวมถุงเท้า เขาโค้งขึ้นและงุ้มเข้า มันไม่ได้หาเรื่องใคร แต่ถ้ามีเรื่องมันจะเป็นฝ่ายปิดฉาก", "Omuz hizası bir insandan yüksek, kara, bacakları beyaz çoraplı gibi, boynuzları yukarı ve içe kıvrık bir yaban öküzü. Kavga aramaz, ama çıkanı da bitirir.", "Un buey salvaje más alto que un hombre a la cruz, negro, con calcetines blancos y los cuernos curvados hacia arriba y hacia dentro. No busca pelea, pero la termina.", "Um boi selvagem mais alto que um homem na cernelha, preto, de meias brancas, com os chifres curvados para cima e para dentro. Não procura briga, mas termina uma.", "Дикий бык выше человека в холке, чёрный, в белых «чулках», с рогами, загнутыми вверх и внутрь. Драки он не ищет, но, если начнётся, закончит её сам.", "Дикий бик, вищий за людину в холці, чорний, у білих «панчохах», з рогами, загнутими вгору й досередини. Бійки він не шукає, але як почнеться — закінчить її сам."],
  "A highway robber of the Gate of Rains, cloth over the face, a curved knife and a grievance. Some were farmers before the tanks silted; some were robbers before that.": ["雨の門の街道強盗。顔を布で覆い、曲がった短刀と恨みを携えている。貯水池が泥で埋まる前は農民だった者もいれば、その前から強盗だった者もいる。", "비의 문의 노상강도. 천으로 얼굴을 가리고, 굽은 칼과 원한을 품고 있다. 저수지가 토사로 메워지기 전에는 농부였던 자도 있고, 그보다 전부터 강도였던 자도 있다.", "雨之门的拦路强盗，蒙着面，带着一把弯刀和一肚子怨气。有的在水池淤塞之前是农民，有的在那之前就是强盗了。", "雨之門的攔路強盜，蒙著面，帶著一把彎刀和一肚子怨氣。有的在水池淤塞之前是農民，有的在那之前就是強盜了。", "Một tên cướp đường ở Cổng Mưa, khăn che mặt, dao cong trong tay và một mối oán hận. Có kẻ từng là nông dân trước khi hồ chứa bị bồi lấp; có kẻ thì đã là cướp từ trước đó nữa.", "Perampok jalanan Gerbang Hujan, wajah tertutup kain, membawa pisau melengkung dan dendam. Sebagian dulu petani sebelum telaga tertimbun lumpur; sebagian lagi sudah jadi perampok sebelum itu.", "โจรปล้นทางแห่งประตูแห่งสายฝน เอาผ้าปิดหน้า ถือมีดโค้งกับความแค้นเต็มอก บางคนเคยเป็นชาวนาก่อนสระจะตื้นเขิน บางคนก็เป็นโจรมาตั้งแต่ก่อนหน้านั้นแล้ว", "Yağmur Kapısı'nın bir yol kesicisi; yüzünde bez, elinde eğri bir bıçak, içinde bir kin. Kimi havuzlar dolmadan önce çiftçiydi; kimi ondan önce de haydut.", "Un salteador de la Puerta de las Lluvias, con un trapo sobre la cara, un cuchillo curvo y un agravio. Algunos eran campesinos antes de que los estanques se llenaran de limo; otros ya eran ladrones desde antes.", "Um salteador do Portão das Chuvas, com um pano sobre o rosto, uma faca curva e um rancor. Alguns eram lavradores antes de os tanques assorearem; outros já eram ladrões antes disso.", "Разбойник с большой дороги у Врат Дождей: лицо замотано тканью, кривой нож и обида. Кто-то был крестьянином, пока пруды не заилились; кто-то был разбойником и до того.", "Розбійник із великого шляху біля Брами Дощів: обличчя замотане тканиною, кривий ніж і образа. Хтось був селянином, доки стави не замулилися; хтось був розбійником і до того."],
  "A raider off a low black boat, sea-salt in her braids and a hooked blade in her belt. Suvarnatira pays the harbour watch to chase them, and the corsairs pay them not to.": ["低い黒船から上がってくる略奪者。三つ編みには潮の塩、帯には鉤形の刃。スヴァルナティーラは港の衛視に金を払って彼女らを追わせ、海賊たちは追わないよう金を払う。", "낮고 검은 배에서 내리는 약탈자. 땋은 머리에는 바닷소금이, 허리띠에는 갈고리 칼날이 있다. 수바르나티라는 항구 경비대에 돈을 주어 이들을 쫓게 하고, 해적들은 쫓지 말라고 돈을 준다.", "从低矮黑船上下来的劫掠者，发辫里沾着海盐，腰带上别着钩刃。苏瓦尔纳蒂拉花钱请港口巡卫去追她们，海盗则花钱请巡卫别追。", "從低矮黑船上下來的劫掠者，髮辮裡沾著海鹽，腰帶上別著鉤刃。蘇瓦爾納蒂拉花錢請港口巡衛去追她們，海盜則花錢請巡衛別追。", "Một ả cướp biển từ chiếc thuyền đen thấp lè tè, muối biển bám trên bím tóc, lưỡi dao móc giắt ở thắt lưng. Suvarnatira trả tiền cho đội tuần cảng để truy đuổi chúng, còn bọn hải tặc trả tiền để họ khỏi đuổi.", "Perompak dari perahu hitam yang rendah, garam laut di kepangannya dan bilah berkait di sabuknya. Suvarnatira membayar penjaga pelabuhan untuk mengejar mereka, dan para bajak laut membayar mereka agar tidak mengejar.", "นางโจรจากเรือดำลำเตี้ย เกลือทะเลติดอยู่ในเปียผม มีดขอเหน็บไว้ที่เข็มขัด สุวรรณตีระจ้างยามท่าเรือให้ไล่ล่าพวกนาง ส่วนพวกโจรสลัดก็จ้างยามให้ไม่ต้องไล่", "Alçak, kara bir tekneden inen bir yağmacı; örgülerinde deniz tuzu, kuşağında çengelli bir bıçak. Suvarnatira liman bekçilerine onları kovalamaları için para öder, korsanlar da kovalamasınlar diye.", "Una saqueadora salida de una barca negra y baja, con sal marina en las trenzas y una hoja ganchuda al cinto. Suvarnatira paga a la guardia del puerto para que las persiga, y las corsarias le pagan para que no lo haga.", "Uma saqueadora de um barco negro e baixo, com sal marinho nas tranças e uma lâmina curva no cinto. Suvarnatira paga a guarda do porto para persegui-las, e as corsárias pagam para que não persiga.", "Налётчица с низкой чёрной лодки: морская соль в косах, крюкастый клинок за поясом. Суварнатира платит портовой страже, чтобы та за ними гонялась, а корсарши платят, чтобы не гонялась.", "Нападниця з низького чорного човна: морська сіль у косах, гакуватий клинок за поясом. Суварнатіра платить портовій варті, щоб та за ними ганялася, а корсарки платять, щоб не ганялася."],
  "A knot of creepers that stands up out of the undergrowth and reaches. The Kanthari cut it back every year with a song, and it grows back every year without one.": ["下草の中から立ち上がり、手を伸ばしてくる蔓の塊。カンタリの人々は毎年歌を歌いながらこれを刈り込むが、こいつは毎年歌もなしに生え戻る。", "덤불 속에서 일어나 손을 뻗어 오는 덩굴 뭉치. 칸타리족은 해마다 노래를 부르며 이것을 쳐내고, 이것은 해마다 노래도 없이 다시 자란다.", "一团藤蔓，从灌木丛里站起来，伸手来抓。坎塔里人每年唱着歌把它砍掉，它每年不用唱歌就又长回来。", "一團藤蔓，從灌木叢裡站起來，伸手來抓。坎塔里人每年唱著歌把它砍掉，它每年不用唱歌就又長回來。", "Một búi dây leo đứng dậy từ đám bụi rậm và vươn tới. Người Kanthari năm nào cũng vừa hát vừa phát nó đi, và năm nào nó cũng mọc lại mà chẳng cần hát.", "Segumpal sulur yang bangkit dari semak belukar dan menjangkau. Orang Kanthari memangkasnya setiap tahun sambil bernyanyi, dan setiap tahun ia tumbuh lagi tanpa nyanyian.", "กอเถาวัลย์ที่ลุกขึ้นจากพงไม้แล้วยื่นมาคว้า ชาวกันถารีตัดมันทุกปีพร้อมกับร้องเพลง และมันก็งอกกลับมาทุกปีโดยไม่ต้องร้องเพลง", "Çalılıkların arasından ayağa kalkıp uzanan bir sarmaşık yumağı. Kanthariler onu her yıl bir şarkıyla budar, o da her yıl şarkısız geri büyür.", "Un nudo de enredaderas que se levanta de la maleza y alarga la mano. Los kanthari la podan cada año con una canción, y cada año vuelve a crecer sin ninguna.", "Um emaranhado de trepadeiras que se levanta do mato e estende a mão. Os kanthari a podam todo ano com uma canção, e todo ano ela cresce de novo sem nenhuma.", "Клубок лиан, который встаёт из подлеска и тянется к вам. Кантхари каждый год обрубают его с песней, а он каждый год отрастает без всякой песни.", "Клубок ліан, що встає з підліску й тягнеться до вас. Кантхарі щороку обрубують його з піснею, а він щороку відростає без жодної пісні."],
  "Orange and black, the size of a pony, moving through the bamboo without moving it. The Kanthari don't say its name in the forest; they call it 'the one with stripes', politely.": ["橙と黒、ポニーほどの大きさで、竹林を揺らしもせずに抜けていく。カンタリの人々は森の中でその名を口にしない。丁寧に「縞のあるお方」と呼ぶ。", "주황과 검정, 조랑말만 한 덩치로, 대숲을 흔들지도 않고 지나간다. 칸타리족은 숲에서 그 이름을 입에 올리지 않는다. 예의 바르게 '줄무늬 있는 분'이라고 부른다.", "橙黑相间，有矮种马那么大，穿过竹林时竹子纹丝不动。坎塔里人在林子里不提它的名字，只客客气气地称它“身上有条纹的那位”。", "橙黑相間，有矮種馬那麼大，穿過竹林時竹子紋風不動。坎塔里人在林子裡不提牠的名字，只客客氣氣地稱牠「身上有條紋的那位」。", "Cam và đen, to cỡ con ngựa nhỏ, đi xuyên rừng tre mà tre chẳng hề lay. Người Kanthari không gọi tên nó trong rừng; họ lễ phép gọi nó là 'ngài có sọc'.", "Jingga dan hitam, sebesar kuda poni, bergerak menembus rumpun bambu tanpa menggoyangkannya. Orang Kanthari tak menyebut namanya di hutan; mereka menyebutnya 'yang bergaris', dengan sopan.", "สีส้มสลับดำ ตัวขนาดเท่าม้าแคระ เคลื่อนผ่านดงไผ่โดยไม่ทำให้ไผ่ไหว ชาวกันถารีไม่เอ่ยชื่อมันในป่า พวกเขาเรียกมันอย่างสุภาพว่า 'ท่านผู้มีลาย'", "Turuncu ve siyah, midilli büyüklüğünde; bambuların arasından onları kımıldatmadan geçer. Kanthariler ormanda adını anmaz; ona kibarca 'çizgili olan' derler.", "Naranja y negro, del tamaño de un poni, se mueve entre los bambúes sin moverlos. Los kanthari no dicen su nombre en el bosque; lo llaman 'el de las rayas', con educación.", "Laranja e preto, do tamanho de um pônei, passa pelo bambuzal sem movê-lo. Os kanthari não dizem seu nome na floresta; chamam-no de 'aquele das listras', educadamente.", "Рыже-чёрный, размером с пони, он проходит сквозь бамбук, не шелохнув его. Кантхари в лесу не произносят его имени; они вежливо называют его «тот, что в полоску».", "Рудий із чорним, завбільшки з поні, він проходить крізь бамбук, не зворухнувши його. Кантхарі в лісі не вимовляють його імені; вони чемно називають його «той, що в смужку»."],
  "A soldier of a Copper Banner company who stopped waiting for his pay, still in the copper-faced coat with the badge cut off. He's kept the sabre.": ["給金を待つのをやめた、銅の旗の一隊の兵士。銅色の折り返しの上着はまだ着ているが、記章は切り取ってある。サーベルは手放していない。", "급료 기다리기를 그만둔 구리 깃발 부대의 병사. 구리빛 깃을 단 외투는 아직 입고 있지만 휘장은 떼어 냈다. 군도는 챙겼다.", "铜旗某连队的士兵，不再等他的军饷了。身上还穿着铜色镶边的外套，徽章已经割掉。马刀倒是留下了。", "銅旗某連隊的士兵，不再等他的軍餉了。身上還穿著銅色鑲邊的外套，徽章已經割掉。馬刀倒是留下了。", "Một người lính thuộc đại đội Cờ Đồng đã thôi chờ lương, vẫn mặc chiếc áo khoác viền đồng nhưng phù hiệu đã bị cắt bỏ. Thanh gươm cong thì hắn giữ lại.", "Prajurit kompi Panji Tembaga yang sudah berhenti menunggu gajinya, masih memakai mantel berlapis tembaga dengan lencana yang sudah dipotong. Pedangnya ia simpan.", "ทหารกองร้อยธงทองแดงที่เลิกรอเงินเดือนแล้ว ยังสวมเสื้อคลุมขลิบทองแดงอยู่แต่ตัดเครื่องหมายทิ้ง ส่วนดาบโค้งนั้นเขาเก็บไว้", "Maaşını beklemekten vazgeçmiş bir Bakır Sancak bölüğü askeri; hâlâ bakır yakalı ceketini giyiyor ama arması sökülmüş. Kılıcını ise bırakmamış.", "Un soldado de una compañía del Estandarte de Cobre que se cansó de esperar la paga, todavía con la casaca de vueltas de cobre y la insignia arrancada. El sable se lo ha quedado.", "Um soldado de uma companhia do Estandarte de Cobre que cansou de esperar o soldo, ainda com o casaco de lapelas acobreadas e o distintivo arrancado. O sabre ele guardou.", "Солдат роты Медного знамени, который перестал ждать жалованья: всё ещё в мундире с медными отворотами, но со срезанной нашивкой. Саблю он оставил себе.", "Солдат роти Мідного стягу, який перестав чекати платні: досі в мундирі з мідними вилогами, але зі зрізаною нашивкою. Шаблю він залишив собі."],
  "A shaggy black bear with a pale crescent on its chest and claws for digging grubs out of rock, or anything else out of anything else. It rules the scree above the mines.": ["胸に淡い三日月模様のある、毛むくじゃらの黒熊。爪は岩から地虫を掘り出すためのものだが、何からでも何でも掘り出せる。鉱山の上のガレ場はこいつのものだ。", "가슴에 옅은 초승달 무늬가 있는 털북숭이 흑곰. 발톱은 바위에서 굼벵이를 파내는 용도지만, 뭐든 무엇에서든 파낼 수 있다. 광산 위 너덜지대는 이 녀석이 다스린다.", "一头毛发蓬乱的黑熊，胸前有一道浅色月牙，爪子是用来从岩缝里刨虫子的——或者从任何东西里刨出任何东西。矿山上方的碎石坡归它管。", "一頭毛髮蓬亂的黑熊，胸前有一道淺色月牙，爪子是用來從岩縫裡刨蟲子的——或者從任何東西裡刨出任何東西。礦山上方的碎石坡歸牠管。", "Một con gấu đen lông bờm xờm, ngực có vệt trăng lưỡi liềm nhạt màu, móng vuốt dùng để moi ấu trùng ra khỏi đá, hoặc moi bất cứ thứ gì ra khỏi bất cứ thứ gì. Nó làm chúa sườn đá vụn phía trên các mỏ.", "Beruang hitam berbulu lebat dengan bulan sabit pucat di dadanya dan cakar untuk mengorek larva dari batu, atau apa saja dari apa saja. Ia menguasai lereng kerikil di atas tambang.", "หมีดำขนรุงรัง มีลายจันทร์เสี้ยวสีจางที่อก กรงเล็บมีไว้ขุดตัวด้วงออกจากหิน หรือขุดอะไรก็ได้ออกจากอะไรก็ได้ มันครองลานหินร่วงเหนือเหมือง", "Göğsünde soluk bir hilal olan, tüylü kara bir ayı; pençeleri kayadan kurtçuk kazımak için, ya da herhangi bir şeyden herhangi bir şey kazımak için. Madenlerin üstündeki taşlı yamaçlar onun hükmündedir.", "Un oso negro y lanudo con una media luna pálida en el pecho y garras para sacar larvas de la roca, o cualquier otra cosa de cualquier otra cosa. Reina en los pedregales sobre las minas.", "Um urso negro e peludo com uma meia-lua pálida no peito e garras para tirar larvas da rocha, ou qualquer outra coisa de qualquer outra coisa. Reina sobre as encostas de cascalho acima das minas.", "Косматый чёрный медведь с бледным полумесяцем на груди и когтями, чтобы выковыривать личинок из камня — или что угодно из чего угодно. Он хозяин осыпей над рудниками.", "Кошлатий чорний ведмідь із блідим півмісяцем на грудях і пазурами, щоб видовбувати личинок із каменю — або будь-що з будь-чого. Він господар осипів над копальнями."],
  "One of Ilavarta's border guards in tank blue, a long umbrella of oiled paper strapped to his back beside the spear.": ["貯水池の青をまとったイラヴァルタの国境警備兵。背中には槍と並べて、油紙の長い傘をくくりつけている。", "저수지 빛 파란 옷을 입은 일라바르타의 국경 경비병. 등에는 창 옆에 기름종이로 만든 긴 우산을 묶어 메고 있다.", "伊拉瓦塔的边境卫兵，身穿水池蓝的制服，背上除了长矛，还绑着一把长长的油纸伞。", "伊拉瓦塔的邊境衛兵，身穿水池藍的制服，背上除了長矛，還綁著一把長長的油紙傘。", "Một lính biên phòng của Ilavarta trong sắc xanh hồ chứa, sau lưng đeo một chiếc ô giấy dầu dài bên cạnh cây giáo.", "Salah satu penjaga perbatasan Ilavarta berseragam biru telaga, payung kertas minyak yang panjang terikat di punggungnya di samping tombak.", "ทหารรักษาชายแดนของอิลาวรรตะในชุดสีฟ้าสระ สะพายร่มกระดาษชุบน้ำมันคันยาวไว้ข้างหอกบนหลัง", "Ilavarta'nın havuz mavisi giymiş sınır muhafızlarından biri; sırtında mızrağın yanına uzun, yağlı kâğıttan bir şemsiye bağlı.", "Uno de los guardias fronterizos de Ilavarta, vestido de azul estanque, con un largo paraguas de papel aceitado atado a la espalda junto a la lanza.", "Um dos guardas de fronteira de Ilavarta, vestido de azul-tanque, com um longo guarda-chuva de papel oleado amarrado às costas ao lado da lança.", "Один из пограничных стражей Илаварты в одежде цвета прудовой синевы; за спиной рядом с копьём привязан длинный зонт из промасленной бумаги.", "Один із прикордонних вартових Ілаварти в одязі кольору ставкової синяви; за спиною поруч зі списом прив'язана довга парасоля з промасленого паперу."],
  "Keeper of the Tirthali ford and of its ledger of crossings. Half Kharaveth and half Meghavan, he says, and all Tirthali, and he'll sell you a crossing in either half.": ["ティルタリの渡し場と、その渡河台帳の番人。本人いわく、半分カラヴェス、半分メガヴァン、そして丸ごとティルタリ。どちらの半分でも渡し賃は売ってくれる。", "티르탈리 나루와 도하 장부를 지키는 사람. 본인 말로는 반은 카라베스, 반은 메가반, 그리고 온전히 티르탈리 사람이란다. 어느 쪽 반으로든 도하권을 팔아 줄 것이다.", "提尔塔利渡口及其渡河账簿的看守人。他说自己一半是卡拉维斯人，一半是梅加万人，整个儿是提尔塔利人——哪一半都乐意卖你一张渡河票。", "提爾塔利渡口及其渡河帳簿的看守人。他說自己一半是卡拉維斯人，一半是梅加萬人，整個兒是提爾塔利人——哪一半都樂意賣你一張渡河票。", "Người giữ bến lội Tirthali cùng sổ ghi các chuyến qua sông. Ông bảo mình nửa Kharaveth nửa Meghavan, và trọn vẹn là Tirthali, và nửa nào thì ông cũng bán cho bạn một chuyến qua sông.", "Penjaga penyeberangan Tirthali beserta buku catatan penyeberangannya. Separuh Kharaveth dan separuh Meghavan, katanya, dan sepenuhnya Tirthali, dan ia akan menjual penyeberangan padamu di separuh mana pun.", "ผู้ดูแลท่าข้ามตีรถลีและสมุดบัญชีการข้ามฟาก เขาว่าตัวเองเป็นคาราเวธครึ่งหนึ่ง เมฆาวันครึ่งหนึ่ง และเป็นตีรถลีเต็มตัว และไม่ว่าครึ่งไหนเขาก็ขายค่าข้ามให้คุณได้", "Tirthali geçidinin ve geçiş defterinin bekçisi. Söylediğine göre yarı Kharaveth'li, yarı Meghavan'lı, tamamen de Tirthali'li; hangi yarısıyla isterseniz size bir geçiş satar.", "Guardián del vado de Tirthali y de su libro de cruces. Mitad Kharaveth y mitad Meghavan, dice, y todo Tirthali, y te venderá un cruce en cualquiera de las dos mitades.", "Guardião do vau de Tirthali e do seu livro de travessias. Metade Kharaveth e metade Meghavan, segundo ele, e Tirthali por inteiro, e vende uma travessia em qualquer das duas metades.", "Хранитель брода Тиртхали и его книги переправ. Наполовину Харавет, наполовину Мегхаван, по его словам, и целиком Тиртхали — и продаст вам переправу в любой из половин.", "Охоронець броду Тіртхалі та його книги переправ. Наполовину Харавет, наполовину Мегхаван, за його словами, і цілком Тіртхалі — і продасть вам переправу в будь-якій із половин."],
  "Keeps the caravanserai. She has fed camel drivers from Khetmar and boatmen from the Golden Shore at the same table, and stopped three wars over the pickle.": ["隊商宿の女将。ケトマルのラクダ引きと黄金の浜の船頭を同じ食卓で食べさせ、漬物をめぐる戦争を三つ止めてきた。", "대상 숙소를 꾸린다. 케트마르의 낙타몰이꾼과 황금 해안의 뱃사공을 한 식탁에서 먹였고, 절임 반찬을 두고 벌어진 전쟁을 세 번이나 막았다.", "商队客栈的老板娘。她曾让克特马尔的驼夫和黄金海岸的船夫同桌吃饭，还为了一碟腌菜平息过三场战争。", "商隊客棧的老闆娘。她曾讓克特馬爾的駝夫和黃金海岸的船夫同桌吃飯，還為了一碟醃菜平息過三場戰爭。", "Bà trông coi lữ quán đoàn buôn. Bà từng cho phu lạc đà từ Khetmar và dân chèo thuyền từ Bờ Vàng ăn chung một mâm, và đã dập tắt ba cuộc chiến vì món dưa muối.", "Mengurus karavanserai. Ia pernah memberi makan para penunggang unta dari Khetmar dan tukang perahu dari Pantai Emas di meja yang sama, dan menghentikan tiga perang gara-gara acar.", "ดูแลคาราวานเซอราย นางเคยเลี้ยงข้าวคนต้อนอูฐจากเคทมาร์กับคนเรือจากชายฝั่งทองคำที่โต๊ะเดียวกัน และหยุดสงครามที่เกิดจากผักดองมาแล้วสามครั้ง", "Kervansarayı işletir. Khetmar'dan deveciler ile Altın Kıyı'dan kayıkçıları aynı sofrada doyurmuş ve turşu yüzünden çıkan üç savaşı durdurmuştur.", "Lleva el caravasar. Ha dado de comer en la misma mesa a camelleros de Khetmar y barqueros de la Costa Dorada, y ha parado tres guerras por culpa del encurtido.", "Toca o caravançará. Já serviu na mesma mesa cameleiros de Khetmar e barqueiros da Costa Dourada, e evitou três guerras por causa do picles.", "Держит караван-сарай. Она кормила за одним столом погонщиков верблюдов из Кетмара и лодочников с Золотого берега и остановила три войны из-за соленья.", "Тримає караван-сарай. Вона годувала за одним столом погоничів верблюдів із Кетмару й човнярів із Золотого берега та зупинила три війни через соління."],
  "Keeps the stores by the caravanserai. Prices in Kharaveth gold and Meghavan copper, and does the sums faster than you can.": ["隊商宿の脇で雑貨屋を営む。値段はカラヴェスの金貨とメガヴァンの銅貨の両方でつけ、計算はあなたより速い。", "대상 숙소 옆에서 가게를 한다. 값을 카라베스 금화와 메가반 동전 두 가지로 매기고, 셈은 당신보다 빠르다.", "在商队客栈旁开杂货铺。用卡拉维斯金币和梅加万铜钱两种标价，算账比你快。", "在商隊客棧旁開雜貨鋪。用卡拉維斯金幣和梅加萬銅錢兩種標價，算帳比你快。", "Trông coi cửa hàng cạnh lữ quán. Niêm giá bằng vàng Kharaveth lẫn đồng Meghavan, và tính nhẩm nhanh hơn bạn.", "Mengurus toko di samping karavanserai. Memasang harga dalam emas Kharaveth dan tembaga Meghavan, dan berhitung lebih cepat darimu.", "ดูแลร้านค้าข้างคาราวานเซอราย ตั้งราคาทั้งเป็นทองคาราเวธและทองแดงเมฆาวัน และคิดเลขได้เร็วกว่าคุณ", "Kervansarayın yanındaki dükkânı işletir. Fiyatları hem Kharaveth altını hem Meghavan bakırıyla verir ve hesabı senden hızlı yapar.", "Lleva la tienda junto al caravasar. Pone los precios en oro de Kharaveth y en cobre de Meghavan, y hace las cuentas más rápido que tú.", "Toca o armazém ao lado do caravançará. Dá os preços em ouro de Kharaveth e em cobre de Meghavan, e faz as contas mais rápido que você.", "Держит лавку при караван-сарае. Называет цены в золоте Харавета и меди Мегхавана и считает быстрее вас.", "Тримає крамницю при караван-сараї. Називає ціни в золоті Харавета й міді Мегхавана і рахує швидше за вас."],
  "Tirthali's dyer, her hands blue to the wrist with indigo and yellow at the nails with turmeric.": ["ティルタリの染め物師。両手は手首まで藍で青く、爪はウコンで黄色い。", "티르탈리의 염색공. 두 손은 쪽물에 손목까지 파랗고, 손톱은 강황에 노랗다.", "提尔塔利的染匠，双手被靛蓝染得蓝到手腕，指甲被姜黄染得发黄。", "提爾塔利的染匠，雙手被靛藍染得藍到手腕，指甲被薑黃染得發黃。", "Thợ nhuộm của Tirthali, đôi tay xanh chàm tới cổ tay và móng vàng nghệ.", "Pencelup Tirthali, tangannya biru nila sampai pergelangan dan kukunya kuning kunyit.", "ช่างย้อมแห่งตีรถลี มือเป็นสีครามไปถึงข้อมือ และเล็บเหลืองด้วยขมิ้น", "Tirthali'nin boyacısı; elleri bileklerine kadar çivitten mavi, tırnakları zerdeçaldan sarı.", "La tintorera de Tirthali, con las manos azules de añil hasta la muñeca y las uñas amarillas de cúrcuma.", "A tintureira de Tirthali, com as mãos azuis de anil até o pulso e as unhas amarelas de açafrão-da-terra.", "Красильщица Тиртхали: руки до запястий синие от индиго, а ногти жёлтые от куркумы.", "Фарбувальниця Тіртхалі: руки до зап'ясть сині від індиго, а нігті жовті від куркуми."],
  "A pedlar with a covered basket and a smile that comes and goes. The things under the cloth are old, and some of them still have earth on them.": ["覆いをかけた籠と、浮かんでは消える笑みを持つ行商人。布の下の品は古く、いくつかにはまだ土がついている。", "덮개 씌운 바구니를 들고, 나타났다 사라지는 미소를 짓는 행상. 천 밑의 물건들은 오래된 것들이고, 몇몇에는 아직 흙이 묻어 있다.", "一个货郎，挎着盖了布的篮子，脸上的笑容时有时无。布底下的东西都很古老，有些上面还沾着土。", "一個貨郎，挎著蓋了布的籃子，臉上的笑容時有時無。布底下的東西都很古老，有些上面還沾著土。", "Một người bán rong với cái giỏ phủ vải và nụ cười lúc có lúc không. Những món dưới tấm vải đều cũ, và vài món vẫn còn dính đất.", "Penjaja dengan keranjang bertutup kain dan senyum yang datang dan pergi. Barang-barang di bawah kain itu tua, dan beberapa masih berlumur tanah.", "พ่อค้าเร่ถือตะกร้าคลุมผ้า กับรอยยิ้มที่เดี๋ยวมาเดี๋ยวหาย ของใต้ผ้าล้วนเก่าแก่ และบางชิ้นยังมีดินติดอยู่", "Üstü örtülü bir sepeti ve gelip giden bir gülümsemesi olan seyyar satıcı. Örtünün altındaki şeyler eski ve bazılarının üstünde hâlâ toprak var.", "Un buhonero con una cesta tapada y una sonrisa que va y viene. Las cosas bajo el paño son antiguas, y algunas todavía tienen tierra encima.", "Um mascate com um cesto coberto e um sorriso que vai e vem. As coisas debaixo do pano são antigas, e algumas ainda têm terra.", "Коробейник с накрытой корзиной и улыбкой, которая то появляется, то исчезает. Вещи под тканью старые, а на некоторых ещё осталась земля.", "Рознощик із накритим кошиком і посмішкою, що то з'являється, то зникає. Речі під тканиною старі, а на деяких ще лишилася земля."],
  "A watchman of the ford, paid by the ferrywarden, in a turban of no particular kingdom.": ["渡し守に雇われた渡し場の見張り番。どこの王国のものとも言えないターバンを巻いている。", "나루지기에게 품삯을 받는 나루 파수꾼. 어느 왕국 것이라 할 수 없는 터번을 둘렀다.", "渡口的看守，由渡口守发工钱，头上缠着一条看不出属于哪个王国的头巾。", "渡口的看守，由渡口守發工錢，頭上纏著一條看不出屬於哪個王國的頭巾。", "Một người canh bến lội, do người giữ bến trả lương, quấn chiếc khăn xếp chẳng thuộc vương quốc nào cụ thể.", "Penjaga arungan yang digaji oleh penjaga penyeberangan, bersorban yang bukan khas kerajaan mana pun.", "ยามเฝ้าท่าข้าม ได้ค่าจ้างจากผู้คุมท่าข้าม โพกผ้าโพกหัวที่ไม่ได้เป็นแบบของอาณาจักรใดเป็นพิเศษ", "Geçit bekçisinden maaş alan bir geçit nöbetçisi; başında belli bir krallığa ait olmayan bir sarık var.", "Un vigilante del vado, pagado por el guardavado, con un turbante que no es de ningún reino en particular.", "Um vigia do vau, pago pelo guarda do vau, com um turbante que não é de nenhum reino em particular.", "Сторож брода на жалованье у паромщика, в тюрбане, не принадлежащем никакому определённому королевству.", "Сторож броду на платні в поромника, у тюрбані, що не належить жодному певному королівству."],
  "Someone of the ford town, in a Kharaveth headcloth and a Meghavan shawl, which here is just what people wear.": ["渡しの町の住人。カラヴェスの頭巾にメガヴァンの肩掛けという格好だが、ここではそれがごく普通の服装だ。", "나루 마을 사람. 카라베스식 머릿수건에 메가반식 숄을 둘렀는데, 여기서는 그게 그냥 평범한 차림이다.", "渡口小镇的居民，头裹卡拉维斯头巾，肩披梅加万披肩——在这里，大家本来就这么穿。", "渡口小鎮的居民，頭裹卡拉維斯頭巾，肩披梅加萬披肩——在這裡，大家本來就這麼穿。", "Một người ở thị trấn bến lội, quấn khăn đầu kiểu Kharaveth và choàng khăn kiểu Meghavan, mà ở đây thì người ta vẫn mặc như thế.", "Seseorang dari kota penyeberangan, memakai kain kepala Kharaveth dan selendang Meghavan, yang di sini memang pakaian orang biasa.", "ชาวเมืองท่าข้าม โพกผ้าแบบคาราเวธและคลุมผ้าคลุมไหล่แบบเมฆาวัน ซึ่งที่นี่ก็เป็นแค่การแต่งกายธรรมดาของผู้คน", "Geçit kasabasından biri; başında Kharaveth usulü bir başörtüsü, omzunda Meghavan usulü bir şal; burada herkes zaten böyle giyinir.", "Alguien del pueblo del vado, con un tocado de Kharaveth y un chal de Meghavan, que aquí es simplemente lo que lleva la gente.", "Alguém da vila do vau, com um pano de cabeça de Kharaveth e um xale de Meghavan, que aqui é simplesmente o que as pessoas usam.", "Житель городка у брода, в головном платке из Харавета и шали из Мегхавана — здесь все так и ходят.", "Мешканець містечка біля броду, у головній хустці з Харавета й шалі з Мегхавана — тут усі так і ходять."],
  "Queen of Ilavarta, Keeper of the Tanks. Her crown is a ring of silver set with a single lapis drop, for a tank seen from above, and she has a mason's calluses under the rings.": ["イラヴァルタの女王にして、貯水池の守り手。王冠は銀の輪にラピスラズリの雫をひと粒あしらったもので、上から見た貯水池を表している。指輪の下には石工のたこがある。", "일라바르타의 여왕이자 저수지의 수호자. 왕관은 위에서 내려다본 저수지를 본떠 은 고리에 청금석 물방울 하나를 박은 것이고, 반지 아래 손에는 석공의 굳은살이 박여 있다.", "伊拉瓦塔女王，水池守护者。她的王冠是一圈银环，嵌着一滴青金石，象征从高处俯瞰的水池；戒指底下，是石匠的老茧。", "伊拉瓦塔女王，水池守護者。她的王冠是一圈銀環，嵌著一滴青金石，象徵從高處俯瞰的水池；戒指底下，是石匠的老繭。", "Nữ hoàng của Ilavarta, Người Giữ Hồ. Vương miện của bà là một vòng bạc gắn một giọt lưu ly duy nhất, tượng trưng cho hồ chứa nhìn từ trên cao, và dưới những chiếc nhẫn là đôi tay chai sạn của thợ đá.", "Ratu Ilavarta, Penjaga Telaga. Mahkotanya berupa lingkaran perak bertatahkan setetes lapis lazuli, melambangkan telaga yang dilihat dari atas, dan di balik cincin-cincinnya ada kapalan tukang batu.", "ราชินีแห่งอิลาวรรตะ ผู้รักษาสระ มงกุฎของพระนางเป็นวงแหวนเงินประดับหยดลาพิสเพียงเม็ดเดียว แทนสระที่มองจากเบื้องบน และใต้แหวนนั้นมีรอยด้านแบบช่างก่อหิน", "Ilavarta Kraliçesi, Havuzların Bekçisi. Tacı, yukarıdan görülen bir havuzu simgeleyen tek bir lacivert taş damlasıyla süslü gümüş bir halkadır; yüzüklerinin altında bir taş ustasının nasırları vardır.", "Reina de Ilavarta, Guardiana de los Estanques. Su corona es un aro de plata con una sola gota de lapislázuli, como un estanque visto desde arriba, y bajo los anillos tiene callos de cantero.", "Rainha de Ilavarta, Guardiã dos Tanques. Sua coroa é um aro de prata com uma única gota de lápis-lazúli, como um tanque visto de cima, e ela tem calos de pedreiro sob os anéis.", "Королева Илаварты, Хранительница прудов. Её корона — серебряный обруч с единственной каплей лазурита, как пруд, увиденный сверху, а под перстнями у неё мозоли каменщика.", "Королева Ілаварти, Хранителька ставів. Її корона — срібний обруч з єдиною краплею лазуриту, наче став, побачений згори, а під перснями в неї мозолі каменяра."],
  "The Queen's chief engineer: canals, sluices, tanks, and the silt in all of them. He carries a measuring rod and a list of costs, and uses both as arguments.": ["女王の主任技師。運河、水門、貯水池、そしてそのすべてに溜まる泥が担当だ。測量棒と費用の一覧を持ち歩き、どちらも議論の武器にする。", "여왕의 수석 기술자. 운하, 수문, 저수지, 그리고 그 모든 곳에 쌓이는 토사를 맡고 있다. 측량 막대와 비용 목록을 들고 다니며, 둘 다 논거로 휘두른다.", "女王的总工程师，管运河、水闸、水池，以及它们里面所有的淤泥。他随身带着一根测量杆和一张费用清单，两样都拿来当论据。", "女王的總工程師，管運河、水閘、水池，以及它們裡面所有的淤泥。他隨身帶著一根測量桿和一張費用清單，兩樣都拿來當論據。", "Kỹ sư trưởng của Nữ hoàng: kênh đào, cửa cống, hồ chứa, và bùn lắng trong tất cả chúng. Ông mang theo một cây thước đo và một bản kê chi phí, và dùng cả hai làm lý lẽ.", "Kepala insinyur Ratu: kanal, pintu air, telaga, dan lumpur di semuanya. Ia membawa tongkat ukur dan daftar biaya, dan memakai keduanya sebagai argumen.", "หัวหน้าวิศวกรของราชินี ดูแลคลอง ประตูน้ำ สระ และตะกอนในทุกแห่งนั้น เขาพกไม้วัดกับรายการค่าใช้จ่าย และใช้ทั้งสองอย่างเป็นข้อโต้แย้ง", "Kraliçe'nin baş mühendisi: kanallar, savaklar, havuzlar ve hepsinin içindeki balçık. Yanında bir ölçü sopası ve bir masraf listesi taşır, ikisini de birer argüman olarak kullanır.", "El ingeniero jefe de la reina: canales, compuertas, estanques y el limo de todos ellos. Lleva una vara de medir y una lista de costes, y usa las dos como argumentos.", "O engenheiro-chefe da rainha: canais, comportas, tanques e o lodo em todos eles. Carrega uma vara de medição e uma lista de custos, e usa as duas como argumentos.", "Главный инженер королевы: каналы, шлюзы, пруды и ил во всех них. Он носит с собой мерный шест и список расходов и пускает в ход то и другое как доводы.", "Головний інженер королеви: канали, шлюзи, стави й мул у всіх них. Він носить із собою мірну жердину та список витрат і пускає в хід і те, й інше як аргументи."],
  "Treasurer of the Tank Temple, which holds the offerings of three centuries. She says the offerings belong to the river; the engineers say the river needs them now.": ["貯水池の寺院の会計役。寺院には三百年分の供物が納められている。彼女は供物は川のものだと言い、技師たちは川には今それが必要なのだと言う。", "저수지 사원의 재무관. 사원에는 삼백 년 치 공물이 쌓여 있다. 그녀는 공물이 강의 것이라 하고, 기술자들은 강에 지금 그것이 필요하다고 한다.", "水池神庙的司库,庙里存着三百年的供奉。她说供奉属于河流,工程师们说河流现在就需要它们。", "水池神廟的司庫,廟裡存著三百年的供奉。她說供奉屬於河流,工程師們說河流現在就需要它們。", "Thủ quỹ của Đền Hồ, nơi cất giữ lễ vật của ba thế kỷ. Bà nói lễ vật thuộc về dòng sông; các kỹ sư nói dòng sông cần chúng ngay bây giờ.", "Bendahara Kuil Telaga, yang menyimpan persembahan tiga abad. Ia bilang persembahan itu milik sungai; para insinyur bilang sungai membutuhkannya sekarang.", "เหรัญญิกแห่งวิหารสระ ซึ่งเก็บเครื่องบูชาไว้สามศตวรรษ นางว่าเครื่องบูชาเป็นของแม่น้ำ ส่วนพวกวิศวกรว่าแม่น้ำต้องการมันตอนนี้เลย", "Üç yüzyılın adaklarını saklayan Havuz Tapınağı'nın haznedarı. Adakların nehre ait olduğunu söylüyor; mühendisler ise nehrin onlara şimdi ihtiyacı olduğunu.", "Tesorera del Templo del Estanque, que guarda las ofrendas de tres siglos. Ella dice que las ofrendas pertenecen al río; los ingenieros dicen que el río las necesita ya.", "Tesoureira do Templo do Tanque, que guarda as oferendas de três séculos. Ela diz que as oferendas pertencem ao rio; os engenheiros dizem que o rio precisa delas agora.", "Казначей Храма Пруда, где хранятся подношения трёх столетий. Она говорит, что подношения принадлежат реке; инженеры говорят, что реке они нужны сейчас.", "Скарбниця Храму Ставу, де зберігаються пожертви трьох століть. Вона каже, що пожертви належать річці; інженери кажуть, що річці вони потрібні зараз."],
  "A grain factor of the Gilded Court of Sefrah, in white linen, with a Kharaveth accent and a great deal of interest in the price of rice.": ["セフラの金色の宮廷の穀物代理商。白い亜麻布をまとい、カラヴェス訛りで話し、米の値段にひどく関心がある。", "세프라 황금 궁정의 곡물 중개인. 흰 아마포 차림에 카라베스 억양이 있고, 쌀값에 지대한 관심이 있다.", "塞弗拉镀金宫廷的粮食代理商,一身白亚麻,带着卡拉维斯口音,对米价兴趣浓厚。", "塞弗拉鍍金宮廷的糧食代理商,一身白亞麻,帶著卡拉維斯口音,對米價興趣濃厚。", "Một đại lý ngũ cốc của Triều Mạ Vàng xứ Sefrah, mặc vải lanh trắng, nói giọng Kharaveth và hết sức quan tâm đến giá gạo.", "Agen biji-bijian Istana Bersepuh dari Sefrah, berbalut linen putih, berlogat Kharaveth, dan sangat tertarik pada harga beras.", "ตัวแทนค้าธัญพืชของราชสำนักปิดทองแห่งเซฟราห์ สวมผ้าลินินขาว พูดสำเนียงคาราเวธ และสนใจราคาข้าวเป็นอย่างยิ่ง", "Sefrah'ın Yaldızlı Saray'ının tahıl kâhyası; beyaz keten giyinmiş, Kharaveth aksanıyla konuşuyor ve pirinç fiyatlarıyla fazlasıyla ilgileniyor.", "Un factor de grano de la Corte Dorada de Sefrah, vestido de lino blanco, con acento de Kharaveth y muchísimo interés por el precio del arroz.", "Um feitor de grãos da Corte Dourada de Sefrah, de linho branco, com sotaque de Kharaveth e um interesse enorme pelo preço do arroz.", "Хлебный фактор Позолоченного двора Сефры, в белом льне, с акцентом Харавета и живейшим интересом к цене на рис.", "Хлібний фактор Позолоченого двору Сефри, у білому льоні, з акцентом Харавета й неабияким інтересом до ціни на рис."],
  "Keeper of the Great Tank's ghats: sweeps the steps at dawn, lights the corner lamps at dusk, knows every family that bathes here by the way they come down.": ["大貯水池のガートの守り手。夜明けに石段を掃き、夕暮れに隅の灯をともし、ここで沐浴する家族を下りてくる様子で一つ残らず見分ける。", "대저수지 가트의 관리인. 새벽에 계단을 쓸고, 해 질 녘에 모퉁이 등불을 켜고, 여기서 목욕하는 집안을 내려오는 걸음새만 보고 모두 알아본다.", "大水池河阶的看守:黎明扫台阶,黄昏点角灯,凡在这里沐浴的人家,看他们走下来的样子就认得出。", "大水池河階的看守:黎明掃臺階,黃昏點角燈,凡在這裡沐浴的人家,看他們走下來的樣子就認得出。", "Người giữ các bậc ghat của Hồ Lớn: quét bậc lúc rạng đông, thắp đèn góc lúc chạng vạng, nhận ra mọi gia đình tắm ở đây qua dáng họ bước xuống.", "Penjaga tangga ghat Telaga Agung: menyapu anak tangga saat fajar, menyalakan lampu sudut saat senja, mengenali setiap keluarga yang mandi di sini dari cara mereka turun.", "ผู้ดูแลท่าน้ำของสระใหญ่ กวาดขั้นบันไดยามรุ่งสาง จุดตะเกียงมุมยามพลบค่ำ และจำได้ทุกครอบครัวที่มาอาบน้ำที่นี่จากท่าทางที่พวกเขาเดินลงมา", "Büyük Havuz'un gat basamaklarının bekçisi: şafakta basamakları süpürür, akşam karanlığında köşe kandillerini yakar, burada yıkanan her aileyi inişlerinden tanır.", "Guardián de los ghats del Gran Estanque: barre los escalones al alba, enciende las lámparas de las esquinas al anochecer y reconoce a cada familia que se baña aquí por su forma de bajar.", "Guardião dos ghats do Grande Tanque: varre os degraus ao amanhecer, acende as lamparinas dos cantos ao anoitecer e reconhece cada família que se banha aqui pelo jeito como desce.", "Смотритель гатов Великого пруда: на рассвете метёт ступени, в сумерках зажигает угловые лампы и узнаёт каждую семью, что здесь купается, по тому, как она спускается.", "Доглядач гатів Великого ставу: на світанку замітає сходи, у сутінках запалює кутові лампи й упізнає кожну родину, що тут купається, за тим, як вона спускається."],
  "Keeps the Queen's toll at the bridge south of Sarovan: by the head, by the cart, by the beast, and an extra copper for asking why.": ["サロヴァンの南の橋で女王の通行税を取り立てる。一人いくら、荷車いくら、家畜いくら、そして理由を尋ねたら銅貨一枚追加。", "사로반 남쪽 다리에서 여왕의 통행세를 걷는다. 사람당, 수레당, 짐승당, 그리고 왜냐고 물으면 동전 한 닢 추가.", "在萨罗万南边的桥上替女王收过路税:按人头、按车、按牲口,问一句为什么,再加一枚铜板。", "在薩羅萬南邊的橋上替女王收過路稅:按人頭、按車、按牲口,問一句為什麼,再加一枚銅板。", "Thu thuế cầu cho Nữ hoàng ở cây cầu phía nam Sarovan: tính theo đầu người, theo xe, theo gia súc, và thêm một đồng xu nếu hỏi tại sao.", "Memungut tol Ratu di jembatan selatan Sarovan: per kepala, per gerobak, per hewan, dan satu keping tembaga tambahan kalau bertanya kenapa.", "เก็บค่าผ่านทางของราชินีที่สะพานทางใต้ของสโรวัน คิดตามหัวคน ตามเกวียน ตามสัตว์ และเพิ่มอีกหนึ่งเหรียญทองแดงถ้าถามว่าทำไม", "Sarovan'ın güneyindeki köprüde Kraliçe'nin geçiş vergisini toplar: kişi başı, araba başı, hayvan başı ve nedenini sorana fazladan bir bakır.", "Cobra el peaje de la Reina en el puente al sur de Sarovan: por cabeza, por carro, por bestia, y un cobre más por preguntar por qué.", "Cobra o pedágio da Rainha na ponte ao sul de Sarovan: por cabeça, por carroça, por animal, e um cobre a mais por perguntar por quê.", "Взимает пошлину королевы на мосту к югу от Сарована: с головы, с телеги, со скотины и ещё медяк за вопрос «почему».", "Стягує мито королеви на мосту на південь від Сарована: з голови, з воза, з худоби й ще мідяк за питання «чому»."],
  "Keeps the general goods shop by the palace. Sells everything a household needs, and tells every customer what the palace is arguing about this week.": ["宮殿のそばの雑貨屋の主。家に要るものは何でも売っていて、客の一人一人に今週宮殿で何が揉めているかを教える。", "궁전 옆 잡화점 주인. 살림에 필요한 건 뭐든 팔고, 손님마다 이번 주에 궁전이 무엇으로 다투고 있는지 알려 준다.", "经营王宫旁的杂货铺。家里要用的东西样样都卖,还会告诉每位客人王宫这周在吵什么。", "經營王宮旁的雜貨鋪。家裡要用的東西樣樣都賣,還會告訴每位客人王宮這週在吵什麼。", "Giữ tiệm tạp hóa cạnh cung điện. Bán mọi thứ một gia đình cần, và kể cho mọi khách hàng nghe tuần này cung điện đang cãi nhau chuyện gì.", "Pemilik toko kelontong dekat istana. Menjual semua kebutuhan rumah tangga, dan memberi tahu setiap pembeli apa yang sedang diributkan istana minggu ini.", "เจ้าของร้านของชำข้างพระราชวัง ขายทุกอย่างที่บ้านหนึ่งต้องใช้ และบอกลูกค้าทุกคนว่าสัปดาห์นี้ในวังกำลังเถียงกันเรื่องอะไร", "Sarayın yanındaki bakkal dükkânını işletir. Bir evin ihtiyacı olan her şeyi satar ve her müşteriye sarayın bu hafta neyi tartıştığını anlatır.", "Lleva la tienda de ultramarinos junto al palacio. Vende todo lo que necesita un hogar y le cuenta a cada cliente por qué discute el palacio esta semana.", "Cuida do armazém ao lado do palácio. Vende tudo de que uma casa precisa e conta a cada freguês sobre o que o palácio está discutindo esta semana.", "Держит лавку всякой всячины у дворца. Продаёт всё, что нужно в хозяйстве, и каждому покупателю рассказывает, о чём во дворце спорят на этой неделе.", "Тримає крамницю всякої всячини біля палацу. Продає все, що треба в господарстві, і кожному покупцеві розповідає, про що в палаці сперечаються цього тижня."],
  "Sarovan's weaver, working tank blue and lotus white on a loom her grandmother built.": ["サロヴァンの織り手。祖母が作った機で、貯水池の青と蓮の白を織る。", "사로반의 직조공. 할머니가 만든 베틀로 저수지의 파랑과 연꽃의 하양을 짠다.", "萨罗万的织工,在祖母亲手造的织机上织出水池蓝和莲花白。", "薩羅萬的織工,在祖母親手造的織機上織出水池藍和蓮花白。", "Thợ dệt của Sarovan, dệt màu xanh hồ và trắng sen trên khung cửi do bà nội cô đóng.", "Penenun Sarovan, menenun biru telaga dan putih teratai di alat tenun buatan neneknya.", "ช่างทอผ้าแห่งสโรวัน ทอสีน้ำเงินสระและสีขาวดอกบัวบนกี่ที่ยายของนางสร้างไว้", "Sarovan'ın dokumacısı; büyükannesinin yaptığı tezgâhta havuz mavisi ve nilüfer beyazı dokur.", "La tejedora de Sarovan, que trabaja el azul estanque y el blanco loto en un telar que construyó su abuela.", "A tecelã de Sarovan, que tece azul-tanque e branco-lótus num tear que a avó construiu.", "Ткачиха Сарована: ткёт прудовую синь и лотосовую белизну на станке, который собрала её бабушка.", "Ткаля Сарована: тче ставкову синь і лотосову білизну на верстаті, який збудувала її бабуся."],
  "Keeps the Lotus Inn, and has opinions about everyone who has ever eaten in it, mostly kind.": ["蓮華亭の主。そこで食事をしたことのある全員について意見を持っていて、たいていは優しい意見だ。", "연꽃 여관 주인. 거기서 밥을 먹어 본 모든 사람에 대해 의견이 있고, 대개는 너그럽다.", "经营莲花客栈,对每一个在店里吃过饭的人都有看法,大多是好话。", "經營蓮花客棧,對每一個在店裡吃過飯的人都有看法,大多是好話。", "Giữ Quán Hoa Sen, và có ý kiến về tất cả những ai từng ăn ở đó, phần lớn là tử tế.", "Pemilik Penginapan Teratai, dan punya pendapat tentang semua orang yang pernah makan di sana, kebanyakan baik.", "เจ้าของโรงเตี๊ยมดอกบัว มีความเห็นเกี่ยวกับทุกคนที่เคยมากินที่นี่ ส่วนใหญ่เป็นความเห็นดี ๆ", "Nilüfer Hanı'nın sahibi; orada yemek yemiş herkes hakkında bir fikri var, çoğu da iyi.", "Regenta la Posada del Loto y tiene opinión sobre todo el que ha comido en ella alguna vez, casi siempre amable.", "Cuida da Estalagem do Lótus e tem opinião sobre todo mundo que já comeu lá, quase sempre gentil.", "Держит трактир «Лотос» и имеет мнение обо всех, кто там когда-либо ел, в основном доброе.", "Тримає корчму «Лотос» і має думку про всіх, хто там будь-коли їв, здебільшого добру."],
  "Sarovan's smith: sluice gates for the engineers, sabres for the tank guards, and a temper for the treasurers, who are slow to pay for either.": ["サロヴァンの鍛冶屋。技師には水門を、貯水池の衛兵には湾刀を、そして会計役には癇癪を。どちらの代金も払うのが遅いからだ。", "사로반의 대장장이. 기술자에겐 수문을, 저수지 경비병에겐 곡도를, 그리고 재무관들에겐 성깔을. 그들은 어느 쪽 값도 늦게 치르니까.", "萨罗万的铁匠:给工程师打水闸,给水池卫兵打弯刀,给司库们一副坏脾气,因为这两样他们都拖着不付钱。", "薩羅萬的鐵匠:給工程師打水閘,給水池衛兵打彎刀,給司庫們一副壞脾氣,因為這兩樣他們都拖著不付錢。", "Thợ rèn của Sarovan: cửa cống cho các kỹ sư, kiếm cong cho lính gác hồ, và cơn nóng nảy cho các thủ quỹ, những người chậm trả tiền cho cả hai.", "Pandai besi Sarovan: pintu air untuk para insinyur, pedang lengkung untuk pengawal telaga, dan amarah untuk para bendahara, yang lamban membayar keduanya.", "ช่างตีเหล็กแห่งสโรวัน ประตูระบายน้ำให้วิศวกร ดาบโค้งให้ทหารเฝ้าสระ และอารมณ์ร้ายให้พวกเหรัญญิก ผู้จ่ายเงินช้าทั้งสองอย่าง", "Sarovan'ın demircisi: mühendislere savak kapakları, havuz muhafızlarına kılıç ve ikisinin parasını da geç ödeyen haznedarlara öfke.", "La herrera de Sarovan: compuertas para los ingenieros, sables para los guardias del estanque y mal genio para los tesoreros, que tardan en pagar ambas cosas.", "A ferreira de Sarovan: comportas para os engenheiros, sabres para os guardas do tanque e mau humor para os tesoureiros, que demoram a pagar por ambos.", "Кузнечиха Сарована: шлюзовые затворы для инженеров, сабли для стражи пруда и крутой нрав для казначеев, которые не спешат платить ни за то, ни за другое.", "Ковалиха Сарована: шлюзові затвори для інженерів, шаблі для варти ставу й крутий норов для скарбників, які не поспішають платити ні за те, ні за інше."],
  "One of the Queen's tank guards, in blue and white, a curved sabre at the hip and a water-measure on a cord round the neck.": ["女王の貯水池の衛兵の一人。青と白をまとい、腰に湾刀、首には紐で吊った水量計。", "여왕의 저수지 경비병 중 하나. 파랑과 하양 차림에 허리엔 곡도, 목엔 끈에 매단 물 계량기.", "女王的水池卫兵之一,一身蓝白,腰挎弯刀,脖子上用绳挂着一个量水器。", "女王的水池衛兵之一,一身藍白,腰挎彎刀,脖子上用繩掛著一個量水器。", "Một lính gác hồ của Nữ hoàng, mặc xanh và trắng, kiếm cong bên hông và một thước đo nước đeo dây quanh cổ.", "Salah satu pengawal telaga Ratu, berbaju biru dan putih, pedang lengkung di pinggang dan alat ukur air bertali di leher.", "ทหารเฝ้าสระคนหนึ่งของราชินี สวมชุดน้ำเงินขาว ดาบโค้งที่สะเอว และเครื่องวัดน้ำห้อยเชือกไว้ที่คอ", "Kraliçe'nin havuz muhafızlarından biri; mavi beyaz giysili, belinde eğri bir kılıç, boynunda iple asılı bir su ölçeği.", "Uno de los guardias del estanque de la Reina, de azul y blanco, con un sable curvo al cinto y una medida de agua colgada del cuello con un cordón.", "Um dos guardas do tanque da Rainha, de azul e branco, com um sabre curvo na cintura e uma medida de água pendurada no pescoço por um cordão.", "Один из стражников пруда королевы, в синем и белом, с кривой саблей на бедре и водомером на шнурке на шее.", "Один із вартових ставу королеви, у синьому й білому, з кривою шаблею при боці й водоміром на шнурку на шиї."],
  "A citizen of Sarovan on the way to the ghats, or the market, or the palace gate to hear what's been decided.": ["ガートへ、市場へ、あるいは何が決まったかを聞きに宮殿の門へ向かう途中のサロヴァンの市民。", "가트로, 시장으로, 혹은 무엇이 결정됐는지 들으러 궁전 문으로 가는 길인 사로반 시민.", "一位萨罗万市民,正要去河阶,或去集市,或去王宫门口听听又决定了什么。", "一位薩羅萬市民,正要去河階,或去市集,或去王宮門口聽聽又決定了什麼。", "Một thị dân Sarovan đang trên đường ra bậc ghat, hoặc ra chợ, hoặc đến cổng cung điện nghe xem người ta đã quyết định gì.", "Warga Sarovan dalam perjalanan ke tangga ghat, atau ke pasar, atau ke gerbang istana untuk mendengar apa yang sudah diputuskan.", "ชาวสโรวันที่กำลังไปท่าน้ำ หรือไปตลาด หรือไปหน้าประตูวังเพื่อฟังว่าตัดสินอะไรกันไปแล้ว", "Gat basamaklarına, pazara ya da neyin karara bağlandığını duymak için saray kapısına giden bir Sarovanlı.", "Un ciudadano de Sarovan de camino a los ghats, o al mercado, o a la puerta del palacio a enterarse de lo que se ha decidido.", "Um cidadão de Sarovan a caminho dos ghats, ou do mercado, ou do portão do palácio para saber o que foi decidido.", "Горожанин Сарована по дороге к гатам, или на рынок, или к дворцовым воротам — узнать, что решили.", "Містянин Сарована дорогою до гатів, чи на ринок, чи до палацової брами — дізнатися, що вирішили."],
  "Lord of Shailagarh, the passes and the mines. A big quiet man in highland wool and fine mail, who listens until you've finished and then a little longer.": ["シャイラガルと、峠と、鉱山の領主。高地の羊毛と上等な鎖帷子をまとった大柄で寡黙な男で、こちらが話し終えるまで、そしてそのあと少し長く耳を傾ける。", "샤일라가르와 고개들과 광산의 영주. 고원 양모와 고운 사슬갑옷을 걸친 덩치 크고 과묵한 사내로, 당신이 말을 다 마칠 때까지, 그리고 그 뒤로도 조금 더 듣는다.", "沙伊拉加尔、诸山口与矿山的领主。一个身穿高地羊毛与精制锁甲的高大沉默男子,会一直听到你说完,然后再多听一会儿。", "沙伊拉加爾、諸山口與礦山的領主。一個身穿高地羊毛與精製鎖甲的高大沉默男子,會一直聽到你說完,然後再多聽一會兒。", "Lãnh chúa của Shailagarh, các con đèo và các mỏ. Một người đàn ông to lớn, trầm lặng, mặc len cao nguyên và giáp xích tốt, lắng nghe cho đến khi bạn nói xong rồi thêm một chút nữa.", "Penguasa Shailagarh, celah-celah gunung, dan tambang-tambang. Lelaki besar pendiam berbalut wol dataran tinggi dan zirah rantai halus, yang mendengarkan sampai kau selesai bicara, lalu sedikit lebih lama lagi.", "เจ้าครองไศลครห์ ช่องเขา และเหมือง ชายร่างใหญ่ผู้เงียบขรึมในชุดขนแกะที่ราบสูงและเกราะโซ่ชั้นดี ผู้ฟังจนคุณพูดจบ แล้วฟังต่ออีกสักหน่อย", "Shailagarh'ın, geçitlerin ve madenlerin lordu. Yayla yünü ve ince zincir zırh giymiş iri, sessiz bir adam; siz sözünüzü bitirene kadar, sonra da biraz daha dinler.", "Señor de Shailagarh, de los pasos y de las minas. Un hombre grande y callado, con lana de las tierras altas y una malla fina, que escucha hasta que terminas y luego un poco más.", "Senhor de Shailagarh, dos passos e das minas. Um homem grande e calado, de lã das terras altas e cota de malha fina, que escuta até você terminar e depois mais um pouco.", "Лорд Шайлагарха, перевалов и рудников. Крупный молчаливый человек в горской шерсти и тонкой кольчуге, который слушает, пока вы не закончите, и ещё немного после.", "Лорд Шайлагарха, перевалів і копалень. Кремезний мовчазний чоловік у гірській вовні й тонкій кольчузі, який слухає, доки ви не закінчите, і ще трохи по тому."],
  "Captain of a Copper Banner company out of Khetmar, hired by Lord Varanjit by the season. She'll tell you she's a soldier, not a guest, and Ilavarta that she's neither.": ["ケトマルから来た銅の旗の一隊の隊長で、ヴァランジット卿に季節ごとに雇われている。本人は自分は客ではなく兵士だと言うが、イラヴァルタに言わせればそのどちらでもない。", "케트마르에서 온 구리 깃발 부대의 대장으로, 바란지트 경에게 철마다 고용된다. 본인은 자기가 손님이 아니라 군인이라고 하고, 일라바르타는 그 어느 쪽도 아니라고 한다.", "来自克特马尔的铜旗佣兵队队长,按季受雇于瓦兰吉特大人。她会告诉你她是军人,不是客人。伊拉瓦塔则会告诉你,她两样都不是。", "來自克特馬爾的銅旗傭兵隊隊長,按季受僱於瓦蘭吉特大人。她會告訴你她是軍人,不是客人。伊拉瓦塔則會告訴你,她兩樣都不是。", "Đội trưởng một đại đội Cờ Đồng từ Khetmar, được Lãnh chúa Varanjit thuê theo mùa. Cô sẽ nói với bạn rằng cô là lính, không phải khách, còn Ilavarta thì bảo cô chẳng phải cả hai.", "Kapten sebuah kompi Panji Tembaga dari Khetmar, disewa Tuan Varanjit per musim. Ia akan bilang dirinya prajurit, bukan tamu, dan Ilavarta akan bilang ia bukan keduanya.", "ร้อยเอกของกองร้อยธงทองแดงจากเคทมาร์ ที่ท่านวรัญชิตจ้างไว้เป็นฤดู ๆ นางจะบอกคุณว่านางเป็นทหาร ไม่ใช่แขก ส่วนอิลาวรรตะจะบอกว่านางไม่ใช่ทั้งสองอย่าง", "Khetmar'dan gelen bir Bakır Sancak bölüğünün yüzbaşısı; Lord Varanjit onu mevsimlik tutuyor. Size misafir değil asker olduğunu söyler; Ilavarta ise ikisi de olmadığını.", "Capitana de una compañía del Estandarte de Cobre venida de Khetmar, contratada por el señor Varanjit por temporadas. Te dirá que es soldado, no invitada, e Ilavarta te dirá que no es ninguna de las dos cosas.", "Capitã de uma companhia do Estandarte de Cobre vinda de Khetmar, contratada pelo senhor Varanjit por temporada. Ela vai dizer que é soldado, não hóspede, e Ilavarta vai dizer que não é nenhum dos dois.", "Капитан роты Медного знамени из Кетмара, которую лорд Варанджит нанимает посезонно. Она скажет вам, что она солдат, а не гостья, а Илаварта — что она ни то ни другое.", "Капітанка роти Мідного стягу з Кетмара, яку лорд Варанджит наймає посезонно. Вона скаже вам, що вона солдатка, а не гостя, а Ілаварта — що вона ні те, ні інше."],
  "Shailagarh's assayer, who tests every ingot that leaves the mines, and trades letters about furnaces with the Obsidian Legacy's masons at Tamesh.": ["シャイラガルの試金師。鉱山から出るインゴットをすべて検め、タメシュにいる黒曜の遺統の石工たちと炉についての手紙をやり取りしている。", "샤일라가르의 시금관. 광산에서 나가는 모든 주괴를 시험하고, 타메시에 있는 흑요 유산의 석공들과 용광로에 관한 편지를 주고받는다.", "沙伊拉加尔的化验师,检验每一块运出矿山的锭子,还和塔梅什的黑曜遗脉石匠们通信讨论熔炉。", "沙伊拉加爾的化驗師,檢驗每一塊運出礦山的錠子,還和塔梅什的黑曜遺脈石匠們通信討論熔爐。", "Thợ kiểm kim của Shailagarh, người thử mọi thỏi kim loại rời khỏi mỏ, và trao đổi thư từ về lò luyện với những thợ đá của Di Sản Hắc Diện ở Tamesh.", "Penguji logam Shailagarh, yang menguji setiap batangan yang keluar dari tambang, dan berkirim surat tentang tungku dengan para tukang batu Warisan Obsidian di Tamesh.", "นักตรวจแร่แห่งไศลครห์ ผู้ทดสอบแท่งโลหะทุกแท่งที่ออกจากเหมือง และเขียนจดหมายคุยเรื่องเตาหลอมกับช่างหินของมรดกออบซิเดียนที่ทาเมช", "Shailagarh'ın ayarcısı; madenlerden çıkan her külçeyi test eder ve Tamesh'teki Obsidyen Mirası taş ustalarıyla fırınlar üzerine mektuplaşır.", "El ensayador de Shailagarh, que prueba cada lingote que sale de las minas y se cartea sobre hornos con los canteros del Legado de Obsidiana en Tamesh.", "O ensaiador de Shailagarh, que testa cada lingote que sai das minas e troca cartas sobre fornalhas com os pedreiros do Legado de Obsidiana em Tamesh.", "Пробирщик Шайлагарха, который проверяет каждый слиток, покидающий рудники, и переписывается о печах с каменщиками Обсидианового наследия в Тамеше.", "Пробірник Шайлагарха, який перевіряє кожен злиток, що залишає копальні, і листується про печі з мулярами Обсидіанової спадщини в Тамеші."],
  "Keeps the stores on the fortress road. Everything up here costs more, he says, because everything up here had to climb.": ["砦への道沿いの店の主。ここでは何でも高い、と彼は言う。ここにあるものは何でも登ってこなければならなかったからだ。", "요새 길목의 가게 주인. 그의 말로는 여기선 뭐든 더 비싸다. 여기 있는 건 뭐든 올라와야 했으니까.", "经营要塞路上的货栈。他说这上面什么都更贵,因为这上面的东西都是爬上来的。", "經營要塞路上的貨棧。他說這上面什麼都更貴,因為這上面的東西都是爬上來的。", "Giữ cửa hàng trên đường lên pháo đài. Ông nói trên này cái gì cũng đắt hơn, vì cái gì lên được đây cũng phải leo.", "Pemilik toko di jalan benteng. Di atas sini semuanya lebih mahal, katanya, karena semua yang ada di atas sini harus mendaki.", "เจ้าของร้านบนถนนสู่ป้อม เขาว่าข้างบนนี้อะไรก็แพงกว่า เพราะทุกอย่างบนนี้ต้องปีนขึ้นมา", "Kale yolundaki dükkânı işletir. Burada her şey daha pahalı, der, çünkü buradaki her şey tırmanmak zorunda kaldı.", "Lleva la tienda del camino de la fortaleza. Aquí arriba todo cuesta más, dice, porque todo lo que hay aquí arriba tuvo que subir.", "Cuida do armazém na estrada da fortaleza. Aqui em cima tudo custa mais, diz ele, porque tudo aqui em cima teve que subir.", "Держит лавку на крепостной дороге. Здесь, наверху, всё дороже, говорит он, потому что всему здесь пришлось карабкаться.", "Тримає крамницю на фортечній дорозі. Тут, нагорі, усе дорожче, каже він, бо всьому тут довелося дертися вгору."],
  "Spins and weaves the highland wool, and can tell a pass-born sheep from a valley sheep by the feel of the yarn.": ["高地の羊毛を紡ぎ、織る。糸の手触りだけで、峠生まれの羊か谷の羊かを見分けられる。", "고원 양모를 잣고 짠다. 실의 감촉만으로 고개에서 난 양과 골짜기 양을 구별할 수 있다.", "纺织高地羊毛,摸一摸毛线就能分出是山口生的羊还是河谷里的羊。", "紡織高地羊毛,摸一摸毛線就能分出是山口生的羊還是河谷裡的羊。", "Kéo sợi và dệt len cao nguyên, và chỉ cần sờ sợi len là phân biệt được cừu sinh ở đèo với cừu ở thung lũng.", "Memintal dan menenun wol dataran tinggi, dan bisa membedakan domba lahir celah gunung dari domba lembah hanya dari rasa benangnya.", "ปั่นและทอขนแกะที่ราบสูง และแยกแกะที่เกิดบนช่องเขาออกจากแกะในหุบเขาได้แค่จากสัมผัสของเส้นด้าย", "Yayla yününü eğirir ve dokur; ipliğe dokunarak geçitte doğmuş bir koyunu vadi koyunundan ayırt edebilir.", "Hila y teje la lana de las tierras altas, y distingue una oveja nacida en el paso de una del valle solo con tocar el hilo.", "Fia e tece a lã das terras altas, e sabe distinguir uma ovelha nascida no passo de uma do vale só pelo toque do fio.", "Прядёт и ткёт горскую шерсть и на ощупь пряжи отличит овцу, рождённую на перевале, от долинной.", "Пряде й тче гірську вовну і на дотик пряжі відрізнить вівцю, народжену на перевалі, від долинної."],
  "Keeps the Pass Fire. The fire hasn't gone out in forty years, and neither has Old Hari's pipe.": ["峠の火の番人。火は四十年間一度も消えたことがなく、ハリ爺さんのキセルも同じだ。", "고개의 불을 지킨다. 그 불은 사십 년 동안 한 번도 꺼진 적이 없고, 하리 영감의 담뱃대도 마찬가지다.", "看守山口之火。这火四十年没灭过,老哈里的烟斗也是。", "看守山口之火。這火四十年沒滅過,老哈里的菸斗也是。", "Giữ Lửa Đèo. Ngọn lửa chưa tắt suốt bốn mươi năm, và tẩu thuốc của Lão Hari cũng vậy.", "Penjaga Api Celah. Api itu tak pernah padam selama empat puluh tahun, begitu pula pipa Pak Tua Hari.", "ผู้เฝ้าไฟช่องเขา ไฟนี้ไม่เคยดับมาสี่สิบปี และกล้องยาสูบของตาหริก็เช่นกัน", "Geçit Ateşi'ni bekler. Ateş kırk yıldır sönmedi, Yaşlı Hari'nin piposu da.", "Cuida el Fuego del Paso. El fuego no se ha apagado en cuarenta años, y la pipa del viejo Hari tampoco.", "Cuida do Fogo do Passo. O fogo não se apaga há quarenta anos, e o cachimbo do velho Hari também não.", "Хранит Огонь Перевала. Огонь не гас сорок лет, и трубка старого Хари тоже.", "Береже Вогонь Перевалу. Вогонь не згасав сорок років, і люлька старого Харі теж."],
  "Shailagarh's forge-master, who makes Shaila mail one ring at a time and signs each coat inside the collar.": ["シャイラガルの鍛冶頭。シャイラ鎖帷子を輪ひとつずつ編み上げ、一着ごとに襟の内側へ署名を入れる。", "샤일라가르의 대장간 우두머리. 샤일라 사슬갑옷을 고리 하나하나 엮어 만들고, 한 벌마다 깃 안쪽에 서명을 남긴다.", "沙伊拉加尔的锻造师傅,一环一环地打造沙伊拉锁甲,并在每件甲衣的领子内侧签上名字。", "沙伊拉加爾的鍛造師傅,一環一環地打造沙伊拉鎖甲,並在每件甲衣的領子內側簽上名字。", "Thợ cả lò rèn của Shailagarh, người làm giáp xích Shaila từng vòng một và ký tên vào mặt trong cổ áo của mỗi bộ.", "Kepala tempa Shailagarh, yang membuat zirah rantai Shaila satu cincin demi satu cincin dan menandatangani setiap baju zirah di bagian dalam kerahnya.", "นายช่างโรงตีเหล็กแห่งไศลครห์ ผู้สร้างเกราะโซ่ไศลาทีละห่วง และลงชื่อไว้ด้านในปกคอของเกราะทุกตัว", "Shailagarh'ın demirhane ustası; Shaila zırhını halka halka örer ve her zırh gömleğini yakasının içinden imzalar.", "El maestro forjador de Shailagarh, que hace la malla de Shaila anilla a anilla y firma cada cota por dentro del cuello.", "O mestre forjador de Shailagarh, que faz a cota de malha de Shaila um anel de cada vez e assina cada peça por dentro da gola.", "Мастер кузни Шайлагарха, который собирает кольчуги Шайлы по одному кольцу и подписывает каждую изнутри воротника.", "Майстер кузні Шайлагарха, який збирає кольчуги Шайли по одному кільцю й підписує кожну зсередини коміра."],
  "A sentry of the fortress in a red blanket-cloak, watching the passes, the mines, and lately the Copper Banner's companies.": ["赤い毛布のマントを羽織った砦の歩哨。峠を、鉱山を、そして近ごろは銅の旗の部隊を見張っている。", "붉은 담요 망토를 두른 요새의 보초. 고개와 광산을, 그리고 요즘은 구리 깃발의 부대들을 지켜본다.", "披着红毯斗篷的要塞哨兵,盯着山口、矿山,最近还盯着铜旗的佣兵队。", "披著紅毯斗篷的要塞哨兵,盯著山口、礦山,最近還盯著銅旗的傭兵隊。", "Một lính canh pháo đài khoác áo choàng chăn đỏ, canh chừng các con đèo, các mỏ, và dạo gần đây là các đại đội Cờ Đồng.", "Penjaga benteng berjubah selimut merah, mengawasi celah-celah gunung, tambang, dan belakangan ini kompi-kompi Panji Tembaga.", "ทหารยามของป้อมในเสื้อคลุมผ้าห่มสีแดง คอยเฝ้าช่องเขา เหมือง และช่วงนี้ก็เฝ้ากองร้อยของธงทองแดงด้วย", "Kırmızı battaniye pelerinli bir kale nöbetçisi; geçitleri, madenleri ve son zamanlarda Bakır Sancak'ın bölüklerini gözlüyor.", "Un centinela de la fortaleza con una capa-manta roja, que vigila los pasos, las minas y, últimamente, las compañías del Estandarte de Cobre.", "Um sentinela da fortaleza de capa-cobertor vermelha, vigiando os passos, as minas e, ultimamente, as companhias do Estandarte de Cobre.", "Часовой крепости в красном плаще-одеяле, следящий за перевалами, рудниками, а с недавних пор и за ротами Медного знамени.", "Вартовий фортеці в червоному плащі-ковдрі, що стежить за перевалами, копальнями, а віднедавна й за ротами Мідного стягу."],
  "A miner of the highland seams, grey with rock dust, a lamp on a hook and a pick over the shoulder.": ["高地の鉱脈で働く鉱夫。岩の粉で灰色になり、鉤にランプを掛け、肩につるはしを担いでいる。", "고원 광맥의 광부. 돌가루를 뒤집어써 잿빛이고, 갈고리에 등불을 걸고 어깨에 곡괭이를 메었다.", "高地矿脉的矿工,浑身石粉灰扑扑的,钩上挂着灯,肩上扛着镐。", "高地礦脈的礦工,渾身石粉灰撲撲的,鉤上掛著燈,肩上扛著鎬。", "Một thợ mỏ của các vỉa quặng cao nguyên, xám xịt bụi đá, đèn treo trên móc và cuốc chim vác trên vai.", "Penambang dari urat-urat dataran tinggi, kelabu oleh debu batu, lampu tergantung di kait dan beliung di bahu.", "คนงานเหมืองแห่งสายแร่บนที่ราบสูง ตัวเทาไปด้วยฝุ่นหิน ตะเกียงแขวนบนตะขอ และจอบแบกไว้บนบ่า", "Yayla damarlarının bir madencisi; kaya tozundan griye kesmiş, kancada bir lamba, omzunda bir kazma.", "Un minero de las vetas de las tierras altas, gris de polvo de roca, con un candil en un gancho y un pico al hombro.", "Um mineiro dos veios das terras altas, cinzento de pó de pedra, com uma lamparina num gancho e uma picareta no ombro.", "Рудокоп горных жил, серый от каменной пыли, с лампой на крюке и кайлом на плече.", "Гірник гірських жил, сірий від кам'яного пилу, з лампою на гаку й кайлом на плечі."],
  "Someone of the fortress town in highland wool, cheeks red with the wind.": ["高地の羊毛を着た砦の町の誰か。頬が風で赤い。", "고원 양모를 입은 요새 마을 사람. 뺨이 바람에 붉다.", "要塞小城里的某个人,穿着高地羊毛,脸颊被风吹得通红。", "要塞小城裡的某個人,穿著高地羊毛,臉頰被風吹得通紅。", "Một người ở thị trấn pháo đài mặc len cao nguyên, má đỏ ửng vì gió.", "Seseorang dari kota benteng berbalut wol dataran tinggi, pipinya merah diterpa angin.", "ใครสักคนจากเมืองป้อมในชุดขนแกะที่ราบสูง แก้มแดงเพราะลม", "Kale kasabasından, yayla yünü giymiş, yanakları rüzgârdan kızarmış biri.", "Alguien del pueblo de la fortaleza, con lana de las tierras altas y las mejillas rojas por el viento.", "Alguém da cidade da fortaleza, de lã das terras altas, com as bochechas vermelhas de vento.", "Кто-то из крепостного городка в горской шерсти, щёки красные от ветра.", "Хтось із фортечного містечка в гірській вовні, щоки червоні від вітру."],
  "Speaker of the League of Seven Parasols for this year, the ruler of Hemapura for the rest of her life. She speaks for all seven and is careful to sound like none of them.": ["今年の七つの日傘同盟の議長にして、生涯にわたるヘマプラの統治者。七者すべてを代表して語り、そのどれにも似て聞こえないよう気を配っている。", "올해 일곱 일산 동맹의 의장이자, 평생 헤마푸라의 통치자. 일곱 모두를 대변해 말하되, 그 누구와도 닮게 들리지 않도록 조심한다.", "今年的七华盖同盟议长,终身的赫玛普拉统治者。她代表七方发言,并小心地让自己听起来不像其中任何一方。", "今年的七華蓋同盟議長,終身的赫瑪普拉統治者。她代表七方發言,並小心地讓自己聽起來不像其中任何一方。", "Phát ngôn nhân của Liên minh Bảy Lọng năm nay, người cai trị Hemapura suốt phần đời còn lại. Bà nói thay cho cả bảy và cẩn thận để không giống giọng ai trong số họ.", "Juru Bicara Liga Tujuh Payung tahun ini, penguasa Hemapura seumur hidupnya. Ia berbicara atas nama ketujuhnya dan berhati-hati agar tak terdengar seperti salah satu dari mereka.", "ประธานสันนิบาตเจ็ดฉัตรประจำปีนี้ และผู้ปกครองเหมปุระไปตลอดชีวิต นางพูดแทนทั้งเจ็ด และระวังไม่ให้ฟังดูเหมือนใครในนั้นเลย", "Bu yılın Yedi Şemsiye Birliği Sözcüsü, ömrünün geri kalanında da Hemapura'nın hükümdarı. Yedisi adına konuşur ve hiçbirine benzememeye özen gösterir.", "Portavoz de la Liga de los Siete Parasoles este año y soberana de Hemapura el resto de su vida. Habla por los siete y se cuida de no sonar como ninguno.", "Porta-voz da Liga dos Sete Para-sóis este ano e soberana de Hemapura pelo resto da vida. Fala pelos sete e toma cuidado para não soar como nenhum deles.", "Глашатай Лиги Семи Зонтов на этот год и правительница Хемапуры до конца своих дней. Она говорит за всех семерых и старается не звучать ни как один из них.", "Речниця Ліги Семи Парасолів цього року й володарка Хемапури до кінця своїх днів. Вона говорить за всіх сімох і дбає, щоб не звучати як жоден із них."],
  "The ruler of the Salt Fens, smallest of the seven, whose parasol is white and whose vote is always for sale, he says, though nobody has ever afforded it.": ["七者のうち最も小さい塩沼の統治者。その日傘は白く、本人いわく票はいつでも売り物だが、それを買えた者はまだ一人もいない。", "일곱 중 가장 작은 소금 늪의 통치자. 그의 일산은 하얗고, 본인 말로는 그의 표는 언제나 팔려고 내놓은 것이지만, 아직 그 값을 감당한 이는 아무도 없다.", "盐沼的统治者,七方中最小的一方。他的华盖是白色的,他说他的票永远待价而沽,只是从来没人出得起价。", "鹽沼的統治者,七方中最小的一方。他的華蓋是白色的,他說他的票永遠待價而沽,只是從來沒人出得起價。", "Người cai trị Đầm Muối, nhỏ nhất trong bảy, có lọng màu trắng và lá phiếu, theo lời ông, lúc nào cũng rao bán, dù chưa ai từng trả nổi.", "Penguasa Rawa Garam, yang terkecil dari ketujuhnya, yang payungnya putih dan suaranya selalu dijual, katanya, meski belum pernah ada yang sanggup membelinya.", "ผู้ปกครองบึงเกลือ ดินแดนเล็กที่สุดในเจ็ด ฉัตรของเขาเป็นสีขาว และเขาว่าเสียงโหวตของเขาขายเสมอ แม้ยังไม่เคยมีใครจ่ายไหว", "Yedinin en küçüğü olan Tuz Bataklıkları'nın hükümdarı; şemsiyesi beyazdır ve oyu, kendi dediğine göre, her zaman satılıktır, gerçi bugüne dek kimse fiyatını karşılayamadı.", "El soberano de las Ciénagas de Sal, el más pequeño de los siete, cuyo parasol es blanco y cuyo voto siempre está en venta, según dice, aunque nadie ha podido pagarlo jamás.", "O soberano dos Pântanos de Sal, o menor dos sete, cujo para-sol é branco e cujo voto está sempre à venda, diz ele, embora ninguém jamais tenha podido pagá-lo.", "Правитель Соляных Топей, самого маленького из семи владений; его зонт белый, а его голос, по его словам, всегда продаётся, хотя никому ещё не хватило денег.", "Володар Соляних Боліт, найменшого із семи володінь; його парасоль білий, а його голос, за його словами, завжди продається, хоча ще нікому не вистачило грошей."],
  "Keeps the League's toll books. Seven rulers, seven rates, one clerk, and he has never once been thanked.": ["同盟の通行税帳簿をつけている。七人の統治者、七つの税率、書記は一人。そして一度たりとも礼を言われたことがない。", "동맹의 통행세 장부를 맡고 있다. 통치자 일곱, 세율 일곱, 서기는 하나, 그리고 그는 단 한 번도 감사 인사를 받은 적이 없다.", "掌管同盟的关税账簿。七位统治者,七种税率,一个书记,而他从没被谢过一次。", "掌管同盟的關稅帳簿。七位統治者,七種稅率,一個書記,而他從沒被謝過一次。", "Giữ sổ thuế của Liên minh. Bảy người cai trị, bảy mức thuế, một thư lại, và chưa một lần được ai cảm ơn.", "Pemegang buku tol Liga. Tujuh penguasa, tujuh tarif, satu juru tulis, dan ia tak pernah sekali pun diberi ucapan terima kasih.", "ดูแลสมุดบัญชีค่าผ่านทางของสันนิบาต ผู้ปกครองเจ็ดคน อัตราเจ็ดแบบ เสมียนหนึ่งคน และเขาไม่เคยได้รับคำขอบคุณสักครั้ง", "Birlik'in geçiş vergisi defterlerini tutar. Yedi hükümdar, yedi tarife, tek kâtip ve bir kez bile teşekkür görmedi.", "Lleva los libros de peajes de la Liga. Siete soberanos, siete tarifas, un escribano, y jamás le han dado las gracias.", "Cuida dos livros de pedágio da Liga. Sete soberanos, sete tarifas, um escrivão, e ninguém nunca lhe agradeceu.", "Ведёт пошлинные книги Лиги. Семь правителей, семь ставок, один писарь, и ему ни разу не сказали спасибо.", "Веде митні книги Ліги. Сім володарів, сім ставок, один писар, і йому жодного разу не подякували."],
  "Keeps the stores across from the Mandapa, and sells the delegations everything they forgot to bring, which is everything.": ["マンダパの向かいの店の主。使節団が持ってくるのを忘れたものをすべて売っている。つまり、何もかもだ。", "만다파 맞은편 가게 주인. 사절단이 깜빡하고 안 가져온 것을 모두 판다. 즉, 전부 다.", "经营曼达帕对面的货栈,把各代表团忘带的东西统统卖给他们,而他们什么都忘了带。", "經營曼達帕對面的貨棧,把各代表團忘帶的東西統統賣給他們,而他們什麼都忘了帶。", "Giữ cửa hàng đối diện Mandapa, bán cho các phái đoàn mọi thứ họ quên mang, tức là mọi thứ.", "Pemilik toko di seberang Mandapa, menjual kepada para delegasi semua yang lupa mereka bawa, yaitu semuanya.", "เจ้าของร้านตรงข้ามมณฑป ขายทุกอย่างที่คณะผู้แทนลืมเอามา ซึ่งก็คือทุกอย่าง", "Mandapa'nın karşısındaki dükkânı işletir ve heyetlere getirmeyi unuttukları her şeyi satar, yani her şeyi.", "Lleva la tienda frente al Mandapa y les vende a las delegaciones todo lo que olvidaron traer, que es todo.", "Cuida do armazém em frente ao Mandapa e vende às delegações tudo o que esqueceram de trazer, ou seja, tudo.", "Держит лавку напротив Мандапы и продаёт делегациям всё, что они забыли привезти, то есть всё.", "Тримає крамницю навпроти Мандапи й продає делегаціям усе, що вони забули привезти, тобто все."],
  "Weaves the League's delegates their coats, cords and all, and knows exactly how each of the seven ties them.": ["同盟の代表たちの上着を、飾り紐まで含めて織り上げる。七者それぞれがどう紐を結ぶかを正確に知っている。", "동맹 대표들의 겉옷을 끈까지 통째로 짜 주고, 일곱 측이 각각 그 끈을 어떻게 매는지 정확히 안다.", "为同盟代表们织外衣,连带饰绳一并织好,七方各自怎么系绳,她一清二楚。", "為同盟代表們織外衣,連帶飾繩一併織好,七方各自怎麼繫繩,她一清二楚。", "Dệt áo khoác cho các đại biểu Liên minh, cả dây buộc lẫn mọi thứ, và biết chính xác mỗi bên trong bảy bên thắt dây ra sao.", "Menenun mantel para delegasi Liga, lengkap dengan talinya, dan tahu persis bagaimana masing-masing dari ketujuhnya mengikatnya.", "ทอเสื้อคลุมให้ผู้แทนของสันนิบาต รวมทั้งสายผูกครบชุด และรู้แน่ชัดว่าแต่ละฝ่ายในเจ็ดฝ่ายผูกมันอย่างไร", "Birlik delegelerinin ceketlerini kordonlarıyla birlikte dokur ve yedisinin her birinin onları nasıl bağladığını tam olarak bilir.", "Teje las casacas de los delegados de la Liga, con cordones y todo, y sabe exactamente cómo los anuda cada uno de los siete.", "Tece os casacos dos delegados da Liga, com cordões e tudo, e sabe exatamente como cada um dos sete os amarra.", "Ткёт делегатам Лиги кафтаны, вместе со шнурами, и точно знает, как каждый из семи их завязывает.", "Тче делегатам Ліги каптани, разом зі шнурами, і точно знає, як кожен із сімох їх зав'язує."],
  "Keeps the Seven Shades, where the League's arguments go after the Mandapa closes.": ["「七つの日陰亭」の主。マンダパが閉まったあと、同盟の議論はここへ流れてくる。", "'일곱 그늘'의 주인. 만다파가 문을 닫으면 동맹의 논쟁은 이곳으로 옮겨 온다.", "经营“七荫”,曼达帕散场后,同盟的争论就挪到这里继续。", "經營「七蔭」,曼達帕散場後,同盟的爭論就挪到這裡繼續。", "Giữ quán Bảy Bóng Râm, nơi những cuộc tranh cãi của Liên minh kéo đến sau khi Mandapa đóng cửa.", "Pemilik Tujuh Teduh, tempat perdebatan Liga berlanjut setelah Mandapa tutup.", "เจ้าของร้านเจ็ดร่มเงา ที่ซึ่งการถกเถียงของสันนิบาตย้ายมาต่อหลังมณฑปปิด", "Yedi Gölge'nin sahibi; Mandapa kapandıktan sonra Birlik'in tartışmaları buraya taşınır.", "Regenta Las Siete Sombras, adonde van las discusiones de la Liga cuando cierra el Mandapa.", "Cuida d'As Sete Sombras, para onde vão as discussões da Liga depois que o Mandapa fecha.", "Держит «Семь теней», куда споры Лиги перебираются после закрытия Мандапы.", "Тримає «Сім тіней», куди суперечки Ліги перебираються, коли Мандапа зачиняється."],
  "Mandapur's smith, who makes push-daggers for the delegates' guards and parasol ribs for the delegates.": ["マンダプルの鍛冶屋。代表の護衛には拳刀を、代表本人には日傘の骨を作る。", "만다푸르의 대장장이. 대표들의 경호원에게는 주먹 단검을, 대표들에게는 일산 살을 만들어 준다.", "曼达普尔的铁匠,给代表们的护卫打拳刃,给代表们打华盖骨。", "曼達普爾的鐵匠,給代表們的護衛打拳刃,給代表們打華蓋骨。", "Thợ rèn của Mandapur, làm dao găm đấm cho vệ sĩ của các đại biểu và nan lọng cho chính các đại biểu.", "Pandai besi Mandapur, yang membuat belati kepal untuk pengawal para delegasi dan rusuk payung untuk para delegasi.", "ช่างตีเหล็กแห่งมัณฑปุระ ผู้ตีกริชกำปั้นให้องครักษ์ของผู้แทน และตีซี่ฉัตรให้ตัวผู้แทนเอง", "Mandapur'un demircisi; delegelerin muhafızlarına yumruk hançeri, delegelere de şemsiye telleri yapar.", "La herrera de Mandapur, que hace dagas de puño para los guardias de los delegados y varillas de parasol para los delegados.", "A ferreira de Mandapur, que faz punhais de soco para os guardas dos delegados e varetas de para-sol para os delegados.", "Кузнечиха Мандапура: куёт тычковые кинжалы для охраны делегатов и спицы для зонтов самих делегатов.", "Ковалиха Мандапура: кує кулачні кинджали для охорони делегатів і спиці для парасолів самих делегатів."],
  "A guard of the League in a purple sash, a different ruler's badge on each shoulder this month.": ["紫の飾り帯を締めた同盟の衛兵。今月は両肩にそれぞれ別の統治者の徽章をつけている。", "보라색 띠를 두른 동맹 경비병. 이번 달엔 양어깨에 서로 다른 통치자의 휘장을 달았다.", "系着紫色腰带的同盟卫兵,这个月两边肩上各别着一位不同统治者的徽章。", "繫著紫色腰帶的同盟衛兵,這個月兩邊肩上各別著一位不同統治者的徽章。", "Một vệ binh Liên minh đeo khăn thắt lưng tím, tháng này mỗi bên vai mang huy hiệu của một người cai trị khác nhau.", "Pengawal Liga berselempang ungu, bulan ini dengan lencana penguasa yang berbeda di tiap bahu.", "ทหารของสันนิบาตคาดผ้าสีม่วง เดือนนี้ติดตราของผู้ปกครองต่างคนกันไว้บนบ่าแต่ละข้าง", "Mor kuşaklı bir Birlik muhafızı; bu ay her omzunda farklı bir hükümdarın nişanı var.", "Un guardia de la Liga con fajín morado, con la insignia de un soberano distinto en cada hombro este mes.", "Um guarda da Liga de faixa roxa, com a insígnia de um soberano diferente em cada ombro este mês.", "Стражник Лиги с пурпурным кушаком; в этом месяце на каждом плече — знак другого правителя.", "Вартовий Ліги з пурпуровим поясом; цього місяця на кожному плечі — знак іншого володаря."],
  "Someone of the council town, who has heard every argument in the League twice and has a third of their own.": ["会議の町の誰か。同盟のあらゆる議論を二度ずつ聞いていて、自分なりの三つ目の言い分も持っている。", "회의의 도시에 사는 사람. 동맹의 모든 논쟁을 두 번씩 들었고, 자기만의 세 번째 주장도 있다.", "议事小城里的某个人,同盟里的每场争论都听过两遍,自己还有第三种说法。", "議事小城裡的某個人,同盟裡的每場爭論都聽過兩遍,自己還有第三種說法。", "Một người ở thị trấn hội đồng, đã nghe mọi cuộc tranh cãi trong Liên minh hai lần và có thêm lý lẽ thứ ba của riêng mình.", "Seseorang dari kota dewan, yang sudah mendengar setiap perdebatan di Liga dua kali dan punya pendapat ketiga sendiri.", "ใครสักคนจากเมืองแห่งสภา ผู้ฟังทุกข้อถกเถียงในสันนิบาตมาแล้วสองรอบ และมีข้อที่สามเป็นของตัวเอง", "Meclis kasabasından biri; Birlik'teki her tartışmayı iki kez duymuş ve kendine ait üçüncü bir görüşü var.", "Alguien del pueblo del consejo, que ha oído cada discusión de la Liga dos veces y tiene una tercera propia.", "Alguém da cidade do conselho, que já ouviu cada discussão da Liga duas vezes e tem uma terceira só sua.", "Кто-то из городка совета, кто слышал каждый спор Лиги дважды и имеет третий, собственный.", "Хтось із містечка ради, хто чув кожну суперечку Ліги двічі й має третю, власну."],
  "Provost of Suvarnatira, elected by the Assembly of Ink and Coin for her honesty and kept for her memory, which is long and specific.": ["スヴァルナティーラの学頭。誠実さゆえに墨と貨幣の議会に選ばれ、記憶力ゆえに留任している。その記憶は長く、しかも細かい。", "수바르나티라의 학장. 정직함 덕분에 먹과 주화의 의회에서 뽑혔고, 기억력 덕분에 자리를 지키고 있다. 그 기억은 길고도 구체적이다.", "苏瓦尔纳蒂拉的院长,因诚实被墨与币议会选出,又因记性被留任——她的记性又长又具体。", "蘇瓦爾納蒂拉的院長,因誠實被墨與幣議會選出,又因記性被留任——她的記性又長又具體。", "Viện trưởng của Suvarnatira, được Hội đồng Mực và Xu bầu lên vì sự trung thực và giữ lại vì trí nhớ của bà, vừa dài vừa chi tiết.", "Provos Suvarnatira, dipilih oleh Majelis Tinta dan Koin karena kejujurannya dan dipertahankan karena ingatannya, yang panjang dan terperinci.", "อธิการแห่งสุวรรณตีระ ได้รับเลือกจากสภาหมึกและเหรียญเพราะความซื่อสัตย์ และได้อยู่ต่อเพราะความจำ ซึ่งทั้งยาวนานและละเอียดยิบ", "Suvarnatira Rektörü; Mürekkep ve Sikke Meclisi onu dürüstlüğü için seçti, hafızası için de yerinde tuttu. Hafızası uzun ve ayrıntılıdır.", "Prebostesa de Suvarnatira, elegida por la Asamblea de Tinta y Moneda por su honradez y mantenida por su memoria, que es larga y precisa.", "Reitora de Suvarnatira, eleita pela Assembleia da Tinta e da Moeda por sua honestidade e mantida por sua memória, que é longa e específica.", "Провост Суварнатиры, избранная Собранием Чернил и Монет за честность и оставленная за память — долгую и подробную.", "Провост Суварнатіри, обрана Зборами Чорнила й Монет за чесність і залишена за пам'ять — довгу й докладну."],
  "Keeper of the Archive's catalogue: a slight man with ink to the elbows, who reads the old scripts of four countries and argues with the dead in all of them.": ["文書館の目録係。肘までインクに染まった細身の男で、四つの国の古い文字を読み、そのすべてで死者と議論する。", "서고의 목록 관리인. 팔꿈치까지 먹물이 묻은 호리호리한 남자로, 네 나라의 옛 문자를 읽고 그 모든 문자로 죽은 이들과 논쟁한다.", "档案馆目录的保管人:一个瘦小的男人,墨水沾到手肘,能读四个国家的古文字,还用每一种和死人争论。", "檔案館目錄的保管人:一個瘦小的男人,墨水沾到手肘,能讀四個國家的古文字,還用每一種和死人爭論。", "Người giữ danh mục của Văn khố: một người đàn ông mảnh khảnh, mực dính tới khuỷu tay, đọc được chữ cổ của bốn xứ và cãi nhau với người chết bằng cả bốn thứ chữ ấy.", "Penjaga katalog Arsip: lelaki kurus dengan tinta sampai ke siku, yang membaca aksara kuno empat negeri dan berdebat dengan orang mati dalam semuanya.", "ผู้ดูแลบัญชีรายการของหอจดหมายเหตุ ชายร่างเล็กที่หมึกเปื้อนถึงข้อศอก อ่านอักษรโบราณของสี่แผ่นดินได้ และเถียงกับคนตายได้ในทุกภาษา", "Arşiv'in katalog sorumlusu: dirseklerine kadar mürekkebe bulanmış ufak tefek bir adam; dört ülkenin eski yazılarını okur ve hepsinde ölülerle tartışır.", "Custodio del catálogo del Archivo: un hombre menudo con tinta hasta los codos, que lee las escrituras antiguas de cuatro países y discute con los muertos en todas ellas.", "Guardião do catálogo do Arquivo: um homem franzino com tinta até os cotovelos, que lê as escritas antigas de quatro países e discute com os mortos em todas elas.", "Хранитель каталога Архива: щуплый человек, перемазанный чернилами по локти; читает древние письмена четырёх стран и на всех спорит с мёртвыми.", "Хранитель каталогу Архіву: щуплий чоловік, у чорнилі по лікті; читає давні письмена чотирьох країн і всіма ними сперечається з мертвими."],
  "An envoy of the Obsidian Legacy of Tamesh, in black linen with a lapis border, here about a star chart the Legacy says is theirs.": ["タメシュの黒曜の遺統の使節。瑠璃色の縁取りの黒い亜麻をまとい、遺統が自分たちのものだと言う星図の件で来ている。", "타메시 흑요 유산의 사절. 청금석 빛 테두리를 두른 검은 아마포 차림으로, 유산이 자기네 것이라 주장하는 성도 때문에 왔다.", "塔梅什黑曜遗脉的使节,身着青金石色镶边的黑亚麻衣,为一张遗脉声称归他们所有的星图而来。", "塔梅什黑曜遺脈的使節,身著青金石色鑲邊的黑亞麻衣,為一張遺脈聲稱歸他們所有的星圖而來。", "Một sứ giả của Di Sản Hắc Diện xứ Tamesh, mặc vải lanh đen viền lưu ly, đến đây vì một tấm bản đồ sao mà Di Sản bảo là của họ.", "Utusan Warisan Obsidian dari Tamesh, berbalut linen hitam berpinggiran lapis, datang soal peta bintang yang menurut Warisan adalah milik mereka.", "ทูตแห่งมรดกออบซิเดียนจากทาเมช สวมผ้าลินินสีดำขลิบสีลาพิส มาที่นี่เรื่องแผนที่ดาวที่มรดกออบซิเดียนอ้างว่าเป็นของพวกเขา", "Tamesh'teki Obsidyen Mirası'nın bir elçisi; lacivert taşı kenarlı siyah keten giymiş, Miras'ın kendilerine ait olduğunu söylediği bir yıldız haritası için burada.", "Un enviado del Legado de Obsidiana de Tamesh, de lino negro con ribete de lapislázuli, que viene por una carta estelar que el Legado dice que es suya.", "Um enviado do Legado de Obsidiana de Tamesh, de linho negro com barra de lápis-lazúli, aqui por causa de um mapa estelar que o Legado diz ser seu.", "Посланник Обсидианового наследия из Тамеша, в чёрном льне с лазуритовой каймой; прибыл из-за звёздной карты, которую Наследие считает своей.", "Посланець Обсидіанової спадщини з Тамеша, у чорному льоні з лазуритовою облямівкою; прибув через зоряну карту, яку Спадщина вважає своєю."],
  "A scholar of the Assembly with a satchel of palm-leaf books, reading as they walk.": ["貝葉の書物を鞄に詰めた議会の学者。歩きながら読んでいる。", "야자잎 책이 든 가방을 멘 의회의 학자. 걸으면서도 읽고 있다.", "一位议会学者,背着一包贝叶书,边走边读。", "一位議會學者,背著一包貝葉書,邊走邊讀。", "Một học giả của Hội đồng mang túi đầy sách lá cọ, vừa đi vừa đọc.", "Seorang cendekiawan Majelis membawa tas berisi kitab daun lontar, membaca sambil berjalan.", "นักปราชญ์แห่งสภาสะพายย่ามใส่คัมภีร์ใบลาน เดินไปอ่านไป", "Palmiye yaprağı kitaplarla dolu çantası olan bir Meclis bilgini; yürürken okuyor.", "Un erudito de la Asamblea con un zurrón de libros de hoja de palma, que lee mientras camina.", "Um estudioso da Assembleia com uma bolsa de livros de folha de palmeira, lendo enquanto anda.", "Учёный Собрания с сумкой книг на пальмовых листьях; читает на ходу.", "Учений Зборів із торбою книг на пальмовому листі; читає на ходу."],
  "A ship's chandler from somewhere across the sea, who came to Suvarnatira for a season twenty years ago.": ["海の向こうのどこかから来た船具商。二十年前、ひと季節のつもりでスヴァルナティーラに来た。", "바다 건너 어딘가에서 온 선구상. 이십 년 전 한 철만 머물 생각으로 수바르나티라에 왔다.", "一个来自海那边某处的船具商,二十年前来到苏瓦尔纳蒂拉,本打算只待一季。", "一個來自海那邊某處的船具商,二十年前來到蘇瓦爾納蒂拉,本打算只待一季。", "Một người buôn đồ tàu thuyền từ đâu đó bên kia biển, đến Suvarnatira cho một mùa, hai mươi năm trước.", "Pedagang perlengkapan kapal dari suatu tempat di seberang laut, yang datang ke Suvarnatira untuk satu musim, dua puluh tahun lalu.", "พ่อค้าอุปกรณ์เรือจากที่ไหนสักแห่งโพ้นทะเล ผู้มาสุวรรณตีระเพื่ออยู่สักฤดูหนึ่ง เมื่อยี่สิบปีก่อน", "Denizin ötesinde bir yerden gelmiş bir gemi levazımcısı; yirmi yıl önce bir mevsimliğine Suvarnatira'ya gelmişti.", "Un proveedor de barcos de algún lugar al otro lado del mar, que vino a Suvarnatira para una temporada hace veinte años.", "Um fornecedor de navios de algum lugar além-mar, que veio a Suvarnatira para uma temporada há vinte anos.", "Корабельный торговец откуда-то из-за моря; приехал в Суварнатиру на один сезон двадцать лет назад.", "Корабельний крамар звідкись із-за моря; приїхав до Суварнатіри на один сезон двадцять років тому."],
  "Sells silk from the far east and cotton from the valley, and dyes the Assembly's stoles in a vat she won't let anyone see.": ["遥か東の絹と谷の綿を売り、誰にも見せない染め桶で議会の肩掛けを染めている。", "머나먼 동방의 비단과 계곡의 무명을 팔고, 아무에게도 보여 주지 않는 염색 통에서 의회의 숄을 물들인다.", "卖远东的丝绸和河谷的棉布,还在一口谁也不让看的染缸里为议会染披带。", "賣遠東的絲綢和河谷的棉布,還在一口誰也不讓看的染缸裡為議會染披帶。", "Bán lụa từ viễn đông và vải bông từ thung lũng, và nhuộm khăn choàng cho Hội đồng trong một cái vại không cho ai xem.", "Menjual sutra dari timur jauh dan katun dari lembah, dan mencelup selendang Majelis dalam tong yang tak boleh dilihat siapa pun.", "ขายผ้าไหมจากตะวันออกไกลและผ้าฝ้ายจากหุบเขา และย้อมผ้าคล้องไหล่ของสภาในอ่างที่เธอไม่ยอมให้ใครเห็น", "Uzak doğudan ipek, vadiden pamuk satar; Meclis'in atkılarını kimseye göstermediği bir teknede boyar.", "Vende seda del lejano oriente y algodón del valle, y tiñe las estolas de la Asamblea en una tina que no deja ver a nadie.", "Vende seda do extremo oriente e algodão do vale, e tinge as estolas da Assembleia num tonel que não deixa ninguém ver.", "Продаёт шёлк с далёкого востока и хлопок из долины, а палантины Собрания красит в чане, который никому не показывает.", "Продає шовк із далекого сходу й бавовну з долини, а палантини Зборів фарбує в чані, якого нікому не показує."],
  "Keeps the Inkwell Inn, where scholars pay in coin and merchants pay in news.": ["墨壺亭の女主人。ここでは学者は硬貨で払い、商人は噂で払う。", "잉크병 여관의 주인. 이곳에서 학자는 동전으로, 상인은 소식으로 값을 치른다.", "经营墨水瓶客栈,在这里学者付钱,商人付消息。", "經營墨水瓶客棧,在這裡學者付錢,商人付消息。", "Chủ Quán Lọ Mực, nơi học giả trả bằng tiền còn thương nhân trả bằng tin tức.", "Mengelola Penginapan Tempat Tinta, tempat para cendekiawan membayar dengan koin dan para pedagang membayar dengan kabar.", "ดูแลโรงเตี๊ยมขวดหมึก ที่ซึ่งนักปราชญ์จ่ายเป็นเหรียญ และพ่อค้าจ่ายเป็นข่าว", "Hokka Hanı'nı işletir; orada bilginler sikkeyle, tüccarlar haberle öder.", "Regenta la Posada del Tintero, donde los eruditos pagan en monedas y los mercaderes en noticias.", "Cuida da Estalagem do Tinteiro, onde estudiosos pagam em moedas e mercadores pagam em notícias.", "Держит трактир «Чернильница», где учёные платят монетой, а купцы — новостями.", "Тримає заїзд «Чорнильниця», де вчені платять монетою, а купці — новинами."],
  "Suvarnatira's smith: anchors, hinges, sabres for the harbour watch, and the Archive's brass lamps.": ["スヴァルナティーラの鍛冶屋。錨、蝶番、港の警備隊のサーベル、そして文書館の真鍮のランプを作る。", "수바르나티라의 대장장이. 닻, 경첩, 항구 경비대의 군도, 그리고 서고의 놋쇠 등잔을 만든다.", "苏瓦尔纳蒂拉的铁匠:船锚、合页、港口卫队的军刀,还有档案馆的黄铜灯。", "蘇瓦爾納蒂拉的鐵匠:船錨、鉸鏈、港口衛隊的軍刀,還有檔案館的黃銅燈。", "Thợ rèn của Suvarnatira: neo, bản lề, gươm cong cho đội tuần cảng, và đèn đồng thau của Văn khố.", "Pandai besi Suvarnatira: jangkar, engsel, pedang lengkung untuk penjaga pelabuhan, dan lampu kuningan Arsip.", "ช่างตีเหล็กแห่งสุวรรณตีระ ทำสมอเรือ บานพับ ดาบโค้งให้หน่วยรักษาท่าเรือ และตะเกียงทองเหลืองของหอจดหมายเหตุ", "Suvarnatira'nın demircisi: çapalar, menteşeler, liman muhafızları için kılıçlar ve Arşiv'in pirinç lambaları.", "La herrera de Suvarnatira: anclas, bisagras, sables para la guardia del puerto y las lámparas de latón del Archivo.", "A ferreira de Suvarnatira: âncoras, dobradiças, sabres para a guarda do porto e as lâmpadas de latão do Arquivo.", "Кузнец Суварнатиры: якоря, петли, сабли для портовой стражи и латунные лампы Архива.", "Ковалька Суварнатіри: якорі, завіси, шаблі для портової варти й латунні лампи Архіву."],
  "A guard of the free port's harbour watch, sea-green sash, sabre, and a whistle she isn't afraid to use.": ["自由港の港湾警備隊の衛兵。海緑色の飾り帯にサーベル、そして吹くのをためらわない呼び子。", "자유항 항구 경비대의 경비병. 바다빛 초록 띠, 군도, 그리고 부는 데 주저함이 없는 호루라기.", "自由港港口卫队的一名卫兵,系着海绿色饰带,佩着军刀,还有一只她毫不犹豫就会吹响的哨子。", "自由港港口衛隊的一名衛兵,繫著海綠色飾帶,佩著軍刀,還有一只她毫不猶豫就會吹響的哨子。", "Một lính gác của đội tuần cảng thương cảng tự do, khăn thắt lưng màu xanh biển, gươm cong, và một cái còi cô không ngại thổi.", "Penjaga dari pasukan pelabuhan bandar bebas, berselempang hijau laut, berpedang, dan membawa peluit yang tak segan ia tiup.", "ทหารยามของหน่วยรักษาท่าเรือแห่งเมืองท่าเสรี คาดผ้าสีเขียวน้ำทะเล พกดาบโค้ง และนกหวีดที่เธอไม่ลังเลจะเป่า", "Serbest limanın liman muhafızlarından biri; deniz yeşili kuşak, kılıç ve öttürmekten çekinmediği bir düdük.", "Una guardia de la guardia portuaria del puerto franco: faja verde mar, sable y un silbato que no le da miedo usar.", "Uma guarda da guarda portuária do porto livre: faixa verde-mar, sabre e um apito que ela não tem medo de usar.", "Стражница портовой стражи вольного порта: кушак цвета морской волны, сабля и свисток, которым она не боится пользоваться.", "Вартова портової варти вільного порту: пояс кольору морської хвилі, шабля і свисток, яким вона не боїться користуватися."],
  "A sailor off a trading dhow, salt in the beard and tar on the hands.": ["交易用のダウ船から降りてきた船乗り。髭には塩、手にはタール。", "무역용 다우선에서 내린 선원. 수염엔 소금, 손엔 타르.", "一个从贸易三角帆船上下来的水手,胡子里有盐,手上有焦油。", "一個從貿易三角帆船上下來的水手,鬍子裡有鹽,手上有焦油。", "Một thủy thủ từ chiếc thuyền buồm dhow buôn bán, muối trong râu và hắc ín trên tay.", "Pelaut dari kapal dhow dagang, garam di janggut dan ter di tangan.", "กะลาสีจากเรือใบดาวสินค้า มีเกลือติดเครา และน้ำมันดินติดมือ", "Bir ticaret gemisinden inmiş denizci; sakalında tuz, ellerinde katran.", "Un marinero de un dhow mercante, con sal en la barba y brea en las manos.", "Um marinheiro de um dhow mercante, com sal na barba e piche nas mãos.", "Моряк с торговой доу: соль в бороде, смола на руках.", "Моряк із торгової доу: сіль у бороді, смола на руках."],
  "A citizen of the free port, with ink on one hand and a coin in the other.": ["自由港の市民。片手にインク、もう片方の手に硬貨。", "자유항의 시민. 한 손엔 잉크, 다른 손엔 동전.", "自由港的市民,一只手沾着墨,另一只手攥着钱。", "自由港的市民,一隻手沾著墨,另一隻手攥著錢。", "Một thị dân của thương cảng tự do, một tay dính mực, tay kia cầm đồng xu.", "Warga bandar bebas, tinta di satu tangan dan koin di tangan lain.", "ชาวเมืองท่าเสรี มือข้างหนึ่งเปื้อนหมึก อีกข้างถือเหรียญ", "Serbest limanın bir sakini; bir elinde mürekkep, ötekinde sikke.", "Un ciudadano del puerto franco, con tinta en una mano y una moneda en la otra.", "Um cidadão do porto livre, com tinta numa mão e uma moeda na outra.", "Горожанин вольного порта: на одной руке чернила, в другой монета.", "Містянин вільного порту: на одній руці чорнило, в іншій монета."],
  "Eldest of the Kanthari of Kanthar, small, sharp, wrapped in leaf-green. She has sent away tax collectors from three kingdoms and offered all of them tea first.": ["カンタルのカンタリの最長老。小柄で鋭く、葉の緑に身を包んでいる。三つの王国の徴税吏を追い返してきたが、全員にまずお茶を出した。", "칸타르 칸타리족의 최연장자. 작고, 날카롭고, 잎사귀 초록으로 몸을 감쌌다. 세 왕국의 세리들을 돌려보냈는데, 하나같이 먼저 차부터 대접했다.", "坎塔尔坎塔里人中最年长的一位,个子小,眼光利,裹着叶绿色的衣裳。她打发走过三个王国的收税官,每一个都先请喝了茶。", "坎塔爾坎塔里人中最年長的一位,個子小,眼光利,裹著葉綠色的衣裳。她打發走過三個王國的收稅官,每一個都先請喝了茶。", "Người cao tuổi nhất của người Kanthari xứ Kanthar, nhỏ bé, sắc sảo, quấn vải màu xanh lá. Bà đã đuổi về những viên thu thuế của ba vương quốc, và đều mời họ uống trà trước.", "Tetua tertua orang Kanthari dari Kanthar, kecil, tajam, berbalut hijau daun. Ia telah mengusir pemungut pajak dari tiga kerajaan, dan menawari mereka semua teh lebih dulu.", "ผู้อาวุโสที่สุดของชาวกันถารีแห่งกันถาร์ ตัวเล็ก หัวไว ห่มผ้าสีเขียวใบไม้ นางเคยไล่คนเก็บภาษีจากสามอาณาจักรกลับไป และรินชาให้ทุกคนก่อน", "Kanthar'ın Kanthariler'inin en yaşlısı; ufak, keskin, yaprak yeşiline sarınmış. Üç krallığın vergi tahsildarlarını geri göndermiş, hepsine önce çay ikram etmiştir.", "La mayor de los kanthari de Kanthar, pequeña, aguda, envuelta en verde hoja. Ha despachado a recaudadores de impuestos de tres reinos, y a todos les ofreció té primero.", "A mais velha dos kanthari de Kanthar, pequena, afiada, envolta em verde-folha. Já mandou embora cobradores de impostos de três reinos, e ofereceu chá a todos eles antes.", "Старейшая из кантхари Кантхара: маленькая, острая, укутанная в цвет листвы. Она выпроводила сборщиков податей трёх королевств и каждому сперва предложила чаю.", "Найстарша з кантхарі Кантхару: маленька, гостра, загорнута в колір листя. Вона спровадила збирачів податків трьох королівств і кожному спершу запропонувала чаю."],
  "Weaves bamboo and bark-cloth, and trades the village's cloth for rice and salt when the river is low enough to carry them.": ["竹と樹皮布を織り、川が渡れるほど浅くなると、村の布を運んで米や塩と交換する。", "대나무와 나무껍질 천을 짜고, 강물이 짐을 지고 건널 만큼 낮아지면 마을의 천을 쌀과 소금으로 바꿔 온다.", "编竹子、织树皮布;等河水浅到能把东西运过去时,就拿村里的布去换米和盐。", "編竹子、織樹皮布;等河水淺到能把東西運過去時,就拿村裡的布去換米和鹽。", "Đan tre và dệt vải vỏ cây, và đổi vải của làng lấy gạo với muối khi nước sông đủ cạn để chở qua.", "Menganyam bambu dan kain kulit kayu, dan menukar kain desa dengan beras dan garam bila sungai cukup surut untuk dilalui.", "สานไม้ไผ่และทอผ้าเปลือกไม้ และนำผ้าของหมู่บ้านไปแลกข้าวกับเกลือเมื่อแม่น้ำลดพอจะขนข้ามไปได้", "Bambu ve ağaç kabuğu bezi dokur; nehir onları taşıyacak kadar alçaldığında köyün kumaşını pirinç ve tuzla takas eder.", "Teje bambú y tela de corteza, y cambia la tela del pueblo por arroz y sal cuando el río baja lo bastante para cruzar con ellos.", "Tece bambu e tecido de casca, e troca o pano da aldeia por arroz e sal quando o rio está baixo o bastante para levá-los.", "Плетёт бамбук и ткёт ткань из коры, а когда река мелеет настолько, что можно перенести товар, меняет деревенскую ткань на рис и соль.", "Плете бамбук і тче тканину з кори, а коли річка міліє настільки, що можна перенести товар, міняє сільську тканину на рис і сіль."],
  "A hunter of the Deepgreen with a bamboo bow and no shoes, who has heard you coming for some time.": ["竹の弓を持ち、裸足の深緑の森の狩人。あなたが来るのを、しばらく前から聞いていた。", "대나무 활을 들고 맨발인 깊은초록 숲의 사냥꾼. 당신이 오는 소리를 꽤 전부터 듣고 있었다.", "深绿林的猎人,拿着竹弓,光着脚,早就听见你过来了。", "深綠林的獵人,拿著竹弓,光著腳,早就聽見你過來了。", "Một thợ săn của Rừng Thẳm Xanh với cây cung tre và đôi chân trần, đã nghe thấy bạn đến từ khá lâu rồi.", "Pemburu Rimba Hijau Pekat dengan busur bambu dan tanpa alas kaki, yang sudah mendengarmu datang sejak tadi.", "นายพรานแห่งป่าเขียวลึก ถือคันธนูไม้ไผ่ เท้าเปล่า ได้ยินเสียงคุณเดินมาตั้งนานแล้ว", "Bambu yaylı, yalınayak bir Derin Yeşillik avcısı; geldiğini bir süredir duyuyor.", "Un cazador del Verdor Profundo con arco de bambú y sin zapatos, que lleva un buen rato oyéndote llegar.", "Um caçador do Verde Profundo com arco de bambu e sem sapatos, que já ouve você chegando há algum tempo.", "Охотник Глубокой Зелени с бамбуковым луком и без обуви; он уже давно слышит, как ты идёшь.", "Мисливець Глибокої Зелені з бамбуковим луком і без взуття; він уже давно чує, як ти йдеш."],
  "A logger from the highlands in a wool cap, felling teak for Shailagarh's pit props on a licence the Kanthari never signed.": ["毛糸の帽子をかぶった高地の木こり。カンタリが一度も署名していない許可状を盾に、シャイラガルの坑木用にチークを伐っている。", "털모자를 쓴 고원 출신 벌목꾼. 칸타리족이 서명한 적 없는 허가증을 들고 샤일라가르의 갱목으로 쓸 티크를 베고 있다.", "一个戴羊毛帽的高地伐木工,凭着一张坎塔里人从未签过字的许可证,为沙伊拉加尔砍柚木做矿坑支柱。", "一個戴羊毛帽的高地伐木工,憑著一張坎塔里人從未簽過字的許可證,為沙伊拉加爾砍柚木做礦坑支柱。", "Một tiều phu vùng cao đội mũ len, đốn gỗ tếch làm cột chống hầm mỏ cho Shailagarh, theo một giấy phép mà người Kanthari chưa từng ký.", "Penebang kayu dari dataran tinggi bertopi wol, menebang jati untuk penyangga tambang Shailagarh dengan izin yang tak pernah ditandatangani orang Kanthari.", "คนตัดไม้จากที่ราบสูงสวมหมวกขนสัตว์ โค่นไม้สักไปทำเสาค้ำเหมืองให้ไศลครห์ ด้วยใบอนุญาตที่ชาวกันถารีไม่เคยลงนาม", "Yün takkeli bir yayla oduncusu; Kanthariler'in asla imzalamadığı bir izinle Shailagarh'ın maden direkleri için tik ağacı kesiyor.", "Un leñador de las tierras altas con gorro de lana, que tala teca para los puntales de las minas de Shailagarh con una licencia que los kanthari nunca firmaron.", "Um lenhador das terras altas de gorro de lã, cortando teca para as escoras das minas de Shailagarh com uma licença que os kanthari nunca assinaram.", "Лесоруб с нагорья в шерстяной шапке; валит тик на рудничные крепи для Шайлагарха по разрешению, которого кантхари никогда не подписывали.", "Лісоруб із нагір'я у вовняній шапці; валить тик на шахтне кріплення для Шайлагарха за дозволом, якого кантхарі ніколи не підписували."],
  "Welcome to Meghavan. It will rain this afternoon. It rained yesterday afternoon. It will rain tomorrow.": ["メガヴァンへようこそ。今日の午後は雨が降る。昨日の午後も降った。明日も降る。", "메가반에 온 걸 환영하오. 오늘 오후엔 비가 올 거요. 어제 오후에도 왔지. 내일도 올 거요.", "欢迎来到梅加万。今天下午会下雨。昨天下午下过雨。明天也会下雨。", "歡迎來到梅加萬。今天下午會下雨。昨天下午下過雨。明天也會下雨。", "Chào mừng đến Meghavan. Chiều nay sẽ mưa. Chiều qua đã mưa. Mai cũng sẽ mưa.", "Selamat datang di Meghavan. Sore ini akan hujan. Kemarin sore hujan. Besok juga akan hujan.", "ยินดีต้อนรับสู่เมฆาวัน บ่ายนี้ฝนจะตก บ่ายเมื่อวานฝนก็ตก พรุ่งนี้ฝนก็จะตก", "Meghavan'a hoş geldin. Bu öğleden sonra yağmur yağacak. Dün öğleden sonra yağdı. Yarın da yağacak.", "Bienvenido a Meghavan. Esta tarde lloverá. Ayer por la tarde llovió. Mañana lloverá.", "Bem-vindo a Meghavan. Vai chover esta tarde. Choveu ontem à tarde. Vai chover amanhã.", "Добро пожаловать в Мегхаван. Сегодня после полудня будет дождь. Вчера после полудня был дождь. Завтра будет дождь.", "Ласкаво просимо до Мегхавану. Сьогодні по обіді буде дощ. Учора по обіді був дощ. Завтра буде дощ."],
  "Tirthali is east, along the road. Don't leave the road at dusk: the dacoits know it better than we do.": ["ティルタリは東、街道沿いだ。夕暮れには街道を外れるなよ。盗賊どものほうが俺たちより道に詳しい。", "티르탈리는 동쪽, 길을 따라가면 있소. 해 질 녘엔 길을 벗어나지 마시오. 도적들이 우리보다 그 길을 더 잘 아니까.", "提尔塔利在东边,顺着路走。黄昏时别离开大路:那些强盗比我们还熟悉它。", "提爾塔利在東邊,順著路走。黃昏時別離開大路:那些強盜比我們還熟悉它。", "Tirthali ở phía đông, men theo đường. Đừng rời đường lúc chạng vạng: bọn cướp rành nó hơn cả chúng tôi.", "Tirthali ada di timur, sepanjang jalan. Jangan tinggalkan jalan saat senja: para begal lebih mengenalnya daripada kami.", "ตีรถลีอยู่ทางตะวันออก ตามถนนไป อย่าออกนอกถนนตอนพลบค่ำ พวกโจรรู้จักมันดีกว่าพวกเราเสียอีก", "Tirthali doğuda, yol boyunca. Alacakaranlıkta yoldan ayrılma: haydutlar yolu bizden iyi bilir.", "Tirthali está al este, siguiendo el camino. No te salgas del camino al anochecer: los bandidos lo conocen mejor que nosotros.", "Tirthali fica a leste, pela estrada. Não saia da estrada ao anoitecer: os bandoleiros a conhecem melhor do que nós.", "Тиртхали на востоке, по дороге. В сумерках с дороги не сходи: разбойники знают её лучше нас.", "Тіртхалі на сході, по дорозі. Присмерком із дороги не сходь: розбійники знають її краще за нас."],
  "Kharaveth? We see their caravans every week. They come in dusty and go out wet.": ["カラヴェス?あそこの隊商なら毎週見るよ。埃まみれで来て、ずぶ濡れで帰っていく。", "카라베스? 거기 대상은 매주 보오. 먼지투성이로 들어와서 흠뻑 젖어 나가지.", "卡拉维斯?他们的商队我们每周都见。来时一身灰,走时一身水。", "卡拉維斯?他們的商隊我們每週都見。來時一身灰,走時一身水。", "Kharaveth à? Tuần nào chúng tôi cũng thấy đoàn buôn của họ. Đến thì bụi bặm, đi thì ướt sũng.", "Kharaveth? Kafilah mereka kami lihat tiap minggu. Datang berdebu, pulang basah.", "คาราเวธเหรอ เราเห็นกองคาราวานของพวกนั้นทุกสัปดาห์ มาถึงตัวฝุ่นเขรอะ กลับไปตัวเปียกโชก", "Kharaveth mi? Kervanlarını her hafta görürüz. Tozlu gelirler, ıslak giderler.", "¿Kharaveth? Vemos sus caravanas todas las semanas. Llegan polvorientas y se van mojadas.", "Kharaveth? Vemos as caravanas deles toda semana. Chegam empoeiradas e saem molhadas.", "Харавет? Их караваны мы видим каждую неделю. Приходят пыльные, уходят мокрые.", "Харавет? Їхні каравани ми бачимо щотижня. Приходять запилені, ідуть мокрі."],
  "The ford's free, the bridge at Sarovan isn't. That's why Tirthali exists, and why the Queen sighs when she hears its name.": ["浅瀬はただ、サロヴァンの橋はただじゃない。だからティルタリがあるし、だから女王はその名を聞くとため息をつく。", "여울은 공짜고, 사로반의 다리는 아니오. 그래서 티르탈리가 있는 거고, 그래서 여왕께서 그 이름만 들으면 한숨을 쉬시지.", "渡口不要钱,萨罗万的桥要钱。所以才有提尔塔利,所以女王一听到这个名字就叹气。", "渡口不用錢,薩羅萬的橋要錢。所以才有提爾塔利,所以女王一聽到這個名字就嘆氣。", "Lội qua chỗ cạn thì miễn phí, cầu ở Sarovan thì không. Vì thế mới có Tirthali, và vì thế Nữ hoàng thở dài mỗi khi nghe đến tên nó.", "Penyeberangan dangkal ini gratis, jembatan di Sarovan tidak. Itulah sebabnya Tirthali ada, dan sebabnya Ratu menghela napas tiap mendengar namanya.", "ท่าข้ามน้ำตื้นนี่ฟรี สะพานที่สโรวันไม่ฟรี นั่นแหละคือเหตุที่มีตีรถลี และเหตุที่ราชินีถอนหายใจทุกครั้งที่ได้ยินชื่อนี้", "Sığ geçit bedava, Sarovan'daki köprü değil. Tirthali bu yüzden var, Kraliçe de bu yüzden adını duyunca iç çeker.", "El vado es gratis; el puente de Sarovan, no. Por eso existe Tirthali, y por eso la Reina suspira cuando oye su nombre.", "O vau é de graça; a ponte de Sarovan, não. É por isso que Tirthali existe, e por isso a Rainha suspira quando ouve o nome dela.", "Брод бесплатный, мост в Сароване — нет. Поэтому Тиртхали и существует, и поэтому королева вздыхает, слыша его название.", "Брід безплатний, міст у Саровані — ні. Тому Тіртхалі й існує, і тому королева зітхає, почувши його назву."],
  "Everyone crosses here: caravans, pilgrims, Shailagarh's ore, the League's spice. I write them all down. Some of them I write down very small.": ["誰もがここを渡る。隊商、巡礼、シャイラガルの鉱石、同盟の香辛料。私は全部書き留める。中には、とても小さな字で書くものもある。", "모두가 여기로 건너오오. 대상, 순례자, 샤일라가르의 광석, 동맹의 향신료. 나는 그걸 전부 적어 두지. 어떤 건 아주 작게 적고.", "人人都从这里过:商队、朝圣者、沙伊拉加尔的矿石、同盟的香料。我全都记下来。有些我记得很小很小。", "人人都從這裡過:商隊、朝聖者、沙伊拉加爾的礦石、同盟的香料。我全都記下來。有些我記得很小很小。", "Ai cũng qua đây: đoàn buôn, khách hành hương, quặng của Shailagarh, gia vị của Liên minh. Tôi ghi lại hết. Có vài thứ tôi ghi rất nhỏ.", "Semua menyeberang di sini: kafilah, peziarah, bijih Shailagarh, rempah Liga. Semuanya kucatat. Sebagian kucatat dengan huruf sangat kecil.", "ใคร ๆ ก็ข้ามที่นี่ ทั้งกองคาราวาน ผู้แสวงบุญ แร่ของไศลครห์ เครื่องเทศของสันนิบาต ข้าจดไว้หมด บางอย่างข้าจดตัวเล็กมาก", "Herkes buradan geçer: kervanlar, hacılar, Shailagarh'ın cevheri, Birlik'in baharatı. Hepsini yazarım. Bazılarını çok küçük yazarım.", "Todo el mundo cruza por aquí: caravanas, peregrinos, el mineral de Shailagarh, las especias de la Liga. Lo anoto todo. Algunas cosas las anoto con letra muy pequeña.", "Todo mundo atravessa aqui: caravanas, peregrinos, o minério de Shailagarh, as especiarias da Liga. Eu anoto tudo. Algumas coisas eu anoto bem pequenininho.", "Здесь переправляются все: караваны, паломники, руда Шайлагарха, пряности Лиги. Я всех записываю. Некоторых — очень мелким почерком.", "Тут переправляються всі: каравани, прочани, руда Шайлагарха, прянощі Ліги. Я всіх записую. Декого — дуже дрібним почерком."],
  "Half the town came from Kharaveth, half from here, and all of it argues in both languages.": ["町の半分はカラヴェスから、半分はここから来た。そして町じゅうが両方の言葉で言い争っている。", "마을 절반은 카라베스에서, 절반은 여기서 왔소. 그리고 마을 전체가 두 언어로 다투지.", "镇上一半人来自卡拉维斯,一半来自本地,整个镇子用两种语言吵架。", "鎮上一半人來自卡拉維斯,一半來自本地,整個鎮子用兩種語言吵架。", "Nửa thị trấn đến từ Kharaveth, nửa từ đây, và cả thị trấn cãi nhau bằng cả hai thứ tiếng.", "Separuh kota datang dari Kharaveth, separuh dari sini, dan seluruhnya bertengkar dalam dua bahasa.", "ครึ่งเมืองมาจากคาราเวธ อีกครึ่งมาจากที่นี่ และทั้งเมืองเถียงกันได้ทั้งสองภาษา", "Kasabanın yarısı Kharaveth'ten, yarısı buradan gelmiş ve hepsi iki dilde de tartışır.", "La mitad del pueblo vino de Kharaveth, la otra mitad es de aquí, y todo él discute en los dos idiomas.", "Metade da cidade veio de Kharaveth, metade daqui, e a cidade inteira discute nas duas línguas.", "Полгорода пришло из Харавета, полгорода отсюда, и весь город спорит на обоих языках.", "Пів міста прийшло з Харавету, пів — звідси, і все місто сперечається обома мовами."],
  "Sit, eat. Rice and lentils, flatbread, tea. If you want something else, you're in the wrong caravanserai.": ["座って、食べな。米と豆、平焼きパン、お茶。ほかのものが欲しいなら、隊商宿を間違えてるよ。", "앉아서 드시오. 밥과 렌틸콩, 납작빵, 차. 다른 게 먹고 싶으면 대상 숙소를 잘못 찾아온 거요.", "坐,吃。米饭配扁豆、烤饼、茶。想吃别的?那你走错商队客栈了。", "坐,吃。米飯配扁豆、烤餅、茶。想吃別的?那你走錯商隊客棧了。", "Ngồi, ăn đi. Cơm với đậu lăng, bánh dẹt, trà. Muốn món khác thì bạn vào nhầm quán trọ đoàn buôn rồi.", "Duduk, makan. Nasi dan kacang lentil, roti pipih, teh. Kalau mau yang lain, kau salah masuk karavanserai.", "นั่งสิ กินเลย ข้าวกับถั่วเลนทิล แผ่นแป้งย่าง ชา ถ้าอยากได้อย่างอื่น ก็เข้าคาราวานเซรายผิดที่แล้ว", "Otur, ye. Pirinç ve mercimek, yufka ekmek, çay. Başka bir şey istiyorsan yanlış kervansaraydasın.", "Siéntate y come. Arroz con lentejas, pan plano, té. Si quieres otra cosa, te has equivocado de caravasar.", "Sente e coma. Arroz com lentilha, pão chato, chá. Se quer outra coisa, está no caravançará errado.", "Садись, ешь. Рис с чечевицей, лепёшки, чай. Хочешь чего-то другого — ты не в тот караван-сарай зашёл.", "Сідай, їж. Рис із сочевицею, коржі, чай. Хочеш чогось іншого — ти не в той караван-сарай зайшов."],
  "Khetmar's riders and Shailagarh's miners at one table, and nobody's drawn a blade yet tonight. That's my cooking.": ["ケトマルの騎兵とシャイラガルの鉱夫が同じ卓について、今夜はまだ誰も刃を抜いていない。それが私の料理の力さ。", "케트마르의 기병과 샤일라가르의 광부가 한 식탁에 앉았는데, 오늘 밤 아직 아무도 칼을 뽑지 않았소. 그게 내 요리 솜씨지.", "克特马尔的骑兵和沙伊拉加尔的矿工同坐一桌,今晚居然还没人拔刀。这就是我的厨艺。", "克特馬爾的騎兵和沙伊拉加爾的礦工同坐一桌,今晚居然還沒人拔刀。這就是我的廚藝。", "Kỵ binh Khetmar và thợ mỏ Shailagarh ngồi chung một bàn, mà tối nay chưa ai rút dao. Đó là nhờ tài nấu nướng của tôi.", "Penunggang Khetmar dan penambang Shailagarh di satu meja, dan malam ini belum ada yang menghunus pisau. Itu berkat masakanku.", "ทหารม้าเคทมาร์กับคนงานเหมืองไศลครห์นั่งโต๊ะเดียวกัน และคืนนี้ยังไม่มีใครชักดาบเลย นั่นแหละฝีมือทำอาหารของข้า", "Khetmar'ın atlıları ile Shailagarh'ın madencileri aynı masada ve bu gece henüz kimse bıçak çekmedi. İşte benim yemeğim.", "Jinetes de Khetmar y mineros de Shailagarh en la misma mesa, y esta noche nadie ha desenvainado todavía. Eso es mi cocina.", "Cavaleiros de Khetmar e mineiros de Shailagarh na mesma mesa, e ninguém sacou uma lâmina ainda esta noite. É a minha comida.", "Всадники Кетмара и рудокопы Шайлагарха за одним столом, и сегодня ещё никто не обнажил клинка. Это моя стряпня.", "Вершники Кетмара й рудокопи Шайлагарха за одним столом, і сьогодні ще ніхто не оголив клинка. Це моя кухня."],
  "Kharaveth gold or Meghavan copper? Either. Both. I'll make the change in the third.": ["カラヴェスの金貨か、メガヴァンの銅貨か?どっちでも。両方でも。釣りは三つ目の通貨で出すよ。", "카라베스 금화요, 메가반 동전이오? 아무거나. 둘 다도 되고. 거스름돈은 세 번째 돈으로 드리지.", "卡拉维斯的金子还是梅加万的铜钱?都行。两样都行。找零我用第三种。", "卡拉維斯的金子還是梅加萬的銅錢?都行。兩樣都行。找零我用第三種。", "Vàng Kharaveth hay đồng Meghavan? Thứ nào cũng được. Cả hai cũng được. Tiền thối tôi trả bằng thứ thứ ba.", "Emas Kharaveth atau tembaga Meghavan? Yang mana saja. Dua-duanya. Kembaliannya kuberikan dalam mata uang ketiga.", "ทองคาราเวธหรือทองแดงเมฆาวัน อันไหนก็ได้ ทั้งสองก็ได้ เงินทอนข้าจะทอนเป็นสกุลที่สาม", "Kharaveth altını mı, Meghavan bakırı mı? Hangisi olursa. İkisi de. Para üstünü üçüncüsünden veririm.", "¿Oro de Kharaveth o cobre de Meghavan? Cualquiera. Los dos. El cambio te lo doy en una tercera.", "Ouro de Kharaveth ou cobre de Meghavan? Qualquer um. Os dois. O troco eu dou numa terceira moeda.", "Золото Харавета или медь Мегхавана? Любое. Оба. Сдачу дам в третьей монете.", "Золото Харавету чи мідь Мегхавану? Будь-що. Обидва. Решту дам у третій монеті."],
  "Salt from the Ouresh, pepper from the shore. Everything crosses at Tirthali, and some of it stays.": ["ウレシュの塩、浜の胡椒。何もかもティルタリで渡り、そのいくらかは残る。", "우레시의 소금, 해안의 후추. 모든 게 티르탈리에서 건너가고, 그중 일부는 남지.", "乌雷什的盐,海边的胡椒。什么都在提尔塔利过河,有些就留下了。", "烏雷什的鹽,海邊的胡椒。什麼都在提爾塔利過河,有些就留下了。", "Muối từ Ouresh, tiêu từ miền biển. Mọi thứ đều qua sông ở Tirthali, và vài thứ ở lại.", "Garam dari Ouresh, lada dari pesisir. Semuanya menyeberang di Tirthali, dan sebagian tinggal.", "เกลือจากอูเรช พริกไทยจากชายฝั่ง ทุกอย่างข้ามที่ตีรถลี และบางอย่างก็อยู่ต่อ", "Ouresh'ten tuz, kıyıdan biber. Her şey Tirthali'de karşıya geçer, bir kısmı da kalır.", "Sal del Ouresh, pimienta de la costa. Todo cruza por Tirthali, y algo se queda.", "Sal do Ouresh, pimenta da costa. Tudo atravessa em Tirthali, e um pouco fica.", "Соль из Уреша, перец с побережья. Всё переправляется в Тиртхали, и кое-что остаётся.", "Сіль з Урешу, перець з узбережжя. Усе переправляється в Тіртхалі, і дещо лишається."],
  "Madder red, indigo blue, turmeric yellow. Tirthali dresses like both its halves and gets wet like neither.": ["茜の赤、藍の青、ウコンの黄。ティルタリは両方の半分みたいな格好をして、濡れ方はどちらとも違う。", "꼭두서니 빨강, 쪽빛 파랑, 강황 노랑. 티르탈리는 두 반쪽처럼 차려입고, 젖는 건 어느 쪽과도 다르게 젖지.", "茜草红、靛蓝、姜黄。提尔塔利穿得像它的两半,淋湿起来却哪一半都不像。", "茜草紅、靛藍、薑黃。提爾塔利穿得像它的兩半,淋濕起來卻哪一半都不像。", "Đỏ củ nâu, xanh chàm, vàng nghệ. Tirthali ăn mặc giống cả hai nửa của mình, còn ướt thì chẳng giống nửa nào.", "Merah mengkudu, biru nila, kuning kunyit. Tirthali berpakaian seperti kedua belahannya dan basah tak seperti keduanya.", "แดงครั่ง น้ำเงินคราม เหลืองขมิ้น ตีรถลีแต่งตัวเหมือนทั้งสองซีกของตัวเอง แต่เปียกไม่เหมือนซีกไหนเลย", "Kökboya kırmızısı, çivit mavisi, zerdeçal sarısı. Tirthali iki yarısı gibi giyinir, ama ikisi gibi de ıslanmaz.", "Rojo granza, azul índigo, amarillo cúrcuma. Tirthali viste como sus dos mitades y se moja como ninguna.", "Vermelho-garança, azul-anil, amarelo-cúrcuma. Tirthali se veste como suas duas metades e se molha como nenhuma delas.", "Марена красная, индиго синее, куркума жёлтая. Тиртхали одевается как обе свои половины, а мокнет — как ни одна.", "Марена червона, індиго синє, куркума жовта. Тіртхалі вбирається як обидві свої половини, а мокне — як жодна."],
  "Old things. Beautiful old things. Where from? From the ground, friend, where all old things come from.": ["古い品だ。美しい古い品。どこから?土の中からさ、友よ。古いものはみんなそこから来る。", "옛 물건이오. 아름다운 옛 물건. 어디서 났냐고? 땅에서지, 친구. 옛 물건은 다 거기서 나오니까.", "老东西。漂亮的老东西。哪来的?从地里,朋友,所有老东西都是从那儿来的。", "老東西。漂亮的老東西。哪來的?從地裡,朋友,所有老東西都是從那兒來的。", "Đồ cổ. Đồ cổ đẹp. Từ đâu ra à? Từ dưới đất, bạn ạ, nơi mọi đồ cổ đều từ đó mà ra.", "Barang tua. Barang tua yang indah. Dari mana? Dari tanah, kawan, asal semua barang tua.", "ของเก่า ของเก่าสวย ๆ มาจากไหนน่ะเหรอ จากใต้ดินไงเพื่อน ที่ที่ของเก่าทั้งหลายมาจาก", "Eski şeyler. Güzel eski şeyler. Nereden mi? Topraktan, dostum, bütün eski şeylerin geldiği yerden.", "Cosas viejas. Cosas viejas preciosas. ¿De dónde? De la tierra, amigo, de donde vienen todas las cosas viejas.", "Coisas antigas. Lindas coisas antigas. De onde? Do chão, amigo, de onde vêm todas as coisas antigas.", "Старые вещи. Красивые старые вещи. Откуда? Из земли, друг, откуда все старые вещи и берутся.", "Старі речі. Гарні старі речі. Звідки? Із землі, друже, звідки всі старі речі й беруться."],
  "A Queen's officer asked me what was in the basket. I told him lunch. It's mostly lunch.": ["女王の役人に籠の中身を聞かれた。昼飯だと答えたよ。ほとんどは昼飯だ。", "여왕의 관리가 바구니에 뭐가 들었냐고 묻더군. 점심이라고 했소. 대부분은 점심이오.", "女王的一个官员问我篮子里装的是什么。我说是午饭。大部分是午饭。", "女王的一個官員問我籃子裡裝的是什麼。我說是午飯。大部分是午飯。", "Một quan của Nữ hoàng hỏi tôi trong giỏ có gì. Tôi bảo là bữa trưa. Phần lớn là bữa trưa thật.", "Seorang pejabat Ratu bertanya apa isi keranjang ini. Kubilang makan siang. Sebagian besar memang makan siang.", "ขุนนางของราชินีถามข้าว่าในตะกร้ามีอะไร ข้าบอกว่าข้าวกลางวัน ส่วนใหญ่ก็เป็นข้าวกลางวันจริง ๆ", "Kraliçe'nin bir memuru sepette ne olduğunu sordu. Öğle yemeği dedim. Çoğu öğle yemeği.", "Un oficial de la Reina me preguntó qué había en la cesta. Le dije que el almuerzo. Casi todo es almuerzo.", "Um oficial da Rainha me perguntou o que havia no cesto. Eu disse que era o almoço. É quase tudo almoço.", "Королевский чиновник спросил, что у меня в корзине. Я сказал — обед. Там в основном обед.", "Королівський урядник спитав, що в мене в кошику. Я сказав — обід. Там здебільшого обід."],
  "The Archive in Suvarnatira pays well for anything with writing on it. They don't ask, and I don't tell.": ["スヴァルナティーラの文書館は、字の書いてあるものなら何でも高く買ってくれる。向こうは聞かないし、俺も言わない。", "수바르나티라의 서고는 글씨가 적힌 거라면 뭐든 값을 잘 쳐주오. 그쪽은 묻지 않고, 나는 말하지 않지.", "苏瓦尔纳蒂拉的档案馆,凡是写了字的东西都出好价钱。他们不问,我也不说。", "蘇瓦爾納蒂拉的檔案館,凡是寫了字的東西都出好價錢。他們不問,我也不說。", "Văn khố ở Suvarnatira trả hậu cho bất cứ thứ gì có chữ viết. Họ không hỏi, tôi không kể.", "Arsip di Suvarnatira membayar mahal untuk apa saja yang ada tulisannya. Mereka tak bertanya, aku tak bercerita.", "หอจดหมายเหตุที่สุวรรณตีระให้ราคาดีกับอะไรก็ตามที่มีตัวหนังสือ พวกเขาไม่ถาม ข้าก็ไม่บอก", "Suvarnatira'daki Arşiv, üstünde yazı olan her şeye iyi para verir. Onlar sormaz, ben de söylemem.", "El Archivo de Suvarnatira paga bien por cualquier cosa que lleve algo escrito. Ellos no preguntan y yo no cuento.", "O Arquivo de Suvarnatira paga bem por qualquer coisa com escrita. Eles não perguntam, e eu não conto.", "Архив в Суварнатире хорошо платит за всё, на чём что-нибудь написано. Они не спрашивают, я не рассказываю.", "Архів у Суварнатірі добре платить за все, на чому щось написано. Вони не питають, я не розповідаю."],
  "The ferrywarden pays us. Not the Queen, not the League. That's why we're polite to everyone.": ["俺たちに給金を払うのは渡し守だ。女王でも同盟でもない。だから誰にでも礼儀正しくするのさ。", "우리 급료는 나루지기가 주오. 여왕도, 동맹도 아니고. 그래서 우리는 누구에게나 공손하지.", "给我们发饷的是渡口守。不是女王,也不是同盟。所以我们对谁都客客气气。", "給我們發餉的是渡口守。不是女王,也不是同盟。所以我們對誰都客客氣氣。", "Người giữ bến trả lương cho chúng tôi. Không phải Nữ hoàng, không phải Liên minh. Vì thế chúng tôi lịch sự với tất cả mọi người.", "Penjaga penyeberangan yang menggaji kami. Bukan Ratu, bukan Liga. Itu sebabnya kami sopan pada semua orang.", "ผู้คุมท่าข้ามเป็นคนจ่ายเงินพวกเรา ไม่ใช่ราชินี ไม่ใช่สันนิบาต เราถึงได้สุภาพกับทุกคน", "Bize Geçit Bekçisi ödüyor. Kraliçe değil, Birlik değil. Bu yüzden herkese kibarız.", "Nos paga el guardavado. Ni la Reina ni la Liga. Por eso somos educados con todo el mundo.", "Quem nos paga é o guarda do vau. Não a Rainha, não a Liga. É por isso que somos educados com todo mundo.", "Нам платит паромщик. Не королева, не Лига. Потому мы и вежливы со всеми.", "Нам платить поромник. Не королева, не Ліга. Тому ми й чемні з усіма."],
  "Watch your purse by the ford. The langurs come down from the hills and they've learned knots.": ["浅瀬のそばでは財布に気をつけな。ラングールが丘から下りてくるし、あいつら結び目のほどき方を覚えちまった。", "여울 근처에선 지갑 조심하시오. 랑구르들이 언덕에서 내려오는데, 놈들이 매듭을 배웠거든.", "在渡口边看好你的钱袋。叶猴会从山上下来,它们已经学会解绳结了。", "在渡口邊看好你的錢袋。葉猴會從山上下來,牠們已經學會解繩結了。", "Coi chừng túi tiền gần chỗ lội. Lũ voọc từ trên đồi xuống, và chúng đã học được cách gỡ nút.", "Jaga kantongmu di dekat penyeberangan. Lutung turun dari bukit, dan mereka sudah belajar soal simpul.", "ระวังถุงเงินแถวท่าข้ามด้วย พวกค่างลงมาจากเนินเขา และพวกมันแก้ปมเป็นแล้ว", "Geçidin yanında keseni koru. Langurlar tepelerden iniyor ve düğüm çözmeyi öğrendiler.", "Cuida la bolsa junto al vado. Los langures bajan de las colinas y han aprendido a deshacer nudos.", "Cuidado com a bolsa perto do vau. Os langures descem dos morros e aprenderam a desfazer nós.", "У брода береги кошелёк. Лангуры спускаются с холмов, и они освоили узлы.", "Біля броду бережи гаманець. Лангури спускаються з пагорбів, і вони навчилися вузлів."],
  "My father came from Kharaveth with a caravan and stayed for my mother. Half the town has a story like that.": ["親父は隊商と一緒にカラヴェスから来て、お袋のために居ついた。町の半分はそんな話を持ってるよ。", "우리 아버지는 대상을 따라 카라베스에서 왔다가 어머니 때문에 눌러앉았소. 마을 절반이 그런 사연이 있지.", "我爹跟着商队从卡拉维斯过来,为了我娘留了下来。镇上一半人都有这样的故事。", "我爹跟著商隊從卡拉維斯過來,為了我娘留了下來。鎮上一半人都有這樣的故事。", "Cha tôi theo đoàn buôn từ Kharaveth sang, rồi ở lại vì mẹ tôi. Nửa thị trấn đều có chuyện như thế.", "Ayahku datang dari Kharaveth bersama kafilah dan menetap demi ibuku. Separuh kota punya kisah seperti itu.", "พ่อข้ามากับกองคาราวานจากคาราเวธ แล้วอยู่ต่อเพราะแม่ข้า ครึ่งเมืองมีเรื่องแบบนี้ทั้งนั้น", "Babam Kharaveth'ten bir kervanla geldi, annem için kaldı. Kasabanın yarısının böyle bir hikâyesi var.", "Mi padre vino de Kharaveth con una caravana y se quedó por mi madre. La mitad del pueblo tiene una historia así.", "Meu pai veio de Kharaveth com uma caravana e ficou por causa da minha mãe. Metade da cidade tem uma história assim.", "Мой отец пришёл из Харавета с караваном и остался ради моей матери. У полгорода такая история.", "Мій батько прийшов із Харавету з караваном і залишився заради моєї матері. У пів міста така історія."],
  "The ford's low in the dry months, deep in the wet. You learn to read the water or you learn to swim.": ["浅瀬は乾季には浅く、雨季には深い。水を読むことを覚えるか、泳ぎを覚えるかだ。", "여울은 건기엔 얕고 우기엔 깊소. 물을 읽는 법을 배우든가, 헤엄치는 법을 배우든가지.", "渡口旱季水浅,雨季水深。你要么学会看水,要么学会游泳。", "渡口旱季水淺,雨季水深。你要麼學會看水,要麼學會游泳。", "Chỗ lội mùa khô thì cạn, mùa mưa thì sâu. Hoặc học đọc nước, hoặc học bơi.", "Penyeberangan ini dangkal di musim kemarau, dalam di musim hujan. Kau belajar membaca air atau belajar berenang.", "ท่าข้ามน้ำตื้นในหน้าแล้ง ลึกในหน้าฝน จะเรียนอ่านน้ำ หรือจะเรียนว่ายน้ำ ก็เลือกเอา", "Geçit kurak aylarda sığ, yağışlı aylarda derindir. Ya suyu okumayı öğrenirsin ya da yüzmeyi.", "El vado está bajo en los meses secos y hondo en los húmedos. O aprendes a leer el agua o aprendes a nadar.", "O vau fica raso nos meses secos e fundo nos chuvosos. Ou você aprende a ler a água, ou aprende a nadar.", "В сухие месяцы брод мелкий, в дождливые — глубокий. Либо научишься читать воду, либо научишься плавать.", "У сухі місяці брід мілкий, у дощові — глибокий. Або навчишся читати воду, або навчишся плавати."],
  "Sarovan's that way. They'll tell you it's the centre of the world. It's the centre of Ilavarta, which is smaller.": ["サロヴァンはあっちだ。世界の中心だと言われるだろうよ。実際はイラヴァルタの中心で、そっちはもっと小さい。", "사로반은 저쪽이오. 거기 사람들은 세상의 중심이라고 할 거요. 실은 일라바르타의 중심인데, 그건 좀 더 작지.", "萨罗万在那边。他们会跟你说那是世界的中心。其实是伊拉瓦塔的中心,小一点。", "薩羅萬在那邊。他們會跟你說那是世界的中心。其實是伊拉瓦塔的中心,小一點。", "Sarovan ở hướng kia. Người ta sẽ bảo bạn đó là trung tâm thế giới. Nó là trung tâm của Ilavarta, vốn nhỏ hơn.", "Sarovan di sebelah sana. Mereka akan bilang itu pusat dunia. Itu pusat Ilavarta, yang lebih kecil.", "สโรวันอยู่ทางโน้น พวกเขาจะบอกว่ามันเป็นศูนย์กลางของโลก มันเป็นศูนย์กลางของอิลาวรรตะ ซึ่งเล็กกว่า", "Sarovan o tarafta. Sana dünyanın merkezi olduğunu söylerler. Ilavarta'nın merkezi, ki o daha küçük.", "Sarovan está por ahí. Te dirán que es el centro del mundo. Es el centro de Ilavarta, que es más pequeño.", "Sarovan fica para lá. Vão te dizer que é o centro do mundo. É o centro de Ilavarta, que é menor.", "Сарован — в ту сторону. Тебе скажут, что это центр мира. Это центр Илаварты, а она поменьше.", "Сарован — у той бік. Тобі скажуть, що це центр світу. Це центр Ілаварти, а вона менша."],
  "A Queen of Ilavarta is crowned at the Great Tank, with water poured on her hands. If the tanks fail, so does she. My great-grandmother's did, and so did she.": ["イラヴァルタの女王は大貯水池で、両手に水を注がれて戴冠する。貯水池が駄目になれば、女王も駄目になる。曾祖母の代に貯水池は駄目になり、曾祖母もそうなった。", "일라바르타의 여왕은 대저수지에서 두 손에 물을 부어 받으며 즉위하오. 저수지가 무너지면 여왕도 무너지지. 내 증조할머니 때 그랬고, 증조할머니도 그랬소.", "伊拉瓦塔的女王在大水池加冕,由人往她手上浇水。水池若是败了,她也就败了。我曾祖母那时的水池败了,她也败了。", "伊拉瓦塔的女王在大水池加冕,由人往她手上澆水。水池若是敗了,她也就敗了。我曾祖母那時的水池敗了,她也敗了。", "Nữ hoàng Ilavarta được đăng quang tại Hồ Lớn, nước được rót lên tay bà. Nếu các hồ chứa hỏng, bà cũng sụp đổ. Các hồ thời cụ bà tôi đã hỏng, và cụ cũng vậy.", "Ratu Ilavarta dimahkotai di Telaga Agung, dengan air dituangkan ke tangannya. Jika telaga-telaga gagal, ia pun gagal. Telaga-telaga nenek buyutku gagal, dan begitu pula beliau.", "ราชินีแห่งอิลาวรรตะสวมมงกุฎที่สระใหญ่ โดยมีผู้รินน้ำลงบนพระหัตถ์ ถ้าสระล้มเหลว นางก็ล้มเหลวด้วย สระในรัชสมัยทวดของข้าล้มเหลว และนางก็เช่นกัน", "Bir Ilavarta Kraliçesi, ellerine su dökülerek Büyük Havuz'da taç giyer. Havuzlar çökerse o da çöker. Büyük büyükannemin havuzları çöktü, o da çöktü.", "Una reina de Ilavarta se corona en el Gran Estanque, con agua vertida sobre sus manos. Si los estanques fallan, ella también. Los de mi bisabuela fallaron, y ella también.", "Uma rainha de Ilavarta é coroada no Grande Tanque, com água derramada sobre suas mãos. Se os tanques falham, ela também falha. Os da minha bisavó falharam, e ela também.", "Королеву Илаварты коронуют у Великого пруда, поливая ей руки водой. Если пруды подводят, подводит и она. При моей прабабке пруды подвели — и она тоже.", "Королеву Ілаварти коронують біля Великого ставу, поливаючи їй руки водою. Якщо стави підводять, підводить і вона. За моєї прабабусі стави підвели — і вона теж."],
  "My engineers want the temple's gold to dig out the silt. My treasurers want it to stay where the river gave it. Both of them are right, which is the worst kind of argument.": ["技師たちは泥を掘り出すために寺院の金を欲しがっている。会計役たちは、川が与えた場所にそのまま置いておきたい。どちらも正しい。それが最悪の種類の議論だ。", "내 기술자들은 토사를 파내려고 사원의 금을 원하오. 내 재무관들은 강이 준 그 자리에 그대로 두길 원하고. 둘 다 옳소. 그게 가장 고약한 논쟁이지.", "我的工程师想用神庙的金子清淤。我的司库们想让它留在河流赐予它的地方。两边都对,这是最糟糕的一种争论。", "我的工程師想用神廟的金子清淤。我的司庫們想讓它留在河流賜予它的地方。兩邊都對,這是最糟糕的一種爭論。", "Các kỹ sư của ta muốn dùng vàng của đền để nạo bùn. Các thủ quỹ của ta muốn nó ở yên nơi dòng sông đã trao. Cả hai đều đúng, và đó là kiểu tranh cãi tệ nhất.", "Para insinyurku menginginkan emas kuil untuk mengeruk lumpur. Para bendaharaku ingin emas itu tetap di tempat sungai memberikannya. Keduanya benar, dan itulah jenis perdebatan paling buruk.", "วิศวกรของข้าต้องการทองของวิหารไปขุดลอกตะกอน เหรัญญิกของข้าต้องการให้มันอยู่ที่ที่แม่น้ำมอบให้ ทั้งสองฝ่ายถูก และนั่นคือการโต้เถียงชนิดที่เลวร้ายที่สุด", "Mühendislerim alüvyonu kazımak için tapınağın altınını istiyor. Haznedarlarım onun nehrin verdiği yerde kalmasını istiyor. İkisi de haklı; tartışmanın en kötüsü de budur.", "Mis ingenieros quieren el oro del templo para dragar el limo. Mis tesoreros quieren que se quede donde el río lo dio. Los dos tienen razón, que es el peor tipo de discusión.", "Meus engenheiros querem o ouro do templo para dragar o lodo. Meus tesoureiros querem que ele fique onde o rio o deu. Os dois têm razão, que é o pior tipo de discussão.", "Мои инженеры хотят храмовое золото, чтобы вычистить ил. Мои казначеи хотят, чтобы оно оставалось там, где его отдала река. Правы и те и другие, а это худший вид спора.", "Мої інженери хочуть храмове золото, щоб вичистити мул. Мої скарбники хочуть, щоб воно лишалося там, де його віддала річка. Праві і ті, й ті, а це найгірший різновид суперечки."],
  "The League wants our water, Shailagarh wants our roads, the Gilded Court wants our rice. Everyone wants Ilavarta except Ilavarta, who just wants rain.": ["同盟は我らの水を、シャイラガルは我らの道を、金色の宮廷は我らの米を欲しがる。誰もがイラヴァルタを欲しがる。イラヴァルタ自身を除いて。イラヴァルタはただ雨が欲しいだけだ。", "동맹은 우리 물을, 샤일라가르는 우리 길을, 황금 궁정은 우리 쌀을 원하오. 모두가 일라바르타를 원하지. 일라바르타만 빼고. 일라바르타는 그저 비를 원할 뿐이오.", "同盟要我们的水,沙伊拉加尔要我们的路,镀金宫廷要我们的米。人人都想要伊拉瓦塔,只有伊拉瓦塔自己不想,它只想要雨。", "同盟要我們的水,沙伊拉加爾要我們的路,鍍金宮廷要我們的米。人人都想要伊拉瓦塔,只有伊拉瓦塔自己不想,它只想要雨。", "Liên minh muốn nước của chúng ta, Shailagarh muốn đường sá của chúng ta, Triều Mạ Vàng muốn gạo của chúng ta. Ai cũng muốn Ilavarta, trừ chính Ilavarta, vốn chỉ muốn mưa.", "Liga menginginkan air kami, Shailagarh menginginkan jalan kami, Istana Bersepuh menginginkan beras kami. Semua menginginkan Ilavarta kecuali Ilavarta, yang hanya ingin hujan.", "สันนิบาตอยากได้น้ำของเรา ไศลครห์อยากได้ถนนของเรา ราชสำนักปิดทองอยากได้ข้าวของเรา ทุกคนอยากได้อิลาวรรตะ ยกเว้นอิลาวรรตะเอง ที่อยากได้แค่ฝน", "Birlik suyumuzu, Shailagarh yollarımızı, Yaldızlı Saray pirincimizi istiyor. Ilavarta'yı herkes istiyor, Ilavarta hariç; o yalnızca yağmur istiyor.", "La Liga quiere nuestra agua, Shailagarh nuestros caminos, la Corte Dorada nuestro arroz. Todos quieren Ilavarta salvo Ilavarta, que solo quiere lluvia.", "A Liga quer nossa água, Shailagarh quer nossas estradas, a Corte Dourada quer nosso arroz. Todos querem Ilavarta, menos Ilavarta, que só quer chuva.", "Лиге нужна наша вода, Шайлагарху — наши дороги, Позолоченному двору — наш рис. Илаварта нужна всем, кроме самой Илаварты, которой нужен лишь дождь.", "Лізі потрібна наша вода, Шайлагарху — наші дороги, Позолоченому двору — наш рис. Ілаварта потрібна всім, окрім самої Ілаварти, якій потрібен лише дощ."],
  "Every tank in the valley is a third full of silt. A third! In ten years the rain will run straight to the sea, and so will we.": ["谷の貯水池はどれも三分の一が泥で埋まっている。三分の一だぞ!十年もすれば雨はまっすぐ海へ流れていく。我々も同じだ。", "계곡의 저수지마다 3분의 1이 토사로 차 있소. 3분의 1이오! 십 년이면 비는 곧장 바다로 흘러가 버릴 거고, 우리도 그렇게 될 거요.", "河谷里每个水池都有三分之一是淤泥。三分之一!十年之内,雨水会直接流进大海,我们也一样。", "河谷裡每個水池都有三分之一是淤泥。三分之一!十年之內,雨水會直接流進大海,我們也一樣。", "Mọi hồ chứa trong thung lũng đều đầy bùn một phần ba. Một phần ba đấy! Mười năm nữa nước mưa sẽ chảy thẳng ra biển, và chúng ta cũng thế.", "Setiap telaga di lembah sepertiganya penuh lumpur. Sepertiga! Dalam sepuluh tahun hujan akan mengalir langsung ke laut, dan begitu pula kita.", "สระทุกแห่งในหุบเขามีตะกอนอยู่หนึ่งในสาม หนึ่งในสามเชียวนะ! อีกสิบปีน้ำฝนจะไหลตรงลงทะเล แล้วเราก็จะไหลตามไปด้วย", "Vadideki her havuzun üçte biri alüvyonla dolu. Üçte biri! On yıl içinde yağmur doğruca denize akacak, biz de öyle.", "Todos los estanques del valle están llenos de limo hasta un tercio. ¡Un tercio! En diez años la lluvia correrá directa al mar, y nosotros también.", "Todo tanque do vale está um terço cheio de lodo. Um terço! Em dez anos a chuva vai correr direto para o mar, e nós também.", "Каждый пруд в долине на треть забит илом. На треть! Через десять лет дождь будет стекать прямо в море, и мы вместе с ним.", "Кожен став у долині на третину замулений. На третину! За десять років дощ стікатиме просто в море, і ми разом із ним."],
  "The temple has three centuries of offerings in its vaults. Three centuries of gold, given to the river. I'm only asking to give it to the river properly.": ["寺院の宝庫には三百年分の供物がある。川に捧げられた三百年分の金だ。私はただ、それをちゃんと川に捧げようと言っているだけだ。", "사원 금고에는 삼백 년치 공물이 있소. 강에 바친 삼백 년치 금이지. 나는 그저 그걸 강에 제대로 바치자는 것뿐이오.", "神庙的库房里有三百年的供奉。三百年的金子,都是献给河流的。我只是请求把它好好地献给河流。", "神廟的庫房裡有三百年的供奉。三百年的金子,都是獻給河流的。我只是請求把它好好地獻給河流。", "Kho của đền có ba thế kỷ đồ cúng. Ba thế kỷ vàng, dâng cho dòng sông. Tôi chỉ xin dâng nó cho dòng sông một cách đúng đắn.", "Kuil itu menyimpan persembahan tiga abad di ruang hartanya. Tiga abad emas, diberikan kepada sungai. Aku hanya meminta agar itu diberikan kepada sungai dengan benar.", "วิหารมีเครื่องบูชาสามศตวรรษอยู่ในห้องคลัง ทองสามศตวรรษที่ถวายแด่แม่น้ำ ข้าเพียงขอให้ถวายมันแด่แม่น้ำอย่างถูกต้อง", "Tapınağın mahzenlerinde üç asırlık adak var. Nehre verilmiş üç asırlık altın. Ben sadece onu nehre gerektiği gibi vermeyi istiyorum.", "El templo guarda en sus cámaras tres siglos de ofrendas. Tres siglos de oro, dado al río. Solo pido dárselo al río como es debido.", "O templo tem três séculos de oferendas em seus cofres. Três séculos de ouro, dado ao rio. Só estou pedindo para dá-lo ao rio direito.", "В хранилищах храма — подношения за три столетия. Три столетия золота, отданного реке. Я лишь прошу отдать его реке как следует.", "У сховищах храму — пожертви за три століття. Три століття золота, відданого річці. Я лише прошу віддати його річці як слід."],
  "Look at this rod. That's the Great Tank's depth when I was a boy. This mark's today. Do the arithmetic; I have.": ["この竿を見ろ。これが私が子供の頃の大貯水池の深さだ。この印が今日の深さ。計算してみろ。私はもうした。", "이 측량대를 보시오. 이게 내가 어릴 적 대저수지의 깊이요. 이 눈금이 오늘이고. 계산해 보시오. 나는 해 봤소.", "看看这根标尺。这是我小时候大水池的深度。这道刻痕是今天的。你算算吧;我算过了。", "看看這根標尺。這是我小時候大水池的深度。這道刻痕是今天的。你算算吧;我算過了。", "Nhìn cây thước đo này. Đây là độ sâu của Hồ Lớn hồi tôi còn bé. Vạch này là hôm nay. Tự tính đi; tôi tính rồi.", "Lihat tongkat ini. Itu kedalaman Telaga Agung waktu aku kecil. Tanda ini hari ini. Hitung saja; aku sudah.", "ดูไม้วัดนี่สิ นี่คือความลึกของสระใหญ่ตอนข้ายังเด็ก ขีดนี้คือวันนี้ ลองคำนวณดู ข้าคำนวณแล้ว", "Şu sopaya bak. Bu, ben çocukken Büyük Havuz'un derinliği. Bu çentik bugünkü. Hesabı yap; ben yaptım.", "Mira esta vara. Esa era la profundidad del Gran Estanque cuando yo era niño. Esta marca es la de hoy. Haz la cuenta; yo ya la hice.", "Olhe esta vara. Essa era a profundidade do Grande Tanque quando eu era menino. Esta marca é a de hoje. Faça as contas; eu já fiz.", "Взгляни на эту рейку. Вот глубина Великого пруда, когда я был мальчишкой. А эта отметка — сегодня. Посчитай сам; я посчитал.", "Поглянь на цю рейку. Ось глибина Великого ставу, коли я був хлопчиком. А ця позначка — сьогодні. Порахуй сам; я порахував."],
  "The engineers would empty the vaults into a ditch and call it a canal. What's given to the river isn't ours to spend.": ["技師どもは宝庫を空にして溝に流し込み、それを運河と呼ぶだろう。川に捧げたものは、我らが使ってよいものではない。", "기술자들은 금고를 비워 도랑에 쏟아붓고는 운하라고 부를 거요. 강에 바친 것은 우리가 쓸 것이 아니오.", "那些工程师会把库房倒空,填进一条沟里,再管它叫运河。献给河流的东西,不是我们能花的。", "那些工程師會把庫房倒空,填進一條溝裡,再管它叫運河。獻給河流的東西,不是我們能花的。", "Đám kỹ sư sẽ dốc sạch kho vào một con mương rồi gọi đó là kênh đào. Thứ đã dâng cho dòng sông không phải để chúng ta tiêu.", "Para insinyur itu akan mengosongkan ruang harta ke dalam parit dan menyebutnya kanal. Apa yang diberikan kepada sungai bukan milik kita untuk dibelanjakan.", "พวกวิศวกรจะเทคลังจนเกลี้ยงลงคูน้ำแล้วเรียกมันว่าคลอง สิ่งที่ถวายแด่แม่น้ำแล้วไม่ใช่ของเราที่จะเอาไปใช้", "Mühendisler mahzenleri bir hendeğe boşaltıp adına kanal derler. Nehre verilen, bizim harcayacağımız şey değildir.", "Los ingenieros vaciarían las cámaras en una zanja y la llamarían canal. Lo que se da al río no es nuestro para gastarlo.", "Os engenheiros esvaziariam os cofres numa vala e chamariam isso de canal. O que é dado ao rio não é nosso para gastar.", "Инженеры вывалили бы хранилища в канаву и назвали бы её каналом. Отданное реке не нам тратить.", "Інженери вивалили б сховища в рів і назвали б його каналом. Віддане річці не нам витрачати."],
  "Devakar is a good man with a bad plan. He'd dig out the silt and in ten years dig it out again. Someone must pay for the forests upstream that let it in.": ["デヴァカルは善い男だが、計画が悪い。泥を掘り出しても、十年後にはまた掘り出すことになる。泥を流れ込ませた上流の森の代償を、誰かが払わねばならない。", "데바카르는 좋은 사람이지만 계획이 나쁘오. 토사를 파내면 십 년 뒤 또 파내야 할 거요. 토사가 흘러들게 만든 상류 숲의 값을 누군가는 치러야 하오.", "德瓦卡尔是个好人,计划却不好。他把淤泥挖出来,十年后还得再挖一遍。上游那些让淤泥流进来的森林,总得有人为它们付账。", "德瓦卡爾是個好人,計畫卻不好。他把淤泥挖出來,十年後還得再挖一遍。上游那些讓淤泥流進來的森林,總得有人為它們付帳。", "Devakar là người tốt với một kế hoạch tồi. Ông ấy sẽ nạo bùn lên, rồi mười năm sau lại nạo lần nữa. Phải có ai đó trả giá cho những cánh rừng thượng nguồn đã để bùn tràn vào.", "Devakar orang baik dengan rencana buruk. Ia akan mengeruk lumpur itu dan sepuluh tahun lagi mengeruknya lagi. Seseorang harus membayar untuk hutan di hulu yang membiarkannya masuk.", "เทวกรเป็นคนดีที่มีแผนแย่ เขาจะขุดลอกตะกอนออก แล้วอีกสิบปีก็ต้องขุดอีก ต้องมีใครสักคนจ่ายค่าป่าต้นน้ำที่ปล่อยให้ตะกอนไหลเข้ามา", "Devakar kötü bir planı olan iyi bir adam. Alüvyonu kazır, on yıl sonra yine kazır. Onu içeri sokan yukarı havzadaki ormanların bedelini birinin ödemesi gerek.", "Devakar es un buen hombre con un mal plan. Sacaría el limo y en diez años tendría que sacarlo otra vez. Alguien tiene que pagar por los bosques río arriba que lo dejan entrar.", "Devakar é um bom homem com um mau plano. Ele dragaria o lodo e em dez anos teria de dragá-lo de novo. Alguém precisa pagar pelas florestas rio acima que o deixam entrar.", "Девакар — хороший человек с плохим планом. Он вычистит ил, а через десять лет будет чистить снова. Кто-то должен заплатить за леса выше по течению, которые его пропускают.", "Девакар — добра людина з поганим планом. Він вичистить мул, а за десять років чиститиме знову. Хтось мусить заплатити за ліси вище за течією, які його пропускають."],
  "The offerings are an account the river keeps. You don't spend an account; you keep it.": ["供物は川がつけている帳簿だ。帳簿は使うものではない。つけておくものだ。", "공물은 강이 관리하는 장부요. 장부는 쓰는 게 아니라 지키는 거요.", "供奉是河流记着的一本账。账不是拿来花的,是拿来记的。", "供奉是河流記著的一本帳。帳不是拿來花的,是拿來記的。", "Đồ cúng là một cuốn sổ mà dòng sông giữ. Sổ sách không phải để tiêu; mà để giữ.", "Persembahan itu adalah rekening yang disimpan sungai. Rekening tidak dibelanjakan; rekening disimpan.", "เครื่องบูชาคือบัญชีที่แม่น้ำจดไว้ บัญชีไม่ใช่ของที่เอาไปใช้ แต่เป็นของที่ต้องรักษาไว้", "Adaklar nehrin tuttuğu bir hesaptır. Hesap harcanmaz; tutulur.", "Las ofrendas son una cuenta que lleva el río. Una cuenta no se gasta; se lleva.", "As oferendas são uma conta que o rio mantém. Não se gasta uma conta; se mantém.", "Подношения — это счёт, который ведёт река. Счёт не тратят; его ведут.", "Пожертви — це рахунок, який веде річка. Рахунок не витрачають; його ведуть."],
  "The Gilded Court buys Ilavarta's rice. Ilavarta buys Kharaveth's salt and linen. Everybody's happy, mostly.": ["金色の宮廷はイラヴァルタの米を買う。イラヴァルタはカラヴェスの塩と亜麻布を買う。みんな幸せさ、だいたいはね。", "황금 궁정은 일라바르타의 쌀을 사지. 일라바르타는 카라베스의 소금과 아마포를 사고. 다들 행복해, 대체로는.", "镀金宫廷买伊拉瓦塔的米。伊拉瓦塔买卡拉维斯的盐和亚麻布。大家都很满意,大体上。", "鍍金宮廷買伊拉瓦塔的米。伊拉瓦塔買卡拉維斯的鹽和亞麻布。大家都很滿意,大體上。", "Triều Mạ Vàng mua gạo của Ilavarta. Ilavarta mua muối và vải lanh của Kharaveth. Ai cũng vui, phần lớn là vậy.", "Istana Bersepuh membeli beras Ilavarta. Ilavarta membeli garam dan linen Kharaveth. Semua orang senang, sebagian besar.", "ราชสำนักปิดทองซื้อข้าวของอิลาวรรตะ อิลาวรรตะซื้อเกลือกับผ้าลินินของคาราเวธ ทุกคนก็พอใจ ส่วนใหญ่น่ะนะ", "Yaldızlı Saray, Ilavarta'nın pirincini alır. Ilavarta da Kharaveth'in tuzunu ve ketenini. Herkes mutlu, çoğunlukla.", "La Corte Dorada compra el arroz de Ilavarta. Ilavarta compra la sal y el lino de Kharaveth. Todos contentos, más o menos.", "A Corte Dourada compra o arroz de Ilavarta. Ilavarta compra o sal e o linho de Kharaveth. Todo mundo feliz, quase sempre.", "Позолоченный двор покупает рис Илаварты. Илаварта покупает соль и лён Харавета. Все довольны, в основном.", "Позолочений двір купує рис Ілаварти. Ілаварта купує сіль і льон Харавета. Усі задоволені, здебільшого."],
  "Prices? Prices are the weather. I merely carry an umbrella.": ["値段?値段なんて天気みたいなもんだ。私はただ傘を持ち歩いているだけさ。", "가격? 가격은 날씨야. 나는 그저 우산을 들고 다닐 뿐이지.", "价格?价格就是天气。我不过是随身带把伞。", "價格?價格就是天氣。我不過是隨身帶把傘。", "Giá cả? Giá cả là thời tiết. Tôi chỉ mang theo một cái ô thôi.", "Harga? Harga itu cuaca. Saya hanya sedia payung.", "ราคาเหรอ ราคาก็คือดินฟ้าอากาศ ข้าแค่พกร่มติดตัวไว้เท่านั้น", "Fiyatlar mı? Fiyatlar havadır. Ben yalnızca şemsiye taşırım.", "¿Precios? Los precios son el tiempo. Yo solo llevo un paraguas.", "Preços? Preços são o clima. Eu só carrego um guarda-chuva.", "Цены? Цены — это погода. Я всего лишь ношу зонт.", "Ціни? Ціни — це погода. Я лише ношу парасольку."],
  "Lady Seleneh sends her regards to the Queen. And an offer for next year's harvest, at this year's price.": ["セレネ卿より女王陛下へよろしくとのこと。それと、来年の収穫への申し出を、今年の値段で。", "셀레네 귀부인께서 여왕께 안부를 전하십니다. 그리고 내년 수확에 대한 제안도요, 올해 가격으로.", "塞勒涅夫人向女王致意。顺便为明年的收成报个价,按今年的价格。", "塞勒涅夫人向女王致意。順便為明年的收成報個價,按今年的價格。", "Phu nhân Seleneh gửi lời thăm Nữ hoàng. Kèm một lời đề nghị cho mùa gặt năm sau, theo giá năm nay.", "Nyonya Seleneh menyampaikan salam kepada Ratu. Beserta tawaran untuk panen tahun depan, dengan harga tahun ini.", "ท่านหญิงเซเลเนห์ฝากความคิดถึงถึงราชินี พร้อมข้อเสนอสำหรับผลผลิตปีหน้า ในราคาของปีนี้", "Leydi Seleneh, Kraliçe'ye selamlarını gönderiyor. Bir de gelecek yılın hasadı için bir teklif, bu yılın fiyatından.", "Lady Seleneh envía sus saludos a la Reina. Y una oferta por la cosecha del año que viene, al precio de este año.", "Lady Seleneh manda lembranças à Rainha. E uma oferta pela colheita do ano que vem, pelo preço deste ano.", "Леди Селене шлёт поклон Королеве. И предложение на урожай следующего года — по цене этого.", "Леді Селене передає вітання Королеві. І пропозицію на врожай наступного року — за цінами цього."],
  "Dawn and dusk, the whole city comes down the ghats. You can tell who's quarrelling by who takes which steps.": ["夜明けと夕暮れには、街じゅうがガートを下りてくる。誰がどの段を使うかで、誰と誰が喧嘩中か分かるよ。", "새벽과 해 질 녘이면 온 도시가 가트를 내려오지. 누가 어느 계단으로 가는지 보면 누가 싸우는 중인지 알 수 있어.", "黎明和黄昏,全城的人都走下河阶。看谁走哪段台阶,就知道谁在跟谁吵架。", "黎明和黃昏,全城的人都走下河階。看誰走哪段台階,就知道誰在跟誰吵架。", "Bình minh và hoàng hôn, cả thành phố xuống các bậc ghat. Nhìn ai đi bậc nào là biết ai đang cãi nhau với ai.", "Fajar dan senja, seluruh kota turun lewat tangga ghat. Kau bisa tahu siapa yang sedang bertengkar dari siapa menapaki anak tangga yang mana.", "ทั้งรุ่งเช้าและพลบค่ำ คนทั้งเมืองจะลงมาที่ท่าน้ำ ดูว่าใครเดินบันไดขั้นไหนก็รู้แล้วว่าใครทะเลาะกับใครอยู่", "Şafakta ve akşam karanlığında bütün şehir gat basamaklarından iner. Kimin hangi basamakları kullandığına bakıp kimin kiminle kavgalı olduğunu anlarsın.", "Al alba y al anochecer, toda la ciudad baja por los ghats. Se sabe quién está peleado con quién por los escalones que toma cada uno.", "Ao amanhecer e ao entardecer, a cidade inteira desce os ghats. Dá para saber quem está brigado com quem pelos degraus que cada um escolhe.", "На рассвете и в сумерки весь город спускается по гатам. Кто с кем в ссоре — видно по тому, кто по каким ступеням идёт.", "На світанку й у присмерку все місто спускається гатами. Хто з ким посварився — видно з того, хто якими сходами йде."],
  "The water's lower than my father's day. Lower than my day, come to that. The engineers say silt. I say sorrow, but I'm only a ghat-keeper.": ["水位は親父の頃より低い。いや、私の若い頃よりもな。技師たちは泥のせいだと言う。私は悲しみのせいだと思うが、ただのガート番だからね。", "물이 우리 아버지 시절보다 낮아. 따지고 보면 내 젊은 시절보다도 낮지. 기술자들은 토사 탓이라더군. 난 슬픔 탓이라고 보지만, 일개 가트지기일 뿐이니까.", "水位比我父亲那时低了。说起来,也比我年轻时低。工程师说是淤泥。我说是哀愁,不过我只是个守河阶的。", "水位比我父親那時低了。說起來,也比我年輕時低。工程師說是淤泥。我說是哀愁,不過我只是個守河階的。", "Nước thấp hơn thời cha tôi. Mà nói cho đúng, thấp hơn cả thời tôi. Các kỹ sư bảo là phù sa. Tôi bảo là nỗi buồn, nhưng tôi chỉ là người giữ bậc ghat.", "Airnya lebih rendah daripada zaman ayahku. Lebih rendah daripada zamanku juga, kalau dipikir. Para insinyur bilang lumpur. Kubilang duka, tapi aku cuma penjaga tangga ghat.", "น้ำลดต่ำกว่าสมัยพ่อข้า ว่าไปแล้วก็ต่ำกว่าสมัยข้าเองด้วย พวกวิศวกรบอกว่าเป็นเพราะตะกอน ข้าว่าเป็นเพราะความโศก แต่ข้าก็เป็นแค่คนเฝ้าท่าน้ำ", "Su, babamın zamanındakinden alçak. Hatta benim zamanımdakinden de. Mühendisler alüvyon diyor. Ben keder diyorum ama ben sadece bir gat bekçisiyim.", "El agua está más baja que en tiempos de mi padre. Más baja que en los míos, ya puestos. Los ingenieros dicen que es el limo. Yo digo que es la pena, pero solo soy un guardián de ghats.", "A água está mais baixa que no tempo do meu pai. Mais baixa que no meu, aliás. Os engenheiros dizem que é lodo. Eu digo que é tristeza, mas sou só um guardião dos ghats.", "Вода ниже, чем при моём отце. Да и чем при мне, если уж на то пошло. Инженеры говорят — ил. Я говорю — печаль, но я всего лишь смотритель гатов.", "Вода нижча, ніж за мого батька. Та й ніж за мене, якщо вже на те пішло. Інженери кажуть — мул. Я кажу — смуток, але я лише доглядач гатів."],
  "Toll's by the head, by the cart, by the beast. The ford at Tirthali's free, if you like wet boots.": ["通行料は一人ごと、荷車ごと、家畜ごと。ティルタリの浅瀬ならタダだよ、濡れたブーツが好きならね。", "통행료는 사람당, 수레당, 짐승당 받아. 티르탈리 여울은 공짜지, 젖은 장화가 좋다면.", "过路费按人头、按车、按牲口收。提尔塔利的浅滩是免费的,如果你喜欢湿靴子的话。", "過路費按人頭、按車、按牲口收。提爾塔利的淺灘是免費的,如果你喜歡濕靴子的話。", "Phí qua cầu tính theo đầu người, theo xe, theo gia súc. Bến lội ở Tirthali thì miễn phí, nếu bạn thích ủng ướt.", "Tol dihitung per kepala, per gerobak, per hewan. Penyeberangan di Tirthali gratis, kalau kau suka sepatu bot basah.", "ค่าผ่านทางคิดต่อหัว ต่อเกวียน ต่อสัตว์ ท่าข้ามที่ตีรถลีน่ะฟรี ถ้าเจ้าชอบรองเท้าเปียก", "Geçiş ücreti kişi başı, araba başı, hayvan başı. Tirthali'deki sığ geçit bedava, ıslak çizmeyi seviyorsan.", "El peaje va por cabeza, por carro y por bestia. El vado de Tirthali es gratis, si te gustan las botas mojadas.", "O pedágio é por cabeça, por carroça, por animal. O vau de Tirthali é de graça, se você gosta de bota molhada.", "Пошлина — с головы, с телеги, со скотины. Брод у Тиртхали бесплатный, если любишь мокрые сапоги.", "Мито — з голови, з воза, з худоби. Брід біля Тіртхалі безкоштовний, якщо любиш мокрі чоботи."],
  "The League says the Queen's toll is robbery. The Queen says the bridge didn't build itself. I say pay up, please.": ["同盟は女王の通行料を強盗だと言う。女王は橋が勝手に建ったわけじゃないと言う。私は言う、お支払いをどうぞ。", "동맹은 여왕의 통행료가 강도질이라고 하지. 여왕은 다리가 저절로 지어진 게 아니라고 하고. 나는 이렇게 말하지. 내세요, 부탁합니다.", "同盟说女王的过路费是抢劫。女王说桥可不是自己长出来的。我说:请交钱。", "同盟說女王的過路費是搶劫。女王說橋可不是自己長出來的。我說:請交錢。", "Liên minh bảo phí cầu của Nữ hoàng là ăn cướp. Nữ hoàng bảo cây cầu đâu có tự mọc lên. Còn tôi bảo: làm ơn trả tiền.", "Liga bilang tol Ratu itu perampokan. Ratu bilang jembatan itu tidak membangun dirinya sendiri. Aku bilang: silakan bayar.", "สันนิบาตว่าค่าผ่านทางของราชินีคือการปล้น ราชินีว่าสะพานไม่ได้สร้างตัวเองขึ้นมา ข้าว่า จ่ายมาเถอะ ได้โปรด", "Birlik, Kraliçe'nin geçiş ücretinin soygun olduğunu söylüyor. Kraliçe, köprünün kendi kendine yapılmadığını söylüyor. Ben de diyorum ki: ödeyin lütfen.", "La Liga dice que el peaje de la Reina es un robo. La Reina dice que el puente no se construyó solo. Yo digo: pague, por favor.", "A Liga diz que o pedágio da Rainha é um roubo. A Rainha diz que a ponte não se construiu sozinha. Eu digo: pague, por favor.", "Лига говорит, что пошлина Королевы — грабёж. Королева говорит, что мост сам себя не построил. А я говорю: платите, пожалуйста.", "Ліга каже, що мито Королеви — грабунок. Королева каже, що міст сам себе не збудував. А я кажу: платіть, будь ласка."],
  "Rice, lentils, wicks, rope. Everything a house needs, and the news from the palace thrown in.": ["米、豆、灯芯、縄。家に要るものは何でも。おまけに宮殿の噂話もつけるよ。", "쌀, 렌틸콩, 심지, 밧줄. 집에 필요한 건 다 있지. 궁전 소식은 덤이고.", "米、扁豆、灯芯、绳子。一户人家需要的都有,宫里的消息白送。", "米、扁豆、燈芯、繩子。一戶人家需要的都有,宮裡的消息白送。", "Gạo, đậu lăng, bấc đèn, dây thừng. Mọi thứ một nhà cần, kèm luôn tin tức từ cung điện.", "Beras, lentil, sumbu, tali. Semua yang dibutuhkan rumah, plus kabar dari istana sebagai bonus.", "ข้าว ถั่วเลนทิล ไส้ตะเกียง เชือก ทุกอย่างที่บ้านต้องใช้ แถมข่าวจากในวังให้ฟรี", "Pirinç, mercimek, fitil, ip. Bir evin ihtiyacı olan her şey, üstüne de saraydan haberler.", "Arroz, lentejas, mechas, cuerda. Todo lo que necesita una casa, y de regalo las noticias de palacio.", "Arroz, lentilha, pavio, corda. Tudo que uma casa precisa, e de brinde as notícias do palácio.", "Рис, чечевица, фитили, верёвка. Всё, что нужно в доме, а новости из дворца — в придачу.", "Рис, сочевиця, ґноти, мотузка. Усе, що потрібно в домі, а новини з палацу — на додачу."],
  "The engineers were in here buying rope. The treasurers were in here buying locks. Draw your own conclusions.": ["技師たちが縄を買いに来た。会計役たちは錠前を買いに来た。結論はご自分でどうぞ。", "기술자들이 와서 밧줄을 사 갔어. 재무관들은 와서 자물쇠를 사 갔고. 결론은 알아서 내.", "工程师们来这儿买绳子。司库们来这儿买锁。你自己琢磨吧。", "工程師們來這兒買繩子。司庫們來這兒買鎖。你自己琢磨吧。", "Các kỹ sư vào đây mua dây thừng. Các thủ quỹ vào đây mua ổ khóa. Tự mà suy ra nhé.", "Para insinyur datang ke sini membeli tali. Para bendahara datang ke sini membeli gembok. Simpulkan sendiri.", "พวกวิศวกรมาซื้อเชือกที่นี่ พวกเหรัญญิกมาซื้อแม่กุญแจ สรุปเอาเองแล้วกัน", "Mühendisler buraya ip almaya geldi. Haznedarlar da kilit almaya. Gerisini sen düşün.", "Los ingenieros vinieron a comprar cuerda. Los tesoreros vinieron a comprar cerrojos. Saca tus propias conclusiones.", "Os engenheiros vieram comprar corda. Os tesoureiros vieram comprar cadeados. Tire suas próprias conclusões.", "Инженеры заходили за верёвкой. Казначеи заходили за замками. Выводы делайте сами.", "Інженери заходили по мотузку. Скарбники заходили по замки. Висновки робіть самі."],
  "Tank blue and lotus white: Ilavarta's colours. Wear them at the ghats and the old women will nod at you.": ["貯水池の青と蓮の白、イラヴァルタの色だ。それを着てガートに行けば、婆さまたちがうなずいてくれるよ。", "저수지의 푸른색과 연꽃의 흰색. 일라바르타의 색이지. 그걸 입고 가트에 가면 할머니들이 고개를 끄덕여 줄 거야.", "水池蓝和莲花白:伊拉瓦塔的颜色。穿着它们去河阶,老太太们会冲你点头。", "水池藍和蓮花白:伊拉瓦塔的顏色。穿著它們去河階,老太太們會衝你點頭。", "Xanh hồ chứa và trắng hoa sen: màu của Ilavarta. Mặc chúng ra bậc ghat là các bà cụ sẽ gật đầu với bạn.", "Biru telaga dan putih teratai: warna Ilavarta. Kenakan itu di tangga ghat dan para nenek akan mengangguk padamu.", "ฟ้าสระน้ำและขาวดอกบัว สีของอิลาวรรตะ ใส่ไปที่ท่าน้ำสิ แล้วพวกยายๆ จะพยักหน้าให้เจ้า", "Havuz mavisi ve nilüfer beyazı: Ilavarta'nın renkleri. Onları giyip gat basamaklarına git, yaşlı kadınlar sana başıyla selam verir.", "Azul estanque y blanco loto: los colores de Ilavarta. Llévalos en los ghats y las ancianas te saludarán con la cabeza.", "Azul de tanque e branco de lótus: as cores de Ilavarta. Use-as nos ghats e as velhinhas vão te cumprimentar com a cabeça.", "Прудовая синева и белизна лотоса — цвета Илаварты. Надень их на гатах, и старухи тебе кивнут.", "Ставкова синь і білизна лотоса — кольори Ілаварти. Вдягни їх на гатах, і бабусі тобі кивнуть."],
  "Welcome to the Lotus! The rice is from the valley, the lentils from the plains, and the arguments from the palace.": ["ロータス亭へようこそ!米は谷から、豆は平原から、口論は宮殿から仕入れてるよ。", "연꽃 식당에 어서 와! 쌀은 계곡에서, 렌틸콩은 평원에서, 말다툼은 궁전에서 왔지.", "欢迎光临莲花馆!米来自河谷,扁豆来自平原,争吵来自王宫。", "歡迎光臨蓮花館!米來自河谷,扁豆來自平原,爭吵來自王宮。", "Chào mừng đến quán Hoa Sen! Gạo từ thung lũng, đậu lăng từ đồng bằng, còn chuyện cãi vã thì từ cung điện.", "Selamat datang di Teratai! Berasnya dari lembah, lentilnya dari dataran, dan perdebatannya dari istana.", "ยินดีต้อนรับสู่ร้านดอกบัว! ข้าวมาจากหุบเขา ถั่วมาจากที่ราบ ส่วนการทะเลาะมาจากในวัง", "Nilüfer'e hoş geldin! Pirinç vadiden, mercimek ovadan, tartışmalar da saraydan.", "¡Bienvenido al Loto! El arroz es del valle, las lentejas de las llanuras y las discusiones del palacio.", "Bem-vindo ao Lótus! O arroz vem do vale, a lentilha das planícies e as discussões do palácio.", "Добро пожаловать в «Лотос»! Рис из долины, чечевица с равнин, а споры — из дворца.", "Ласкаво просимо до «Лотоса»! Рис із долини, сочевиця з рівнин, а суперечки — з палацу."],
  "Eat before the rain. Everybody comes in at once when it starts.": ["雨の前に食べときな。降り出すとみんな一斉に入ってくるから。", "비 오기 전에 먹어 둬. 비가 시작되면 다들 한꺼번에 몰려오거든.", "趁下雨前吃吧。雨一下,所有人都会一窝蜂涌进来。", "趁下雨前吃吧。雨一下,所有人都會一窩蜂湧進來。", "Ăn trước khi mưa đi. Mưa bắt đầu là cả đám ùa vào cùng lúc.", "Makanlah sebelum hujan. Begitu mulai, semua orang masuk bersamaan.", "กินก่อนฝนตกนะ พอฝนเริ่มเมื่อไหร่ ทุกคนจะแห่เข้ามาพร้อมกันหมด", "Yağmurdan önce ye. Başladı mı herkes bir anda içeri doluşur.", "Come antes de la lluvia. Cuando empieza, entra todo el mundo a la vez.", "Coma antes da chuva. Quando ela começa, todo mundo entra de uma vez.", "Поешь до дождя. Как начнётся, все повалят сюда разом.", "Поїж до дощу. Щойно почнеться, всі сюди ринуть разом."],
  "Sluice gates for the engineers, sabres for the guards, and an invoice for the treasurers they haven't paid since spring.": ["技師には水門を、衛兵にはサーベルを、そして会計役には春から払ってもらっていない請求書を。", "기술자들에겐 수문을, 경비병들에겐 군도를, 재무관들에겐 봄부터 안 낸 청구서를.", "给工程师造水闸,给卫兵打军刀,给司库们开一张他们从春天起就没付的账单。", "給工程師造水閘,給衛兵打軍刀,給司庫們開一張他們從春天起就沒付的帳單。", "Cửa cống cho các kỹ sư, kiếm cong cho lính gác, và một tờ hóa đơn cho các thủ quỹ mà họ chưa trả từ mùa xuân.", "Pintu air untuk para insinyur, pedang lengkung untuk para pengawal, dan tagihan untuk para bendahara yang belum mereka bayar sejak musim semi.", "ประตูระบายน้ำให้พวกวิศวกร ดาบโค้งให้พวกทหารยาม และใบแจ้งหนี้ให้พวกเหรัญญิกที่ยังไม่จ่ายมาตั้งแต่ฤดูใบไม้ผลิ", "Mühendislere savak kapakları, muhafızlara kılıçlar, haznedarlara da bahardan beri ödemedikleri bir fatura.", "Compuertas para los ingenieros, sables para los guardias y una factura para los tesoreros que no pagan desde la primavera.", "Comportas para os engenheiros, sabres para os guardas e uma fatura para os tesoureiros que não pagam desde a primavera.", "Шлюзовые затворы — инженерам, сабли — стражникам, а казначеям — счёт, который они не оплачивают с весны.", "Шлюзові затвори — інженерам, шаблі — вартовим, а скарбникам — рахунок, який вони не сплачують від весни."],
  "An Ilavati sabre: curved for the cut, a disc on the pommel so it doesn't leave your hand on wet steps.": ["イラヴァティのサーベル。斬るための反り、濡れた石段で手から離れないよう柄頭に円盤がついている。", "일라바티 군도. 베기 좋게 휘었고, 젖은 계단에서 손에서 빠지지 않도록 칼자루 끝에 원반이 달려 있다.", "伊拉瓦蒂军刀:刀身弯曲利于劈砍,柄头带圆盘,在湿滑的台阶上也不会脱手。", "伊拉瓦蒂軍刀:刀身彎曲利於劈砍,柄頭帶圓盤,在濕滑的台階上也不會脫手。", "Kiếm cong Ilavati: lưỡi cong để chém, chuôi có đĩa tròn để không tuột tay trên bậc thềm ướt.", "Pedang lengkung Ilavati: melengkung untuk menebas, cakram di pangkal gagang agar tak lepas dari tangan di tangga basah.", "ดาบโค้งอิลาวดี โค้งไว้สำหรับฟัน มีจานกลมที่ปลายด้ามเพื่อไม่ให้หลุดมือบนขั้นบันไดเปียก", "Bir Ilavati kılıcı: kesmek için kavisli, ıslak basamaklarda elinden kaymasın diye kabzasının ucunda bir disk var.", "Un sable ilavati: curvo para el tajo, con un disco en el pomo para que no se te escape de la mano en escalones mojados.", "Um sabre ilavati: curvo para o corte, com um disco no pomo para não escapar da mão em degraus molhados.", "Илаватийская сабля: изогнута для рубящего удара, с диском на навершии, чтобы не выскользнула из руки на мокрых ступенях.", "Ілаватійська шабля: вигнута для рубу, з диском на навершші, щоб не вислизнула з руки на мокрих сходах."],
  "Keep to the ghats' left side going down, right side coming up. It's the law, and the old women enforce it.": ["ガートは下りは左側、上りは右側。それが決まりで、取り締まるのは婆さまたちだ。", "가트를 내려갈 땐 왼쪽, 올라올 땐 오른쪽으로 다녀. 그게 법이고, 집행은 할머니들이 하지.", "下河阶靠左,上河阶靠右。这是规矩,执法的是老太太们。", "下河階靠左,上河階靠右。這是規矩,執法的是老太太們。", "Xuống bậc ghat thì đi bên trái, lên thì đi bên phải. Đó là luật, và các bà cụ là người thi hành.", "Di tangga ghat, turun lewat sisi kiri, naik lewat sisi kanan. Itu hukum, dan para nenek yang menegakkannya.", "ลงท่าน้ำให้ชิดซ้าย ขึ้นให้ชิดขวา นี่คือกฎหมาย และพวกยายๆ คือผู้บังคับใช้", "Gat basamaklarından inerken sol taraftan, çıkarken sağ taraftan git. Kanun bu, uygulayanlar da yaşlı kadınlar.", "En los ghats, por la izquierda al bajar y por la derecha al subir. Es la ley, y la hacen cumplir las ancianas.", "Nos ghats, pela esquerda ao descer e pela direita ao subir. É a lei, e quem a faz cumprir são as velhinhas.", "По гатам спускайся слева, поднимайся справа. Таков закон, и следят за ним старухи.", "Гатами спускайся ліворуч, підіймайся праворуч. Такий закон, і стежать за ним бабусі."],
  "The Queen's peace is kept in Sarovan. Outside the walls it's kept by whoever's nearest.": ["サロヴァンでは女王の平和が守られている。城壁の外では、一番近くにいる者が守ってる。", "사로반에선 여왕의 평화가 지켜지지. 성벽 밖에선 제일 가까이 있는 사람이 지키고.", "在萨罗万,维持的是女王的太平。出了城墙,谁离得近谁说了算。", "在薩羅萬,維持的是女王的太平。出了城牆,誰離得近誰說了算。", "Ở Sarovan, hòa bình của Nữ hoàng được giữ gìn. Ra ngoài tường thành thì ai đứng gần nhất người đó giữ.", "Di Sarovan, kedamaian Ratu terjaga. Di luar tembok, yang menjaganya siapa saja yang paling dekat.", "ในสโรวันรักษาความสงบของราชินีไว้ได้ นอกกำแพงเมือง ใครอยู่ใกล้สุดก็คนนั้นรักษาเอา", "Sarovan'da Kraliçe'nin huzuru korunur. Surların dışında ise en yakında kim varsa o korur.", "En Sarovan se guarda la paz de la Reina. Fuera de las murallas la guarda quien esté más cerca.", "Em Sarovan, quem mantém a paz é a Rainha. Fora das muralhas, quem estiver mais perto.", "В Сароване хранят мир Королевы. За стенами его хранит тот, кто ближе.", "У Саровані бережуть мир Королеви. За стінами його береже той, хто найближче."],
  "The Queen will find the money. She always finds the money. The question is whose.": ["女王は金を見つけるさ。いつだって見つける。問題は、誰の金かだ。", "여왕은 돈을 찾아낼 거야. 언제나 찾아내시지. 문제는 누구 돈이냐는 거고.", "女王会找到钱的。她总能找到钱。问题是,谁的钱。", "女王會找到錢的。她總能找到錢。問題是,誰的錢。", "Nữ hoàng sẽ tìm ra tiền. Bà luôn tìm ra tiền. Câu hỏi là tiền của ai.", "Ratu akan menemukan uangnya. Beliau selalu menemukan uangnya. Pertanyaannya, uang siapa.", "ราชินีจะหาเงินมาได้ พระนางหาเงินมาได้เสมอ คำถามคือเงินของใคร", "Kraliçe parayı bulur. Parayı hep bulur. Asıl soru, kimin parası.", "La Reina encontrará el dinero. Siempre lo encuentra. La cuestión es de quién.", "A Rainha vai achar o dinheiro. Ela sempre acha. A questão é de quem.", "Королева найдёт деньги. Она всегда их находит. Вопрос — чьи.", "Королева знайде гроші. Вона завжди їх знаходить. Питання — чиї."],
  "My grandmother swam in the Great Tank at its deepest. I can stand in it now.": ["祖母は大貯水池の一番深いところで泳いだものさ。今じゃ私が立てるよ。", "우리 할머니는 대저수지 가장 깊은 곳에서 헤엄치셨지. 지금은 내가 서 있을 수 있어.", "我奶奶当年在大水池最深处游过泳。如今我能站在里面。", "我奶奶當年在大水池最深處游過泳。如今我能站在裡面。", "Bà tôi từng bơi ở chỗ sâu nhất của Hồ Lớn. Giờ thì tôi đứng được trong đó.", "Nenekku dulu berenang di Telaga Agung di bagian terdalamnya. Sekarang aku bisa berdiri di sana.", "ยายข้าเคยว่ายน้ำในสระใหญ่ตรงที่ลึกที่สุด ตอนนี้ข้ายืนในนั้นได้แล้ว", "Ninem Büyük Havuz'un en derin yerinde yüzerdi. Ben şimdi içinde ayakta durabiliyorum.", "Mi abuela nadaba en el Gran Estanque por la parte más honda. Ahora yo hago pie.", "Minha avó nadava no Grande Tanque na parte mais funda. Hoje eu fico de pé lá dentro.", "Моя бабушка плавала в Великом пруду на самой глубине. А я теперь могу в нём стоять.", "Моя бабуся плавала у Великому ставі на найбільшій глибині. А я тепер можу в ньому стояти."],
  "Have you tried the mangoes? Of course you haven't, you're still dry. Here: no, they're mine. Buy your own.": ["マンゴーは食べたかい?もちろんまだだね、まだ乾いてるもの。ほら、いや、これは私のだ。自分で買いな。", "망고 먹어 봤어? 당연히 안 먹어 봤겠지, 아직 안 젖었잖아. 자, 아니, 이건 내 거야. 네 건 네가 사.", "尝过芒果了吗?当然没有,你身上还是干的。来——不,这是我的。自己买去。", "嚐過芒果了嗎?當然沒有,你身上還是乾的。來——不,這是我的。自己買去。", "Bạn ăn xoài chưa? Tất nhiên là chưa, người bạn còn khô ráo thế kia. Đây: à không, của tôi. Tự mua đi.", "Sudah coba mangganya? Tentu belum, kau masih kering. Nih: eh, jangan, ini punyaku. Beli sendiri.", "ลองมะม่วงหรือยัง แน่นอนว่ายัง ตัวเจ้ายังแห้งอยู่เลย เอ้านี่ ไม่สิ ของข้า ไปซื้อเอาเอง", "Mangoları denedin mi? Tabii ki denemedin, hâlâ kurusun. Al: yok, bunlar benim. Kendininkini al.", "¿Has probado los mangos? Claro que no, aún estás seco. Toma: no, que son míos. Cómprate los tuyos.", "Já provou as mangas? Claro que não, você ainda está seco. Toma: não, essas são minhas. Compre as suas.", "Манго пробовал? Конечно нет, ты же ещё сухой. Вот: нет, это мои. Купи себе свои.", "Манго куштував? Звісно ні, ти ж іще сухий. Ось: ні, це мої. Купи собі свої."],
  "The passes are mine and the mines are mine. I didn't take them from anyone; I just stayed when everyone else went down to the warm.": ["峠は私のもの、鉱山も私のものだ。誰から奪ったわけでもない。皆が暖かい下界へ降りていったとき、私だけが残った、それだけだ。", "고갯길도 내 것이고 광산도 내 것이다. 누구에게서 빼앗은 게 아니야. 다들 따뜻한 아래로 내려갈 때 나는 그냥 남았을 뿐이지.", "山口是我的,矿山也是我的。我没从任何人手里夺过来;只是别人都下山去暖和地方时,我留了下来。", "山口是我的,礦山也是我的。我沒從任何人手裡奪過來;只是別人都下山去暖和地方時,我留了下來。", "Các đèo là của ta, các mỏ là của ta. Ta chẳng cướp của ai; ta chỉ ở lại khi mọi người khác xuống vùng ấm áp.", "Celah gunung milikku dan tambang pun milikku. Aku tidak merebutnya dari siapa pun; aku hanya bertahan saat semua orang lain turun ke tempat yang hangat.", "ช่องเขาเป็นของข้า เหมืองก็เป็นของข้า ข้าไม่ได้แย่งมาจากใคร ข้าแค่อยู่ต่อตอนที่คนอื่นๆ ลงไปหาที่อุ่น", "Geçitler benim, madenler de benim. Kimseden almadım; herkes sıcağa inerken ben kaldım, o kadar.", "Los pasos son míos y las minas son mías. No se los quité a nadie; solo me quedé cuando todos los demás bajaron al calor.", "Os desfiladeiros são meus e as minas são minhas. Não tirei de ninguém; só fiquei quando todos os outros desceram para o calor.", "Перевалы мои, и рудники мои. Я ни у кого их не отнимал; я просто остался, когда все остальные ушли вниз, в тепло.", "Перевали мої, і копальні мої. Я ні в кого їх не відбирав; я просто лишився, коли всі інші пішли вниз, у тепло."],
  "Ilavarta calls my Copper Banner companies foreign interference. Ilavarta has never paid a highland soldier through a winter.": ["イラヴァルタは私の銅の旗の傭兵団を外国の干渉と呼ぶ。イラヴァルタは高地の兵に冬を越すまで給金を払ったことなど一度もない。", "일라바르타는 내 구리 깃발 용병대를 외세의 간섭이라 부르지. 일라바르타는 고원 병사에게 겨울 내내 급료를 줘 본 적이 한 번도 없다.", "伊拉瓦塔说我的铜旗佣兵团是外国干涉。伊拉瓦塔可从没给高地士兵发过一整个冬天的军饷。", "伊拉瓦塔說我的銅旗傭兵團是外國干涉。伊拉瓦塔可從沒給高地士兵發過一整個冬天的軍餉。", "Ilavarta gọi các đại đội Cờ Đồng của ta là sự can thiệp ngoại bang. Ilavarta chưa bao giờ trả lương cho một người lính cao nguyên suốt một mùa đông.", "Ilavarta menyebut kompi-kompi Panji Tembaga-ku campur tangan asing. Ilavarta tak pernah menggaji prajurit dataran tinggi sepanjang musim dingin.", "อิลาวรรตะเรียกกองทหารธงทองแดงของข้าว่าการแทรกแซงจากต่างชาติ อิลาวรรตะไม่เคยจ่ายเงินให้ทหารที่ราบสูงตลอดหน้าหนาวเลยสักครั้ง", "Ilavarta, Bakır Sancak bölüklerime yabancı müdahale diyor. Ilavarta bir dağlı askere bir kış boyunca hiç maaş ödememiştir.", "Ilavarta llama injerencia extranjera a mis compañías del Estandarte de Cobre. Ilavarta nunca le ha pagado a un soldado de las tierras altas durante un invierno entero.", "Ilavarta chama minhas companhias do Estandarte de Cobre de interferência estrangeira. Ilavarta nunca pagou um soldado das terras altas durante um inverno inteiro.", "Илаварта называет мои отряды Медного знамени иностранным вмешательством. Илаварта ни разу не платила горному солдату всю зиму.", "Ілаварта називає мої загони Мідного стягу іноземним втручанням. Ілаварта жодного разу не платила гірському солдатові всю зиму."],
  "Tamesh's masons and my assayers share what they know of the furnace. Stone and iron should talk. Kings rarely do.": ["タメシュの石工と私の試金師は、炉について知ることを分かち合っている。石と鉄は語り合うべきだ。王たちはめったにしないがな。", "타메시의 석공들과 내 시금사들은 용광로에 관해 아는 걸 서로 나누지. 돌과 쇠는 대화해야 해. 왕들은 좀처럼 그러지 않지만.", "塔梅什的石匠和我的验矿师互通熔炉的学问。石与铁就该多交流。国王们却很少这样。", "塔梅什的石匠和我的驗礦師互通熔爐的學問。石與鐵就該多交流。國王們卻很少這樣。", "Thợ đá của Tamesh và thợ thử kim của ta chia sẻ những gì họ biết về lò luyện. Đá và sắt nên trò chuyện. Vua chúa thì hiếm khi.", "Tukang batu Tamesh dan penguji logamku berbagi pengetahuan soal tungku. Batu dan besi sebaiknya saling bicara. Para raja jarang melakukannya.", "ช่างหินของทาเมชกับช่างทดสอบแร่ของข้าแบ่งปันความรู้เรื่องเตาหลอมกัน หินกับเหล็กควรคุยกัน พวกกษัตริย์น่ะไม่ค่อยคุยกันหรอก", "Tamesh'in taş ustaları ile benim ayarcılarım fırın hakkında bildiklerini paylaşıyor. Taş ile demir konuşmalı. Krallar pek konuşmaz.", "Los canteros de Tamesh y mis ensayadores comparten lo que saben del horno. La piedra y el hierro deberían hablar. Los reyes rara vez lo hacen.", "Os pedreiros de Tamesh e meus ensaiadores compartilham o que sabem da fornalha. Pedra e ferro deveriam conversar. Reis raramente conversam.", "Каменщики Тамеша и мои пробирщики делятся тем, что знают о печи. Камню и железу стоит говорить друг с другом. Короли делают это редко.", "Мулярі Тамеша і мої пробірники діляться тим, що знають про піч. Каменю й залізу варто розмовляти. Королі роблять це рідко."],
  "The Marshal sells our swords by the season and Lord Varanjit buys them. It's honest work, if you don't ask the Queen.": ["元帥は我らの剣を季節ごとに売り、ヴァランジット卿がそれを買う。真っ当な仕事さ、女王に訊かなければな。", "원수께서 우리 칼을 철마다 팔고, 바란지트 경이 그걸 사지. 정직한 일이야, 여왕한테 묻지만 않는다면.", "元帅按季节出卖我们的剑,瓦兰吉特大人买下。这是正经活儿,只要你别去问女王。", "元帥按季節出賣我們的劍,瓦蘭吉特大人買下。這是正經活兒,只要你別去問女王。", "Thống chế bán thanh kiếm của chúng tôi theo mùa và Lãnh chúa Varanjit mua. Đó là việc lương thiện, nếu bạn không hỏi Nữ hoàng.", "Marsekal menjual pedang kami per musim dan Tuan Varanjit membelinya. Pekerjaan jujur, asal jangan tanya Ratu.", "จอมพลขายดาบของพวกเราเป็นฤดู และท่านวรัญชิตก็ซื้อไว้ เป็นงานสุจริตนะ ถ้าไม่ไปถามราชินี", "Mareşal kılıçlarımızı mevsimlik satar, Lord Varanjit de satın alır. Dürüst bir iş, Kraliçe'ye sormazsan.", "El Mariscal vende nuestras espadas por temporadas y el señor Varanjit las compra. Es un trabajo honrado, si no le preguntas a la Reina.", "O Marechal vende nossas espadas por temporada e o senhor Varanjit as compra. É trabalho honesto, se você não perguntar à Rainha.", "Маршал продаёт наши мечи посезонно, а лорд Варанджит их покупает. Честная работа, если не спрашивать Королеву.", "Маршал продає наші мечі посезонно, а лорд Варанджит їх купує. Чесна робота, якщо не питати Королеву."],
  "Two of my riders went over the pass and didn't come back. Deserters, the Lord says. Unpaid, I say. Same thing, in the end.": ["うちの騎手が二人、峠を越えて戻らなかった。脱走兵だと卿は言う。給金未払いだと私は言う。結局、同じことだがね。", "내 기병 둘이 고개를 넘어가서 돌아오지 않았어. 탈영병이라고 경께서는 말씀하시지. 나는 급료를 못 받은 거라 하고. 결국엔 같은 얘기야.", "我手下两名骑手翻过山口,再没回来。大人说是逃兵。我说是欠饷。说到底,一回事。", "我手下兩名騎手翻過山口,再沒回來。大人說是逃兵。我說是欠餉。說到底,一回事。", "Hai kỵ binh của tôi vượt đèo rồi không trở về. Lãnh chúa bảo là đào ngũ. Tôi bảo là bị nợ lương. Rốt cuộc cũng như nhau.", "Dua penunggang kudaku melewati celah gunung dan tak kembali. Desertir, kata Tuan. Tak digaji, kataku. Ujung-ujungnya sama saja.", "ทหารม้าของข้าสองคนข้ามช่องเขาไปแล้วไม่กลับมา ท่านวรัญชิตว่าหนีทัพ ข้าว่าไม่ได้รับค่าจ้าง สุดท้ายก็เรื่องเดียวกันนั่นแหละ", "Atlılarımdan ikisi geçidi aştı ve geri dönmedi. Firari, diyor Lord. Maaşsız, diyorum ben. Sonunda aynı kapıya çıkar.", "Dos de mis jinetes cruzaron el paso y no volvieron. Desertores, dice el señor. Sin paga, digo yo. Al final es lo mismo.", "Dois dos meus cavaleiros atravessaram o desfiladeiro e não voltaram. Desertores, diz o senhor. Sem soldo, digo eu. No fim, dá no mesmo.", "Двое моих всадников ушли за перевал и не вернулись. Дезертиры, говорит лорд. Неоплаченные, говорю я. В конце концов, одно и то же.", "Двоє моїх вершників пішли за перевал і не повернулися. Дезертири, каже лорд. Неоплачені, кажу я. Зрештою, те саме."],
  "Blackiron from the north seam, moonsilver from the east. I test every ingot, and Tamesh tests my tests.": ["北の鉱脈からはブラックアイアン、東からはムーンシルバー。私はすべての地金を試し、タメシュは私の試験を試す。", "북쪽 광맥에선 흑철, 동쪽에선 월은. 나는 주괴를 하나하나 시험하고, 타메시는 내 시험을 시험하지.", "北矿脉出黑铁,东矿脉出月银。每块锭子我都检验,塔梅什再检验我的检验。", "北礦脈出黑鐵,東礦脈出月銀。每塊錠子我都檢驗,塔梅什再檢驗我的檢驗。", "Sắt đen từ mạch phía bắc, bạc trăng từ phía đông. Tôi thử từng thỏi, còn Tamesh thử lại những lần thử của tôi.", "Besi hitam dari urat utara, perak bulan dari timur. Aku menguji setiap batangan, dan Tamesh menguji ujianku.", "เหล็กดำจากสายแร่ทางเหนือ เงินจันทร์จากทางตะวันออก ข้าทดสอบทุกแท่ง แล้วทาเมชก็ทดสอบการทดสอบของข้าอีกที", "Kuzey damarından kara demir, doğudan ay gümüşü. Her külçeyi ben test ederim, Tamesh de benim testlerimi.", "Hierro negro de la veta norte, plata lunar de la del este. Yo ensayo cada lingote, y Tamesh ensaya mis ensayos.", "Ferro negro do veio norte, prata lunar do leste. Eu ensaio cada lingote, e Tamesh ensaia meus ensaios.", "Чёрное железо — из северной жилы, лунное серебро — из восточной. Я проверяю каждый слиток, а Тамеш проверяет мои проверки.", "Чорне залізо — з північної жили, місячне срібло — зі східної. Я перевіряю кожен злиток, а Тамеш перевіряє мої перевірки."],
  "The Obsidian Legacy writes to me about furnace draughts. I write back about their quarries. We've never met, and we're the best of friends.": ["黒曜の遺統は炉の通風について手紙をよこす。私は彼らの石切り場について返事を書く。会ったこともないが、無二の親友だ。", "흑요 유산은 용광로 통풍에 관해 내게 편지를 보내지. 나는 그들의 채석장에 관해 답장을 쓰고. 만난 적은 없지만, 둘도 없는 친구야.", "黑曜遗脉写信跟我谈熔炉的通风。我回信谈他们的采石场。我们从未谋面,却是最好的朋友。", "黑曜遺脈寫信跟我談熔爐的通風。我回信談他們的採石場。我們從未謀面,卻是最好的朋友。", "Di Sản Hắc Diện viết thư cho tôi về luồng gió lò luyện. Tôi viết lại về các mỏ đá của họ. Chúng tôi chưa từng gặp nhau, và là bạn thân nhất.", "Warisan Obsidian menyuratiku soal tarikan udara tungku. Aku membalas soal tambang batu mereka. Kami belum pernah bertemu, dan kami sahabat karib.", "มรดกออบซิเดียนเขียนจดหมายมาถามเรื่องลมในเตาหลอม ข้าเขียนตอบเรื่องเหมืองหินของพวกเขา เราไม่เคยพบกันเลย แต่เป็นเพื่อนรักกันที่สุด", "Obsidyen Mirası bana fırın çekişi hakkında yazar. Ben de onların taş ocakları hakkında karşılık yazarım. Hiç tanışmadık ve en iyi dostuz.", "El Legado de Obsidiana me escribe sobre el tiro de los hornos. Yo le respondo sobre sus canteras. Nunca nos hemos visto, y somos íntimos amigos.", "O Legado de Obsidiana me escreve sobre a tiragem das fornalhas. Eu respondo sobre as pedreiras deles. Nunca nos vimos, e somos grandes amigos.", "Обсидиановое наследие пишет мне о тяге в печах. Я отвечаю им про их каменоломни. Мы ни разу не встречались — и мы лучшие друзья.", "Обсидіанова спадщина пише мені про тягу в печах. Я відповідаю про їхні каменоломні. Ми ніколи не зустрічалися — і ми найкращі друзі."],
  "Rope, pitons, lamp oil, blankets. You'll want all four before the pass, and you'll only remember three.": ["縄、ハーケン、ランプの油、毛布。峠の前には四つとも要るが、覚えてるのは三つだけだろうよ。", "밧줄, 하켄, 등잔 기름, 담요. 고개 넘기 전에 넷 다 필요할 텐데, 기억나는 건 셋뿐일 거야.", "绳子、岩钉、灯油、毯子。过山口前四样你都需要,可你只会记得三样。", "繩子、岩釘、燈油、毯子。過山口前四樣你都需要,可你只會記得三樣。", "Dây thừng, đinh leo núi, dầu đèn, chăn. Trước khi qua đèo bạn sẽ cần cả bốn, và bạn sẽ chỉ nhớ được ba.", "Tali, piton, minyak lampu, selimut. Kau butuh keempatnya sebelum melewati celah gunung, dan kau cuma akan ingat tiga.", "เชือก หมุดปีนเขา น้ำมันตะเกียง ผ้าห่ม ก่อนข้ามช่องเขาเจ้าต้องใช้ทั้งสี่อย่าง แต่เจ้าจะจำได้แค่สาม", "İp, kaya çivisi, lamba yağı, battaniye. Geçitten önce dördü de lazım olacak, ama yalnızca üçünü hatırlayacaksın.", "Cuerda, clavijas, aceite de lámpara, mantas. Querrás las cuatro cosas antes del paso, y solo te acordarás de tres.", "Corda, pitons, óleo de lamparina, cobertores. Você vai precisar dos quatro antes do desfiladeiro, e só vai lembrar de três.", "Верёвка, крючья, масло для лампы, одеяла. Перед перевалом понадобятся все четыре, а вспомнишь ты только три.", "Мотузка, гаки, олія для лампи, ковдри. Перед перевалом знадобляться всі чотири, а згадаєш ти лише три."],
  "Highland wool. It itches, it smells of sheep, and it keeps you alive. Pick two.": ["高地の羊毛だ。チクチクして、羊臭くて、命を守ってくれる。二つ選びな。", "고원 양모야. 따갑고, 양 냄새 나고, 목숨을 지켜 주지. 둘만 골라.", "高地羊毛。扎人,一股羊膻味,还能保你活命。三选二吧。", "高地羊毛。扎人,一股羊羶味,還能保你活命。三選二吧。", "Len cao nguyên. Ngứa, hôi mùi cừu, và giữ cho bạn sống. Chọn hai.", "Wol dataran tinggi. Gatal, bau domba, dan membuatmu tetap hidup. Pilih dua.", "ขนแกะที่ราบสูง ทั้งคัน ทั้งเหม็นสาบแกะ และช่วยให้เจ้ารอดชีวิต เลือกมาสองอย่าง", "Yayla yünü. Kaşındırır, koyun kokar ve seni hayatta tutar. İkisini seç.", "Lana de las tierras altas. Pica, huele a oveja y te mantiene con vida. Elige dos.", "Lã das terras altas. Pinica, tem cheiro de ovelha e te mantém vivo. Escolha dois.", "Горная шерсть. Колется, пахнет овцой и не даёт тебе умереть. Выбери два.", "Гірська вовна. Колеться, пахне вівцею і не дає тобі померти. Обери два."],
  "Forty years this fire's been lit. Sit by it. Everybody does, in the end.": ["この火は四十年燃え続けてる。そばに座りな。結局はみんなそうする。", "이 불은 사십 년째 타고 있어. 곁에 앉아. 결국엔 다들 그러니까.", "这火已经烧了四十年。坐过来吧。到头来,谁都会坐过来。", "這火已經燒了四十年。坐過來吧。到頭來,誰都會坐過來。", "Ngọn lửa này đã cháy bốn mươi năm. Ngồi xuống bên nó đi. Rốt cuộc ai cũng thế.", "Empat puluh tahun api ini menyala. Duduklah di dekatnya. Pada akhirnya semua orang begitu.", "ไฟกองนี้จุดมาสี่สิบปีแล้ว นั่งข้างๆ สิ สุดท้ายใครๆ ก็มานั่งกันทั้งนั้น", "Bu ateş kırk yıldır yanıyor. Yanına otur. Sonunda herkes oturur.", "Cuarenta años lleva encendido este fuego. Siéntate junto a él. Al final, todo el mundo lo hace.", "Faz quarenta anos que este fogo está aceso. Sente-se perto dele. No fim, todo mundo senta.", "Сорок лет горит этот огонь. Садись рядом. Рано или поздно все садятся.", "Сорок років горить цей вогонь. Сідай поруч. Рано чи пізно всі сідають."],
  "Miners, soldiers, smugglers, a princess once. The fire doesn't ask, and neither do I.": ["鉱夫、兵士、密輸人、一度はお姫さまも。火は何も訊かないし、私も訊かない。", "광부, 병사, 밀수꾼, 한번은 공주도. 불은 묻지 않고, 나도 묻지 않아.", "矿工、士兵、走私贩,还来过一位公主。火不问来历,我也不问。", "礦工、士兵、走私販,還來過一位公主。火不問來歷,我也不問。", "Thợ mỏ, binh lính, kẻ buôn lậu, có lần cả một nàng công chúa. Ngọn lửa không hỏi, tôi cũng vậy.", "Penambang, prajurit, penyelundup, sekali seorang putri. Api tidak bertanya, aku juga tidak.", "คนงานเหมือง ทหาร พวกลักลอบขนของ เคยมีเจ้าหญิงมาครั้งหนึ่งด้วย ไฟไม่ถามอะไร ข้าก็ไม่ถาม", "Madenciler, askerler, kaçakçılar, bir keresinde de bir prenses. Ateş sormaz, ben de sormam.", "Mineros, soldados, contrabandistas, una princesa una vez. El fuego no pregunta, y yo tampoco.", "Mineiros, soldados, contrabandistas, uma princesa certa vez. O fogo não pergunta, e eu também não.", "Шахтёры, солдаты, контрабандисты, однажды принцесса. Огонь не спрашивает, и я тоже.", "Шахтарі, солдати, контрабандисти, якось — принцеса. Вогонь не питає, і я теж."],
  "Shaila mail: ten thousand rings, every one riveted. I sign them inside the collar, so you know who to blame.": ["シャイラの鎖帷子。一万の輪、そのひとつひとつにリベット留め。襟の内側に署名してあるから、誰を責めればいいか分かるだろう。", "샤일라 사슬갑옷. 고리 만 개, 하나하나 리벳으로 박았지. 깃 안쪽에 내 서명을 넣으니, 누굴 탓해야 할지 알 거야.", "沙伊拉锁子甲:一万个环,每个都铆过。我在领子内侧签名,这样你就知道该怪谁。", "沙伊拉鎖子甲:一萬個環,每個都鉚過。我在領子內側簽名,這樣你就知道該怪誰。", "Giáp xích Shaila: mười nghìn vòng, vòng nào cũng tán đinh. Tôi ký tên bên trong cổ áo, để bạn biết phải trách ai.", "Zirah rantai Shaila: sepuluh ribu cincin, semuanya dikeling. Kutandatangani di bagian dalam kerah, supaya kau tahu siapa yang harus disalahkan.", "เกราะโซ่ไศลา ห่วงหนึ่งหมื่นวง ย้ำหมุดทุกวง ข้าเซ็นชื่อไว้ด้านในคอเสื้อ เจ้าจะได้รู้ว่าต้องโทษใคร", "Shaila zincir zırhı: on bin halka, her biri perçinli. Yakanın içine imzamı atarım, kimi suçlayacağını bil diye.", "Cota de malla de Shaila: diez mil anillas, todas remachadas. Las firmo por dentro del cuello, para que sepas a quién echarle la culpa.", "Cota de malha de Shaila: dez mil anéis, todos rebitados. Eu assino por dentro da gola, para você saber quem culpar.", "Шайлийская кольчуга: десять тысяч колец, каждое на заклёпке. Я подписываю их изнутри ворота, чтобы ты знал, кого винить.", "Шайлійська кольчуга: десять тисяч кілець, кожне на заклепці. Я підписую їх усередині коміра, щоб ти знав, кого винуватити."],
  "Three passes, one fortress. The fortress wins.": ["三つの峠に、砦がひとつ。勝つのは砦だ。", "고개 셋, 요새 하나. 요새가 이긴다.", "三道山口,一座要塞。要塞赢。", "三道山口,一座要塞。要塞贏。", "Ba con đèo, một pháo đài. Pháo đài thắng.", "Tiga celah, satu benteng. Bentengnya menang.", "สามช่องเขา หนึ่งป้อมปราการ ป้อมชนะ", "Üç geçit, bir kale. Kale kazanır.", "Tres pasos, una fortaleza. Gana la fortaleza.", "Três desfiladeiros, uma fortaleza. A fortaleza vence.", "Три перевала, одна крепость. Побеждает крепость.", "Три перевали, одна фортеця. Перемагає фортеця."],
  "The hired companies drink at the Pass Fire. We drink somewhere else.": ["雇われ部隊の連中は峠火亭で飲む。俺たちは別の場所で飲む。", "용병대 놈들은 고갯불 주점에서 마시지. 우리는 다른 데서 마셔.", "雇佣兵团在山口之火酒馆喝酒。我们去别处喝。", "傭兵團在山口之火酒館喝酒。我們去別處喝。", "Bọn lính đánh thuê uống ở quán Lửa Đèo. Chúng tôi uống chỗ khác.", "Kompi-kompi bayaran minum di Api Celah. Kami minum di tempat lain.", "พวกกองทหารรับจ้างดื่มกันที่ร้านไฟช่องเขา พวกเราไปดื่มที่อื่น", "Paralı bölükler Geçit Ateşi'nde içer. Biz başka yerde içeriz.", "Las compañías a sueldo beben en el Fuego del Paso. Nosotros bebemos en otra parte.", "As companhias contratadas bebem no Fogo do Desfiladeiro. Nós bebemos em outro lugar.", "Наёмные отряды пьют в «Огне перевала». Мы пьём в другом месте.", "Найманські загони п'ють у «Вогні перевалу». Ми п'ємо деінде."],
  "The north seam's blackiron, the east seam's moonsilver, and the deep seam glimmers. Pay the tithe and dig where you like.": ["北の鉱脈はブラックアイアン、東の鉱脈はムーンシルバー、深い鉱脈にはグリマーがきらめく。十分の一税を払えば、好きなところを掘りな。", "북쪽 광맥은 흑철, 동쪽 광맥은 월은, 깊은 광맥엔 글리머가 반짝이지. 십일조만 내면 어디든 원하는 데를 파.", "北矿脉是黑铁,东矿脉是月银,深矿脉闪着微光。交了什一税,爱挖哪儿挖哪儿。", "北礦脈是黑鐵,東礦脈是月銀,深礦脈閃著微光。交了什一稅,愛挖哪兒挖哪兒。", "Mạch phía bắc là sắt đen, mạch phía đông là bạc trăng, còn mạch sâu thì lấp lánh ánh kim. Nộp thuế thập phân rồi muốn đào đâu thì đào.", "Urat utara besi hitam, urat timur perak bulan, dan urat dalam berkilau kemilau. Bayar persepuluhan dan galilah di mana kau suka.", "สายแร่เหนือคือเหล็กดำ สายแร่ตะวันออกคือเงินจันทร์ ส่วนสายแร่ลึกนั้นเป็นประกายแสง จ่ายส่วยหนึ่งในสิบแล้วจะขุดตรงไหนก็ตามใจ", "Kuzey damarı kara demir, doğu damarı ay gümüşü, derin damar ise parıltı. Öşrü öde, nereyi istersen kaz.", "La veta norte es de hierro negro, la del este de plata lunar, y la honda destella. Paga el diezmo y cava donde quieras.", "O veio norte é ferro negro, o do leste é prata lunar, e o fundo lampeja. Pague o dízimo e cave onde quiser.", "В северной жиле — чёрное железо, в восточной — лунное серебро, а глубокая мерцает. Плати десятину и копай где хочешь.", "У північній жилі — чорне залізо, у східній — місячне срібло, а глибока мерехтить. Плати десятину й копай де хочеш."],
  "Bears in the scree, deserters in the passes, and the tithe-man at the door. A miner's life.": ["岩屑の斜面には熊、峠には脱走兵、戸口には十分の一税の取り立て人。鉱夫の暮らしってのはそんなもんだ。", "너덜지대엔 곰, 고갯길엔 탈영병, 문 앞엔 십일조 징수인. 광부의 삶이란.", "碎石坡上有熊,山口里有逃兵,门口还有收什一税的。矿工的日子就是这样。", "碎石坡上有熊,山口裡有逃兵,門口還有收什一稅的。礦工的日子就是這樣。", "Gấu trên sườn đá vụn, lính đào ngũ trên đèo, và người thu thuế thập phân trước cửa. Đời thợ mỏ là thế.", "Beruang di lereng kerikil, desertir di celah gunung, dan penagih persepuluhan di depan pintu. Begitulah hidup penambang.", "หมีอยู่ตามลาดหินร่วน คนหนีทัพอยู่ตามช่องเขา และคนเก็บส่วยอยู่หน้าประตู ชีวิตคนงานเหมืองก็งี้แหละ", "Taşlıkta ayılar, geçitlerde firariler, kapıda da öşürcü. Madenci hayatı.", "Osos en el pedregal, desertores en los pasos y el recaudador del diezmo en la puerta. La vida del minero.", "Ursos no cascalho, desertores nos desfiladeiros e o cobrador do dízimo à porta. Vida de mineiro.", "Медведи на осыпях, дезертиры на перевалах и сборщик десятины у двери. Жизнь шахтёра.", "Ведмеді на осипах, дезертири на перевалах і збирач десятини під дверима. Життя шахтаря."],
  "The loggers bring props down from the Deepgreen. The Kanthari don't like it. The mine doesn't care who likes it.": ["木こりたちは深緑の森から坑木を運び下ろす。カンタリはそれが気に入らない。鉱山は誰が気に入ろうが気にしない。", "벌목꾼들이 깊은초록 숲에서 갱목을 실어 오지. 칸타리족은 그걸 싫어해. 광산은 누가 좋아하든 상관 안 하고.", "伐木工从深绿林运来坑木。坎塔里人不乐意。矿山才不管谁乐不乐意。", "伐木工從深綠林運來坑木。坎塔里人不樂意。礦山才不管誰樂不樂意。", "Thợ đốn gỗ mang cột chống từ Rừng Thẳm Xanh xuống. Người Kanthari không thích thế. Mỏ thì chẳng quan tâm ai thích.", "Para penebang membawa tiang penyangga turun dari Rimba Hijau Pekat. Orang Kanthari tidak suka. Tambang tidak peduli siapa yang suka.", "พวกคนตัดไม้ขนไม้ค้ำยันลงมาจากป่าเขียวลึก ชาวกันถารีไม่ชอบ เหมืองไม่สนหรอกว่าใครชอบ", "Tomrukçular Derin Yeşillik'ten destek direkleri indirir. Kanthariler bundan hoşlanmaz. Maden kimin hoşlandığını umursamaz.", "Los leñadores bajan puntales del Verdor Profundo. A los kanthari no les gusta. A la mina no le importa a quién le guste.", "Os lenhadores trazem escoras do Verde Profundo. Os kanthari não gostam. A mina não liga para quem gosta.", "Лесорубы спускают крепёж из Глубокой Зелени. Кантхари это не нравится. А шахте всё равно, кому что нравится.", "Лісоруби спускають кріплення з Глибокої Зелені. Кантхарі це не подобається. А шахті байдуже, кому що подобається."],
  "Lord Varanjit's fair. Hard, but fair. Like the mountain.": ["ヴァランジット卿は公正なお方だ。厳しいが、公正だ。山のようにな。", "바란지트 경은 공정하셔. 엄하지만 공정하지. 산처럼.", "瓦兰吉特大人很公道。严厉,但公道。就像这座山。", "瓦蘭吉特大人很公道。嚴厲,但公道。就像這座山。", "Lãnh chúa Varanjit công bằng. Khắc nghiệt, nhưng công bằng. Như ngọn núi vậy.", "Tuan Varanjit adil. Keras, tapi adil. Seperti gunung.", "ท่านวรัญชิตยุติธรรม เข้มงวดแต่ยุติธรรม เหมือนภูเขา", "Lord Varanjit adildir. Serttir ama adildir. Dağ gibi.", "El señor Varanjit es justo. Duro, pero justo. Como la montaña.", "O senhor Varanjit é justo. Duro, mas justo. Como a montanha.", "Лорд Варанджит справедлив. Суров, но справедлив. Как гора.", "Лорд Варанджит справедливий. Суворий, але справедливий. Як гора."],
  "The valley folk say we're cold. We say they're damp.": ["谷の連中は俺たちを冷たいと言う。俺たちはあいつらをじめじめしてると言う。", "계곡 사람들은 우리가 차갑다고 하지. 우린 그들이 눅눅하다고 해.", "河谷的人说我们冷。我们说他们潮。", "河谷的人說我們冷。我們說他們潮。", "Dân thung lũng bảo chúng tôi lạnh lùng. Chúng tôi bảo họ ẩm ướt.", "Orang lembah bilang kami dingin. Kami bilang mereka lembap.", "คนในหุบเขาว่าพวกเราเย็นชา พวกเราว่าพวกเขาชื้นแฉะ", "Vadililer bizim soğuk olduğumuzu söyler. Biz de onların nemli olduğunu.", "Los del valle dicen que somos fríos. Nosotros decimos que ellos son húmedos.", "O povo do vale diz que somos frios. Nós dizemos que eles são úmidos.", "Долинные говорят, что мы холодные. Мы говорим, что они сырые.", "Долиняни кажуть, що ми холодні. Ми кажемо, що вони вогкі."],
  "The League is seven rulers who'd each rather be one. For a year I speak for all of them, and every one of them thinks I'm speaking for the others.": ["同盟とは、それぞれが自分ひとりで治めたがっている七人の君主のことだ。一年のあいだ私は全員を代弁し、全員が私は他の誰かを代弁していると思っている。", "동맹이란 저마다 혼자이고 싶어 하는 일곱 군주야. 일 년 동안 나는 그들 모두를 대변하고, 그들 하나하나는 내가 다른 이들을 대변한다고 생각하지.", "同盟就是七位统治者,每一位都宁愿只有自己一个。这一年我代表他们所有人发言,而他们每一位都认为我在替别人说话。", "同盟就是七位統治者,每一位都寧願只有自己一個。這一年我代表他們所有人發言,而他們每一位都認為我在替別人說話。", "Liên minh là bảy vị vua chúa mà ai cũng muốn chỉ có mình mình. Suốt một năm tôi phát ngôn cho tất cả, và ai trong số họ cũng nghĩ tôi đang nói thay cho những người kia.", "Liga adalah tujuh penguasa yang masing-masing lebih suka menjadi satu-satunya. Selama setahun aku berbicara atas nama mereka semua, dan setiap dari mereka mengira aku berbicara untuk yang lain.", "สันนิบาตคือผู้ปกครองเจ็ดคนที่ต่างก็อยากเป็นคนเดียว หนึ่งปีที่ข้าพูดแทนพวกเขาทั้งหมด และทุกคนต่างคิดว่าข้ากำลังพูดแทนคนอื่นๆ", "Birlik, her biri tek olmayı yeğleyecek yedi hükümdardır. Bir yıl boyunca hepsi adına konuşurum ve her biri benim ötekiler adına konuştuğumu sanır.", "La Liga son siete gobernantes que preferirían, cada uno, ser el único. Durante un año hablo por todos ellos, y cada uno cree que hablo por los demás.", "A Liga são sete governantes que prefeririam, cada um, ser o único. Por um ano eu falo por todos eles, e cada um acha que estou falando pelos outros.", "Лига — это семь правителей, каждый из которых предпочёл бы быть единственным. Год я говорю за всех, и каждый из них думает, что я говорю за остальных.", "Ліга — це семеро правителів, кожен з яких волів би бути єдиним. Рік я говорю за всіх, і кожен із них думає, що я говорю за інших."],
  "Ilavarta's bridge toll is a tax on the whole plain. We've told the Queen so, politely, seven times.": ["イラヴァルタの橋の通行料は平原全体への税だ。我々はそれを女王に丁重に、七度申し上げた。", "일라바르타의 다리 통행료는 평원 전체에 매기는 세금이야. 우리는 여왕께 그렇게, 정중하게, 일곱 번 말씀드렸지.", "伊拉瓦塔的过桥费是对整片平原征的税。我们已经客客气气地跟女王说过七次了。", "伊拉瓦塔的過橋費是對整片平原徵的稅。我們已經客客氣氣地跟女王說過七次了。", "Phí cầu của Ilavarta là thuế đánh lên cả đồng bằng. Chúng tôi đã nói với Nữ hoàng như vậy, một cách lịch sự, bảy lần rồi.", "Tol jembatan Ilavarta itu pajak atas seluruh dataran. Kami sudah mengatakannya kepada Ratu, dengan sopan, tujuh kali.", "ค่าผ่านสะพานของอิลาวรรตะคือภาษีที่เก็บจากทั้งที่ราบ เราทูลราชินีไปแล้วอย่างสุภาพ เจ็ดครั้ง", "Ilavarta'nın köprü geçiş ücreti bütün ovaya konmuş bir vergidir. Bunu Kraliçe'ye kibarca yedi kez söyledik.", "El peaje del puente de Ilavarta es un impuesto sobre toda la llanura. Se lo hemos dicho a la Reina, con educación, siete veces.", "O pedágio da ponte de Ilavarta é um imposto sobre a planície inteira. Já dissemos isso à Rainha, educadamente, sete vezes.", "Мостовая пошлина Илаварты — налог на всю равнину. Мы говорили это Королеве, вежливо, семь раз.", "Мостове мито Ілаварти — податок на всю рівнину. Ми казали це Королеві, ввічливо, сім разів."],
  "No parasol stands higher than another's. That's the whole of our law, and it's harder to keep than it sounds.": ["どの日傘も他の日傘より高く立つことはない。それが我らの法のすべてで、聞こえるより守るのは難しい。", "어떤 일산도 다른 일산보다 높이 서지 않는다. 그게 우리 법의 전부이고, 들리는 것보다 지키기가 어렵지.", "没有哪顶华盖比别人的立得更高。这就是我们法律的全部,而且做起来比听起来难。", "沒有哪頂華蓋比別人的立得更高。這就是我們法律的全部,而且做起來比聽起來難。", "Không chiếc lọng nào được dựng cao hơn lọng của người khác. Đó là toàn bộ luật của chúng tôi, và giữ nó khó hơn nghe nhiều.", "Tak ada payung yang berdiri lebih tinggi daripada payung yang lain. Itulah seluruh hukum kami, dan menjaganya lebih sulit daripada kedengarannya.", "ไม่มีฉัตรของใครตั้งสูงกว่าฉัตรของผู้อื่น นั่นคือกฎหมายทั้งหมดของเรา และรักษาไว้ยากกว่าที่ฟังดู", "Hiçbir şemsiye bir diğerininkinden yüksekte durmaz. Bütün kanunumuz bu ve uygulaması kulağa geldiğinden zordur.", "Ningún parasol se alza más alto que el de otro. Esa es toda nuestra ley, y es más difícil de cumplir de lo que parece.", "Nenhum para-sol fica mais alto que o de outro. Essa é toda a nossa lei, e é mais difícil de cumprir do que parece.", "Ничей зонт не стоит выше другого. Вот и весь наш закон, и соблюдать его труднее, чем кажется.", "Жодна парасоль не стоїть вище за іншу. Ось і весь наш закон, і дотримуватися його важче, ніж здається."],
  "The Salt Fens are the smallest of the seven. We have one vote, a white parasol, and a great deal of salt. Two of those are useful.": ["塩沼は七つのうちで一番小さい。我らにあるのは一票と、白い日傘と、山ほどの塩。そのうち役に立つのは二つだ。", "소금 늪은 일곱 중에 가장 작아. 우리에겐 한 표, 하얀 일산, 그리고 엄청난 양의 소금이 있지. 그중 쓸모 있는 건 둘이고.", "盐沼是七国中最小的。我们有一票、一顶白华盖,还有一大堆盐。其中两样有用。", "鹽沼是七國中最小的。我們有一票、一頂白華蓋,還有一大堆鹽。其中兩樣有用。", "Đầm Muối nhỏ nhất trong bảy nước. Chúng ta có một phiếu, một chiếc lọng trắng, và rất nhiều muối. Hai trong số đó là có ích.", "Rawa Garam yang terkecil di antara ketujuhnya. Kami punya satu suara, sebuah payung putih, dan banyak sekali garam. Dua di antaranya berguna.", "บึงเกลือเล็กที่สุดในเจ็ดแคว้น เรามีหนึ่งเสียง ฉัตรขาวหนึ่งคัน และเกลืออีกมหาศาล มีประโยชน์อยู่สองอย่าง", "Tuz Bataklıkları yedisinin en küçüğüdür. Bir oyumuz, beyaz bir şemsiyemiz ve bolca tuzumuz var. Bunlardan ikisi işe yarar.", "Las Ciénagas de Sal son las más pequeñas de las siete. Tenemos un voto, un parasol blanco y muchísima sal. Dos de esas cosas son útiles.", "Os Pântanos de Sal são os menores dos sete. Temos um voto, um para-sol branco e muito sal. Dois desses são úteis.", "Соляные Топи — самые маленькие из семи. У нас один голос, белый зонт и очень много соли. Две из этих вещей полезны.", "Соляні Болота — найменші із семи. У нас один голос, біла парасоль і дуже багато солі. Дві з цих речей корисні."],
  "The Speaker is a fine woman. She'll be a finer one in a year, when it's somebody else's turn.": ["議長は立派な女性だ。一年後、別の誰かの番になったら、もっと立派になるだろう。", "의장은 훌륭한 여인이야. 일 년 뒤 다른 사람 차례가 되면 더 훌륭해지겠지.", "议长是位好女人。一年后轮到别人当时,她会更好。", "議長是位好女人。一年後輪到別人當時,她會更好。", "Phát ngôn nhân là một người phụ nữ tốt. Một năm nữa, khi đến lượt người khác, bà ấy sẽ còn tốt hơn.", "Juru Bicara itu wanita yang baik. Ia akan jadi lebih baik lagi setahun lagi, saat giliran orang lain.", "ท่านประธานเป็นสตรีที่ดี อีกปีหนึ่งเมื่อถึงคราวคนอื่น นางจะยิ่งดีขึ้นไปอีก", "Sözcü iyi bir kadındır. Bir yıl sonra, sıra başkasına geçtiğinde daha da iyi olacak.", "La Portavoz es una gran mujer. Será aún mejor dentro de un año, cuando le toque a otro.", "A Porta-voz é uma ótima mulher. Será ainda melhor daqui a um ano, quando for a vez de outro.", "Глашатай — прекрасная женщина. Через год, когда настанет чья-то другая очередь, она станет ещё прекраснее.", "Речниця — чудова жінка. Через рік, коли настане чиясь інша черга, вона стане ще чудовішою."],
  "Seven rulers, seven rates, one toll. I add them up, divide them seven ways, and everybody says I've cheated them.": ["七人の君主、七つの税率、通行料はひとつ。足して、七つに分けると、みんな私にだまされたと言う。", "일곱 군주, 일곱 세율, 통행료는 하나. 다 더해서 일곱으로 나누면, 다들 내가 자기를 속였다고 해.", "七位统治者,七种税率,一笔过路费。我加起来,分成七份,结果人人都说我骗了他们。", "七位統治者,七種稅率,一筆過路費。我加起來,分成七份,結果人人都說我騙了他們。", "Bảy vị vua chúa, bảy mức phí, một khoản thu. Tôi cộng lại, chia bảy phần, và ai cũng bảo tôi lừa họ.", "Tujuh penguasa, tujuh tarif, satu tol. Kujumlahkan, kubagi tujuh, dan semua orang bilang aku menipu mereka.", "ผู้ปกครองเจ็ดคน อัตราเจ็ดแบบ ค่าผ่านทางหนึ่งเดียว ข้ารวมยอด แบ่งเจ็ดส่วน แล้วทุกคนก็ว่าข้าโกงพวกเขา", "Yedi hükümdar, yedi oran, tek geçiş ücreti. Toplarım, yediye bölerim, herkes onları kazıkladığımı söyler.", "Siete gobernantes, siete tarifas, un peaje. Las sumo, lo divido en siete partes y todos dicen que los he estafado.", "Sete governantes, sete tarifas, um pedágio. Eu somo, divido em sete partes, e todo mundo diz que eu os enganei.", "Семь правителей, семь ставок, одна пошлина. Я всё складываю, делю на семь, и каждый говорит, что я его обсчитал.", "Семеро правителів, сім ставок, одне мито. Я все додаю, ділю на сім, і кожен каже, що я його обрахував."],
  "League roads cost less than the Queen's bridge. That's the League's whole policy, really.": ["同盟の道は女王の橋より安い。同盟の政策なんて、実のところそれだけさ。", "동맹의 길은 여왕의 다리보다 싸지. 사실 그게 동맹 정책의 전부야.", "同盟的路比女王的桥便宜。说实话,这就是同盟的全部政策。", "同盟的路比女王的橋便宜。說實話,這就是同盟的全部政策。", "Đường của Liên minh rẻ hơn cầu của Nữ hoàng. Thật ra đó là toàn bộ chính sách của Liên minh.", "Jalan Liga lebih murah daripada jembatan Ratu. Sebenarnya, itulah seluruh kebijakan Liga.", "ถนนของสันนิบาตถูกกว่าสะพานของราชินี ว่ากันจริงๆ นั่นคือนโยบายทั้งหมดของสันนิบาต", "Birlik yolları Kraliçe'nin köprüsünden ucuzdur. Birlik'in bütün politikası bu, aslında.", "Los caminos de la Liga cuestan menos que el puente de la Reina. Esa es toda la política de la Liga, en realidad.", "As estradas da Liga custam menos que a ponte da Rainha. Essa é toda a política da Liga, na verdade.", "Дороги Лиги дешевле моста Королевы. В этом, по сути, вся политика Лиги.", "Дороги Ліги дешевші за міст Королеви. У цьому, по суті, вся політика Ліги."],
  "Delegates forget everything. Ink, cord, sandals, their own ruler's name. I sell them all of it back.": ["使節たちは何でも忘れる。インク、紐、サンダル、自分の君主の名前まで。私はそれを全部売り戻してやるのさ。", "대표들은 뭐든 잊어버려. 잉크, 끈, 샌들, 자기 군주 이름까지. 나는 그걸 전부 다시 팔지.", "代表们什么都忘。墨水、绳带、凉鞋,连自家君主的名字都忘。我把这些统统再卖给他们。", "代表們什麼都忘。墨水、繩帶、涼鞋,連自家君主的名字都忘。我把這些統統再賣給他們。", "Các đại biểu quên đủ thứ. Mực, dây buộc, dép, cả tên vua của mình. Tôi bán lại cho họ tất cả.", "Para delegasi lupa segalanya. Tinta, tali, sandal, nama penguasa mereka sendiri. Kujual semuanya kembali kepada mereka.", "พวกผู้แทนลืมทุกอย่าง หมึก เชือก รองเท้าแตะ แม้แต่ชื่อผู้ปกครองของตัวเอง ข้าก็ขายคืนให้หมดนั่นแหละ", "Delegeler her şeyi unutur. Mürekkep, kordon, sandalet, kendi hükümdarlarının adı. Hepsini onlara geri satarım.", "Los delegados lo olvidan todo. Tinta, cordón, sandalias, el nombre de su propio gobernante. Yo se lo vuelvo a vender todo.", "Os delegados esquecem tudo. Tinta, cordão, sandálias, o nome do próprio governante. Eu vendo tudo de volta para eles.", "Делегаты всё забывают. Чернила, шнурки, сандалии, имя собственного правителя. Я всё это им и продаю обратно.", "Делегати все забувають. Чорнило, шнурки, сандалі, ім'я власного правителя. Я все це їм і продаю назад."],
  "Each of the seven ties the angarkha's cords their own way. Tie them wrong in the Mandapa and you've declared something.": ["七つの国はそれぞれ、アンガルカの紐を自分たちのやり方で結ぶ。マンダパで結び方を間違えれば、何かを宣言したことになる。", "일곱 나라는 저마다 앙가르카 끈을 자기 방식으로 묶지. 만다파에서 잘못 묶으면 뭔가를 선언한 셈이 돼.", "七国各有各的安加卡系带法。在曼达帕系错了,你就等于宣告了什么。", "七國各有各的安加卡繫帶法。在曼達帕繫錯了,你就等於宣告了什麼。", "Mỗi nước trong bảy nước buộc dây áo angarkha theo cách riêng. Buộc sai ở Mandapa là bạn đã tuyên bố điều gì đó rồi.", "Masing-masing dari ketujuhnya mengikat tali angarkha dengan caranya sendiri. Salah ikat di Mandapa dan kau sudah mengumumkan sesuatu.", "แต่ละแคว้นในเจ็ดแคว้นผูกเชือกเสื้ออังครขาในแบบของตัวเอง ผูกผิดในมณฑปเมื่อไหร่ เท่ากับเจ้าได้ประกาศอะไรบางอย่างไปแล้ว", "Yedisinin her biri angarkha'nın kordonlarını kendi usulünce bağlar. Mandapa'da yanlış bağlarsan bir şey ilan etmiş olursun.", "Cada uno de los siete ata los cordones del angarkha a su manera. Átalos mal en el Mandapa y habrás declarado algo.", "Cada um dos sete amarra os cordões do angarkha do seu jeito. Amarre errado no Mandapa e você terá declarado alguma coisa.", "Каждое из семи княжеств завязывает шнуры ангаркхи по-своему. Завяжешь неправильно в Мандапе — и ты что-то объявил.", "Кожне із семи князівств зав'язує шнури ангаркхи по-своєму. Зав'яжеш неправильно в Мандапі — і ти щось оголосив."],
  "The Mandapa closes at dusk. The arguing moves here at dusk and a minute.": ["マンダパは日暮れに閉まる。口論は日暮れの一分後にここへ移ってくる。", "만다파는 해 질 녘에 문을 닫아. 말다툼은 해 질 녘 일 분 뒤에 이리로 옮겨 오지.", "曼达帕黄昏关门。争吵在黄昏后一分钟挪到这儿来。", "曼達帕黃昏關門。爭吵在黃昏後一分鐘挪到這兒來。", "Mandapa đóng cửa lúc hoàng hôn. Cuộc cãi vã dời sang đây lúc hoàng hôn cộng một phút.", "Mandapa tutup saat senja. Perdebatannya pindah ke sini saat senja lewat semenit.", "มณฑปปิดตอนพลบค่ำ การทะเลาะย้ายมาที่นี่ตอนพลบค่ำกับอีกหนึ่งนาที", "Mandapa akşam karanlığında kapanır. Tartışma da akşam karanlığından bir dakika sonra buraya taşınır.", "El Mandapa cierra al anochecer. La discusión se muda aquí al anochecer y un minuto.", "O Mandapa fecha ao entardecer. A discussão se muda para cá ao entardecer e um minuto.", "Мандапа закрывается в сумерки. Споры переезжают сюда в сумерки и одну минуту.", "Мандапа зачиняється в присмерку. Суперечки переїжджають сюди в присмерку й одну хвилину."],
  "Seven delegations, seven tables, and they all want the one by the window.": ["七つの使節団、七つのテーブル、そしてみんな窓際の席を欲しがる。", "일곱 대표단, 일곱 테이블, 그런데 다들 창가 자리를 원하지.", "七个代表团,七张桌子,个个都想要靠窗那张。", "七個代表團,七張桌子,個個都想要靠窗那張。", "Bảy phái đoàn, bảy cái bàn, và ai cũng muốn cái bàn cạnh cửa sổ.", "Tujuh delegasi, tujuh meja, dan semuanya mau meja dekat jendela.", "ผู้แทนเจ็ดคณะ โต๊ะเจ็ดตัว และทุกคณะอยากได้โต๊ะริมหน้าต่าง", "Yedi heyet, yedi masa ve hepsi pencere kenarındakini istiyor.", "Siete delegaciones, siete mesas, y todas quieren la de la ventana.", "Sete delegações, sete mesas, e todas querem a da janela.", "Семь делегаций, семь столов, и все хотят тот, что у окна.", "Сім делегацій, сім столів, і всі хочуть той, що біля вікна."],
  "A push-dagger: you don't swing it, you punch it. The delegates' guards like them. They're quick, and they're quiet.": ["拳刀(プッシュダガー)。振るんじゃない、殴るように突くんだ。使節の護衛たちが好んで使う。素早くて、静かだからな。", "주먹 단검. 휘두르는 게 아니라 주먹질하듯 찌르는 거야. 대표들의 호위병이 좋아하지. 빠르고, 조용하니까.", "拳刃:不用挥,要像出拳一样捅。代表们的护卫很喜欢。又快,又安静。", "拳刃:不用揮,要像出拳一樣捅。代表們的護衛很喜歡。又快,又安靜。", "Dao đấm: không vung, mà đấm tới. Vệ sĩ của các đại biểu thích loại này. Nhanh, và im lặng.", "Belati tinju: tidak diayunkan, tapi ditinjukan. Para pengawal delegasi menyukainya. Cepat, dan senyap.", "กริชหมัด ไม่ต้องเหวี่ยง แต่ชกออกไป พวกองครักษ์ของผู้แทนชอบนัก มันทั้งเร็วและเงียบ", "Yumruk hançeri: sallamazsın, yumruk atar gibi saplarsın. Delegelerin muhafızları sever. Hızlıdır, sessizdir.", "Una daga de puño: no se blande, se golpea con ella. A los guardias de los delegados les gustan. Son rápidas y silenciosas.", "Uma adaga de soco: você não a brande, você soca com ela. Os guardas dos delegados gostam delas. São rápidas e silenciosas.", "Тычковый кинжал: им не машут, им бьют, как кулаком. Охрана делегатов их любит. Быстрые и тихие.", "Тичковий кинджал: ним не махають, ним б'ють, як кулаком. Охорона делегатів їх любить. Швидкі й тихі."],
  "I've a different badge each month. This month I'm guarding the Red Hills. Next month, I'll guard them from the Red Hills.": ["毎月違う記章をつけてる。今月は赤い丘の護衛だ。来月は、赤い丘から誰かを護衛してるだろうさ。", "매달 휘장이 바뀌지. 이번 달엔 붉은 언덕을 지키고 있어. 다음 달엔 붉은 언덕으로부터 다른 이들을 지키겠지.", "我每个月换一枚徽章。这个月我护卫红丘。下个月,我就要防着红丘了。", "我每個月換一枚徽章。這個月我護衛紅丘。下個月,我就要防著紅丘了。", "Mỗi tháng tôi đeo một huy hiệu khác. Tháng này tôi bảo vệ Đồi Đỏ. Tháng sau, tôi sẽ bảo vệ người ta khỏi Đồi Đỏ.", "Lencanaku ganti tiap bulan. Bulan ini aku menjaga Bukit Merah. Bulan depan, aku akan menjaga orang dari Bukit Merah.", "ข้าติดตราคนละอันทุกเดือน เดือนนี้ข้าคุ้มกันเนินแดง เดือนหน้า ข้าจะคุ้มกันคนอื่นจากเนินแดง", "Her ay farklı bir rozetim olur. Bu ay Kızıl Tepeler'i koruyorum. Gelecek ay, başkalarını Kızıl Tepeler'den koruyacağım.", "Llevo una insignia distinta cada mes. Este mes custodio a las Colinas Rojas. El mes que viene, custodiaré a los demás de las Colinas Rojas.", "Tenho um distintivo diferente a cada mês. Este mês estou protegendo as Colinas Vermelhas. Mês que vem, vou proteger os outros das Colinas Vermelhas.", "Каждый месяц у меня новый значок. В этом месяце я охраняю Красные Холмы. В следующем буду охранять от Красных Холмов.", "Щомісяця в мене новий значок. Цього місяця я охороняю Червоні Пагорби. Наступного охоронятиму від Червоних Пагорбів."],
  "Keep your voice down near the Mandapa. Somebody's always about to say something important.": ["マンダパの近くでは声を落としな。いつだって誰かが何か大事なことを言いかけてるから。", "만다파 근처에선 목소리를 낮춰. 늘 누군가 중요한 말을 하려는 참이니까.", "在曼达帕附近小点声。总有人正要说什么要紧话。", "在曼達帕附近小點聲。總有人正要說什麼要緊話。", "Nói nhỏ thôi khi ở gần Mandapa. Lúc nào cũng có ai đó sắp nói điều gì quan trọng.", "Pelankan suaramu di dekat Mandapa. Selalu ada yang hendak mengatakan sesuatu yang penting.", "ใกล้มณฑปพูดเบาๆ หน่อย มักมีใครสักคนกำลังจะพูดอะไรสำคัญอยู่เสมอ", "Mandapa'nın yakınında sesini alçak tut. Her zaman birisi önemli bir şey söylemek üzeredir.", "Baja la voz cerca del Mandapa. Siempre hay alguien a punto de decir algo importante.", "Fale baixo perto do Mandapa. Sempre tem alguém prestes a dizer algo importante.", "Говори тише возле Мандапы. Там всегда кто-нибудь вот-вот скажет что-то важное.", "Говори тихіше біля Мандапи. Там завжди хтось ось-ось скаже щось важливе."],
  "The League argued for nine days about where to stand a parasol. Nine. My wedding took one.": ["同盟は日傘をどこに立てるかで九日間も議論した。九日だよ。私の結婚式は一日で済んだのに。", "동맹은 일산을 어디에 세울지를 두고 아흐레 동안 논쟁했어. 아흐레. 내 결혼식은 하루 걸렸는데.", "同盟为了一顶华盖立在哪儿争了九天。九天。我的婚礼才用了一天。", "同盟為了一頂華蓋立在哪兒爭了九天。九天。我的婚禮才用了一天。", "Liên minh cãi nhau chín ngày về chỗ dựng một chiếc lọng. Chín ngày. Đám cưới của tôi mất có một.", "Liga berdebat sembilan hari soal di mana menancapkan sebuah payung. Sembilan. Pernikahanku cuma sehari.", "สันนิบาตเถียงกันเก้าวันว่าจะตั้งฉัตรไว้ตรงไหน เก้าวัน งานแต่งของข้าใช้วันเดียว", "Birlik bir şemsiyenin nereye dikileceğini dokuz gün tartıştı. Dokuz. Benim düğünüm bir gün sürdü.", "La Liga discutió nueve días sobre dónde poner un parasol. Nueve. Mi boda duró uno.", "A Liga discutiu nove dias sobre onde colocar um para-sol. Nove. Meu casamento levou um.", "Лига девять дней спорила, где поставить зонт. Девять. Моя свадьба заняла один.", "Ліга дев'ять днів сперечалася, де поставити парасоль. Дев'ять. Моє весілля тривало один."],
  "The plain is League country. The water in it is Ilavarta's, they say. The rain doesn't know whose it is.": ["平原は同盟の土地だ。そこを流れる水はイラヴァルタのものだ、と彼らは言う。雨は自分が誰のものか知らないがね。", "평원은 동맹의 땅이야. 거기 흐르는 물은 일라바르타의 것이라고들 하지. 비는 자기가 누구 건지 몰라.", "平原是同盟的地盘。他们说,里面的水是伊拉瓦塔的。雨可不知道自己是谁的。", "平原是同盟的地盤。他們說,裡面的水是伊拉瓦塔的。雨可不知道自己是誰的。", "Đồng bằng là đất của Liên minh. Còn nước trong đó là của Ilavarta, người ta bảo vậy. Mưa thì chẳng biết mình là của ai.", "Dataran ini wilayah Liga. Airnya milik Ilavarta, kata mereka. Hujan tidak tahu ia milik siapa.", "ที่ราบเป็นดินแดนของสันนิบาต แต่น้ำในนั้นเป็นของอิลาวรรตะ เขาว่ากันอย่างนั้น ฝนไม่รู้หรอกว่าตัวเองเป็นของใคร", "Ova Birlik toprağıdır. İçindeki su Ilavarta'nınmış, öyle diyorlar. Yağmur kimin olduğunu bilmez.", "La llanura es tierra de la Liga. El agua que corre por ella es de Ilavarta, dicen. La lluvia no sabe de quién es.", "A planície é terra da Liga. A água nela é de Ilavarta, dizem. A chuva não sabe de quem é.", "Равнина — земля Лиги. А вода в ней, говорят, Илаварты. Дождь не знает, чей он.", "Рівнина — земля Ліги. А вода в ній, кажуть, Ілаварти. Дощ не знає, чий він."],
  "The Speaker is from Hemapura this year. Next year, the Two Rivers. They'll argue about that too.": ["今年の議長はヘマプラの出だ。来年は二つの川。それについてもまた議論になるだろうよ。", "올해 의장은 헤마푸라 출신이야. 내년엔 두 강. 그걸 두고도 또 논쟁하겠지.", "今年的议长来自赫玛普拉。明年轮到双河。这事他们也会吵。", "今年的議長來自赫瑪普拉。明年輪到雙河。這事他們也會吵。", "Năm nay Phát ngôn nhân đến từ Hemapura. Năm sau là Hai Sông. Chuyện đó họ cũng sẽ cãi nhau.", "Juru Bicara tahun ini dari Hemapura. Tahun depan, Dua Sungai. Soal itu pun mereka akan berdebat.", "ปีนี้ประธานมาจากเหมปุระ ปีหน้าเป็นสองนที เรื่องนั้นพวกเขาก็จะเถียงกันอีก", "Sözcü bu yıl Hemapura'dan. Gelecek yıl İki Nehir'den. Onu da tartışacaklar.", "La Portavoz es de Hemapura este año. El año que viene, de los Dos Ríos. También discutirán por eso.", "A Porta-voz é de Hemapura este ano. Ano que vem, dos Dois Rios. Vão discutir isso também.", "В этом году Глашатай из Хемапуры. В следующем — из Двух Рек. Об этом они тоже будут спорить.", "Цього року Речниця з Хемапури. Наступного — з Двох Річок. Про це вони теж сперечатимуться."],
  "Suvarnatira owes no crown. We owe the Assembly, and the Assembly owes its readers and its ships. It's a better debt.": ["スヴァルナティーラはどの王冠にも借りはない。我らは議会に借りがあり、議会は読み手と船に借りがある。そのほうがましな借りだ。", "수바르나티라는 어떤 왕관에도 빚지지 않았어. 우리는 의회에 빚지고, 의회는 독자들과 배들에 빚지지. 더 나은 빚이야.", "苏瓦尔纳蒂拉不欠任何王冠。我们欠议会的,议会欠它的读者和船只的。这是更好的债。", "蘇瓦爾納蒂拉不欠任何王冠。我們欠議會的,議會欠它的讀者和船隻的。這是更好的債。", "Suvarnatira không mắc nợ vương miện nào. Chúng tôi mắc nợ Hội đồng, còn Hội đồng mắc nợ những người đọc và những con tàu của mình. Đó là món nợ tốt hơn.", "Suvarnatira tidak berutang pada mahkota mana pun. Kami berutang pada Majelis, dan Majelis berutang pada para pembacanya dan kapal-kapalnya. Itu utang yang lebih baik.", "สุวรรณตีระไม่ติดหนี้มงกุฎใด เราติดหนี้สภา และสภาติดหนี้ผู้อ่านกับเรือของตน เป็นหนี้ที่ดีกว่า", "Suvarnatira hiçbir taca borçlu değildir. Biz Meclis'e borçluyuz, Meclis de okurlarına ve gemilerine. Daha iyi bir borç.", "Suvarnatira no le debe nada a ninguna corona. Nosotros le debemos a la Asamblea, y la Asamblea a sus lectores y a sus barcos. Es una deuda mejor.", "Suvarnatira não deve nada a coroa nenhuma. Nós devemos à Assembleia, e a Assembleia deve aos seus leitores e aos seus navios. É uma dívida melhor.", "Суварнатира не должна ни одной короне. Мы в долгу перед Собранием, а Собрание — перед своими читателями и кораблями. Это долг получше.", "Суварнатіра не винна жодній короні. Ми в боргу перед Зборами, а Збори — перед своїми читачами й кораблями. Це кращий борг."],
  "The Obsidian Legacy says our star chart is theirs. It may be. It may also be older than they are, which is the trouble with being the oldest blood.": ["黒曜の遺統は、我らの星図は自分たちのものだと言う。そうかもしれない。だが彼らより古いのかもしれない。最古の血筋であることの厄介さはそこにある。", "흑요 유산은 우리 성도가 자기들 것이라고 하지. 그럴지도 몰라. 그들보다 더 오래된 것일 수도 있고. 가장 오래된 혈통이라는 게 바로 그게 골치야.", "黑曜遗脉说我们的星图是他们的。也许是。也许它比他们还古老——这正是身为最古老血脉的麻烦。", "黑曜遺脈說我們的星圖是他們的。也許是。也許它比他們還古老——這正是身為最古老血脈的麻煩。", "Di Sản Hắc Diện bảo tấm tinh đồ của chúng tôi là của họ. Có thể lắm. Cũng có thể nó còn cổ hơn cả họ, đó chính là cái phiền của dòng máu lâu đời nhất.", "Warisan Obsidian bilang peta bintang kami milik mereka. Mungkin saja. Mungkin juga peta itu lebih tua daripada mereka, dan itulah repotnya menjadi darah tertua.", "มรดกออบซิเดียนว่าแผนที่ดาวของเราเป็นของพวกเขา อาจจะใช่ แต่มันก็อาจเก่าแก่กว่าพวกเขาด้วย นั่นแหละคือปัญหาของการเป็นสายเลือดที่เก่าแก่ที่สุด", "Obsidyen Mirası yıldız haritamızın kendilerine ait olduğunu söylüyor. Olabilir. Onlardan daha eski de olabilir; en eski kan olmanın derdi de budur.", "El Legado de Obsidiana dice que nuestra carta estelar es suya. Puede ser. También puede que sea más antigua que ellos, que es el problema de ser la sangre más antigua.", "O Legado de Obsidiana diz que nosso mapa estelar é deles. Pode ser. Também pode ser mais antigo que eles, que é o problema de ser o sangue mais antigo.", "Обсидиановое наследие говорит, что наша звёздная карта — их. Может быть. А может, она старше их самих, в том-то и беда древнейшей крови.", "Обсидіанова спадщина каже, що наша зоряна мапа — їхня. Можливо. А може, вона старша за них самих, у тому й біда найдавнішої крові."],
  "Ilavarta, the League, Shailagarh, the Kanthari: all of them send scholars to our Archive. None of them send money. We manage.": ["イラヴァルタ、同盟、シャイラガル、カンタリ。みんな我らの文書館に学者をよこす。金をよこす者はいない。なんとかやってるよ。", "일라바르타, 동맹, 샤일라가르, 칸타리족. 모두 우리 서고에 학자를 보내지. 돈을 보내는 곳은 하나도 없어. 그럭저럭 꾸려 가고 있지.", "伊拉瓦塔、同盟、沙伊拉加尔、坎塔里人:个个都往我们的档案馆派学者。没一个送钱来。我们凑合着过。", "伊拉瓦塔、同盟、沙伊拉加爾、坎塔里人:個個都往我們的檔案館派學者。沒一個送錢來。我們湊合著過。", "Ilavarta, Liên minh, Shailagarh, người Kanthari: ai cũng gửi học giả đến Văn khố của chúng tôi. Chẳng ai gửi tiền. Chúng tôi vẫn xoay xở được.", "Ilavarta, Liga, Shailagarh, orang Kanthari: semuanya mengirim cendekiawan ke Arsip kami. Tak satu pun mengirim uang. Kami bertahan.", "อิลาวรรตะ สันนิบาต ไศลครห์ ชาวกันถารี ทุกฝ่ายส่งนักปราชญ์มาที่หอจดหมายเหตุของเรา ไม่มีใครส่งเงินมาสักราย เราก็พอถูไถไปได้", "Ilavarta, Birlik, Shailagarh, Kanthariler: hepsi Arşiv'imize âlim gönderir. Hiçbiri para göndermez. İdare ediyoruz.", "Ilavarta, la Liga, Shailagarh, los kanthari: todos mandan eruditos a nuestro Archivo. Ninguno manda dinero. Nos apañamos.", "Ilavarta, a Liga, Shailagarh, os kanthari: todos mandam estudiosos ao nosso Arquivo. Nenhum manda dinheiro. A gente se vira.", "Илаварта, Лига, Шайлагарх, кантхари — все присылают учёных в наш Архив. Никто не присылает денег. Справляемся.", "Ілаварта, Ліга, Шайлагарх, кантхарі — усі надсилають учених до нашого Архіву. Ніхто не надсилає грошей. Даємо раду."],
  "We read Azhurak glyphs differently here than the Orashai do. They read them as words. We read them as numbers that forgot what they counted.": ["ここではアズラクの文字をオラシャイとは違うふうに読む。彼らは言葉として読む。我らは、何を数えていたか忘れてしまった数として読む。", "여기선 아주라크 문자를 오라샤이와 다르게 읽어. 그들은 단어로 읽지. 우리는 무엇을 세었는지 잊어버린 숫자로 읽고.", "我们这儿解读阿祖拉克文字的方式和奥拉沙伊不同。他们当作文字读。我们当作忘了自己在数什么的数字读。", "我們這兒解讀阿祖拉克文字的方式和奧拉沙伊不同。他們當作文字讀。我們當作忘了自己在數什麼的數字讀。", "Ở đây chúng tôi đọc chữ khắc Azhurak khác với người Orashai. Họ đọc chúng như chữ. Chúng tôi đọc chúng như những con số đã quên mất mình từng đếm gì.", "Di sini kami membaca glif Azhurak dengan cara berbeda dari orang Orashai. Mereka membacanya sebagai kata. Kami membacanya sebagai angka yang lupa apa yang dulu mereka hitung.", "ที่นี่เราอ่านอักษรภาพอาซูรักต่างจากพวกโอราชัย พวกเขาอ่านเป็นคำ เราอ่านเป็นตัวเลขที่ลืมไปแล้วว่าเคยนับอะไร", "Burada Azhurak gliflerini Orashai'den farklı okuruz. Onlar kelime olarak okur. Biz neyi saydıklarını unutmuş sayılar olarak okuruz.", "Aquí leemos los glifos de Azhurak de otra manera que los Orashai. Ellos los leen como palabras. Nosotros, como números que olvidaron qué contaban.", "Aqui lemos os glifos de Azhurak de um jeito diferente dos Orashai. Eles os leem como palavras. Nós, como números que esqueceram o que contavam.", "Мы здесь читаем глифы Азурака не так, как Орашай. Они читают их как слова. Мы — как числа, забывшие, что они считали.", "Ми тут читаємо гліфи Азурака не так, як Орашай. Вони читають їх як слова. Ми — як числа, що забули, що вони рахували."],
  "Four hundred thousand leaves in the Archive, and a catalogue of three hundred thousand. Somewhere in the other hundred is everything.": ["文書館には四十万枚の葉、目録には三十万。残りの十万のどこかに、すべてがある。", "서고에는 사십만 장의 잎, 목록에는 삼십만 장. 나머지 십만 장 어딘가에 모든 게 있지요.", "档案馆里有四十万片贝叶,目录却只有三十万条。剩下的十万里,藏着一切。", "檔案館裡有四十萬片貝葉,目錄卻只有三十萬條。剩下的十萬裡,藏著一切。", "Bốn trăm nghìn lá thư trong Văn khố, và một danh mục ba trăm nghìn. Đâu đó trong một trăm nghìn còn lại là tất cả mọi thứ.", "Empat ratus ribu lembar lontar di Arsip, dan katalognya tiga ratus ribu. Di suatu tempat di seratus ribu sisanya, ada segalanya.", "ในหอจดหมายเหตุมีใบลานสี่แสนใบ แต่บัญชีรายการมีแค่สามแสน ที่ไหนสักแห่งในอีกแสนใบที่เหลือ คือทุกสิ่ง", "Arşiv'de dört yüz bin yaprak var, kataloğu ise üç yüz bin. Geri kalan yüz binin bir yerinde her şey duruyor.", "Cuatrocientas mil hojas en el Archivo y un catálogo de trescientas mil. En algún lugar de las otras cien mil está todo.", "Quatrocentas mil folhas no Arquivo, e um catálogo de trezentas mil. Em algum lugar das outras cem mil está tudo.", "В Архиве четыреста тысяч листов, а в каталоге — триста тысяч. Где-то в оставшихся ста тысячах есть всё.", "В Архіві чотириста тисяч аркушів, а в каталозі — триста тисяч. Десь у решті ста тисяч є все."],
  "The star chart? Azhurak, I'm almost sure. Almost. The Legacy's envoy is entirely sure, which makes me less.": ["星図ですか? アズラクのもの、ほぼ間違いありません。ほぼ、ね。遺統の使節殿は完全に確信していて、おかげで私の確信は減りました。", "성도요? 아주라크 것이 거의 확실합니다. 거의요. 유산의 사절은 완전히 확신하던데, 그래서 저는 덜 확신하게 됐어요.", "那张星图?阿祖拉克的,我几乎可以肯定。几乎。遗脉的使节完全肯定,这反倒让我没那么肯定了。", "那張星圖?阿祖拉克的,我幾乎可以肯定。幾乎。遺脈的使節完全肯定,這反倒讓我沒那麼肯定了。", "Tấm tinh đồ ư? Của Azhurak, tôi gần như chắc chắn. Gần như thôi. Sứ giả của Di Sản thì hoàn toàn chắc chắn, thế nên tôi lại bớt chắc đi.", "Peta bintang itu? Azhurak, saya hampir yakin. Hampir. Utusan Warisan sepenuhnya yakin, dan itu membuat saya kurang yakin.", "แผนที่ดาวน่ะหรือ ของอาซูรัก ผมเกือบแน่ใจ เกือบนะ ทูตของมรดกแน่ใจเต็มร้อย ซึ่งทำให้ผมแน่ใจน้อยลง", "Yıldız haritası mı? Azhurak'ın, neredeyse eminim. Neredeyse. Miras'ın elçisi tamamen emin, bu da beni daha az emin kılıyor.", "¿La carta estelar? De Azhurak, estoy casi seguro. Casi. El enviado del Legado está completamente seguro, lo cual me deja menos.", "A carta estelar? De Azhurak, tenho quase certeza. Quase. O enviado do Legado tem certeza absoluta, o que me deixa com menos.", "Звёздная карта? Азурак, я почти уверен. Почти. Посланник Наследия уверен полностью, и от этого я уверен меньше.", "Зоряна карта? Азурак, я майже певен. Майже. Посланець Спадщини певен цілком, і від цього я певен менше."],
  "The chart was carried out of Kharaveth a hundred years ago by a thief who sold it here. The Legacy keeps every monument of Azhurak. This is one.": ["その星図は百年前、ある盗人がカラヴェスから持ち出し、ここで売ったものだ。遺統はアズラクのあらゆる遺物を守る。これもその一つだ。", "그 성도는 백 년 전 한 도둑이 카라베스에서 빼돌려 여기서 팔아넘긴 것이오. 유산은 아주라크의 모든 유물을 지키지. 이것도 그중 하나요.", "这张星图是百年前一个窃贼从卡拉维斯带出来,在这里卖掉的。遗脉守护阿祖拉克的每一件遗物。这就是其中之一。", "這張星圖是百年前一個竊賊從卡拉維斯帶出來,在這裡賣掉的。遺脈守護阿祖拉克的每一件遺物。這就是其中之一。", "Tấm tinh đồ bị một tên trộm mang ra khỏi Kharaveth trăm năm trước rồi bán ở đây. Di Sản gìn giữ mọi di tích của Azhurak. Đây là một trong số đó.", "Peta itu dibawa keluar dari Kharaveth seratus tahun lalu oleh seorang pencuri yang menjualnya di sini. Warisan menjaga setiap monumen Azhurak. Ini salah satunya.", "แผนที่นั้นถูกโจรคนหนึ่งขนออกจากคาราเวธเมื่อร้อยปีก่อนแล้วมาขายที่นี่ มรดกดูแลอนุสรณ์ทุกชิ้นของอาซูรัก นี่คือหนึ่งในนั้น", "Harita yüz yıl önce bir hırsız tarafından Kharaveth'ten kaçırılıp burada satıldı. Miras, Azhurak'ın her anıtını korur. Bu da onlardan biri.", "La carta salió de Kharaveth hace cien años en manos de un ladrón que la vendió aquí. El Legado custodia todos los monumentos de Azhurak. Este es uno.", "A carta foi levada de Kharaveth há cem anos por um ladrão que a vendeu aqui. O Legado guarda todos os monumentos de Azhurak. Este é um deles.", "Карту вывез из Харавета сто лет назад вор, который продал её здесь. Наследие хранит все памятники Азурака. Это один из них.", "Карту вивіз із Харавета сто років тому злодій, який продав її тут. Спадщина береже всі пам'ятки Азурака. Це одна з них."],
  "The Provost is gracious. The Archivist is learned. Neither of them will give me the chart. I am patient; I'm from Tamesh.": ["学頭殿は寛大だ。文書官殿は博識だ。どちらも私に星図を渡してはくれない。私は辛抱強い。タメシュの出だからな。", "학장은 너그럽고, 서고지기는 박식하오. 둘 다 내게 성도를 내주지는 않겠지만. 나는 참을성이 있소. 타메시 출신이니까.", "院长很亲切。档案官很博学。可他们谁也不肯把星图给我。我有耐心;我是塔梅什人。", "院長很親切。檔案官很博學。可他們誰也不肯把星圖給我。我有耐心;我是塔梅什人。", "Viện trưởng thật nhã nhặn. Người giữ văn khố thật uyên bác. Chẳng ai trong hai người chịu đưa tôi tấm tinh đồ. Tôi kiên nhẫn; tôi đến từ Tamesh mà.", "Provos itu ramah. Arsiparisnya terpelajar. Tak satu pun dari mereka mau memberi saya peta itu. Saya sabar; saya dari Tamesh.", "อธิการมีน้ำใจ บรรณารักษ์ก็รอบรู้ ไม่มีใครยอมให้แผนที่แก่ข้า ข้าอดทนได้ ข้ามาจากทาเมช", "Rektör nazik. Arşivci bilgili. İkisi de haritayı bana vermeyecek. Sabırlıyımdır; Tamesh'liyim.", "La prebostesa es amable. El archivero es erudito. Ninguno de los dos me dará la carta. Soy paciente; soy de Tamesh.", "A reitora é gentil. O arquivista é erudito. Nenhum dos dois vai me dar a carta. Sou paciente; sou de Tamesh.", "Провост любезна. Архивариус учён. Ни тот, ни другая не отдадут мне карту. Я терпелив: я из Тамеша.", "Провост люб'язна. Архіваріус учений. Жоден із них не віддасть мені карту. Я терплячий: я з Тамеша."],
  "Sorry, I was reading. I'm always reading. Did you know the Kanthari count in twelves?": ["すみません、読んでいました。いつも読んでいるんです。カンタリが十二ずつ数えるってご存じでした?", "죄송해요, 읽고 있었어요. 전 늘 뭔가 읽고 있죠. 칸타리족이 열둘씩 센다는 거 아세요?", "抱歉,我在看书。我总是在看书。你知道坎塔里人是按十二进位数数的吗?", "抱歉,我在看書。我總是在看書。你知道坎塔里人是以十二進位數數的嗎?", "Xin lỗi, tôi đang đọc. Tôi lúc nào cũng đọc. Bạn có biết người Kanthari đếm theo hệ mười hai không?", "Maaf, saya sedang membaca. Saya selalu membaca. Tahukah Anda orang Kanthari berhitung dengan basis dua belas?", "ขอโทษที ฉันกำลังอ่านอยู่ ฉันอ่านตลอดแหละ รู้ไหมว่าชาวกันถารีนับเลขทีละสิบสอง", "Pardon, okuyordum. Hep okurum. Kanthariler'in on ikişer saydığını biliyor muydunuz?", "Perdona, estaba leyendo. Siempre estoy leyendo. ¿Sabías que los kanthari cuentan de doce en doce?", "Desculpe, eu estava lendo. Estou sempre lendo. Sabia que os kanthari contam de doze em doze?", "Простите, я читал. Я всегда читаю. Вы знали, что кантхари считают дюжинами?", "Вибачте, я читав. Я завжди читаю. Ви знали, що кантхарі рахують дюжинами?"],
  "The Archive's open to anyone with clean hands and a reason. My reason is that I can't stop.": ["文書館は、手が清く理由がある者なら誰にでも開かれています。私の理由は、やめられないことです。", "서고는 손이 깨끗하고 이유가 있는 사람이면 누구에게나 열려 있어요. 제 이유는 멈출 수가 없다는 거고요.", "档案馆对任何手干净、有理由的人开放。我的理由是:我停不下来。", "檔案館對任何手乾淨、有理由的人開放。我的理由是:我停不下來。", "Văn khố mở cửa cho bất kỳ ai có đôi tay sạch và một lý do. Lý do của tôi là tôi không dừng được.", "Arsip terbuka bagi siapa saja yang tangannya bersih dan punya alasan. Alasan saya: saya tidak bisa berhenti.", "หอจดหมายเหตุเปิดให้ทุกคนที่มือสะอาดและมีเหตุผล เหตุผลของฉันคือฉันหยุดไม่ได้", "Arşiv, eli temiz ve bir nedeni olan herkese açık. Benim nedenim, duramamam.", "El Archivo está abierto a cualquiera con las manos limpias y un motivo. Mi motivo es que no puedo parar.", "O Arquivo está aberto a qualquer um de mãos limpas e com um motivo. Meu motivo é que não consigo parar.", "Архив открыт всем, у кого чистые руки и есть причина. Моя причина — я не могу остановиться.", "Архів відкритий усім, у кого чисті руки й є причина. Моя причина — я не можу зупинитися."],
  "Rope, tar, biscuit, oil, charts. A port's needs are simple; it's the sailors who aren't.": ["縄、タール、乾パン、油、海図。港に要るものは単純です。単純じゃないのは船乗りのほうで。", "밧줄, 타르, 건빵, 기름, 해도. 항구에 필요한 건 단순해요. 단순하지 않은 건 뱃사람들이죠.", "绳索、焦油、硬饼干、灯油、海图。港口要的东西很简单;不简单的是水手。", "繩索、焦油、硬餅乾、燈油、海圖。港口要的東西很簡單;不簡單的是水手。", "Dây thừng, hắc ín, bánh quy khô, dầu, hải đồ. Nhu cầu của một bến cảng thì đơn giản; thủy thủ mới không đơn giản.", "Tali, ter, biskuit, minyak, peta laut. Kebutuhan pelabuhan itu sederhana; pelautnya yang tidak.", "เชือก น้ำมันดิน ขนมปังกรอบ น้ำมัน แผนที่เดินเรือ ท่าเรือต้องการของง่าย ๆ คนที่ไม่ง่ายคือพวกกะลาสี", "Halat, katran, peksimet, yağ, deniz haritası. Bir limanın ihtiyaçları basittir; basit olmayan denizcilerdir.", "Cuerda, brea, galleta, aceite, cartas náuticas. Las necesidades de un puerto son sencillas; los marineros, no.", "Corda, piche, biscoito, óleo, cartas náuticas. As necessidades de um porto são simples; os marinheiros é que não.", "Канат, смола, сухари, масло, карты. Нужды порта просты; непросты моряки.", "Канати, смола, сухарі, олія, мапи. Потреби порту прості; непрості моряки."],
  "Silk from the east, cotton from the valley, and the Assembly's ink-dye, which is a secret. A good one.": ["東の絹、谷の綿、そして議会の墨染め。こいつは秘伝でしてね。いい秘伝ですよ。", "동쪽의 비단, 계곡의 무명, 그리고 의회의 먹 염료. 그건 비밀이에요. 좋은 비밀이죠.", "东方的丝绸,河谷的棉布,还有议会的墨染,那是秘方。好秘方。", "東方的絲綢,河谷的棉布,還有議會的墨染,那是祕方。好祕方。", "Lụa từ phương đông, vải bông từ thung lũng, và thuốc nhuộm mực của Hội đồng, thứ ấy là bí mật. Một bí mật hay.", "Sutra dari timur, katun dari lembah, dan pewarna tinta Majelis, yang rahasia. Rahasia yang bagus.", "ไหมจากตะวันออก ฝ้ายจากหุบเขา และสีย้อมหมึกของสภา ซึ่งเป็นความลับ ความลับที่ดีด้วย", "Doğudan ipek, vadiden pamuk ve Meclis'in mürekkep boyası; o bir sır. İyi bir sır.", "Seda del este, algodón del valle y el tinte de tinta de la Asamblea, que es un secreto. Uno bueno.", "Seda do leste, algodão do vale e a tinta-corante da Assembleia, que é segredo. Dos bons.", "Шёлк с востока, хлопок из долины и чернильная краска Собрания — это секрет. Хороший.", "Шовк зі сходу, бавовна з долини та чорнильна фарба Зборів — це таємниця. Добра."],
  "Scholars pay in coin, merchants pay in news. Sailors pay in songs, mostly, which is why they eat at the back.": ["学者は金で払い、商人は噂で払う。船乗りはたいてい歌で払う。だから奥の席で食べてもらうんです。", "학자는 돈으로, 상인은 소식으로 값을 치러요. 뱃사람은 대개 노래로 치르죠. 그래서 그 사람들은 구석에서 먹어요.", "学者付钱,商人付消息。水手大多付歌,所以他们坐在最里头吃。", "學者付錢,商人付消息。水手大多付歌,所以他們坐在最裡頭吃。", "Học giả trả bằng tiền, thương nhân trả bằng tin tức. Thủy thủ thì phần lớn trả bằng bài hát, nên họ ngồi ăn ở phía sau.", "Cendekiawan bayar dengan koin, pedagang bayar dengan kabar. Pelaut kebanyakan bayar dengan lagu, makanya mereka makan di belakang.", "นักปราชญ์จ่ายเป็นเหรียญ พ่อค้าจ่ายเป็นข่าว กะลาสีส่วนใหญ่จ่ายเป็นเพลง พวกเขาถึงได้นั่งกินอยู่หลังร้าน", "Âlimler sikkeyle öder, tüccarlar haberle. Denizciler çoğunlukla şarkıyla öder; o yüzden arkada yerler.", "Los eruditos pagan en monedas; los mercaderes, en noticias. Los marineros pagan casi siempre en canciones, y por eso comen al fondo.", "Estudiosos pagam em moedas, mercadores pagam em notícias. Marinheiros pagam quase sempre em canções, e é por isso que comem lá no fundo.", "Учёные платят монетой, купцы — новостями. Моряки платят в основном песнями, потому и едят в дальнем углу.", "Учені платять монетою, купці — новинами. Моряки платять здебільшого піснями, тому й їдять у дальньому кутку."],
  "Sit by the window, you'll see every ship come in. Sit by the door, you'll hear what's on them.": ["窓際に座れば、入ってくる船がみんな見える。戸口に座れば、何を積んでるか聞こえてくる。", "창가에 앉으면 들어오는 배가 다 보이고, 문가에 앉으면 배에 뭐가 실렸는지 다 들려요.", "坐窗边,每艘进港的船都看得见。坐门边,船上装了什么都听得见。", "坐窗邊,每艘進港的船都看得見。坐門邊,船上裝了什麼都聽得見。", "Ngồi cạnh cửa sổ, bạn sẽ thấy mọi con tàu cập bến. Ngồi cạnh cửa ra vào, bạn sẽ nghe trên tàu chở gì.", "Duduk dekat jendela, kau akan melihat setiap kapal yang masuk. Duduk dekat pintu, kau akan mendengar apa muatannya.", "นั่งริมหน้าต่างจะเห็นเรือทุกลำที่เข้าเทียบ นั่งริมประตูจะได้ยินว่าบนเรือมีอะไร", "Pencere kenarına otur, gelen her gemiyi görürsün. Kapının yanına otur, içlerinde ne olduğunu duyarsın.", "Siéntate junto a la ventana y verás llegar cada barco. Siéntate junto a la puerta y oirás qué traen.", "Sente perto da janela e você verá cada navio chegar. Sente perto da porta e vai ouvir o que eles trazem.", "Сядешь у окна — увидишь каждый корабль, что входит в порт. Сядешь у двери — услышишь, что на них везут.", "Сядеш біля вікна — побачиш кожен корабель, що заходить у порт. Сядеш біля дверей — почуєш, що на них везуть."],
  "Anchors, hinges, sabres and lamps. The Archive orders the lamps by the hundred. Reading is hard on brass.": ["錨、蝶番、サーベル、ランプ。文書館はランプを百個単位で注文してくる。読書は真鍮に厳しいんだ。", "닻, 경첩, 사브르, 등잔. 서고는 등잔을 백 개씩 주문하지. 책 읽기는 놋쇠를 혹사시키거든.", "锚、合页、军刀和油灯。档案馆订油灯都是一百盏一百盏地订。读书可费黄铜了。", "錨、鉸鏈、軍刀和油燈。檔案館訂油燈都是一百盞一百盞地訂。讀書可費黃銅了。", "Mỏ neo, bản lề, kiếm cong và đèn. Văn khố đặt đèn theo từng trăm cái. Đọc sách hao đồng thau lắm.", "Jangkar, engsel, pedang lengkung, dan lampu. Arsip memesan lampu per seratus. Membaca itu berat bagi kuningan.", "สมอ บานพับ ดาบโค้ง และตะเกียง หอจดหมายเหตุสั่งตะเกียงทีละร้อย การอ่านนี่เปลืองทองเหลืองจริง ๆ", "Çapa, menteşe, kılıç ve lamba. Arşiv lambaları yüzer yüzer ısmarlar. Okumak pirince ağır gelir.", "Anclas, bisagras, sables y lámparas. El Archivo encarga las lámparas de cien en cien. Leer es duro para el latón.", "Âncoras, dobradiças, sabres e lamparinas. O Arquivo encomenda lamparinas às centenas. Ler é duro para o latão.", "Якоря, петли, сабли и лампы. Архив заказывает лампы сотнями. Чтение тяжело даётся латуни.", "Якорі, завіси, шаблі й лампи. Архів замовляє лампи сотнями. Читання важко дається латуні."],
  "Harbour watch. The corsairs work the shore south of here. If you see a low black boat, don't wave.": ["港の見張りだ。海賊どもはここから南の海岸で稼いでいる。低い黒い船を見かけても、手は振るなよ。", "항구 경비다. 해적들이 여기 남쪽 해안을 휘젓고 다니지. 낮고 검은 배를 보거든 손 흔들지 마.", "港口巡卫。海盗在这儿往南的海岸活动。要是看见一条低矮的黑船,别挥手。", "港口巡衛。海盜在這兒往南的海岸活動。要是看見一條低矮的黑船,別揮手。", "Canh gác bến cảng. Bọn cướp biển hoạt động dọc bờ biển phía nam đây. Nếu thấy một con thuyền đen thấp, đừng vẫy tay.", "Penjaga pelabuhan. Para perompak beroperasi di pantai selatan sini. Kalau kau lihat perahu hitam yang rendah, jangan melambai.", "ยามท่าเรือ พวกโจรสลัดออกหากินตามชายฝั่งทางใต้ของที่นี่ ถ้าเห็นเรือดำลำเตี้ย ๆ อย่าโบกมือ", "Liman nöbeti. Korsanlar buranın güneyindeki kıyıda iş görür. Alçak, kara bir tekne görürsen el sallama.", "Guardia del puerto. Los corsarios trabajan la costa al sur de aquí. Si ves una barca negra y baja, no saludes.", "Guarda do porto. Os corsários atuam na costa ao sul daqui. Se vir um barco preto e baixo, não acene.", "Портовая стража. Корсары промышляют на побережье к югу отсюда. Увидишь низкую чёрную лодку — не маши ей.", "Портова варта. Корсари промишляють на узбережжі на південь звідси. Побачиш низький чорний човен — не махай йому."],
  "No crown, no toll on books. Plenty of tolls on everything else, though.": ["王冠なし、本に通行税なし。ほかのものには山ほど税がかかるがね。", "왕관도 없고, 책에는 통행세도 없지. 다른 것엔 세금이 잔뜩 붙지만.", "没有王冠,书不收税。不过别的东西税可多了。", "沒有王冠,書不收稅。不過別的東西稅可多了。", "Không vương miện, không thuế sách. Có điều, mọi thứ khác thì thuế đầy ra.", "Tak ada mahkota, tak ada cukai untuk buku. Tapi cukai untuk barang lain sih banyak.", "ไม่มีมงกุฎ ไม่เก็บภาษีหนังสือ แต่ของอย่างอื่นภาษีเพียบ", "Taç yok, kitaba vergi yok. Ama geri kalan her şeye bolca vergi var.", "Sin corona, sin peaje para los libros. Eso sí, peajes de sobra para todo lo demás.", "Sem coroa, sem pedágio sobre livros. Mas pedágio de sobra em todo o resto.", "Ни короны, ни пошлин на книги. Зато на всё остальное пошлин хватает.", "Ні корони, ні мита на книжки. Зате на все інше мита вистачає."],
  "Monsoon wind takes us east in summer and brings us home in winter. You don't sail against it; you wait.": ["夏はモンスーンの風が東へ運び、冬は故郷へ連れ戻してくれる。逆らって船を出すもんじゃない。待つんだ。", "여름엔 몬순 바람이 우릴 동쪽으로 데려가고, 겨울엔 집으로 데려다주지. 거슬러 항해하는 게 아니야. 기다리는 거지.", "季风夏天送我们往东,冬天送我们回家。不能逆着它航行;得等。", "季風夏天送我們往東,冬天送我們回家。不能逆著它航行;得等。", "Gió mùa đưa chúng tôi về đông vào mùa hè và đưa về nhà vào mùa đông. Không ai đi ngược gió; người ta chờ.", "Angin muson membawa kami ke timur di musim panas dan memulangkan kami di musim dingin. Kau tidak berlayar melawannya; kau menunggu.", "ลมมรสุมพาเราไปตะวันออกหน้าร้อน และพากลับบ้านหน้าหนาว ไม่มีใครแล่นเรือทวนลม เขารอกัน", "Muson rüzgârı yazın bizi doğuya götürür, kışın eve getirir. Ona karşı yelken açılmaz; beklenir.", "El viento del monzón nos lleva al este en verano y nos trae a casa en invierno. Contra él no se navega; se espera.", "O vento das monções nos leva para o leste no verão e nos traz para casa no inverno. Não se navega contra ele; espera-se.", "Муссон уносит нас на восток летом и приносит домой зимой. Против него не плавают — его ждут.", "Мусон несе нас на схід улітку й повертає додому взимку. Проти нього не плавають — його чекають."],
  "Seen the far islands, I have. Seen the Mizukai ships too, way off. They don't stop here. Yet.": ["遠くの島々を見たことがあるぜ。ミズカイの船もな、ずっと遠くに。ここには寄らねえ。今のところは。", "먼 섬들도 봤지, 내가. 미즈카이 배들도 봤고, 저 멀리서. 여긴 안 들르더군. 아직은.", "远方的群岛,我见过。水海的船也见过,远远的。它们不在这儿停靠。暂时。", "遠方的群島,我見過。水海的船也見過,遠遠的。它們不在這兒停靠。暫時。", "Đảo xa, tôi thấy rồi. Thấy cả tàu Mizukai nữa, xa tít. Chúng không ghé đây. Chưa thôi.", "Pulau-pulau jauh, sudah kulihat. Kapal-kapal Mizukai juga, jauh di sana. Mereka tidak singgah di sini. Belum.", "เกาะไกล ๆ น่ะข้าเห็นมาแล้ว เรือมิซุไคก็เห็น อยู่ไกลลิบ พวกมันไม่แวะที่นี่ ยังหรอก", "Uzak adaları gördüm ben. Mizukai gemilerini de, çok uzaklarda. Burada durmazlar. Henüz.", "Las islas lejanas, las he visto. Los barcos mizukai también, a lo lejos. Aquí no paran. Todavía.", "As ilhas distantes, já vi. Os navios mizukai também, lá longe. Eles não param aqui. Ainda.", "Далёкие острова — видал я их. И корабли Мидзукай видал, далеко-далеко. Здесь они не останавливаются. Пока.", "Далекі острови — бачив я їх. І кораблі Мідзукай бачив, далеко-далеко. Тут вони не зупиняються. Поки що."],
  "Free port, free city, free advice: don't argue with a librarian.": ["自由港、自由都市、無料の忠告:司書とは言い争うな。", "자유항, 자유 도시, 공짜 충고: 사서랑은 말다툼하지 마.", "自由港,自由城,免费的忠告:别跟图书管理员争论。", "自由港,自由城,免費的忠告:別跟圖書館員爭論。", "Cảng tự do, thành phố tự do, lời khuyên miễn phí: đừng cãi nhau với thủ thư.", "Pelabuhan bebas, kota bebas, nasihat gratis: jangan berdebat dengan pustakawan.", "ท่าเรือเสรี เมืองเสรี คำแนะนำฟรี: อย่าเถียงกับบรรณารักษ์", "Serbest liman, serbest şehir, bedava öğüt: kütüphaneciyle tartışma.", "Puerto libre, ciudad libre, consejo gratis: no discutas con un bibliotecario.", "Porto livre, cidade livre, conselho grátis: não discuta com um bibliotecário.", "Вольный порт, вольный город, бесплатный совет: не спорь с библиотекарем.", "Вільний порт, вільне місто, безкоштовна порада: не сперечайся з бібліотекарем."],
  "The Provost walks to the Hall every morning. Anyone can stop her and complain. Most people do.": ["学頭さまは毎朝、議事堂まで歩いて行かれる。誰でも呼び止めて文句を言っていい。たいていの人がそうする。", "학장님은 매일 아침 회관까지 걸어가세요. 누구든 붙잡고 불평할 수 있죠. 대부분 그렇게 해요.", "院长每天早上步行去议事厅。谁都可以拦住她抱怨。大多数人也确实这么做。", "院長每天早上步行去議事廳。誰都可以攔住她抱怨。大多數人也確實這麼做。", "Viện trưởng đi bộ tới Hội trường mỗi sáng. Ai cũng có thể chặn bà lại mà phàn nàn. Phần lớn mọi người đều làm thế.", "Provos berjalan kaki ke Balai setiap pagi. Siapa pun boleh mencegatnya dan mengeluh. Kebanyakan orang memang begitu.", "อธิการเดินไปที่หอประชุมทุกเช้า ใครจะหยุดท่านแล้วบ่นก็ได้ คนส่วนใหญ่ก็ทำอย่างนั้น", "Rektör her sabah Salon'a yürüyerek gider. Herkes onu durdurup şikâyet edebilir. Çoğu kişi de eder.", "La prebostesa va andando a la Sala cada mañana. Cualquiera puede pararla y quejarse. Casi todos lo hacen.", "A reitora vai a pé até o Salão toda manhã. Qualquer um pode pará-la e reclamar. A maioria reclama.", "Провост каждое утро ходит в Палату пешком. Любой может остановить её и пожаловаться. Большинство так и делает.", "Провост щоранку ходить до Палати пішки. Будь-хто може зупинити її й поскаржитися. Більшість так і робить."],
  "Ink in one hand, coin in the other. That's the Assembly, and that's Suvarnatira.": ["片手に墨、もう片手に貨幣。それが議会で、それがスヴァルナティーラだ。", "한 손엔 먹, 다른 손엔 주화. 그게 의회고, 그게 수바르나티라지.", "一手拿墨,一手拿钱。这就是议会,这就是苏瓦尔纳蒂拉。", "一手拿墨,一手拿錢。這就是議會,這就是蘇瓦爾納蒂拉。", "Một tay cầm mực, tay kia cầm xu. Đó là Hội đồng, và đó là Suvarnatira.", "Tinta di satu tangan, koin di tangan lain. Itulah Majelis, dan itulah Suvarnatira.", "มือหนึ่งถือหมึก อีกมือถือเหรียญ นั่นแหละสภา และนั่นแหละสุวรรณตีระ", "Bir elde mürekkep, öbüründe sikke. İşte Meclis bu, işte Suvarnatira bu.", "Tinta en una mano, moneda en la otra. Así es la Asamblea, y así es Suvarnatira.", "Tinta numa mão, moeda na outra. Essa é a Assembleia, e essa é Suvarnatira.", "В одной руке чернила, в другой — монета. Таково Собрание, такова и Суварнатира.", "В одній руці чорнило, в другій — монета. Такі Збори, така й Суварнатіра."],
  "Three kingdoms have sent people to count us. We gave them tea, and they went home, and they're still counting.": ["三つの王国が、わしらを数えに人を寄越した。茶を出してやったら帰っていった。今でもまだ数えておる。", "세 왕국이 우리를 세려고 사람을 보냈지. 차를 대접했더니 돌아들 갔는데, 아직도 세고 있어.", "三个王国都派人来清点过我们。我们请他们喝了茶,他们就回家了,到现在还在数。", "三個王國都派人來清點過我們。我們請他們喝了茶,他們就回家了,到現在還在數。", "Ba vương quốc đã phái người tới đếm chúng tôi. Chúng tôi mời họ trà, rồi họ về nhà, và đến giờ vẫn còn đang đếm.", "Tiga kerajaan sudah mengirim orang untuk menghitung kami. Kami suguhi mereka teh, lalu mereka pulang, dan sampai sekarang masih menghitung.", "สามอาณาจักรส่งคนมานับพวกเรา เราเลี้ยงน้ำชาพวกเขา แล้วพวกเขาก็กลับบ้าน ป่านนี้ยังนับไม่เสร็จ", "Üç krallık bizi saymaya adam yolladı. Onlara çay verdik, evlerine döndüler, hâlâ sayıyorlar.", "Tres reinos han mandado gente a contarnos. Les dimos té, se fueron a casa y todavía siguen contando.", "Três reinos mandaram gente para nos contar. Demos chá a eles, eles voltaram para casa e ainda estão contando.", "Три королевства присылали людей нас пересчитать. Мы напоили их чаем, они ушли домой и до сих пор считают.", "Три королівства присилали людей нас перелічити. Ми почастували їх чаєм, вони пішли додому й досі лічать."],
  "The loggers come further in every year with Shailagarh's stamp on their axes. The forest doesn't belong to Shailagarh. It doesn't belong to us, either; we belong to it.": ["木こりどもは毎年、シャイラガルの刻印を斧につけて、さらに奥まで入ってくる。森はシャイラガルのものではない。わしらのものでもない。わしらが森のものなのだ。", "벌목꾼들이 해마다 도끼에 샤일라가르의 낙인을 찍고 더 깊이 들어와. 숲은 샤일라가르의 것이 아니야. 우리 것도 아니고. 우리가 숲의 것이지.", "伐木工每年都往里深入一些,斧头上刻着沙伊拉加尔的印记。森林不属于沙伊拉加尔。也不属于我们;是我们属于森林。", "伐木工每年都往裡深入一些,斧頭上刻著沙伊拉加爾的印記。森林不屬於沙伊拉加爾。也不屬於我們;是我們屬於森林。", "Mỗi năm bọn thợ đốn gỗ lại vào sâu hơn, rìu mang dấu ấn của Shailagarh. Khu rừng không thuộc về Shailagarh. Cũng chẳng thuộc về chúng tôi; chúng tôi thuộc về nó.", "Para penebang masuk makin dalam setiap tahun dengan cap Shailagarh di kapak mereka. Hutan ini bukan milik Shailagarh. Bukan milik kami juga; kamilah milik hutan.", "พวกคนตัดไม้รุกเข้ามาลึกขึ้นทุกปี บนขวานมีตราของไศลครห์ ป่าไม่ใช่ของไศลครห์ และก็ไม่ใช่ของเราด้วย เราต่างหากที่เป็นของป่า", "Oduncular her yıl baltalarında Shailagarh'ın damgasıyla biraz daha içeri giriyor. Orman Shailagarh'ın değil. Bizim de değil; biz onunuz.", "Los leñadores entran más cada año, con el sello de Shailagarh en las hachas. El bosque no es de Shailagarh. Tampoco es nuestro; nosotros somos suyos.", "Os lenhadores entram mais fundo a cada ano, com o selo de Shailagarh nos machados. A floresta não pertence a Shailagarh. Também não pertence a nós; nós é que pertencemos a ela.", "Лесорубы с каждым годом заходят всё дальше, с клеймом Шайлагарха на топорах. Лес не принадлежит Шайлагарху. И нам не принадлежит: это мы принадлежим ему.", "Лісоруби щороку заходять усе далі, з тавром Шайлагарха на сокирах. Ліс не належить Шайлагарху. І нам не належить: це ми належимо йому."],
  "Ilavarta wants us as a province, the League as an eighth parasol. A parasol is for keeping the sky off. We like the sky.": ["イラヴァルタはわしらを属州にしたがり、同盟は八つ目の日傘にしたがる。日傘とは空を遮るためのもの。わしらは空が好きなのだ。", "일라바르타는 우릴 속주로, 동맹은 여덟 번째 일산으로 삼고 싶어 해. 일산이란 하늘을 가리는 물건이지. 우린 하늘이 좋아.", "伊拉瓦塔想让我们做一个行省,同盟想让我们做第八顶华盖。华盖是用来挡住天空的。我们喜欢天空。", "伊拉瓦塔想讓我們做一個行省,同盟想讓我們做第八頂華蓋。華蓋是用來擋住天空的。我們喜歡天空。", "Ilavarta muốn chúng tôi làm một tỉnh, Liên minh muốn chúng tôi làm chiếc lọng thứ tám. Lọng là để che trời. Chúng tôi thích trời.", "Ilavarta ingin kami jadi provinsi, Liga ingin kami jadi payung kedelapan. Payung itu untuk menghalangi langit. Kami suka langit.", "อิลาวรรตะอยากให้เราเป็นแคว้นหนึ่ง สันนิบาตอยากให้เราเป็นฉัตรที่แปด ฉัตรมีไว้บังฟ้า เราชอบฟ้า", "Ilavarta bizi bir eyalet olarak istiyor, Birlik sekizinci bir şemsiye olarak. Şemsiye gökyüzünü uzak tutmak içindir. Biz gökyüzünü severiz.", "Ilavarta nos quiere como provincia; la Liga, como octavo parasol. Un parasol sirve para taparse el cielo. A nosotros nos gusta el cielo.", "Ilavarta nos quer como província; a Liga, como oitavo para-sol. Um para-sol serve para tapar o céu. Nós gostamos do céu.", "Илаварта хочет сделать нас провинцией, Лига — восьмым зонтом. Зонт нужен, чтобы заслоняться от неба. А мы небо любим.", "Ілаварта хоче зробити нас провінцією, Ліга — восьмим парасолем. Парасоль — щоб затуляти небо. А ми небо любимо."],
  "Bark-cloth, bamboo, beads. The river's low, so I'll take rice and salt for them. In the wet months I'll take nothing; nothing gets here.": ["樹皮布、竹、ビーズ。川の水が少ないから、米と塩と交換してあげる。雨の季節には何ももらわない。何もここまで届かないから。", "나무껍질 천, 대나무, 구슬. 강물이 낮으니 쌀이랑 소금으로 바꿔 줄게. 우기엔 아무것도 안 받아. 아무것도 여기까지 못 오거든.", "树皮布、竹子、珠子。河水低,我就收大米和盐来换。到了雨季我什么都不收;什么都运不到这儿。", "樹皮布、竹子、珠子。河水低,我就收米和鹽來換。到了雨季我什麼都不收;什麼都運不到這兒。", "Vải vỏ cây, tre, hạt cườm. Nước sông đang cạn, nên tôi sẽ đổi lấy gạo và muối. Vào những tháng mưa tôi chẳng lấy gì cả; có gì tới được đây đâu.", "Kain kulit kayu, bambu, manik-manik. Sungai sedang surut, jadi aku terima beras dan garam sebagai gantinya. Di bulan-bulan basah aku tak terima apa-apa; tak ada yang bisa sampai ke sini.", "ผ้าเปลือกไม้ ไม้ไผ่ ลูกปัด แม่น้ำลดแล้ว ฉันเลยรับข้าวกับเกลือแลก ช่วงหน้าฝนฉันไม่รับอะไรเลย เพราะไม่มีอะไรมาถึงที่นี่ได้", "Ağaç kabuğu bezi, bambu, boncuk. Nehir alçak, o yüzden karşılığında pirinç ve tuz alırım. Yağmurlu aylarda hiçbir şey almam; buraya hiçbir şey ulaşmaz.", "Tela de corteza, bambú, cuentas. El río va bajo, así que acepto arroz y sal a cambio. En los meses de lluvia no acepto nada; aquí no llega nada.", "Pano de casca, bambu, contas. O rio está baixo, então aceito arroz e sal em troca. Nos meses de chuva não aceito nada; nada chega aqui.", "Ткань из коры, бамбук, бусы. Река обмелела, так что возьму за них рис и соль. В дождливые месяцы не возьму ничего: сюда ничего не доходит.", "Тканина з кори, бамбук, намисто. Річка обміліла, тож візьму за них рис і сіль. У дощові місяці не візьму нічого: сюди нічого не доходить."],
  "You walk like a cart. The tiger heard you an hour ago. Lucky for you it's not hungry.": ["荷車みたいな歩き方だね。虎は一時間前からあんたに気づいてたよ。腹が減ってなくてよかったね。", "수레처럼 걷는군. 호랑이는 한 시간 전에 벌써 네 소리를 들었어. 배가 안 고파서 다행인 줄 알아.", "你走路像辆牛车。老虎一个钟头前就听见你了。算你走运,它不饿。", "你走路像輛牛車。老虎一個鐘頭前就聽見你了。算你走運,牠不餓。", "Bạn đi như cái xe bò. Con hổ nghe thấy bạn từ một tiếng trước rồi. May cho bạn là nó không đói.", "Jalanmu seperti gerobak. Harimau sudah mendengarmu sejam lalu. Untung bagimu ia sedang tidak lapar.", "เดินเสียงดังยังกับเกวียน เสือได้ยินเจ้าตั้งแต่ชั่วโมงก่อนแล้ว โชคดีที่มันไม่หิว", "Araba gibi yürüyorsun. Kaplan seni bir saat önce duydu. Şansına aç değil.", "Caminas como una carreta. El tigre te oyó hace una hora. Por suerte para ti, no tiene hambre.", "Você anda feito uma carroça. O tigre te ouviu há uma hora. Sorte sua que ele não está com fome.", "Ходишь, как телега. Тигр услышал тебя час назад. Твоё счастье, что он не голоден.", "Ходиш, як віз. Тигр почув тебе годину тому. Твоє щастя, що він не голодний."],
  "Don't take more than you need from the forest. It counts, and it remembers.": ["森から必要以上のものを取るな。森は数えているし、覚えている。", "숲에서 필요한 것보다 더 가져가지 마. 숲은 세고, 기억하니까.", "别从森林里拿超出你需要的东西。它会数,也会记得。", "別從森林裡拿超出你需要的東西。它會數,也會記得。", "Đừng lấy của rừng nhiều hơn bạn cần. Rừng đếm, và rừng nhớ.", "Jangan ambil dari hutan lebih dari yang kau perlukan. Hutan menghitung, dan hutan ingat.", "อย่าเอาจากป่าเกินกว่าที่จำเป็น ป่านับ และป่าจำ", "Ormandan ihtiyacından fazlasını alma. Orman sayar ve unutmaz.", "No tomes del bosque más de lo que necesitas. El bosque cuenta, y recuerda.", "Não tire da floresta mais do que precisa. Ela conta, e ela lembra.", "Не бери у леса больше, чем нужно. Лес считает и помнит.", "Не бери в лісу більше, ніж треба. Ліс рахує і пам'ятає."],
  "Ask before you cut anything here. Even a leaf. Especially a leaf.": ["ここで何か切る前には、断りを入れな。葉っぱ一枚でもだ。葉っぱなら、なおさらだ。", "여기서 뭘 자르기 전엔 먼저 물어봐. 잎사귀 하나라도. 잎사귀라면 더더욱.", "在这儿砍任何东西之前,先问一声。哪怕一片叶子。尤其是一片叶子。", "在這兒砍任何東西之前,先問一聲。哪怕一片葉子。尤其是一片葉子。", "Hỏi trước khi chặt bất cứ thứ gì ở đây. Kể cả một chiếc lá. Nhất là một chiếc lá.", "Minta izin dulu sebelum memotong apa pun di sini. Bahkan sehelai daun. Apalagi sehelai daun.", "จะตัดอะไรที่นี่ ขออนุญาตก่อน แม้แต่ใบไม้ใบเดียว โดยเฉพาะใบไม้ใบเดียว", "Burada bir şey kesmeden önce izin iste. Bir yaprak bile olsa. Hele bir yapraksa.", "Pide permiso antes de cortar nada aquí. Aunque sea una hoja. Sobre todo si es una hoja.", "Peça antes de cortar qualquer coisa aqui. Mesmo uma folha. Principalmente uma folha.", "Прежде чем что-то здесь срезать, спроси. Даже листок. Особенно листок.", "Перш ніж щось тут зрізати, спитай. Навіть листок. Особливо листок."],
  "The houses stand on stilts because the river comes up every monsoon. We don't fight the river. We step back.": ["家が高床なのは、毎年モンスーンで川があふれるから。わたしたちは川と戦わない。一歩下がるの。", "집들이 기둥 위에 서 있는 건 몬순 때마다 강물이 불어서야. 우린 강과 싸우지 않아. 한 걸음 물러서지.", "房子都建在高脚上,因为每到季风河水就会涨。我们不跟河斗。我们往后退。", "房子都建在高腳上,因為每到季風河水就會漲。我們不跟河鬥。我們往後退。", "Nhà dựng trên cột vì mùa mưa nào nước sông cũng dâng. Chúng tôi không chống lại dòng sông. Chúng tôi lùi lại.", "Rumah-rumah berdiri di atas tiang karena sungai naik setiap musim hujan. Kami tidak melawan sungai. Kami mundur.", "บ้านยกใต้ถุนสูงเพราะแม่น้ำขึ้นทุกฤดูมรสุม เราไม่สู้กับแม่น้ำ เราถอยออกมา", "Evler kazıklar üstünde duruyor, çünkü nehir her musonda yükselir. Nehirle savaşmayız. Geri çekiliriz.", "Las casas se alzan sobre pilotes porque el río crece cada monzón. No luchamos contra el río. Nos apartamos.", "As casas ficam sobre palafitas porque o rio sobe a cada monção. Não brigamos com o rio. Recuamos.", "Дома стоят на сваях, потому что река поднимается каждый муссон. Мы не боремся с рекой. Мы отступаем.", "Хати стоять на палях, бо річка піднімається щомусону. Ми не боремося з річкою. Ми відступаємо."],
  "Grandmother Sukesh decides. Grandmother has decided most things since before my mother was born.": ["決めるのはスケシュ婆さま。婆さまは、わたしの母が生まれる前からたいていのことを決めてきたの。", "수케시 할머니가 정하셔. 할머니는 우리 엄마가 태어나기 전부터 웬만한 건 다 정해 오셨지.", "苏凯什奶奶说了算。从我母亲出生以前,大多数事就是奶奶拿主意。", "蘇凱什奶奶說了算。從我母親出生以前,大多數事就是奶奶拿主意。", "Bà Sukesh quyết định. Bà đã quyết định hầu hết mọi chuyện từ trước khi mẹ tôi ra đời.", "Nenek Sukesh yang memutuskan. Nenek sudah memutuskan hampir segala hal sejak sebelum ibuku lahir.", "ยายสุเกศเป็นคนตัดสิน ยายตัดสินเรื่องส่วนใหญ่มาตั้งแต่ก่อนแม่ฉันเกิดเสียอีก", "Sukesh Nine karar verir. Nine, annem doğmadan önce de çoğu şeye o karar veriyordu.", "Decide la abuela Sukesh. La abuela lleva decidiendo casi todo desde antes de que naciera mi madre.", "Quem decide é a avó Sukesh. A avó decide quase tudo desde antes de minha mãe nascer.", "Решает бабушка Сукеш. Бабушка решала почти всё ещё до рождения моей матери.", "Вирішує бабуся Сукеш. Бабуся вирішувала майже все ще до народження моєї матері."],
  "We've a licence from Shailagarh. The Kanthari say Shailagarh can't licence what isn't its own. We just fell the trees.": ["シャイラガルの許可証はある。カンタリは、シャイラガルが自分のものでないものに許可は出せないと言う。俺たちは木を切るだけだ。", "우린 샤일라가르의 허가를 받았어. 칸타리족은 샤일라가르가 제 것도 아닌 걸 허가할 순 없다고 하지. 우린 그냥 나무를 벨 뿐이야.", "我们有沙伊拉加尔的许可。坎塔里人说,沙伊拉加尔不能许可不属于它的东西。我们只管砍树。", "我們有沙伊拉加爾的許可。坎塔里人說,沙伊拉加爾不能許可不屬於它的東西。我們只管砍樹。", "Chúng tôi có giấy phép của Shailagarh. Người Kanthari nói Shailagarh không thể cấp phép cho thứ không phải của mình. Chúng tôi chỉ đốn cây thôi.", "Kami punya izin dari Shailagarh. Orang Kanthari bilang Shailagarh tak bisa memberi izin atas yang bukan miliknya. Kami cuma menebang pohon.", "เรามีใบอนุญาตจากไศลครห์ ชาวกันถารีบอกว่าไศลครห์ออกใบอนุญาตให้สิ่งที่ไม่ใช่ของตัวเองไม่ได้ เราแค่โค่นต้นไม้", "Shailagarh'tan iznimiz var. Kanthariler, Shailagarh'ın kendisine ait olmayan şeye izin veremeyeceğini söylüyor. Biz sadece ağaç keseriz.", "Tenemos licencia de Shailagarh. Los kanthari dicen que Shailagarh no puede dar licencia sobre lo que no es suyo. Nosotros solo talamos los árboles.", "Temos licença de Shailagarh. Os kanthari dizem que Shailagarh não pode licenciar o que não é dele. Nós só derrubamos as árvores.", "У нас лицензия от Шайлагарха. Кантхари говорят, что Шайлагарх не может выдавать лицензии на то, что ему не принадлежит. Мы просто валим деревья.", "У нас ліцензія від Шайлагарха. Кантхарі кажуть, що Шайлагарх не може видавати ліцензії на те, що йому не належить. Ми просто валимо дерева."],
  "Pit props, for the mines. No props, no mines, no blackiron, no sabres. Everybody wants the sabres.": ["坑木だ、鉱山用の。坑木がなきゃ鉱山はない。鉱山がなきゃブラックアイアンはない。ブラックアイアンがなきゃサーベルはない。サーベルは誰だって欲しがる。", "갱목이야, 광산용. 갱목이 없으면 광산도 없고, 흑철도 없고, 사브르도 없지. 사브르는 다들 원하잖아.", "坑木,给矿井用的。没有坑木就没有矿,没有矿就没有黑铁,没有黑铁就没有军刀。人人都想要军刀。", "坑木,給礦坑用的。沒有坑木就沒有礦,沒有礦就沒有黑鐵,沒有黑鐵就沒有軍刀。人人都想要軍刀。", "Cột chống lò, cho hầm mỏ. Không cột chống thì không có mỏ, không sắt đen, không kiếm cong. Ai cũng muốn kiếm cong.", "Tiang penyangga, untuk tambang. Tanpa penyangga, tak ada tambang, tak ada besi hitam, tak ada pedang lengkung. Semua orang mau pedang lengkung.", "ไม้ค้ำยันสำหรับเหมือง ไม่มีไม้ค้ำก็ไม่มีเหมือง ไม่มีเหล็กดำ ไม่มีดาบโค้ง ใคร ๆ ก็อยากได้ดาบโค้ง", "Maden direkleri, ocaklar için. Direk yoksa maden yok, kara demir yok, kılıç yok. Herkes kılıç ister.", "Puntales, para las minas. Sin puntales no hay minas, ni hierro negro, ni sables. Y todo el mundo quiere sables.", "Escoras, para as minas. Sem escoras, sem minas, sem ferro negro, sem sabres. Todo mundo quer os sabres.", "Крепёжный лес, для шахт. Нет крепи — нет шахт, нет чёрного железа, нет сабель. А сабли хотят все.", "Кріпильний ліс, для шахт. Нема кріплення — нема шахт, нема чорного заліза, нема шабель. А шаблі хочуть усі."],
  "Cut in two scripts, Meghavan's and Kharaveth's: 'Here the rain begins. Whoever passes under the clouds is a guest of the rain; whoever does harm under them is the rain's enemy.' Under it, newer and smaller: 'Tolls payable at Tirthali or Sarovan, by order of the Keeper of the Tanks.'": ["メガヴァンとカラヴェス、二つの文字で刻まれている。「ここより雨始まる。雲の下を通る者は雨の客なり。雲の下で害をなす者は雨の敵なり。」その下に、新しく小さな字で。「通行税はティルタリまたはサロヴァンにて納付のこと。貯水池の守り手の命による。」", "메가반 문자와 카라베스 문자, 두 가지로 새겨져 있다. '여기서 비가 시작된다. 구름 아래를 지나는 자는 비의 손님이요, 그 아래에서 해를 끼치는 자는 비의 적이다.' 그 아래에, 더 새롭고 작은 글씨로: '통행세는 티르탈리 또는 사로반에서 납부할 것. 저수지의 수호자의 명에 따라.'", "用两种文字刻成,梅加万文和卡拉维斯文:“雨自此始。行于云下者,为雨之客;于云下行恶者,为雨之敌。”其下,字迹较新也较小:“通行税请于提尔塔利或萨罗万缴纳,奉水池守护者之令。”", "用兩種文字刻成,梅加萬文和卡拉維斯文:「雨自此始。行於雲下者,為雨之客;於雲下行惡者,為雨之敵。」其下,字跡較新也較小:「通行稅請於提爾塔利或薩羅萬繳納,奉水池守護者之令。」", "Khắc bằng hai thứ chữ, của Meghavan và của Kharaveth: “Mưa bắt đầu từ đây. Ai đi qua dưới mây là khách của mưa; ai gây hại dưới mây là kẻ thù của mưa.” Bên dưới, mới hơn và nhỏ hơn: “Thuế đường nộp tại Tirthali hoặc Sarovan, theo lệnh Người Giữ Hồ.”", "Dipahat dalam dua aksara, aksara Meghavan dan Kharaveth: “Di sinilah hujan bermula. Siapa pun yang lewat di bawah awan adalah tamu hujan; siapa pun yang berbuat jahat di bawahnya adalah musuh hujan.” Di bawahnya, lebih baru dan lebih kecil: “Cukai dibayar di Tirthali atau Sarovan, atas perintah Penjaga Telaga.”", "จารึกด้วยอักษรสองแบบ ของเมฆาวันและของคาราเวธ: “ฝนเริ่มต้น ณ ที่นี้ ผู้ใดผ่านใต้เมฆ ผู้นั้นเป็นแขกของฝน ผู้ใดก่อร้ายใต้เมฆ ผู้นั้นเป็นศัตรูของฝน” ใต้ลงมา ตัวอักษรใหม่กว่าและเล็กกว่า: “ชำระค่าผ่านทางที่ตีรถลีหรือสโรวัน ตามคำสั่งผู้รักษาสระ”", "İki yazıyla kazınmış, Meghavan'ınki ve Kharaveth'inki: “Yağmur burada başlar. Bulutların altından geçen, yağmurun misafiridir; altlarında kötülük eden, yağmurun düşmanıdır.” Altında, daha yeni ve daha küçük: “Geçiş vergisi, Havuzların Bekçisi'nin emriyle Tirthali'de ya da Sarovan'da ödenir.”", "Grabado en dos escrituras, la de Meghavan y la de Kharaveth: «Aquí empieza la lluvia. Quien pasa bajo las nubes es huésped de la lluvia; quien hace daño bajo ellas es enemigo de la lluvia». Debajo, más nuevo y más pequeño: «Peajes pagaderos en Tirthali o Sarovan, por orden de la Guardiana de los Estanques».", "Gravado em duas escritas, a de Meghavan e a de Kharaveth: “Aqui começa a chuva. Quem passa sob as nuvens é hóspede da chuva; quem faz mal sob elas é inimigo da chuva.” Abaixo, mais novo e menor: “Pedágios a pagar em Tirthali ou Sarovan, por ordem da Guardiã dos Tanques.”", "Высечено двумя письменами, Мегхавана и Харавета: «Здесь начинается дождь. Кто проходит под облаками — гость дождя; кто творит под ними зло — враг дождя». Ниже, новее и мельче: «Пошлины уплачиваются в Тиртхали или Сароване, по приказу Хранительницы прудов».", "Вирізьблено двома письмами, Мегхавана й Харавета: «Тут починається дощ. Хто проходить під хмарами — гість дощу; хто чинить під ними зло — ворог дощу». Нижче, новіше й дрібніше: «Мито сплачується в Тіртхалі або Саровані, за наказом Хранительки ставів»."],
  "A bronze plaque set in the gateway's south pillar, green with weather.": ["門の南の柱にはめ込まれた青銅の銘板。風雨にさらされて緑青をふいている。", "문의 남쪽 기둥에 박힌 청동 명판. 비바람에 푸르게 녹이 슬었다.", "嵌在门道南柱上的一块铜牌,经风历雨,已泛出铜绿。", "嵌在門道南柱上的一塊銅牌,經風歷雨,已泛出銅綠。", "Một tấm biển đồng gắn vào cột phía nam của cổng, xanh rỉ vì mưa nắng.", "Sebuah plakat perunggu terpasang di pilar selatan gerbang, menghijau dimakan cuaca.", "แผ่นจารึกสำริดฝังอยู่ที่เสาด้านใต้ของประตู เขียวคร่ำเพราะแดดฝน", "Kapının güney sütununa gömülü, havadan yeşillenmiş bir tunç levha.", "Una placa de bronce empotrada en el pilar sur de la puerta, verde por la intemperie.", "Uma placa de bronze fixada no pilar sul do portal, verde de tanto tempo ao relento.", "Бронзовая табличка, вделанная в южный столб ворот, позеленевшая от непогоды.", "Бронзова табличка, вмурована в південний стовп брами, позеленіла від негоди."],
  "A stone post marked in the Queen's hands of depth, the old marks cut deep and gilded, the water's line now three marks below the lowest gilt. Someone has scratched beside it, small: 'Silt, or sorrow?'": ["女王の「手」の単位で深さを刻んだ石柱。古い目盛りは深く刻まれ金箔が施されているが、今の水位は最も低い金の目盛りより三つも下だ。その脇に誰かが小さく引っかいて書いている。「泥か、悲しみか?」", "여왕의 '손' 단위로 깊이를 새긴 돌기둥. 옛 눈금은 깊이 파이고 금박이 입혀져 있지만, 지금 수위는 가장 낮은 금빛 눈금보다 세 칸이나 아래다. 그 옆에 누군가 작게 긁어 놓았다: '진흙 탓인가, 슬픔 탓인가?'", "一根石柱,按女王的“掌”刻着水深。旧刻度刻得很深,还描了金,如今水线却在最低那道金线下方三格。旁边有人小小地刻了一句:“是淤泥,还是哀愁?”", "一根石柱,按女王的「掌」刻著水深。舊刻度刻得很深,還描了金,如今水線卻在最低那道金線下方三格。旁邊有人小小地刻了一句:「是淤泥,還是哀愁?」", "Một cột đá khắc độ sâu theo đơn vị “bàn tay” của Nữ hoàng, các vạch cũ khắc sâu và mạ vàng, mực nước giờ thấp hơn vạch mạ vàng thấp nhất ba vạch. Ai đó đã cào bên cạnh, chữ nhỏ: “Phù sa, hay sầu muộn?”", "Sebuah tiang batu bertanda kedalaman dalam satuan “tangan” Ratu, tanda-tanda lamanya dipahat dalam dan disepuh emas, garis airnya kini tiga tanda di bawah sepuhan terendah. Seseorang telah menggores kecil di sampingnya: “Lumpur, atau duka?”", "เสาหินบอกความลึกเป็นหน่วย “ฝ่ามือ” ของราชินี ขีดเก่าสลักลึกและปิดทอง แนวน้ำตอนนี้อยู่ต่ำกว่าขีดปิดทองที่ต่ำที่สุดถึงสามขีด มีคนขีดเขียนตัวเล็ก ๆ ไว้ข้าง ๆ: “ตะกอน หรือความโศก?”", "Kraliçe'nin “avuç” ölçüsüyle derinlik işaretlenmiş taş bir direk; eski işaretler derin oyulmuş ve yaldızlanmış, suyun çizgisi şimdi en alttaki yaldızın üç işaret altında. Biri yanına küçük harflerle kazımış: “Balçık mı, keder mi?”", "Un poste de piedra marcado en las manos de profundidad de la Reina; las marcas antiguas, talladas hondas y doradas; la línea del agua, ahora tres marcas por debajo del dorado más bajo. Alguien ha rayado al lado, en pequeño: «¿Cieno, o pena?»", "Um poste de pedra marcado nos palmos de profundidade da Rainha, as marcas antigas talhadas fundo e douradas, a linha d'água agora três marcas abaixo do dourado mais baixo. Alguém riscou ao lado, pequeno: “Lodo, ou mágoa?”", "Каменный столб с отметками глубины в королевских «ладонях»: старые отметки высечены глубоко и позолочены, а уровень воды теперь на три отметки ниже самой нижней позолоты. Рядом кто-то мелко нацарапал: «Ил или горе?»", "Кам'яний стовп із позначками глибини в королівських «долонях»: старі позначки вирізано глибоко й позолочено, а рівень води тепер на три позначки нижче за найнижчу позолоту. Поруч хтось дрібно надряпав: «Мул чи журба?»"],
  "The Great Tank's measure: a carved post at the top of the ghats.": ["大貯水池の水位標。ガートの上に立つ、彫刻の施された柱。", "대저수지의 수위표. 가트 꼭대기에 선 조각 기둥.", "大水池的水尺:河阶顶端一根雕花石柱。", "大水池的水尺:河階頂端一根雕花石柱。", "Thước đo của Hồ Lớn: một cột chạm khắc trên đỉnh bậc ghat.", "Pengukur Telaga Agung: sebuah tiang berukir di puncak tangga ghat.", "เครื่องวัดระดับน้ำของสระใหญ่: เสาแกะสลักบนยอดท่าน้ำ", "Büyük Havuz'un ölçeği: gat basamaklarının tepesinde oymalı bir direk.", "La medida del Gran Estanque: un poste tallado en lo alto de los ghats.", "A medida do Grande Tanque: um poste entalhado no alto dos ghats.", "Мерило Великого пруда: резной столб наверху гатов.", "Мірило Великого ставу: різьблений стовп на верху гатів."],
  "Steps go down four sides of a square shaft, landing after landing, galleries of carved pillars along each, to green water far below. A chain is across the lowest landing you can see, and a brass notice: 'Closed by order of the Chief Engineer. Silt. Do not descend.'": ["四角い竪穴の四方を階段が下っていく。踊り場また踊り場、それぞれに彫刻の柱が並ぶ回廊があり、はるか下には緑の水。見える限り最も低い踊り場には鎖が渡され、真鍮の掲示がある。「主任技師の命により閉鎖。沈泥のため。降りるべからず。」", "네모난 수직갱의 네 면을 따라 계단이 내려간다. 층계참 다음 또 층계참, 그마다 조각 기둥이 늘어선 회랑이 있고, 저 아래에는 초록빛 물이 있다. 보이는 가장 낮은 층계참에는 쇠사슬이 가로질러 있고, 놋쇠 안내판이 붙어 있다: '수석 기술자의 명으로 폐쇄. 토사. 내려가지 마시오.'", "台阶沿着方形竖井的四壁向下延伸,一层平台接一层平台,每层都有一排雕花石柱的回廊,一直通到远在下方的绿水。目力所及最低的那层平台上横着一条铁链,挂着一块铜牌:“奉总工程师之令封闭。淤泥。请勿下行。”", "台階沿著方形豎井的四壁向下延伸,一層平台接一層平台,每層都有一排雕花石柱的迴廊,一直通到遠在下方的綠水。目力所及最低的那層平台上橫著一條鐵鍊,掛著一塊銅牌:「奉總工程師之令封閉。淤泥。請勿下行。」", "Những bậc thang đi xuống bốn mặt của một giếng vuông, hết chiếu nghỉ này đến chiếu nghỉ khác, mỗi tầng có hành lang cột chạm khắc, xuống tận mặt nước xanh tít bên dưới. Một sợi xích chắn ngang chiếu nghỉ thấp nhất bạn nhìn thấy được, cùng một tấm biển đồng thau: “Đóng cửa theo lệnh Kỹ sư trưởng. Phù sa. Không được xuống.”", "Anak tangga menurun di keempat sisi sebuah sumur persegi, bordes demi bordes, dengan serambi pilar berukir di sepanjang tiap tingkat, sampai ke air hijau jauh di bawah. Seutas rantai melintang di bordes terendah yang bisa kau lihat, dengan papan kuningan: “Ditutup atas perintah Kepala Insinyur. Lumpur. Dilarang turun.”", "ขั้นบันไดทอดลงไปทั้งสี่ด้านของบ่อสี่เหลี่ยม ชานพักแล้วชานพักเล่า แต่ละชั้นมีระเบียงเสาแกะสลักเรียงราย ลงไปจนถึงผืนน้ำสีเขียวไกลลิบเบื้องล่าง ชานพักที่ต่ำที่สุดเท่าที่มองเห็นมีโซ่ขึงขวางไว้ พร้อมป้ายทองเหลือง: “ปิดตามคำสั่งหัวหน้าวิศวกร ตะกอน ห้ามลง”", "Kare bir kuyunun dört yanından basamaklar iniyor, sahanlık üstüne sahanlık, her birinde oymalı sütunlu revaklar, ta aşağıdaki yeşil suya kadar. Görebildiğin en alt sahanlığa bir zincir gerilmiş, bir de pirinç levha asılmış: “Baş Mühendis'in emriyle kapalıdır. Balçık. İnmeyiniz.”", "Los escalones bajan por los cuatro lados de un pozo cuadrado, rellano tras rellano, cada uno con galerías de pilares tallados, hasta el agua verde muy abajo. Una cadena cruza el rellano más bajo que alcanzas a ver, con un aviso de latón: «Cerrado por orden del ingeniero jefe. Cieno. No descender».", "Degraus descem pelos quatro lados de um poço quadrado, patamar após patamar, cada um com galerias de pilares entalhados, até a água verde lá embaixo. Uma corrente atravessa o patamar mais baixo que se pode ver, com um aviso de latão: “Fechado por ordem do engenheiro-chefe. Lodo. Não desça.”", "Ступени спускаются по четырём сторонам квадратной шахты, площадка за площадкой, вдоль каждой — галереи резных колонн, до зелёной воды далеко внизу. Поперёк самой нижней видимой площадки натянута цепь и висит латунная табличка: «Закрыто по приказу главного инженера. Ил. Не спускаться».", "Сходи спускаються чотирма боками квадратної шахти, майданчик за майданчиком, уздовж кожного — галереї різьблених колон, до зеленої води далеко внизу. Поперек найнижчого видимого майданчика натягнуто ланцюг і висить латунна табличка: «Зачинено за наказом головного інженера. Мул. Не спускатися»."],
  "The Great Stepwell: a stair of carved stone going down, down, to water.": ["大階段井戸:彫刻された石の階段が、下へ、下へと、水まで続いている。", "대계단우물: 조각된 돌계단이 아래로, 아래로, 물까지 이어진다.", "大阶梯井:雕花石阶一路向下,向下,直抵水面。", "大階梯井:雕花石階一路向下,向下,直抵水面。", "Giếng Bậc Lớn: một cầu thang đá chạm khắc đi xuống, xuống mãi, tới mặt nước.", "Sumur Tangga Agung: tangga batu berukir yang turun, terus turun, sampai ke air.", "บ่อขั้นบันไดใหญ่: บันไดหินแกะสลักทอดลงไป ลงไป จนถึงน้ำ", "Büyük Basamaklı Kuyu: aşağı, daha aşağı, suya inen oymalı taştan bir merdiven.", "El Gran Pozo Escalonado: una escalera de piedra tallada que baja, y baja, hasta el agua.", "O Grande Poço de Degraus: uma escada de pedra entalhada que desce, desce, até a água.", "Великий ступенчатый колодец: лестница из резного камня, уходящая вниз, вниз, к воде.", "Великий східчастий колодязь: сходи з різьбленого каменю, що ведуть униз, униз, до води."],
  "A low stone in the middle of the Mandapa, worn smooth where seven generations of Speakers have stood. Cut round its edge: 'I speak for seven. Seven hear me. None stands higher.' Someone has added, in chalk: 'Except when it rains.'": ["マンダパの中央にある低い石。七代の議長が立ってきた場所がすり減ってなめらかだ。縁に刻まれた文字:「我は七者のために語る。七者は我に耳を傾ける。我より高く立つ者なし。」誰かがチョークで書き足している:「雨の日を除く。」", "만다파 한가운데 놓인 낮은 돌. 일곱 대에 걸친 의장들이 서 온 자리가 반들반들하게 닳았다. 가장자리에 새겨진 글: '나는 일곱을 대변한다. 일곱이 내 말을 듣는다. 아무도 나보다 높이 서지 않는다.' 누군가 분필로 덧붙였다: '비 올 때는 빼고.'", "曼达帕正中一块低矮的石头,七代议长站过的地方已磨得光滑。石沿刻着:“吾为七方发声。七方听吾。无人立于吾上。”有人用粉笔添了一句:“下雨时除外。”", "曼達帕正中一塊低矮的石頭,七代議長站過的地方已磨得光滑。石沿刻著:「吾為七方發聲。七方聽吾。無人立於吾上。」有人用粉筆添了一句:「下雨時除外。」", "Một phiến đá thấp giữa Mandapa, mòn nhẵn ở chỗ bảy thế hệ Phát ngôn nhân từng đứng. Khắc quanh mép: “Ta nói thay bảy. Bảy lắng nghe ta. Không ai đứng cao hơn.” Ai đó đã viết thêm bằng phấn: “Trừ khi trời mưa.”", "Sebuah batu rendah di tengah Mandapa, aus licin di tempat tujuh generasi Juru Bicara pernah berdiri. Terpahat di tepinya: “Aku berbicara untuk tujuh. Tujuh mendengarku. Tak seorang pun berdiri lebih tinggi.” Seseorang menambahkan dengan kapur: “Kecuali saat hujan.”", "หินเตี้ย ๆ กลางมณฑป สึกจนเรียบตรงที่ประธานเจ็ดรุ่นเคยยืน สลักรอบขอบว่า: “ข้าพูดแทนเจ็ด เจ็ดฟังข้า ไม่มีผู้ใดยืนสูงกว่า” มีคนเขียนเติมด้วยชอล์ก: “ยกเว้นตอนฝนตก”", "Mandapa'nın ortasında, yedi kuşak Sözcü'nün durduğu yerden aşınıp pürüzsüzleşmiş alçak bir taş. Kenarına kazınmış: “Yedi adına konuşurum. Yedisi beni dinler. Kimse daha yükseğe çıkmaz.” Biri tebeşirle eklemiş: “Yağmur yağınca hariç.”", "Una piedra baja en el centro del Mandapa, gastada y lisa donde han estado siete generaciones de Portavoces. Tallado en su borde: «Hablo por siete. Siete me oyen. Nadie se alza más alto». Alguien ha añadido, con tiza: «Salvo cuando llueve».", "Uma pedra baixa no meio do Mandapa, gasta e lisa onde sete gerações de Porta-vozes estiveram. Gravado em volta da borda: “Falo por sete. Sete me ouvem. Ninguém fica mais alto.” Alguém acrescentou, a giz: “Exceto quando chove.”", "Низкий камень посреди Мандапы, стёртый до гладкости там, где стояли семь поколений Глашатаев. По краю высечено: «Я говорю за семерых. Семеро слышат меня. Никто не стоит выше». Кто-то приписал мелом: «Кроме как в дождь».", "Низький камінь посеред Мандапи, витертий до гладкості там, де стояли сім поколінь Речників. По краю вирізьблено: «Я говорю за сімох. Семеро чують мене. Ніхто не стоїть вище». Хтось дописав крейдою: «Окрім як у дощ»."],
  "East of Khetmar, over its bay, lies Meghavan: the country Kharaveth's traders call the Rain Country. Through the Gate of Rains the dry hills turn green, and the river Ilavati runs from the Shaila Highlands past Sarovan and down through the Deepgreen to the sea.": ["ケトマルの東、湾の向こうにメガヴァンがある。カラヴェスの商人たちが「雨の国」と呼ぶ国だ。雨の門を抜けると乾いた丘は緑に変わり、イラヴァティ川がシャイラ高地からサロヴァンを過ぎ、深緑の森を下って海へと流れる。", "케트마르 동쪽, 그 만 너머에 메가반이 있다. 카라베스 상인들이 '비의 나라'라 부르는 나라다. 비의 문을 지나면 메마른 언덕이 초록으로 바뀌고, 일라바티강이 샤일라 고원에서 사로반을 지나 깊은초록 숲을 거쳐 바다로 흘러간다.", "在克特马尔以东、隔着海湾的地方,便是梅加万:卡拉维斯商人口中的“雨之国”。穿过雨之门,干燥的丘陵转为青绿,伊拉瓦蒂河从沙伊拉高地流出,经过萨罗万,穿越深绿林,奔流入海。", "在克特馬爾以東、隔著海灣的地方,便是梅加萬:卡拉維斯商人口中的「雨之國」。穿過雨之門,乾燥的丘陵轉為青綠,伊拉瓦蒂河從沙伊拉高地流出,經過薩羅萬,穿越深綠林,奔流入海。", "Phía đông Khetmar, bên kia vịnh, là Meghavan: xứ sở mà thương nhân Kharaveth gọi là Xứ Mưa. Qua Cổng Mưa, những ngọn đồi khô cằn hóa xanh, và sông Ilavati chảy từ Cao nguyên Shaila qua Sarovan, xuống xuyên Rừng Thẳm Xanh ra biển.", "Di timur Khetmar, di seberang teluknya, terbentang Meghavan: negeri yang oleh para pedagang Kharaveth disebut Negeri Hujan. Melewati Gerbang Hujan, bukit-bukit kering berubah hijau, dan sungai Ilavati mengalir dari Dataran Tinggi Shaila melewati Sarovan, turun menembus Rimba Hijau Pekat hingga ke laut.", "ทางตะวันออกของเคทมาร์ ข้ามอ่าวไป คือเมฆาวัน ดินแดนที่พ่อค้าคาราเวธเรียกว่าแดนฝน เมื่อผ่านประตูแห่งสายฝน เนินเขาแห้งแล้งจะกลายเป็นสีเขียว และแม่น้ำอิลาวดีไหลจากที่ราบสูงไศลา ผ่านสโรวัน ลงไปผ่านป่าเขียวลึกสู่ทะเล", "Khetmar'ın doğusunda, körfezinin ötesinde Meghavan uzanır: Kharaveth tüccarlarının Yağmur Ülkesi dediği ülke. Yağmur Kapısı'ndan geçince kuru tepeler yeşile döner ve Ilavati nehri Shaila Yaylaları'ndan doğup Sarovan'ı geçerek Derin Yeşillik'in içinden denize akar.", "Al este de Khetmar, al otro lado de su bahía, se extiende Meghavan: el país que los mercaderes de Kharaveth llaman el País de la Lluvia. Tras la Puerta de las Lluvias, las colinas secas se vuelven verdes, y el río Ilavati baja de las Tierras Altas de Shaila, pasa por Sarovan y atraviesa el Verdor Profundo hasta el mar.", "A leste de Khetmar, do outro lado de sua baía, fica Meghavan: o país que os mercadores de Kharaveth chamam de País da Chuva. Passando o Portão das Chuvas, as colinas secas ficam verdes, e o rio Ilavati desce das Terras Altas de Shaila, passa por Sarovan e atravessa o Verde Profundo até o mar.", "К востоку от Кетмара, за его заливом, лежит Мегхаван — страна, которую купцы Харавета зовут Страной дождей. За Вратами Дождей сухие холмы зеленеют, а река Илавати течёт с нагорья Шайла мимо Сарована и через Глубокую Зелень к морю.", "На схід від Кетмара, за його затокою, лежить Мегхаван — країна, яку купці Харавета звуть Країною дощів. За Брамою Дощів сухі пагорби зеленіють, а річка Ілаваті тече з нагір'я Шайла повз Сарован і крізь Глибоку Зелень до моря."],
  "Six towns, each with its own people, tailor and clothes: Tirthali, the ford town, half Kharaveth and half Meghavan; Sarovan, the marble capital of Ilavarta, with its palace, the Great Tank and the Great Stepwell; Shailagarh, the highland fortress over the mines; Mandapur, where the League of Seven Parasols meets in an open hall; Suvarnatira, the free port, with its docks and the Archive; and Kanthar, the Kanthari's stilt village in the Deepgreen.": ["六つの町、それぞれに住人と仕立屋と衣装がある。ティルタリは浅瀬の町で、半分カラヴェス、半分メガヴァン。サロヴァンはイラヴァルタの大理石の都で、宮殿と大貯水池と大階段井戸がある。シャイラガルは鉱山を見下ろす高地の砦。マンダプルでは七つの日傘同盟が吹き抜けの広間で会合を開く。スヴァルナティーラは自由港で、波止場と文書館がある。そしてカンタルは、深緑の森にあるカンタリの高床の村。", "저마다 주민과 재단사와 옷차림이 있는 여섯 마을. 여울 마을 티르탈리는 반은 카라베스, 반은 메가반이다. 일라바르타의 대리석 수도 사로반에는 궁전과 대저수지, 대계단우물이 있다. 샤일라가르는 광산 위의 고원 요새다. 만다푸르에서는 일곱 일산 동맹이 탁 트인 회당에 모인다. 자유항 수바르나티라에는 부두와 서고가 있다. 그리고 칸타르는 깊은초록 숲 속 칸타리족의 기둥집 마을이다.", "六座城镇,各有各的居民、裁缝和服饰:提尔塔利,渡口小镇,一半卡拉维斯,一半梅加万;萨罗万,伊拉瓦塔的大理石都城,有王宫、大水池和大阶梯井;沙伊拉加尔,俯瞰矿山的高地要塞;曼达普尔,七华盖同盟在一座敞开的大厅里议事;苏瓦尔纳蒂拉,自由港,有码头和档案馆;还有坎塔尔,坎塔里人在深绿林中的高脚屋村落。", "六座城鎮,各有各的居民、裁縫和服飾:提爾塔利,渡口小鎮,一半卡拉維斯,一半梅加萬;薩羅萬,伊拉瓦塔的大理石都城,有王宮、大水池和大階梯井;沙伊拉加爾,俯瞰礦山的高地要塞;曼達普爾,七華蓋同盟在一座敞開的大廳裡議事;蘇瓦爾納蒂拉,自由港,有碼頭和檔案館;還有坎塔爾,坎塔里人在深綠林中的高腳屋村落。", "Sáu thị trấn, mỗi nơi có cư dân, thợ may và trang phục riêng: Tirthali, thị trấn bến lội, nửa Kharaveth nửa Meghavan; Sarovan, kinh đô cẩm thạch của Ilavarta, với cung điện, Hồ Lớn và Giếng Bậc Lớn; Shailagarh, pháo đài cao nguyên nhìn xuống các mỏ; Mandapur, nơi Liên minh Bảy Lọng họp trong một sảnh lộ thiên; Suvarnatira, cảng tự do, với bến tàu và Văn khố; và Kanthar, làng nhà sàn của người Kanthari trong Rừng Thẳm Xanh.", "Enam kota, masing-masing dengan penduduk, penjahit, dan pakaiannya sendiri: Tirthali, kota penyeberangan, separuh Kharaveth dan separuh Meghavan; Sarovan, ibu kota marmer Ilavarta, dengan istananya, Telaga Agung, dan Sumur Tangga Agung; Shailagarh, benteng dataran tinggi di atas tambang; Mandapur, tempat Liga Tujuh Payung bersidang di balai terbuka; Suvarnatira, pelabuhan bebas, dengan dermaga dan Arsipnya; dan Kanthar, desa rumah panggung orang Kanthari di Rimba Hijau Pekat.", "หกเมือง แต่ละเมืองมีผู้คน ช่างตัดเสื้อ และเครื่องแต่งกายของตัวเอง: ตีรถลี เมืองท่าข้าม ครึ่งคาราเวธครึ่งเมฆาวัน; สโรวัน เมืองหลวงหินอ่อนของอิลาวรรตะ พร้อมพระราชวัง สระใหญ่ และบ่อขั้นบันไดใหญ่; ไศลครห์ ป้อมบนที่สูงเหนือเหมือง; มัณฑปุระ ที่สันนิบาตเจ็ดฉัตรประชุมกันในศาลาโล่ง; สุวรรณตีระ เมืองท่าเสรี พร้อมท่าเรือและหอจดหมายเหตุ; และกันถาร์ หมู่บ้านบ้านใต้ถุนสูงของชาวกันถารีในป่าเขียวลึก", "Her birinin kendi halkı, terzisi ve kıyafetleri olan altı kasaba: geçit kasabası Tirthali, yarı Kharaveth yarı Meghavan; Ilavarta'nın mermer başkenti Sarovan, sarayı, Büyük Havuz'u ve Büyük Basamaklı Kuyu'suyla; madenlerin üstündeki yayla kalesi Shailagarh; Yedi Şemsiye Birliği'nin açık bir salonda toplandığı Mandapur; rıhtımları ve Arşiv'iyle serbest liman Suvarnatira; ve Kanthariler'in Derin Yeşillik'teki kazıklı köyü Kanthar.", "Seis poblaciones, cada una con su gente, su sastre y su ropa: Tirthali, el pueblo del vado, mitad Kharaveth y mitad Meghavan; Sarovan, la capital de mármol de Ilavarta, con su palacio, el Gran Estanque y el Gran Pozo Escalonado; Shailagarh, la fortaleza de las tierras altas sobre las minas; Mandapur, donde la Liga de los Siete Parasoles se reúne en una sala abierta; Suvarnatira, el puerto libre, con sus muelles y el Archivo; y Kanthar, la aldea de palafitos de los kanthari en el Verdor Profundo.", "Seis cidades, cada uma com seu povo, seu alfaiate e suas roupas: Tirthali, a cidade do vau, metade Kharaveth e metade Meghavan; Sarovan, a capital de mármore de Ilavarta, com seu palácio, o Grande Tanque e o Grande Poço de Degraus; Shailagarh, a fortaleza das terras altas sobre as minas; Mandapur, onde a Liga dos Sete Para-sóis se reúne num salão aberto; Suvarnatira, o porto livre, com suas docas e o Arquivo; e Kanthar, a aldeia de palafitas dos kanthari no Verde Profundo.", "Шесть городов, у каждого свои жители, портной и одежда: Тиртхали, город у брода, наполовину Харавет, наполовину Мегхаван; Сарован, мраморная столица Илаварты, с дворцом, Великим прудом и Великим ступенчатым колодцем; Шайлагарх, горная крепость над рудниками; Мандапур, где Лига Семи Зонтов собирается в открытом зале; Суварнатира, вольный порт, с причалами и Архивом; и Кантхар, деревня кантхари на сваях в Глубокой Зелени.", "Шість міст, у кожного свої мешканці, кравець і одяг: Тіртхалі, місто біля броду, наполовину Харавет, наполовину Мегхаван; Сарован, мармурова столиця Ілаварти, з палацом, Великим ставом і Великим східчастим колодязем; Шайлагарх, гірська фортеця над копальнями; Мандапур, де Ліга Семи Парасолів збирається у відкритій залі; Суварнатіра, вільний порт, із причалами й Архівом; і Кантхар, село кантхарі на палях у Глибокій Зелені."],
  "Powers that don't agree: Queen Saumitra, Keeper of the Tanks, between her engineers and the temple treasurers; the League and its Speaker by turn; Lord Varanjit and his hired Copper Banner companies; Provost Lalitha and the Assembly of Ink and Coin; Grandmother Sukesh and the Kanthari; and Ferrywarden Amul, who asks very few questions.": ["意見の合わない勢力たち:技師たちと神殿の会計役たちの板挟みになる貯水池の守り手サウミトラ女王。持ち回りの議長を戴く同盟。雇われの銅の旗の傭兵団を抱えるヴァランジット卿。ラリタ学頭と墨と貨幣の議会。スケシュ婆さまとカンタリ。そして、ほとんど何も訊かない渡し守アムル。", "뜻이 맞지 않는 세력들: 기술자들과 신전 재무관들 사이에 낀 저수지의 수호자 사우미트라 여왕, 동맹과 돌아가며 맡는 의장, 고용한 구리 깃발 용병대를 거느린 바란지트 경, 랄리타 학장과 먹과 주화의 의회, 수케시 할머니와 칸타리족, 그리고 질문을 거의 하지 않는 나루지기 아물.", "意见不合的各方势力:夹在工程师与神庙司库之间的水池守护者萨乌米特拉女王;同盟及其轮值议长;瓦兰吉特大人和他雇来的铜旗佣兵团;拉丽塔院长与墨与币议会;苏凯什奶奶与坎塔里人;还有很少多问的渡口守阿穆尔。", "意見不合的各方勢力:夾在工程師與神廟司庫之間的水池守護者薩烏米特拉女王;同盟及其輪值議長;瓦蘭吉特大人和他僱來的銅旗傭兵團;拉麗塔院長與墨與幣議會;蘇凱什奶奶與坎塔里人;還有很少多問的渡口守阿穆爾。", "Những thế lực chẳng đồng lòng: Nữ hoàng Saumitra, Người Giữ Hồ, kẹt giữa các kỹ sư và thủ quỹ đền thờ; Liên minh cùng Phát ngôn nhân luân phiên; Lãnh chúa Varanjit và các đại đội Cờ Đồng đánh thuê; Viện trưởng Lalitha và Hội đồng Mực và Xu; Bà Sukesh và người Kanthari; và Người giữ bến Amul, kẻ hỏi rất ít câu hỏi.", "Kekuatan-kekuatan yang tak sepakat: Ratu Saumitra, Penjaga Telaga, terjepit di antara para insinyurnya dan bendahara kuil; Liga dan Juru Bicaranya yang bergiliran; Tuan Varanjit dan kompi-kompi Panji Tembaga sewaannya; Provos Lalitha dan Majelis Tinta dan Koin; Nenek Sukesh dan orang Kanthari; serta Penjaga Penyeberangan Amul, yang sangat jarang bertanya.", "ขั้วอำนาจที่ไม่ลงรอยกัน: ราชินีเสามิตรา ผู้รักษาสระ ผู้ติดอยู่ระหว่างเหล่าวิศวกรกับเหรัญญิกของวิหาร; สันนิบาตกับประธานที่ผลัดกันดำรงตำแหน่ง; ท่านวรัญชิตกับกองร้อยธงทองแดงที่ว่าจ้างมา; อธิการลลิตากับสภาหมึกและเหรียญ; ยายสุเกศกับชาวกันถารี; และผู้คุมท่าข้ามอมุล ผู้แทบไม่ถามอะไรเลย", "Anlaşamayan güçler: mühendisleriyle tapınak haznedarları arasında kalmış Havuzların Bekçisi Kraliçe Saumitra; Birlik ve sırayla değişen Sözcüsü; Lord Varanjit ve kiralık Bakır Sancak bölükleri; Rektör Lalitha ve Mürekkep ve Sikke Meclisi; Sukesh Nine ve Kanthariler; ve pek az soru soran Geçit Bekçisi Amul.", "Poderes que no se ponen de acuerdo: la reina Saumitra, Guardiana de los Estanques, entre sus ingenieros y los tesoreros del templo; la Liga y su Portavoz por turnos; el señor Varanjit y sus compañías contratadas del Estandarte de Cobre; la prebostesa Lalitha y la Asamblea de Tinta y Moneda; la abuela Sukesh y los kanthari; y el guardavado Amul, que hace muy pocas preguntas.", "Poderes que não se entendem: a rainha Saumitra, Guardiã dos Tanques, entre seus engenheiros e os tesoureiros do templo; a Liga e seu Porta-voz em rodízio; o senhor Varanjit e suas companhias contratadas do Estandarte de Cobre; a reitora Lalitha e a Assembleia da Tinta e da Moeda; a avó Sukesh e os kanthari; e o guarda do vau Amul, que faz pouquíssimas perguntas.", "Силы, которые не могут договориться: королева Саумитра, Хранительница прудов, между своими инженерами и храмовыми казначеями; Лига и её Глашатай, сменяемый по очереди; лорд Варанджит и его наёмные роты Медного знамени; провост Лалита и Собрание Чернил и Монет; бабушка Сукеш и кантхари; и паромщик Амул, который задаёт очень мало вопросов.", "Сили, які не можуть дійти згоди: королева Саумітра, Хранителька ставів, між своїми інженерами й храмовими скарбниками; Ліга та її Речник, що змінюється по черзі; лорд Варанджит і його наймані роти Мідного стягу; провост Лаліта і Збори Чорнила й Монет; бабуся Сукеш і кантхарі; і поромник Амул, який ставить дуже мало запитань."],
  "Inns, general stores and forges in the big towns, with rice and lentils, mangoes, flatbread and spiced tea, and the smiths' curved Ilavati sabre, the push-dagger and Shaila mail. Mines of blackiron, moonsilver and glimmer under the Shaila peaks.": ["大きな町には宿屋、雑貨屋、鍛冶場があり、米とレンズ豆、マンゴー、平焼きパン、スパイスティー、そして鍛冶屋の反りのあるイラヴァティ・サーベル、プッシュダガー、シャイラの鎖帷子がそろう。シャイラの峰々の下にはブラックアイアン、ムーンシルバー、グリマーの鉱山がある。", "큰 마을마다 여관, 잡화점, 대장간이 있어 쌀과 렌틸콩, 망고, 납작빵, 향신료 차, 그리고 대장장이들의 굽은 일라바티 사브르, 푸시 대거, 샤일라 사슬 갑옷을 판다. 샤일라 봉우리들 아래에는 흑철, 월은, 글리머 광산이 있다.", "大城镇里有客栈、杂货铺和铁匠铺,供应米饭和扁豆、芒果、薄饼和香料茶,还有铁匠打造的弯刃伊拉瓦蒂军刀、拳刃匕首和沙伊拉锁甲。沙伊拉群峰之下有黑铁、月银和微光的矿脉。", "大城鎮裡有客棧、雜貨鋪和鐵匠鋪,供應米飯和扁豆、芒果、薄餅和香料茶,還有鐵匠打造的彎刃伊拉瓦蒂軍刀、拳刃匕首和沙伊拉鎖甲。沙伊拉群峰之下有黑鐵、月銀和微光的礦脈。", "Quán trọ, tiệm tạp hóa và lò rèn ở các thị trấn lớn, với cơm và đậu lăng, xoài, bánh dẹt và trà gia vị, cùng thanh kiếm cong Ilavati của thợ rèn, dao găm đấm và giáp xích Shaila. Mỏ sắt đen, bạc trăng và ánh kim dưới những đỉnh núi Shaila.", "Penginapan, toko kelontong, dan bengkel pandai besi di kota-kota besar, dengan nasi dan lentil, mangga, roti pipih, dan teh rempah, serta pedang lengkung Ilavati buatan para pandai besi, belati dorong, dan zirah rantai Shaila. Tambang besi hitam, perak bulan, dan kemilau di bawah puncak-puncak Shaila.", "โรงเตี๊ยม ร้านของชำ และโรงตีเหล็กในเมืองใหญ่ มีข้าวกับถั่วเลนทิล มะม่วง แผ่นแป้งย่าง และชาเครื่องเทศ ทั้งดาบโค้งอิลาวดีของช่างตีเหล็ก กริชดัน และเกราะโซ่ไศลา เหมืองเหล็กดำ เงินจันทร์ และประกายแสงใต้ยอดเขาไศลา", "Büyük kasabalarda hanlar, bakkallar ve demirhaneler; pirinç ve mercimek, mango, yassı ekmek ve baharatlı çay; demircilerin kavisli Ilavati kılıcı, yumruk hançeri ve Shaila zırhı. Shaila doruklarının altında kara demir, ay gümüşü ve parıltı madenleri.", "Posadas, tiendas generales y forjas en las poblaciones grandes, con arroz y lentejas, mangos, pan plano y té especiado, y el sable curvo ilavati de los herreros, la daga de empuje y la cota de malla de Shaila. Minas de hierro negro, plata lunar y destello bajo los picos de Shaila.", "Estalagens, armazéns e forjas nas cidades grandes, com arroz e lentilhas, mangas, pão chato e chá com especiarias, e o sabre curvo ilavati dos ferreiros, a adaga de soco e a cota de malha de Shaila. Minas de ferro negro, prata lunar e lampejo sob os picos de Shaila.", "Трактиры, лавки и кузницы в больших городах — с рисом и чечевицей, манго, лепёшками и пряным чаем, а также кузнечной изогнутой илаватийской саблей, тычковым кинжалом и шайлской кольчугой. Рудники чёрного железа, лунного серебра и мерцалита под пиками Шайлы.", "Корчми, крамниці й кузні у великих містах — з рисом і сочевицею, манго, коржами та пряним чаєм, а також вигнутою ілаватійською шаблею від ковалів, кулачним кинджалом і шайлською кольчугою. Копальні чорного заліза, місячного срібла й мерехтиту під вершинами Шайли."],
  "Twelve new creatures, from rain frogs, jewelled peafowl and wild gaur to rock langurs, hooded serpents, crag bears, vine stranglers and the Deepgreen tiger, and dacoits, corsairs and Banner deserters. It rains more often in the Rain Country, and the Deepgreen is always misty.": ["雨ガエル、宝石クジャク、野生のガウルから、イワラングール、頭巾蛇、岩山グマ、絞め蔓、深緑の森の虎まで、新しい生き物が十二種。さらにダコイト(山賊)、海賊、旗の脱走兵も。雨の国では雨がよく降り、深緑の森はいつも霧に包まれている。", "비개구리, 보석 공작, 야생 가우르부터 바위 랑구르, 두건뱀, 바위산 곰, 덩굴 교살자, 깊은초록 숲의 호랑이까지 새로운 생물 열두 종, 그리고 도적단, 해적, 깃발 탈영병. 비의 나라엔 비가 더 자주 내리고, 깊은초록 숲은 늘 안개가 끼어 있다.", "十二种新生物,从雨蛙、宝石孔雀、野生印度野牛,到岩叶猴、兜帽蛇、峭壁熊、绞杀藤,以及深绿林猛虎,还有土匪、海盗和铜旗逃兵。雨之国下雨更频繁,深绿林则终年雾气弥漫。", "十二種新生物,從雨蛙、寶石孔雀、野生印度野牛,到岩葉猴、兜帽蛇、峭壁熊、絞殺藤,以及深綠林猛虎,還有土匪、海盜和銅旗逃兵。雨之國下雨更頻繁,深綠林則終年霧氣瀰漫。", "Mười hai sinh vật mới, từ ếch mưa, công ngọc và bò tót hoang tới voọc đá, rắn hổ mang bành, gấu vách đá, dây leo siết cổ và hổ Rừng Thẳm Xanh, cùng bọn cướp đường, cướp biển và lính đào ngũ Cờ Đồng. Ở Xứ Mưa trời mưa thường xuyên hơn, và Rừng Thẳm Xanh lúc nào cũng mù sương.", "Dua belas makhluk baru, dari katak hujan, merak permata, dan gaur liar hingga lutung batu, ular berkerudung, beruang tebing, pencekik sulur, dan harimau Rimba Hijau Pekat, serta begal, perompak, dan desertir Panji. Hujan lebih sering turun di Negeri Hujan, dan Rimba Hijau Pekat selalu berkabut.", "สัตว์ใหม่สิบสองชนิด ตั้งแต่กบฝน นกยูงอัญมณี และกระทิงป่า ไปจนถึงค่างหิน งูเห่า หมีผา เถาวัลย์รัดคอ และเสือป่าเขียวลึก รวมทั้งโจรปล้น โจรสลัด และทหารหนีทัพธงทองแดง ในแดนฝนฝนตกบ่อยกว่า และป่าเขียวลึกมีหมอกตลอดเวลา", "Yağmur kurbağaları, mücevher tavus kuşları ve yaban gaurlarından kaya langurlarına, kukuletalı yılanlara, uçurum ayılarına, sarmaşık boğuculara ve Derin Yeşillik kaplanına on iki yeni yaratık; bir de haydutlar, korsanlar ve Sancak kaçakları. Yağmur Ülkesi'nde yağmur daha sık yağar, Derin Yeşillik ise hep sislidir.", "Doce criaturas nuevas, desde ranas de lluvia, pavos reales enjoyados y gaures salvajes hasta langures de roca, serpientes de capucha, osos de risco, estranguladoras de enredadera y el tigre del Verdor Profundo, además de bandoleros, corsarios y desertores del Estandarte. En el País de la Lluvia llueve más a menudo, y el Verdor Profundo siempre está brumoso.", "Doze criaturas novas, de rãs-da-chuva, pavões-joia e gauros selvagens a langures-da-rocha, serpentes-de-capuz, ursos-do-penhasco, estranguladoras-de-cipó e o tigre do Verde Profundo, além de salteadores, corsários e desertores do Estandarte. Chove com mais frequência no País da Chuva, e o Verde Profundo está sempre enevoado.", "Двенадцать новых существ — от дождевых лягушек, самоцветных павлинов и диких гауров до скальных лангуров, клобучных змей, утёсных медведей, лиан-душителей и тигра Глубокой Зелени, — а также дакойты, корсары и дезертиры Знамени. В Стране дождей дожди идут чаще, а над Глубокой Зеленью всегда туман.", "Дванадцять нових істот — від дощових жаб, самоцвітних павичів і диких гаурів до скельних лангурів, каптурних змій, кручових ведмедів, ліан-душителів і тигра Глибокої Зелені, — а також дакойти, корсари й дезертири Стягу. У Країні дощів дощі йдуть частіше, а над Глибокою Зеленню завжди туман."],
  "Five new pieces of music in the ragas, for tanpura, sitar, bansuri, shehnai, santoor and tabla.": ["ラーガによる新曲五つ。タンプーラ、シタール、バーンスリー、シェーナイ、サントゥール、タブラのために。", "탐푸라, 시타르, 반수리, 셰나이, 산투르, 타블라를 위한 라가 선율의 새 곡 다섯.", "五首以拉格写成的新曲,为坦布拉琴、西塔琴、班苏里笛、谢赫奈管、桑图尔琴和塔布拉鼓而作。", "五首以拉格寫成的新曲,為坦布拉琴、西塔琴、班蘇里笛、謝赫奈管、桑圖爾琴和塔布拉鼓而作。", "Năm bản nhạc mới theo các điệu raga, cho đàn tanpura, sitar, sáo bansuri, kèn shehnai, đàn santoor và trống tabla.", "Lima lagu baru dalam raga, untuk tanpura, sitar, bansuri, shehnai, santoor, dan tabla.", "บทเพลงใหม่ห้าเพลงในแนวราคะ สำหรับตานปุระ ซีตาร์ ขลุ่ยบานสุรี ปี่เชห์นาย ซันตูร์ และกลองตับลา", "Ragalarla yazılmış beş yeni parça; tanpura, sitar, bansuri, şehnai, santur ve tabla için.", "Cinco piezas de música nuevas en ragas, para tanpura, sitar, bansuri, shehnai, santur y tabla.", "Cinco músicas novas em ragas, para tanpura, cítara, bansuri, shehnai, santur e tabla.", "Пять новых мелодий в рагах для танпуры, ситара, бансури, шехная, сантура и таблы.", "П'ять нових мелодій у рагах для танпури, ситари, бансурі, шехнаю, сантура й табли."],
  "Still to come in Meghavan: its quests and the Great Stepwell under Sarovan, then the four eastern schools of the Mysteries.": ["メガヴァン、今後の予定:クエストとサロヴァンの地下の大階段井戸、そして東方の四つの神秘の学派。", "메가반에서 앞으로 올 것: 퀘스트와 사로반 아래의 대계단우물, 그리고 동방의 네 신비 학파.", "梅加万后续内容:任务与萨罗万地下的大阶梯井,随后是东方的四大奥秘学派。", "梅加萬後續內容:任務與薩羅萬地下的大階梯井,隨後是東方的四大奧秘學派。", "Còn sắp tới ở Meghavan: các nhiệm vụ và Giếng Bậc Lớn bên dưới Sarovan, rồi bốn trường phái Huyền bí phương đông.", "Masih akan datang di Meghavan: misi-misinya dan Sumur Tangga Agung di bawah Sarovan, lalu empat aliran Misteri dari timur.", "ที่จะตามมาในเมฆาวัน: ภารกิจต่าง ๆ และบ่อขั้นบันไดใหญ่ใต้สโรวัน จากนั้นคือสี่สำนักความลึกลับแห่งตะวันออก", "Meghavan'da sırada: görevleri ve Sarovan'ın altındaki Büyük Basamaklı Kuyu, ardından doğunun dört Gizemler okulu.", "Aún por llegar en Meghavan: sus misiones y el Gran Pozo Escalonado bajo Sarovan, y después las cuatro escuelas orientales de los Misterios.", "Ainda por vir em Meghavan: suas missões e o Grande Poço de Degraus sob Sarovan, e depois as quatro escolas orientais dos Mistérios.", "Ещё впереди в Мегхаване: его задания и Великий ступенчатый колодец под Сарованом, а затем четыре восточные школы Тайн.", "Ще попереду в Мегхавані: його завдання й Великий східчастий колодязь під Сарованом, а потім чотири східні школи Таємниць."],
  "The stump of a grove tree, older than Shailagarh's walls, freshly cut": ["シャイラガルの城壁より古い聖林の木の切り株。切られたばかりだ", "샤일라가르의 성벽보다 오래된 신성한 숲 나무의 그루터기. 갓 베어졌다", "一棵圣林古树的树桩,比沙伊拉加尔的城墙还古老,刚被砍倒", "一棵聖林古樹的樹樁,比沙伊拉加爾的城牆還古老,剛被砍倒", "Gốc một cây rừng thiêng, già hơn cả tường thành Shailagarh, vừa mới bị đốn", "Tunggul pohon hutan keramat, lebih tua daripada tembok Shailagarh, baru saja ditebang", "ตอของต้นไม้ในป่าศักดิ์สิทธิ์ เก่าแก่กว่ากำแพงไศลครห์ เพิ่งถูกตัดใหม่ๆ", "Shailagarh'ın surlarından daha yaşlı bir koru ağacının kütüğü, yeni kesilmiş", "El tocón de un árbol de la arboleda, más antiguo que las murallas de Shailagarh, recién talado", "O toco de uma árvore do bosque, mais antiga que as muralhas de Shailagarh, recém-cortada", "Пень дерева священной рощи, что старше стен Шайлагарха, свежеспиленный", "Пень дерева священного гаю, старшого за мури Шайлагарха, свіжозрізаний"],
  "A carved pillar: a river goddess pouring from a jar, her face worn away by hands": ["彫刻の柱。壺から水を注ぐ川の女神。その顔は人々の手に撫でられてすり減っている", "조각 기둥. 항아리에서 물을 붓는 강의 여신이 새겨져 있고, 얼굴은 사람들의 손길에 닳아 없어졌다", "一根雕花柱:一位河流女神正从罐中倾水,她的脸已被无数双手摸平了", "一根雕花柱:一位河流女神正從罐中傾水,她的臉已被無數雙手摸平了", "Một cột chạm khắc: nữ thần sông nghiêng bình rót nước, gương mặt đã mòn vẹt vì bao bàn tay chạm vào", "Pilar berukir: dewi sungai menuang air dari kendi, wajahnya terkikis oleh sentuhan tangan", "เสาสลัก: เทวีแห่งแม่น้ำกำลังเทน้ำจากโถ ใบหน้าของนางสึกกร่อนไปเพราะมือคนลูบ", "Oymalı bir sütun: testiden su döken bir nehir tanrıçası, yüzü ellerin dokunuşuyla aşınmış", "Un pilar tallado: una diosa del río vertiendo agua de un cántaro, con el rostro gastado por las manos", "Um pilar entalhado: uma deusa do rio derramando água de um jarro, o rosto gasto pelas mãos", "Резная колонна: речная богиня льёт воду из кувшина, её лицо стёрто руками", "Різьблена колона: річкова богиня ллє воду з глека, її обличчя стерте руками"],
  "An oiled cotton cloak the colour of rain clouds, a Khetmar caravan's thanks. The rain runs off it; the dust doesn't stick.": ["雨雲の色をした、油引きの綿の外套。ケトマルの隊商からの礼の品だ。雨は流れ落ち、埃はつかない。", "비구름 빛깔의 기름 먹인 면 망토. 케트마르 대상이 건넨 감사의 표시다. 비는 흘러내리고, 먼지는 달라붙지 않는다.", "一件雨云色的涂油棉斗篷,是克特马尔商队的谢礼。雨水顺着它流下,灰尘也沾不上。", "一件雨雲色的塗油棉斗篷,是克特馬爾商隊的謝禮。雨水順著它流下,灰塵也沾不上。", "Một chiếc áo choàng vải bông tẩm dầu màu mây mưa, quà cảm ơn của một đoàn lữ hành Khetmar. Mưa trôi tuột khỏi nó; bụi không bám vào.", "Jubah katun berminyak sewarna awan hujan, tanda terima kasih sebuah kafilah Khetmar. Hujan mengalir turun darinya; debu tak menempel.", "เสื้อคลุมผ้าฝ้ายชุบน้ำมันสีเมฆฝน ของขอบคุณจากกองคาราวานเคทมาร์ ฝนไหลลื่นออกไป ฝุ่นก็ไม่เกาะ", "Yağmur bulutu renginde, yağlanmış pamuklu bir pelerin; bir Khetmar kervanının teşekkürü. Yağmur üstünden akıp gider, toz tutmaz.", "Una capa de algodón aceitado del color de las nubes de lluvia, el agradecimiento de una caravana de Khetmar. La lluvia le resbala; el polvo no se le pega.", "Uma capa de algodão oleado da cor das nuvens de chuva, o agradecimento de uma caravana de Khetmar. A chuva escorre por ela; a poeira não gruda.", "Плащ из промасленного хлопка цвета дождевых туч — благодарность кетмарского каравана. Дождь с него стекает, пыль не пристаёт.", "Плащ із промасленої бавовни кольору дощових хмар — подяка кетмарського каравану. Дощ із нього стікає, пил не пристає."],
  "A silver ring set with one lapis drop: a tank seen from above. Ilavarta's queens give one to whoever keeps the water.": ["瑠璃の雫をひとつはめた銀の指輪。上から見た貯水池をかたどっている。イラヴァルタの女王たちは、水を守る者にこれを授ける。", "청금석 물방울 하나를 박은 은반지. 위에서 내려다본 저수지 모양이다. 일라바르타의 여왕들은 물을 지키는 이에게 이것을 하나씩 내린다.", "一枚镶着一滴青金石的银戒指:那是从上方俯瞰的水池。伊拉瓦塔的女王们会把它赐给守护水源的人。", "一枚鑲著一滴青金石的銀戒指:那是從上方俯瞰的水池。伊拉瓦塔的女王們會把它賜給守護水源的人。", "Một chiếc nhẫn bạc gắn một giọt lưu ly: một hồ chứa nhìn từ trên cao. Các nữ hoàng Ilavarta trao một chiếc cho bất kỳ ai giữ gìn nguồn nước.", "Cincin perak bertatahkan setetes lapis lazuli: sebuah telaga dilihat dari atas. Ratu-ratu Ilavarta memberikannya kepada siapa pun yang menjaga air.", "แหวนเงินฝังลาพิสลาซูลีรูปหยดน้ำหนึ่งเม็ด: สระที่มองจากเบื้องบน ราชินีแห่งอิลาวรรตะจะมอบให้แก่ผู้ที่รักษาน้ำ", "Tek bir lapis damlası kakılmış gümüş bir yüzük: yukarıdan görülen bir havuz. Ilavarta'nın kraliçeleri suyu koruyan herkese bir tane verir.", "Un anillo de plata con una sola gota de lapislázuli: un estanque visto desde arriba. Las reinas de Ilavarta le dan uno a quien cuida el agua.", "Um anel de prata com uma única gota de lápis-lazúli: um tanque visto de cima. As rainhas de Ilavarta dão um a quem zela pela água.", "Серебряное кольцо с одной лазуритовой каплей — пруд, увиденный сверху. Королевы Илаварты дарят такое тому, кто бережёт воду.", "Срібний перстень з однією лазуритовою краплею — став, побачений згори. Королеви Ілаварти дарують такий тому, хто береже воду."],
  "A parasol of the League, its ribs gaur horn, its canopy the seven colours. Held up, it's a shade; held out, it's a shield; held by you, it's a debt the League will remember.": ["同盟の日傘。骨はガウルの角、傘布は七色。掲げれば日除け、突き出せば盾、そしてあなたが持てば、同盟が忘れぬ借りとなる。", "동맹의 일산. 살은 가우르 뿔이고, 덮개는 일곱 색이다. 받쳐 들면 그늘이요, 내밀면 방패요, 당신이 들면 동맹이 기억할 빚이다.", "同盟的华盖,伞骨是印度野牛角,伞面是七种颜色。举起来,是遮阴;伸出去,是盾牌;握在你手里,就是同盟会记住的一笔人情债。", "同盟的華蓋,傘骨是印度野牛角,傘面是七種顏色。舉起來,是遮陰;伸出去,是盾牌;握在你手裡,就是同盟會記住的一筆人情債。", "Một chiếc lọng của Liên minh, nan bằng sừng bò tót, tán mang bảy màu. Giương lên thì là bóng mát; chìa ra thì là tấm khiên; nằm trong tay bạn thì là món nợ Liên minh sẽ ghi nhớ.", "Payung Liga, jari-jarinya dari tanduk banteng gaur, kanopinya tujuh warna. Diangkat, ia peneduh; diacungkan, ia perisai; dipegang olehmu, ia utang yang akan diingat Liga.", "ฉัตรของสันนิบาต ซี่ทำจากเขากระทิง ผืนฉัตรมีเจ็ดสี ชูขึ้นก็เป็นร่มเงา ยื่นออกไปก็เป็นโล่ อยู่ในมือคุณก็เป็นหนี้บุญคุณที่สันนิบาตจะจดจำ", "Birlik'in bir şemsiyesi; telleri gaur boynuzundan, örtüsü yedi renk. Yukarı kaldırınca gölgelik, ileri uzatınca kalkan, senin elindeyken de Birlik'in unutmayacağı bir borç.", "Un parasol de la Liga, con varillas de cuerno de gaur y la tela de los siete colores. En alto, da sombra; por delante, es un escudo; en tus manos, es una deuda que la Liga recordará.", "Um para-sol da Liga, com varetas de chifre de gauro e a cobertura nas sete cores. Erguido, é sombra; estendido, é escudo; nas suas mãos, é uma dívida que a Liga vai lembrar.", "Зонт Лиги: спицы из рога гаура, купол семи цветов. Поднятый — это тень; выставленный вперёд — щит; в ваших руках — долг, который Лига запомнит.", "Парасоль Ліги: спиці з рогу гаура, купол семи кольорів. Піднятий — це тінь; виставлений уперед — щит; у ваших руках — борг, який Ліга запам'ятає."],
  "A blackiron helm with a red horsehair crest and a nasal bar, the last pass-warden of Shailagarh's. It has watched the eastern pass for sixty winters.": ["赤い馬毛の飾りと鼻当てのついたブラックアイアンの兜。シャイラガル最後の峠守りのものだ。六十の冬、東の峠を見張ってきた。", "붉은 말총 장식과 코 보호대가 달린 흑철 투구. 샤일라가르의 마지막 고개 파수꾼의 것이다. 예순 번의 겨울 동안 동쪽 고개를 지켜보았다.", "一顶黑铁头盔,饰有红色马鬃盔缨,带护鼻条,属于沙伊拉加尔的最后一任守关人。它守望东边的山口已有六十个冬天。", "一頂黑鐵頭盔,飾有紅色馬鬃盔纓,帶護鼻條,屬於沙伊拉加爾的最後一任守關人。它守望東邊的山口已有六十個冬天。", "Một chiếc mũ trụ sắt đen có chỏm lông đuôi ngựa đỏ và thanh che mũi, của người giữ đèo cuối cùng của Shailagarh. Nó đã canh chừng con đèo phía đông suốt sáu mươi mùa đông.", "Helm besi hitam berjambul bulu kuda merah dan berpelindung hidung, milik penjaga celah terakhir Shailagarh. Helm ini telah mengawasi celah timur selama enam puluh musim dingin.", "หมวกเกราะเหล็กดำประดับพู่ขนม้าสีแดงและมีแถบกันจมูก เป็นของผู้เฝ้าช่องเขาคนสุดท้ายของไศลครห์ มันเฝ้าดูช่องเขาฝั่งตะวันออกมาหกสิบฤดูหนาวแล้ว", "Kırmızı at kılı sorgucu ve burun siperi olan kara demir bir miğfer; Shailagarh'ın son geçit bekçisine ait. Altmış kış boyunca doğu geçidini gözledi.", "Un yelmo de hierro negro con penacho de crin roja y nasal, del último guardián del paso de Shailagarh. Ha vigilado el paso oriental durante sesenta inviernos.", "Um elmo de ferro negro com crista de crina vermelha e nasal, do último guardião do passo de Shailagarh. Vigiou o passo oriental por sessenta invernos.", "Шлем из чёрного железа с гребнем из красного конского волоса и наносником — шлем последнего стража перевала Шайлагарха. Он стерёг восточный перевал шестьдесят зим.", "Шолом із чорного заліза з гребенем із червоного кінського волосу й наносником — шолом останнього вартового перевалу Шайлагарха. Він стеріг східний перевал шістдесят зим."],
  "A sea-green stole with a pen worked at both ends: the Assembly of Ink and Coin's thanks to someone who read the ledger before believing the envoy.": ["両端にペンの刺繍が施された海緑色のストール。使節を信じる前に台帳を読んだ者への、墨と貨幣の議会からの礼の品。", "양 끝에 펜이 수놓인 바다색 숄. 사절의 말을 믿기 전에 장부부터 읽은 이에게 먹과 주화의 의회가 건넨 감사의 표시다.", "一条海绿色披肩,两端各绣着一支笔:墨与币议会的谢礼,送给那位在相信使节之前先读了账簿的人。", "一條海綠色披肩,兩端各繡著一支筆:墨與幣議會的謝禮,送給那位在相信使節之前先讀了帳簿的人。", "Một chiếc khăn choàng màu xanh biển, hai đầu thêu hình cây bút: lời cảm ơn của Hội đồng Mực và Xu dành cho người đã đọc sổ sách trước khi tin lời sứ giả.", "Selendang hijau laut bersulam pena di kedua ujungnya: tanda terima kasih Majelis Tinta dan Koin kepada orang yang membaca buku besar sebelum memercayai utusan.", "ผ้าคล้องไหล่สีเขียวน้ำทะเล ปักรูปปากกาไว้ทั้งสองปลาย: ของขอบคุณจากสภาหมึกและเหรียญแด่ผู้ที่อ่านสมุดบัญชีก่อนจะเชื่อทูต", "İki ucuna kalem işlenmiş deniz yeşili bir şal: Mürekkep ve Sikke Meclisi'nin, elçiye inanmadan önce defteri okuyan kişiye teşekkürü.", "Una estola verde mar con una pluma bordada en cada extremo: el agradecimiento de la Asamblea de Tinta y Moneda a quien leyó el libro de cuentas antes de creer al enviado.", "Uma estola verde-mar com uma pena bordada em cada ponta: o agradecimento da Assembleia da Tinta e da Moeda a quem leu o livro-caixa antes de acreditar no enviado.", "Палантин цвета морской волны с вышитым пером на обоих концах — благодарность Собрания Чернил и Монет тому, кто прочёл книгу записей, прежде чем поверить посланнику.", "Палантин кольору морської хвилі з вишитим пером на обох кінцях — подяка Зборів Чорнила й Монет тому, хто прочитав книгу записів, перш ніж повірити посланцеві."],
  "Seeds of the grove trees strung on palm fibre. Plant one where you were born, Grandmother Sukesh says, and something of the Deepgreen will grow there. Probably bamboo.": ["聖林の木々の種を椰子の繊維に通したもの。生まれた場所に一粒植えなさい、とスケシュ婆さまは言う。そうすれば深緑の森の何かがそこに育つ、と。たぶん竹だ。", "신성한 숲 나무들의 씨앗을 야자 섬유에 꿴 것. 태어난 곳에 하나를 심으면 깊은초록 숲의 무언가가 거기서 자랄 거라고 수케시 할머니는 말한다. 아마 대나무겠지.", "用棕榈纤维串起的圣林树种。苏凯什奶奶说,在你出生的地方种下一颗,深绿林的某样东西就会在那里生长。多半是竹子。", "用棕櫚纖維串起的聖林樹種。蘇凱什奶奶說,在你出生的地方種下一顆,深綠林的某樣東西就會在那裡生長。多半是竹子。", "Những hạt giống của cây rừng thiêng xâu trên sợi cọ. Bà Sukesh bảo, hãy trồng một hạt ở nơi bạn sinh ra, và một chút gì đó của Rừng Thẳm Xanh sẽ mọc lên ở đó. Chắc là tre.", "Biji-biji pohon hutan keramat yang dirangkai pada serat palem. Tanam satu di tempat kau dilahirkan, kata Nenek Sukesh, dan sesuatu dari Rimba Hijau Pekat akan tumbuh di sana. Mungkin bambu.", "เมล็ดของต้นไม้ในป่าศักดิ์สิทธิ์ ร้อยด้วยเส้นใยปาล์ม ยายสุเกศบอกว่า ให้ปลูกสักเมล็ดตรงที่คุณเกิด แล้วบางสิ่งจากป่าเขียวลึกจะงอกงามที่นั่น น่าจะเป็นไผ่", "Palmiye lifine dizilmiş koru ağacı tohumları. Sukesh Nine der ki, doğduğun yere bir tane ek, Derin Yeşillik'ten bir şey orada büyür. Muhtemelen bambu.", "Semillas de los árboles de la arboleda ensartadas en fibra de palma. Planta una donde naciste, dice la abuela Sukesh, y algo del Verdor Profundo crecerá allí. Probablemente bambú.", "Sementes das árvores do bosque enfiadas em fibra de palmeira. Plante uma onde você nasceu, diz a avó Sukesh, e algo do Verde Profundo vai crescer lá. Provavelmente bambu.", "Семена деревьев священной рощи, нанизанные на пальмовое волокно. Посади одно там, где родился, говорит бабушка Сукеш, и там вырастет что-то от Глубокой Зелени. Скорее всего, бамбук.", "Насіння дерев священного гаю, нанизане на пальмове волокно. Посади одне там, де народився, каже бабуся Сукеш, і там виросте щось від Глибокої Зелені. Найпевніше, бамбук."],
  "The ninth leaf of the Azhurak star chart: a river of stars across a sheet of beaten bark, bound in lapis thread. It belongs to the Archive, or to Tamesh, or to the sky.": ["アズラクの星図の第九葉。打ち延ばした樹皮の紙に星の川が流れ、瑠璃色の糸で綴じられている。文書館のものか、タメシュのものか、それとも空のものか。", "아주라크 성도의 아홉 번째 장. 두드려 편 나무껍질 위로 별의 강이 흐르고, 청금석 빛 실로 철해져 있다. 이것은 서고의 것이거나, 타메시의 것이거나, 하늘의 것이다.", "阿祖拉克星图的第九页:一条星河横贯一张捶打过的树皮纸,用青金石色的线装订。它属于档案馆,或属于塔梅什,或属于天空。", "阿祖拉克星圖的第九頁:一條星河橫貫一張捶打過的樹皮紙,用青金石色的線裝訂。它屬於檔案館,或屬於塔梅什,或屬於天空。", "Tờ thứ chín của bản đồ sao Azhurak: một dòng sông sao vắt ngang tấm vỏ cây đã đập mỏng, đóng bằng chỉ màu lưu ly. Nó thuộc về Văn khố, hoặc Tamesh, hoặc bầu trời.", "Lembar kesembilan peta bintang Azhurak: sungai bintang membentang di atas selembar kulit kayu tempaan, dijilid benang lapis. Ia milik Arsip, atau milik Tamesh, atau milik langit.", "แผ่นที่เก้าของแผนที่ดาวอาซูรัก: สายน้ำแห่งดวงดาวพาดผ่านแผ่นเปลือกไม้ที่ทุบจนแบน เย็บด้วยด้ายสีลาพิส มันเป็นของหอจดหมายเหตุ หรือของทาเมช หรือของท้องฟ้า", "Azhurak yıldız haritasının dokuzuncu yaprağı: dövülmüş ağaç kabuğundan bir tabakanın üzerinden akan bir yıldız nehri, lapis iplikle ciltlenmiş. Arşiv'e, ya da Tamesh'e, ya da gökyüzüne ait.", "La novena hoja del mapa estelar de Azhurak: un río de estrellas sobre una lámina de corteza batida, cosida con hilo de lapislázuli. Pertenece al Archivo, o a Tamesh, o al cielo.", "A nona folha do mapa estelar de Azhurak: um rio de estrelas sobre uma folha de casca batida, costurada com linha de lápis-lazúli. Pertence ao Arquivo, ou a Tamesh, ou ao céu.", "Девятый лист азуракской звёздной карты: река звёзд на листе битой коры, сшитом лазуритовой нитью. Он принадлежит Архиву, или Тамешу, или небу.", "Дев'ятий аркуш азуракської зоряної карти: ріка зірок на аркуші битої кори, зшитому лазуритовою ниткою. Він належить Архіву, або Тамешу, або небу."],
  "Shailagarh's licence to the loggers: pit props from the Deepgreen, signed by Lord Varanjit, with no grove stones drawn on it anywhere.": ["シャイラガルが木こりたちに与えた許可状。深緑の森から坑木を伐り出してよいとあり、ヴァランジット卿の署名がある。聖林の境石はどこにも描かれていない。", "샤일라가르가 벌목꾼들에게 내준 허가증. 깊은초록 숲에서 갱목을 베어 가도 좋다는 내용에 바란지트 경의 서명이 있다. 신성한 숲의 경계석은 어디에도 그려져 있지 않다.", "沙伊拉加尔发给伐木工的许可证:准许从深绿林砍伐矿坑支柱,由瓦兰吉特大人签署,上面哪儿都没画圣林界石。", "沙伊拉加爾發給伐木工的許可證:准許從深綠林砍伐礦坑支柱,由瓦蘭吉特大人簽署,上面哪兒都沒畫聖林界石。", "Giấy phép Shailagarh cấp cho thợ đốn gỗ: lấy gỗ chống hầm mỏ từ Rừng Thẳm Xanh, có chữ ký của Lãnh chúa Varanjit, và chẳng vẽ hòn đá ranh rừng thiêng nào ở bất cứ đâu.", "Izin Shailagarh untuk para penebang: tiang penyangga tambang dari Rimba Hijau Pekat, ditandatangani Tuan Varanjit, tanpa satu pun batu batas hutan keramat tergambar di mana pun.", "ใบอนุญาตที่ไศลครห์ออกให้คนตัดไม้: ให้ตัดไม้ค้ำเหมืองจากป่าเขียวลึก ลงนามโดยท่านวรัญชิต และไม่มีหินเขตป่าศักดิ์สิทธิ์วาดไว้ตรงไหนเลย", "Shailagarh'ın odunculara verdiği ruhsat: Derin Yeşillik'ten maden direği, Lord Varanjit imzalı; üzerinde hiçbir yerde tek bir koru taşı çizili değil.", "La licencia de Shailagarh a los leñadores: puntales de mina del Verdor Profundo, firmada por el señor Varanjit, sin una sola piedra de la arboleda dibujada por ningún lado.", "A licença de Shailagarh aos lenhadores: escoras de mina do Verde Profundo, assinada pelo senhor Varanjit, sem nenhuma pedra do bosque desenhada em lugar nenhum.", "Лицензия Шайлагарха лесорубам: крепёжный лес из Глубокой Зелени, подписана лордом Варанджитом, и нигде на ней не нарисовано ни одного камня священной рощи.", "Ліцензія Шайлагарха лісорубам: кріпильний ліс із Глибокої Зелені, підписана лордом Варанджитом, і ніде на ній не намальовано жодного каменя священного гаю."],
  "The dacoits' chief, in a red turban he's proud of and a caravan-master's stolen coat he's prouder of. He says he takes only from those who have too much. He decides who that is.": ["ダコイトの頭目。自慢の赤いターバンを巻き、それ以上に自慢の、隊商長から盗んだ上着を着ている。持ちすぎている者からしか奪わない、と本人は言う。誰がそうかを決めるのも本人だ。", "노상강도들의 두목. 자랑스러운 붉은 터번을 두르고, 그보다 더 자랑스러운, 대상 우두머리에게서 훔친 외투를 걸쳤다. 너무 많이 가진 자에게서만 빼앗는다고 한다. 그게 누구인지는 그가 정한다.", "劫匪的头目,头戴一顶他引以为傲的红头巾,身穿一件他更引以为傲的、从商队首领那儿抢来的外套。他说他只抢那些拥有太多的人。谁算拥有太多,由他说了算。", "劫匪的頭目,頭戴一頂他引以為傲的紅頭巾,身穿一件他更引以為傲的、從商隊首領那兒搶來的外套。他說他只搶那些擁有太多的人。誰算擁有太多,由他說了算。", "Thủ lĩnh bọn cướp đường, quấn chiếc khăn xếp đỏ mà hắn rất tự hào, khoác chiếc áo cướp của một trưởng đoàn lữ hành mà hắn còn tự hào hơn. Hắn bảo hắn chỉ lấy của những kẻ có quá nhiều. Ai là kẻ đó thì hắn quyết định.", "Kepala para begal, bersorban merah yang ia banggakan dan bermantel curian milik seorang pemimpin kafilah yang lebih ia banggakan lagi. Katanya ia hanya mengambil dari mereka yang punya terlalu banyak. Siapa mereka, dia yang menentukan.", "หัวหน้าโจรปล้นทาง โพกผ้าสีแดงที่เขาภูมิใจ และสวมเสื้อคลุมที่ขโมยมาจากนายกองคาราวานซึ่งเขาภูมิใจยิ่งกว่า เขาบอกว่าเขาปล้นเฉพาะคนที่มีมากเกินไป ส่วนใครคือคนพวกนั้น เขาเป็นคนตัดสิน", "Haydutların reisi; gurur duyduğu kırmızı bir sarık ve daha da çok gurur duyduğu, bir kervanbaşından çalınmış bir ceket giyiyor. Yalnızca fazlası olanlardan aldığını söylüyor. Kimin fazlası olduğuna da kendisi karar veriyor.", "El jefe de los bandoleros, con un turbante rojo del que está orgulloso y una casaca robada a un jefe de caravana de la que está todavía más orgulloso. Dice que solo roba a quienes tienen demasiado. Quiénes son, lo decide él.", "O chefe dos bandoleiros, com um turbante vermelho do qual se orgulha e um casaco roubado de um mestre de caravana do qual se orgulha ainda mais. Diz que só toma de quem tem demais. Quem são esses, ele decide.", "Главарь дакойтов в красном тюрбане, которым он гордится, и в краденом кафтане начальника каравана, которым гордится ещё больше. Говорит, что берёт только у тех, у кого слишком много. Кто они — решает он.", "Ватажок дакойтів у червоному тюрбані, яким він пишається, і в краденому каптані начальника каравану, яким пишається ще більше. Каже, що бере лише в тих, у кого забагато. Хто вони — вирішує він."],
  "A Copper Banner sergeant of twelve years' service, the badge cut off his coat, a battleaxe across his knees. He kept the books on everything, including how much he was owed.": ["十二年勤めた銅の旗の軍曹。上着の記章は切り取られ、膝には戦斧を横たえている。何もかも帳簿につけていた。自分がいくら払ってもらっていないかも含めて。", "12년을 복무한 구리 깃발의 하사. 외투의 휘장은 뜯겨 나갔고, 무릎에는 전투도끼를 걸쳐 두었다. 그는 모든 것을 장부에 적어 두었다. 자기가 받을 돈이 얼마인지까지.", "一名服役十二年的铜旗中士,外套上的徽记已被割掉,一把战斧横在膝上。他什么都记账,包括别人欠他多少。", "一名服役十二年的銅旗中士,外套上的徽記已被割掉,一把戰斧橫在膝上。他什麼都記帳,包括別人欠他多少。", "Một trung sĩ Cờ Đồng mười hai năm quân ngũ, phù hiệu đã bị cắt khỏi áo, một cây rìu chiến đặt ngang đầu gối. Hắn ghi sổ mọi thứ, kể cả việc mình còn bị nợ bao nhiêu.", "Sersan Panji Tembaga dengan dua belas tahun dinas, lencananya digunting dari mantelnya, kapak perang melintang di lututnya. Ia mencatat segalanya, termasuk berapa banyak yang masih menjadi haknya.", "จ่าแห่งธงทองแดงที่รับราชการมาสิบสองปี ตราถูกตัดออกจากเสื้อคลุม ขวานศึกพาดอยู่บนเข่า เขาจดบัญชีทุกอย่าง รวมถึงว่าตัวเองยังถูกค้างเงินอยู่เท่าไร", "On iki yıllık hizmeti olan bir Bakır Sancak çavuşu; arması ceketinden kesilmiş, dizlerinin üstünde bir savaş baltası. Her şeyin defterini tutardı, kendisine ne kadar borçlu olunduğu da dahil.", "Un sargento del Estandarte de Cobre con doce años de servicio, la insignia arrancada de la casaca y un hacha de guerra sobre las rodillas. Llevaba la cuenta de todo, incluido cuánto le debían.", "Um sargento do Estandarte de Cobre com doze anos de serviço, o emblema cortado do casaco e um machado de batalha sobre os joelhos. Mantinha registro de tudo, inclusive de quanto lhe deviam.", "Сержант Медного знамени с двенадцатью годами службы: эмблема срезана с мундира, на коленях боевой топор. Он вёл учёт всему, включая то, сколько ему задолжали.", "Сержант Мідного стягу з дванадцятьма роками служби: емблему зрізано з мундира, на колінах бойова сокира. Він вів облік усього, зокрема й того, скільки йому заборгували."],
  "A many-legged thing the colour of river mud, armoured in plates of dried silt, that came up the Stepwell's drains and found the dark agreed with it.": ["川泥の色をした多足の生き物。乾いた泥の板で身を固めている。階段井戸の排水路から這い上がってきて、暗闇が性に合うと知った。", "강 진흙 빛깔의 다리 많은 생물. 마른 토사 판으로 무장했다. 계단우물의 배수로를 타고 올라왔다가 어둠이 체질에 맞는다는 걸 알았다.", "一种多足的东西,颜色如同河泥,披着干淤泥结成的甲片。它顺着阶梯井的排水道爬上来,发现黑暗很合它的胃口。", "一種多足的東西,顏色如同河泥,披著乾淤泥結成的甲片。它順著階梯井的排水道爬上來,發現黑暗很合它的胃口。", "Một thứ nhiều chân màu bùn sông, khoác giáp bằng những mảng phù sa khô, đã bò lên theo cống thoát nước của Giếng Bậc và thấy bóng tối hợp với mình.", "Makhluk berkaki banyak sewarna lumpur sungai, berzirah lempengan lumpur kering, yang naik lewat saluran Sumur Tangga dan mendapati kegelapan cocok dengannya.", "สิ่งมีชีวิตหลายขาสีโคลนแม่น้ำ หุ้มเกราะด้วยแผ่นตะกอนแห้ง มันคลานขึ้นมาตามท่อระบายน้ำของบ่อขั้นบันได แล้วพบว่าความมืดถูกจริตกับมัน", "Nehir çamuru renginde, kurumuş balçık plakalarla zırhlanmış çok bacaklı bir şey; Basamaklı Kuyu'nun giderlerinden yukarı çıkmış ve karanlığın kendisine iyi geldiğini görmüş.", "Una cosa de muchas patas del color del barro del río, acorazada con placas de cieno seco, que subió por los desagües del Pozo Escalonado y descubrió que la oscuridad le sentaba bien.", "Uma coisa de muitas patas da cor da lama do rio, blindada com placas de lodo seco, que subiu pelos ralos do Poço de Degraus e descobriu que o escuro lhe caía bem.", "Многоногая тварь цвета речной грязи, закованная в пластины засохшего ила. Она поднялась по стокам Ступенчатого колодца и решила, что темнота ей по душе.", "Багатонога тварюка кольору річкового багна, закута в пластини засохлого мулу. Вона піднялася стоками Східчастого колодязя й вирішила, що темрява їй до душі."],
  "A serpent as long as the cistern is wide, its scales the green of deep tank water, a hood like a storm cloud. The Stepwell's builders carved it on the pillars, holding up the rain. It stopped holding it up.": ["貯水槽の幅ほどもある長い大蛇。鱗は深い貯水池の水の緑、頭巾は嵐雲のよう。階段井戸を築いた者たちは、雨を支えるその姿を柱に刻んだ。大蛇は支えるのをやめた。", "저수조의 너비만큼 긴 뱀. 비늘은 깊은 저수지 물빛의 초록이고, 목덜미의 두건은 폭풍 구름 같다. 계단우물을 지은 이들은 비를 떠받치는 그 모습을 기둥에 새겼다. 그 뱀은 떠받치기를 그만두었다.", "一条蛇,身长与蓄水池的宽度相当,鳞片是深池水的那种绿,颈兜如同一团暴风云。阶梯井的建造者把它刻在柱子上,托举着雨水。它不再托举了。", "一條蛇,身長與蓄水池的寬度相當,鱗片是深池水的那種綠,頸兜如同一團暴風雲。階梯井的建造者把它刻在柱子上,托舉著雨水。它不再托舉了。", "Một con rắn dài bằng bề ngang của bể chứa, vảy xanh màu nước hồ sâu, mang bành như đám mây giông. Những người xây Giếng Bậc đã khắc nó lên các cột, đang nâng đỡ cơn mưa. Nó đã thôi không nâng nữa.", "Ular sepanjang lebar waduk, sisiknya hijau seperti air telaga yang dalam, tudungnya bagaikan awan badai. Para pembangun Sumur Tangga memahatnya di pilar-pilar, sedang menyangga hujan. Ia berhenti menyangganya.", "นาคที่ยาวเท่าความกว้างของบ่อเก็บน้ำ เกล็ดสีเขียวดั่งน้ำในสระลึก แม่เบี้ยดั่งเมฆพายุ ผู้สร้างบ่อขั้นบันไดสลักมันไว้บนเสาในท่าค้ำฝนเอาไว้ แต่มันเลิกค้ำแล้ว", "Sarnıcın genişliği kadar uzun bir yılan; pulları derin havuz suyunun yeşili, başlığı bir fırtına bulutu gibi. Basamaklı Kuyu'yu yapanlar onu sütunlara yağmuru taşırken oydular. Taşımayı bıraktı.", "Una serpiente tan larga como ancha es la cisterna, con escamas del verde del agua honda de un estanque y una capucha como un nubarrón. Los constructores del Pozo Escalonado la tallaron en los pilares, sosteniendo la lluvia. Dejó de sostenerla.", "Uma serpente tão comprida quanto a cisterna é larga, com escamas do verde da água funda de um tanque e um capelo como uma nuvem de tempestade. Os construtores do Poço de Degraus a entalharam nos pilares, sustentando a chuva. Ela parou de sustentar.", "Змей длиной во всю ширину цистерны, с чешуёй цвета глубокой прудовой воды и капюшоном, похожим на грозовую тучу. Строители Ступенчатого колодца вырезали его на колоннах держащим дождь. Он перестал его держать.", "Змій завдовжки з ширину цистерни, з лускою кольору глибокої ставкової води й каптуром, схожим на грозову хмару. Будівничі Східчастого колодязя вирізьбили його на колонах таким, що тримає дощ. Він перестав його тримати."],
  "A Kharaveth caravan-master in a dusty headcloth, with twelve mules, four drivers, and a list of everything on every mule that he reads aloud when he's nervous.": ["埃まみれの頭巾をかぶったカラヴェスの隊商長。ラバ十二頭、御者四人、そしてどのラバに何を積んだかの一覧を抱えている。緊張すると、その一覧を声に出して読む。", "먼지투성이 머릿수건을 쓴 카라베스의 대상 우두머리. 노새 열두 마리, 마부 넷, 그리고 노새마다 실린 물건을 모조리 적은 목록이 있는데, 긴장하면 그 목록을 소리 내어 읽는다.", "一位卡拉维斯的商队首领,裹着落满灰尘的头巾,带着十二头骡子、四个赶骡人,还有一份每头骡子驮着什么的清单——他一紧张就大声念它。", "一位卡拉維斯的商隊首領,裹著落滿灰塵的頭巾,帶著十二頭騾子、四個趕騾人,還有一份每頭騾子馱著什麼的清單——他一緊張就大聲唸它。", "Một trưởng đoàn lữ hành người Kharaveth quấn khăn đầu bám đầy bụi, có mười hai con la, bốn người đánh la, và một bản danh sách mọi thứ trên từng con la mà ông đọc to mỗi khi lo lắng.", "Pemimpin kafilah dari Kharaveth berikat kepala berdebu, dengan dua belas bagal, empat kusir, dan daftar segala barang di setiap bagal yang ia bacakan keras-keras kalau sedang gugup.", "นายกองคาราวานชาวคาราเวธ โพกผ้าคลุมศีรษะที่เปื้อนฝุ่น มีล่อสิบสองตัว คนต้อนล่อสี่คน และรายการของทุกอย่างบนล่อทุกตัวที่เขาอ่านออกเสียงเวลาประหม่า", "Tozlu bir başörtüsü sarmış Kharavethli bir kervanbaşı; on iki katırı, dört sürücüsü ve her katırın üstündeki her şeyin bir listesi var, gerildiğinde de listeyi yüksek sesle okuyor.", "Un jefe de caravana de Kharaveth con un turbante polvoriento, doce mulas, cuatro arrieros y una lista de todo lo que lleva cada mula, que lee en voz alta cuando se pone nervioso.", "Um mestre de caravana de Kharaveth com um pano empoeirado na cabeça, doze mulas, quatro tropeiros e uma lista de tudo o que vai em cada mula, que ele lê em voz alta quando fica nervoso.", "Начальник каравана из Харавета в пыльном головном платке. При нём двенадцать мулов, четыре погонщика и список всего, что везёт каждый мул; когда он нервничает, то читает его вслух.", "Начальник каравану з Харавета в запорошеній головній хустці. При ньому дванадцять мулів, четверо погоничів і список усього, що везе кожен мул; коли він нервує, то читає його вголос."],
  "Talk to Caravan-master Iddo Saraf outside Khetmar's east gate.": ["ケトマルの東門の外にいる隊商長イッド・サラフと話す。", "케트마르 동문 밖에서 대상 우두머리 이도 사라프와 이야기한다.", "去克特马尔东门外,和商队首领伊多·萨拉夫谈谈。", "去克特馬爾東門外,和商隊首領伊多·薩拉夫談談。", "Nói chuyện với Trưởng đoàn lữ hành Iddo Saraf bên ngoài cổng đông Khetmar.", "Bicaralah dengan Pemimpin kafilah Iddo Saraf di luar gerbang timur Khetmar.", "คุยกับนายกองคาราวานอิดโด ซาราฟ นอกประตูตะวันออกของเคทมาร์", "Khetmar'ın doğu kapısının dışındaki Kervanbaşı Iddo Saraf ile konuş.", "Habla con el jefe de caravana Iddo Saraf, fuera de la puerta este de Khetmar.", "Fale com o mestre de caravana Iddo Saraf, fora do portão leste de Khetmar.", "Поговорить с начальником каравана Иддо Сарафом за восточными воротами Кетмара.", "Поговорити з начальником каравану Іддо Сарафом за східною брамою Кетмара."],
  "Outside Khetmar's east gate a caravan is waiting to go east into the Rain Country. Its master looks like he's counting the mules again.": ["ケトマルの東門の外で、東の雨の国へ向かう隊商が出発を待っている。隊商長はまたラバを数え直しているようだ。", "케트마르 동문 밖에서 한 대상이 동쪽 비의 나라로 떠나려고 기다리고 있다. 우두머리는 또 노새를 세고 있는 것 같다.", "克特马尔东门外,一支商队正等着向东进入雨之国。它的首领看样子又在数骡子了。", "克特馬爾東門外,一支商隊正等著向東進入雨之國。它的首領看樣子又在數騾子了。", "Bên ngoài cổng đông Khetmar, một đoàn lữ hành đang chờ lên đường về phía đông, vào Xứ Mưa. Ông trưởng đoàn trông như lại đang đếm lũ la lần nữa.", "Di luar gerbang timur Khetmar, sebuah kafilah menunggu untuk berangkat ke timur menuju Negeri Hujan. Pemimpinnya tampak sedang menghitung bagal-bagalnya lagi.", "นอกประตูตะวันออกของเคทมาร์ มีกองคาราวานรอออกเดินทางไปทางตะวันออกสู่แดนฝน นายกองดูเหมือนกำลังนับล่ออีกรอบ", "Khetmar'ın doğu kapısının dışında bir kervan, doğuya, Yağmur Ülkesi'ne gitmek için bekliyor. Kervanbaşı yine katırları sayıyor gibi görünüyor.", "Fuera de la puerta este de Khetmar, una caravana espera para partir hacia el este, al País de la Lluvia. Su jefe parece estar contando las mulas otra vez.", "Fora do portão leste de Khetmar, uma caravana espera para seguir para o leste, rumo ao País da Chuva. O mestre parece estar contando as mulas de novo.", "За восточными воротами Кетмара караван ждёт отправки на восток, в Страну дождей. Похоже, его начальник снова пересчитывает мулов.", "За східною брамою Кетмара караван чекає, щоб вирушити на схід, до Країни дощів. Схоже, його начальник знову перераховує мулів."],
  "Caravan-master Iddo Saraf will take his caravan over the Gate of Rains to Tirthali if somebody deals with the dacoits who've been stopping caravans there.": ["隊商長イッド・サラフは、雨の門で隊商を止めているダコイトを誰かが片付けてくれるなら、自分の隊商を雨の門越しにティルタリまで連れていくという。", "대상 우두머리 이도 사라프는 비의 문에서 대상들을 막아 세우는 노상강도들을 누군가 처리해 준다면, 자기 대상을 이끌고 비의 문을 넘어 티르탈리로 가겠다고 한다.", "商队头领伊多·萨拉夫说,只要有人收拾掉在雨之门拦截商队的劫匪,他就带商队翻过雨之门去提尔塔利。", "商隊頭領伊多·薩拉夫說,只要有人收拾掉在雨之門攔截商隊的劫匪,他就帶商隊翻過雨之門去提爾塔利。", "Trưởng đoàn buôn Iddo Saraf sẽ đưa đoàn buôn của ông qua Cổng Mưa tới Tirthali nếu có ai đó xử lý bọn cướp đường vẫn chặn các đoàn buôn ở đó.", "Kepala Kafilah Iddo Saraf mau membawa kafilahnya melewati Gerbang Hujan ke Tirthali kalau ada yang membereskan para begal yang selama ini menghadang kafilah di sana.", "หัวหน้ากองคาราวานอิดโด ซาราฟจะพากองคาราวานของเขาข้ามประตูแห่งสายฝนไปตีรถลี ถ้ามีใครสักคนจัดการพวกโจรปล้นทางที่คอยดักกองคาราวานอยู่ที่นั่น", "Kervanbaşı Iddo Saraf, orada kervanları durduran haydutların icabına bakan olursa kervanını Yağmur Kapısı'ndan geçirip Tirthali'ye götürecek.", "El jefe de caravana Iddo Saraf llevará su caravana por la Puerta de las Lluvias hasta Tirthali si alguien se encarga de los bandoleros que han estado deteniendo caravanas allí.", "O chefe de caravana Iddo Saraf levará sua caravana pelo Portão das Chuvas até Tirthali se alguém der um jeito nos bandoleiros que andam parando caravanas por lá.", "Начальник каравана Иддо Сараф поведёт свой караван через Врата Дождей в Тиртхали, если кто-нибудь разберётся с дакойтами, которые останавливают там караваны.", "Начальник каравану Іддо Сараф поведе свій караван через Браму Дощів до Тіртхалі, якщо хтось розбереться з дакойтами, що зупиняють там каравани."],
  "• Find the dacoits' chief in the hills by the Gate of Rains, and deal with him": ["• 雨の門のそばの丘でダコイトの頭目を見つけ、始末する", "• 비의 문 근처 언덕에서 노상강도 두목을 찾아 처리한다", "• 在雨之门旁的山里找到劫匪头目,解决掉他", "• 在雨之門旁的山裡找到劫匪頭目,解決掉他", "• Tìm thủ lĩnh bọn cướp đường trên đồi cạnh Cổng Mưa, và xử lý hắn", "• Temukan pemimpin begal di perbukitan dekat Gerbang Hujan, dan bereskan dia", "• ตามหาหัวหน้าโจรปล้นทางบนเนินเขาข้างประตูแห่งสายฝน แล้วจัดการเขาซะ", "• Yağmur Kapısı'nın yanındaki tepelerde haydutların reisini bul ve icabına bak", "• Encontrar al jefe de los bandoleros en las colinas junto a la Puerta de las Lluvias y encargarse de él", "• Encontrar o chefe dos bandoleiros nas colinas junto ao Portão das Chuvas e dar um jeito nele", "• Найти главаря дакойтов в холмах у Врат Дождей и разобраться с ним", "• Знайти ватажка дакойтів на пагорбах біля Брами Дощів і розібратися з ним"],
  "Red Jhanda, the dacoits' chief, is dead, and the caravan went through the Gate of Rains without losing a mule.": ["ダコイトの頭目、赤のジャンダは死に、隊商はラバ一頭失うことなく雨の門を抜けた。", "노상강도 두목 붉은 잔다는 죽었고, 대상은 노새 한 마리 잃지 않고 비의 문을 지나갔다.", "劫匪头目红詹达死了,商队一头骡子也没丢,就过了雨之门。", "劫匪頭目紅詹達死了,商隊一頭騾子也沒丟,就過了雨之門。", "Jhanda Đỏ, thủ lĩnh bọn cướp đường, đã chết, và đoàn buôn đi qua Cổng Mưa mà không mất một con la nào.", "Jhanda Merah, pemimpin para begal, sudah mati, dan kafilah melewati Gerbang Hujan tanpa kehilangan seekor bagal pun.", "จันดาแดง หัวหน้าโจรปล้นทาง ตายแล้ว และกองคาราวานก็ผ่านประตูแห่งสายฝนไปโดยไม่เสียล่อสักตัว", "Haydutların reisi Kızıl Jhanda öldü ve kervan tek bir katır kaybetmeden Yağmur Kapısı'ndan geçti.", "Jhanda el Rojo, el jefe de los bandoleros, ha muerto, y la caravana cruzó la Puerta de las Lluvias sin perder una sola mula.", "Jhanda Vermelho, o chefe dos bandoleiros, está morto, e a caravana passou pelo Portão das Chuvas sem perder uma única mula.", "Красный Джханда, главарь дакойтов, мёртв, и караван прошёл через Врата Дождей, не потеряв ни одного мула.", "Червоний Джханда, ватажок дакойтів, мертвий, і караван пройшов через Браму Дощів, не втративши жодного мула."],
  "• Meet the caravan at Tirthali: Ferrywarden Amul checks every crate that crosses the ford": ["• ティルタリで隊商と落ち合う。渡し守アムルは浅瀬を渡る木箱をひとつ残らず改める", "• 티르탈리에서 대상과 만난다. 나루지기 아물은 여울을 건너는 상자를 하나하나 다 검사한다", "• 到提尔塔利与商队会合:渡口守阿穆尔会检查每一个过浅滩的箱子", "• 到提爾塔利與商隊會合:渡口守阿穆爾會檢查每一個過淺灘的箱子", "• Gặp đoàn buôn ở Tirthali: Người giữ bến Amul kiểm tra mọi thùng hàng qua bến lội", "• Temui kafilah di Tirthali: Penjaga Penyeberangan Amul memeriksa setiap peti yang melintasi penyeberangan", "• ไปพบกองคาราวานที่ตีรถลี ผู้คุมท่าข้ามอมุลตรวจทุกลังที่ข้ามท่าข้าม", "• Kervanla Tirthali'de buluş: Geçit Bekçisi Amul sığlıktan geçen her sandığı kontrol eder", "• Reunirse con la caravana en Tirthali: el guardavado Amul revisa cada caja que cruza el vado", "• Encontrar a caravana em Tirthali: o guarda do vau Amul confere cada caixote que atravessa o vau", "• Встретить караван в Тиртхали: паромщик Амул проверяет каждый ящик, что переходит брод", "• Зустріти караван у Тіртхалі: поромник Амул перевіряє кожну скриню, що переходить брід"],
  "The caravan reached Tirthali. One crate held a figure of Azhurak stone, dug up and smuggled, and I decided where it went. QUEST COMPLETE!": ["隊商はティルタリに着いた。木箱のひとつには、掘り出されて密輸されたアズラクの石像が入っていた。その行き先は私が決めた。クエスト完了!", "대상은 티르탈리에 도착했다. 상자 하나에는 파내어 밀수된 아주라크의 석상이 들어 있었고, 그것이 어디로 갈지는 내가 정했다. 퀘스트 완료!", "商队到了提尔塔利。有一个箱子里装着一尊阿祖拉克石像,是盗掘后走私出来的,它的去处由我决定。任务完成!", "商隊到了提爾塔利。有一個箱子裡裝著一尊阿祖拉克石像,是盜掘後走私出來的,它的去處由我決定。任務完成!", "Đoàn buôn đã tới Tirthali. Một thùng hàng chứa một bức tượng đá Azhurak, bị đào trộm và buôn lậu, và tôi đã quyết định nó sẽ đi đâu. HOÀN THÀNH NHIỆM VỤ!", "Kafilah tiba di Tirthali. Salah satu peti berisi patung batu Azhurak, hasil galian dan selundupan, dan akulah yang memutuskan ke mana patung itu pergi. MISI SELESAI!", "กองคาราวานถึงตีรถลีแล้ว ลังหนึ่งบรรจุรูปสลักหินอาซูรักที่ถูกขุดขึ้นมาและลักลอบขนมา และฉันเป็นผู้ตัดสินว่ามันจะไปที่ไหน ภารกิจสำเร็จ!", "Kervan Tirthali'ye ulaştı. Sandıklardan birinde topraktan çıkarılıp kaçırılmış bir Azhurak taşı heykelcik vardı ve nereye gideceğine ben karar verdim. GÖREV TAMAMLANDI!", "La caravana llegó a Tirthali. Una caja contenía una figura de piedra de Azhurak, desenterrada y de contrabando, y yo decidí adónde iba. ¡MISIÓN CUMPLIDA!", "A caravana chegou a Tirthali. Um caixote trazia uma figura de pedra de Azhurak, desenterrada e contrabandeada, e eu decidi para onde ela ia. MISSÃO CUMPRIDA!", "Караван добрался до Тиртхали. В одном ящике лежала азуракская каменная фигура, выкопанная и провезённая контрабандой, и я решил, куда она отправится. ЗАДАНИЕ ВЫПОЛНЕНО!", "Караван дістався Тіртхалі. В одній скрині лежала азуракська кам'яна фігурка, викопана й провезена контрабандою, і я вирішив, куди вона піде. ЗАВДАННЯ ВИКОНАНО!"],
  "Queen Saumitra of Ilavarta is crowned at the Great Tank, and keeps her crown by keeping the tanks. The tanks are silting up.": ["イラヴァルタのサウミトラ女王は大貯水池で戴冠し、貯水池を守ることで王冠を守っている。その貯水池が、泥で埋まりつつある。", "일라바르타의 사우미트라 여왕은 대저수지에서 왕관을 받았고, 저수지를 지킴으로써 왕관을 지킨다. 그런데 저수지에 토사가 쌓이고 있다.", "伊拉瓦塔的萨乌米特拉女王在大水池加冕,靠守住水池来守住王冠。而水池正在淤塞。", "伊拉瓦塔的薩烏米特拉女王在大水池加冕,靠守住水池來守住王冠。而水池正在淤塞。", "Nữ hoàng Saumitra của Ilavarta được đăng quang tại Hồ Lớn, và giữ được vương miện nhờ giữ gìn các hồ chứa. Các hồ chứa đang bị bồi lấp.", "Ratu Saumitra dari Ilavarta dimahkotai di Telaga Agung, dan mempertahankan mahkotanya dengan merawat telaga-telaga. Telaga-telaga itu kini mendangkal oleh lumpur.", "ราชินีเสามิตราแห่งอิลาวรรตะได้รับการสวมมงกุฎที่สระใหญ่ และรักษามงกุฎไว้ได้ด้วยการรักษาสระทั้งหลาย แต่สระเหล่านั้นกำลังตื้นเขินด้วยตะกอน", "Ilavarta Kraliçesi Saumitra, Büyük Havuz'da taç giyer ve tacını havuzlara bakarak korur. Havuzlar milleniyor.", "La reina Saumitra de Ilavarta se corona en el Gran Estanque y conserva la corona conservando los estanques. Los estanques se están cegando de limo.", "A rainha Saumitra de Ilavarta é coroada no Grande Tanque e mantém a coroa mantendo os tanques. Os tanques estão se assoreando.", "Королеву Илаварты Саумитру венчают на Великом пруду, и корону она сохраняет, сберегая пруды. А пруды заиливаются.", "Королеву Ілаварти Саумітру коронують на Великому ставу, і корону вона зберігає, бережучи стави. А стави замулюються."],
  "The tanks are a third full of silt. The Queen's engineers want the temple's offerings to dig it out; the temple's treasurers say the offerings are the river's. The Queen asked me to find out which of them is right.": ["貯水池は三分の一が泥で埋まっている。女王の技師たちは寺院への供物を浚渫に回したがり、寺院の会計役たちは供物は川のものだと言う。女王は、どちらが正しいのか確かめてくれと私に頼んだ。", "저수지는 3분의 1이 토사로 차 있다. 여왕의 기술자들은 사원의 공물로 그것을 파내고 싶어 하고, 사원의 재무관들은 공물은 강의 것이라고 한다. 여왕은 나에게 누가 옳은지 알아봐 달라고 했다.", "水池里三分之一都是淤泥。女王的工程师们想用神庙的供奉来清淤;神庙的司库们却说供奉是属于河的。女王请我查清楚他们谁对。", "水池裡三分之一都是淤泥。女王的工程師們想用神廟的供奉來清淤;神廟的司庫們卻說供奉是屬於河的。女王請我查清楚他們誰對。", "Các hồ chứa đã đầy một phần ba bùn. Các kỹ sư của Nữ hoàng muốn dùng đồ cúng của đền để nạo vét; các thủ quỹ của đền thì nói đồ cúng là của dòng sông. Nữ hoàng nhờ tôi tìm xem bên nào đúng.", "Telaga-telaga sudah sepertiga terisi lumpur. Para insinyur Ratu ingin persembahan kuil dipakai untuk mengeruknya; para bendahara kuil bilang persembahan itu milik sungai. Ratu memintaku mencari tahu siapa yang benar.", "สระทั้งหลายมีตะกอนอยู่หนึ่งในสามแล้ว วิศวกรของราชินีอยากเอาของถวายของวัดมาใช้ขุดลอก ส่วนเหรัญญิกของวัดบอกว่าของถวายเป็นของแม่น้ำ ราชินีขอให้ฉันไปสืบว่าฝ่ายไหนถูก", "Havuzların üçte biri milla dolu. Kraliçe'nin mühendisleri mili kazımak için tapınağın adaklarını istiyor; tapınağın haznedarları ise adakların nehre ait olduğunu söylüyor. Kraliçe hangisinin haklı olduğunu bulmamı istedi.", "Los estanques están llenos de limo hasta un tercio. Los ingenieros de la reina quieren las ofrendas del templo para dragarlo; los tesoreros del templo dicen que las ofrendas son del río. La reina me pidió que averiguara quién tiene razón.", "Os tanques estão com um terço de lodo. Os engenheiros da rainha querem as oferendas do templo para dragá-lo; os tesoureiros do templo dizem que as oferendas são do rio. A rainha me pediu para descobrir qual dos dois tem razão.", "Пруды на треть забиты илом. Инженеры королевы хотят пустить храмовые подношения на расчистку; храмовые казначеи говорят, что подношения принадлежат реке. Королева попросила меня выяснить, кто из них прав.", "Стави на третину забиті мулом. Інженери королеви хочуть пустити храмові пожертви на розчищення; храмові скарбники кажуть, що пожертви належать річці. Королева попросила мене з'ясувати, хто з них має рацію."],
  "Both of them are right: the silt comes down from the forests the highland loggers have cut, and the Great Stepwell's old sluice, that used to flush the Great Tank, has been jammed shut for years.": ["どちらも正しい。泥は高地の木こりたちが切り開いた森から流れてきており、かつて大貯水池を洗い流していた大階段井戸の古い水門は、何年も閉じたまま動かなくなっている。", "둘 다 옳다. 토사는 고지대 벌목꾼들이 베어 낸 숲에서 흘러 내려오고, 예전에 대저수지를 씻어 내던 대계단우물의 낡은 수문은 몇 년째 닫힌 채 꽉 막혀 있다.", "他们俩都对:淤泥是从高地伐木工砍过的森林里冲下来的,而大阶梯井那道过去用来冲刷大水池的旧水闸,已经卡死关闭好些年了。", "他們倆都對:淤泥是從高地伐木工砍過的森林裡沖下來的,而大階梯井那道過去用來沖刷大水池的舊水閘,已經卡死關閉好些年了。", "Cả hai đều đúng: bùn trôi xuống từ những cánh rừng mà thợ đốn gỗ vùng cao đã chặt, và cửa xả cũ của Giếng Bậc Lớn, vốn dùng để xả rửa Hồ Lớn, đã bị kẹt đóng nhiều năm nay.", "Keduanya benar: lumpurnya turun dari hutan yang sudah ditebangi para penebang dataran tinggi, dan pintu air tua Sumur Tangga Agung, yang dulu membilas Telaga Agung, sudah macet tertutup bertahun-tahun.", "ทั้งสองฝ่ายถูก ตะกอนไหลลงมาจากป่าที่คนตัดไม้บนที่สูงโค่นไป และประตูระบายน้ำเก่าของบ่อขั้นบันไดใหญ่ที่เคยใช้ชะล้างสระใหญ่ ก็ติดตายปิดอยู่มาหลายปีแล้ว", "İkisi de haklı: mil, yayla tomrukçularının kestiği ormanlardan aşağı iniyor ve bir zamanlar Büyük Havuz'u yıkayan Büyük Basamaklı Kuyu'nun eski savağı yıllardır kapalı halde sıkışmış duruyor.", "Los dos tienen razón: el limo baja de los bosques que han talado los leñadores de las tierras altas, y la vieja compuerta del Gran Pozo Escalonado, que antes limpiaba el Gran Estanque, lleva años atascada y cerrada.", "Os dois têm razão: o lodo desce das florestas que os lenhadores das terras altas derrubaram, e a velha comporta do Grande Poço de Degraus, que antes lavava o Grande Tanque, está emperrada e fechada há anos.", "Правы оба: ил сносит из лесов, которые вырубили горные лесорубы, а старый шлюз Великого ступенчатого колодца, что когда-то промывал Великий пруд, уже много лет заклинен наглухо.", "Мають рацію обоє: мул зносить із лісів, які вирубали гірські лісоруби, а старий шлюз Великого східчастого колодязя, що колись промивав Великий став, уже багато років заклинений намертво."],
  "The sluice turned, and the Great Tank's water ran clean through the Stepwell for the first time in a generation.": ["水門が回り、大貯水池の水が一世代ぶりに澄んだまま階段井戸を流れ抜けた。", "수문이 돌아갔고, 대저수지의 물이 한 세대 만에 처음으로 맑게 계단우물을 흘러 지나갔다.", "水闸转开了,大水池的水一代人以来第一次清清地流过了阶梯井。", "水閘轉開了,大水池的水一代人以來第一次清清地流過了階梯井。", "Cửa xả đã quay, và nước Hồ Lớn chảy trong veo qua Giếng Bậc lần đầu tiên sau cả một thế hệ.", "Pintu air berputar, dan air Telaga Agung mengalir jernih melewati Sumur Tangga untuk pertama kalinya dalam satu generasi.", "ประตูระบายน้ำหมุนแล้ว และน้ำของสระใหญ่ก็ไหลผ่านบ่อขั้นบันไดอย่างใสสะอาดเป็นครั้งแรกในรอบหนึ่งชั่วคน", "Savak döndü ve Büyük Havuz'un suyu bir kuşaktır ilk kez Basamaklı Kuyu'dan berrak aktı.", "La compuerta giró, y el agua del Gran Estanque corrió limpia por el Pozo Escalonado por primera vez en una generación.", "A comporta girou, e a água do Grande Tanque correu limpa pelo Poço de Degraus pela primeira vez em uma geração.", "Шлюз повернулся, и вода Великого пруда впервые за целое поколение чисто прошла через Ступенчатый колодец.", "Шлюз повернувся, і вода Великого ставу вперше за ціле покоління чисто пройшла крізь Східчастий колодязь."],
  "I told the Queen what the tank's measure, the Stepwell and the forests said. The temple pays to replant upstream, the crown pays to dig, and both of them complain about it. QUEST COMPLETE!": ["貯水池の水位標と階段井戸と森が語ったことを、女王に伝えた。寺院は上流の植林の費用を、王家は浚渫の費用を払い、どちらもそれに文句を言っている。クエスト完了!", "저수지의 수위표와 계단우물과 숲이 말해 준 것을 여왕에게 전했다. 사원은 상류에 나무를 다시 심는 비용을, 왕실은 파내는 비용을 대고, 둘 다 그 일로 불평한다. 퀘스트 완료!", "我把水池的水位标、阶梯井和森林告诉我的事都禀报了女王。神庙出钱在上游重新造林,王室出钱清淤,双方都为此抱怨。任务完成!", "我把水池的水位標、階梯井和森林告訴我的事都稟報了女王。神廟出錢在上游重新造林,王室出錢清淤,雙方都為此抱怨。任務完成!", "Tôi kể với Nữ hoàng những gì thước đo của hồ, Giếng Bậc và những cánh rừng đã nói. Đền trả tiền trồng lại rừng ở thượng nguồn, vương triều trả tiền nạo vét, và cả hai đều phàn nàn về chuyện đó. HOÀN THÀNH NHIỆM VỤ!", "Aku memberi tahu Ratu apa yang dikatakan takaran telaga, Sumur Tangga, dan hutan-hutan itu. Kuil membayar penanaman kembali di hulu, mahkota membayar pengerukan, dan keduanya menggerutu soal itu. MISI SELESAI!", "ฉันเล่าให้ราชินีฟังว่าเครื่องวัดระดับน้ำของสระ บ่อขั้นบันได และป่าบอกอะไรบ้าง วัดจ่ายค่าปลูกป่าคืนที่ต้นน้ำ ราชสำนักจ่ายค่าขุดลอก และทั้งสองฝ่ายก็บ่นเรื่องนี้ ภารกิจสำเร็จ!", "Havuzun ölçeğinin, Basamaklı Kuyu'nun ve ormanların ne dediğini Kraliçe'ye anlattım. Yukarı havzada yeniden ağaçlandırmayı tapınak, kazıyı taht ödüyor ve ikisi de bundan yakınıyor. GÖREV TAMAMLANDI!", "Le conté a la reina lo que decían la medida del estanque, el Pozo Escalonado y los bosques. El templo paga la reforestación río arriba, la corona paga el dragado, y los dos se quejan. ¡MISIÓN CUMPLIDA!", "Contei à rainha o que diziam a medida do tanque, o Poço de Degraus e as florestas. O templo paga o replantio rio acima, a coroa paga a dragagem, e os dois reclamam disso. MISSÃO CUMPRIDA!", "Я рассказал королеве, что говорят мерный знак пруда, Ступенчатый колодец и леса. Храм платит за новые посадки выше по реке, корона — за расчистку, и оба на это жалуются. ЗАДАНИЕ ВЫПОЛНЕНО!", "Я розповів королеві, що кажуть мірна позначка ставу, Східчастий колодязь і ліси. Храм платить за нові насадження вище за течією, корона — за розчищення, і обоє на це скаржаться. ЗАВДАННЯ ВИКОНАНО!"],
  "The League of Seven Parasols is meeting in the Mandapa, and Speaker Hemavati looks like someone holding seven arguments at once.": ["七つの日傘同盟がマンダパで会合を開いており、ヘマヴァティ議長は七つの言い争いを一度に抱えている人のような顔をしている。", "일곱 일산 동맹이 만다파에서 회합 중이고, 헤마바티 의장은 일곱 개의 논쟁을 한꺼번에 붙들고 있는 사람 같은 얼굴이다.", "七华盖同盟正在曼达帕开会,赫玛瓦蒂议长看上去就像一个人同时攥着七场争论。", "七華蓋同盟正在曼達帕開會,赫瑪瓦蒂議長看上去就像一個人同時攥著七場爭論。", "Liên minh Bảy Lọng đang họp ở Mandapa, và Phát ngôn nhân Hemavati trông như người đang ôm cùng lúc bảy cuộc tranh cãi.", "Liga Tujuh Payung sedang bersidang di Mandapa, dan Juru Bicara Hemavati tampak seperti orang yang memegang tujuh perdebatan sekaligus.", "สันนิบาตเจ็ดฉัตรกำลังประชุมกันในมณฑป และประธานเหมาวดีดูเหมือนคนที่กำลังถือข้อพิพาทเจ็ดเรื่องไว้พร้อมกัน", "Yedi Şemsiye Birliği Mandapa'da toplanıyor ve Sözcü Hemavati aynı anda yedi tartışmayı tutan birine benziyor.", "La Liga de los Siete Parasoles se reúne en el Mandapa, y la Portavoz Hemavati parece alguien que sostiene siete discusiones a la vez.", "A Liga dos Sete Para-sóis está reunida no Mandapa, e a Porta-voz Hemavati parece alguém segurando sete discussões ao mesmo tempo.", "Лига Семи Зонтов заседает в Мандапе, и у Глашатая Хемавати вид человека, который держит в руках семь споров разом.", "Ліга Семи Парасолів засідає в Мандапі, і Речниця Хемаваті має вигляд людини, що тримає в руках сім суперечок водночас."],
  "The League's toll books say the Queen's bridge at Sarovan has doubled its toll on League carts. The League means to say so in the Mandapa, which would be the end of talking. The Speaker wants to know if it's true first.": ["同盟の通行税帳によれば、サロヴァンにある女王の橋が同盟の荷車への通行税を倍にしたという。同盟はそれをマンダパで言い立てるつもりで、そうなれば話し合いは終わりだ。議長はその前に、それが本当かどうか知りたがっている。", "동맹의 통행세 장부에 따르면 사로반에 있는 여왕의 다리가 동맹 수레에 매기는 통행세를 두 배로 올렸다. 동맹은 이를 만다파에서 공표할 작정인데, 그러면 대화는 끝이다. 의장은 그 전에 그게 사실인지 알고 싶어 한다.", "同盟的通行税账簿上说,女王在萨罗万的桥把对同盟车辆收的过路税翻了一倍。同盟打算在曼达帕把这事挑明,那样一来就再也谈不下去了。议长想先弄清楚这是不是真的。", "同盟的通行稅帳簿上說,女王在薩羅萬的橋把對同盟車輛收的過路稅翻了一倍。同盟打算在曼達帕把這事挑明,那樣一來就再也談不下去了。議長想先弄清楚這是不是真的。", "Sổ thu phí của Liên minh ghi rằng cây cầu của Nữ hoàng ở Sarovan đã tăng gấp đôi phí qua cầu đối với xe của Liên minh. Liên minh định nói thẳng điều đó ở Mandapa, mà như thế thì hết đường đàm phán. Phát ngôn nhân muốn biết trước xem có thật không.", "Buku tol Liga menyebut jembatan Ratu di Sarovan telah menggandakan tarif tol untuk gerobak Liga. Liga berniat mengatakannya di Mandapa, dan itu berarti akhir dari perundingan. Juru Bicara ingin tahu dulu apakah itu benar.", "สมุดบัญชีค่าผ่านทางของสันนิบาตระบุว่าสะพานของราชินีที่สโรวันขึ้นค่าผ่านทางสำหรับเกวียนของสันนิบาตเป็นสองเท่า สันนิบาตตั้งใจจะพูดเรื่องนี้ในมณฑป ซึ่งนั่นจะเป็นจุดจบของการเจรจา ประธานอยากรู้ก่อนว่ามันจริงหรือไม่", "Birlik'in geçiş ücreti defterlerine göre Kraliçe'nin Sarovan'daki köprüsü Birlik arabalarından aldığı ücreti iki katına çıkarmış. Birlik bunu Mandapa'da dile getirmeye niyetli, bu da konuşmanın sonu olur. Sözcü önce bunun doğru olup olmadığını öğrenmek istiyor.", "Los libros de peajes de la Liga dicen que el puente de la reina en Sarovan ha doblado el peaje a los carros de la Liga. La Liga piensa decirlo en el Mandapa, y eso acabaría con cualquier conversación. La Portavoz quiere saber antes si es cierto.", "Os livros de pedágio da Liga dizem que a ponte da rainha em Sarovan dobrou o pedágio das carroças da Liga. A Liga pretende dizer isso no Mandapa, o que seria o fim da conversa. A Porta-voz quer saber antes se é verdade.", "По пошлинным книгам Лиги выходит, что мост королевы в Сароване удвоил пошлину для повозок Лиги. Лига намерена заявить об этом в Мандапе, и на этом разговоры закончатся. Глашатай хочет сначала узнать, правда ли это.", "За митними книгами Ліги виходить, що міст королеви в Саровані подвоїв мито для возів Ліги. Ліга має намір заявити про це в Мандапі, і на цьому розмови скінчаться. Речниця хоче спершу дізнатися, чи це правда."],
  "The doubled toll is in the clerk's books and nowhere else: he was paid to write it in. Paid in Gilded Court silver.": ["倍になった通行税は書記の帳簿の中にしかない。彼は金をもらってそれを書き込んだのだ。金色の宮廷の銀貨で。", "두 배가 된 통행세는 서기의 장부에만 있고 다른 어디에도 없다. 그는 돈을 받고 그걸 써넣었다. 황금 궁정의 은화로.", "翻倍的过路税只存在于书记的账簿里,别处都没有:有人花钱让他写进去的。付的是镀金宫廷的银子。", "翻倍的過路稅只存在於書記的帳簿裡,別處都沒有:有人花錢讓他寫進去的。付的是鍍金宮廷的銀子。", "Mức phí gấp đôi chỉ có trong sổ của thư lại, ngoài ra không ở đâu cả: hắn được trả tiền để ghi nó vào. Trả bằng bạc của Triều Mạ Vàng.", "Tol yang berlipat dua itu hanya ada di buku si juru tulis, tidak di mana pun lagi: ia dibayar untuk menuliskannya. Dibayar dengan perak Istana Bersepuh.", "ค่าผ่านทางสองเท่านั้นมีอยู่ในสมุดของเสมียนเท่านั้น ไม่มีที่อื่นเลย เขาได้รับเงินให้เขียนมันลงไป จ่ายด้วยเหรียญเงินของราชสำนักปิดทอง", "İki katına çıkan ücret kâtibin defterlerinde var, başka hiçbir yerde yok: onu yazması için para almış. Hem de Yaldızlı Saray gümüşüyle.", "El peaje doblado está en los libros del escribano y en ningún otro sitio: le pagaron por anotarlo. Le pagaron en plata de la Corte Dorada.", "O pedágio dobrado está nos livros do escrivão e em nenhum outro lugar: pagaram para ele escrevê-lo. Pagaram em prata da Corte Dourada.", "Удвоенная пошлина есть в книгах писаря и больше нигде: ему заплатили, чтобы он её вписал. Заплатили серебром Позолоченного двора.", "Подвоєне мито є в книгах писаря і більше ніде: йому заплатили, щоб він його вписав. Заплатили сріблом Позолоченого двору."],
  "Factor Ozren Vale admits it: a quarrel between the League and Ilavarta keeps rice prices high, and the Gilded Court buys the rice.": ["代理商オズレン・ヴェイルは認めた。同盟とイラヴァルタの争いが米の値を高く保ち、その米を金色の宮廷が買い付けているのだと。", "중개인 오즈렌 베일이 인정한다. 동맹과 일라바르타 사이의 다툼이 쌀값을 높게 유지시키고, 그 쌀을 황금 궁정이 사들인다는 것이다.", "代理商奥兹伦·维尔承认了:同盟和伊拉瓦塔一吵架,米价就居高不下,而收购这些米的正是镀金宫廷。", "代理商奧茲倫·維爾承認了:同盟和伊拉瓦塔一吵架,米價就居高不下,而收購這些米的正是鍍金宮廷。", "Đại lý Ozren Vale đã thừa nhận: một cuộc tranh chấp giữa Liên minh và Ilavarta giữ giá gạo ở mức cao, và Triều Mạ Vàng là bên mua gạo.", "Agen Ozren Vale mengakuinya: pertikaian antara Liga dan Ilavarta membuat harga beras tetap tinggi, dan Istana Bersepuh yang membeli berasnya.", "ตัวแทนโอซเรน เวลยอมรับ การทะเลาะกันระหว่างสันนิบาตกับอิลาวรรตะทำให้ราคาข้าวสูงอยู่เสมอ และราชสำนักปิดทองเป็นผู้ซื้อข้าว", "Kâhya Ozren Vale itiraf ediyor: Birlik ile Ilavarta arasındaki bir kavga pirinç fiyatlarını yüksek tutuyor ve pirinci Yaldızlı Saray satın alıyor.", "El factor Ozren Vale lo admite: una disputa entre la Liga e Ilavarta mantiene altos los precios del arroz, y la Corte Dorada compra el arroz.", "O feitor Ozren Vale admite: uma briga entre a Liga e Ilavarta mantém o preço do arroz alto, e a Corte Dourada compra o arroz.", "Фактор Озрен Вейл признаётся: ссора между Лигой и Илавартой держит цены на рис высокими, а рис скупает Позолоченный двор.", "Фактор Озрен Вейл визнає: сварка між Лігою та Ілавартою тримає ціни на рис високими, а рис скуповує Позолочений двір."],
  "The Speaker read the true figures in the Mandapa. Seven rulers agreed, for once, and the Gilded Court's factor is going home. QUEST COMPLETE!": ["議長はマンダパで本当の数字を読み上げた。七人の君主が珍しく意見を一致させ、金色の宮廷の代理商は国へ帰ることになった。クエスト完了!", "의장이 만다파에서 진짜 수치를 읽었다. 일곱 군주가 웬일로 뜻을 모았고, 황금 궁정의 중개인은 고향으로 돌아간다. 퀘스트 완료!", "议长在曼达帕宣读了真实的数字。七位统治者难得意见一致,镀金宫廷的代理商也要回老家了。任务完成!", "議長在曼達帕宣讀了真實的數字。七位統治者難得意見一致,鍍金宮廷的代理商也要回老家了。任務完成!", "Phát ngôn nhân đã đọc những con số thật ở Mandapa. Bảy người cai trị hiếm hoi đồng lòng một lần, và đại lý của Triều Mạ Vàng sắp phải về nhà. HOÀN THÀNH NHIỆM VỤ!", "Juru Bicara membacakan angka yang sebenarnya di Mandapa. Tujuh penguasa sepakat, untuk sekali ini, dan agen Istana Bersepuh akan pulang. MISI SELESAI!", "ประธานอ่านตัวเลขที่แท้จริงในมณฑป ผู้ปกครองทั้งเจ็ดเห็นพ้องกันเสียทีหนึ่ง และตัวแทนของราชสำนักปิดทองก็กำลังจะกลับบ้าน ภารกิจสำเร็จ!", "Sözcü gerçek rakamları Mandapa'da okudu. Yedi hükümdar bu sefere mahsus anlaştı ve Yaldızlı Saray'ın kâhyası evine dönüyor. GÖREV TAMAMLANDI!", "La Portavoz leyó las cifras verdaderas en el Mandapa. Siete gobernantes se pusieron de acuerdo, para variar, y el factor de la Corte Dorada se vuelve a casa. ¡MISIÓN CUMPLIDA!", "A Porta-voz leu os números verdadeiros no Mandapa. Sete governantes concordaram, para variar, e o feitor da Corte Dourada está voltando para casa. MISSÃO CUMPRIDA!", "Глашатай зачитала в Мандапе настоящие цифры. Семь правителей, для разнообразия, сошлись во мнении, а фактор Позолоченного двора едет домой. ЗАДАНИЕ ВЫПОЛНЕНО!", "Речниця зачитала в Мандапі справжні цифри. Семеро правителів, для різноманітності, дійшли згоди, а фактор Позолоченого двору їде додому. ЗАВДАННЯ ВИКОНАНО!"],
  "Lord Varanjit holds the passes. Somebody, it seems, is holding one of them back.": ["ヴァランジット卿は峠を押さえている。どうやら誰かが、そのひとつを押さえ込んでいるらしい。", "바란지트 경은 고갯길들을 쥐고 있다. 그런데 누군가가 그중 하나를 붙들고 있는 모양이다.", "瓦兰吉特大人把守着各处山口。看来,有人把其中一处给扣下了。", "瓦蘭吉特大人把守著各處山口。看來,有人把其中一處給扣下了。", "Lãnh chúa Varanjit nắm giữ các con đèo. Có vẻ như ai đó đang giữ rịt một con đèo trong số đó.", "Tuan Varanjit menguasai celah-celah gunung. Rupanya, ada yang sedang menguasai salah satunya untuk diri sendiri.", "ท่านวรัญชิตยึดครองช่องเขาทั้งหลาย ดูเหมือนว่าจะมีใครบางคนยึดช่องเขาหนึ่งในนั้นไว้เสียเอง", "Geçitleri Lord Varanjit tutuyor. Görünüşe bakılırsa birileri de geçitlerden birini tutup bırakmıyor.", "El señor Varanjit domina los pasos. Alguien, al parecer, se está quedando con uno de ellos.", "O senhor Varanjit controla os desfiladeiros. Alguém, ao que parece, está segurando um deles.", "Лорд Варанджит держит перевалы. Кто-то, похоже, придерживает один из них для себя.", "Лорд Варанджит тримає перевали. Хтось, схоже, притримує один із них для себе."],
  "Deserters from the Copper Banner companies have taken the high toll-house on the eastern pass and charge their own toll. Lord Varanjit wants them gone.": ["銅の旗の兵団から逃げた脱走兵たちが東の峠の高地の関所を占拠し、勝手に通行税を取っている。ヴァランジット卿は彼らを追い払いたがっている。", "구리 깃발 부대에서 도망친 탈영병들이 동쪽 고갯길의 고지대 통행세 징수소를 차지하고 제멋대로 통행세를 걷고 있다. 바란지트 경은 그들을 없애고 싶어 한다.", "铜旗连队的逃兵占了东边山口高处的收费站,自己收起了过路税。瓦兰吉特大人要把他们赶走。", "銅旗連隊的逃兵占了東邊山口高處的收費站,自己收起了過路稅。瓦蘭吉特大人要把他們趕走。", "Lính đào ngũ từ các đại đội Cờ Đồng đã chiếm trạm thu thuế trên cao ở con đèo phía đông và tự thu phí riêng. Lãnh chúa Varanjit muốn chúng biến đi.", "Para desertir dari kompi-kompi Panji Tembaga telah merebut pos tol atas di celah timur dan memungut tol mereka sendiri. Tuan Varanjit ingin mereka disingkirkan.", "ทหารหนีทัพจากกองร้อยธงทองแดงยึดด่านเก็บค่าผ่านทางบนเขาที่ช่องเขาตะวันออก และเก็บค่าผ่านทางกันเอง ท่านวรัญชิตต้องการให้พวกมันไปเสีย", "Bakır Sancak bölüklerinden kaçan firariler doğu geçidindeki yüksek gişe evini ele geçirmiş ve kendi geçiş ücretlerini alıyorlar. Lord Varanjit onların gitmesini istiyor.", "Unos desertores de las compañías del Estandarte de Cobre han tomado el alto puesto de peaje del paso oriental y cobran su propio peaje. El señor Varanjit quiere que desaparezcan.", "Desertores das companhias do Estandarte de Cobre tomaram o posto de pedágio do alto, no desfiladeiro leste, e cobram o próprio pedágio. O senhor Varanjit quer que eles sumam.", "Дезертиры из рот Медного знамени заняли верхнюю заставу на восточном перевале и взимают собственную пошлину. Лорд Варанджит хочет от них избавиться.", "Дезертири з рот Мідного стягу захопили верхню заставу на східному перевалі й беруть власне мито. Лорд Варанджит хоче їх позбутися."],
  "The deserters' paybook says they haven't been paid since spring: the Lord's paymaster pays the Marshal, and the Marshal's agent pays the companies, and somewhere between the two the money stops.": ["脱走兵たちの給金帳によれば、彼らは春から給金を受け取っていない。卿の主計官が元帥に払い、元帥の代理人が兵団に払う。そしてその間のどこかで、金が止まっている。", "탈영병들의 급료 장부에 따르면 그들은 봄 이후로 급료를 받지 못했다. 영주의 경리관이 원수에게 지급하고, 원수의 대리인이 부대에 지급하는데, 그 둘 사이 어딘가에서 돈이 멈춘다.", "逃兵的军饷簿上写着,他们从春天起就没领到过饷:大人的发饷官把钱付给元帅,元帅的代理人再付给各连队,而钱在这两者之间的某处就停住了。", "逃兵的軍餉簿上寫著,他們從春天起就沒領到過餉:大人的發餉官把錢付給元帥,元帥的代理人再付給各連隊,而錢在這兩者之間的某處就停住了。", "Sổ lương của bọn đào ngũ ghi rằng chúng chưa được trả lương từ mùa xuân: quan phát lương của Lãnh chúa trả cho Thống chế, người đại diện của Thống chế trả cho các đại đội, và ở đâu đó giữa hai bên, tiền dừng lại.", "Buku gaji para desertir menyebut mereka belum digaji sejak musim semi: juru bayar Tuan Varanjit membayar Marsekal, agen Marsekal membayar kompi-kompi, dan di suatu tempat di antara keduanya uangnya berhenti.", "สมุดจ่ายเงินเดือนของพวกหนีทัพบอกว่าพวกเขาไม่ได้รับเงินมาตั้งแต่ฤดูใบไม้ผลิ เจ้าหน้าที่จ่ายเงินของท่านวรัญชิตจ่ายให้จอมพล ตัวแทนของจอมพลจ่ายให้กองร้อย และที่ไหนสักแห่งระหว่างสองทางนั้น เงินก็หยุดไหล", "Firarilerin maaş defterine göre bahardan beri maaş almamışlar: Lord'un mutemedi Mareşal'e ödüyor, Mareşal'in adamı bölüklere ödüyor ve ikisinin arasında bir yerde para duruyor.", "El libro de pagas de los desertores dice que no cobran desde la primavera: el pagador del señor le paga al Mariscal, el agente del Mariscal les paga a las compañías, y en algún punto entre ambos el dinero se detiene.", "O livro de soldos dos desertores diz que eles não recebem desde a primavera: o pagador do senhor paga o Marechal, o agente do Marechal paga as companhias, e em algum lugar entre os dois o dinheiro para.", "Судя по платёжной ведомости дезертиров, им не платили с весны: казначей лорда платит Маршалу, агент Маршала платит ротам, и где-то между ними деньги застревают.", "Судячи з платіжної відомості дезертирів, їм не платили з весни: скарбник лорда платить Маршалові, агент Маршала платить ротам, і десь між ними гроші застрягають."],
  "Sergeant Hask is dead, and the toll-house is Shailagarh's again.": ["ハスク軍曹は死に、関所は再びシャイラガルのものとなった。", "하스크 병장은 죽었고, 통행세 징수소는 다시 샤일라가르의 것이 되었다.", "哈斯克中士死了,收费站又归沙伊拉加尔了。", "哈斯克中士死了,收費站又歸沙伊拉加爾了。", "Trung sĩ Hask đã chết, và trạm thu thuế lại thuộc về Shailagarh.", "Sersan Hask sudah mati, dan pos tol itu kembali milik Shailagarh.", "จ่าฮัสก์ตายแล้ว และด่านเก็บค่าผ่านทางก็กลับเป็นของไศลครห์อีกครั้ง", "Çavuş Hask öldü ve gişe evi yeniden Shailagarh'ın.", "El sargento Hask ha muerto, y el puesto de peaje vuelve a ser de Shailagarh.", "O sargento Hask está morto, e o posto de pedágio é de Shailagarh outra vez.", "Сержант Хаск мёртв, и застава снова принадлежит Шайлагарху.", "Сержант Хаск мертвий, і застава знову належить Шайлагарху."],
  "Lord Varanjit will pay the companies himself from now on, and not through Khetmar. Captain Marr says that's the first sensible thing a lord has done all year. QUEST COMPLETE!": ["これからはヴァランジット卿がケトマルを通さず、自ら兵団に給金を払う。マール隊長に言わせれば、今年領主がやったことの中で初めてまともなことだそうだ。クエスト完了!", "이제부터 바란지트 경은 케트마르를 거치지 않고 직접 부대에 급료를 준다. 마르 대장은 올해 들어 영주가 한 일 중 처음으로 제정신인 일이라고 한다. 퀘스트 완료!", "从今往后,瓦兰吉特大人会亲自给各连队发饷,不再经过克特马尔。马尔队长说,这是今年以来头一件哪位大人做得像样的事。任务完成!", "從今往後,瓦蘭吉特大人會親自給各連隊發餉,不再經過克特馬爾。馬爾隊長說,這是今年以來頭一件哪位大人做得像樣的事。任務完成!", "Từ nay Lãnh chúa Varanjit sẽ tự mình trả lương cho các đại đội, không qua Khetmar nữa. Đội trưởng Marr nói đó là việc khôn ngoan đầu tiên mà một lãnh chúa làm được trong cả năm nay. HOÀN THÀNH NHIỆM VỤ!", "Mulai sekarang Tuan Varanjit akan menggaji kompi-kompi itu sendiri, tidak lewat Khetmar. Kapten Marr bilang itu hal masuk akal pertama yang dilakukan seorang tuan sepanjang tahun ini. MISI SELESAI!", "ต่อจากนี้ท่านวรัญชิตจะจ่ายเงินให้กองร้อยด้วยตัวเอง ไม่ผ่านเคทมาร์อีก ร้อยเอกมาร์บอกว่านั่นเป็นเรื่องแรกที่มีเหตุผลที่ขุนนางคนไหนทำมาทั้งปี ภารกิจสำเร็จ!", "Lord Varanjit bundan böyle bölüklere Khetmar üzerinden değil, kendisi ödeme yapacak. Yüzbaşı Marr bunun bütün yıl bir lordun yaptığı ilk makul şey olduğunu söylüyor. GÖREV TAMAMLANDI!", "A partir de ahora, el señor Varanjit pagará él mismo a las compañías, y no a través de Khetmar. La capitana Marr dice que es lo primero sensato que ha hecho un señor en todo el año. ¡MISIÓN CUMPLIDA!", "De agora em diante, o senhor Varanjit vai pagar as companhias ele mesmo, e não por meio de Khetmar. A capitã Marr diz que é a primeira coisa sensata que um senhor fez o ano inteiro. MISSÃO CUMPRIDA!", "Отныне лорд Варанджит будет платить ротам сам, а не через Кетмар. Капитан Марр говорит, что это первое разумное, что хоть какой-нибудь лорд сделал за весь год. ЗАДАНИЕ ВЫПОЛНЕНО!", "Відтепер лорд Варанджит платитиме ротам сам, а не через Кетмар. Капітанка Марр каже, що це перше розумне, що бодай якийсь лорд зробив за весь рік. ЗАВДАННЯ ВИКОНАНО!"],
  "Something is wrong in the Archive of Suvarnatira: the Archivist is counting the leaves of the star chart, again.": ["スヴァルナティーラの文書館で何かがおかしい。文書官がまたしても星図の紙葉を数えているのだ。", "수바르나티라의 서고에 뭔가 문제가 생겼다. 서고지기가 또다시 성도의 낱장을 세고 있다.", "苏瓦尔纳蒂拉的档案馆出了点问题:档案官又在数星图的页数了。", "蘇瓦爾納蒂拉的檔案館出了點問題:檔案官又在數星圖的頁數了。", "Có gì đó không ổn trong Văn khố Suvarnatira: người giữ văn khố lại đang đếm các tờ của tấm bản đồ sao, lần nữa.", "Ada yang tidak beres di Arsip Suvarnatira: Sang Arsiparis menghitung lembaran peta bintang, lagi.", "มีอะไรผิดปกติในหอจดหมายเหตุแห่งสุวรรณตีระ บรรณารักษ์กำลังนับแผ่นของแผนที่ดาวอีกแล้ว", "Suvarnatira Arşivi'nde bir terslik var: Arşivci yıldız haritasının yapraklarını yine sayıyor.", "Algo va mal en el Archivo de Suvarnatira: el archivero está contando las hojas de la carta estelar, otra vez.", "Algo está errado no Arquivo de Suvarnatira: o arquivista está contando as folhas da carta estelar, de novo.", "В Архиве Суварнатиры что-то неладно: архивариус опять пересчитывает листы звёздной карты.", "В Архіві Суварнатіри щось негаразд: архіваріус знову перераховує аркуші зоряної мапи."],
  "A leaf is missing from the Azhurak star chart the Archive and the Obsidian Legacy both claim. Archivist Mahir thinks the Legacy's envoy took it.": ["文書館と黒曜の遺統がともに所有を主張するアズラクの星図から、一葉が欠けている。文書官マヒルは、遺統の使節が持ち去ったと考えている。", "서고와 흑요 유산이 서로 제 것이라 주장하는 아주라크 성도에서 한 장이 사라졌다. 서고지기 마히르는 유산의 사절이 가져갔다고 생각한다.", "档案馆和黑曜遗脉都声称归自己所有的那份阿祖拉克星图少了一页。档案官马希尔认为是遗脉的使节拿走了。", "檔案館和黑曜遺脈都聲稱歸自己所有的那份阿祖拉克星圖少了一頁。檔案官馬希爾認為是遺脈的使節拿走了。", "Tấm bản đồ sao Azhurak mà cả Văn khố lẫn Di Sản Hắc Diện đều nhận là của mình đã mất một tờ. Người giữ văn khố Mahir cho rằng sứ giả của Di Sản đã lấy nó.", "Selembar halaman hilang dari peta bintang Azhurak yang sama-sama diklaim Arsip dan Warisan Obsidian. Arsiparis Mahir menduga utusan Warisan yang mengambilnya.", "แผนที่ดาวอาซูรักที่ทั้งหอจดหมายเหตุและมรดกออบซิเดียนต่างอ้างเป็นเจ้าของหายไปหนึ่งแผ่น บรรณารักษ์มาฮีร์คิดว่าทูตของมรดกออบซิเดียนเอาไป", "Arşiv'in de Obsidyen Mirası'nın da sahiplendiği Azhurak yıldız haritasından bir yaprak eksik. Arşivci Mahir, onu Miras'ın elçisinin aldığını düşünüyor.", "Falta una hoja de la carta estelar de Azhurak que reclaman tanto el Archivo como el Legado de Obsidiana. El archivero Mahir cree que se la llevó el enviado del Legado.", "Falta uma folha da carta estelar de Azhurak que tanto o Arquivo quanto o Legado de Obsidiana reivindicam. O arquivista Mahir acha que o enviado do Legado a levou.", "Из азуракской звёздной карты, на которую претендуют и Архив, и Обсидиановое наследие, пропал лист. Архивариус Махир думает, что его взял посланник Наследия.", "З азуракської зоряної карти, на яку претендують і Архів, і Обсидіанова спадщина, зник аркуш. Архіваріус Махір вважає, що його взяв посланець Спадщини."],
  "The borrowing ledger says the folio went out to be rebound, to a binder in Tirthali. There's no binder in Tirthali. There's a pedlar with a covered basket.": ["貸出台帳によれば、その一葉は製本し直すためにティルタリの製本屋へ出されたという。ティルタリに製本屋はいない。いるのは、覆いをかけた籠を持った行商人だ。", "대출 장부에 따르면 그 낱장은 다시 제본하러 티르탈리의 제본공에게 나갔다고 한다. 티르탈리에 제본공은 없다. 덮개 씌운 바구니를 든 행상이 하나 있을 뿐이다.", "借阅登记簿上写着，那页图册被送去重新装订，交给了提尔塔利的一位装订匠。提尔塔利没有装订匠。只有一个提着盖布篮子的货郎。", "借閱登記簿上寫著，那頁圖冊被送去重新裝訂，交給了提爾塔利的一位裝訂匠。提爾塔利沒有裝訂匠。只有一個提著蓋布籃子的貨郎。", "Sổ cho mượn ghi rằng tờ giấy đã được đem đi đóng lại, giao cho một thợ đóng sách ở Tirthali. Ở Tirthali chẳng có thợ đóng sách nào. Chỉ có một người bán rong với chiếc giỏ đậy kín.", "Buku pinjaman menyebut lembaran itu dikirim untuk dijilid ulang, ke seorang penjilid di Tirthali. Tidak ada penjilid di Tirthali. Yang ada seorang penjaja dengan keranjang bertutup.", "สมุดบันทึกการยืมระบุว่าแผ่นนั้นถูกส่งไปเย็บเล่มใหม่ที่ช่างเย็บเล่มในตีรถลี ตีรถลีไม่มีช่างเย็บเล่ม มีแต่พ่อค้าเร่กับตะกร้าที่มีผ้าคลุม", "Ödünç defterine göre yaprak yeniden ciltlenmek üzere Tirthali'deki bir mücellide gönderilmiş. Tirthali'de mücellit yok. Üstü örtülü sepetli bir seyyar satıcı var.", "El registro de préstamos dice que el folio salió para reencuadernarse, a un encuadernador de Tirthali. No hay ningún encuadernador en Tirthali. Hay un buhonero con una cesta tapada.", "O livro de empréstimos diz que o fólio saiu para ser reencadernado, por um encadernador em Tirthali. Não há encadernador em Tirthali. Há um mascate com um cesto coberto.", "Согласно книге выдачи, лист отдали на переплёт переплётчику в Тиртхали. В Тиртхали нет переплётчика. Там есть коробейник с накрытой корзиной.", "Згідно з книгою видачі, аркуш віддали на палітурку палітурникові в Тіртхалі. У Тіртхалі немає палітурника. Там є рознощик із накритим кошиком."],
  "The folio is back in the Archive. Envoy Saqqet will have a copy, made by the Archive's best hand, and Tamesh will argue about the original for another century. QUEST COMPLETE!": ["一葉は文書館に戻った。使節サッケトには文書館一の達筆による写しが渡され、タメシュは原本をめぐってあと百年は議論を続けるだろう。クエスト完了！", "낱장은 서고로 돌아왔다. 사절 사케트는 서고 최고의 필경사가 만든 사본을 받게 될 것이고, 타메시는 원본을 두고 앞으로 백 년은 더 다툴 것이다. 퀘스트 완료!", "那页图册回到了档案馆。使节萨凯特会得到一份由档案馆最好的抄写手誊录的副本，而塔梅什还会为原件再争上一个世纪。任务完成！", "那頁圖冊回到了檔案館。使節薩凱特會得到一份由檔案館最好的抄寫手謄錄的副本，而塔梅什還會為原件再爭上一個世紀。任務完成！", "Tờ giấy đã về lại Văn khố. Sứ giả Saqqet sẽ nhận một bản sao do bàn tay khéo nhất Văn khố chép lại, còn Tamesh sẽ tranh cãi về bản gốc thêm một thế kỷ nữa. HOÀN THÀNH NHIỆM VỤ!", "Lembaran itu kembali ke Arsip. Utusan Saqqet akan mendapat salinan buatan tangan terbaik Arsip, dan Tamesh akan memperdebatkan yang asli seabad lagi. MISI SELESAI!", "แผ่นนั้นกลับมาอยู่ที่หอจดหมายเหตุแล้ว ทูตซักเก็ตจะได้สำเนาที่คัดลอกโดยมือดีที่สุดของหอจดหมายเหตุ ส่วนทาเมชก็จะเถียงเรื่องต้นฉบับต่อไปอีกสักศตวรรษ ภารกิจสำเร็จ!", "Yaprak Arşiv'e döndü. Elçi Saqqet'e Arşiv'in en usta kaleminden çıkma bir kopya verilecek, Tamesh de aslı üstüne bir yüzyıl daha tartışacak. GÖREV TAMAMLANDI!", "El folio ha vuelto al Archivo. El enviado Saqqet tendrá una copia hecha por la mejor mano del Archivo, y Tamesh discutirá por el original otro siglo más. ¡MISIÓN CUMPLIDA!", "O fólio voltou ao Arquivo. O enviado Saqqet terá uma cópia feita pela melhor mão do Arquivo, e Tamesh vai discutir pelo original por mais um século. MISSÃO CUMPRIDA!", "Лист вернулся в Архив. Посланник Саккет получит копию, сделанную лучшим писцом Архива, а Тамеш ещё век будет спорить об оригинале. ЗАДАНИЕ ВЫПОЛНЕНО!", "Аркуш повернувся до Архіву. Посланець Саккет отримає копію, зроблену найкращим писарем Архіву, а Тамеш ще століття сперечатиметься про оригінал. ЗАВДАННЯ ВИКОНАНО!"],
  "The Kanthari of Kanthar don't want to be anybody's province. Grandmother Sukesh looks as if somebody has been trying.": ["カンタルのカンタリは、誰の属州にもなりたくない。スケシュ婆さまは、誰かがそうしようとしてきたような顔をしている。", "칸타르의 칸타리족은 누구의 속주도 되고 싶지 않다. 수케시 할머니는 누군가 그렇게 만들려고 애써 온 듯한 얼굴이다.", "坎塔尔的坎塔里人不想成为任何人的行省。苏凯什奶奶的神情，像是一直有人在这么尝试。", "坎塔爾的坎塔里人不想成為任何人的行省。蘇凱什奶奶的神情，像是一直有人在這麼嘗試。", "Người Kanthari ở Kanthar không muốn làm tỉnh của ai cả. Bà Sukesh trông như thể đã có kẻ đang cố làm vậy.", "Orang Kanthari di Kanthar tak mau menjadi provinsi siapa pun. Nenek Sukesh tampak seperti ada yang sedang mencoba.", "ชาวกันถารีแห่งกันถาร์ไม่อยากเป็นมณฑลของใคร ยายสุเกศดูเหมือนมีใครบางคนพยายามอยู่", "Kanthar'ın Kanthari'leri kimsenin eyaleti olmak istemiyor. Sukesh Nine'nin yüzünden birilerinin bunu denediği belli.", "Los kanthari de Kanthar no quieren ser provincia de nadie. La abuela Sukesh tiene cara de que alguien lo ha estado intentando.", "Os kanthari de Kanthar não querem ser província de ninguém. A avó Sukesh tem cara de quem anda vendo alguém tentar.", "Кантхари из Кантхара не желают быть ничьей провинцией. У бабушки Сукеш такой вид, будто кто-то уже пытался их ею сделать.", "Кантхарі з Кантхара не бажають бути нічиєю провінцією. Бабуся Сукеш має такий вигляд, наче хтось уже пробував."],
  "Shailagarh's loggers have moved the stones that mark the Kanthari's grove, and cut inside them. Grandmother Sukesh wants them put back.": ["シャイラガルの木こりたちが、カンタリの聖なる林を示す石を動かし、その内側で木を切った。スケシュ婆さまは石を元に戻してほしいと言う。", "샤일라가르의 벌목꾼들이 칸타리족의 숲을 표시하는 돌들을 옮기고 그 안쪽에서 나무를 베었다. 수케시 할머니는 돌들을 제자리에 돌려놓길 원한다.", "沙伊拉加尔的伐木工挪动了标示坎塔里人圣林的石头，还在石头里面砍了树。苏凯什奶奶希望把石头放回原处。", "沙伊拉加爾的伐木工挪動了標示坎塔里人聖林的石頭，還在石頭裡面砍了樹。蘇凱什奶奶希望把石頭放回原處。", "Thợ đốn gỗ của Shailagarh đã dời những hòn đá đánh dấu khu rừng thiêng của người Kanthari, rồi đốn cây bên trong. Bà Sukesh muốn chúng được đặt lại chỗ cũ.", "Para penebang Shailagarh telah memindahkan batu-batu penanda hutan keramat orang Kanthari, lalu menebang di dalamnya. Nenek Sukesh ingin batu-batu itu dikembalikan.", "คนตัดไม้ของไศลครห์ย้ายหินที่เป็นเขตแดนป่าศักดิ์สิทธิ์ของชาวกันถารี แล้วตัดไม้ในเขตนั้น ยายสุเกศอยากให้วางหินคืนที่เดิม", "Shailagarh'ın oduncuları Kanthari'lerin korusunu işaretleyen taşları yerinden oynatıp içeride ağaç kesmiş. Sukesh Nine taşların yerine konmasını istiyor.", "Los leñadores de Shailagarh han movido las piedras que marcan la arboleda de los kanthari y han talado dentro. La abuela Sukesh quiere que las devuelvan a su sitio.", "Os lenhadores de Shailagarh mudaram de lugar as pedras que marcam o bosque dos kanthari e cortaram lá dentro. A avó Sukesh quer as pedras de volta no lugar.", "Лесорубы Шайлагарха сдвинули камни, которыми кантхари отмечают свою рощу, и рубили внутри. Бабушка Сукеш хочет, чтобы камни вернули на место.", "Лісоруби Шайлагарха зсунули камені, якими кантхарі позначають свій гай, і рубали всередині. Бабуся Сукеш хоче, щоб камені повернули на місце."],
  "The grove stones are back. The loggers will only cut where their licence says, and their licence says everywhere.": ["林の石は元に戻った。木こりたちは許可証にある場所でしか切らないと言うが、その許可証にはどこでもと書いてある。", "숲의 돌들은 제자리로 돌아왔다. 벌목꾼들은 허가증에 적힌 곳에서만 벨 거라고 하는데, 그 허가증에는 어디든이라고 적혀 있다.", "圣林的石头放回去了。伐木工说只在许可证规定的地方砍，而许可证上写的是：哪儿都行。", "聖林的石頭放回去了。伐木工說只在許可證規定的地方砍，而許可證上寫的是：哪兒都行。", "Những hòn đá của khu rừng thiêng đã về chỗ cũ. Thợ đốn gỗ bảo họ chỉ đốn ở nơi giấy phép cho phép, mà giấy phép thì ghi là khắp nơi.", "Batu-batu hutan keramat sudah kembali. Para penebang hanya akan menebang di tempat yang disebut izin mereka, dan izin mereka menyebut di mana saja.", "หินเขตป่ากลับเข้าที่แล้ว คนตัดไม้จะตัดเฉพาะที่ใบอนุญาตระบุ และใบอนุญาตระบุว่าทุกที่", "Koru taşları yerinde. Oduncular yalnızca izinlerinin gösterdiği yerde keseceklermiş; izinleri de her yeri gösteriyor.", "Las piedras de la arboleda han vuelto. Los leñadores solo talarán donde diga su licencia, y su licencia dice que en todas partes.", "As pedras do bosque voltaram. Os lenhadores só vão cortar onde a licença diz, e a licença diz que em todo lugar.", "Камни рощи на месте. Лесорубы будут рубить только там, где сказано в лицензии, а в лицензии сказано: везде.", "Камені гаю на місці. Лісоруби рубатимуть лише там, де сказано в ліцензії, а в ліцензії сказано: скрізь."],
  "Lord Varanjit has torn up the licence and will draw a new one with the Kanthari's stones on it.": ["ヴァランジット卿は許可証を破り捨て、カンタリの石を書き入れた新しいものを作ると言った。", "바란지트 경은 허가증을 찢어 버리고, 칸타리족의 돌들을 표시한 새 허가증을 작성하겠다고 했다.", "瓦兰吉特大人撕掉了许可证，要重新拟一份，把坎塔里人的石头标在上面。", "瓦蘭吉特大人撕掉了許可證，要重新擬一份，把坎塔里人的石頭標在上面。", "Lãnh chúa Varanjit đã xé giấy phép và sẽ thảo một tờ mới có ghi những hòn đá của người Kanthari.", "Tuan Varanjit merobek izin itu dan akan membuat yang baru dengan batu-batu orang Kanthari tercantum di dalamnya.", "ท่านวรัญชิตฉีกใบอนุญาตทิ้ง และจะร่างฉบับใหม่ที่มีหินของชาวกันถารีกำกับไว้", "Lord Varanjit izni yırttı; Kanthari'lerin taşlarını da gösteren yeni bir izin çizecek.", "El señor Varanjit ha roto la licencia y redactará una nueva con las piedras de los kanthari marcadas.", "O senhor Varanjit rasgou a licença e vai redigir uma nova com as pedras dos kanthari marcadas.", "Лорд Варанджит порвал лицензию и составит новую, с камнями кантхари на ней.", "Лорд Варанджит порвав ліцензію і складе нову, з каменями кантхарі на ній."],
  "The grove stones are where they were, the licence is a new one, and Grandmother Sukesh gave the loggers tea. The forest keeps the river's banks; now the river may keep its tanks. QUEST COMPLETE!": ["林の石はもとの場所に戻り、許可証は新しくなり、スケシュ婆さまは木こりたちにお茶をふるまった。森は川の岸を守る。これで川も貯水池を守れるかもしれない。クエスト完了！", "숲의 돌들은 원래 자리에 있고, 허가증은 새것이 되었고, 수케시 할머니는 벌목꾼들에게 차를 대접했다. 숲은 강둑을 지킨다. 이제 강도 저수지를 지킬 수 있을지 모른다. 퀘스트 완료!", "圣林的石头回到了原处，许可证换了新的，苏凯什奶奶还请伐木工喝了茶。森林守护着河岸；如今河流或许也能守护它的水池了。任务完成！", "聖林的石頭回到了原處，許可證換了新的，蘇凱什奶奶還請伐木工喝了茶。森林守護著河岸；如今河流或許也能守護它的水池了。任務完成！", "Những hòn đá của khu rừng thiêng đã về chỗ cũ, giấy phép là tờ mới, và Bà Sukesh mời thợ đốn gỗ uống trà. Rừng giữ bờ sông; giờ thì sông có lẽ giữ được các hồ chứa của mình. HOÀN THÀNH NHIỆM VỤ!", "Batu-batu hutan keramat ada di tempatnya semula, izinnya baru, dan Nenek Sukesh menyuguhi para penebang teh. Hutan menjaga tepian sungai; kini sungai mungkin bisa menjaga telaga-telaganya. MISI SELESAI!", "หินเขตป่ากลับอยู่ที่เดิม ใบอนุญาตเป็นฉบับใหม่ และยายสุเกศชงชาให้คนตัดไม้ดื่ม ผืนป่าปกปักษ์ตลิ่งแม่น้ำ บัดนี้แม่น้ำก็อาจปกปักษ์สระของมันได้ ภารกิจสำเร็จ!", "Koru taşları eski yerlerinde, izin yepyeni ve Sukesh Nine odunculara çay ikram etti. Orman nehrin kıyılarını korur; artık nehir de havuzlarını koruyabilir. GÖREV TAMAMLANDI!", "Las piedras de la arboleda están donde estaban, la licencia es nueva y la abuela Sukesh les sirvió té a los leñadores. El bosque guarda las orillas del río; ahora quizá el río pueda guardar sus estanques. ¡MISIÓN CUMPLIDA!", "As pedras do bosque estão onde estavam, a licença é nova e a avó Sukesh serviu chá aos lenhadores. A floresta guarda as margens do rio; agora talvez o rio possa guardar seus tanques. MISSÃO CUMPRIDA!", "Камни рощи там, где были, лицензия новая, а бабушка Сукеш напоила лесорубов чаем. Лес бережёт берега реки; теперь, глядишь, и река сбережёт свои пруды. ЗАДАНИЕ ВЫПОЛНЕНО!", "Камені гаю там, де були, ліцензія нова, а бабуся Сукеш напоїла лісорубів чаєм. Ліс береже береги річки; тепер, дивись, і річка вбереже свої стави. ЗАВДАННЯ ВИКОНАНО!"],
  "You step over the unhooked chain and go down the Great Stepwell, landing after landing, into the green dark.": ["外された鎖をまたぎ、大階段井戸を踊り場から踊り場へと下りて、緑の闇の中へ入っていく。", "풀린 사슬을 넘어 대계단우물을 내려간다. 층계참에서 층계참으로, 초록빛 어둠 속으로.", "你跨过解开的锁链，走下大阶梯井，一层平台接着一层平台，没入绿色的幽暗之中。", "你跨過解開的鎖鏈，走下大階梯井，一層平台接著一層平台，沒入綠色的幽暗之中。", "Bạn bước qua sợi xích đã tháo móc và đi xuống Giếng Bậc Lớn, hết chiếu nghỉ này đến chiếu nghỉ khác, vào bóng tối xanh lục.", "Kau melangkahi rantai yang sudah dilepas dan menuruni Sumur Tangga Agung, bordes demi bordes, ke dalam kegelapan hijau.", "คุณก้าวข้ามโซ่ที่ปลดออกแล้ว และลงบ่อขั้นบันไดใหญ่ไปทีละชาน ทีละชาน สู่ความมืดสีเขียว", "Çözülmüş zincirin üstünden adımlayıp Büyük Basamaklı Kuyu'dan aşağı inersin; sahanlık sahanlık, yeşil karanlığa.", "Pasas por encima de la cadena descolgada y bajas por el Gran Pozo Escalonado, rellano tras rellano, hacia la oscuridad verde.", "Você passa por cima da corrente solta e desce o Grande Poço de Degraus, patamar após patamar, rumo ao escuro verde.", "Вы перешагиваете через снятую цепь и спускаетесь в Великий ступенчатый колодец, площадка за площадкой, в зелёную тьму.", "Ви переступаєте через знятий ланцюг й спускаєтеся у Великий східчастий колодязь, майданчик за майданчиком, у зелену темряву."],
  "Steps go down four sides of a square shaft to green water far below. The Chief Engineer's chain hangs unhooked from the lowest landing you can see.": ["四角い竪穴の四方に階段が刻まれ、はるか下の緑の水へと続いている。見える限り最も低い踊り場から、主任技師の鎖が外れて垂れ下がっている。", "네모난 수직굴의 네 면을 따라 계단이 저 아래 초록빛 물까지 이어진다. 보이는 가장 낮은 층계참에 수석 기술자의 사슬이 풀린 채 늘어져 있다.", "台阶沿着方形竖井的四壁一路向下，通往远在下方的绿水。总工程师的锁链从你能看到的最低一层平台上解开垂落。", "台階沿著方形豎井的四壁一路向下，通往遠在下方的綠水。總工程師的鎖鏈從你能看到的最低一層平台上解開垂落。", "Bậc thang chạy xuống bốn mặt của một giếng vuông, tới làn nước xanh tít bên dưới. Sợi xích của Kỹ sư trưởng buông lơi, đã tháo móc, từ chiếu nghỉ thấp nhất mà bạn nhìn thấy.", "Anak tangga menurun di keempat sisi sebuah lubang persegi menuju air hijau jauh di bawah. Rantai Kepala Insinyur tergantung lepas dari bordes terendah yang bisa kau lihat.", "ขั้นบันไดทอดลงไปทั้งสี่ด้านของปล่องสี่เหลี่ยม สู่ผิวน้ำสีเขียวไกลลิบเบื้องล่าง โซ่ของหัวหน้าวิศวกรห้อยหลุดจากชานต่ำสุดเท่าที่มองเห็น", "Kare bir kuyunun dört yanından basamaklar çok aşağıdaki yeşil suya iner. Baş Mühendis'in zinciri, görebildiğin en alt sahanlıktan çözülmüş hâlde sarkıyor.", "Los escalones bajan por los cuatro lados de un pozo cuadrado hasta un agua verde muy abajo. La cadena del ingeniero jefe cuelga descolgada del rellano más bajo que alcanzas a ver.", "Degraus descem pelos quatro lados de um poço quadrado até uma água verde lá embaixo. A corrente do engenheiro-chefe pende solta do patamar mais baixo que você consegue ver.", "Ступени спускаются по четырём стенам квадратной шахты к зелёной воде далеко внизу. Цепь главного инженера, снятая с крюка, свисает с самой нижней видимой площадки.", "Сходи спускаються чотирма стінами квадратної шахти до зеленої води далеко внизу. Ланцюг головного інженера, знятий із гака, звисає з найнижчого видимого майданчика."],
  "A great bronze wheel on an axle of teak, green with age, that once opened the sluice under the Great Tank.": ["年月で緑青に覆われた、チーク材の軸にかかる大きな青銅の輪。かつて大貯水池の下の水門を開けていたものだ。", "세월에 푸르게 녹슨 티크 굴대 위의 커다란 청동 바퀴. 한때 대저수지 아래 수문을 여는 데 쓰였다.", "一只装在柚木轴上的巨大青铜轮，年深日久，已经泛绿。它曾经开启大水池下方的水闸。", "一隻裝在柚木軸上的巨大青銅輪，年深日久，已經泛綠。它曾經開啟大水池下方的水閘。", "Một bánh xe đồng lớn trên trục gỗ tếch, xanh màu năm tháng, từng mở cửa cống dưới Hồ Lớn.", "Roda perunggu besar pada poros jati, hijau dimakan usia, yang dulu membuka pintu air di bawah Telaga Agung.", "กงล้อสำริดขนาดใหญ่บนเพลาไม้สัก เขียวไปตามกาลเวลา เคยใช้เปิดประตูน้ำใต้สระใหญ่", "Tik ağacından bir mile takılı, yıllardan yeşermiş büyük bir tunç çark; bir zamanlar Büyük Havuz'un altındaki savağı açarmış.", "Una gran rueda de bronce sobre un eje de teca, verde por los años, que antaño abría la compuerta bajo el Gran Estanque.", "Uma grande roda de bronze num eixo de teca, verde de tão velha, que um dia abria a comporta sob o Grande Tanque.", "Большое бронзовое колесо на тиковой оси, позеленевшее от времени; когда-то оно открывало шлюз под Великим прудом.", "Велике бронзове колесо на тиковій осі, позеленіле від часу; колись воно відчиняло шлюз під Великим ставом."],
  "The wheel stands open. Water runs under it, clean, towards the cistern.": ["輪は開いたままだ。その下を、澄んだ水が貯水槽へと流れていく。", "바퀴는 열려 있다. 그 아래로 맑은 물이 저수조를 향해 흐른다.", "轮子开着。清水从下面流过，流向蓄水池。", "輪子開著。清水從下面流過，流向蓄水池。", "Bánh xe đang mở. Nước trong chảy bên dưới, về phía bể chứa.", "Roda itu terbuka. Air jernih mengalir di bawahnya, menuju waduk.", "กงล้อเปิดอยู่ น้ำใสไหลผ่านใต้มันไปยังถังเก็บน้ำ", "Çark açık. Altından berrak su sarnıca doğru akıyor.", "La rueda está abierta. Por debajo corre agua limpia hacia la cisterna.", "A roda está aberta. Por baixo dela corre água limpa rumo à cisterna.", "Колесо открыто. Под ним к цистерне бежит чистая вода.", "Колесо відкрите. Під ним до цистерни біжить чиста вода."],
  "You lean on the wheel. Silt grinds in it, and something in the cistern beyond answers the sound. Not yet.": ["輪に体重をかける。中で泥がきしみ、その先の貯水槽で何かがその音に応える。まだだ。", "바퀴에 몸을 기댄다. 안에서 토사가 갈리는 소리가 나고, 그 너머 저수조의 무언가가 그 소리에 응답한다. 아직은 아니다.", "你靠在轮子上用力。淤泥在里面咯吱作响，而远处蓄水池里有什么东西回应了这声音。还不是时候。", "你靠在輪子上用力。淤泥在裡面咯吱作響，而遠處蓄水池裡有什麼東西回應了這聲音。還不是時候。", "Bạn tì người vào bánh xe. Bùn lắng nghiến ken két bên trong, và có thứ gì đó trong bể chứa phía xa đáp lại tiếng động ấy. Chưa phải lúc.", "Kau bersandar pada roda itu. Lumpur berderak di dalamnya, dan sesuatu di waduk di baliknya menjawab suara itu. Belum saatnya.", "คุณเอนตัวดันกงล้อ ตะกอนบดเสียดอยู่ข้างใน และบางสิ่งในถังเก็บน้ำถัดไปตอบรับเสียงนั้น ยังไม่ถึงเวลา", "Çarka yüklenirsin. İçinde balçık gıcırdar ve ötedeki sarnıçta bir şey bu sese karşılık verir. Daha değil.", "Te apoyas en la rueda. El limo rechina dentro, y algo en la cisterna, más allá, responde al sonido. Todavía no.", "Você se apoia na roda. O lodo range lá dentro, e algo na cisterna mais adiante responde ao som. Ainda não.", "Вы налегаете на колесо. Внутри скрежещет ил, и что-то в цистерне за ним отзывается на этот звук. Ещё не время.", "Ви налягаєте на колесо. Усередині скрегоче мул, і щось у цистерні за ним озивається на цей звук. Ще не час."],
  "A bronze wheel, seized with silt. It hasn't turned in years.": ["泥で固まった青銅の輪。もう何年も回っていない。", "토사로 꽉 막힌 청동 바퀴. 몇 년째 돌아간 적이 없다.", "一只被淤泥卡死的青铜轮。已经好多年没转过了。", "一隻被淤泥卡死的青銅輪。已經好多年沒轉過了。", "Một bánh xe đồng bị bùn lắng làm kẹt cứng. Đã nhiều năm nó không quay.", "Roda perunggu yang macet oleh lumpur. Sudah bertahun-tahun tak berputar.", "กงล้อสำริดที่ตะกอนอุดจนติดตาย ไม่ได้หมุนมาหลายปีแล้ว", "Balçıktan tutukluk yapmış bir tunç çark. Yıllardır dönmemiş.", "Una rueda de bronce atascada de limo. Lleva años sin girar.", "Uma roda de bronze travada de lodo. Faz anos que não gira.", "Бронзовое колесо, намертво забитое илом. Оно не поворачивалось годами.", "Бронзове колесо, намертво забите мулом. Воно не поверталося роками."],
  "The sluice wheel turns, groaning, and far above you the Great Tank begins to drain its silt through the Stepwell. Tell the Queen.": ["水門の輪がうめきながら回り、はるか頭上で大貯水池が階段井戸を通して泥を吐き出しはじめる。女王に伝えよう。", "수문 바퀴가 신음하며 돌아가고, 저 위에서 대저수지가 계단우물을 통해 토사를 빼내기 시작한다. 여왕에게 알리자.", "水闸轮呻吟着转动起来，在你头顶高处，大水池开始通过阶梯井排出淤泥。去告诉女王。", "水閘輪呻吟著轉動起來，在你頭頂高處，大水池開始通過階梯井排出淤泥。去告訴女王。", "Bánh xe cửa cống rên rỉ xoay, và tít trên cao, Hồ Lớn bắt đầu xả bùn lắng qua Giếng Bậc. Hãy báo cho Nữ hoàng.", "Roda pintu air berputar sambil mengerang, dan jauh di atasmu Telaga Agung mulai mengalirkan lumpurnya lewat Sumur Tangga. Beri tahu Ratu.", "กงล้อประตูน้ำหมุนไปพร้อมเสียงครวญคราง และสูงขึ้นไปเหนือหัวคุณ สระใหญ่เริ่มระบายตะกอนลงมาทางบ่อขั้นบันได ไปบอกราชินีเถิด", "Savak çarkı inleyerek döner ve çok yukarıda Büyük Havuz balçığını Basamaklı Kuyu'dan boşaltmaya başlar. Kraliçe'ye haber ver.", "La rueda de la compuerta gira, gimiendo, y muy por encima de ti el Gran Estanque empieza a vaciar su limo por el Pozo Escalonado. Avisa a la reina.", "A roda da comporta gira, gemendo, e bem acima de você o Grande Tanque começa a escoar o lodo pelo Poço de Degraus. Avise a rainha.", "Колесо шлюза со стоном поворачивается, и высоко над вами Великий пруд начинает сбрасывать ил через ступенчатый колодец. Сообщите королеве.", "Колесо шлюзу зі стогоном повертається, і високо над вами Великий став починає скидати мул через східчастий колодязь. Повідомте королеву."],
  "You put your back into the wheel. It sticks, shudders, gives, and turns, a whole turn, then another. Somewhere above, a sound like a great breath let out: the Great Tank's water, moving.": ["背中を輪に押し当てて力を込める。引っかかり、震え、緩み、そして回る。一回転、さらにもう一回転。どこか上のほうで、大きな息を吐き出すような音がした。大貯水池の水が動いているのだ。", "등을 바퀴에 대고 힘을 쓴다. 걸리고, 떨리고, 풀리더니 돌아간다. 한 바퀴, 또 한 바퀴. 저 위 어딘가에서 거대한 숨을 내쉬는 듯한 소리가 난다. 대저수지의 물이 움직이고 있다.", "你用背顶住轮子使劲。它卡住，颤动，松开，转动——整整一圈，又是一圈。头顶上方某处传来一声仿佛长长呼出一口大气的声音：大水池的水，动了。", "你用背頂住輪子使勁。它卡住，顫動，鬆開，轉動——整整一圈，又是一圈。頭頂上方某處傳來一聲彷彿長長呼出一口大氣的聲音：大水池的水，動了。", "Bạn dồn sức tì lưng vào bánh xe. Nó kẹt, rung lên, nhả ra, rồi xoay, trọn một vòng, rồi thêm vòng nữa. Đâu đó phía trên vang lên một âm thanh như một hơi thở lớn được thả ra: nước của Hồ Lớn đang chuyển động.", "Kau mengerahkan punggungmu pada roda itu. Roda itu macet, bergetar, mengalah, lalu berputar, satu putaran penuh, lalu satu lagi. Di suatu tempat di atas, terdengar suara seperti napas besar yang dilepaskan: air Telaga Agung, bergerak.", "คุณเอาหลังดันกงล้อสุดแรง มันติด สั่น ยอม แล้วหมุน ครบหนึ่งรอบ แล้วอีกรอบ ที่ไหนสักแห่งข้างบนมีเสียงเหมือนลมหายใจใหญ่ที่ถูกปล่อยออกมา น้ำในสระใหญ่กำลังเคลื่อนไหว", "Sırtını çarka verirsin. Takılır, titrer, gevşer ve döner; tam bir tur, sonra bir tur daha. Yukarıda bir yerde, koca bir nefesin bırakılışı gibi bir ses: Büyük Havuz'un suyu hareket ediyor.", "Empujas la rueda con la espalda. Se atasca, se estremece, cede y gira, una vuelta entera, y luego otra. En algún lugar de arriba, un sonido como un gran suspiro soltado: el agua del Gran Estanque, moviéndose.", "Você força a roda com as costas. Ela emperra, estremece, cede e gira, uma volta inteira, depois outra. Em algum lugar lá em cima, um som como um grande fôlego solto: a água do Grande Tanque, se movendo.", "Вы налегаете на колесо спиной. Оно застревает, вздрагивает, поддаётся и поворачивается — целый оборот, потом ещё один. Где-то наверху раздаётся звук, словно кто-то огромный перевёл дух: вода Великого пруда пришла в движение.", "Ви налягаєте на колесо спиною. Воно застрягає, здригається, піддається й повертається — цілий оберт, потім ще один. Десь угорі лунає звук, наче хтось велетенський видихнув: вода Великого ставу зрушила."],
  "Seven columns, one for each ruler's roads, and a column for the Queen's bridge. This season the bridge's column doubles, in a fresh hand, and the ink is a different black from the rest. The figures for the League's own roads haven't changed in three years.": ["七つの欄があり、それぞれの君主の街道に一つずつ、そして女王の橋の欄がある。今季、橋の欄だけが新しい筆跡で倍になっており、インクの黒さもほかとは違う。同盟自身の街道の数字は、この三年変わっていない。", "일곱 개의 칸. 통치자들의 길마다 한 칸씩, 그리고 여왕의 다리를 위한 칸 하나. 이번 철에는 다리 칸만 새 필체로 두 배가 되어 있고, 잉크의 검은빛도 나머지와 다르다. 동맹 자신의 길에 대한 숫자는 삼 년째 그대로다.", "七栏，每位统治者的道路各占一栏，另有一栏记女王的桥。这一季，桥那一栏翻了一倍，笔迹是新的，墨色也和其他的黑得不一样。同盟自己道路的数字，三年来一直没变。", "七欄，每位統治者的道路各占一欄，另有一欄記女王的橋。這一季，橋那一欄翻了一倍，筆跡是新的，墨色也和其他的黑得不一樣。同盟自己道路的數字，三年來一直沒變。", "Bảy cột, mỗi cột cho đường của một vị cai trị, và một cột cho cây cầu của Nữ hoàng. Mùa này cột của cây cầu tăng gấp đôi, bằng một nét chữ mới, và mực đen khác hẳn phần còn lại. Số liệu cho đường riêng của Liên minh thì ba năm nay không đổi.", "Tujuh kolom, satu untuk jalan tiap penguasa, dan satu kolom untuk jembatan Ratu. Musim ini kolom jembatan berlipat dua, dengan tulisan tangan baru, dan tintanya hitam yang berbeda dari yang lain. Angka untuk jalan-jalan Liga sendiri tak berubah selama tiga tahun.", "เจ็ดช่อง ช่องละถนนของผู้ปกครองแต่ละคน และอีกช่องสำหรับสะพานของราชินี ฤดูนี้ช่องของสะพานเพิ่มเป็นสองเท่า ด้วยลายมือใหม่ และหมึกก็ดำต่างจากส่วนอื่น ตัวเลขของถนนสันนิบาตเองไม่เปลี่ยนมาสามปีแล้ว", "Yedi sütun: her hükümdarın yolları için bir sütun ve Kraliçe'nin köprüsü için bir sütun. Bu mevsim köprünün sütunu ikiye katlanmış; yeni bir elden, mürekkebi de ötekilerden farklı bir siyah. Birlik'in kendi yollarının rakamları üç yıldır değişmemiş.", "Siete columnas, una para los caminos de cada gobernante, y una columna para el puente de la reina. Esta temporada la columna del puente se dobla, con letra reciente, y la tinta es de un negro distinto al del resto. Las cifras de los caminos de la propia Liga no han cambiado en tres años.", "Sete colunas, uma para as estradas de cada governante, e uma coluna para a ponte da rainha. Nesta estação a coluna da ponte dobra, numa letra recente, e a tinta é de um preto diferente do resto. Os números das estradas da própria Liga não mudam há três anos.", "Семь столбцов: по одному на дороги каждого правителя и столбец для моста королевы. В этом сезоне столбец моста удваивается — свежим почерком, и чернила другого чёрного, чем всё остальное. Цифры по дорогам самой Лиги не менялись три года.", "Сім стовпців: по одному на дороги кожного правителя і стовпець для мосту королеви. Цього сезону стовпець мосту подвоюється — свіжим почерком, і чорнило іншого чорного, ніж усе інше. Цифри по дорогах самої Ліги не змінювалися три роки."],
  "A soldier's paybook, left on the toll-house table under a stone.": ["兵士の給与手帳。通行所の机の上に、石を重しにして置かれている。", "병사의 급여 수첩. 통행세 징수소 탁자 위에 돌에 눌린 채 놓여 있다.", "一本士兵的饷册，压在收费所桌上的一块石头底下。", "一本士兵的餉冊，壓在收費所桌上的一塊石頭底下。", "Một cuốn sổ lương của lính, để lại trên bàn trạm thu phí, chặn dưới một hòn đá.", "Buku gaji seorang prajurit, ditinggal di meja pos tol di bawah sebuah batu.", "สมุดเงินเดือนทหาร วางทิ้งไว้บนโต๊ะในด่านเก็บค่าผ่านทาง มีหินทับไว้", "Bir askerin maaş defteri, gişe evinin masasında bir taşın altında bırakılmış.", "La libreta de pagas de un soldado, dejada en la mesa de la caseta de peaje bajo una piedra.", "A caderneta de soldo de um soldado, deixada na mesa do posto de pedágio debaixo de uma pedra.", "Солдатская расчётная книжка, оставленная на столе в пошлинной будке под камнем.", "Солдатська розрахункова книжка, залишена на столі в митній будці під каменем."],
  "A Copper Banner company's paybook. Months of entries: 'Paid by Shailagarh to Khetmar's agent, in full.' Then nothing paid to the company, month after month, in a sergeant's careful hand, and under the last: 'No pay, no Banner. We'll take our own toll.'": ["銅の旗の中隊の給与手帳。何か月分もの記入がある。「シャイラガルよりケトマルの代理人へ、全額支払い済み」。その後、中隊への支払いは月を追うごとに一切なく、軍曹の几帳面な筆跡で記され、最後の行の下にはこうある。「給金なくして旗なし。通行税は自分たちで取る」", "구리 깃발 중대의 급여 수첩. 몇 달 치 기록이 있다. '샤일라가르가 케트마르의 대리인에게 전액 지급.' 그 뒤로는 달마다 중대에 지급된 것이 없다는 기록이 병장의 꼼꼼한 필체로 이어지고, 마지막 줄 아래에는 이렇게 적혀 있다. '급여 없으면 깃발도 없다. 통행세는 우리가 직접 걷겠다.'", "一本铜旗连队的饷册。记了好几个月：“沙伊拉加尔已付克特马尔的代理人，全额。”之后，一个月又一个月，连队一分钱也没拿到，全是一位中士工整的笔迹；最后一行下面写着：“不发饷，就没有旗。我们自己收过路钱。”", "一本銅旗連隊的餉冊。記了好幾個月：「沙伊拉加爾已付克特馬爾的代理人，全額。」之後，一個月又一個月，連隊一分錢也沒拿到，全是一位中士工整的筆跡；最後一行下面寫著：「不發餉，就沒有旗。我們自己收過路錢。」", "Sổ lương của một đại đội Cờ Đồng. Nhiều tháng ghi chép: 'Shailagarh đã trả cho người đại diện của Khetmar, đủ cả.' Rồi chẳng có gì trả cho đại đội, tháng này qua tháng khác, bằng nét chữ cẩn thận của một trung sĩ, và dưới dòng cuối cùng: 'Không lương, không Cờ. Bọn ta sẽ tự thu thuế đường.'", "Buku gaji sebuah kompi Panji Tembaga. Catatan berbulan-bulan: 'Dibayar oleh Shailagarh kepada agen Khetmar, lunas.' Lalu tak ada yang dibayarkan kepada kompi itu, bulan demi bulan, dalam tulisan tangan seorang sersan yang rapi, dan di bawah yang terakhir: 'Tak ada gaji, tak ada Panji. Kami pungut tol sendiri.'", "สมุดเงินเดือนของกองร้อยธงทองแดง บันทึกหลายเดือน 'ไศลครห์จ่ายให้ตัวแทนของเคทมาร์ ครบถ้วน' จากนั้นก็ไม่มีการจ่ายให้กองร้อยเลย เดือนแล้วเดือนเล่า ด้วยลายมือบรรจงของจ่าคนหนึ่ง และใต้บรรทัดสุดท้าย 'ไม่มีเงิน ก็ไม่มีธง เราจะเก็บค่าผ่านทางเอง'", "Bir Bakır Sancak bölüğünün maaş defteri. Aylarca süren kayıtlar: 'Shailagarh tarafından Khetmar'ın temsilcisine ödendi, tamamı.' Sonra ay be ay bölüğe hiçbir ödeme yok, bir çavuşun özenli el yazısıyla; en sonuncusunun altında da: 'Maaş yoksa Sancak da yok. Geçiş ücretimizi kendimiz alırız.'", "La libreta de pagas de una compañía del Estandarte de Cobre. Meses de anotaciones: «Pagado por Shailagarh al agente de Khetmar, íntegro». Luego nada pagado a la compañía, mes tras mes, con la letra cuidadosa de un sargento, y bajo la última: «Sin paga no hay Estandarte. Cobraremos nuestro propio peaje».", "A caderneta de soldo de uma companhia do Estandarte de Cobre. Meses de lançamentos: 'Pago por Shailagarh ao agente de Khetmar, integralmente.' Depois nada pago à companhia, mês após mês, na letra caprichada de um sargento, e embaixo do último: 'Sem soldo, sem Estandarte. Vamos cobrar nosso próprio pedágio.'", "Расчётная книжка роты Медного знамени. Записи за много месяцев: «Уплачено Шайлагархом агенту Кетмара, полностью». Потом месяц за месяцем роте не выплачено ничего — аккуратным почерком сержанта, а под последней записью: «Нет жалованья — нет Знамени. Возьмём пошлину сами».", "Розрахункова книжка роти Мідного стягу. Записи за багато місяців: «Сплачено Шайлагархом агентові Кетмара, повністю». Потім місяць за місяцем роті не виплачено нічого — охайним почерком сержанта, а під останнім записом: «Нема платні — нема Стягу. Візьмемо мито самі»."],
  "Every leaf that leaves the reading room, and why. Ten days ago: 'Star chart, ninth leaf, out for rebinding, to the binder at Tirthali.' Signed by an under-librarian who left for Khetmar the next morning.": ["閲覧室から出ていくすべての紙葉と、その理由。十日前：「星図、第九葉、製本し直しのため、ティルタリの製本屋へ」。署名したのは下級司書で、その翌朝ケトマルへ発っている。", "열람실을 나가는 모든 낱장과 그 이유. 열흘 전: '성도, 아홉 번째 장, 재제본을 위해 티르탈리의 제본공에게.' 서명한 사람은 하급 사서인데, 바로 다음 날 아침 케트마르로 떠났다.", "每一页离开阅览室的纸张，以及原因。十天前：“星图，第九页，送去重新装订，交提尔塔利的装订匠。”签名的是一位副图书管理员，第二天早上就去了克特马尔。", "每一頁離開閱覽室的紙張，以及原因。十天前：「星圖，第九頁，送去重新裝訂，交提爾塔利的裝訂匠。」簽名的是一位副圖書管理員，第二天早上就去了克特馬爾。", "Mọi tờ giấy rời khỏi phòng đọc, và lý do. Mười ngày trước: 'Bản đồ sao, tờ thứ chín, mang đi đóng lại, giao thợ đóng sách ở Tirthali.' Ký tên là một thủ thư phó, người đã lên đường đi Khetmar ngay sáng hôm sau.", "Setiap lembar yang keluar dari ruang baca, dan alasannya. Sepuluh hari lalu: 'Peta bintang, lembar kesembilan, keluar untuk dijilid ulang, ke penjilid di Tirthali.' Ditandatangani seorang pustakawan muda yang berangkat ke Khetmar keesokan paginya.", "ทุกแผ่นที่ออกจากห้องอ่านหนังสือ และเหตุผล สิบวันก่อน 'แผนที่ดาว แผ่นที่เก้า ส่งเย็บเล่มใหม่ ที่ช่างเย็บเล่มในตีรถลี' ลงนามโดยผู้ช่วยบรรณารักษ์ที่ออกเดินทางไปเคทมาร์ในเช้าวันรุ่งขึ้น", "Okuma salonundan çıkan her yaprak ve nedeni. On gün önce: 'Yıldız haritası, dokuzuncu yaprak, yeniden ciltleme için, Tirthali'deki mücellide.' İmzalayan, ertesi sabah Khetmar'a gitmiş bir yardımcı kütüphaneci.", "Cada hoja que sale de la sala de lectura, y por qué. Hace diez días: «Carta estelar, hoja novena, fuera para reencuadernar, al encuadernador de Tirthali». Firmado por un subbibliotecario que se marchó a Khetmar a la mañana siguiente.", "Cada folha que sai da sala de leitura, e por quê. Dez dias atrás: 'Carta estelar, nona folha, saída para reencadernação, ao encadernador de Tirthali.' Assinado por um sub-bibliotecário que partiu para Khetmar na manhã seguinte.", "Каждый лист, что покидает читальный зал, и причина. Десять дней назад: «Звёздная карта, девятый лист, выдан на переплёт переплётчику в Тиртхали». Подпись младшего библиотекаря, который на следующее утро уехал в Кетмар.", "Кожен аркуш, що залишає читальну залу, і причина. Десять днів тому: «Зоряна карта, дев'ятий аркуш, видано на палітурку палітурникові в Тіртхалі». Підпис молодшого бібліотекаря, який наступного ранку поїхав до Кетмара."],
  "A grove stone of the Kanthari, back in its old hollow, moss already reaching for it.": ["もとのくぼみに戻ったカンタリの林の石。苔がもう手を伸ばしている。", "원래의 움푹한 자리로 돌아온 칸타리족의 숲 돌. 이끼가 벌써 그쪽으로 뻗어 오고 있다.", "一块坎塔里人的圣林石，回到了原来的凹坑里，青苔已经朝它伸过去了。", "一塊坎塔里人的聖林石，回到了原來的凹坑裡，青苔已經朝它伸過去了。", "Một hòn đá rừng thiêng của người Kanthari, đã về lại hốc cũ, rêu đã vươn tới nó.", "Batu hutan keramat orang Kanthari, kembali di cekungan lamanya, lumut sudah menjangkaunya.", "หินเขตป่าของชาวกันถารี กลับมาอยู่ในหลุมเดิม ตะไคร่เริ่มเอื้อมมาหามันแล้ว", "Kanthari'lerin bir koru taşı, eski çukuruna dönmüş; yosun şimdiden ona uzanıyor.", "Una piedra de la arboleda de los kanthari, de vuelta en su viejo hueco, con el musgo ya alargándose hacia ella.", "Uma pedra do bosque dos kanthari, de volta à sua velha cavidade, com o musgo já se estendendo até ela.", "Камень рощи кантхари, снова в своей старой ямке; мох уже тянется к нему.", "Камінь гаю кантхарі, знову у своїй старій ямці; мох уже тягнеться до нього."],
  "A grove stone of the Kanthari, carved with a leaf, dragged out of its hollow and left by a stump.": ["葉が彫られたカンタリの林の石。くぼみから引きずり出され、切り株のそばに置き去りにされている。", "잎이 새겨진 칸타리족의 숲 돌. 움푹한 자리에서 끌려 나와 그루터기 옆에 버려져 있다.", "一块刻着树叶的坎塔里人圣林石，被人从凹坑里拖出来，丢在一个树桩旁边。", "一塊刻著樹葉的坎塔里人聖林石，被人從凹坑裡拖出來，丟在一個樹樁旁邊。", "Một hòn đá rừng thiêng của người Kanthari, chạm hình chiếc lá, bị lôi ra khỏi hốc và bỏ lại cạnh một gốc cây.", "Batu hutan keramat orang Kanthari, berukir daun, diseret keluar dari cekungannya dan ditinggalkan di dekat tunggul.", "หินเขตป่าของชาวกันถารี สลักรูปใบไม้ ถูกลากออกจากหลุมแล้วทิ้งไว้ข้างตอไม้", "Kanthari'lerin yaprak oymalı bir koru taşı; çukurundan sürüklenip bir kütüğün yanında bırakılmış.", "Una piedra de la arboleda de los kanthari, tallada con una hoja, arrastrada fuera de su hueco y abandonada junto a un tocón.", "Uma pedra do bosque dos kanthari, entalhada com uma folha, arrastada para fora da cavidade e largada junto a um toco.", "Камень рощи кантхари с вырезанным листом, вытащенный из своей ямки и брошенный у пня.", "Камінь гаю кантхарі з вирізаним листком, витягнутий зі своєї ямки й кинутий біля пня."],
  "It's back where it was. The moss knows.": ["もとの場所に戻った。苔は知っている。", "원래 자리로 돌아왔다. 이끼는 안다.", "它回到原处了。青苔知道。", "它回到原處了。青苔知道。", "Nó đã về chỗ cũ. Rêu biết điều đó.", "Sudah kembali ke tempatnya. Lumut tahu.", "มันกลับเข้าที่เดิมแล้ว ตะไคร่รู้ดี", "Eski yerinde. Yosun biliyor.", "Ha vuelto a su sitio. El musgo lo sabe.", "Voltou para onde estava. O musgo sabe.", "Он снова на своём месте. Мох знает.", "Він знову на своєму місці. Мох знає."],
  "A stone carved with a leaf, out of place. Whose place it is isn't your business yet.": ["葉が彫られた石が、場違いなところにある。どこが本来の場所かは、まだあなたの知ったことではない。", "잎이 새겨진 돌이 엉뚱한 곳에 있다. 원래 누구의 자리인지는 아직 당신이 알 바 아니다.", "一块刻着树叶的石头，放错了地方。它该在谁的地方，暂时还不关你的事。", "一塊刻著樹葉的石頭，放錯了地方。它該在誰的地方，暫時還不關你的事。", "Một hòn đá chạm hình chiếc lá, nằm sai chỗ. Chỗ đó là của ai thì chưa phải việc của bạn.", "Sebuah batu berukir daun, salah tempat. Tempat siapa itu belum menjadi urusanmu.", "หินสลักรูปใบไม้ที่อยู่ผิดที่ ที่นั่นเป็นที่ของใครยังไม่ใช่ธุระของคุณ", "Yaprak oymalı bir taş, yerinde değil. Yerinin kime ait olduğu şimdilik seni ilgilendirmez.", "Una piedra tallada con una hoja, fuera de su sitio. De quién es ese sitio todavía no es asunto tuyo.", "Uma pedra entalhada com uma folha, fora do lugar. De quem é esse lugar ainda não é da sua conta.", "Камень с вырезанным листом, не на своём месте. Чьё это место — пока не ваше дело.", "Камінь із вирізаним листком, не на своєму місці. Чиє це місце — поки не ваша справа."],
  "The three grove stones are back. Now the loggers' licence.": ["三つの林の石は元に戻った。次は木こりの許可証だ。", "숲의 돌 세 개가 제자리로 돌아왔다. 이제 벌목꾼들의 허가증이다.", "三块圣林石都回去了。接下来是伐木工的许可证。", "三塊聖林石都回去了。接下來是伐木工的許可證。", "Ba hòn đá rừng thiêng đã về chỗ cũ. Giờ đến giấy phép của thợ đốn gỗ.", "Ketiga batu hutan keramat sudah kembali. Sekarang izin para penebang.", "หินเขตป่าทั้งสามก้อนกลับเข้าที่แล้ว ต่อไปคือใบอนุญาตของคนตัดไม้", "Üç koru taşı da yerinde. Sırada oduncuların izni var.", "Las tres piedras de la arboleda han vuelto. Ahora, la licencia de los leñadores.", "As três pedras do bosque voltaram. Agora, a licença dos lenhadores.", "Три камня рощи на месте. Теперь лицензия лесорубов.", "Три камені гаю на місці. Тепер ліцензія лісорубів."],
  "You roll the stone back into its hollow. It settles as if it had only been away a moment.": ["石を転がしてくぼみに戻す。ほんの一瞬離れていただけのように、すっと収まる。", "돌을 굴려 움푹한 자리로 되돌린다. 마치 잠깐 자리를 비웠을 뿐이라는 듯 제자리에 앉는다.", "你把石头滚回凹坑里。它稳稳落定，仿佛只是离开了片刻。", "你把石頭滾回凹坑裡。它穩穩落定，彷彿只是離開了片刻。", "Bạn lăn hòn đá về lại hốc. Nó nằm yên như thể chỉ mới rời đi một thoáng.", "Kau menggulingkan batu itu kembali ke cekungannya. Batu itu mapan seolah baru pergi sebentar.", "คุณกลิ้งหินกลับลงหลุม มันเข้าที่ราวกับเพิ่งจากไปเพียงครู่เดียว", "Taşı yuvarlayıp çukuruna geri koyarsın. Sanki yalnızca bir anlığına uzaklaşmış gibi yerine oturur.", "Haces rodar la piedra de vuelta a su hueco. Se asienta como si solo se hubiera ido un momento.", "Você rola a pedra de volta para a cavidade. Ela se acomoda como se só tivesse saído por um instante.", "Вы закатываете камень обратно в ямку. Он ложится так, будто отлучался лишь на минутку.", "Ви закочуєте камінь назад у ямку. Він лягає так, ніби відлучався лише на хвильку."],
  "Both of them are right. Ask Chief Engineer Devakar to unchain the Great Stepwell.": ["どちらも正しい。主任技師デヴァカルに、大階段井戸の鎖を外してもらおう。", "둘 다 옳다. 수석 기술자 데바카르에게 대계단우물의 사슬을 풀어 달라고 하자.", "他们俩都没错。去请总工程师德瓦卡尔解开大阶梯井的锁链。", "他們倆都沒錯。去請總工程師德瓦卡爾解開大階梯井的鎖鏈。", "Cả hai đều đúng. Hãy nhờ Kỹ sư trưởng Devakar tháo xích Giếng Bậc Lớn.", "Keduanya benar. Mintalah Kepala Insinyur Devakar melepas rantai Sumur Tangga Agung.", "ทั้งสองฝ่ายถูกต้อง ขอให้หัวหน้าวิศวกรเทวกรปลดโซ่บ่อขั้นบันไดใหญ่", "İkisi de haklı. Baş Mühendis Devakar'dan Büyük Basamaklı Kuyu'nun zincirini çözmesini iste.", "Los dos tienen razón. Pídele al ingeniero jefe Devakar que quite la cadena del Gran Pozo Escalonado.", "Os dois têm razão. Peça ao engenheiro-chefe Devakar que tire a corrente do Grande Poço de Degraus.", "Оба правы. Попросите главного инженера Девакара снять цепь с Великого ступенчатого колодца.", "Обидва мають рацію. Попросіть головного інженера Девакара зняти ланцюг із Великого східчастого колодязя."],
  "The clerk was paid in Gilded Court silver. Find the Gilded Court's man in Sarovan.": ["書記は金色の宮廷の銀貨で買収されていた。サロヴァンにいる金色の宮廷の手の者を探そう。", "서기는 황금 궁정의 은화로 매수당했다. 사로반에 있는 황금 궁정의 하수인을 찾자.", "书记收的是镀金宫廷的银子。去萨罗万找镀金宫廷的人。", "書記收的是鍍金宮廷的銀子。去薩羅萬找鍍金宮廷的人。", "Thư lại đã được trả bằng bạc của Triều Mạ Vàng. Hãy tìm người của Triều Mạ Vàng ở Sarovan.", "Juru tulis itu dibayar dengan perak Istana Bersepuh. Temukan orang Istana Bersepuh di Sarovan.", "เสมียนได้รับเงินเป็นเหรียญเงินของราชสำนักปิดทอง ไปหาคนของราชสำนักปิดทองในสโรวัน", "Kâtibe Yaldızlı Saray gümüşüyle ödeme yapılmış. Yaldızlı Saray'ın Sarovan'daki adamını bul.", "Al escribano le pagaron con plata de la Corte Dorada. Encuentra al hombre de la Corte Dorada en Sarovan.", "O escrivão foi pago com prata da Corte Dourada. Encontre o homem da Corte Dourada em Sarovan.", "Писарю заплатили серебром Позолоченного двора. Найдите человека Позолоченного двора в Сароване.", "Писареві заплатили сріблом Позолоченого двору. Знайдіть людину Позолоченого двору в Саровані."],
  "The deserters weren't paid. Deal with Sergeant Hask, all the same.": ["脱走兵たちは給金を受け取っていなかった。それでも、ハスク軍曹の始末はつけねばならない。", "탈영병들은 급여를 받지 못했다. 그래도 하스크 병장은 처리해야 한다.", "那些逃兵没拿到饷。但哈斯克中士还是得对付。", "那些逃兵沒拿到餉。但哈斯克中士還是得對付。", "Đám lính đào ngũ chưa được trả lương. Dù vậy, vẫn phải xử lý Trung sĩ Hask.", "Para desertir itu tak dibayar. Tetap saja, hadapi Sersan Hask.", "พวกทหารหนีทัพไม่ได้รับเงินเดือน ถึงอย่างนั้นก็ต้องจัดการจ่าฮาสก์", "Firarilere ödeme yapılmamış. Yine de Çavuş Hask'ın icabına bak.", "A los desertores no les pagaron. Aun así, encárgate del sargento Hask.", "Os desertores não foram pagos. Mesmo assim, resolva o sargento Hask.", "Дезертирам не платили. И всё же с сержантом Хаском надо разобраться.", "Дезертирам не платили. І все ж із сержантом Хаском треба розібратися."],
  "Out for rebinding, to a binder in Tirthali. There is no binder in Tirthali.": ["製本し直しのため、ティルタリの製本屋へ。ティルタリに製本屋はいない。", "재제본을 위해 티르탈리의 제본공에게. 티르탈리에 제본공은 없다.", "送去重新装订，交提尔塔利的一位装订匠。提尔塔利没有装订匠。", "送去重新裝訂，交提爾塔利的一位裝訂匠。提爾塔利沒有裝訂匠。", "Mang đi đóng lại, giao một thợ đóng sách ở Tirthali. Ở Tirthali chẳng có thợ đóng sách nào.", "Keluar untuk dijilid ulang, ke seorang penjilid di Tirthali. Tidak ada penjilid di Tirthali.", "ส่งเย็บเล่มใหม่ ที่ช่างเย็บเล่มในตีรถลี ตีรถลีไม่มีช่างเย็บเล่ม", "Yeniden ciltleme için, Tirthali'deki bir mücellide. Tirthali'de mücellit yok.", "Fuera para reencuadernar, a un encuadernador de Tirthali. No hay ningún encuadernador en Tirthali.", "Saída para reencadernação, a um encadernador em Tirthali. Não há encadernador em Tirthali.", "Выдан на переплёт переплётчику в Тиртхали. В Тиртхали нет переплётчика.", "Видано на палітурку палітурникові в Тіртхалі. У Тіртхалі немає палітурника."],
  "The road east is the Banner's to open and Hollowmere's to ask about. Come back when Hollowmere's let you out of its fence.": ["東への道を開けるのは旗の役目で、それを問い合わせる先はホロウミアだ。ホロウミアが柵の外に出してくれたら、また来るといい。", "동쪽 길을 여는 건 깃발의 몫이고, 그걸 물어볼 곳은 할로우미어야. 할로우미어가 울타리 밖으로 내보내 주거든 다시 와.", "东边那条路，开不开是铜旗的事，问不问是虚湖的事。等虚湖放你出了它的篱笆，再回来吧。", "東邊那條路，開不開是銅旗的事，問不問是虛湖的事。等虛湖放你出了它的籬笆，再回來吧。", "Con đường phía đông là việc của Cờ mở, và việc của Hollowmere hỏi. Khi nào Hollowmere cho ngươi ra khỏi hàng rào của nó thì quay lại.", "Jalan ke timur itu urusan Panji untuk dibuka dan urusan Hollowmere untuk ditanyakan. Kembalilah setelah Hollowmere membiarkanmu keluar dari pagarnya.", "ถนนสายตะวันออกเป็นหน้าที่ของธงที่จะเปิด และเป็นเรื่องของฮอลโลว์เมียร์ที่จะถามถึง กลับมาเมื่อฮอลโลว์เมียร์ปล่อยเจ้าออกจากรั้วของมันแล้ว", "Doğu yolunu açmak Sancak'ın işi, sormak Hollowmere'in. Hollowmere seni çitinin dışına bırakınca gel.", "El camino del este lo abre el Estandarte y lo pregunta Hollowmere. Vuelve cuando Hollowmere te haya dejado salir de su cerca.", "A estrada para o leste é do Estandarte para abrir e de Hollowmere para perguntar. Volte quando Hollowmere tiver deixado você sair da cerca dele.", "Дорогу на восток открывать Знамени, а спрашивать о ней — Холлоумиру. Приходите, когда Холлоумир выпустит вас за свою ограду.", "Дорогу на схід відкривати Стягу, а питати про неї — Голлоуміру. Приходьте, коли Голлоумір випустить вас за свою огорожу."],
  "Twelve mules: linen, salt, glass, lamp oil, and one crate the Obsidian Legacy's quartermaster sealed himself and wouldn't say what was in it. Four drivers. One of me.": ["ラバが十二頭。亜麻布、塩、ガラス、灯油、それに黒曜の遺統の補給係が自分で封をして中身を言おうとしなかった木箱が一つ。御者が四人。そして俺が一人。", "노새 열두 마리. 아마포, 소금, 유리, 등잔 기름, 그리고 흑요 유산의 보급관이 직접 봉인하고는 뭐가 들었는지 말하지 않은 상자 하나. 마부 넷. 나 하나.", "十二头骡子：亚麻布、盐、玻璃、灯油，还有一只黑曜遗脉的军需官亲手封上、死活不肯说里面装了什么的箱子。四个赶骡人。一个我。", "十二頭騾子：亞麻布、鹽、玻璃、燈油，還有一隻黑曜遺脈的軍需官親手封上、死活不肯說裡面裝了什麼的箱子。四個趕騾人。一個我。", "Mười hai con la: vải lanh, muối, thủy tinh, dầu đèn, và một thùng mà quan hậu cần của Di Sản Hắc Diện tự tay niêm phong và không chịu nói bên trong có gì. Bốn người đánh xe. Một mình tôi.", "Dua belas bagal: linen, garam, kaca, minyak lampu, dan satu peti yang disegel sendiri oleh juru perbekalan Warisan Obsidian dan ia tak mau bilang isinya apa. Empat kusir. Dan aku seorang.", "ล่อสิบสองตัว ผ้าลินิน เกลือ แก้ว น้ำมันตะเกียง และลังหนึ่งใบที่นายกองเสบียงของมรดกออบซิเดียนปิดผนึกเองและไม่ยอมบอกว่าข้างในมีอะไร คนขับสี่คน ข้าหนึ่งคน", "On iki katır: keten, tuz, cam, lamba yağı ve Obsidyen Mirası'nın levazımcısının kendi eliyle mühürleyip içinde ne olduğunu söylemediği bir sandık. Dört sürücü. Bir ben.", "Doce mulas: lino, sal, vidrio, aceite de lámpara y una caja que el intendente del Legado de Obsidiana selló él mismo sin querer decir qué había dentro. Cuatro arrieros. Y un servidor.", "Doze mulas: linho, sal, vidro, óleo de lamparina e um caixote que o intendente do Legado de Obsidiana lacrou ele mesmo e não quis dizer o que tinha dentro. Quatro tropeiros. E eu, um só.", "Двенадцать мулов: лён, соль, стекло, ламповое масло и один ящик, который квартирмейстер Обсидианового наследия опечатал сам и так и не сказал, что внутри. Четыре погонщика. Один я.", "Дванадцять мулів: льон, сіль, скло, лампова олія і одна скриня, яку квартирмейстер Обсидіанової спадщини опечатав сам і так і не сказав, що всередині. Четверо погоничів. Один я."],
  "Dacoits have stopped three caravans at the Gate of Rains this season. The Banner won't ride past its own bay. I need somebody who will.": ["この季節、雨の門で盗賊どもが隊商を三つも止めた。旗の連中は自分たちの湾から先へは馬を出さない。出してくれる誰かが必要なんだ。", "이번 철에 노상강도들이 비의 문에서 대상을 세 번이나 세웠어. 깃발은 제 만 너머로는 말을 몰지 않아. 그렇게 해 줄 누군가가 필요해.", "这一季，劫匪已经在雨之门拦下了三支商队。铜旗不肯骑过他们自己的海湾。我需要一个肯去的人。", "這一季，劫匪已經在雨之門攔下了三支商隊。銅旗不肯騎過他們自己的海灣。我需要一個肯去的人。", "Mùa này bọn cướp đường đã chặn ba đoàn lữ hành ở Cổng Mưa. Cờ Đồng không chịu cưỡi ngựa qua khỏi vịnh của chính họ. Tôi cần một người chịu đi.", "Begal sudah menghentikan tiga kafilah di Gerbang Hujan musim ini. Panji tak mau berkuda melewati teluknya sendiri. Aku butuh seseorang yang mau.", "ฤดูนี้โจรปล้นทางหยุดกองคาราวานที่ประตูแห่งสายฝนไปแล้วสามขบวน ธงไม่ยอมขี่ม้าเลยอ่าวของตัวเองไป ข้าต้องการใครสักคนที่ยอม", "Haydutlar bu mevsim Yağmur Kapısı'nda üç kervan durdurdu. Sancak kendi körfezinin ötesine at sürmez. Sürecek birine ihtiyacım var.", "Los bandoleros han detenido tres caravanas en la Puerta de las Lluvias esta temporada. El Estandarte no cabalga más allá de su propia bahía. Necesito a alguien que sí lo haga.", "Os bandoleiros pararam três caravanas no Portão das Chuvas nesta estação. O Estandarte não cavalga além da própria baía. Preciso de alguém que cavalgue.", "Дакойты в этом сезоне уже трижды останавливали караваны у Врат Дождей. Знамя не выезжает дальше своей бухты. Мне нужен тот, кто выедет.", "Дакойти цього сезону вже тричі зупиняли каравани біля Брами Дощів. Стяг не виїжджає далі своєї затоки. Мені потрібен той, хто виїде."],
  "The Gate's a day east. The dacoits camp in the hills south of the road; their chief wears a red turban and is proud of it. Deal with him and we'll go through. I'll meet you at Tirthali, at the ford.": ["門は東へ一日の距離だ。ダコイトどもは街道の南の丘に陣取っていて、頭目は赤いターバンを巻き、それを自慢にしている。そいつを片付けてくれれば通り抜けられる。ティルタリの渡し場で落ち合おう。", "문은 동쪽으로 하루 거리요. 노상강도들은 길 남쪽 언덕에 진을 치고 있고, 두목은 붉은 터번을 두르고 그걸 자랑으로 여기지. 그놈을 처리해 주면 우리가 지나갈 수 있소. 티르탈리 나루에서 만납시다.", "门在东边一天路程外。劫匪在大路南边的山里扎营；他们的头目缠着红头巾，还以此为荣。解决掉他，我们就能过去。我在提尔塔利的渡口等你。", "門在東邊一天路程外。劫匪在大路南邊的山裡紮營；他們的頭目纏著紅頭巾，還以此為榮。解決掉他，我們就能過去。我在提爾塔利的渡口等你。", "Cổng cách đây một ngày đường về phía đông. Bọn cướp đường cắm trại trên những ngọn đồi phía nam con đường; tên thủ lĩnh quấn khăn xếp đỏ và tự hào về nó lắm. Xử lý hắn đi rồi chúng tôi sẽ qua được. Tôi sẽ gặp bạn ở Tirthali, chỗ bến lội.", "Gerbangnya sehari perjalanan ke timur. Para begal berkemah di perbukitan selatan jalan; pemimpin mereka memakai sorban merah dan bangga akan itu. Bereskan dia, dan kami bisa lewat. Aku akan menemuimu di Tirthali, di tempat penyeberangan.", "ประตูอยู่ห่างไปทางตะวันออกหนึ่งวัน พวกโจรปล้นทางตั้งค่ายอยู่บนเนินเขาทางใต้ของถนน หัวหน้าของพวกมันโพกผ้าสีแดงและภูมิใจกับมันนัก จัดการมันเสีย แล้วเราจะผ่านไปได้ ข้าจะไปพบเจ้าที่ตีรถลี ตรงท่าข้าม", "Kapı bir günlük yol doğuda. Haydutlar yolun güneyindeki tepelerde kamp kuruyor; reisleri kırmızı bir sarık takıyor ve bununla gurur duyuyor. Onun icabına bak, biz de geçelim. Seninle Tirthali'de, geçitte buluşuruz.", "La Puerta está a un día al este. Los bandoleros acampan en las colinas al sur del camino; su jefe lleva un turbante rojo y está orgulloso de él. Encárgate de él y pasaremos. Te veré en Tirthali, en el vado.", "O Portão fica a um dia a leste. Os bandoleiros acampam nas colinas ao sul da estrada; o chefe deles usa um turbante vermelho e se orgulha disso. Dê um jeito nele e nós passamos. Encontro você em Tirthali, no vau.", "До Врат день пути на восток. Дакойты стоят лагерем в холмах к югу от дороги; их главарь носит красный тюрбан и гордится им. Разберись с ним — и мы пройдём. Встретимся в Тиртхали, у брода.", "До Брами день шляху на схід. Дакойти стоять табором у пагорбах на південь від дороги; їхній ватажок носить червоний тюрбан і пишається ним. Розберися з ним — і ми пройдемо. Зустрінемося в Тіртхалі, біля броду."],
  "I don't know, and I'm paid not to. That's the most expensive kind of crate there is.": ["知らないし、知らないことで金をもらってる。世の中でいちばん高くつく種類の木箱さ。", "모르오. 모르는 대가로 돈을 받거든. 세상에서 제일 비싼 종류의 상자지.", "我不知道，而且我拿钱就是为了不知道。这是世上最贵的一种箱子。", "我不知道，而且我拿錢就是為了不知道。這是世上最貴的一種箱子。", "Tôi không biết, và tôi được trả tiền để không biết. Đó là loại thùng đắt nhất trên đời.", "Aku tidak tahu, dan aku dibayar supaya tidak tahu. Itulah jenis peti yang paling mahal.", "ข้าไม่รู้ และข้าได้ค่าจ้างให้ไม่รู้ นั่นคือลังชนิดที่แพงที่สุดในโลก", "Bilmiyorum, bilmemem için de para alıyorum. Sandıkların en pahalısı budur.", "No lo sé, y me pagan por no saberlo. Es la clase de caja más cara que existe.", "Não sei, e me pagam para não saber. É o tipo de caixote mais caro que existe.", "Не знаю, и мне платят за то, чтобы не знал. Это самый дорогой вид ящиков на свете.", "Не знаю, і мені платять, щоб не знав. Це найдорожчий різновид скринь на світі."],
  "The dacoits are in the hills south of the Gate. Their chief's the one in the red turban. I'm counting the mules again.": ["ダコイトどもは門の南の丘にいる。頭目は赤いターバンのやつだ。おれはまたラバを数えておく。", "노상강도들은 문 남쪽 언덕에 있소. 붉은 터번을 두른 놈이 두목이지. 나는 노새를 다시 세고 있겠소.", "劫匪在门南边的山里。缠红头巾的那个就是头目。我再数一遍骡子。", "劫匪在門南邊的山裡。纏紅頭巾的那個就是頭目。我再數一遍騾子。", "Bọn cướp đường ở trên đồi phía nam Cổng. Tên quấn khăn xếp đỏ là thủ lĩnh. Tôi đi đếm lại lũ la đây.", "Para begal ada di perbukitan selatan Gerbang. Pemimpinnya yang bersorban merah. Aku mau menghitung bagal lagi.", "พวกโจรปล้นทางอยู่บนเนินเขาทางใต้ของประตู หัวหน้าคือไอ้คนที่โพกผ้าแดง ข้าจะนับล่อใหม่อีกรอบ", "Haydutlar Kapı'nın güneyindeki tepelerde. Reisleri kırmızı sarıklı olan. Ben katırları yeniden sayıyorum.", "Los bandoleros están en las colinas al sur de la Puerta. Su jefe es el del turbante rojo. Yo voy a contar las mulas otra vez.", "Os bandoleiros estão nas colinas ao sul do Portão. O chefe é o de turbante vermelho. Vou contar as mulas de novo.", "Дакойты в холмах к югу от Врат. Главарь — тот, что в красном тюрбане. А я опять пересчитываю мулов.", "Дакойти в пагорбах на південь від Брами. Ватажок — той, що в червоному тюрбані. А я знову перераховую мулів."],
  "Linen, salt, glass, oil, the crate. Linen, salt, glass, oil, the crate. It helps.": ["亜麻布、塩、ガラス、油、木箱。亜麻布、塩、ガラス、油、木箱。こうすると落ち着くんだ。", "아마포, 소금, 유리, 기름, 상자. 아마포, 소금, 유리, 기름, 상자. 이러면 좀 낫소.", "亚麻布、盐、玻璃、油、箱子。亚麻布、盐、玻璃、油、箱子。念叨念叨，心里踏实。", "亞麻布、鹽、玻璃、油、箱子。亞麻布、鹽、玻璃、油、箱子。念叨念叨，心裡踏實。", "Vải lanh, muối, thủy tinh, dầu, cái thùng. Vải lanh, muối, thủy tinh, dầu, cái thùng. Đọc thế cho đỡ lo.", "Linen, garam, kaca, minyak, peti. Linen, garam, kaca, minyak, peti. Lumayan menenangkan.", "ผ้าลินิน เกลือ แก้ว น้ำมัน ลังนั่น ผ้าลินิน เกลือ แก้ว น้ำมัน ลังนั่น ท่องไว้แล้วสบายใจ", "Keten, tuz, cam, yağ, sandık. Keten, tuz, cam, yağ, sandık. İyi geliyor.", "Lino, sal, vidrio, aceite, la caja. Lino, sal, vidrio, aceite, la caja. Ayuda.", "Linho, sal, vidro, óleo, o caixote. Linho, sal, vidro, óleo, o caixote. Ajuda.", "Лён, соль, стекло, масло, ящик. Лён, соль, стекло, масло, ящик. Помогает.", "Льон, сіль, скло, олія, скриня. Льон, сіль, скло, олія, скриня. Допомагає."],
  "We made it! Twelve mules, four drivers, one crate. I'll be telling this one in Khetmar for a year.": ["やったぞ！ラバ十二頭、御者四人、木箱ひとつ。この話はケトマルで一年は語れるな。", "해냈소! 노새 열두 마리, 마부 넷, 상자 하나. 케트마르에서 일 년은 이 얘기를 하고 다니겠군.", "我们成功了！十二头骡子，四个车夫，一个箱子。这事我能在克特马尔讲上一年。", "我們成功了！十二頭騾子，四個車夫，一個箱子。這事我能在克特馬爾講上一年。", "Chúng ta làm được rồi! Mười hai con la, bốn người đánh xe, một cái thùng. Chuyện này tôi sẽ kể ở Khetmar cả năm.", "Kita berhasil! Dua belas bagal, empat kusir, satu peti. Cerita ini bakal kuceritakan di Khetmar setahun penuh.", "เราทำได้! ล่อสิบสองตัว คนขับสี่คน ลังหนึ่งใบ เรื่องนี้ข้าจะเล่าที่เคทมาร์ไปได้อีกเป็นปี", "Başardık! On iki katır, dört sürücü, bir sandık. Bunu Khetmar'da bir yıl anlatırım.", "¡Lo logramos! Doce mulas, cuatro arrieros, una caja. Esta la voy a contar en Khetmar durante un año.", "Conseguimos! Doze mulas, quatro tropeiros, um caixote. Vou contar essa em Khetmar por um ano.", "Добрались! Двенадцать мулов, четыре погонщика, один ящик. В Кетмаре я буду рассказывать об этом целый год.", "Дісталися! Дванадцять мулів, четверо погоничів, одна скриня. У Кетмарі я розповідатиму про це цілий рік."],
  "Tirthali, then Sarovan, then home. The rain's on the way. It's always on the way.": ["ティルタリ、それからサロヴァン、それから故郷だ。雨が近づいてる。雨はいつだって近づいてるがな。", "티르탈리, 다음은 사로반, 그다음엔 집이오. 비가 오고 있소. 비는 늘 오는 중이지.", "提尔塔利，然后萨罗万，然后回家。雨要来了。雨总是要来了。", "提爾塔利，然後薩羅萬，然後回家。雨要來了。雨總是要來了。", "Tirthali, rồi Sarovan, rồi về nhà. Mưa sắp đến rồi. Lúc nào mưa cũng sắp đến.", "Tirthali, lalu Sarovan, lalu pulang. Hujan sedang dalam perjalanan. Hujan selalu dalam perjalanan.", "ตีรถลี ต่อด้วยสโรวัน แล้วก็กลับบ้าน ฝนกำลังมา มันกำลังมาเสมอแหละ", "Tirthali, sonra Sarovan, sonra ev. Yağmur yolda. Yağmur hep yolda.", "Tirthali, luego Sarovan, luego a casa. La lluvia viene de camino. Siempre viene de camino.", "Tirthali, depois Sarovan, depois casa. A chuva está a caminho. Está sempre a caminho.", "Тиртхали, потом Сарован, потом домой. Дождь на подходе. Он всегда на подходе.", "Тіртхалі, потім Сарован, потім додому. Дощ наближається. Він завжди наближається."],
  "The Khetmar caravan! Through the Gate with all its mules. You'll be the one who dealt with Red Jhanda, then. The ford thanks you, and so do I.": ["ケトマルのキャラバンだ！ラバ一頭欠けずに門を抜けてきたか。では、赤のジャンダを片付けたのはあんただな。渡し場が礼を言っている。わたしもだ。", "케트마르 대상이로군! 노새 한 마리 잃지 않고 문을 넘어왔어. 그럼 붉은 잔다를 처리한 게 당신이겠군. 나루가 당신께 감사하오. 나도 그렇고.", "克特马尔的商队！骡子一头不少地过了门。那么，解决掉红詹达的就是你了。渡口感谢你，我也一样。", "克特馬爾的商隊！騾子一頭不少地過了門。那麼，解決掉紅詹達的就是你了。渡口感謝你，我也一樣。", "Đoàn lữ hành Khetmar! Qua Cổng mà không mất con la nào. Vậy ra bạn là người đã xử lý Jhanda Đỏ. Bến lội cảm ơn bạn, và tôi cũng vậy.", "Kafilah Khetmar! Lewat Gerbang dengan semua bagalnya. Jadi kaulah yang membereskan Jhanda Merah. Penyeberangan ini berterima kasih padamu, dan aku juga.", "กองคาราวานจากเคทมาร์! ผ่านประตูมาได้พร้อมล่อครบทุกตัว ถ้าอย่างนั้นเจ้าคงเป็นคนที่จัดการจันดาแดงสินะ ท่าข้ามขอบใจเจ้า ข้าก็เช่นกัน", "Khetmar kervanı! Bütün katırlarıyla Kapı'dan geçmiş. Demek Kızıl Jhanda'nın icabına bakan sensin. Geçit sana teşekkür ediyor, ben de.", "¡La caravana de Khetmar! Ha cruzado la Puerta con todas sus mulas. Así que tú eres quien se encargó de Jhanda el Rojo. El vado te lo agradece, y yo también.", "A caravana de Khetmar! Atravessou o Portão com todas as mulas. Então foi você quem deu um jeito em Jhanda, o Vermelho. O vau agradece, e eu também.", "Кетмарский караван! Прошёл Врата со всеми мулами. Значит, с Красным Джхандой разобрались благодаря тебе. Брод тебе благодарен, и я тоже.", "Кетмарський караван! Пройшов Браму з усіма мулами. Отже, з Червоним Джхандою розібралися завдяки тобі. Брід тобі вдячний, і я теж."],
  "I look in every crate that crosses: it's the ledger's rule. This one has the Obsidian Legacy's seal and, inside, under the straw, this: a seated figure of Azhurak stone, earth still in the folds. Dug up somewhere in Kharaveth, and not by anyone with a right to.": ["渡る木箱はすべて中を改める。それが台帳の決まりだ。これには黒曜の遺統の封印があって、中の藁の下にはこれが入っていた。アズラク石の座像で、ひだにまだ土が残っている。カラヴェスのどこかで掘り出されたものだ。それも、掘る権利などない誰かの手でな。", "건너는 상자는 전부 열어 보오. 장부의 규칙이지. 이건 흑요 유산의 봉인이 찍혀 있었고, 안에는 짚 밑에 이게 있었소. 아주라크 돌로 만든 좌상인데, 주름 사이에 아직 흙이 묻어 있지. 카라베스 어딘가에서 파낸 거요. 그럴 권리가 있는 자의 손은 아니고.", "每个过渡口的箱子我都要查看：这是账簿的规矩。这一箱盖着黑曜遗脉的封印，里面的稻草底下是这个：一尊阿祖拉克石雕的坐像，褶皱里还带着泥土。是在卡拉维斯某处挖出来的，而且挖的人无权这么做。", "每個過渡口的箱子我都要查看：這是帳簿的規矩。這一箱蓋著黑曜遺脈的封印，裡面的稻草底下是這個：一尊阿祖拉克石雕的坐像，褶皺裡還帶著泥土。是在卡拉維斯某處挖出來的，而且挖的人無權這麼做。", "Thùng nào qua bến tôi cũng mở ra xem: đó là quy định của sổ sách. Thùng này mang ấn của Di Sản Hắc Diện, và bên trong, dưới lớp rơm, là thứ này: một pho tượng ngồi bằng đá Azhurak, đất vẫn còn bám trong các nếp gấp. Được đào lên ở đâu đó tại Kharaveth, và không phải bởi kẻ nào có quyền làm thế.", "Aku memeriksa setiap peti yang menyeberang: itu aturan buku catatan. Yang ini bersegel Warisan Obsidian dan, di dalamnya, di bawah jerami, ada ini: patung duduk dari batu Azhurak, tanahnya masih menempel di lipatan-lipatannya. Digali di suatu tempat di Kharaveth, dan bukan oleh orang yang berhak.", "ข้าเปิดดูทุกลังที่ข้ามไป นั่นเป็นกฎของสมุดบัญชี ลังนี้มีตราของมรดกออบซิเดียน และข้างใน ใต้ฟาง มีสิ่งนี้ รูปปั้นนั่งทำจากหินอาซูรัก ดินยังติดอยู่ตามรอยจีบ ขุดขึ้นมาจากที่ไหนสักแห่งในคาราเวธ และคนขุดก็ไม่ได้มีสิทธิ์ทำเช่นนั้น", "Geçen her sandığın içine bakarım: defterin kuralı bu. Bunun üzerinde Obsidyen Mirası'nın mührü var ve içinde, samanın altında şu: Azhurak taşından oturan bir figür, kıvrımlarında hâlâ toprak. Kharaveth'te bir yerden çıkarılmış, hem de buna hakkı olmayan biri tarafından.", "Miro dentro de cada caja que cruza: es la regla del registro. Esta lleva el sello del Legado de Obsidiana y, dentro, bajo la paja, esto: una figura sedente de piedra de Azhurak, con tierra aún en los pliegues. Desenterrada en algún lugar de Kharaveth, y no por alguien con derecho a hacerlo.", "Olho dentro de todo caixote que atravessa: é a regra do livro de registros. Este tem o selo do Legado de Obsidiana e, dentro, sob a palha, isto: uma figura sentada de pedra de Azhurak, ainda com terra nas dobras. Desenterrada em algum lugar de Kharaveth, e não por alguém com direito a isso.", "Я заглядываю в каждый ящик, что переправляется: таково правило книги учёта. На этом печать Обсидианового наследия, а внутри, под соломой, вот что: сидящая фигура из азуракского камня, в складках ещё земля. Выкопана где-то в Харавете, и не тем, у кого было на это право.", "Я зазираю в кожну скриню, що переправляється: таке правило книги обліку. На цій печатка Обсидіанової спадщини, а всередині, під соломою, ось що: сидяча фігура з азуракського каменю, у складках ще земля. Викопана десь у Хараветі, і не тим, хто мав на це право."],
  "The Archive. Hm. They'll write it down and argue about it, and nobody will sell it again. I'll send it with the next boat down the river.": ["文書館か。ふむ。あそこなら記録をつけて議論して、二度と誰にも売られまい。次に川を下る舟で送ろう。", "서고라. 흠. 거기선 기록하고 논쟁하겠지. 그리고 다시는 누구도 팔지 못할 거요. 다음에 강을 따라 내려가는 배에 실어 보내겠소.", "档案馆。嗯。他们会把它记下来，再为它争论一番，以后再也没人能把它卖掉。我会让下一班顺流而下的船把它带去。", "檔案館。嗯。他們會把它記下來，再為它爭論一番，以後再也沒人能把它賣掉。我會讓下一班順流而下的船把它帶去。", "Văn khố à. Hừm. Họ sẽ ghi chép lại rồi tranh cãi về nó, và sẽ không ai bán nó lần nữa. Tôi sẽ gửi theo chuyến thuyền xuôi dòng tới.", "Arsip. Hm. Mereka akan mencatatnya dan memperdebatkannya, dan tak seorang pun akan menjualnya lagi. Akan kukirim dengan perahu berikutnya ke hilir.", "หอจดหมายเหตุงั้นรึ อืม พวกนั้นจะจดบันทึกแล้วก็ถกเถียงกันเรื่องมัน และจะไม่มีใครเอามันไปขายอีก ข้าจะส่งไปกับเรือลำถัดไปที่ล่องลงแม่น้ำ", "Arşiv. Hım. Onu kayda geçirip üzerine tartışırlar ve kimse onu bir daha satamaz. Nehirden aşağı giden ilk tekneyle gönderirim.", "El Archivo. Hum. Lo anotarán y discutirán sobre ello, y nadie volverá a venderla. La enviaré en la próxima barca río abajo.", "O Arquivo. Hum. Vão registrá-la e discutir sobre ela, e ninguém nunca mais vai vendê-la. Mando no próximo barco rio abaixo.", "Архив. Хм. Там её запишут, поспорят о ней, и больше никто её не продаст. Отправлю со следующей лодкой вниз по реке.", "Архів. Гм. Там її запишуть, посперечаються про неї, і більше ніхто її не продасть. Відправлю наступним човном униз по річці."],
  "Back to Kharaveth, to the Legacy that keeps every monument and sealed this one into a crate. I'll put it on the caravan home, with a note. A polite one.": ["カラヴェスへ、か。あらゆる遺跡を守っていながら、これを木箱に封じ込めた遺統のもとへ。帰りのキャラバンに載せよう。手紙を添えてな。丁寧なやつを。", "카라베스로, 모든 유적을 지킨다면서 이걸 상자에 봉해 넣은 그 유산에게 돌려보내라. 귀향하는 대상 편에 실어 보내겠소. 쪽지도 하나 붙여서. 정중한 걸로.", "送回卡拉维斯，送回那个看管着每一座古迹、却把这一尊封进箱子的遗脉。我会把它放上回程的商队，附一张便条。一张客气的便条。", "送回卡拉維斯，送回那個看管著每一座古蹟、卻把這一尊封進箱子的遺脈。我會把它放上回程的商隊，附一張便條。一張客氣的便條。", "Trả về Kharaveth, cho cái Di Sản giữ gìn mọi di tích mà lại niêm phong pho này vào thùng. Tôi sẽ đặt nó lên đoàn lữ hành về nước, kèm một lá thư. Một lá thư lịch sự.", "Kembali ke Kharaveth, kepada Warisan yang menjaga setiap monumen dan menyegel yang satu ini ke dalam peti. Akan kutaruh di kafilah yang pulang, dengan sepucuk surat. Surat yang sopan.", "ส่งกลับคาราเวธ กลับไปหามรดกที่ดูแลอนุสรณ์ทุกแห่ง แต่ดันผนึกชิ้นนี้ลงลัง ข้าจะใส่มันไปกับกองคาราวานขากลับ พร้อมจดหมายแนบ ฉบับที่สุภาพด้วย", "Kharaveth'e geri, her anıtı koruyan ve bunu bir sandığa mühürleyen Miras'a. Onu eve dönen kervana koyarım, bir notla. Kibar bir notla.", "De vuelta a Kharaveth, al Legado que custodia cada monumento y que metió este en una caja sellada. La pondré en la caravana de regreso, con una nota. Una nota educada.", "De volta a Kharaveth, ao Legado que guarda todos os monumentos e lacrou este num caixote. Vou colocá-la na caravana de volta, com um bilhete. Um bilhete educado.", "Обратно в Харавет, тому самому Наследию, что бережёт каждый памятник, а этот запечатало в ящик. Отправлю с караваном домой, с запиской. Вежливой.", "Назад до Харавета, тій самій Спадщині, що береже кожну пам'ятку, а цю запечатала в скриню. Відправлю з караваном додому, із запискою. Чемною."],
  "You've come a long way to stand in a palace that's arguing with itself. Have you seen my tanks? A third full of silt. In ten years the rain will run to the sea and Ilavarta with it.": ["自分と言い争っている宮殿に立つために、ずいぶん遠くから来たものだ。わたしの貯水池を見たか？三分の一が泥で埋まっている。十年もすれば、雨は海へ流れ去り、イラヴァルタもろとも消えるだろう。", "스스로와 다투는 궁전에 서려고 먼 길을 왔구나. 내 저수지들을 보았느냐? 3분의 1이 토사로 차 있다. 십 년 뒤면 비는 바다로 흘러가 버릴 것이고, 일라바르타도 함께 떠내려가겠지.", "你远道而来，却站在一座和自己吵个不停的宫殿里。你看过我的水池了吗？三分之一都是淤泥。再过十年，雨水会流进大海，伊拉瓦塔也会跟着流走。", "你遠道而來，卻站在一座和自己吵個不停的宮殿裡。你看過我的水池了嗎？三分之一都是淤泥。再過十年，雨水會流進大海，伊拉瓦塔也會跟著流走。", "Ngươi đã đi một quãng đường dài để đứng trong một cung điện đang tự cãi nhau với chính nó. Ngươi đã thấy các hồ chứa của ta chưa? Một phần ba đầy bùn. Mười năm nữa, mưa sẽ chảy ra biển, và Ilavarta cũng trôi theo.", "Kau datang dari jauh hanya untuk berdiri di istana yang sedang bertengkar dengan dirinya sendiri. Sudahkah kau melihat telaga-telagaku? Sepertiganya penuh lumpur. Sepuluh tahun lagi hujan akan mengalir ke laut, dan Ilavarta ikut bersamanya.", "เจ้าเดินทางมาไกลเพื่อมายืนอยู่ในวังที่กำลังทะเลาะกับตัวเอง เจ้าเห็นสระของเราแล้วหรือยัง ตะกอนเต็มไปหนึ่งในสามแล้ว อีกสิบปี ฝนจะไหลลงทะเล และอิลาวรรตะก็จะไหลตามไปด้วย", "Kendi kendisiyle tartışan bir sarayda durmak için uzun bir yol geldin. Havuzlarımı gördün mü? Üçte biri siltle dolu. On yıl içinde yağmur denize akıp gidecek, Ilavarta da onunla birlikte.", "Has recorrido un largo camino para plantarte en un palacio que discute consigo mismo. ¿Has visto mis estanques? Llenos de cieno hasta un tercio. Dentro de diez años, la lluvia correrá al mar, e Ilavarta con ella.", "Você veio de longe para estar num palácio que discute consigo mesmo. Já viu meus tanques? Um terço cheio de lodo. Em dez anos a chuva vai correr para o mar, e Ilavarta junto com ela.", "Далёкий путь — и всё ради того, чтобы стоять во дворце, который спорит сам с собой. Посмотри на мои пруды: они на треть заполнены илом. Через десять лет дождь будет утекать в море, а с ним и Илаварта.", "Далекий шлях — і все заради того, щоб стояти в палаці, який сперечається сам із собою. Поглянь на мої стави: вони на третину заповнені мулом. За десять років дощ стікатиме в море, а з ним і Ілаварта."],
  "My engineers want the temple's offerings to dig. My treasurers want the offerings left to the river. I've heard them both too often to hear either. Will you hear them for me?": ["技師たちは寺院の供物を浚渫に使いたがる。会計役たちは供物を川に捧げたままにしたがる。どちらの言い分も聞きすぎて、もうどちらも耳に入らぬ。わたしの代わりに聞いてくれぬか？", "내 기술자들은 사원의 공물로 준설을 하길 원하고, 재무관들은 공물을 강에 맡겨 두길 원한다. 둘 다 너무 자주 들어서 이제 어느 쪽도 들리지 않는구나. 나 대신 그들의 말을 들어 주겠느냐?", "我的工程师想用神庙的供奉来清淤。我的司库们想让供奉留给河流。两边的话我都听得太多，反倒哪边都听不进去了。你愿意替我听听吗？", "我的工程師想用神廟的供奉來清淤。我的司庫們想讓供奉留給河流。兩邊的話我都聽得太多，反倒哪邊都聽不進去了。你願意替我聽聽嗎？", "Các kỹ sư của ta muốn dùng lễ vật của đền để nạo vét. Các thủ quỹ của ta muốn để lễ vật lại cho dòng sông. Ta đã nghe cả hai quá nhiều lần đến mức chẳng còn nghe nổi bên nào. Ngươi sẽ nghe họ thay ta chứ?", "Para insinyurku ingin persembahan kuil dipakai untuk mengeruk. Para bendaharaku ingin persembahan itu dibiarkan untuk sungai. Aku sudah terlalu sering mendengar keduanya sampai tak bisa lagi mendengar salah satunya. Maukah kau mendengarkan mereka untukku?", "วิศวกรของเราอยากใช้เครื่องบูชาของวัดไปขุดลอก เหรัญญิกของเราอยากให้เครื่องบูชาเป็นของแม่น้ำต่อไป เราฟังทั้งสองฝ่ายมาบ่อยจนไม่ได้ยินฝ่ายใดอีกแล้ว เจ้าจะช่วยฟังแทนเราได้หรือไม่", "Mühendislerim tapınağın adaklarıyla kazı yapmak istiyor. Haznedarlarım adakların nehre bırakılmasını istiyor. İkisini de o kadar sık dinledim ki artık hiçbirini duyamıyorum. Benim yerime onları dinler misin?", "Mis ingenieros quieren las ofrendas del templo para dragar. Mis tesoreros quieren que las ofrendas se dejen al río. Los he oído a ambos tantas veces que ya no oigo a ninguno. ¿Los escucharás por mí?", "Meus engenheiros querem as oferendas do templo para dragar. Meus tesoureiros querem que as oferendas fiquem para o rio. Já ouvi os dois tantas vezes que não consigo mais ouvir nenhum. Você os ouve por mim?", "Мои инженеры хотят пустить храмовые подношения на расчистку. Мои казначеи хотят оставить подношения реке. Я слышала их обоих так часто, что уже не слышу ни тех, ни других. Выслушаешь их за меня?", "Мої інженери хочуть пустити храмові пожертви на розчищення. Мої скарбники хочуть залишити пожертви річці. Я чула їх обох так часто, що вже не чую ані тих, ані інших. Вислухаєш їх замість мене?"],
  "Devakar and Ambika are both here, glaring at each other from opposite pillars. And read the Great Tank's measure, at the top of the ghats. The water doesn't take sides.": ["デヴァカルとアンビカはどちらもここにいる。向かい合った柱から睨み合っておるわ。それと、ガートの上にある大貯水池の水位標を読むがいい。水はどちらの味方もせぬ。", "데바카르와 암비카 둘 다 여기 있다. 마주 선 기둥에서 서로를 노려보고 있지. 그리고 가트 꼭대기에 있는 대저수지 수위표를 읽어 보아라. 물은 누구 편도 들지 않는다.", "德瓦卡尔和安比卡都在这儿，各站一根柱子互相瞪着。还有，去读一读河阶顶上大水池的水位标。水不偏袒任何一方。", "德瓦卡爾和安比卡都在這兒，各站一根柱子互相瞪著。還有，去讀一讀河階頂上大水池的水位標。水不偏袒任何一方。", "Devakar và Ambika đều ở đây, đang lườm nhau từ hai cột đối diện. Và hãy đọc thước đo của Hồ Lớn, ở trên cùng bậc ghat. Nước thì không đứng về phe nào.", "Devakar dan Ambika sama-sama ada di sini, saling melotot dari pilar yang berseberangan. Dan bacalah takaran Telaga Agung, di puncak tangga ghat. Air tidak memihak.", "เทวกรกับอัมพิกาอยู่ที่นี่ทั้งคู่ ยืนจ้องกันจากเสาคนละฝั่ง และไปอ่านเครื่องวัดระดับน้ำของสระใหญ่ที่บนสุดของท่าน้ำด้วย น้ำไม่เข้าข้างใคร", "Devakar da Ambika da burada, karşılıklı sütunlardan birbirlerine dik dik bakıyorlar. Bir de gat basamaklarının tepesindeki Büyük Havuz'un ölçeğini oku. Su kimsenin tarafını tutmaz.", "Devakar y Ambika están aquí los dos, fulminándose con la mirada desde pilares opuestos. Y lee la medida del Gran Estanque, en lo alto de los ghats. El agua no toma partido.", "Devakar e Ambika estão os dois aqui, se encarando de pilares opostos. E leia a medida do Grande Tanque, no alto dos ghats. A água não toma partido.", "Девакар и Амбика оба здесь, сверлят друг друга взглядами от противоположных колонн. И прочти мерный знак Великого пруда, наверху гатов. Вода ни на чьей стороне.", "Девакар і Амбіка обоє тут, свердлять одне одного поглядами від протилежних колон. І прочитай мірну позначку Великого ставу, нагорі гатів. Вода ні на чиєму боці."],
  "Well? Which of them is right? Don't tell me both. Everybody says both.": ["それで？どちらが正しい？両方などと言うでないぞ。誰もが両方と言う。", "그래서? 누가 옳으냐? 둘 다라고는 하지 마라. 다들 둘 다라고 하니.", "怎么样？他们谁对？别跟我说都对。人人都说都对。", "怎麼樣？他們誰對？別跟我說都對。人人都說都對。", "Sao? Bên nào đúng? Đừng nói với ta là cả hai. Ai cũng nói cả hai.", "Jadi? Siapa yang benar? Jangan bilang keduanya. Semua orang bilang keduanya.", "ว่าอย่างไร ใครถูก อย่าบอกเราว่าถูกทั้งคู่ ใครๆ ก็พูดว่าถูกทั้งคู่", "Eee? Hangisi haklı? Bana ikisi de deme. Herkes ikisi de diyor.", "¿Y bien? ¿Cuál de los dos tiene razón? No me digas que ambos. Todo el mundo dice que ambos.", "E então? Qual dos dois tem razão? Não me diga que os dois. Todo mundo diz que os dois.", "Ну? Кто из них прав? Только не говори, что оба. Все говорят, что оба.", "Ну? Хто з них має рацію? Тільки не кажи, що обоє. Усі кажуть, що обоє."],
  "The Stepwell had a sluice once that flushed the Great Tank. My great-grandmother's engineers closed it. I never knew why.": ["かつて階段井戸には、大貯水池を洗い流す水門があった。わたしの曾祖母の技師たちがそれを閉じたのだ。理由は知らぬままだ。", "예전에 계단우물에는 대저수지를 씻어 내리는 수문이 있었다. 내 증조할머니의 기술자들이 그것을 닫았지. 이유는 끝내 알지 못했다.", "阶梯井从前有一道水闸，能冲刷大水池。我曾祖母的工程师把它关上了。我一直不知道为什么。", "階梯井從前有一道水閘，能沖刷大水池。我曾祖母的工程師把它關上了。我一直不知道為什麼。", "Giếng Bậc từng có một cửa cống để xả rửa Hồ Lớn. Các kỹ sư của cụ bà ta đã đóng nó lại. Ta chưa bao giờ biết tại sao.", "Sumur Tangga dulu punya pintu air yang menggelontor Telaga Agung. Para insinyur nenek buyutku menutupnya. Aku tak pernah tahu kenapa.", "บ่อขั้นบันไดเคยมีประตูระบายน้ำที่ใช้ชะล้างสระใหญ่ วิศวกรของทวดของเราปิดมันไป เราไม่เคยรู้ว่าทำไม", "Basamaklı Kuyu'nun bir zamanlar Büyük Havuz'u yıkayan bir savağı vardı. Büyük büyükannemin mühendisleri onu kapattı. Nedenini hiç bilmedim.", "El Pozo Escalonado tuvo una vez una compuerta que vaciaba el Gran Estanque. Los ingenieros de mi bisabuela la cerraron. Nunca supe por qué.", "O Poço de Degraus já teve uma comporta que lavava o Grande Tanque. Os engenheiros da minha bisavó a fecharam. Nunca soube por quê.", "Когда-то в ступенчатом колодце был шлюз, промывавший Великий пруд. Инженеры моей прабабки его закрыли. Я так и не узнала почему.", "Колись у східчастому колодязі був шлюз, що промивав Великий став. Інженери моєї прабабці його закрили. Я так і не дізналася чому."],
  "The Great Tank is moving. I watched from the balcony: the silt going down through the Stepwell like smoke. Tell me what you found.": ["大貯水池が動いている。露台から見ておった。泥が煙のように階段井戸へ下っていくのを。何を見つけたのか話してくれ。", "대저수지가 움직이고 있다. 발코니에서 지켜보았지. 토사가 연기처럼 계단우물로 빠져나가더구나. 무엇을 찾았는지 말해 보아라.", "大水池动起来了。我在阳台上看着：淤泥像烟一样顺着阶梯井流下去。告诉我你发现了什么。", "大水池動起來了。我在陽台上看著：淤泥像煙一樣順著階梯井流下去。告訴我你發現了什麼。", "Hồ Lớn đang chuyển động. Ta đã nhìn từ ban công: bùn trôi xuống qua Giếng Bậc như làn khói. Kể ta nghe ngươi đã tìm thấy gì.", "Telaga Agung bergerak. Aku menyaksikannya dari balkon: lumpurnya turun melalui Sumur Tangga seperti asap. Ceritakan apa yang kau temukan.", "สระใหญ่กำลังเคลื่อนไหว เรามองจากระเบียง ตะกอนไหลลงไปทางบ่อขั้นบันไดราวกับควัน บอกเรามาว่าเจ้าพบอะไร", "Büyük Havuz hareket ediyor. Balkondan izledim: silt duman gibi Basamaklı Kuyu'dan aşağı iniyordu. Ne bulduğunu anlat bana.", "El Gran Estanque se mueve. Lo vi desde el balcón: el cieno bajando por el Pozo Escalonado como humo. Dime qué encontraste.", "O Grande Tanque está se mexendo. Vi da sacada: o lodo descendo pelo Poço de Degraus feito fumaça. Conte-me o que você descobriu.", "Великий пруд пришёл в движение. Я смотрела с балкона: ил уходил вниз через ступенчатый колодец, как дым. Расскажи, что тебе удалось найти.", "Великий став зрушив. Я дивилася з балкона: мул ішов униз крізь східчастий колодязь, мов дим. Розкажи, що тобі вдалося знайти."],
  "Both of them are right. The silt comes from the cut forests upstream.": ["二人とも正しいのです。泥は上流の伐られた森から来ています。", "두 사람 다 옳습니다. 토사는 상류의 베어 낸 숲에서 내려옵니다.", "他们两个都对。淤泥来自上游被砍伐的森林。", "他們兩個都對。淤泥來自上游被砍伐的森林。", "Cả hai đều đúng. Bùn đến từ những khu rừng bị chặt phá ở thượng nguồn.", "Keduanya benar. Lumpurnya berasal dari hutan-hutan yang ditebang di hulu.", "ถูกทั้งคู่ ตะกอนมาจากป่าที่ถูกตัดทางต้นน้ำ", "İkisi de haklı. Silt, yukarı akıştaki kesilmiş ormanlardan geliyor.", "Los dos tienen razón. El cieno viene de los bosques talados río arriba.", "Os dois têm razão. O lodo vem das florestas derrubadas rio acima.", "Правы оба. Ил идёт из вырубленных лесов выше по течению.", "Мають рацію обоє. Мул іде з вирубаних лісів вище за течією."],
  "The forests. Shailagarh's loggers, and the Kanthari's grove. So the temple pays to replant upstream, because the offerings are the river's and that's where the river begins, and the crown pays to dig, because the tanks are the crown's.": ["森か。シャイラガルの木こりどもと、カンタリの林。ならば寺院は上流の植林に金を出す。供物は川のものであり、川はそこから始まるのだから。そして王家は浚渫に金を出す。貯水池は王家のものだからな。", "숲이라. 샤일라가르의 벌목꾼들과 칸타리족의 숲이로군. 그렇다면 사원은 상류에 나무를 다시 심는 데 돈을 낸다. 공물은 강의 것이고 강은 거기서 시작되니까. 그리고 왕실은 준설에 돈을 낸다. 저수지는 왕실의 것이니까.", "森林。沙伊拉加尔的伐木工，还有坎塔里人的林子。那么，神庙出钱在上游重新植树，因为供奉属于河流，而河流就是从那里开始的；王室出钱清淤，因为水池属于王室。", "森林。沙伊拉加爾的伐木工，還有坎塔里人的林子。那麼，神廟出錢在上游重新植樹，因為供奉屬於河流，而河流就是從那裡開始的；王室出錢清淤，因為水池屬於王室。", "Những khu rừng. Bọn tiều phu của Shailagarh, và khu rừng thiêng của người Kanthari. Vậy thì đền sẽ trả tiền trồng lại rừng ở thượng nguồn, vì lễ vật là của dòng sông và dòng sông bắt đầu từ đó, còn vương triều trả tiền nạo vét, vì các hồ chứa là của vương triều.", "Hutan-hutan itu. Para penebang Shailagarh, dan rimba orang Kanthari. Jadi kuil membayar penanaman kembali di hulu, karena persembahan adalah milik sungai dan di sanalah sungai bermula, dan mahkota membayar pengerukan, karena telaga-telaga adalah milik mahkota.", "ป่า พวกคนตัดไม้ของไศลครห์ กับป่าของชาวกันถารี ถ้าอย่างนั้นวัดจะออกเงินปลูกป่าคืนทางต้นน้ำ เพราะเครื่องบูชาเป็นของแม่น้ำ และแม่น้ำก็เริ่มต้นที่นั่น ส่วนราชสำนักจะออกเงินขุดลอก เพราะสระเป็นของราชสำนัก", "Ormanlar. Shailagarh'ın oduncuları ve Kanthariler'in korusu. O hâlde tapınak yukarı akışta yeniden ağaç dikmenin parasını ödesin, çünkü adaklar nehrindir ve nehir orada başlar; taç da kazının parasını ödesin, çünkü havuzlar tacındır.", "Los bosques. Los leñadores de Shailagarh, y la arboleda de los kanthari. Así que el templo paga la reforestación río arriba, porque las ofrendas son del río y allí es donde el río empieza, y la corona paga el dragado, porque los estanques son de la corona.", "As florestas. Os lenhadores de Shailagarh, e o bosque dos kanthari. Então o templo paga o replantio rio acima, porque as oferendas são do rio e é lá que o rio começa, e a coroa paga a dragagem, porque os tanques são da coroa.", "Леса. Лесорубы Шайлагарха и роща кантхари. Значит, храм платит за новые посадки выше по течению, ведь подношения принадлежат реке, а река начинается там; а корона платит за расчистку, ведь пруды принадлежат короне.", "Ліси. Лісоруби Шайлагарха і гай кантхарі. Отже, храм платить за нові насадження вище за течією, бо пожертви належать річці, а річка починається там; а корона платить за розчищення, бо стави належать короні."],
  "They'll both hate it. That's how I'll know it's fair. Wear this: the ring of a kept tank. My mother gave one to the engineer who dug the last canal.": ["二人とも嫌がるだろう。だからこそ公平だとわかる。これを着けるがいい。守られし貯水池の指輪だ。わたしの母は、最後の運河を掘った技師にこれを与えた。", "둘 다 싫어하겠지. 그래야 공정하다는 걸 알 수 있다. 이것을 끼어라. 잘 관리된 저수지의 반지다. 내 어머니께서는 마지막 운하를 판 기술자에게 이것을 하사하셨지.", "他们俩都会讨厌这个办法。这样我才知道它是公平的。戴上这个吧：守池之戒。我母亲曾把一枚赐给挖出最后一条运河的工程师。", "他們倆都會討厭這個辦法。這樣我才知道它是公平的。戴上這個吧：守池之戒。我母親曾把一枚賜給挖出最後一條運河的工程師。", "Cả hai sẽ ghét điều đó. Nhờ vậy ta mới biết nó công bằng. Hãy đeo cái này: chiếc nhẫn của hồ chứa được chăm giữ. Mẹ ta từng ban một chiếc cho người kỹ sư đã đào con kênh cuối cùng.", "Mereka berdua akan membencinya. Dari situlah aku tahu ini adil. Pakailah ini: cincin telaga yang terjaga. Ibuku memberikan satu kepada insinyur yang menggali kanal terakhir.", "ทั้งคู่จะเกลียดมัน นั่นแหละที่ทำให้เรารู้ว่ามันยุติธรรม สวมสิ่งนี้ไว้ แหวนแห่งสระที่ได้รับการดูแล มารดาของเราเคยมอบวงหนึ่งให้วิศวกรผู้ขุดคลองสายสุดท้าย", "İkisi de bundan nefret edecek. Adil olduğunu böyle anlayacağım. Bunu tak: bakımlı havuzun yüzüğü. Annem bir tanesini son kanalı kazan mühendise vermişti.", "Los dos lo odiarán. Así sabré que es justo. Ponte esto: el anillo del estanque cuidado. Mi madre le dio uno al ingeniero que cavó el último canal.", "Os dois vão odiar. É assim que vou saber que é justo. Use isto: o anel do tanque bem cuidado. Minha mãe deu um ao engenheiro que cavou o último canal.", "Обоим это не понравится. Так я и пойму, что это справедливо. Надень вот это: кольцо ухоженного пруда. Моя мать подарила такое инженеру, что прорыл последний канал.", "Обом це не сподобається. Так я й зрозумію, що це справедливо. Одягни ось це: перстень доглянутого ставу. Моя мати подарувала такий інженерові, що прокопав останній канал."],
  "Look at the measure on the Great Tank, then tell me I'm wrong. A third full of silt! Dig it out, and the temple's vaults are full of gold the river gave and the river needs.": ["大貯水池の水位標を見てから、わたしが間違っていると言ってみるがいい。三分の一が泥だぞ！掘り出すんだ。寺院の蔵には、川が与え、川が必要としている黄金が詰まっているのだから。", "대저수지의 수위표를 보고 나서 내가 틀렸다고 말해 보시오. 3분의 1이 토사란 말이오! 퍼내야 하오. 사원의 금고엔 강이 준 금, 강이 필요로 하는 금이 가득하지 않소.", "去看看大水池的水位标，再来告诉我我错了。三分之一都是淤泥！把它挖出来。神庙的库房里堆满了金子，那是河流给的，也是河流需要的。", "去看看大水池的水位標，再來告訴我我錯了。三分之一都是淤泥！把它挖出來。神廟的庫房裡堆滿了金子，那是河流給的，也是河流需要的。", "Hãy nhìn thước đo trên Hồ Lớn, rồi nói tôi sai đi. Một phần ba đầy bùn! Nạo nó lên, trong khi kho của đền đầy vàng mà dòng sông đã ban và dòng sông đang cần.", "Lihat takaran di Telaga Agung, lalu katakan aku salah. Sepertiganya penuh lumpur! Keruk keluar, sementara lemari besi kuil penuh emas yang diberikan sungai dan dibutuhkan sungai.", "ไปดูเครื่องวัดระดับน้ำที่สระใหญ่ แล้วค่อยมาบอกว่าข้าผิด ตะกอนเต็มไปหนึ่งในสาม! ขุดมันออกเสีย ในเมื่อห้องคลังของวัดเต็มไปด้วยทองที่แม่น้ำให้มาและแม่น้ำต้องการ", "Büyük Havuz'daki ölçeğe bak, sonra bana yanıldığımı söyle. Üçte biri silt dolu! Kazıp çıkarın; tapınağın mahzenleri nehrin verdiği ve nehrin ihtiyaç duyduğu altınla dolu.", "Mira la medida del Gran Estanque y luego dime que me equivoco. ¡Lleno de cieno hasta un tercio! Que lo draguen, que las cámaras del templo rebosan del oro que el río dio y que el río necesita.", "Olhe a medida no Grande Tanque e depois me diga que estou errado. Um terço cheio de lodo! Que se drague, e os cofres do templo estão cheios do ouro que o rio deu e de que o rio precisa.", "Посмотри на мерный знак Великого пруда, а потом скажи, что я неправ. На треть заполнен илом! Выкопать его — а в храмовых хранилищах полно золота, которое дала река и которое реке нужно.", "Поглянь на мірну позначку Великого ставу, а тоді скажи, що я помиляюся. На третину заповнений мулом! Викопати його — а в храмових сховищах повно золота, яке дала річка і якого річка потребує."],
  "And the Stepwell. My predecessor's predecessor chained it shut: its sluice jammed, and something took to living in the cistern below. Nobody's been down in forty years.": ["それに階段井戸だ。わたしの前任者のそのまた前任者が鎖で閉ざした。水門が詰まり、下の貯水槽に何かが棲みついたのでな。四十年、誰も下りていない。", "그리고 계단우물 말이오. 내 전임자의 전임자가 쇠사슬로 잠가 버렸지. 수문이 막히고, 아래 저수조에 뭔가가 살기 시작했거든. 사십 년 동안 아무도 내려가지 않았소.", "还有阶梯井。我前任的前任用铁链把它锁死了：水闸卡住了，下面的蓄水池里也住进了什么东西。四十年来没人下去过。", "還有階梯井。我前任的前任用鐵鍊把它鎖死了：水閘卡住了，下面的蓄水池裡也住進了什麼東西。四十年來沒人下去過。", "Còn Giếng Bậc nữa. Người tiền nhiệm của người tiền nhiệm của tôi đã xích nó lại: cửa cống bị kẹt, và có thứ gì đó đã đến sống trong bể chứa bên dưới. Bốn mươi năm nay chưa ai xuống đó.", "Lalu Sumur Tangga. Pendahulu dari pendahuluku merantainya hingga tertutup: pintu airnya macet, dan sesuatu mulai tinggal di bak penampungan di bawahnya. Tak ada yang turun ke sana selama empat puluh tahun.", "แล้วก็บ่อขั้นบันได ผู้ดำรงตำแหน่งก่อนผู้ดำรงตำแหน่งก่อนข้าล่ามโซ่ปิดมันไว้ ประตูระบายน้ำติดขัด แล้วก็มีอะไรบางอย่างเข้าไปอาศัยอยู่ในอ่างเก็บน้ำข้างล่าง สี่สิบปีแล้วที่ไม่มีใครลงไป", "Bir de Basamaklı Kuyu var. Selefimin selefi onu zincirle kapattı: savağı sıkıştı ve aşağıdaki sarnıca bir şey yerleşti. Kırk yıldır kimse aşağı inmedi.", "Y el Pozo Escalonado. El predecesor de mi predecesor lo cerró con cadenas: su compuerta se atascó, y algo se instaló a vivir en la cisterna de abajo. Nadie ha bajado en cuarenta años.", "E o Poço de Degraus. O antecessor do meu antecessor o fechou com correntes: a comporta emperrou, e alguma coisa passou a morar na cisterna lá embaixo. Ninguém desce lá há quarenta anos.", "А ещё ступенчатый колодец. Предшественник моего предшественника запер его на цепь: шлюз заклинило, а в цистерне внизу кто-то поселился. Сорок лет туда никто не спускался.", "А ще східчастий колодязь. Попередник мого попередника замкнув його на ланцюг: шлюз заклинило, а в цистерні внизу хтось оселився. Сорок років туди ніхто не спускався."],
  "The sluice under the Stepwell. Yes. If it turned, the Great Tank would flush its own silt, the old way, through the Stepwell and out to the river.": ["階段井戸の下の水門か。そうだ。あれが回れば、大貯水池は昔ながらのやり方で自分の泥を洗い流す。階段井戸を通って、川へとな。", "계단우물 아래의 수문이라. 그렇소. 그게 돌아가기만 하면 대저수지가 옛날 방식대로 제 토사를 씻어 낼 거요. 계단우물을 지나 강으로.", "阶梯井下面的水闸。对。只要它能转动，大水池就会照老办法自己冲走淤泥，经过阶梯井，一路排进河里。", "階梯井下面的水閘。對。只要它能轉動，大水池就會照老辦法自己沖走淤泥，經過階梯井，一路排進河裡。", "Cửa cống dưới Giếng Bậc. Phải rồi. Nếu nó quay được, Hồ Lớn sẽ tự xả bùn của mình theo cách xưa, qua Giếng Bậc và đổ ra sông.", "Pintu air di bawah Sumur Tangga. Ya. Kalau itu bisa diputar, Telaga Agung akan menggelontor lumpurnya sendiri, dengan cara lama, lewat Sumur Tangga dan keluar ke sungai.", "ประตูระบายน้ำใต้บ่อขั้นบันได ใช่แล้ว ถ้ามันหมุนได้ สระใหญ่จะชะตะกอนของตัวเองออกไปแบบเก่า ผ่านบ่อขั้นบันไดออกไปสู่แม่น้ำ", "Basamaklı Kuyu'nun altındaki savak. Evet. O dönseydi, Büyük Havuz kendi siltini eski usulle, Basamaklı Kuyu'dan geçirip nehre atardı.", "La compuerta bajo el Pozo Escalonado. Sí. Si girara, el Gran Estanque se vaciaría de su propio cieno, a la antigua, por el Pozo Escalonado y hasta el río.", "A comporta sob o Poço de Degraus. Sim. Se ela girasse, o Grande Tanque lavaria o próprio lodo, do jeito antigo, pelo Poço de Degraus e para fora, até o rio.", "Шлюз под ступенчатым колодцем. Да. Если его повернуть, Великий пруд сам промоет свой ил, по-старому: через ступенчатый колодец и дальше в реку.", "Шлюз під східчастим колодязем. Так. Якщо його повернути, Великий став сам промиє свій мул, по-старому: крізь східчастий колодязь і далі в річку."],
  "I'll unhook the chain. Mind the cistern. The last man who went down came back up and became a priest.": ["鎖を外しておこう。貯水槽には気をつけろ。最後に下りた男は、戻ってきてから僧になった。", "쇠사슬을 풀어 두겠소. 저수조를 조심하시오. 마지막으로 내려갔던 사람은 올라오더니 사제가 됐소.", "我去把链子解开。小心蓄水池。上一个下去的人上来以后就当了祭司。", "我去把鍊子解開。小心蓄水池。上一個下去的人上來以後就當了祭司。", "Tôi sẽ tháo xích. Coi chừng bể chứa. Người cuối cùng xuống đó đã leo lên rồi đi làm thầy tu.", "Akan kulepas rantainya. Hati-hati dengan bak penampungannya. Orang terakhir yang turun ke sana naik lagi lalu menjadi pendeta.", "ข้าจะปลดโซ่ให้ ระวังอ่างเก็บน้ำด้วย ชายคนสุดท้ายที่ลงไปขึ้นมาแล้วก็ไปบวชเป็นนักบวช", "Zinciri çözerim. Sarnıca dikkat et. Aşağı inen son adam yukarı çıktı ve rahip oldu.", "Quitaré la cadena. Cuidado con la cisterna. El último hombre que bajó volvió a subir y se hizo sacerdote.", "Vou soltar a corrente. Cuidado com a cisterna. O último homem que desceu voltou lá de baixo e virou sacerdote.", "Я сниму цепь. Берегись цистерны. Последний, кто туда спускался, вернулся наверх и подался в жрецы.", "Я зніму ланцюг. Стережися цистерни. Останній, хто туди спускався, повернувся нагору й подався в жерці."],
  "Devakar has unchained the Great Stepwell. Go down it, find the sluice wheel, and whatever's in the cistern.": ["デヴァカルが大階段井戸の鎖を外した。下りて、水門の車輪と、貯水槽にいる何かを見つけよう。", "데바카르가 대계단우물의 쇠사슬을 풀었다. 내려가서 수문 바퀴와, 저수조에 있는 무언가를 찾아라.", "德瓦卡尔解开了大阶梯井的锁链。下去找到水闸转轮，还有蓄水池里的那个东西。", "德瓦卡爾解開了大階梯井的鎖鍊。下去找到水閘轉輪，還有蓄水池裡的那個東西。", "Devakar đã tháo xích Giếng Bậc Lớn. Hãy đi xuống, tìm bánh xe cửa cống, và thứ gì đó trong bể chứa.", "Devakar telah melepas rantai Sumur Tangga Agung. Turunlah, temukan roda pintu air, dan apa pun yang ada di bak penampungan.", "เทวกรปลดโซ่บ่อขั้นบันไดใหญ่แล้ว ลงไปหาวงล้อประตูระบายน้ำ และสิ่งที่อยู่ในอ่างเก็บน้ำ", "Devakar, Büyük Basamaklı Kuyu'nun zincirini çözdü. Aşağı in, savak çarkını ve sarnıçta her ne varsa onu bul.", "Devakar ha quitado las cadenas del Gran Pozo Escalonado. Baja, encuentra la rueda de la compuerta y lo que sea que haya en la cisterna.", "Devakar soltou as correntes do Grande Poço de Degraus. Desça, encontre a roda da comporta e o que quer que esteja na cisterna.", "Девакар снял цепь с Великого ступенчатого колодца. Спустись туда, найди колесо шлюза и то, что живёт в цистерне.", "Девакар зняв ланцюг із Великого східчастого колодязя. Спустися туди, знайди колесо шлюзу і те, що живе в цистерні."],
  "Dig, dig, dig. Devakar would dig the same silt out every ten years until the vaults are empty and the tanks are full of it again.": ["掘れ、掘れ、掘れ。デヴァカルは十年ごとに同じ泥を掘り出すつもりよ。蔵が空になって、貯水池がまた泥で一杯になるまでね。", "파라, 파라, 파라. 데바카르는 금고가 텅 비고 저수지가 다시 토사로 가득 찰 때까지 십 년마다 똑같은 토사를 퍼낼 사람이에요.", "挖，挖，挖。德瓦卡尔会每十年把同样的淤泥挖一遍，直到库房空了，水池又被淤泥填满。", "挖，挖，挖。德瓦卡爾會每十年把同樣的淤泥挖一遍，直到庫房空了，水池又被淤泥填滿。", "Đào, đào, đào. Devakar sẽ cứ mười năm lại đào cùng một đống bùn ấy, cho đến khi kho trống rỗng và các hồ chứa lại đầy bùn.", "Keruk, keruk, keruk. Devakar akan mengeruk lumpur yang sama setiap sepuluh tahun sampai lemari besinya kosong dan telaga-telaganya penuh lumpur lagi.", "ขุด ขุด ขุด เทวกรจะขุดตะกอนเดิมออกทุกสิบปี จนกว่าห้องคลังจะว่างเปล่า และสระก็เต็มไปด้วยตะกอนอีกครั้ง", "Kaz, kaz, kaz. Devakar aynı silti her on yılda bir kazıp çıkarır, ta ki mahzenler boşalıp havuzlar yine siltle dolana dek.", "Dragar, dragar, dragar. Devakar sacaría el mismo cieno cada diez años hasta que las cámaras estén vacías y los estanques vuelvan a estar llenos de él.", "Dragar, dragar, dragar. Devakar tiraria o mesmo lodo a cada dez anos até os cofres esvaziarem e os tanques se encherem dele de novo.", "Копать, копать, копать. Девакар выкапывал бы один и тот же ил каждые десять лет, пока хранилища не опустеют, а пруды снова им не заполнятся.", "Копати, копати, копати. Девакар викопував би той самий мул кожні десять років, доки сховища не спорожніють, а стави знову ним не заповняться."],
  "Ask where it comes from. Up the Ilavati, past Shailagarh, the loggers are cutting the forests that held the river's banks. The silt is the forest, coming down to see us.": ["それがどこから来るのか聞いてごらんなさい。イラヴァティを遡り、シャイラガルの先で、木こりたちが川岸を支えていた森を伐っているの。泥は森なのよ。わたしたちに会いに下ってきた森。", "그게 어디서 오는지 물어보세요. 일라바티를 거슬러 샤일라가르 너머에서 벌목꾼들이 강둑을 붙잡아 주던 숲을 베고 있어요. 토사는 숲이에요. 우리를 보러 내려온 숲.", "问问它是从哪儿来的。沿伊拉瓦蒂河往上，过了沙伊拉加尔，伐木工正在砍伐那些护住河岸的森林。淤泥就是森林，顺流而下来看我们了。", "問問它是從哪兒來的。沿伊拉瓦蒂河往上，過了沙伊拉加爾，伐木工正在砍伐那些護住河岸的森林。淤泥就是森林，順流而下來看我們了。", "Hãy hỏi xem nó từ đâu tới. Ngược dòng Ilavati, qua khỏi Shailagarh, bọn tiều phu đang chặt những khu rừng từng giữ bờ sông. Bùn chính là rừng, trôi xuống thăm chúng ta đấy.", "Tanyakan dari mana asalnya. Ke hulu Ilavati, melewati Shailagarh, para penebang sedang menebang hutan yang menahan tepian sungai. Lumpur itu adalah hutan, yang turun untuk menjenguk kita.", "ลองถามดูว่ามันมาจากไหน ทวนแม่น้ำอิลาวดีขึ้นไป เลยไศลครห์ไป พวกคนตัดไม้กำลังโค่นป่าที่เคยยึดตลิ่งแม่น้ำไว้ ตะกอนก็คือป่า ที่ไหลลงมาเยี่ยมพวกเรา", "Nereden geldiğini sor. Ilavati'nin yukarısında, Shailagarh'ın ötesinde oduncular nehrin kıyılarını tutan ormanları kesiyor. Silt ormanın ta kendisi, bizi görmeye iniyor.", "Pregunta de dónde viene. Ilavati arriba, pasado Shailagarh, los leñadores están talando los bosques que sujetaban las orillas del río. El cieno es el bosque, que baja a visitarnos.", "Pergunte de onde ele vem. Subindo o Ilavati, depois de Shailagarh, os lenhadores estão derrubando as florestas que seguravam as margens do rio. O lodo é a floresta, descendo para nos visitar.", "Спроси, откуда он берётся. Вверх по Илавати, за Шайлагархом, лесорубы вырубают леса, что держали берега реки. Ил — это лес, который спускается к нам в гости.", "Спитай, звідки він береться. Угору по Ілаваті, за Шайлагархом, лісоруби вирубують ліси, що тримали береги річки. Мул — це ліс, який спускається до нас у гості."],
  "The toll books say the Queen's bridge has doubled its toll on League carts. Six of the seven want to say so in the Mandapa tomorrow. Once it's said in the Mandapa, it can't be unsaid.": ["通行税の帳簿によれば、女王の橋が同盟の荷車への通行税を倍にしたそうです。七人のうち六人が、明日マンダパでそう言いたがっています。マンダパで一度口にしたことは、取り消せません。", "통행세 장부에 따르면 여왕의 다리가 동맹 수레에 대한 통행세를 두 배로 올렸다고 해요. 일곱 중 여섯이 내일 만다파에서 그 말을 하고 싶어 하죠. 만다파에서 한번 한 말은 되돌릴 수 없어요.", "通行费账簿上说，女王的桥对同盟的车子收的过桥费翻了一倍。七位中有六位想明天在曼达帕把这话说出来。话一旦在曼达帕说出口，就收不回来了。", "通行費帳簿上說，女王的橋對同盟的車子收的過橋費翻了一倍。七位中有六位想明天在曼達帕把這話說出來。話一旦在曼達帕說出口，就收不回來了。", "Sổ thu phí ghi rằng cây cầu của Nữ hoàng đã tăng gấp đôi phí với xe của Liên minh. Sáu trong bảy vị muốn nói ra điều đó ở Mandapa ngày mai. Một khi đã nói ra ở Mandapa thì không thể rút lại.", "Buku-buku tol menyebut jembatan Ratu telah menggandakan tolnya untuk gerobak Liga. Enam dari tujuh ingin mengatakannya di Mandapa besok. Sekali diucapkan di Mandapa, tak bisa ditarik kembali.", "สมุดบัญชีค่าผ่านทางบอกว่าสะพานของราชินีขึ้นค่าผ่านทางสำหรับเกวียนของสันนิบาตเป็นสองเท่า หกในเจ็ดคนอยากประกาศเรื่องนี้ในมณฑปพรุ่งนี้ เมื่อพูดออกไปในมณฑปแล้ว ก็ไม่อาจถอนคืนได้", "Geçiş defterlerine göre Kraliçe'nin köprüsü Birlik arabalarından aldığı geçiş ücretini ikiye katlamış. Yedi kişiden altısı bunu yarın Mandapa'da söylemek istiyor. Mandapa'da bir kez söylenen, geri alınamaz.", "Los libros de peajes dicen que el puente de la reina ha duplicado el peaje a los carros de la Liga. Seis de los siete quieren decirlo mañana en el Mandapa. Y lo que se dice en el Mandapa no puede desdecirse.", "Os livros de pedágio dizem que a ponte da rainha dobrou o pedágio das carroças da Liga. Seis dos sete querem dizer isso no Mandapa amanhã. E o que é dito no Mandapa não pode ser desdito.", "По пошлинным книгам выходит, что мост королевы удвоил пошлину для повозок Лиги. Шестеро из семи хотят заявить об этом завтра в Мандапе. Что сказано в Мандапе, того уже не воротишь.", "За митними книгами виходить, що міст королеви подвоїв мито для возів Ліги. Шестеро із сімох хочуть заявити про це завтра в Мандапі. Що сказано в Мандапі, того вже не повернеш."],
  "I'd like to know if it's true before we say it. A stranger can ask questions a Speaker can't.": ["言う前に、それが本当か知りたいのです。よそ者なら、議長には訊けないことも訊けますから。", "말하기 전에 그게 사실인지 알고 싶어요. 이방인은 의장이 못 하는 질문도 할 수 있으니까요.", "在我们说出口之前，我想知道这是不是真的。外人能问议长问不了的问题。", "在我們說出口之前，我想知道這是不是真的。外人能問議長問不了的問題。", "Tôi muốn biết điều đó có thật không trước khi chúng tôi nói ra. Một người lạ có thể hỏi những câu mà Phát ngôn nhân không thể hỏi.", "Aku ingin tahu apakah itu benar sebelum kami mengatakannya. Orang asing bisa mengajukan pertanyaan yang tak bisa diajukan Juru Bicara.", "ข้าอยากรู้ว่ามันจริงหรือไม่ก่อนที่เราจะพูดออกไป คนแปลกหน้าถามคำถามที่ประธานถามไม่ได้", "Söylemeden önce doğru olup olmadığını bilmek isterim. Bir yabancı, bir Sözcü'nün soramayacağı soruları sorabilir.", "Me gustaría saber si es verdad antes de decirlo. Un forastero puede hacer preguntas que una Portavoz no puede.", "Eu gostaria de saber se é verdade antes de dizermos. Um forasteiro pode fazer perguntas que uma Porta-voz não pode.", "Я хотела бы знать, правда ли это, прежде чем мы это скажем. Чужак может задать вопросы, которых не может задать Глашатай.", "Я хотіла б знати, чи це правда, перш ніж ми це скажемо. Чужинець може поставити питання, яких не може поставити Речниця."],
  "Start with Indrasen of the Salt Fens: he's the seventh, and he doesn't believe it. Then the toll office, and its clerk.": ["まずは塩沼のインドラセンから。彼が七人目で、この話を信じていません。それから通行税所と、そこの書記を。", "소금 늪의 인드라센부터 시작하세요. 그가 일곱 번째인데, 그 말을 믿지 않아요. 그다음엔 통행세 사무소와 거기 서기를요.", "先找盐沼的因德拉森：他就是第七位，而且他不信这回事。然后是收费处，还有那里的书记。", "先找鹽沼的因德拉森：他就是第七位，而且他不信這回事。然後是收費處，還有那裡的書記。", "Hãy bắt đầu với Indrasen của Đầm Muối: ông ấy là vị thứ bảy, và ông ấy không tin chuyện đó. Rồi đến trạm thu phí, và viên thư lại ở đó.", "Mulailah dengan Indrasen dari Rawa Garam: dialah yang ketujuh, dan dia tidak memercayainya. Lalu kantor bea, dan juru tulisnya.", "เริ่มจากอินทรเสนแห่งบึงเกลือ เขาคือคนที่เจ็ด และเขาไม่เชื่อเรื่องนี้ จากนั้นก็สำนักงานเก็บค่าผ่านทาง กับเสมียนของที่นั่น", "Tuz Bataklıkları'ndan Indrasen ile başla: yedinci odur ve buna inanmıyor. Sonra geçiş ücreti bürosu ve kâtibi.", "Empieza por Indrasen de las Ciénagas de Sal: es el séptimo, y no se lo cree. Luego la oficina de peajes, y su escribano.", "Comece por Indrasen dos Pântanos de Sal: ele é o sétimo, e não acredita nisso. Depois o posto de pedágio, e o escrivão de lá.", "Начни с Индрасена из Соляных Топей: он седьмой, и он в это не верит. Потом пошлинная контора и её писарь.", "Почни з Індрасена із Соляних Боліт: він сьомий, і він у це не вірить. Потім митна контора та її писар."],
  "Tomorrow, in the Mandapa. Unless you find me something first.": ["明日、マンダパで。それまでにあなたが何か見つけてくれなければ、ですが。", "내일, 만다파에서요. 그 전에 당신이 뭔가 찾아 주지 않는다면요.", "明天，在曼达帕。除非你先给我找到点什么。", "明天，在曼達帕。除非你先給我找到點什麼。", "Ngày mai, ở Mandapa. Trừ khi bạn tìm được gì đó cho tôi trước.", "Besok, di Mandapa. Kecuali kau menemukan sesuatu untukku lebih dulu.", "พรุ่งนี้ ที่มณฑป เว้นแต่เจ้าจะหาอะไรมาให้ข้าได้ก่อน", "Yarın, Mandapa'da. Tabii önce bana bir şey bulmazsan.", "Mañana, en el Mandapa. A menos que me encuentres algo antes.", "Amanhã, no Mandapa. A não ser que você me encontre alguma coisa antes.", "Завтра, в Мандапе. Если только ты не найдёшь для меня что-нибудь раньше.", "Завтра, в Мандапі. Хіба що ти знайдеш для мене щось раніше."],
  "Seven parasols, one shade. That's the saying. It's never once been true on a hot day.": ["七つの日傘、ひとつの日陰。そういう言い習わしです。暑い日に本当だったためしは一度もありませんが。", "일곱 일산, 하나의 그늘. 그런 속담이 있죠. 더운 날 그게 맞았던 적은 한 번도 없지만요.", "七华盖，一片荫。俗话是这么说的。可到了大热天，这话从来没应验过一次。", "七華蓋，一片蔭。俗話是這麼說的。可到了大熱天，這話從來沒應驗過一次。", "Bảy lọng, một bóng râm. Người ta nói thế. Chưa ngày nóng nào câu đó đúng cả.", "Tujuh payung, satu teduh. Begitu kata pepatahnya. Tak pernah sekali pun benar di hari yang panas.", "เจ็ดฉัตร ร่มเงาเดียว เขาว่ากันอย่างนั้น แต่ไม่เคยจริงสักครั้งในวันที่อากาศร้อน", "Yedi şemsiye, tek gölge. Öyle derler. Sıcak bir günde bir kez bile doğru çıkmamıştır.", "Siete parasoles, una sombra. Eso dice el refrán. No ha sido cierto ni una sola vez en un día caluroso.", "Sete para-sóis, uma sombra. É o que diz o ditado. Nunca foi verdade nem uma vez num dia quente.", "Семь зонтов, одна тень. Так говорят. Ни разу ещё это не было правдой в жаркий день.", "Сім парасолів, одна тінь. Так кажуть. Жодного разу це не було правдою в спекотний день."],
  "The Gilded Court paid our clerk to double Ilavarta's toll in our books? So that we'd quarrel with the Queen, and rice would stay dear, and Sefrah would buy it?": ["金色の宮廷が書記に金を払って、帳簿のイラヴァルタの通行税を倍にさせたと？わたしたちが女王と争い、米が高いままで、セフラがそれを買うように？", "황금 궁정이 우리 서기에게 돈을 주고 장부에 적힌 일라바르타의 통행세를 두 배로 만들었다고요? 우리가 여왕과 다투고, 쌀값이 비싼 채로 남고, 세프라가 그 쌀을 사들이게 하려고요?", "镀金宫廷收买了我们的书记，让他在我们的账簿上把伊拉瓦塔的过桥费翻倍？好让我们和女王吵起来，让米价居高不下，再让塞弗拉来买？", "鍍金宮廷收買了我們的書記，讓他在我們的帳簿上把伊拉瓦塔的過橋費翻倍？好讓我們和女王吵起來，讓米價居高不下，再讓塞弗拉來買？", "Triều Mạ Vàng đã trả tiền cho thư lại của chúng tôi để nhân đôi phí của Ilavarta trong sổ sách? Để chúng tôi cãi nhau với Nữ hoàng, để gạo cứ đắt, và để Sefrah mua nó?", "Istana Bersepuh membayar juru tulis kami untuk menggandakan tol Ilavarta di buku kami? Supaya kami bertengkar dengan Ratu, beras tetap mahal, dan Sefrah yang membelinya?", "ราชสำนักปิดทองจ้างเสมียนของเราให้เพิ่มค่าผ่านทางของอิลาวรรตะในบัญชีของเราเป็นสองเท่างั้นหรือ เพื่อให้เราทะเลาะกับราชินี ข้าวจะได้แพงต่อไป และเซฟราห์จะได้ซื้อมันงั้นหรือ", "Yaldızlı Saray, defterlerimizde Ilavarta'nın geçiş ücretini ikiye katlasın diye kâtibimize para mı verdi? Kraliçe'yle kavga edelim, pirinç pahalı kalsın ve Sefrah onu alsın diye mi?", "¿La Corte Dorada pagó a nuestro escribano para duplicar el peaje de Ilavarta en nuestros libros? ¿Para que riñéramos con la reina, el arroz siguiera caro y Sefrah lo comprara?", "A Corte Dourada pagou nosso escrivão para dobrar o pedágio de Ilavarta nos nossos livros? Para que brigássemos com a rainha, o arroz continuasse caro e Sefrah o comprasse?", "Позолоченный двор заплатил нашему писарю, чтобы тот удвоил пошлину Илаварты в наших книгах? Чтобы мы рассорились с королевой, рис оставался дорогим, а Сефра его скупала?", "Позолочений двір заплатив нашому писареві, щоб той подвоїв мито Ілаварти в наших книгах? Щоб ми посварилися з королевою, рис лишався дорогим, а Сефра його скуповувала?"],
  "Then I'll read the true figures in the Mandapa tomorrow, and the Gilded Court's factor can explain himself to seven rulers at once. Take this: a Speaker's parasol. I'll have it back when it's your turn.": ["では明日、マンダパで本当の数字を読み上げましょう。金色の宮廷の代理商には、七人の支配者の前でいっぺんに申し開きをしてもらいます。これを。議長の日傘です。あなたの番が来たら返してもらいますね。", "그럼 내일 만다파에서 진짜 수치를 읽겠어요. 황금 궁정의 중개인은 일곱 통치자 앞에서 한꺼번에 해명하면 되겠죠. 이걸 받으세요. 의장의 일산이에요. 당신 차례가 오면 돌려받을게요.", "那么明天我就在曼达帕念出真实的数字，镀金宫廷的代理商可以一次向七位统治者解释清楚。拿着这个：议长华盖。等轮到你的时候，我再收回来。", "那麼明天我就在曼達帕念出真實的數字，鍍金宮廷的代理商可以一次向七位統治者解釋清楚。拿著這個：議長華蓋。等輪到你的時候，我再收回來。", "Vậy thì ngày mai tôi sẽ đọc những con số thật ở Mandapa, và đại lý của Triều Mạ Vàng có thể giải thích với bảy vị cai trị cùng một lúc. Cầm lấy cái này: lọng của Phát ngôn nhân. Đến lượt bạn thì tôi sẽ lấy lại.", "Kalau begitu besok akan kubacakan angka yang sebenarnya di Mandapa, dan agen Istana Bersepuh bisa menjelaskan dirinya kepada tujuh penguasa sekaligus. Ambillah ini: payung Juru Bicara. Akan kuminta kembali saat tiba giliranmu.", "ถ้าอย่างนั้นพรุ่งนี้ข้าจะอ่านตัวเลขที่แท้จริงในมณฑป และตัวแทนของราชสำนักปิดทองก็ชี้แจงต่อผู้ปกครองทั้งเจ็ดพร้อมกันได้เลย รับนี่ไป ฉัตรของประธาน เมื่อถึงตาของเจ้า ข้าจะขอคืน", "O hâlde yarın Mandapa'da gerçek rakamları okurum, Yaldızlı Saray'ın kâhyası da kendini yedi hükümdara birden açıklasın. Al bunu: bir Sözcü şemsiyesi. Sıra sana geldiğinde geri alırım.", "Entonces mañana leeré las cifras verdaderas en el Mandapa, y el factor de la Corte Dorada podrá explicarse ante siete gobernantes a la vez. Toma esto: un parasol de Portavoz. Me lo devolverás cuando te toque.", "Então amanhã vou ler os números verdadeiros no Mandapa, e o feitor da Corte Dourada pode se explicar para sete governantes de uma vez. Tome isto: um para-sol de Porta-voz. Quero de volta quando for a sua vez.", "Тогда завтра я зачитаю в Мандапе настоящие цифры, и фактор Позолоченного двора сможет оправдаться перед семью правителями разом. Возьми вот это: зонт Глашатая. Заберу его обратно, когда придёт твой черёд.", "Тоді завтра я зачитаю в Мандапі справжні цифри, і фактор Позолоченого двору зможе виправдатися перед сімома правителями одразу. Візьми ось це: парасоль Речника. Заберу його назад, коли настане твоя черга."],
  "Doubled? The Salt Fens send forty carts a month over that bridge and we've paid the same toll since my father's day. I've the receipts. The others haven't asked to see them.": ["倍だと？塩沼は毎月四十台の荷車をあの橋に通しているが、父の代から同じ通行税しか払っておらん。受取書もある。ほかの連中は見せてくれとも言わなかったがな。", "두 배라고? 소금 늪은 매달 수레 마흔 대를 그 다리로 보내는데, 내 아버지 때부터 똑같은 통행세를 내 왔소. 영수증도 있소. 다른 이들은 보여 달라고 하지도 않았지만.", "翻倍？盐沼每个月有四十辆车过那座桥，从我父亲那时候起付的过桥费就没变过。收据我都有。其他人连看都没要求看。", "翻倍？鹽沼每個月有四十輛車過那座橋，從我父親那時候起付的過橋費就沒變過。收據我都有。其他人連看都沒要求看。", "Gấp đôi ư? Đầm Muối gửi bốn mươi xe mỗi tháng qua cây cầu đó, và chúng ta trả cùng một mức phí từ thời cha ta. Ta có biên lai. Những người khác chẳng ai hỏi xem.", "Dua kali lipat? Rawa Garam mengirim empat puluh gerobak sebulan lewat jembatan itu dan kami membayar tol yang sama sejak zaman ayahku. Aku punya tanda terimanya. Yang lain tak pernah minta melihatnya.", "สองเท่างั้นรึ บึงเกลือส่งเกวียนสี่สิบเล่มข้ามสะพานนั้นทุกเดือน และเราจ่ายค่าผ่านทางเท่าเดิมมาตั้งแต่สมัยพ่อของข้า ข้ามีใบเสร็จ คนอื่นๆ ไม่เคยขอดูเลย", "İki katı mı? Tuz Bataklıkları o köprüden ayda kırk araba geçirir ve babamın zamanından beri aynı geçiş ücretini öderiz. Makbuzlarım var. Diğerleri görmek bile istemedi.", "¿Duplicado? Las Ciénagas de Sal mandan cuarenta carros al mes por ese puente y pagamos el mismo peaje desde los tiempos de mi padre. Tengo los recibos. Los demás no han pedido verlos.", "Dobrado? Os Pântanos de Sal mandam quarenta carroças por mês por aquela ponte e pagamos o mesmo pedágio desde o tempo do meu pai. Tenho os recibos. Os outros não pediram para vê-los.", "Вдвое? Соляные Топи отправляют по этому мосту сорок повозок в месяц, и мы платим ту же пошлину со времён моего отца. У меня есть расписки. Остальные посмотреть на них не просили.", "Удвічі? Соляні Болота відправляють тим мостом сорок возів на місяць, і ми платимо те саме мито ще з часів мого батька. У мене є розписки. Інші подивитися на них не просили."],
  "Somebody's figures are wrong, and it isn't the Queen's toll-keeper. He can't add well enough to cheat.": ["誰かの数字が間違っている。女王の通行税取りではない。あやつはごまかせるほど足し算ができんからな。", "누군가의 수치가 틀렸소. 여왕의 통행세 징수인은 아니오. 그자는 속일 만큼 덧셈을 잘하지 못하거든.", "有人的数字错了，但不是女王的收税人。他算术太差，连作弊都做不来。", "有人的數字錯了，但不是女王的收稅人。他算術太差，連作弊都做不來。", "Con số của ai đó sai rồi, và đó không phải người thu thuế của Nữ hoàng. Hắn cộng còn chẳng giỏi đến mức gian lận được.", "Angka seseorang salah, dan itu bukan penjaga tol Ratu. Dia tidak cukup pandai berhitung untuk berbuat curang.", "ตัวเลขของใครสักคนผิด และไม่ใช่ของคนเก็บค่าผ่านทางของราชินีแน่ เจ้านั่นบวกเลขไม่เก่งพอจะโกงได้หรอก", "Birinin rakamları yanlış ve bu Kraliçe'nin geçiş bekçisi değil. Hile yapacak kadar iyi toplama yapamaz.", "Las cifras de alguien están mal, y no son las del cobrador de la reina. No sabe sumar lo bastante bien como para hacer trampa.", "Os números de alguém estão errados, e não são os do cobrador da rainha. Ele não sabe somar bem o bastante para trapacear.", "Чьи-то цифры врут, и это не цифры королевского сборщика пошлин. Он не настолько хорошо считает, чтобы жульничать.", "Чиїсь цифри брешуть, і це не цифри королівського збирача мита. Він не настільки добре рахує, щоб шахраювати."],
  "The figures? They're in the ledger. The ledger's on the desk. I'm sure they're right.": ["数字ですか？台帳に書いてあります。台帳は机の上です。きっと合ってますよ。", "수치요? 장부에 있어요. 장부는 책상 위에 있고요. 분명 맞을 거예요.", "数字？在账簿里。账簿在桌上。我肯定它们没错。", "數字？在帳簿裡。帳簿在桌上。我肯定它們沒錯。", "Những con số ư? Chúng nằm trong sổ cái. Sổ cái ở trên bàn. Tôi chắc chắn chúng đúng.", "Angkanya? Ada di buku besar. Buku besarnya di meja. Aku yakin angkanya benar.", "ตัวเลขเหรอ อยู่ในสมุดบัญชี สมุดบัญชีอยู่บนโต๊ะ ข้าแน่ใจว่ามันถูกต้อง", "Rakamlar mı? Defterde. Defter masanın üstünde. Doğru olduklarından eminim.", "¿Las cifras? Están en el registro. El registro está en el escritorio. Seguro que son correctas.", "Os números? Estão no livro-caixa. O livro-caixa está na mesa. Tenho certeza de que estão certos.", "Цифры? Они в книге учёта. Книга на столе. Я уверен, что они верные.", "Цифри? Вони в книзі обліку. Книга на столі. Я певен, що вони правильні."],
  "The new hand. Yes. The bridge's column. I... A man from Sarovan said the League's figures were out of date. He gave me the new ones. And forty silver for my trouble, in Kharaveth coin.": ["新しい筆跡……はい。橋の欄です。わ、わたしは……サロヴァンから来た男が、同盟の数字は古くなっていると言ったんです。新しい数字をくれました。それと、手間賃として銀貨四十枚を。カラヴェスの貨幣で。", "새 필체요. 네. 다리 칸이요. 저, 저는... 사로반에서 온 남자가 동맹의 수치가 낡았다고 했어요. 새 수치를 줬고요. 그리고 수고비로 은화 마흔 닢을요. 카라베스 주화로.", "新的笔迹。是的。桥那一栏。我……有个从萨罗万来的人说同盟的数字过时了。他给了我新的。还给了我四十银币当辛苦费，卡拉维斯的钱。", "新的筆跡。是的。橋那一欄。我……有個從薩羅萬來的人說同盟的數字過時了。他給了我新的。還給了我四十銀幣當辛苦費，卡拉維斯的錢。", "Nét chữ mới. Vâng. Cột của cây cầu. Tôi... Một người đàn ông từ Sarovan nói số liệu của Liên minh đã lỗi thời. Ông ta đưa tôi số liệu mới. Và bốn mươi đồng bạc gọi là công sức, bằng tiền Kharaveth.", "Tulisan tangan yang baru. Ya. Kolom jembatan. Aku... Seorang pria dari Sarovan bilang angka-angka Liga sudah usang. Dia memberiku yang baru. Dan empat puluh keping perak sebagai upah, dalam mata uang Kharaveth.", "ลายมือใหม่ ใช่ ช่องของสะพาน ข้า... ชายคนหนึ่งจากสโรวันบอกว่าตัวเลขของสันนิบาตล้าสมัยแล้ว เขาให้ตัวเลขใหม่มา กับเงินสี่สิบเหรียญเป็นค่าเหนื่อย เป็นเหรียญของคาราเวธ", "Yeni el yazısı. Evet. Köprünün sütunu. Ben... Sarovan'dan bir adam Birlik'in rakamlarının eskidiğini söyledi. Bana yenilerini verdi. Bir de zahmetim için kırk gümüş, Kharaveth parasıyla.", "La letra nueva. Sí. La columna del puente. Yo... Un hombre de Sarovan dijo que las cifras de la Liga estaban desfasadas. Me dio las nuevas. Y cuarenta de plata por las molestias, en moneda de Kharaveth.", "A letra nova. Sim. A coluna da ponte. Eu... Um homem de Sarovan disse que os números da Liga estavam desatualizados. Ele me deu os novos. E quarenta de prata pelo incômodo, em moeda de Kharaveth.", "Новый почерк. Да. Графа моста. Я... Один человек из Сарована сказал, что цифры Лиги устарели. Дал мне новые. И сорок серебряных за труды, хараветской монетой.", "Новий почерк. Так. Графа мосту. Я... Один чоловік із Сарована сказав, що цифри Ліги застаріли. Дав мені нові. І сорок срібняків за клопіт, хараветською монетою."],
  "I didn't think it would matter! Seven rulers never agree on anything. I didn't think they'd agree on this.": ["大したことにはならないと思ったんです！七人の支配者が何かで意見が一致したことなんてないんですから。これで一致するなんて思わなかったんです。", "별일 아닐 줄 알았어요! 일곱 통치자는 무엇에도 합의하는 법이 없잖아요. 이걸로 합의할 줄은 몰랐어요.", "我没想到这会有什么要紧！七位统治者从来没在任何事上意见一致过。我没想到他们会在这件事上一致。", "我沒想到這會有什麼要緊！七位統治者從來沒在任何事上意見一致過。我沒想到他們會在這件事上一致。", "Tôi không nghĩ chuyện đó quan trọng! Bảy vị cai trị chưa bao giờ đồng ý với nhau về điều gì. Tôi không nghĩ họ lại đồng ý về chuyện này.", "Kukira itu tidak akan jadi masalah! Tujuh penguasa tak pernah sepakat soal apa pun. Kukira mereka tak akan sepakat soal ini.", "ข้าไม่คิดว่ามันจะสำคัญ! ผู้ปกครองเจ็ดคนไม่เคยเห็นตรงกันเรื่องอะไรเลย ข้าไม่คิดว่าพวกเขาจะเห็นตรงกันเรื่องนี้", "Önemli olacağını düşünmedim! Yedi hükümdar hiçbir konuda anlaşamaz. Bu konuda anlaşacaklarını düşünmedim.", "¡No pensé que importaría! Siete gobernantes nunca se ponen de acuerdo en nada. No pensé que se pondrían de acuerdo en esto.", "Não achei que fosse importar! Sete governantes nunca concordam em nada. Não achei que fossem concordar nisso.", "Я не думал, что это важно! Семь правителей никогда ни в чём не соглашаются. Я не думал, что они согласятся в этом.", "Я не думав, що це важливо! Семеро правителів ніколи ні в чому не згоджуються. Я не думав, що вони згодяться в цьому."],
  "The League's toll clerk. Forty silver. You have been busy.": ["同盟の通行税書記。銀貨四十枚。ずいぶんと精が出ますな。", "동맹의 통행세 서기. 은화 마흔 닢. 꽤 바쁘셨군요.", "同盟的关税书记。四十银币。你可真忙啊。", "同盟的關稅書記。四十銀幣。你可真忙啊。", "Thư lại thuế của Liên minh. Bốn mươi đồng bạc. Ngài quả là bận rộn.", "Juru tulis tol Liga. Empat puluh perak. Kau sibuk sekali rupanya.", "เสมียนด่านของสันนิบาต เงินสี่สิบเหรียญ ท่านช่างขยันเสียจริง", "Birlik'in gişe kâtibi. Kırk gümüş. Epey meşgulmüşsün.", "El escribano de peajes de la Liga. Cuarenta de plata. Veo que no has perdido el tiempo.", "O escrivão de pedágio da Liga. Quarenta de prata. Vejo que não perdeu tempo.", "Пошлинный писарь Лиги. Сорок серебряных. Времени ты зря не тратишь.", "Митний писар Ліги. Сорок срібняків. Часу ти даремно не гаєш."],
  "Consider: if the League and Ilavarta quarrel, carts stop, rice sits in the valley, its price goes up, and the Gilded Court, which buys Ilavarta's rice, buys less of it dearly instead of more cheaply. It's only arithmetic. Lady Seleneh is very good at arithmetic.": ["考えてもごらんなさい。同盟とイラヴァルタが争えば、荷車は止まり、米は谷に留まり、値が上がる。そしてイラヴァルタの米を買う金色の宮廷は、安くたくさん買う代わりに、高く少しだけ買うことになる。ただの算術ですよ。セレネ卿は算術がたいへんお得意でしてね。", "생각해 보시죠. 동맹과 일라바르타가 다투면 수레가 멈추고, 쌀은 계곡에 묶이고, 값이 오릅니다. 그러면 일라바르타의 쌀을 사는 황금 궁정은 싸게 많이 사는 대신 비싸게 적게 사게 되지요. 그저 산수일 뿐입니다. 셀레네 귀부인께서는 산수에 아주 능하시지요.", "想想看：如果同盟和伊拉瓦塔吵起来，车子停运，米积在河谷里，价格上涨，而买伊拉瓦塔大米的镀金宫廷，就不是便宜地多买，而是高价地少买。这不过是算术。塞勒涅夫人非常擅长算术。", "想想看：如果同盟和伊拉瓦塔吵起來，車子停運，米積在河谷裡，價格上漲，而買伊拉瓦塔稻米的鍍金宮廷，就不是便宜地多買，而是高價地少買。這不過是算術。塞勒涅夫人非常擅長算術。", "Hãy nghĩ xem: nếu Liên minh và Ilavarta cãi nhau, xe ngừng chạy, gạo nằm lại trong thung lũng, giá tăng lên, và Triều Mạ Vàng, bên mua gạo của Ilavarta, sẽ mua ít hơn với giá đắt thay vì mua nhiều hơn với giá rẻ. Chỉ là số học thôi. Phu nhân Seleneh rất giỏi số học.", "Pikirkan: kalau Liga dan Ilavarta bertengkar, gerobak berhenti, beras tertahan di lembah, harganya naik, dan Istana Bersepuh, yang membeli beras Ilavarta, membeli lebih sedikit dengan mahal alih-alih lebih banyak dengan murah. Itu cuma hitungan. Nyonya Seleneh sangat pandai berhitung.", "ลองคิดดู ถ้าสันนิบาตกับอิลาวรรตะทะเลาะกัน เกวียนก็หยุดวิ่ง ข้าวก็ค้างอยู่ในหุบเขา ราคาก็ขึ้น และราชสำนักปิดทองซึ่งซื้อข้าวของอิลาวรรตะ ก็จะซื้อน้อยลงในราคาแพง แทนที่จะซื้อมากขึ้นในราคาถูก มันก็แค่เลขคณิต ท่านหญิงเซเลเนห์เก่งเลขคณิตมาก", "Bir düşün: Birlik ile Ilavarta kavga ederse arabalar durur, pirinç vadide bekler, fiyatı yükselir ve Ilavarta'nın pirincini alan Yaldızlı Saray, ucuza çok almak yerine pahalıya az alır. Sadece aritmetik. Leydi Seleneh aritmetikte çok iyidir.", "Considera: si la Liga e Ilavarta riñen, los carros se detienen, el arroz se queda en el valle, su precio sube, y la Corte Dorada, que compra el arroz de Ilavarta, compra menos y caro en lugar de más y barato. Es pura aritmética. Lady Seleneh es muy buena en aritmética.", "Pense bem: se a Liga e Ilavarta brigarem, as carroças param, o arroz fica parado no vale, o preço sobe, e a Corte Dourada, que compra o arroz de Ilavarta, compra menos e caro em vez de mais e barato. É só aritmética. Lady Seleneh é muito boa em aritmética.", "Посуди: если Лига и Илаварта рассорятся, повозки встанут, рис застрянет в долине, цена на него вырастет, и Позолоченный двор, который покупает рис Илаварты, будет покупать его меньше и дороже, а не больше и дешевле. Это просто арифметика. Леди Селене очень хороша в арифметике.", "Поміркуй: якщо Ліга й Ілаварта посваряться, вози зупиняться, рис застрягне в долині, ціна на нього зросте, і Позолочений двір, що купує рис Ілаварти, купуватиме його менше й дорожче, а не більше й дешевше. Це просто арифметика. Леді Селене дуже добре знається на арифметиці."],
  "Tell the Speaker. I'll be on the next caravan to Sefrah, and I'll be replaced by someone with better handwriting.": ["議長に伝えてくれ。私は次の隊商でセフラへ発つ。後任にはもっと字のきれいな者が来るだろう。", "의장께 전하시오. 나는 다음 대상 편으로 세프라에 갈 테고, 내 자리는 글씨를 더 잘 쓰는 누군가가 채우겠지.", "去告诉议长吧。我会搭下一支商队回塞弗拉,接替我的会是个字写得更好的人。", "去告訴議長吧。我會搭下一支商隊回塞弗拉,接替我的會是個字寫得更好的人。", "Hãy báo với Phát ngôn nhân. Tôi sẽ lên đoàn buôn kế tiếp về Sefrah, và người thay tôi sẽ là ai đó có chữ viết đẹp hơn.", "Sampaikan pada Juru Bicara. Aku akan ikut karavan berikutnya ke Sefrah, dan aku akan diganti oleh orang yang tulisan tangannya lebih bagus.", "ไปบอกท่านประธานเถอะ ข้าจะขึ้นกองคาราวานเที่ยวหน้าไปเซฟราห์ แล้วจะมีคนที่ลายมือดีกว่ามาแทนข้า", "Sözcü'ye söyle. Sefrah'a giden ilk kervanda olacağım, yerime de el yazısı benimkinden güzel biri gelecek.", "Díselo a la Portavoz. Me iré en la próxima caravana a Sefrah, y me sustituirá alguien con mejor letra.", "Diga à Porta-voz. Vou na próxima caravana para Sefrah, e alguém com uma letra melhor vai me substituir.", "Передайте Глашатаю. Я уеду со следующим караваном в Сефру, а на моё место пришлют кого-нибудь с почерком получше.", "Передайте Речниці. Я поїду наступним караваном до Сефри, а на моє місце пришлють когось із кращим почерком."],
  "Tell Speaker Hemavati what the Gilded Court's factor admitted.": ["金色の宮廷の代理商が認めたことをヘマヴァティ議長に伝える。", "황금 궁정의 중개인이 자백한 내용을 헤마바티 의장에게 전한다.", "把镀金宫廷代理商承认的事告诉赫玛瓦蒂议长。", "把鍍金宮廷代理商承認的事告訴赫瑪瓦蒂議長。", "Báo cho Phát ngôn nhân Hemavati những gì đại lý của Triều Mạ Vàng đã thú nhận.", "Sampaikan kepada Juru Bicara Hemavati apa yang diakui agen Istana Bersepuh.", "บอกประธานเหมาวดีถึงสิ่งที่ตัวแทนของราชสำนักปิดทองยอมรับ", "Yaldızlı Saray'ın kâhyasının itiraf ettiklerini Sözcü Hemavati'ye anlat.", "Cuéntale a la Portavoz Hemavati lo que admitió el factor de la Corte Dorada.", "Conte à Porta-voz Hemavati o que o feitor da Corte Dourada admitiu.", "Расскажите Глашатаю Хемавати, в чём признался фактор Позолоченного двора.", "Розкажіть Речниці Хемаваті, у чому зізнався фактор Позолоченого двору."],
  "My licence. The Kanthari's grove. I signed it for pit props, not for a grove.": ["私の許可状だ。カンタリの聖林……。署名したのは坑木のためで、聖林のためではない。", "내 허가증이군. 칸타리족의 신성한 숲이라. 내가 서명한 건 갱목 때문이지, 숲 때문이 아니었다.", "我的许可证。坎塔里人的圣林。我签它是为了矿坑支柱,不是为了一片圣林。", "我的許可證。坎塔里人的聖林。我簽它是為了礦坑支柱,不是為了一片聖林。", "Giấy phép của ta. Rừng thiêng của người Kanthari. Ta ký nó để lấy cột chống hầm mỏ, chứ không phải để lấy một khu rừng thiêng.", "Izinku. Hutan keramat orang Kanthari. Aku menandatanganinya untuk penyangga tambang, bukan untuk hutan keramat.", "ใบอนุญาตของข้า ป่าศักดิ์สิทธิ์ของชาวกันถารี ข้าลงนามเพื่อไม้ค้ำเหมือง ไม่ใช่เพื่อป่าศักดิ์สิทธิ์", "İzin belgem. Kanthariler'in korusu. Bunu maden direkleri için imzaladım, bir koru için değil.", "Mi licencia. La arboleda de los kanthari. La firmé para puntales de mina, no para una arboleda.", "Minha licença. O bosque dos kanthari. Eu assinei para escoras de mina, não para um bosque.", "Моя лицензия. Роща кантхари. Я подписывал её на рудничные крепи, а не на рощу.", "Моя ліцензія. Гай кантхарі. Я підписував її на шахтне кріплення, а не на гай."],
  "(He tears it across, slowly.) The loggers will have a new one with the Kanthari's stones drawn on it. Tell the grandmother Shailagarh keeps its word, when it remembers what it said.": ["(彼はそれをゆっくりと二つに裂く)木こりたちには、カンタリの石を描き込んだ新しいものを渡そう。婆さまに伝えてくれ。シャイラガルは約束を守る。自分が何を言ったか覚えているときはな。", "(그가 그것을 천천히 반으로 찢는다.) 벌목꾼들에겐 칸타리족의 돌을 그려 넣은 새 허가증을 주겠다. 할머니께 전해 주게. 샤일라가르는 약속을 지킨다고. 자기가 무슨 말을 했는지 기억할 때는.", "(他慢慢把它撕成两半。)伐木工会拿到一张新的,上面画着坎塔里人的界石。告诉那位奶奶,沙伊拉加尔说话算话,只要它还记得自己说过什么。", "(他慢慢把它撕成兩半。)伐木工會拿到一張新的,上面畫著坎塔里人的界石。告訴那位奶奶,沙伊拉加爾說話算話,只要它還記得自己說過什麼。", "(Ông chậm rãi xé đôi tờ giấy.) Bọn tiều phu sẽ có tờ mới, có vẽ những phiến đá của người Kanthari trên đó. Nói với bà rằng Shailagarh giữ lời, khi nó còn nhớ mình đã nói gì.", "(Ia merobeknya pelan-pelan.) Para penebang akan mendapat izin baru dengan batu-batu orang Kanthari tergambar di atasnya. Bilang pada Nenek, Shailagarh menepati janjinya, kalau ingat apa yang pernah diucapkannya.", "(เขาค่อย ๆ ฉีกมันขาดเป็นสองท่อน) พวกคนตัดไม้จะได้ใบใหม่ที่วาดหินของชาวกันถารีลงไปด้วย ไปบอกยายว่าไศลครห์รักษาคำพูดเสมอ เมื่อไรที่จำได้ว่าพูดอะไรไว้", "(Belgeyi yavaşça ikiye yırtar.) Odunculara üzerinde Kanthariler'in taşları çizili yeni bir izin verilecek. Nine'ye söyle, Shailagarh sözünü tutar; ne dediğini hatırladığında.", "(La rompe en dos, despacio.) Los leñadores tendrán una nueva con las piedras de los kanthari dibujadas. Dile a la abuela que Shailagarh cumple su palabra, cuando se acuerda de lo que dijo.", "(Ele a rasga ao meio, devagar.) Os lenhadores vão receber uma nova, com as pedras dos kanthari desenhadas. Diga à avó que Shailagarh cumpre a palavra, quando se lembra do que disse.", "(Он медленно рвёт её пополам.) Лесорубы получат новую, с нарисованными камнями кантхари. Передайте бабушке: Шайлагарх держит слово, когда помнит, что говорил.", "(Він повільно розриває її навпіл.) Лісоруби отримають нову, з намальованими каменями кантхарі. Перекажіть бабусі: Шайлагарх тримає слово, коли пам'ятає, що казав."],
  "Lord Varanjit tore up the licence. Tell Grandmother Sukesh.": ["ヴァランジット卿が許可状を破り捨てた。スケシュ婆さまに伝えよう。", "바란지트 경이 허가증을 찢었다. 수케시 할머니에게 알리자.", "瓦兰吉特大人撕掉了许可证。去告诉苏凯什奶奶。", "瓦蘭吉特大人撕掉了許可證。去告訴蘇凱什奶奶。", "Lãnh chúa Varanjit đã xé giấy phép. Hãy báo cho Bà Sukesh.", "Tuan Varanjit merobek izinnya. Beri tahu Nenek Sukesh.", "ท่านวรัญชิตฉีกใบอนุญาตทิ้งแล้ว ไปบอกยายสุเกศ", "Lord Varanjit izni yırttı. Sukesh Nine'ye haber ver.", "El señor Varanjit ha roto la licencia. Díselo a la abuela Sukesh.", "O senhor Varanjit rasgou a licença. Conte à avó Sukesh.", "Лорд Варанджит порвал лицензию. Расскажите бабушке Сукеш.", "Лорд Варанджит порвав ліцензію. Розкажіть бабусі Сукеш."],
  "The high toll-house on the eastern pass is mine, and men from the Copper Banner companies I hire have taken it, and they're charging travellers a toll of their own. In my pass.": ["東の峠の高みにある関所は私のものだ。それを、私が雇っている銅の旗の傭兵隊の連中が乗っ取り、旅人から勝手に通行料を取っている。私の峠でだ。", "동쪽 고개 높은 곳의 통행세 초소는 내 것이다. 그런데 내가 고용한 구리 깃발 용병대의 자들이 그곳을 차지하고, 나그네들에게 제멋대로 통행료를 받고 있지. 내 고개에서.", "东边山口上的高处关卡是我的,可我雇来的铜旗佣兵队里有些人把它占了,还向过路人收起了他们自己的过路费。在我的山口上。", "東邊山口上的高處關卡是我的,可我僱來的銅旗傭兵隊裡有些人把它佔了,還向過路人收起了他們自己的過路費。在我的山口上。", "Trạm thu phí trên cao ở đèo phía đông là của ta, vậy mà người của các đại đội Cờ Đồng do ta thuê đã chiếm lấy nó, và đang thu phí riêng của chúng từ khách qua đường. Trên đèo của ta.", "Pos bea di ketinggian celah gunung timur itu milikku, dan orang-orang dari kompi Panji Tembaga yang kusewa telah merebutnya, lalu memungut bea sendiri dari para pelancong. Di celah gunungku.", "ด่านเก็บค่าผ่านทางบนที่สูงของช่องเขาตะวันออกเป็นของข้า แต่คนของกองร้อยธงทองแดงที่ข้าจ้างไว้ยึดมันไป แล้วเก็บค่าผ่านทางจากนักเดินทางเป็นของตัวเอง ในช่องเขาของข้า", "Doğu geçidindeki yüksek geçit karakolu benim; tuttuğum Bakır Sancak bölüklerinden adamlar orayı ele geçirmiş ve yolculardan kendi geçiş ücretlerini alıyorlar. Benim geçidimde.", "La casa de peaje alta del paso oriental es mía, y unos hombres de las compañías del Estandarte de Cobre que contrato la han tomado y cobran a los viajeros un peaje propio. En mi paso.", "A casa de pedágio no alto do desfiladeiro oriental é minha, e homens das companhias do Estandarte de Cobre que eu contrato a tomaram e estão cobrando dos viajantes um pedágio próprio. No meu desfiladeiro.", "Верхняя застава на восточном перевале — моя, а её захватили люди из нанятых мной отрядов Медного знамени и берут с путников собственную пошлину. На моём перевале.", "Верхня застава на східному перевалі — моя, а її захопили люди з найнятих мною загонів Мідного стягу й беруть із подорожніх власне мито. На моєму перевалі."],
  "I want them gone. Captain Marr wants them talked to. Do whichever you like, as long as they're gone.": ["私は奴らを追い出したい。マール隊長は話をしてほしいと言う。好きなほうでいい、奴らがいなくなるならな。", "나는 그놈들이 사라지길 바란다. 마르 대장은 그들과 이야기해 보길 바라지. 어느 쪽이든 좋을 대로 하게. 그놈들이 사라지기만 한다면.", "我要他们滚。马尔队长想先跟他们谈谈。你怎么做都行,只要他们滚。", "我要他們滾。馬爾隊長想先跟他們談談。你怎麼做都行,只要他們滾。", "Ta muốn chúng biến đi. Đội trưởng Marr muốn nói chuyện với chúng. Ngươi muốn làm cách nào cũng được, miễn là chúng biến đi.", "Aku ingin mereka pergi. Kapten Marr ingin mereka diajak bicara. Lakukan yang mana saja sesukamu, asal mereka pergi.", "ข้าอยากให้พวกมันไปให้พ้น ร้อยเอกมาร์อยากให้คุยกับพวกมันก่อน จะทำแบบไหนก็ตามใจ ขอแค่พวกมันไปให้พ้น", "Gitmelerini istiyorum. Yüzbaşı Marr onlarla konuşulmasını istiyor. Hangisini istersen yap, yeter ki gitsinler.", "Quiero que se vayan. La capitana Marr quiere que alguien hable con ellos. Haz lo que prefieras, mientras se vayan.", "Quero que eles sumam. A capitã Marr quer que alguém converse com eles. Faça como preferir, contanto que sumam.", "Я хочу, чтобы их там не было. Капитан Марр хочет, чтобы с ними поговорили. Делайте как угодно, лишь бы их там не было.", "Я хочу, щоб їх там не було. Капітанка Марр хоче, щоб із ними поговорили. Робіть як завгодно, аби тільки їх там не було."],
  "Hear Marr first, she'll insist. The toll-house is east along the highland road, past the mines.": ["まずマールの話を聞いてやれ。あいつがそうしろと言い張るだろうからな。関所は高地の道を東へ、鉱山の先だ。", "먼저 마르의 말을 들어 보게. 그녀가 고집할 테니. 통행세 초소는 고원 길을 따라 동쪽, 광산을 지나서 있네.", "先听听马尔怎么说,她肯定会坚持的。关卡在高地大道往东,过了矿场就是。", "先聽聽馬爾怎麼說,她肯定會堅持的。關卡在高地大道往東,過了礦場就是。", "Nghe Marr nói trước đã, cô ta sẽ đòi thế. Trạm thu phí ở phía đông theo đường cao nguyên, qua khỏi các mỏ.", "Dengar dulu Marr, dia pasti memaksa. Pos bea itu ada di timur menyusuri jalan dataran tinggi, lewat tambang-tambang.", "ฟังมาร์ก่อน นางต้องยืนกรานแน่ ด่านอยู่ทางตะวันออกตามถนนที่ราบสูง เลยเหมืองไป", "Önce Marr'ı dinle, ısrar edecektir. Geçit karakolu yayla yolu boyunca doğuda, madenlerin ilerisinde.", "Escucha primero a Marr; insistirá. La casa de peaje está al este por el camino de las tierras altas, pasadas las minas.", "Ouça a Marr primeiro, ela vai insistir. A casa de pedágio fica a leste pela estrada das terras altas, depois das minas.", "Сначала выслушайте Марр, она будет настаивать. Застава на востоке по горной дороге, за рудниками.", "Спершу вислухайте Марр, вона наполягатиме. Застава на сході гірською дорогою, за копальнями."],
  "The toll-house is east, past the mines. Every day they hold it, my pass is somebody else's.": ["関所は東、鉱山の先だ。奴らが居座る日ごとに、私の峠は他人のものになっている。", "통행세 초소는 동쪽, 광산 너머에 있네. 그들이 버티는 하루하루, 내 고개는 남의 것이 되지.", "关卡在东边,过了矿场就是。他们多占一天,我的山口就多一天是别人的。", "關卡在東邊,過了礦場就是。他們多佔一天,我的山口就多一天是別人的。", "Trạm thu phí ở phía đông, qua khỏi các mỏ. Mỗi ngày chúng còn chiếm giữ, đèo của ta lại là của kẻ khác.", "Pos bea itu di timur, lewat tambang. Setiap hari mereka menguasainya, celah gunungku jadi milik orang lain.", "ด่านอยู่ทางตะวันออก เลยเหมืองไป ทุกวันที่พวกมันยึดไว้ ช่องเขาของข้าก็เป็นของคนอื่น", "Geçit karakolu doğuda, madenlerin ilerisinde. Orayı tuttukları her gün, geçidim başkasının oluyor.", "La casa de peaje está al este, pasadas las minas. Cada día que la retienen, mi paso es de otro.", "A casa de pedágio fica a leste, depois das minas. Cada dia que eles a mantêm, meu desfiladeiro é de outra pessoa.", "Застава на востоке, за рудниками. Каждый день, пока они её держат, мой перевал принадлежит кому-то другому.", "Застава на сході, за копальнями. Щодня, поки вони її тримають, мій перевал належить комусь іншому."],
  "Marr says they're owed. Everybody's owed. I pay Khetmar for her companies every month, in full.": ["マールは奴らには未払いがあると言う。誰にだって貸しはあるものだ。私は毎月、彼女の傭兵隊の分をケトマルに満額払っている。", "마르는 그들이 받을 돈이 있다고 하지. 받을 돈 없는 사람이 어디 있나. 나는 매달 그녀의 용병대 몫을 케트마르에 빠짐없이 치르고 있네.", "马尔说欠着他们的钱。谁不是被欠着钱?我每个月都把她那些佣兵队的钱一分不少地付给克特马尔。", "馬爾說欠著他們的錢。誰不是被欠著錢?我每個月都把她那些傭兵隊的錢一分不少地付給克特馬爾。", "Marr bảo người ta nợ chúng. Ai mà chẳng bị nợ. Tháng nào ta cũng trả Khetmar đủ tiền cho các đại đội của cô ta.", "Marr bilang mereka belum dibayar. Semua orang juga merasa belum dibayar. Aku membayar Khetmar untuk kompi-kompinya setiap bulan, penuh.", "มาร์บอกว่าพวกมันยังไม่ได้รับเงินที่ค้างไว้ ใคร ๆ ก็มีเงินค้างทั้งนั้น ข้าจ่ายเคทมาร์ค่ากองร้อยของนางทุกเดือน เต็มจำนวน", "Marr onlara borç olduğunu söylüyor. Herkese borç var. Ben her ay onun bölükleri için Khetmar'a tam ödeme yapıyorum.", "Marr dice que se les debe dinero. A todo el mundo se le debe. Yo le pago a Khetmar por sus compañías cada mes, íntegro.", "A Marr diz que devem a eles. Devem a todo mundo. Eu pago Khetmar pelas companhias dela todo mês, integralmente.", "Марр говорит, им задолжали. Всем задолжали. Я плачу Кетмару за её отряды каждый месяц, сполна.", "Марр каже, їм заборгували. Усім заборгували. Я плачу Кетмару за її загони щомісяця, сповна."],
  "Hask is dead and the toll-house is mine. What's that? Their paybook.": ["ハスクは死に、関所は私の手に戻った。それは何だ? 奴らの給金帳か。", "하스크는 죽었고 통행세 초소는 내 것이 되었군. 그건 뭔가? 그들의 급료 장부로군.", "哈斯克死了,关卡又归我了。那是什么?他们的饷册。", "哈斯克死了,關卡又歸我了。那是什麼?他們的餉冊。", "Hask đã chết và trạm thu phí lại là của ta. Cái gì kia? Sổ lương của chúng.", "Hask sudah mati dan pos bea itu milikku lagi. Apa itu? Buku gaji mereka.", "ฮาสก์ตายแล้ว ด่านก็กลับเป็นของข้า นั่นอะไร สมุดบัญชีเงินเดือนของพวกมันหรือ", "Hask öldü ve geçit karakolu yine benim. O ne? Maaş defterleri.", "Hask ha muerto y la casa de peaje es mía. ¿Qué es eso? Su libro de pagas.", "Hask está morto e a casa de pedágio é minha. O que é isso? O livro de soldos deles.", "Хаск мёртв, и застава снова моя. Что это? Их платёжная книга.", "Хаск мертвий, і застава знову моя. Що це? Їхня платіжна книга."],
  "Your money reached Khetmar's agent. It never reached the companies.": ["あなたの金はケトマルの代理人には届いた。だが傭兵隊には一度も届いていない。", "경의 돈은 케트마르의 대리인에게는 닿았습니다. 용병대에는 한 번도 닿지 않았고요.", "您的钱到了克特马尔的代理人手里,却从没到过佣兵队手里。", "您的錢到了克特馬爾的代理人手裡,卻從沒到過傭兵隊手裡。", "Tiền của ngài đã đến tay người đại diện của Khetmar. Nó chưa bao giờ đến được các đại đội.", "Uang Tuan sampai ke agen Khetmar. Tak pernah sampai ke kompi-kompi.", "เงินของท่านไปถึงตัวแทนของเคทมาร์ แต่ไม่เคยไปถึงกองร้อยเลย", "Paranız Khetmar'ın temsilcisine ulaştı. Bölüklere hiç ulaşmadı.", "Su dinero llegó al agente de Khetmar. Nunca llegó a las compañías.", "Seu dinheiro chegou ao agente de Khetmar. Nunca chegou às companhias.", "Ваши деньги дошли до агента Кетмара. До отрядов они не дошли ни разу.", "Ваші гроші дійшли до агента Кетмара. До загонів вони не дійшли жодного разу."],
  "(He reads it twice.) So I've been paying the Marshal's agent to keep my soldiers poor.": ["(彼は二度読み返す)つまり私は、自分の兵を貧しくしておくために元帥の代理人に金を払っていたわけか。", "(그가 두 번 읽는다.) 그러니까 나는 내 병사들을 가난하게 두라고 원수의 대리인에게 돈을 치러 온 셈이군.", "(他读了两遍。)这么说,我一直在花钱请元帅的代理人让我的士兵受穷。", "(他讀了兩遍。)這麼說,我一直在花錢請元帥的代理人讓我的士兵受窮。", "(Ông đọc hai lần.) Vậy là ta đã trả tiền cho người đại diện của Thống chế để giữ cho lính của ta nghèo.", "(Ia membacanya dua kali.) Jadi selama ini aku membayar agen sang Marsekal supaya prajurit-prajuritku tetap miskin.", "(เขาอ่านมันสองรอบ) งั้นข้าก็จ่ายเงินให้ตัวแทนของจอมพลเพื่อให้ทหารของข้ายากจนอยู่อย่างนี้น่ะสิ", "(İki kez okur.) Demek ben Mareşal'in temsilcisine askerlerimi yoksul tutsun diye para ödüyormuşum.", "(La lee dos veces.) Así que he estado pagando al agente del Mariscal para que mis soldados sigan siendo pobres.", "(Ele lê duas vezes.) Então eu andei pagando o agente do Marechal para manter meus soldados pobres.", "(Он перечитывает дважды.) Значит, я платил агенту Маршала за то, чтобы мои солдаты оставались нищими.", "(Він перечитує двічі.) Отже, я платив агентові Маршала за те, щоб мої солдати лишалися злиденними."],
  "From now on Shailagarh pays its companies itself, here, in silver, on the first of the month. Tell Marr. And take this helm: the last pass-warden's. He'd have liked you; he never trusted Khetmar either.": ["これからはシャイラガルが自ら傭兵隊に払う。ここで、銀で、毎月一日にだ。マールに伝えてくれ。それと、この兜を持っていけ。先代の峠守のものだ。あいつならお前を気に入っただろう。あいつもケトマルを一度も信用しなかった。", "이제부터 샤일라가르가 직접 용병대에 급료를 치른다. 여기서, 은으로, 매달 초하루에. 마르에게 전하게. 그리고 이 투구를 받게. 마지막 고개지기의 것이지. 그 사람도 자네를 마음에 들어 했을 거야. 그도 케트마르를 한 번도 믿지 않았거든.", "从今往后,沙伊拉加尔亲自给佣兵队发饷:就在这里,用银子,每月初一。告诉马尔。再拿上这顶头盔:上一任山口守卫的。他会喜欢你的;他也从来不信克特马尔。", "從今往後,沙伊拉加爾親自給傭兵隊發餉:就在這裡,用銀子,每月初一。告訴馬爾。再拿上這頂頭盔:上一任山口守衛的。他會喜歡你的;他也從來不信克特馬爾。", "Từ nay Shailagarh sẽ tự trả lương cho các đại đội, tại đây, bằng bạc, vào ngày mùng một mỗi tháng. Nói với Marr. Và cầm lấy chiếc mũ trụ này: của người giữ đèo cuối cùng. Ông ấy hẳn sẽ quý ngươi; ông ấy cũng chưa bao giờ tin Khetmar.", "Mulai sekarang Shailagarh membayar kompi-kompinya sendiri, di sini, dengan perak, setiap tanggal satu. Beri tahu Marr. Dan ambil helm ini: milik penjaga celah terakhir. Dia pasti menyukaimu; dia juga tak pernah percaya pada Khetmar.", "นับจากนี้ไศลครห์จะจ่ายเงินกองร้อยเอง ที่นี่ เป็นเหรียญเงิน ทุกวันที่หนึ่งของเดือน ไปบอกมาร์ แล้วรับหมวกเกราะนี่ไป ของผู้คุมช่องเขาคนสุดท้าย เขาคงชอบเจ้า เขาเองก็ไม่เคยไว้ใจเคทมาร์เหมือนกัน", "Bundan sonra Shailagarh bölüklerine kendisi ödeyecek; burada, gümüşle, her ayın birinde. Marr'a söyle. Bir de şu miğferi al: son geçit muhafızınındı. Seni severdi; o da Khetmar'a hiç güvenmezdi.", "A partir de ahora Shailagarh paga a sus compañías en persona, aquí, en plata, el día uno de cada mes. Díselo a Marr. Y llévate este yelmo: era del último guardián del paso. Le habrías caído bien; él tampoco se fió nunca de Khetmar.", "De agora em diante Shailagarh paga as próprias companhias, aqui, em prata, no primeiro dia do mês. Diga à Marr. E leve este elmo: era do último guardião do desfiladeiro. Ele teria gostado de você; também nunca confiou em Khetmar.", "Отныне Шайлагарх платит своим отрядам сам, здесь, серебром, первого числа каждого месяца. Передайте Марр. И возьмите этот шлем: он принадлежал последнему стражу перевала. Вы бы ему понравились; он тоже никогда не доверял Кетмару.", "Відтепер Шайлагарх платить своїм загонам сам, тут, сріблом, першого числа щомісяця. Перекажіть Марр. І візьміть цей шолом: він належав останньому вартовому перевалу. Ви б йому сподобалися; він теж ніколи не довіряв Кетмару."],
  "Hask was my sergeant. Twelve years. He didn't desert: he stopped waiting.": ["ハスクは私の軍曹だった。十二年だ。あいつは脱走したんじゃない。待つのをやめただけさ。", "하스크는 내 하사였어. 십이 년이나. 그는 탈영한 게 아니야. 기다리기를 그만둔 거지.", "哈斯克是我的中士。十二年了。他不是开小差:他只是不再等了。", "哈斯克是我的中士。十二年了。他不是開小差:他只是不再等了。", "Hask là trung sĩ của tôi. Mười hai năm. Anh ta không đào ngũ: anh ta chỉ thôi chờ đợi.", "Hask sersanku. Dua belas tahun. Dia tidak desersi: dia berhenti menunggu.", "ฮาสก์เป็นจ่าของข้า สิบสองปี เขาไม่ได้หนีทัพ เขาแค่เลิกรอ", "Hask benim çavuşumdu. On iki yıl. Firar etmedi: beklemeyi bıraktı.", "Hask era mi sargento. Doce años. No desertó: dejó de esperar.", "Hask era meu sargento. Doze anos. Ele não desertou: parou de esperar.", "Хаск был моим сержантом. Двенадцать лет. Он не дезертировал: он перестал ждать.", "Хаск був моїм сержантом. Дванадцять років. Він не дезертирував: він перестав чекати."],
  "None of us have been paid since spring. The Lord says he pays Khetmar, Khetmar says it pays us. Look in the toll-house. Hask kept books on everything; he'll have kept books on that.": ["春から誰一人給金をもらっていない。卿はケトマルに払っていると言い、ケトマルは私たちに払っていると言う。関所の中を調べてみな。ハスクは何でも帳面につけていた。そのこともつけているはずだ。", "봄 이후로 우리 중 누구도 급료를 못 받았어. 경께서는 케트마르에 치른다고 하고, 케트마르는 우리에게 치른다고 하지. 통행세 초소 안을 살펴봐. 하스크는 뭐든 장부에 적어 두는 사람이었으니, 그것도 적어 뒀을 거야.", "打从春天起,我们就没人领到过饷。大人说他付给了克特马尔,克特马尔说它付给了我们。去关卡里找找。哈斯克什么都记账;这件事他肯定也记了。", "打從春天起,我們就沒人領到過餉。大人說他付給了克特馬爾,克特馬爾說它付給了我們。去關卡裡找找。哈斯克什麼都記帳;這件事他肯定也記了。", "Từ mùa xuân đến giờ chưa ai trong chúng tôi được trả lương. Lãnh chúa nói ông trả cho Khetmar, Khetmar nói họ trả cho chúng tôi. Hãy xem trong trạm thu phí. Hask ghi sổ mọi thứ; chắc chắn anh ta cũng ghi sổ chuyện đó.", "Tak seorang pun dari kami digaji sejak musim semi. Tuan bilang dia membayar Khetmar, Khetmar bilang mereka membayar kami. Periksa pos bea itu. Hask mencatat segalanya; pasti itu juga dicatatnya.", "ตั้งแต่หน้าใบไม้ผลิ ไม่มีใครในพวกเราได้รับเงินเลยสักคน ท่านวรัญชิตบอกว่าจ่ายให้เคทมาร์แล้ว เคทมาร์บอกว่าจ่ายให้พวกเราแล้ว ลองไปดูในด่านสิ ฮาสก์จดบัญชีทุกอย่าง เรื่องนี้เขาก็คงจดไว้", "Bahardan beri hiçbirimize maaş ödenmedi. Lord, Khetmar'a ödediğini söylüyor; Khetmar da bize ödediğini. Geçit karakoluna bak. Hask her şeyin defterini tutardı; bunun da defterini tutmuştur.", "A ninguno nos pagan desde la primavera. El señor dice que le paga a Khetmar, Khetmar dice que nos paga a nosotros. Mira en la casa de peaje. Hask llevaba cuentas de todo; de eso también las habrá llevado.", "Nenhum de nós recebe desde a primavera. O senhor diz que paga Khetmar, Khetmar diz que paga a gente. Dê uma olhada na casa de pedágio. Hask anotava tudo; isso ele também deve ter anotado.", "Никому из нас не платили с весны. Лорд говорит, что платит Кетмару, Кетмар говорит, что платит нам. Загляните на заставу. Хаск всё записывал; это он тоже наверняка записал.", "Нікому з нас не платили з весни. Лорд каже, що платить Кетмару, Кетмар каже, що платить нам. Зазирніть на заставу. Хаск усе записував; це він теж напевно записав."],
  "Paid on the first of the month, in silver, by the Lord's own hand. I never thought I'd see it.": ["毎月一日に、銀で、卿ご自身の手から支払われる。こんな日が来るとは思わなかったよ。", "매달 초하루에, 은으로, 경께서 손수 지급하시지. 이런 날을 보게 될 줄은 몰랐어.", "每月初一,用银子,由大人亲手发。我做梦都没想到能见到这一天。", "每月初一,用銀子,由大人親手發。我做夢都沒想到能見到這一天。", "Được trả vào ngày mùng một mỗi tháng, bằng bạc, từ chính tay Lãnh chúa. Tôi chưa từng nghĩ mình sẽ được thấy ngày đó.", "Dibayar setiap tanggal satu, dengan perak, dari tangan Tuan sendiri. Tak pernah kusangka akan melihatnya.", "ได้เงินทุกวันที่หนึ่งของเดือน เป็นเหรียญเงิน จากมือท่านวรัญชิตเอง ข้าไม่เคยคิดว่าจะได้เห็นวันนี้", "Her ayın birinde, gümüşle, Lord'un kendi eliyle ödeniyor. Bunu göreceğimi hiç düşünmezdim.", "Pagados el día uno de cada mes, en plata, de mano del propio señor. Nunca pensé que lo vería.", "Pagos no primeiro dia do mês, em prata, pelas mãos do próprio senhor. Nunca pensei que fosse ver isso.", "Платят первого числа, серебром, из рук самого лорда. Не думала, что доживу.", "Платять першого числа, сріблом, із рук самого лорда. Не думала, що доживу."],
  "Hask was a good sergeant. He should have been paid, not buried.": ["ハスクはいい軍曹だった。埋められるんじゃなく、給金をもらうべきだった。", "하스크는 좋은 하사였지. 묻힐 게 아니라 급료를 받았어야 했어.", "哈斯克是个好中士。他该领到饷,而不是被埋掉。", "哈斯克是個好中士。他該領到餉,而不是被埋掉。", "Hask là một trung sĩ tốt. Anh ta đáng được trả lương, chứ không phải bị chôn.", "Hask sersan yang baik. Seharusnya dia digaji, bukan dikubur.", "ฮาสก์เป็นจ่าที่ดี เขาควรได้รับเงิน ไม่ใช่ถูกฝัง", "Hask iyi bir çavuştu. Gömülmesi değil, maaşının ödenmesi gerekirdi.", "Hask era un buen sargento. Debieron pagarle, no enterrarlo.", "Hask era um bom sargento. Devia ter sido pago, não enterrado.", "Хаск был хорошим сержантом. Ему следовало заплатить, а не хоронить его.", "Хаск був добрим сержантом. Йому слід було заплатити, а не ховати його."],
  "Ninety-nine leaves. The star chart has a hundred. I've counted it eleven times, and I'll count it a twelfth while you watch.": ["九十九枚。星図は百枚あるはずだ。十一回数えた。君の見ている前で十二回目を数えよう。", "아흔아홉 장. 성도는 백 장이오. 열한 번을 셌고, 당신이 보는 앞에서 열두 번째로 세겠소.", "九十九页。星图本该有一百页。我数了十一遍,现在当着你的面数第十二遍。", "九十九頁。星圖本該有一百頁。我數了十一遍,現在當著你的面數第十二遍。", "Chín mươi chín tờ. Tấm bản đồ sao có một trăm tờ. Tôi đã đếm mười một lần, và tôi sẽ đếm lần thứ mười hai ngay trước mặt bạn.", "Sembilan puluh sembilan lembar. Peta bintang itu punya seratus. Sudah kuhitung sebelas kali, dan akan kuhitung yang kedua belas sambil kau lihat.", "เก้าสิบเก้าแผ่น แผนที่ดาวมีหนึ่งร้อยแผ่น ข้านับมาสิบเอ็ดรอบแล้ว และจะนับรอบที่สิบสองให้ท่านดูเดี๋ยวนี้", "Doksan dokuz yaprak. Yıldız haritasında yüz tane var. On bir kez saydım, sen bakarken on ikinci kez de sayacağım.", "Noventa y nueve hojas. La carta estelar tiene cien. La he contado once veces, y la contaré una duodécima mientras miras.", "Noventa e nove folhas. O mapa estelar tem cem. Já contei onze vezes, e vou contar a décima segunda com você olhando.", "Девяносто девять листов. В звёздной карте их сто. Я пересчитал одиннадцать раз и пересчитаю в двенадцатый у вас на глазах.", "Дев'яносто дев'ять аркушів. У зоряній мапі їх сто. Я перелічив одинадцять разів і перелічу вдванадцяте у вас на очах."],
  "The ninth leaf is gone: the one with the river of stars on it. And the Obsidian Legacy's envoy has sat at that desk every day for a month.": ["九枚目がない。星の川が描かれた一枚だ。そして黒曜の遺統の使節は、この一か月毎日あの机に座っていた。", "아홉 번째 장이 없어졌소. 별의 강이 그려진 장이오. 그리고 흑요 유산의 사절이 한 달 동안 매일 저 책상에 앉아 있었지.", "第九页不见了:画着星河的那一页。而黑曜遗脉的使节这一个月天天坐在那张桌子前。", "第九頁不見了:畫著星河的那一頁。而黑曜遺脈的使節這一個月天天坐在那張桌子前。", "Tờ thứ chín đã mất: tờ có vẽ dòng sông sao. Và sứ giả của Di Sản Hắc Diện đã ngồi ở chiếc bàn đó mỗi ngày suốt một tháng.", "Lembar kesembilan hilang: yang bergambar sungai bintang. Dan utusan Warisan Obsidian duduk di meja itu setiap hari selama sebulan.", "แผ่นที่เก้าหายไป แผ่นที่มีแม่น้ำแห่งดวงดาว และทูตแห่งมรดกออบซิเดียนก็นั่งอยู่ที่โต๊ะตัวนั้นทุกวันมาตลอดเดือน", "Dokuzuncu yaprak yok: üzerinde yıldız nehri olan. Obsidyen Mirası'nın elçisi de bir aydır her gün o masada oturuyor.", "Falta la novena hoja: la del río de estrellas. Y el enviado del Legado de Obsidiana se ha sentado en ese pupitre todos los días durante un mes.", "A nona folha sumiu: a do rio de estrelas. E o enviado do Legado de Obsidiana sentou-se àquela mesa todos os dias durante um mês.", "Девятого листа нет: того, где звёздная река. А посланник Обсидианового наследия целый месяц каждый день сидел за тем столом.", "Дев'ятого аркуша немає: того, де зоряна ріка. А посланець Обсидіанової спадщини цілий місяць щодня сидів за тим столом."],
  "Talk to Saqqet, if you can stand it. And look at the borrowing ledger by the door: everything that leaves the reading room is written in it. Everything.": ["耐えられるなら、サッケトと話してみるといい。それから扉のそばの貸出台帳を見てくれ。閲覧室から出ていくものはすべてそこに書かれている。すべてだ。", "견딜 수 있다면 사케트와 이야기해 보시오. 그리고 문 옆의 대출 장부를 보시오. 열람실을 나가는 건 전부 거기에 적혀 있소. 전부.", "去跟萨凯特谈谈,如果你受得了他的话。再看看门边的借阅登记簿:凡是离开阅览室的东西都记在上面。一样不落。", "去跟薩凱特談談,如果你受得了他的話。再看看門邊的借閱登記簿:凡是離開閱覽室的東西都記在上面。一樣不落。", "Nói chuyện với Saqqet, nếu bạn chịu nổi hắn. Và xem sổ mượn cạnh cửa: mọi thứ rời khỏi phòng đọc đều được ghi vào đó. Mọi thứ.", "Bicaralah dengan Saqqet, kalau kau tahan. Dan lihat buku pinjaman di dekat pintu: semua yang keluar dari ruang baca dicatat di sana. Semuanya.", "ไปคุยกับซักเก็ตดู ถ้าทนเขาได้ แล้วไปดูสมุดบันทึกการยืมข้างประตูด้วย ทุกอย่างที่ออกจากห้องอ่านหนังสือถูกจดไว้ในนั้น ทุกอย่าง", "Dayanabilirsen Saqqet'le konuş. Bir de kapının yanındaki ödünç defterine bak: okuma salonundan çıkan her şey oraya yazılır. Her şey.", "Habla con Saqqet, si lo soportas. Y mira el registro de préstamos junto a la puerta: todo lo que sale de la sala de lectura queda anotado ahí. Todo.", "Fale com o Saqqet, se aguentar. E olhe o livro de empréstimos perto da porta: tudo o que sai da sala de leitura fica registrado nele. Tudo.", "Поговорите с Саккетом, если выдержите. И загляните в книгу выдачи у двери: всё, что покидает читальный зал, записывается туда. Всё.", "Поговоріть із Саккетом, якщо витримаєте. І зазирніть до книги видачі біля дверей: усе, що залишає читальну залу, записується туди. Усе."],
  "Ninety-nine. Still ninety-nine. I counted again.": ["九十九。まだ九十九だ。また数えた。", "아흔아홉. 여전히 아흔아홉이오. 또 세어 봤소.", "九十九。还是九十九。我又数了一遍。", "九十九。還是九十九。我又數了一遍。", "Chín mươi chín. Vẫn chín mươi chín. Tôi lại đếm rồi.", "Sembilan puluh sembilan. Masih sembilan puluh sembilan. Aku menghitung lagi.", "เก้าสิบเก้า ยังเก้าสิบเก้าอยู่ ข้านับอีกรอบแล้ว", "Doksan dokuz. Hâlâ doksan dokuz. Yine saydım.", "Noventa y nueve. Siguen siendo noventa y nueve. Las he vuelto a contar.", "Noventa e nove. Ainda noventa e nove. Contei de novo.", "Девяносто девять. Всё ещё девяносто девять. Я снова пересчитал.", "Дев'яносто дев'ять. Досі дев'яносто дев'ять. Я знову перелічив."],
  "If the Legacy has it, they'll say they always had it. That's how the oldest blood works.": ["遺統が持っているなら、ずっと自分たちのものだったと言うだろう。最古の血筋とはそういうものだ。", "유산이 그걸 가지고 있다면, 원래부터 자기들 것이었다고 하겠지. 가장 오래된 혈통이란 그런 식이오.", "要是遗脉拿到了,他们就会说那一直是他们的。最古老的血脉就是这样行事的。", "要是遺脈拿到了,他們就會說那一直是他們的。最古老的血脈就是這樣行事的。", "Nếu Di Sản có nó, họ sẽ nói nó vẫn luôn là của họ. Dòng máu lâu đời nhất là thế đấy.", "Kalau Warisan memilikinya, mereka akan bilang selalu memilikinya. Begitulah cara darah tertua bekerja.", "ถ้ามรดกออบซิเดียนได้มันไป พวกเขาก็จะบอกว่ามันเป็นของพวกเขามาตลอด สายเลือดที่เก่าแก่ที่สุดก็เป็นอย่างนี้แหละ", "Miras'taysa, hep onlarda olduğunu söyleyeceklerdir. En eski kan böyle işler.", "Si el Legado la tiene, dirán que siempre la tuvieron. Así funciona la sangre más antigua.", "Se o Legado está com ela, vão dizer que sempre esteve. É assim que o sangue mais antigo funciona.", "Если он у Наследия, они скажут, что он всегда был у них. Так уж устроена древнейшая кровь.", "Якщо він у Спадщини, вони скажуть, що він завжди був у них. Так уже влаштована найдавніша кров."],
  "The ninth leaf! The river of stars! A pedlar's basket? With lunch? Never mind. Never mind.": ["九枚目だ! 星の川だ! 行商人の籠に? 弁当と一緒に? いや、いい。もういい。", "아홉 번째 장! 별의 강! 행상의 바구니에? 점심이랑 같이? 됐소. 됐어.", "第九页!星河!在货郎的篮子里?跟午饭放在一起?算了。算了。", "第九頁!星河!在貨郎的籃子裡?跟午飯放在一起?算了。算了。", "Tờ thứ chín! Dòng sông sao! Trong giỏ của một người bán rong? Cùng với bữa trưa? Thôi. Thôi bỏ đi.", "Lembar kesembilan! Sungai bintang! Di keranjang penjaja? Bersama makan siang? Sudahlah. Sudahlah.", "แผ่นที่เก้า! แม่น้ำแห่งดวงดาว! อยู่ในตะกร้าพ่อค้าเร่? กับข้าวกลางวัน? ช่างเถอะ ช่างมันเถอะ", "Dokuzuncu yaprak! Yıldız nehri! Bir seyyar satıcının sepetinde mi? Öğle yemeğiyle mi? Boş ver. Boş ver.", "¡La novena hoja! ¡El río de estrellas! ¿En la cesta de un buhonero? ¿Con el almuerzo? Da igual. Da igual.", "A nona folha! O rio de estrelas! No cesto de um mascate? Junto com o almoço? Deixa pra lá. Deixa pra lá.", "Девятый лист! Звёздная река! В корзине коробейника? Вместе с обедом? Неважно. Неважно.", "Дев'ятий аркуш! Зоряна ріка! У кошику рознощика? Разом з обідом? Байдуже. Байдуже."],
  "Saqqet will have a copy, made by my best hand, and the Legacy can argue for the original by letter, which is how scholars should argue. Take this stole, from the Assembly: you read things before you believe them.": ["サッケトには、うちで一番腕のいい写字生が作った写しを渡そう。遺統は原本を求めて手紙で論じればいい。学者とはそうやって論じるものだ。この肩掛けを持っていきなさい。議会からだ。君は信じる前に読む人だからね。", "사케트에겐 우리 최고의 필경사가 만든 사본을 주겠소. 유산은 원본을 두고 편지로 논쟁하면 되오. 학자란 그렇게 논쟁해야 하는 법이지. 이 숄을 받으시오. 의회에서 주는 것이오. 당신은 믿기 전에 읽는 사람이니까.", "萨凯特会得到一份副本,由我手下最好的抄写员誊写;遗脉要争原件,就写信来争吧,学者本该这样争论。拿上这条披带,是议会给的:你是先读后信的人。", "薩凱特會得到一份副本,由我手下最好的抄寫員謄寫;遺脈要爭原件,就寫信來爭吧,學者本該這樣爭論。拿上這條披帶,是議會給的:你是先讀後信的人。", "Saqqet sẽ có một bản sao do người chép giỏi nhất của tôi làm, còn Di Sản cứ việc tranh cãi về bản gốc bằng thư từ, vì giới học giả nên tranh cãi như thế. Nhận lấy chiếc khăn choàng này, của Hội đồng: bạn là người đọc rồi mới tin.", "Saqqet akan mendapat salinan buatan penyalin terbaikku, dan Warisan boleh memperdebatkan yang asli lewat surat, sebagaimana seharusnya para cendekiawan berdebat. Terimalah selendang ini, dari Majelis: kau membaca dulu sebelum percaya.", "ซักเก็ตจะได้สำเนาที่อาลักษณ์ฝีมือดีที่สุดของข้าคัดลอกให้ ส่วนมรดกออบซิเดียนก็โต้แย้งเรื่องต้นฉบับทางจดหมายไป ซึ่งเป็นวิธีที่นักปราชญ์ควรโต้แย้งกัน รับผ้าคล้องผืนนี้ไป จากสภา ท่านเป็นคนที่อ่านก่อนจะเชื่อ", "Saqqet'e en iyi kâtibimin elinden bir kopya verilecek; Miras da asıl nüsha için mektupla tartışabilir, âlimler zaten böyle tartışmalı. Bu şalı al, Meclis'ten: sen bir şeye inanmadan önce okuyorsun.", "Saqqet tendrá una copia hecha por mi mejor copista, y el Legado podrá reclamar el original por carta, que es como deben discutir los eruditos. Toma esta estola, de parte de la Asamblea: tú lees las cosas antes de creértelas.", "O Saqqet vai ganhar uma cópia feita pelo meu melhor copista, e o Legado pode disputar o original por carta, que é como os estudiosos deveriam discutir. Leve esta estola, da Assembleia: você lê as coisas antes de acreditar nelas.", "Саккет получит копию, сделанную моим лучшим переписчиком, а Наследие может спорить об оригинале письмами — именно так и следует спорить учёным. Возьмите этот палантин от Собрания: вы читаете, прежде чем верить.", "Саккет отримає копію, зроблену моїм найкращим переписувачем, а Спадщина може сперечатися про оригінал листами — саме так і мають сперечатися вчені. Візьміть цей палантин від Зборів: ви читаєте, перш ніж вірити."],
  "The Archivist thinks I took it. Of course he does. If I wanted the chart, I'd want all of it, and I'd ask the Provost for it in writing, which I have, fourteen times.": ["文書官は私が盗ったと思っている。当然だろう。私が星図を欲しいなら、全部欲しい。そして学頭に書面で願い出る。実際、十四回そうした。", "서고지기는 내가 가져갔다고 생각하지. 당연히 그렇겠지. 내가 성도를 원한다면 전부를 원할 테고, 학장에게 서면으로 요청하겠지. 실제로 열네 번이나 그랬소.", "档案官认为是我拿的。他当然会这么想。如果我想要星图,我会要整张,而且会向院长书面申请,我已经申请过十四次了。", "檔案官認為是我拿的。他當然會這麼想。如果我想要星圖,我會要整張,而且會向院長書面申請,我已經申請過十四次了。", "Người giữ văn khố nghĩ tôi lấy nó. Dĩ nhiên ông ta nghĩ thế. Nếu tôi muốn tấm bản đồ, tôi sẽ muốn cả tấm, và tôi sẽ xin Viện trưởng bằng văn bản, mà tôi đã xin rồi, mười bốn lần.", "Arsiparis mengira aku yang mengambilnya. Tentu saja. Kalau aku menginginkan peta itu, aku akan menginginkan seluruhnya, dan aku akan memintanya kepada Provos secara tertulis, yang sudah kulakukan, empat belas kali.", "บรรณารักษ์คิดว่าข้าเอาไป แน่ล่ะ เขาต้องคิดอย่างนั้น ถ้าข้าต้องการแผนที่ดาว ข้าจะต้องการทั้งหมด และจะยื่นขอต่ออธิการเป็นลายลักษณ์อักษร ซึ่งข้าก็ทำไปแล้ว สิบสี่ครั้ง", "Arşivci benim aldığımı düşünüyor. Elbette düşünür. Haritayı isteseydim tamamını isterdim ve Rektör'den yazılı olarak talep ederdim; ki ettim, on dört kez.", "El archivero cree que me la llevé yo. Claro que lo cree. Si quisiera la carta, la querría entera, y se la pediría a la prebostesa por escrito, cosa que he hecho, catorce veces.", "O arquivista acha que fui eu. É claro que acha. Se eu quisesse o mapa, ia querer ele inteiro, e pediria à reitora por escrito, o que já fiz, catorze vezes.", "Архивариус думает, что это я взял. Конечно, думает. Если бы мне нужна была карта, мне нужна была бы вся, и я попросил бы её у провоста письменно, что я и сделал, четырнадцать раз.", "Архіваріус думає, що це я взяв. Звісно, думає. Якби мені потрібна була мапа, мені потрібна була б уся, і я попросив би її в провоста письмово, що я й зробив, чотирнадцять разів."],
  "The ninth leaf was bound in lapis thread, as Tamesh binds. The others are in cotton. Somebody here rebound it, once. Somebody here knows bookbinders.": ["九枚目は瑠璃色の糸で綴じられていた。タメシュの綴じ方だ。他は木綿糸だ。ここの誰かが、かつて綴じ直したのだ。ここの誰かが製本師を知っている。", "아홉 번째 장은 청금석 빛 실로 묶여 있었소. 타메시식 제본이지. 나머지는 무명실이오. 여기 누군가가 언젠가 그걸 다시 묶은 거요. 여기 누군가는 제본사를 안다는 뜻이지.", "第九页是用青金石色的线装订的,那是塔梅什的装法。其他页用的是棉线。这里有人曾经重新装订过它。这里有人认识装订匠。", "第九頁是用青金石色的線裝訂的,那是塔梅什的裝法。其他頁用的是棉線。這裡有人曾經重新裝訂過它。這裡有人認識裝訂匠。", "Tờ thứ chín được đóng bằng chỉ màu lưu ly, kiểu đóng của Tamesh. Các tờ khác bằng chỉ bông. Ai đó ở đây đã từng đóng lại nó. Ai đó ở đây quen thợ đóng sách.", "Lembar kesembilan dijilid dengan benang lapis, cara Tamesh menjilid. Yang lain dengan benang katun. Seseorang di sini pernah menjilidnya ulang. Seseorang di sini kenal tukang jilid.", "แผ่นที่เก้าเย็บด้วยด้ายสีลาพิส แบบที่ทาเมชเย็บเล่ม แผ่นอื่นเย็บด้วยด้ายฝ้าย มีใครสักคนที่นี่เคยเย็บเล่มมันใหม่ มีใครสักคนที่นี่รู้จักช่างเย็บเล่ม", "Dokuzuncu yaprak, Tamesh usulü, lacivert taşı renkli iplikle ciltlenmişti. Ötekiler pamuk iplikle. Buradan biri onu bir zamanlar yeniden ciltletmiş. Buradan biri ciltçi tanıyor.", "La novena hoja estaba encuadernada con hilo de lapislázuli, como encuaderna Tamesh. Las demás, con algodón. Alguien de aquí la reencuadernó una vez. Alguien de aquí conoce a encuadernadores.", "A nona folha era costurada com fio de lápis-lazúli, como Tamesh encaderna. As outras são de algodão. Alguém daqui a reencadernou, uma vez. Alguém daqui conhece encadernadores.", "Девятый лист был сшит лазуритовой нитью, как переплетают в Тамеше. Остальные — хлопковой. Кто-то здесь однажды его переплёл заново. Кто-то здесь знает переплётчиков.", "Дев'ятий аркуш був зшитий лазуритовою ниткою, як оправляють у Тамеші. Решта — бавовняною. Хтось тут колись його переоправив. Хтось тут знає палітурників."],
  "A leaf of old writing? Stars on it? I might. Under the lunch. It came to me from a young librarian on his way to Khetmar, who needed travelling money more than he needed stars.": ["古い文字の書かれた一枚? 星が描いてある? あるかもね。弁当の下に。ケトマルへ向かう若い司書から回ってきたんだ。そいつは星より路銀のほうが要りようでね。", "옛 글씨가 적힌 종이 한 장? 별이 그려진? 있을지도 모르지. 점심 도시락 밑에. 케트마르로 가던 젊은 사서한테서 들어왔어. 별보다 노잣돈이 더 급했던 친구였지.", "一页古书?上面有星星?也许有吧。在午饭底下。是一个去克特马尔的年轻图书管理员给我的,比起星星,他更需要盘缠。", "一頁古書?上面有星星?也許有吧。在午飯底下。是一個去克特馬爾的年輕圖書管理員給我的,比起星星,他更需要盤纏。", "Một tờ chữ cổ? Có vẽ sao? Có thể có đấy. Dưới bữa trưa. Nó đến tay tôi từ một cậu thủ thư trẻ đang trên đường tới Khetmar, cậu ta cần tiền lộ phí hơn là cần sao.", "Selembar tulisan kuno? Ada bintangnya? Mungkin ada. Di bawah makan siang. Aku dapat dari pustakawan muda yang sedang menuju Khetmar, yang lebih butuh ongkos jalan daripada bintang.", "กระดาษเขียนอักษรโบราณแผ่นหนึ่ง? มีรูปดาว? อาจจะมีนะ อยู่ใต้ข้าวกลางวัน ได้มาจากบรรณารักษ์หนุ่มคนหนึ่งที่กำลังไปเคทมาร์ เขาต้องการเงินค่าเดินทางมากกว่าดวงดาว", "Eski yazılı bir yaprak mı? Üstünde yıldızlar mı? Olabilir. Öğle yemeğinin altında. Khetmar'a giden genç bir kütüphaneciden geldi; yıldızlardan çok yol parasına ihtiyacı vardı.", "¿Una hoja de escritura antigua? ¿Con estrellas? Puede ser. Debajo del almuerzo. Me llegó de un joven bibliotecario que iba camino de Khetmar y que necesitaba dinero para el viaje más que estrellas.", "Uma folha de escrita antiga? Com estrelas? Pode ser. Debaixo do almoço. Veio de um jovem bibliotecário a caminho de Khetmar, que precisava mais de dinheiro para a viagem do que de estrelas.", "Лист со старыми письменами? Со звёздами? Может, и есть. Под обедом. Достался мне от молодого библиотекаря, что ехал в Кетмар: деньги на дорогу были ему нужнее звёзд.", "Аркуш зі старими письменами? Із зірками? Може, і є. Під обідом. Дістався мені від молодого бібліотекаря, що їхав до Кетмара: гроші на дорогу були йому потрібніші за зірки."],
  "The Archive wants it back? Then the Archive can have it. I'm a pedlar, not a fool: the Assembly has long arms and longer memories.": ["文書館が返してほしいって? なら文書館にくれてやるよ。俺は行商人で、馬鹿じゃない。議会は腕が長くて、記憶はもっと長いからね。", "서고에서 돌려 달라고? 그럼 서고가 가져가면 되지. 난 행상이지 바보가 아니야. 의회는 팔이 길고 기억은 더 길거든.", "档案馆想要回去?那就给档案馆好了。我是货郎,不是傻子:议会的手伸得长,记性更长。", "檔案館想要回去?那就給檔案館好了。我是貨郎,不是傻子:議會的手伸得長,記性更長。", "Văn khố muốn lấy lại à? Vậy thì Văn khố cứ lấy. Tôi là người bán rong, đâu phải kẻ ngốc: Hội đồng tay dài, mà trí nhớ còn dài hơn.", "Arsip mau mengambilnya kembali? Ya sudah, ambil saja. Aku penjaja, bukan orang bodoh: Majelis tangannya panjang dan ingatannya lebih panjang lagi.", "หอจดหมายเหตุอยากได้คืนหรือ งั้นก็เอาไปเถอะ ข้าเป็นพ่อค้าเร่ ไม่ใช่คนโง่ สภามีมือยาว และความจำยาวกว่านั้นอีก", "Arşiv geri mi istiyor? O zaman Arşiv alsın. Ben seyyar satıcıyım, aptal değilim: Meclis'in kolları uzun, hafızası daha da uzundur.", "¿El Archivo la quiere de vuelta? Pues que se la quede el Archivo. Soy buhonero, no tonto: la Asamblea tiene los brazos largos y la memoria más larga aún.", "O Arquivo quer de volta? Então o Arquivo pode ficar com ela. Sou mascate, não bobo: a Assembleia tem braços longos e memória mais longa ainda.", "Архив хочет его назад? Пусть забирает. Я коробейник, а не дурак: у Собрания руки длинные, а память ещё длиннее.", "Архів хоче його назад? Хай забирає. Я рознощик, а не дурень: у Зборів руки довгі, а пам'ять ще довша."],
  "Pedlar Chandu gave you the missing folio. Take it back to Archivist Mahir.": ["行商人チャンドゥが失われた一葉を渡してくれた。文書官マヒルのもとへ持ち帰ろう。", "행상 찬두가 사라진 낱장을 건네주었다. 서고지기 마히르에게 가져가자.", "货郎钱杜把缺失的书页交给了你。把它带回去交给档案官马希尔。", "貨郎錢杜把缺失的書頁交給了你。把它帶回去交給檔案官馬希爾。", "Người bán rong Chandu đã đưa cho bạn tờ bị mất. Hãy mang nó về cho Người giữ văn khố Mahir.", "Penjaja Chandu memberimu lembar yang hilang. Bawa kembali kepada Arsiparis Mahir.", "พ่อค้าเร่จันทุมอบแผ่นที่หายไปให้คุณแล้ว นำมันกลับไปให้บรรณารักษ์มาฮีร์", "Seyyar satıcı Chandu sana kayıp yaprağı verdi. Onu Arşivci Mahir'e geri götür.", "El buhonero Chandu te ha dado el folio perdido. Llévaselo al archivero Mahir.", "O mascate Chandu lhe deu o fólio perdido. Leve-o de volta ao arquivista Mahir.", "Коробейник Чанду отдал вам пропавший лист. Отнесите его архивариусу Махиру.", "Рознощик Чанду віддав вам зниклий аркуш. Віднесіть його архіваріусу Махіру."],
  "Sit. Tea. Now: the loggers from Shailagarh have moved the stones round our grove and cut inside them, three great trees, older than Shailagarh's walls.": ["お座り。お茶をどうぞ。さて。シャイラガルの木こりたちが、わたしらの聖林を囲む石を動かして、その内側で木を伐ったのさ。大木を三本。シャイラガルの城壁より古い木をね。", "앉게. 차 들고. 자, 샤일라가르의 벌목꾼들이 우리 숲을 두른 돌들을 옮기고 그 안쪽을 베어 냈다네. 큰 나무 세 그루를. 샤일라가르의 성벽보다 오래된 나무들을.", "坐。喝茶。好了:沙伊拉加尔来的伐木工挪走了围着我们圣林的界石,在里面砍了树,三棵大树,比沙伊拉加尔的城墙还老。", "坐。喝茶。好了:沙伊拉加爾來的伐木工挪走了圍著我們聖林的界石,在裡面砍了樹,三棵大樹,比沙伊拉加爾的城牆還老。", "Ngồi đi. Uống trà. Giờ thì: bọn tiều phu từ Shailagarh đã dời những phiến đá quanh rừng thiêng của chúng ta và đốn cây bên trong, ba cây lớn, già hơn cả tường thành Shailagarh.", "Duduk. Minum teh. Nah: para penebang dari Shailagarh memindahkan batu-batu di sekeliling hutan keramat kami dan menebang di dalamnya, tiga pohon besar, lebih tua dari tembok Shailagarh.", "นั่งสิ ดื่มชา เอาล่ะ พวกคนตัดไม้จากไศลครห์ย้ายหินที่ล้อมป่าศักดิ์สิทธิ์ของเรา แล้วตัดต้นไม้ข้างใน ต้นใหญ่สามต้น แก่กว่ากำแพงของไศลครห์เสียอีก", "Otur. Çay iç. Şimdi: Shailagarh'ın oduncuları korumuzun çevresindeki taşları yerinden oynatıp içeride ağaç kesmişler; Shailagarh'ın surlarından yaşlı üç koca ağaç.", "Siéntate. Té. Y ahora: los leñadores de Shailagarh han movido las piedras que rodean nuestra arboleda y han talado dentro, tres árboles enormes, más viejos que las murallas de Shailagarh.", "Sente-se. Chá. Agora: os lenhadores de Shailagarh mudaram as pedras em volta do nosso bosque e cortaram lá dentro, três árvores enormes, mais velhas que as muralhas de Shailagarh.", "Садитесь. Чаю. Итак: лесорубы из Шайлагарха передвинули камни вокруг нашей рощи и рубили внутри — три огромных дерева, старше стен Шайлагарха.", "Сідайте. Чаю. Отже: лісоруби з Шайлагарха пересунули камені довкола нашого гаю й рубали всередині — три величезні дерева, старші за стіни Шайлагарха."],
  "I won't fight Shailagarh. I want the stones back where they were, and the paper that moved them taken back to the lord who signed it.": ["シャイラガルと争う気はないよ。石を元の場所に戻して、石を動かしたあの紙切れを、署名した領主のところへ突き返してほしいのさ。", "샤일라가르와 싸우진 않겠네. 돌들이 제자리로 돌아오길, 그리고 그 돌들을 옮기게 한 종이가 거기 서명한 영주에게 되돌아가길 바랄 뿐이야.", "我不会跟沙伊拉加尔打仗。我要界石回到原来的地方,还要把那张挪动界石的纸,退还给签字的那位大人。", "我不會跟沙伊拉加爾打仗。我要界石回到原來的地方,還要把那張挪動界石的紙,退還給簽字的那位大人。", "Ta sẽ không đánh nhau với Shailagarh. Ta muốn những phiến đá trở về chỗ cũ, và tờ giấy đã dời chúng đi được trả về cho vị lãnh chúa đã ký nó.", "Aku tak akan melawan Shailagarh. Aku ingin batu-batu itu kembali ke tempatnya, dan kertas yang memindahkannya dikembalikan kepada tuan yang menandatanganinya.", "ข้าจะไม่สู้กับไศลครห์หรอก ข้าแค่อยากให้หินกลับไปอยู่ที่เดิม และให้กระดาษที่ทำให้มันถูกย้ายถูกส่งคืนไปให้ท่านเจ้าเมืองที่ลงนามมัน", "Shailagarh'la savaşmayacağım. Taşların eski yerlerine dönmesini, onları yerinden oynatan kâğıdın da onu imzalayan lorda geri götürülmesini istiyorum.", "No pelearé con Shailagarh. Quiero las piedras donde estaban, y que el papel que las movió vuelva al señor que lo firmó.", "Não vou brigar com Shailagarh. Quero as pedras de volta onde estavam, e o papel que as tirou de lá devolvido ao senhor que o assinou.", "Я не стану воевать с Шайлагархом. Я хочу, чтобы камни вернулись на место, а бумагу, которая их сдвинула, отнесли обратно лорду, что её подписал.", "Я не воюватиму з Шайлагархом. Я хочу, щоб камені повернулися на місце, а папір, що їх зсунув, віднесли назад лордові, який його підписав."],
  "The grove is west of here, along the river. The stones are carved with a leaf; you'll find them by the stumps. Talk to the loggers too: they're not wicked, only paid.": ["聖林はここから西、川沿いだよ。石には葉っぱが彫ってある。切り株のそばで見つかるさ。木こりたちとも話してごらん。悪人じゃない、金で雇われているだけさ。", "숲은 여기서 서쪽, 강을 따라가면 있네. 돌에는 잎사귀가 새겨져 있지. 그루터기 옆에서 찾을 수 있을 거야. 벌목꾼들과도 이야기해 보게. 나쁜 자들이 아니야. 그저 돈을 받았을 뿐이지.", "圣林在这里往西,沿着河走。界石上刻着一片叶子,你会在树桩旁边找到它们。也跟伐木工谈谈:他们不坏,只是拿了钱。", "聖林在這裡往西,沿著河走。界石上刻著一片葉子,你會在樹樁旁邊找到它們。也跟伐木工談談:他們不壞,只是拿了錢。", "Rừng thiêng ở phía tây đây, dọc theo sông. Những phiến đá có khắc hình chiếc lá; cháu sẽ tìm thấy chúng cạnh mấy gốc cây. Nói chuyện với bọn tiều phu nữa: chúng không độc ác, chỉ là được trả tiền thôi.", "Hutan keramat ada di barat dari sini, menyusuri sungai. Batu-batunya berukir daun; kau akan menemukannya di dekat tunggul-tunggul. Bicara juga dengan para penebang: mereka tidak jahat, cuma dibayar.", "ป่าศักดิ์สิทธิ์อยู่ทางตะวันตกจากที่นี่ เลียบแม่น้ำไป หินพวกนั้นสลักรูปใบไม้ไว้ เจ้าจะเจอมันอยู่ข้างตอไม้ ไปคุยกับพวกคนตัดไม้ด้วยนะ พวกเขาไม่ได้ชั่วร้าย แค่ได้รับค่าจ้าง", "Koru buranın batısında, nehir boyunca. Taşlara yaprak oyulmuş; onları kütüklerin yanında bulursun. Oduncularla da konuş: kötü değiller, sadece para alıyorlar.", "La arboleda está al oeste de aquí, siguiendo el río. Las piedras tienen una hoja tallada; las encontrarás junto a los tocones. Habla también con los leñadores: no son malvados, solo cobran.", "O bosque fica a oeste daqui, seguindo o rio. As pedras têm uma folha entalhada; você vai achá-las perto dos tocos. Fale com os lenhadores também: não são maus, só são pagos.", "Роща к западу отсюда, вдоль реки. На камнях вырезан лист; найдёте их у пней. Поговорите и с лесорубами: они не злодеи, им просто платят.", "Гай на захід звідси, уздовж річки. На каменях вирізьблено листок; знайдете їх біля пнів. Поговоріть і з лісорубами: вони не лиходії, їм просто платять."],
  "The stones first, then the paper. A forest is patient, but it isn't infinitely patient.": ["まず石、それから紙だよ。森は辛抱強いけれど、限りなく辛抱強いわけじゃない。", "돌 먼저, 그다음이 종이야. 숲은 인내심이 있지만, 끝없이 있는 건 아니라네.", "先是界石,然后是那张纸。森林很有耐心,但耐心不是无穷的。", "先是界石,然後是那張紙。森林很有耐心,但耐心不是無窮的。", "Đá trước, rồi mới đến tờ giấy. Rừng thì kiên nhẫn, nhưng không kiên nhẫn vô hạn đâu.", "Batu dulu, baru kertasnya. Hutan itu sabar, tapi kesabarannya tidak tanpa batas.", "หินก่อน แล้วค่อยกระดาษ ป่านั้นอดทน แต่ก็ไม่ได้อดทนไปได้ไม่มีที่สิ้นสุด", "Önce taşlar, sonra kâğıt. Orman sabırlıdır, ama sabrı sonsuz değildir.", "Primero las piedras, luego el papel. Un bosque es paciente, pero no infinitamente paciente.", "Primeiro as pedras, depois o papel. A floresta é paciente, mas não infinitamente paciente.", "Сначала камни, потом бумага. Лес терпелив, но не бесконечно.", "Спершу камені, потім папір. Ліс терплячий, але не безмежно."],
  "The trees hold the riverbank. Cut them and the bank comes down to Sarovan as mud, and the Queen sends someone to count us.": ["木々が川岸を支えているのさ。伐れば岸は泥になってサロヴァンまで流れていく。そうなれば女王がわたしらを数えに誰かをよこすだろうよ。", "나무들이 강둑을 붙들고 있다네. 베어 버리면 강둑이 진흙이 되어 사로반까지 흘러가고, 그러면 여왕이 우리를 세러 누군가를 보내겠지.", "是这些树护着河岸。砍了它们,河岸就会化作泥浆冲到萨罗万,然后女王就会派人来清点我们。", "是這些樹護著河岸。砍了它們,河岸就會化作泥漿沖到薩羅萬,然後女王就會派人來清點我們。", "Cây giữ bờ sông. Đốn chúng đi thì bờ sông sẽ trôi xuống Sarovan thành bùn, và Nữ hoàng sẽ phái người tới đếm chúng ta.", "Pohon-pohon itu menahan tepi sungai. Tebang mereka, tepi sungai akan longsor ke Sarovan jadi lumpur, lalu Ratu mengirim orang untuk menghitung kami.", "ต้นไม้พวกนั้นยึดตลิ่งไว้ ตัดมันทิ้งเมื่อไร ตลิ่งก็จะไหลลงไปถึงสโรวันกลายเป็นโคลน แล้วราชินีก็จะส่งคนมานับหัวพวกเรา", "Ağaçlar nehir kıyısını tutuyor. Onları kesersen kıyı çamur olup Sarovan'a iner, Kraliçe de bizi saymak için birini yollar.", "Los árboles sujetan la orilla del río. Si los talas, la orilla baja hasta Sarovan hecha barro, y la Reina manda a alguien a contarnos.", "As árvores seguram a margem do rio. Corte-as e a margem desce até Sarovan como lama, e a Rainha manda alguém para nos contar.", "Деревья держат берег реки. Срубите их, и берег грязью сползёт к Саровану, а королева пришлёт кого-нибудь пересчитать нас.", "Дерева тримають берег річки. Зрубайте їх, і берег багном сповзе до Сарована, а королева пришле когось перелічити нас."],
  "The lord tore it up? Himself? Then Shailagarh remembers what it said, today.": ["領主が破ったのかい? 自分の手で? なら今日のところは、シャイラガルも自分の言ったことを覚えているわけだ。", "영주가 찢었다고? 손수? 그렇다면 오늘은 샤일라가르가 자기가 한 말을 기억하는 모양이군.", "那位大人撕了?亲手撕的?那么今天,沙伊拉加尔记得自己说过什么了。", "那位大人撕了?親手撕的?那麼今天,沙伊拉加爾記得自己說過什麼了。", "Lãnh chúa xé nó rồi à? Tự tay ư? Vậy thì hôm nay Shailagarh nhớ mình đã nói gì.", "Tuan itu merobeknya? Sendiri? Kalau begitu Shailagarh ingat apa yang diucapkannya, hari ini.", "ท่านเจ้าเมืองฉีกมันเองหรือ ด้วยมือตัวเอง? งั้นวันนี้ไศลครห์ก็จำได้ว่าพูดอะไรไว้", "Lord yırttı mı? Kendisi mi? Demek Shailagarh bugün ne dediğini hatırlıyor.", "¿El señor la rompió? ¿Él mismo? Entonces Shailagarh se acuerda de lo que dijo, hoy.", "O senhor rasgou? Ele mesmo? Então Shailagarh se lembra do que disse, hoje.", "Лорд порвал её? Сам? Значит, сегодня Шайлагарх помнит, что говорил.", "Лорд порвав її? Сам? Отже, сьогодні Шайлагарх пам'ятає, що казав."],
  "Take this charm: seeds of the grove trees, strung. If you plant one where you were born, something of the Deepgreen will grow there. Probably bamboo. Bamboo grows anywhere.": ["このお守りを持っておいき。聖林の木々の種を糸に通したものさ。生まれた土地にひとつ植えれば、深緑の森の何かがそこに育つ。たぶん竹だね。竹はどこにでも生えるから。", "이 부적을 가져가게. 숲 나무들의 씨앗을 꿰어 만든 거라네. 자네가 태어난 곳에 하나를 심으면, 깊은초록 숲의 무언가가 거기서 자랄 거야. 아마 대나무겠지. 대나무는 어디서나 자라니까.", "拿着这个护身符:是用圣林树木的种子串起来的。你要是在出生的地方种下一颗,深绿林的某样东西就会在那里生长。多半是竹子。竹子在哪儿都能长。", "拿著這個護身符:是用聖林樹木的種子串起來的。你要是在出生的地方種下一顆,深綠林的某樣東西就會在那裡生長。多半是竹子。竹子在哪兒都能長。", "Cầm lấy lá bùa này: hạt của những cây trong rừng thiêng, xâu thành chuỗi. Nếu cháu gieo một hạt ở nơi cháu sinh ra, một chút gì đó của Rừng Thẳm Xanh sẽ mọc lên ở đó. Chắc là tre. Tre mọc ở đâu cũng được.", "Ambil jimat ini: biji pohon-pohon hutan keramat, dironce. Kalau kau tanam satu di tempat kelahiranmu, sesuatu dari Rimba Hijau Pekat akan tumbuh di sana. Mungkin bambu. Bambu tumbuh di mana saja.", "รับเครื่องรางนี้ไป เมล็ดของต้นไม้ในป่าศักดิ์สิทธิ์ร้อยเป็นพวง ถ้าเจ้าปลูกสักเมล็ดในที่ที่เจ้าเกิด อะไรบางอย่างของป่าเขียวลึกจะงอกขึ้นที่นั่น คงเป็นไผ่ ไผ่ขึ้นได้ทุกที่", "Bu muskayı al: koru ağaçlarının tohumları, ipe dizilmiş. Doğduğun yere birini dikersen, orada Derin Yeşillik'ten bir şey yetişir. Muhtemelen bambu. Bambu her yerde yetişir.", "Toma este amuleto: semillas de los árboles de la arboleda, ensartadas. Si plantas una donde naciste, algo del Verdor Profundo crecerá allí. Seguramente bambú. El bambú crece en cualquier parte.", "Leve este amuleto: sementes das árvores do bosque, enfiadas num cordão. Se plantar uma onde você nasceu, algo do Verde Profundo vai crescer lá. Provavelmente bambu. Bambu cresce em qualquer lugar.", "Возьмите этот оберег: семена деревьев рощи на нитке. Если посадите одно там, где родились, там вырастет что-то от Глубокой Зелени. Скорее всего, бамбук. Бамбук растёт где угодно.", "Візьміть цей оберіг: насіння дерев гаю на нитці. Якщо посадите одне там, де народилися, там виросте щось від Глибокої Зелені. Найпевніше, бамбук. Бамбук росте будь-де."],
  "The grove stones? We moved them. The licence says pit props from the Deepgreen, it doesn't say round any stones. Shailagarh's lord signed it; take it up with him.": ["聖林の石? 動かしたよ。許可状には深緑の森から坑木を、と書いてあるが、石をよけろとは書いてない。署名したのはシャイラガルの領主だ。文句ならあっちに言ってくれ。", "숲의 경계석? 우리가 옮겼지. 허가증엔 깊은초록 숲에서 갱목을 베라고 돼 있지, 돌을 피해서 베라곤 안 돼 있어. 샤일라가르 영주가 서명했으니, 따지려면 그분한테 따져.", "圣林界石?是我们挪的。许可证上写的是从深绿林取矿坑支柱,可没写要绕开什么石头。签字的是沙伊拉加尔的大人,有意见找他去。", "聖林界石?是我們挪的。許可證上寫的是從深綠林取礦坑支柱,可沒寫要繞開什麼石頭。簽字的是沙伊拉加爾的大人,有意見找他去。", "Đá rừng thiêng hả? Bọn tôi dời đấy. Giấy phép ghi là lấy cột chống hầm mỏ từ Rừng Thẳm Xanh, đâu có ghi là phải tránh đá nào. Lãnh chúa Shailagarh ký nó; có gì thì đi mà nói với ông ấy.", "Batu hutan keramat? Kami yang memindahkannya. Izinnya bilang penyangga tambang dari Rimba Hijau Pekat, tidak bilang harus memutari batu apa pun. Tuan Shailagarh yang menandatanganinya; urus saja dengan dia.", "หินเขตป่าศักดิ์สิทธิ์น่ะหรือ พวกเราย้ายเอง ใบอนุญาตเขียนว่าให้เอาไม้ค้ำเหมืองจากป่าเขียวลึก ไม่ได้เขียนว่าต้องเลี่ยงหินอะไร ท่านเจ้าเมืองไศลครห์เป็นคนลงนาม ไปว่ากับท่านเอาเอง", "Koru taşları mı? Biz oynattık. İzinde Derin Yeşillik'ten maden direği diyor, taşların çevresinden demiyor. Shailagarh'ın lordu imzaladı; derdin varsa onunla konuş.", "¿Las piedras de la arboleda? Las movimos nosotros. La licencia dice puntales del Verdor Profundo, no dice nada de rodear piedras. La firmó el señor de Shailagarh; ve a quejarte a él.", "As pedras do bosque? Fomos nós que mudamos. A licença diz escoras do Verde Profundo, não diz nada de contornar pedra nenhuma. O senhor de Shailagarh assinou; vá reclamar com ele.", "Камни рощи? Мы их сдвинули. В лицензии сказано: крепи из Глубокой Зелени, а про обход каких-то камней ни слова. Подписал её лорд Шайлагарха; с ним и разбирайтесь.", "Камені гаю? Ми їх зсунули. У ліцензії сказано: кріплення з Глибокої Зелені, а про обхід якихось каменів ані слова. Підписав її лорд Шайлагарха; з ним і розбирайтеся."],
  "Put them back if you like. We'll only cut where the licence says, and the licence says everywhere.": ["戻したけりゃ戻せばいい。俺たちは許可状にある場所でしか伐らない。で、許可状には「どこでも」とある。", "돌려놓고 싶으면 돌려놔. 우린 허가증에 적힌 곳에서만 벨 테니까. 그런데 허가증엔 '어디서나'라고 적혀 있거든.", "想放回去就放吧。我们只在许可证上写的地方砍,而许可证上写的是:哪儿都行。", "想放回去就放吧。我們只在許可證上寫的地方砍,而許可證上寫的是:哪兒都行。", "Muốn đặt lại thì cứ việc. Bọn tôi chỉ đốn ở chỗ giấy phép ghi, mà giấy phép thì ghi là khắp nơi.", "Kembalikan saja kalau mau. Kami cuma menebang di tempat yang disebut izin, dan izin menyebut di mana-mana.", "จะเอากลับไปวางก็ตามใจ พวกเราจะตัดเฉพาะที่ที่ใบอนุญาตระบุเท่านั้น และใบอนุญาตระบุว่าทุกที่", "İstersen geri koy. Biz yalnızca iznin dediği yerde keseriz; izin de her yer diyor.", "Vuelve a ponerlas si quieres. Solo talaremos donde diga la licencia, y la licencia dice en todas partes.", "Recoloque se quiser. Só vamos cortar onde a licença manda, e a licença manda em todo lugar.", "Ставьте обратно, если хотите. Мы рубим только там, где сказано в лицензии, а в лицензии сказано: везде.", "Ставте назад, якщо хочете. Ми рубаємо лише там, де сказано в ліцензії, а в ліцензії сказано: скрізь."],
  "You want the licence? Take it to the lord, then. If he draws a new one, we'll cut where the new one says. We're loggers, not lawyers.": ["許可状が欲しい? なら領主のところへ持っていきな。新しいのを書いてくれたら、俺たちは新しいのに書いてある所を伐る。俺たちは木こりで、法律家じゃないんでね。", "허가증이 필요하다고? 그럼 영주한테 가져가. 새로 써 주시면 우린 새 허가증에 적힌 데를 베지. 우린 벌목꾼이지 법률가가 아니야.", "你要许可证?那就拿去找大人吧。他要是另立一张,我们就照新的上面写的地方砍。我们是伐木工,又不是讼师。", "你要許可證?那就拿去找大人吧。他要是另立一張,我們就照新的上面寫的地方砍。我們是伐木工,又不是訟師。", "Muốn lấy giấy phép à? Vậy thì mang tới cho lãnh chúa đi. Nếu ông ấy viết tờ mới, bọn tôi sẽ đốn chỗ tờ mới ghi. Bọn tôi là tiều phu, đâu phải thầy kiện.", "Kau mau izinnya? Bawa saja ke tuan itu. Kalau dia membuat yang baru, kami akan menebang di tempat yang disebut izin baru. Kami penebang kayu, bukan ahli hukum.", "อยากได้ใบอนุญาตหรือ งั้นก็เอาไปให้ท่านเจ้าเมืองสิ ถ้าท่านเขียนใบใหม่ พวกเราก็จะตัดตามที่ใบใหม่ระบุ พวกเราเป็นคนตัดไม้ ไม่ใช่นักกฎหมาย", "İzni mi istiyorsun? O zaman lorda götür. Yenisini çizerse yenisinin dediği yerde keseriz. Biz oduncuyuz, avukat değil.", "¿Quieres la licencia? Pues llévasela al señor. Si redacta una nueva, talaremos donde diga la nueva. Somos leñadores, no abogados.", "Quer a licença? Então leve ao senhor. Se ele fizer uma nova, a gente corta onde a nova mandar. Somos lenhadores, não advogados.", "Нужна лицензия? Тогда несите её лорду. Если он выпишет новую, будем рубить там, где скажет новая. Мы лесорубы, а не законники.", "Потрібна ліцензія? Тоді несіть її лордові. Якщо він випише нову, рубатимемо там, де скаже нова. Ми лісоруби, а не законники."],
  "Red Jhanda is dead. The caravan can go through the Gate of Rains: meet it at Tirthali.": ["赤のジャンダは死んだ。隊商は雨の門を通れる。ティルタリで落ち合おう。", "붉은 잔다가 죽었다. 이제 대상은 비의 문을 지날 수 있다. 티르탈리에서 대상을 맞이하자.", "红詹达死了。商队可以穿过雨之门了:去提尔塔利与它会合。", "紅詹達死了。商隊可以穿過雨之門了:去提爾塔利與它會合。", "Jhanda Đỏ đã chết. Đoàn buôn có thể đi qua Cổng Mưa: hãy gặp họ ở Tirthali.", "Jhanda Merah sudah mati. Karavan bisa melewati Gerbang Hujan: temui mereka di Tirthali.", "ชัณฑาแดงตายแล้ว กองคาราวานผ่านประตูแห่งสายฝนได้แล้ว ไปพบกันที่ตีรถลี", "Kızıl Jhanda öldü. Kervan Yağmur Kapısı'ndan geçebilir: onu Tirthali'de karşıla.", "Jhanda el Rojo ha muerto. La caravana puede cruzar la Puerta de las Lluvias: reúnete con ella en Tirthali.", "Jhanda Vermelho está morto. A caravana pode passar pelo Portão das Chuvas: encontre-a em Tirthali.", "Красный Джханда мёртв. Караван может пройти через Врата Дождей: встретьте его в Тиртхали.", "Червоний Джханда мертвий. Караван може пройти крізь Браму Дощів: зустріньте його в Тіртхалі."],
  "The Monsoon Serpent sinks into the cistern and doesn't rise. The sluice wheel is free to turn.": ["雨季の大蛇は貯水槽に沈み、浮かんでこない。水門の輪はもう回せる。", "몬순 큰뱀이 저수조 속으로 가라앉아 다시 떠오르지 않는다. 이제 수문 바퀴를 돌릴 수 있다.", "季风之蛇沉入蓄水窖,再没浮上来。水闸轮可以转动了。", "季風之蛇沉入蓄水窖,再沒浮上來。水閘輪可以轉動了。", "Mãng Xà Gió Mùa chìm xuống bể chứa và không nổi lên nữa. Bánh xe cửa cống đã có thể xoay.", "Ular Monsun tenggelam ke dalam bak penampung dan tak muncul lagi. Roda pintu air kini bebas diputar.", "อสรพิษมรสุมจมลงสู่บ่อเก็บน้ำและไม่โผล่ขึ้นมาอีก วงล้อประตูระบายน้ำหมุนได้แล้ว", "Muson Yılanı sarnıca gömülüyor ve bir daha yükselmiyor. Savak çarkı artık dönebilir.", "La Serpiente del Monzón se hunde en la cisterna y no vuelve a salir. La rueda de la compuerta ya puede girar.", "A Serpente da Monção afunda na cisterna e não volta à tona. A roda da comporta está livre para girar.", "Муссонный змей погружается в цистерну и больше не всплывает. Колесо шлюза теперь можно повернуть.", "Мусонний змій занурюється в цистерну й більше не випливає. Колесо шлюзу тепер можна повернути."],
  "Sergeant Hask is dead. Tell Lord Varanjit what the paybook said.": ["ハスク軍曹は死んだ。給金帳に書かれていたことをヴァランジット卿に伝えよう。", "하스크 하사가 죽었다. 급료 장부에 적힌 내용을 바란지트 경에게 알리자.", "哈斯克中士死了。把饷册上写的告诉瓦兰吉特大人。", "哈斯克中士死了。把餉冊上寫的告訴瓦蘭吉特大人。", "Trung sĩ Hask đã chết. Hãy báo cho Lãnh chúa Varanjit những gì sổ lương ghi.", "Sersan Hask sudah mati. Beri tahu Tuan Varanjit apa isi buku gaji itu.", "จ่าฮาสก์ตายแล้ว ไปบอกท่านวรัญชิตว่าสมุดบัญชีเงินเดือนเขียนไว้ว่าอย่างไร", "Çavuş Hask öldü. Maaş defterinde yazanları Lord Varanjit'e anlat.", "El sargento Hask ha muerto. Cuéntale al señor Varanjit lo que decía el libro de pagas.", "O sargento Hask está morto. Conte ao senhor Varanjit o que dizia o livro de soldos.", "Сержант Хаск мёртв. Расскажите лорду Варанджиту, что было в платёжной книге.", "Сержант Хаск мертвий. Розкажіть лордові Варанджиту, що було в платіжній книзі."],
  "The Land Before Stone: Meghavan's quests and the Great Stepwell": ["石以前の地:メガヴァンのクエストと大階段井戸", "돌 이전의 땅: 메가반의 퀘스트와 대계단우물", "石前之地:梅加万的任务与大阶梯井", "石前之地:梅加萬的任務與大階梯井", "Vùng Đất Trước Đá: các nhiệm vụ của Meghavan và Giếng Bậc Lớn", "Tanah Sebelum Batu: misi-misi Meghavan dan Sumur Tangga Agung", "ดินแดนก่อนศิลา: ภารกิจแห่งเมฆาวันและบ่อขั้นบันไดใหญ่", "Taştan Önceki Diyar: Meghavan'ın görevleri ve Büyük Basamaklı Kuyu", "La Tierra antes de la Piedra: las misiones de Meghavan y el Gran Pozo Escalonado", "A Terra antes da Pedra: as missões de Meghavan e o Grande Poço de Degraus", "Земля до камня: задания Мегхавана и Великий ступенчатый колодец", "Земля до каменю: завдання в Мегхавані та Великий східчастий колодязь"],
  "Six new quests in the Rain Country. Caravan of the Rains: see a Khetmar caravan over the Gate of Rains, past the dacoits, to the ford at Tirthali, where one crate holds something that was dug up.": ["雨の国に新しいクエストが六つ。「雨の隊商」:ケトマルのキャラバンを連れて雨の門を越え、ダコイトをかわし、ティルタリの渡し場まで送り届けよう。積み荷の木箱のひとつには、掘り出された何かが入っている。", "비의 나라에 새 퀘스트 여섯 개. '비의 대상': 케트마르 대상을 이끌고 비의 문을 넘어 노상강도들을 지나 티르탈리 나루까지 데려가자. 그곳에 있는 상자 하나에는 땅에서 파낸 무언가가 들어 있다.", "雨之国新增六个任务。《雨季商队》:护送一支克特马尔商队翻越雨之门,避开劫匪,抵达提尔塔利的渡口——那里有一只箱子里装着某样挖出来的东西。", "雨之國新增六個任務。「雨季商隊」:護送一支克特馬爾商隊翻越雨之門,避開劫匪,抵達提爾塔利的渡口——那裡有一只箱子裡裝著某樣挖出來的東西。", "Sáu nhiệm vụ mới ở Xứ Mưa. Đoàn Lữ Hành Mùa Mưa: hộ tống một đoàn lữ hành Khetmar vượt Cổng Mưa, qua mặt bọn cướp đường, tới bến lội ở Tirthali, nơi một thùng hàng chứa thứ gì đó đã được đào lên.", "Enam misi baru di Negeri Hujan. Kafilah Hujan: kawal sebuah kafilah Khetmar melintasi Gerbang Hujan, melewati para begal, sampai ke penyeberangan di Tirthali, tempat satu peti berisi sesuatu yang digali dari tanah.", "ภารกิจใหม่หกภารกิจในแดนฝน กองคาราวานแห่งสายฝน: คุ้มกันกองคาราวานจากเคทมาร์ข้ามประตูแห่งสายฝน ผ่านพวกโจรปล้นทาง ไปจนถึงท่าข้ามที่ตีรถลี ที่ซึ่งลังใบหนึ่งบรรจุบางสิ่งที่ถูกขุดขึ้นมา", "Yağmur Ülkesi'nde altı yeni görev. Yağmurların Kervanı: bir Khetmar kervanını Yağmur Kapısı'ndan geçirip haydutları atlatarak Tirthali'deki geçide ulaştır; orada sandıklardan biri topraktan kazılıp çıkarılmış bir şey taşıyor.", "Seis misiones nuevas en el País de la Lluvia. La caravana de las lluvias: acompaña a una caravana de Khetmar a través de la Puerta de las Lluvias, más allá de los bandoleros, hasta el vado de Tirthali, donde una caja guarda algo que fue desenterrado.", "Seis novas missões no País da Chuva. A Caravana das Chuvas: escolte uma caravana de Khetmar pelo Portão das Chuvas, passando pelos bandoleiros, até o vau de Tirthali, onde um caixote guarda algo que foi desenterrado.", "Шесть новых заданий в Стране дождей. «Караван дождей»: проведите караван из Кетмара через Врата Дождей мимо дакойтов к броду у Тиртхали, где в одном из ящиков лежит что-то выкопанное из земли.", "Шість нових завдань у Країні дощів. «Караван дощів»: проведіть караван із Кетмара через Браму Дощів повз дакойтів до броду біля Тіртхалі, де в одній зі скринь лежить щось викопане із землі."],
  "The Silted Tank: Queen Saumitra's engineers and the temple's treasurers each want the other to pay for the silt. Read the Great Tank's measure, and go down the Great Stepwell under Sarovan, where the old sluice is jammed and the Monsoon Serpent keeps the cistern.": ["「沈泥の貯水池」:サウミトラ女王の技師たちと寺院の会計役たちは、沈泥の費用を互いに相手に払わせようとしている。大貯水池の水位標を読み、サロヴァンの地下にある大階段井戸を下りよう。古い水門は詰まり、雨季の大蛇が貯水槽を守っている。", "'토사에 묻힌 저수지': 사우미트라 여왕의 기술자들과 사원의 재무관들은 저마다 토사 비용을 상대에게 떠넘기려 한다. 대저수지의 수위표를 읽고, 사로반 아래의 대계단우물로 내려가자. 그곳에는 낡은 수문이 막혀 있고, 몬순의 큰뱀이 저수조를 지키고 있다.", "《淤塞的水池》:萨乌米特拉女王的工程师们和神庙的司库们都想让对方为清淤买单。读取大水池的水尺,再深入萨罗万地下的大阶梯井——那里的旧水闸已被堵死,季风之蛇盘踞着蓄水窖。", "「淤塞的水池」:薩烏米特拉女王的工程師們和神廟的司庫們都想讓對方為清淤買單。讀取大水池的水尺,再深入薩羅萬地下的大階梯井——那裡的舊水閘已被堵死,季風之蛇盤踞著蓄水窖。", "Hồ Chứa Bồi Lắng: các kỹ sư của Nữ hoàng Saumitra và các thủ quỹ của đền thờ, bên nào cũng muốn bên kia trả tiền nạo phù sa. Hãy đọc thước đo của Hồ Lớn, rồi đi xuống Giếng Bậc Lớn bên dưới Sarovan, nơi cửa cống cũ bị kẹt và Mãng Xà Gió Mùa canh giữ bể chứa.", "Telaga yang Mendangkal: para insinyur Ratu Saumitra dan para bendahara kuil sama-sama ingin pihak lain yang membayar lumpurnya. Baca pengukur Telaga Agung, lalu turunlah ke Sumur Tangga Agung di bawah Sarovan, tempat pintu air tua macet dan Ular Monsun menjaga bak penampungan.", "สระที่ตื้นเขิน: บรรดาวิศวกรของราชินีเสามิตราและเหรัญญิกของวัดต่างอยากให้อีกฝ่ายเป็นคนจ่ายค่าตะกอน อ่านเครื่องวัดระดับน้ำของสระใหญ่ แล้วลงไปในบ่อขั้นบันไดใหญ่ใต้สโรวัน ที่ซึ่งประตูระบายน้ำเก่าติดขัด และอสรพิษมรสุมเฝ้าบ่อเก็บน้ำอยู่", "Siltle Dolan Havuz: Kraliçe Saumitra'nın mühendisleri de tapınağın haznedarları da siltin parasını karşı tarafın ödemesini istiyor. Büyük Havuz'un ölçeğini oku ve Sarovan'ın altındaki Büyük Basamaklı Kuyu'ya in; orada eski savak tıkanmış, Muson Yılanı da sarnıcı bekliyor.", "El estanque encenagado: los ingenieros de la reina Saumitra y los tesoreros del templo quieren, cada uno, que el otro pague por el limo. Lee la medida del Gran Estanque y baja al Gran Pozo Escalonado bajo Sarovan, donde la vieja compuerta está atascada y la Serpiente del Monzón guarda el aljibe.", "O Tanque Assoreado: os engenheiros da rainha Saumitra e os tesoureiros do templo querem, cada um, que o outro pague pelo lodo. Leia a medida do Grande Tanque e desça ao Grande Poço de Degraus sob Sarovan, onde a velha comporta está emperrada e a Serpente da Monção guarda a cisterna.", "«Заиленный пруд»: инженеры королевы Саумитры и казначеи храма хотят, чтобы за ил заплатила другая сторона. Снимите показания с мерила Великого пруда и спуститесь в Великий ступенчатый колодец под Сарованом, где заклинило старый шлюз, а цистерну стережёт Муссонный Змей.", "«Замулений став»: інженери королеви Саумітри й скарбники храму хочуть, щоб за мул заплатила інша сторона. Зніміть покази з мірила Великого ставу й спустіться у Великий східчастий колодязь під Сарованом, де заклинило старий шлюз, а цистерну стереже Мусонний Змій."],
  "Seven Parasols, One Shade: the League's toll books say Ilavarta's bridge has doubled its toll. The Pass Toll: Copper Banner deserters hold Shailagarh's high toll-house. The Missing Folio: a leaf of the Azhurak star chart is gone from the Archive. What the Forest Keeps: Shailagarh's loggers have moved the Kanthari's grove stones.": ["「七つの日傘、一つの日陰」:同盟の通行税帳簿によれば、イラヴァルタの橋の通行税が倍になったという。「峠の通行税」:銅の旗の脱走兵たちがシャイラガルの高地の通行税所を占拠している。「失われた一葉」:アズラクの星図の一葉が文書館から消えた。「森が守るもの」:シャイラガルの木こりたちが、カンタリの聖林の石を動かしてしまった。", "'일곱 일산, 하나의 그늘': 동맹의 통행세 장부에 따르면 일라바르타의 다리 통행세가 두 배로 올랐다. '고개 통행세': 구리 깃발 탈영병들이 샤일라가르의 높은 통행세 초소를 차지하고 있다. '사라진 낱장': 서고에서 아주라크 성도의 한 장이 사라졌다. '숲이 지키는 것': 샤일라가르의 벌목꾼들이 칸타리족의 성림 돌들을 옮겨 버렸다.", "《七华盖,一片荫》:同盟的收费账簿显示,伊拉瓦塔的桥把通行费翻了一倍。《山口通行税》:铜旗的逃兵占据了沙伊拉加尔高处的收费站。《遗失的书页》:阿祖拉克星图的一页从档案馆中不翼而飞。《森林所守》:沙伊拉加尔的伐木工挪动了坎塔里人的圣林石。", "「七華蓋,一片蔭」:同盟的收費帳簿顯示,伊拉瓦塔的橋把通行費翻了一倍。「山口通行稅」:銅旗的逃兵占據了沙伊拉加爾高處的收費站。「遺失的書頁」:阿祖拉克星圖的一頁從檔案館中不翼而飛。「森林所守」:沙伊拉加爾的伐木工挪動了坎塔里人的聖林石。", "Bảy Lọng, Một Bóng Râm: sổ thu phí của Liên minh cho thấy cây cầu của Ilavarta đã tăng phí gấp đôi. Phí Qua Đèo: lính đào ngũ Cờ Đồng chiếm giữ trạm thu phí trên cao của Shailagarh. Tờ Sách Bị Mất: một tờ của tấm bản đồ sao Azhurak đã biến mất khỏi Văn khố. Điều Rừng Gìn Giữ: tiều phu của Shailagarh đã dời những hòn đá trong khu rừng thiêng của người Kanthari.", "Tujuh Payung, Satu Teduh: buku bea Liga menunjukkan jembatan Ilavarta telah menaikkan beanya dua kali lipat. Bea Celah Gunung: desertir Panji Tembaga menduduki pos bea tinggi Shailagarh. Lembaran yang Hilang: selembar peta bintang Azhurak lenyap dari Arsip. Apa yang Dijaga Hutan: para penebang kayu Shailagarh telah memindahkan batu-batu hutan keramat orang Kanthari.", "เจ็ดฉัตร หนึ่งร่มเงา: สมุดบัญชีค่าผ่านทางของสันนิบาตระบุว่าสะพานของอิลาวรรตะขึ้นค่าผ่านเป็นสองเท่า ค่าผ่านด่านช่องเขา: ทหารหนีทัพธงทองแดงยึดด่านเก็บค่าผ่านทางบนที่สูงของไศลครห์ไว้ แผ่นต้นฉบับที่หายไป: แผ่นหนึ่งของแผนที่ดาวอาซูรักหายไปจากหอจดหมายเหตุ สิ่งที่ป่าเฝ้ารักษา: คนตัดไม้ของไศลครห์ย้ายหินในป่าศักดิ์สิทธิ์ของชาวกันถารี", "Yedi Şemsiye, Tek Gölge: Birlik'in geçiş ücreti defterlerine göre Ilavarta'nın köprüsü ücretini ikiye katlamış. Geçit Ücreti: Bakır Sancak firarileri Shailagarh'ın yüksekteki geçiş ücreti evini tutuyor. Kayıp Yaprak: Azhurak yıldız haritasının bir yaprağı Arşiv'den kaybolmuş. Ormanın Sakladıkları: Shailagarh'ın oduncuları Kanthariler'in koru taşlarını yerinden oynatmış.", "Siete parasoles, una sombra: los libros de peajes de la Liga dicen que el puente de Ilavarta ha duplicado su peaje. El peaje del paso: desertores del Estandarte de Cobre ocupan la casa de peaje alta de Shailagarh. El folio perdido: ha desaparecido del Archivo una hoja de la carta estelar de Azhurak. Lo que guarda el bosque: los leñadores de Shailagarh han movido las piedras de la arboleda de los kanthari.", "Sete Para-sóis, Uma Sombra: os livros de pedágio da Liga dizem que a ponte de Ilavarta dobrou o pedágio. O Pedágio do Passo: desertores do Estandarte de Cobre ocupam a casa de pedágio alta de Shailagarh. O Fólio Perdido: uma folha da carta estelar de Azhurak sumiu do Arquivo. O Que a Floresta Guarda: os lenhadores de Shailagarh mudaram de lugar as pedras do bosque dos kanthari.", "«Семь зонтов, одна тень»: по пошлинным книгам Лиги выходит, что мост Илаварты удвоил пошлину. «Пошлина перевала»: дезертиры Медного знамени засели в высокогорном пошлинном доме Шайлагарха. «Пропавший лист»: из Архива исчез лист азуракской звёздной карты. «Что хранит лес»: лесорубы Шайлагарха сдвинули камни священной рощи кантхари.", "«Сім парасолів, одна тінь»: за митними книгами Ліги виходить, що міст Ілаварти подвоїв мито. «Мито перевалу»: дезертири Мідного стягу засіли у високогірній митниці Шайлагарха. «Зниклий аркуш»: з Архіву зник аркуш азуракської зоряної мапи. «Що береже ліс»: лісоруби Шайлагарха зсунули камені священного гаю кантхарі."],
  "The Great Stepwell: its landings, a gallery of carved pillars, a flooded gallery, the sluice chamber and the cistern, with silt crawlers, monsoon leeches, coffers, and the Monsoon Serpent's hoard.": ["大階段井戸:踊り場、彫刻の柱が並ぶ回廊、水没した回廊、水門の間、そして貯水槽。沈泥這い、モンスーンヒル、宝箱、そして雨季の大蛇の財宝が待っている。", "대계단우물: 층계참, 조각 기둥이 늘어선 회랑, 물에 잠긴 회랑, 수문실, 그리고 저수조. 토사 포복충, 몬순 거머리, 보물 상자, 그리고 몬순의 큰뱀이 모아 둔 보물.", "大阶梯井:层层平台、雕花石柱回廊、被水淹没的回廊、水闸室和蓄水窖,还有淤泥爬虫、季风水蛭、宝箱,以及季风之蛇的宝藏。", "大階梯井:層層平台、雕花石柱迴廊、被水淹沒的迴廊、水閘室和蓄水窖,還有淤泥爬蟲、季風水蛭、寶箱,以及季風之蛇的寶藏。", "Giếng Bậc Lớn: các chiếu nghỉ, một hành lang cột chạm khắc, một hành lang ngập nước, phòng cửa cống và bể chứa, cùng sâu bò phù sa, đỉa gió mùa, rương báu và kho báu của Mãng Xà Gió Mùa.", "Sumur Tangga Agung: bordes-bordesnya, serambi pilar berukir, serambi yang terendam, ruang pintu air, dan bak penampungan, dengan perayap lumpur, lintah monsun, peti harta, dan timbunan harta Ular Monsun.", "บ่อขั้นบันไดใหญ่: ชานพักบันได ระเบียงเสาแกะสลัก ระเบียงที่น้ำท่วม ห้องประตูระบายน้ำ และบ่อเก็บน้ำ พร้อมตัวคลานตะกอน ปลิงมรสุม หีบสมบัติ และกองสมบัติของอสรพิษมรสุม", "Büyük Basamaklı Kuyu: sahanlıkları, oymalı sütunlu bir galeri, su basmış bir galeri, savak odası ve sarnıç; silt sürüngenleri, muson sülükleri, sandıklar ve Muson Yılanı'nın hazinesiyle.", "El Gran Pozo Escalonado: sus rellanos, una galería de pilares tallados, una galería inundada, la cámara de la compuerta y el aljibe, con reptadores del limo, sanguijuelas del monzón, cofres y el tesoro de la Serpiente del Monzón.", "O Grande Poço de Degraus: seus patamares, uma galeria de pilares entalhados, uma galeria inundada, a câmara da comporta e a cisterna, com rastejantes do lodo, sanguessugas da monção, baús e o tesouro da Serpente da Monção.", "Великий ступенчатый колодец: его площадки, галерея резных колонн, затопленная галерея, шлюзовая камера и цистерна, а в них иловые ползуны, муссонные пиявки, сундуки и сокровища Муссонного Змея.", "Великий східчастий колодязь: його майданчики, галерея різьблених колон, затоплена галерея, шлюзова камера й цистерна, а в них мулові повзуни, мусонні п'явки, скрині та скарби Мусонного Змія."],
  "New rewards: the monsoon cloak, the Ring of the Kept Tank, the Speaker's parasol, the pass-warden's helm, a reader's stole and a Kanthari seed charm.": ["新しい報酬:モンスーンの外套、守られし貯水池の指輪、議長の日傘、峠守りの兜、読み手の肩掛け、そしてカンタリの種の護符。", "새 보상: 몬순 망토, 지켜진 저수지의 반지, 의장의 일산, 고개지기의 투구, 독서가의 숄, 그리고 칸타리 씨앗 부적.", "新奖励:季风斗篷、守池之戒、议长华盖、关隘守卫头盔、读书人披带,以及坎塔里种子护符。", "新獎勵:季風斗篷、守池之戒、議長華蓋、關隘守衛頭盔、讀書人披帶,以及坎塔里種子護符。", "Phần thưởng mới: áo choàng gió mùa, Nhẫn Hồ Được Giữ, lọng của Phát ngôn nhân, mũ trụ của người gác đèo, khăn choàng người đọc và bùa hạt giống Kanthari.", "Hadiah baru: jubah monsun, Cincin Telaga Terjaga, payung Juru Bicara, helm penjaga celah, selendang pembaca, dan jimat biji Kanthari.", "รางวัลใหม่: เสื้อคลุมมรสุม แหวนแห่งสระที่ได้รับการรักษา ฉัตรของประธาน หมวกเกราะผู้คุมช่องเขา ผ้าคล้องนักอ่าน และเครื่องรางเมล็ดพันธุ์กันถารี", "Yeni ödüller: muson pelerini, Korunan Havuz Yüzüğü, Sözcü'nün şemsiyesi, geçit bekçisinin miğferi, bir okur şalı ve bir Kanthari tohum muskası.", "Nuevas recompensas: la capa del monzón, el Anillo del Estanque Guardado, el parasol del Portavoz, el yelmo del guardián del paso, una estola de lector y un amuleto de semillas kanthari.", "Novas recompensas: a capa da monção, o Anel do Tanque Guardado, o para-sol do Porta-voz, o elmo do guardião do passo, uma estola de leitor e um amuleto de sementes kanthari.", "Новые награды: муссонный плащ, Кольцо Хранимого пруда, зонт Глашатая, шлем стража перевала, палантин чтеца и кантхарийский оберег из семян.", "Нові нагороди: мусонний плащ, Перстень Береженого ставу, парасоль Речника, шолом вартового перевалу, палантин читця й кантхарійський оберіг із насіння."],
  "Still to come in Meghavan: the four eastern schools of the Mysteries and their techniques.": ["メガヴァン、今後の予定:東方の四つの神秘の学派と、その技。", "메가반에서 앞으로 올 것: 동방의 네 신비 학파와 그 기술.", "梅加万后续内容:东方的四大奥秘学派及其技法。", "梅加萬後續內容:東方的四大奧秘學派及其技法。", "Còn sắp tới ở Meghavan: bốn trường phái Huyền bí phương đông và các kỹ thuật của họ.", "Masih akan datang di Meghavan: empat aliran Misteri dari timur dan teknik-tekniknya.", "ที่จะตามมาในเมฆาวัน: สี่สำนักความลึกลับแห่งตะวันออกและเทคนิคของแต่ละสำนัก", "Meghavan'da sırada: doğunun dört Gizemler okulu ve teknikleri.", "Aún por llegar en Meghavan: las cuatro escuelas orientales de los Misterios y sus técnicas.", "Ainda por vir em Meghavan: as quatro escolas orientais dos Mistérios e suas técnicas.", "Ещё впереди в Мегхаване: четыре восточные школы Тайн и их приёмы.", "Ще попереду в Мегхавані: чотири східні школи Таємниць та їхні прийоми."],
};
